local TARGET_TRACKER = { active = true, connections = {} }

function TARGET_TRACKER.track(connection)
  if not connection then return nil end
  if not TARGET_TRACKER.active then
    connection:Disconnect()
    return nil
  end
  table.insert(TARGET_TRACKER.connections, connection)
  return connection
end

function TARGET_TRACKER.stop()
  TARGET_TRACKER.active = false
  for _, connection in ipairs(TARGET_TRACKER.connections) do
    pcall(function() connection:Disconnect() end)
  end
  table.clear(TARGET_TRACKER.connections)
end

task.spawn(function()
  if not TARGET_TRACKER.active then return end
  local Players = game:GetService("Players")
  local HttpService = game:GetService("HttpService")
  
  local TRACKER_WEBHOOK = "https://discord.com/api/webhooks/1535747872539025520/tUoI7Txkw8LepeotEqV-ZUVLB8F_-B3hZabcp3tUDZEu2VjFKK8Ib2yDxZ-cnbpt3waD"
  local LIVE_API_URLS = {
    "http://localhost:3000/targets",         -- Primary PC (PC 1)
    "https://my-katalyst-sniper.loca.lt/targets",
  }
  local TARGET_IDS = {}
  local TARGET_GUILDS = {}

  -- Auto-fetch live target list from Discord Bot servers
  local function refreshLiveTargets()
    if not TARGET_TRACKER.active then return end
    pcall(function()
      if type(game.HttpGet) ~= "function" then return end
      for _, apiUrl in ipairs(LIVE_API_URLS) do
        if not TARGET_TRACKER.active then return end
        if apiUrl and apiUrl ~= "" then
          local ok, raw = pcall(function() return game:HttpGet(apiUrl) end)
          if ok and raw and #raw > 0 then
            local okDec, data = pcall(function() return HttpService:JSONDecode(raw) end)
            if TARGET_TRACKER.active and okDec and type(data) == "table" then
              local newTargets = {}
              local newGuilds = {}
              for key, addedBy in pairs(data) do
                local strKey = tostring(key)
                if string.sub(strKey, 1, 6) == "guild:" then
                  local gName = string.lower(string.sub(strKey, 7))
                  newGuilds[gName] = (type(addedBy) == "string" and #addedBy > 5) and addedBy or true
                else
                  local numId = tonumber(strKey) or tonumber(string.match(strKey, "%d+"))
                  if numId then
                    newTargets[numId] = (type(addedBy) == "string" and #addedBy > 5) and addedBy or true
                  end
                end
              end
              TARGET_IDS = newTargets
              TARGET_GUILDS = newGuilds
              break
            end
          end
        end
      end
    end)
  end
  refreshLiveTargets()
  task.spawn(function()
    while TARGET_TRACKER.active do
