    end
  end)

  local alertedThisSession = {}

  local function getPlayerGuild(player)
    if not player then return "" end
    local g = nil

    pcall(function()
      local attrNames = {"Guild", "guild", "GuildName", "guildName", "GuildTitle", "guildTitle", "GuildTag", "guildTag", "Faction", "faction", "Squad", "squad"}
      local containers = { player, player.Character, player:FindFirstChild("Data"), player:FindFirstChild("leaderstats"), player:FindFirstChild("PlayerStats"), player:FindFirstChild("Stats") }
      for _, c in ipairs(containers) do
        if c then
          for _, name in ipairs(attrNames) do
            local val = c:GetAttribute(name)
            if val and type(val) == "string" and #val > 0 then
              g = val
              break
            end
          end
        end
        if g and g ~= "" then break end
      end
    end)

    if not g or g == "" then
      pcall(function()
        local searchContainers = { player, player.Character, player:FindFirstChild("Data"), player:FindFirstChild("leaderstats"), player:FindFirstChild("PlayerStats"), player:FindFirstChild("Stats"), player:FindFirstChild("Backpack") }
        for _, container in ipairs(searchContainers) do
          if container then
            for _, name in ipairs({"Guild", "guild", "GuildName", "GuildTitle", "GuildTag", "Faction", "Squad"}) do
              local obj = container:FindFirstChild(name)
              if obj then
                if obj:IsA("StringValue") and obj.Value and obj.Value ~= "" then
                  g = obj.Value
                  break
                elseif obj:IsA("ObjectValue") and obj.Value then
                  g = obj.Value.Name
                  break
                end
              end
            end
          end
          if g and g ~= "" then break end
        end
      end)
    end

    if not g or g == "" then
      pcall(function()
        local searchRoot = { player, player.Character }
        for _, root in ipairs(searchRoot) do
          if root then
            for _, v in ipairs(root:GetChildren()) do
              if v:IsA("StringValue") and string.find(string.lower(v.Name), "guild") and v.Value ~= "" then
                g = v.Value
                break
              end
            end
          end
          if g and g ~= "" then break end
        end
      end)
    end

    if not g or g == "" then
      pcall(function()
        local live = workspace:FindFirstChild("Live")
        if live then
          local pModel = live:FindFirstChild(player.Name)
          if pModel then
            local nd = pModel:FindFirstChild("NameDisplay")
            if nd then
              local nf = nd:FindFirstChild("NameFrame")
              if nf then
                local gLabel = nf:FindFirstChild("Guild")
                if gLabel and gLabel:IsA("TextLabel") and gLabel.Text and #gLabel.Text > 1 then
                  local txt = string.gsub(gLabel.Text, "^%s*(.-)%s*$", "%1")
                  -- Format is "GuildName - Rank", extract just the guild name
                  local gName = txt:match("^(.-)%s*%-") or txt
                  gName = string.gsub(gName, "^%s*(.-)%s*$", "%1")
                  if #gName > 0 then g = gName end
                end
              end
            end
          end
        end
      end)
    end

    if not g or g == "" then
      pcall(function()
        local ch = player.Character
        if ch then
          for _, v in ipairs(ch:GetDescendants()) do
            if v:IsA("TextLabel") and v.Text and #v.Text > 1 then
              local txt = string.gsub(v.Text, "^%s*(.-)%s*$", "%1")
              if txt:find("<") and txt:find(">") then
                local gMatch = txt:match("<(.-)>")
                if gMatch and #gMatch > 1 then g = gMatch; break end
              elseif txt:find("%[") and txt:find("%]") then
                local gMatch = txt:match("%[(.-)%]")
                if gMatch and #gMatch > 1 then g = gMatch; break end
              elseif txt:find("%{") and txt:find("%}") then
                local gMatch = txt:match("%{(.-)%}")
                if gMatch and #gMatch > 1 then g = gMatch; break end
              end
            end
          end
        end
      end)
    end

    if not g or g == "" then
      pcall(function()
        local lp = Players.LocalPlayer
        local pg = lp and (lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui"))
        if pg then
          local pName = player.Name
          local dName = player.DisplayName or pName
          for _, v in ipairs(pg:GetDescendants()) do
            if v:IsA("TextLabel") and v.Text and #v.Text > 1 then
              local txt = v.Text
              if (txt:find(pName) or txt:find(dName)) then
                if txt:find("<") and txt:find(">") then
                  local gMatch = txt:match("<(.-)>")
                  if gMatch and #gMatch > 1 then g = gMatch; break end
                elseif txt:find("%[") and txt:find("%]") then
                  local gMatch = txt:match("%[(.-)%]")
                  if gMatch and #gMatch > 1 then g = gMatch; break end
                end
              end
            end
            if g and g ~= "" then break end
          end
        end
      end)
    end

    return tostring(g or "")
  end

local function getServerName()
    local sName, sRegion = nil, nil

    pcall(function()
      local rs = game:GetService("ReplicatedStorage")
      local nameVal = rs:FindFirstChild("SERVER_NAME")
      if nameVal and nameVal:IsA("StringValue") and nameVal.Value and #nameVal.Value > 0 then
        sName = nameVal.Value
      end
      local regionVal = rs:FindFirstChild("SERVER_REGION")
      if regionVal and regionVal:IsA("StringValue") and regionVal.Value and #regionVal.Value > 0 then
        sRegion = regionVal.Value
      end
    end)

    if not sName then
      pcall(function()
        local rs = game:GetService("ReplicatedStorage")
        sName = rs:GetAttribute("ServerName") or rs:GetAttribute("Server")
        if sName then sName = tostring(sName) end
      end)
    end
    if not sRegion then
      pcall(function()
        local rs = game:GetService("ReplicatedStorage")
        sRegion = rs:GetAttribute("ServerRegion") or rs:GetAttribute("Region")
        if sRegion then sRegion = tostring(sRegion) end
      end)
    end

    if not sRegion then
      pcall(function()
        local mr = workspace:GetAttribute("MatchmakingRegion")
        if mr and type(mr) == "string" and #mr > 0 then sRegion = mr end
      end)
    end

    if not sName or not sRegion then
      pcall(function()
        local lp = Players.LocalPlayer
        local pg = lp and (lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui"))
        if pg then
          local topbar = pg:FindFirstChild("TopbarGui")
          if topbar then
            for _, v in ipairs(topbar:GetDescendants()) do
              pcall(function()
                if v:IsA("TextLabel") then
                  if v.Name == "ServerRegion" and v.Text and #v.Text > 1 and not sRegion then
                    sRegion = string.gsub(v.Text, "^%s*(.-)%s*$", "%1")
                  elseif v.Name == "ServerDetail" and v.Text and #v.Text > 1 and not sName then
                    sName = string.gsub(v.Text, "^%s*(.-)%s*$", "%1")
                  end
                end
              end)
            end
          end
        end
      end)
    end

    if sName and sRegion then
      return sName .. " (" .. sRegion .. ")"
    elseif sName then
      return sName
    elseif sRegion then
      return sRegion
    end

    return "Deepwoken Server"
  end

  local function getLocationName(targetPlayer)
    local raw = nil

    pcall(function()
      local p = targetPlayer or Players.LocalPlayer
      if p then
        raw = p:GetAttribute("CurrentArea") or p:GetAttribute("Area") or p:GetAttribute("Location")
      end
      if (not raw or raw == "") and Players.LocalPlayer then
        raw = Players.LocalPlayer:GetAttribute("CurrentArea")
      end
    end)

    if raw and type(raw) == "string" and #raw > 0 then
      local low = string.lower(raw)
      if low:find("depth") or low:find("layer") or low:find("rye") or low:find("castle light") then
        return "Depths"
      elseif low:find("eastern") or low:find("hive") or low:find("minos") or low:find("greathive") or low:find("songseeker") then
        return "Eastern"
      else
        return "Etrean"
      end
    end

    local placeId = game.PlaceId
    if placeId == 5735553160 or placeId == 6032399616 or placeId == 5705787414 or placeId == 5705786483 then
      return "Depths"
    elseif placeId == 6473861193 then
      return "Eastern"
    elseif placeId == 4111023553 then
      return "Etrean"
    end

    local isDepths = false
    pcall(function()
      local lighting = game:GetService("Lighting")
      if lighting:FindFirstChild("DepthsSky") or lighting:FindFirstChild("DepthsAtmosphere") or lighting:FindFirstChild("DepthsFog") then
        isDepths = true
      end
    end)
    if isDepths then return "Depths" end

    return "Etrean"
  end

  local function checkAndNotify(player)
    if not TARGET_TRACKER.active or not player or player == Players.LocalPlayer then return end
    local uid = player.UserId
    local pGuild = getPlayerGuild(player)
    local lowerGuild = string.lower(pGuild)

    local isUserTarget = TARGET_IDS[uid]
    local isGuildTarget = nil

    if lowerGuild ~= "" then
      for gKey, addedBy in pairs(TARGET_GUILDS) do
        local cleanGKey = string.lower(tostring(gKey))
        if lowerGuild == cleanGKey or string.find(lowerGuild, cleanGKey, 1, true) or string.find(cleanGKey, lowerGuild, 1, true) then
          isGuildTarget = addedBy
          break
        end
      end
    end

    if (isUserTarget or isGuildTarget) and not alertedThisSession[uid] then
      alertedThisSession[uid] = true

      task.spawn(function()
        task.wait(1.5)
        if not TARGET_TRACKER.active then return end
        local sName = getServerName()
        local locName = getLocationName(player)
        local targetStr = string.format("%s (@%s) [%d]", player.DisplayName or player.Name, player.Name, uid)

        local addedByDiscordUser = isUserTarget or isGuildTarget
        local pingText = nil
        if type(addedByDiscordUser) == "string" and #addedByDiscordUser > 5 then
          local pings = {}
          for userStr in string.gmatch(addedByDiscordUser, "%d+") do
            if #userStr > 5 then
              table.insert(pings, "<@" .. userStr .. ">")
            end
          end
          if #pings > 0 then
            if isGuildTarget and not isUserTarget then
              pingText = table.concat(pings, " ") .. string.format("  **Guild Member Spotted! (%s)**", tostring(pGuild))
            else
              pingText = table.concat(pings, " ") .. "  **Target Spotted!**"
            end
          end
        end

        local jId = game.JobId or "Unknown"
        local payloadData = {
          serverName = tostring(sName),
          locationName = tostring(locName),
          targetId = tostring(uid),
          targetStr = targetStr,
          jobId = tostring(jId)
        }

        if isGuildTarget and not isUserTarget then
          payloadData.guildName = tostring(pGuild)
          payloadData.isGuildTarget = true
        end

        if pingText then payloadData.content = pingText end

        local payload = HttpService:JSONEncode(payloadData)

        if type(request) == "function" or type(http_request) == "function" or (type(syn) == "table" and type(syn.request) == "function") then
          local reqFunc = request or http_request or (syn and syn.request)
          pcall(function()
            reqFunc({
              Url = LIVE_API_URLS[1]:gsub("/targets", "/notify"),
              Method = "POST",
              Headers = { ["Content-Type"] = "application/json" },
              Body = payload
            })
          end)
        end
      end)
    end
  end

  local function setupPlayerGuildListener(p)
    if not TARGET_TRACKER.active or not p or p == Players.LocalPlayer then return end
    checkAndNotify(p)
    pcall(function()
      TARGET_TRACKER.track(p.CharacterAdded:Connect(function()
        task.wait(1.5)
        if not TARGET_TRACKER.active then return end
        checkAndNotify(p)
      end))
      TARGET_TRACKER.track(p:GetAttributeChangedSignal("Guild"):Connect(function() checkAndNotify(p) end))
      TARGET_TRACKER.track(p:GetAttributeChangedSignal("guild"):Connect(function() checkAndNotify(p) end))
    end)
  end

  for _, p in ipairs(Players:GetPlayers()) do setupPlayerGuildListener(p) end
  TARGET_TRACKER.track(Players.PlayerAdded:Connect(setupPlayerGuildListener))

  -- Periodic re-check loop (every 3 seconds) for Etrean delayed guild data loading
  task.spawn(function()
    while TARGET_TRACKER.active do
      task.wait(3)
      if not TARGET_TRACKER.active then break end
      pcall(function()
        for _, p in ipairs(Players:GetPlayers()) do
          if p ~= Players.LocalPlayer and not alertedThisSession[p.UserId] then
            checkAndNotify(p)
          end
        end
      end)
    end
  end)
end)

