  function G.parseMantraStudDelays(str)
    CFG.MantraStudDelays = CFG.MantraStudDelays or {}
    table.clear(CFG.MantraStudDelays)
    if not str or #str == 0 then return end
    for item in string.gmatch(str, "[^,]+") do
      local id, val = string.match(item, "([%d]+)%s*:%s*([%d%.%-]+)")
      if id and val then
        local nVal = tonumber(val)
        if nVal then
          CFG.MantraStudDelays[id] = nVal
          CFG.MantraStudDelays["rbxassetid://"..id] = nVal
        end
      end
    end
  end
  
  local function buildConfigDocument(forExport)
    local document = {
      keybinds = {},
      toggles = {},
      cfg = {},
      learnedTimings = LEARNED_TIMINGS or {},
      mantraStudDelays = MANTRA_STUD_DELAYS or {},
    }
    if forExport then document.version = "4.0" end

    for field, keyCode in pairs(kb) do
      local keyName = keyCode and keyCode.Name
      if keyName then
        document.keybinds[field] = keyName
        document[field] = keyName
      elseif keyCode == false then
        document.keybinds[field] = false
        document[field] = false
      end
    end

    for field, value in pairs(S) do
      if field ~= "menu" and field ~= "fly" and type(value) == "boolean" then
        document.toggles[field] = value
      end
    end

    for field, value in pairs(CFG) do
      local valueType = type(value)
      if valueType == "number" or valueType == "string" or valueType == "boolean" or valueType == "table" then
        document.cfg[field] = value
        if forExport then document[field] = value end
      end
    end

    document.sliders = document.cfg
    document.macros = {m1 = CFG.M1, m2 = CFG.M2, m3 = CFG.M3}
    if not forExport then
      document.WebhookURL = CFG.WebhookURL
      document.agSpd = S.agSpd
    end
    return document
  end

  local function applyConfigDocument(document, persistLearnedTimings)
    if type(document.toggles) == "table" then
      for field, value in pairs(document.toggles) do
      if field ~= "fly" and type(value) == "boolean" then S[field] = value end
      end
      if document.toggles.apNuker == nil and type(document.toggles.apBreaker) == "boolean" then
        S.apNuker = document.toggles.apBreaker
      end
    end

    local hasNestedKeybinds = type(document.keybinds) == "table"
    local keybindSource = hasNestedKeybinds and document.keybinds or document
    for field, value in pairs(keybindSource) do
      if hasNestedKeybinds and value == false and field ~= "menuKey" then
        kb[field] = false
      elseif type(value) == "string" and value ~= "" and not configContainerFields[field] then
        local valid, keyCode = pcall(function() return Enum.KeyCode[value] end)
        kb[field] = valid and keyCode or nil
      end
    end
    if kb.apNuker == nil and kb.apBreaker ~= nil then kb.apNuker = kb.apBreaker end
    kb.apBreaker = nil
    if kb.menuKey then CFG.MenuKey = kb.menuKey end

    local configSource = type(document.cfg) == "table" and document.cfg
      or type(document.sliders) == "table" and document.sliders
      or {}
    if type(configSource.KeybindModes) ~= "table" and type(document.KeybindModes) ~= "table" then
      CFG.KeybindModes = {}
    end
    for field, value in pairs(configSource) do
      if not retiredConfigFields[field] then CFG[field] = value end
    end

    for field, value in pairs(document) do
      if not configContainerFields[field]
        and not retiredConfigFields[field]
        and (CFG[field] ~= nil or type(value) == "table")
      then
        CFG[field] = value
      end
    end

    if type(document.macros) == "table" then
      if document.macros.m1 then CFG.M1 = document.macros.m1 end
      if document.macros.m2 then CFG.M2 = document.macros.m2 end
      if document.macros.m3 then CFG.M3 = document.macros.m3 end
    end

    if document.MantraStudDelaysStr then
      G.parseMantraStudDelays(document.MantraStudDelaysStr)
    elseif CFG.MantraStudDelaysStr then
      G.parseMantraStudDelays(CFG.MantraStudDelaysStr)
    end

    if type(document.learnedTimings) == "table" then
      for field, value in pairs(document.learnedTimings) do
        TIMINGS[field] = value
        LEARNED_TIMINGS[field] = value
      end
      if persistLearnedTimings then G.saveTimings() end
    end

    if type(document.mantraStudDelays) == "table" then
      for field, value in pairs(document.mantraStudDelays) do
        MANTRA_STUD_DELAYS[field] = value
      end
    end

    AUTO_PARRY.refreshTimings()
  end

  function G.saveConfig()
    if UI.importing or UI.suspendSave or UI.tearingDown or type(writefile) ~= "function" then return end
    pcall(function()
      writefile(CFG.File, G.HS:JSONEncode(buildConfigDocument(false)))
    end)
  end

  function G.loadConfig()
    if type(readfile) ~= "function" or type(isfile) ~= "function" or not isfile(CFG.File) then return end
    pcall(function()
      local document = G.HS:JSONDecode(readfile(CFG.File))
      if type(document) == "table" then applyConfigDocument(document, false) end
    end)
  end

  function G.exportConfig()
    return "KATALYST_CFG_" .. G.HS:JSONEncode(buildConfigDocument(true))
  end

  function G.importConfig(str)
    if type(str) ~= "string" or #str == 0 then return false, "Empty String" end
    str = string.gsub(str, "^%s*(.-)%s*$", "%1")
    if string.sub(str, 1, 13) == "KATALYST_CFG_" then
      str = string.sub(str, 14)
    end

    local decoded, data = pcall(function() return G.HS:JSONDecode(str) end)
    if not decoded or type(data) ~= "table" then return false, "Invalid JSON" end

    local previousToggles = {}
    for key, value in pairs(S) do
      if type(value) == "boolean" then previousToggles[key] = value end
    end

    UI.importing = true
    local applied, applyError = pcall(function()
      applyConfigDocument(data, true)

      if UI.reconcileImportedState then
        UI.reconcileImportedState(previousToggles)
      elseif UI.syncAll then
        UI.syncAll()
      end
      if UI.reconcileConfig then UI.reconcileConfig() end
    end)
    UI.importing = false

    if not applied then
      return false, "Invalid configuration: " .. tostring(applyError)
    end
    G.saveConfig()
    return true, "Success"
  end

  function G.getEditedTimingsLuaCode()
    local count = 0
    local lines = {}
    table.insert(lines, "-- ============================================")
    table.insert(lines, "-- KATALYST EDITED TIMINGS EXPORT")
    table.insert(lines, "-- ============================================")
    table.insert(lines, "TIMINGS = {")
    table.insert(lines, "")
    
    table.insert(lines, "-- [1] ATTACK / MANTRA BASE DELAYS:")
    if LEARNED_TIMINGS then
      for animKey, data in pairs(LEARNED_TIMINGS) do
        count = count + 1
        local keyStr = string.format("[%q]", tostring(animKey))
        if type(data) == "table" then
          local entries = {}
          for _, entry in ipairs(data) do
            local act = entry.action or "Parry"
            local del = entry.delay or 0.25
            local dps = entry.dps or entry.studDelay
            if dps then
              table.insert(entries, string.format("{ action = %q, delay = %.4f, dps = %.4f }", act, del, dps))
            else
              table.insert(entries, string.format("{ action = %q, delay = %.4f }", act, del))
            end
          end
          table.insert(lines, string.format("  %s = { %s },", keyStr, table.concat(entries, ", ")))
        elseif type(data) == "number" then
          table.insert(lines, string.format("  %s = {{ action = \"Parry\", delay = %.4f }},", keyStr, data))
        end
      end
    end
    
    if MANTRA_STUD_DELAYS and next(MANTRA_STUD_DELAYS) then
      table.insert(lines, "")
      table.insert(lines, "}\n\nMANTRA_STUD_DELAYS = {")
      for animKey, dpsVal in pairs(MANTRA_STUD_DELAYS) do
        table.insert(lines, string.format("  [%q] = %.4f,", tostring(animKey), tonumber(dpsVal) or 0.0125))
      end
    end

    table.insert(lines, "")
    table.insert(lines, "}")
    return table.concat(lines, "\n"), count
  end

  function G.copyEditedTimings(btn)
    local code, count = G.getEditedTimingsLuaCode()
    if count == 0 then
      G.noti("Timings", "No edited timings recorded yet to export!", 2)
      if btn then
        btn.Text = "No Timings Recorded Yet"
        task.delay(1.5, function() btn.Text = "Copy Edited Timings (Lua Code)" end)
      end
      return
    end

    if type(setclipboard) == "function" then
      setclipboard(code)
      if btn then
        btn.Text = string.format("COPIED %d TIMINGS (LUA CODE)!", count)
        task.delay(2, function() btn.Text = "Copy Edited Timings (Lua Code)" end)
      end
      G.noti("Timings Exported", string.format("Copied %d edited timings formatted as drop-in Lua code!", count), 3)
    else
      print("\n" .. code .. "\n")
      if btn then
        btn.Text = "PRINTED TO F9 CONSOLE"
        task.delay(2, function() btn.Text = "Copy Edited Timings (Lua Code)" end)
      end
      G.noti("Timings Printed", "Printed Lua code to developer console (F9)!", 3)
    end
  end

  function G.saveTimings()
    if type(writefile)~="function" then return end
    pcall(function() writefile(CFG.TimingsFile, G.HS:JSONEncode(LEARNED_TIMINGS)) end)
  end
  function G.loadTimings()
    if type(readfile)~="function" or type(isfile)~="function" then return end; if not isfile(CFG.TimingsFile) then return end
    pcall(function()
      local loaded = G.HS:JSONDecode(readfile(CFG.TimingsFile))
      if loaded then
        for k,v in pairs(loaded) do 
          TIMINGS[k] = v 
          LEARNED_TIMINGS[k] = v
        end
        AUTO_PARRY.refreshTimings()
      end
    end)
  end
end
