      if ok then return end
    end
    pcall(function() G.SG:SetCore("SendNotification", {Title = t, Text = x, Duration = duration or 4}) end)
  end
  function G.tween(i,inf,p) if not i then return end; G.TS:Create(i,inf,p):Play() end
  function G.mkC(p,r) G.new("UICorner",p).CornerRadius=G.UD(0,r) end
  function G.mkS(p,c,th,tr) local s=G.new("UIStroke",p); s.Color=c; s.Thickness=th or 1; s.Transparency=tr or 0.1 end
  function G.mkG(p,cs,rot) local g=G.new("UIGradient",p); g.Color=cs; g.Rotation=rot or 90 end
  function G.mkL(par,txt,pos,sz,ts2,fnt,ax,col,wrap)
    local l=G.new("TextLabel"); l.BackgroundTransparency=1; l.Font=fnt or Enum.Font.GothamBold
    l.TextSize=ts2 or 14; l.TextColor3=col or P.tx; l.TextXAlignment=ax or Enum.TextXAlignment.Left
    l.Text=txt or ""; l.Parent=par; if pos then l.Position=pos end; if sz then l.Size=sz end
    if wrap then l.TextWrapped=true end; return l end
  function G.makeDraggable(gui)
    if not gui then return end
    local dragging, dragInput, dragStart, startPos = false, nil, nil, nil
    gui.InputBegan:Connect(function(input)
      if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPos = gui.Position
        input.Changed:Connect(function()
          if input.UserInputState == Enum.UserInputState.End then dragging = false end
        end)
      end
    end)
    gui.InputChanged:Connect(function(input)
      if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
        dragInput = input
      end
    end)
    G.UIS.InputChanged:Connect(function(input)
      if input == dragInput and dragging and dragStart and startPos then
        local delta = input.Position - dragStart
        gui.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
      end
    end)
  end
end
do
local BAN_REMOTE_HOOK = {
  active = false,
  remotes = {},
  ownedSlots = {},
}

do
  local hookStateKey = "__KATALYST_BAN_REMOTE_HOOK_TRAMPOLINES_V1"
  local remoteEventFireServer = Instance.new("RemoteEvent").FireServer
  local unreliableRemoteEventFireServer = Instance.new("UnreliableRemoteEvent").FireServer
  local trampolineState

  local function executorName()
    local identify = getexecutorname or identifyexecutor
    if type(identify) ~= "function" then return "" end

    local succeeded, name = pcall(identify)
    return succeeded and type(name) == "string" and string.lower(name) or ""
  end

  local executorIsVolt = string.find(executorName(), "volt", 1, true) ~= nil

  local function hookEnvironment()
    assert(type(getgenv) == "function", "executor environment is unavailable")
    local environment = getgenv()
    local state = rawget(environment, hookStateKey)
    if type(state) == "table" and state.dataModel == game and type(state.slots) == "table" then
      return state
    end

    if type(state) == "table" and type(state.slots) == "table" then
      for _, slot in next, state.slots do
        slot.handler = nil
      end
    end

    state = {
      dataModel = game,
      slots = {},
    }
    rawset(environment, hookStateKey, state)
    return state
  end

  local function executorOwned(callback)
    if not executorIsVolt or type(newcclosure) ~= "function" then
      return callback
    end

    local wrapped, result = pcall(newcclosure, callback)
    return wrapped and type(result) == "function" and result or callback
  end

  local function activateSlot(name, target, handler, useExecutorClosure)
    local slot = trampolineState.slots[name]
    if slot then
      assert(slot.target == target, "hook target changed within the current DataModel: " .. name)
    else
      slot = { target = target }
      local function trampoline(...)
        local activeHandler = slot.handler
        if activeHandler then
          return activeHandler(slot.predecessor, ...)
        end
        return slot.predecessor(...)
      end

      slot.trampoline = useExecutorClosure and executorOwned(trampoline) or trampoline
      local hookOk, hookRes = pcall(hookfunction, target, slot.trampoline)
      if hookOk and type(hookRes) == "function" then
        slot.predecessor = hookRes
      else
        slot.predecessor = target
      end
      trampolineState.slots[name] = slot
    end

    slot.handler = handler
    BAN_REMOTE_HOOK.ownedSlots[#BAN_REMOTE_HOOK.ownedSlots + 1] = {
      slot = slot,
      handler = handler,
    }
  end

  local function deactivateSlots()
    for index, owned in ipairs(BAN_REMOTE_HOOK.ownedSlots) do
      if owned.slot.handler == owned.handler then
        owned.slot.handler = nil
      end
      BAN_REMOTE_HOOK.ownedSlots[index] = nil
    end
  end

  local function getConnections(signal)
    if type(getconnections) ~= "function" then return nil end

    local succeeded, connections = pcall(getconnections, signal)
    return succeeded and type(connections) == "table" and connections or nil
  end

  local function discoverBanRemotes()
    local requests = G.RepS:WaitForChild("Requests", 30)
    assert(requests, "Requests container is unavailable")

    local remotes = {}
    local count = 0
    for _, request in ipairs(requests:GetChildren()) do
      local connections = getConnections(request.Changed)
      if connections and #connections > 0 then
        remotes[request] = true
        count = count + 1
      end
    end

    local nulledCount = 0
    if type(getnilinstances) == "function" then
      for _, instance in ipairs(getnilinstances()) do
        if instance.Name == "NulledBanRemote" then
          nulledCount = nulledCount + 1
        end
      end
    end

    assert(count == 2 or nulledCount == 2, "expected exactly two Deepwoken ban remotes")
    BAN_REMOTE_HOOK.remotes = remotes
  end

  local function warnBlocked(remote)
    warn("[Katalyst] Blocked ban remote: " .. remote.Name)
  end

  local function onRemoteEventFireServer(predecessor, ...)
    local remote = ...
    if BAN_REMOTE_HOOK.remotes[remote] then
      warnBlocked(remote)
      return
    end
    return predecessor(...)
  end

  local function onUnreliableRemoteEventFireServer(predecessor, ...)
    local remote = ...
    if BAN_REMOTE_HOOK.remotes[remote] then
      warnBlocked(remote)
      return
    end
    return predecessor(...)
  end

  local function onNameCall(predecessor, ...)
    local remote = ...
    if typeof(remote) ~= "Instance" or getnamecallmethod() ~= "FireServer" then
      return predecessor(...)
    end

    if BAN_REMOTE_HOOK.remotes[remote] and not checkcaller() then
      warnBlocked(remote)
      return
    end
    return predecessor(...)
  end

  function BAN_REMOTE_HOOK.init()
    if BAN_REMOTE_HOOK.active then return end

    assert(type(hookfunction) == "function", "hookfunction is unavailable")
    assert(type(getrawmetatable) == "function", "getrawmetatable is unavailable")
    assert(type(getnamecallmethod) == "function", "getnamecallmethod is unavailable")
    assert(type(checkcaller) == "function", "checkcaller is unavailable")

    trampolineState = hookEnvironment()
    discoverBanRemotes()
    activateSlot("remoteEvent", remoteEventFireServer, onRemoteEventFireServer, false)
    activateSlot(
      "unreliableRemoteEvent",
      unreliableRemoteEventFireServer,
      onUnreliableRemoteEventFireServer,
      false
    )
    activateSlot("namecall", getrawmetatable(game).__namecall, onNameCall, true)
    BAN_REMOTE_HOOK.active = true
  end

  function BAN_REMOTE_HOOK.detach()
    deactivateSlots()
    BAN_REMOTE_HOOK.remotes = {}
    BAN_REMOTE_HOOK.active = false
  end
end
G.BanRemoteHook = BAN_REMOTE_HOOK
end
local AUTO_PARRY_BREAKER_ATTRIBUTE = "KatalystAPBreaker"
local APB = {on=false,stop=nil,cc=nil}
do
  local function run(ch) if not ch then return function() end end
    local hum=ch:FindFirstChildOfClass("Humanoid"); if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 2)
    if not ani then ani = G.new("Animator"); ani.Parent = hum end
    local trs = {}
    for _, id in ipairs(CFG.APAnims or {}) do
      pcall(function()
        local a = G.new("Animation")
        a.AnimationId = id
        a:SetAttribute(AUTO_PARRY_BREAKER_ATTRIBUTE, true)
        local tr = ani:LoadAnimation(a)
        tr.Priority = Enum.AnimationPriority.Action
        G.ti(trs, tr)
      end)
    end
    if #trs == 0 then return function() end end
    local go = true
    G.ts(function()
      local cur = nil
      local reps = 0
      while go do
        if not ch.Parent or not S.ap then break end
        
        -- Reuse same track for 3-5 pulses before switching to avoid bone conflicts
        if not cur or reps <= 0 then
          local idx = G.rd(1, #trs)
          local nxt = trs[idx]
          if cur and cur ~= nxt then
            pcall(function() cur:Stop(0.15) end)
            task.wait(0.04)
          end
          cur = nxt
          reps = G.rd(3, 5)
        end
        pcall(function()
          cur:Play(0.1, CFG.APWt or 0.06, CFG.APSpd or 0.8)
        end)
        reps = reps - 1
        -- Organic pulse timing
        task.wait(1/6 + (math.random() - 0.5) * 0.04)
      end
    end)
    return function()
      go = false
      for _, t in ipairs(trs) do
        pcall(function() t:Stop(0.1); t:Destroy() end)
      end
    end
  end
  local function att(ch) if APB.stop then APB.stop() end; APB.stop = nil; if not APB.on or not ch then return end; APB.stop = run(ch) end
  function APB:start() if self.on then return end; self.on = true; if not self.cc then self.cc = G.LP.CharacterAdded:Connect(att) end; att(G.LP.Character or G.LP.CharacterAdded:Wait()) end
  function APB:stp() if not self.on then return end; self.on = false; if self.stop then self.stop(); self.stop = nil end; if self.cc then self.cc:Disconnect(); self.cc = nil end end
end

local PL_KILLER = {on=false,stop=nil,cc=nil}
do
  local function run(ch) if not ch then return function() end end
    local hum=ch:FindFirstChildOfClass("Humanoid"); if not hum then return function() end end
    local ani=hum:FindFirstChildOfClass("Animator"); if not ani then ani=G.new("Animator"); ani.Parent=hum end
    -- Curated list of cleaner, less visually disruptive animations
    local animsToUse = {
      "rbxassetid://7627889074",
      "rbxassetid://7620630583",
      "rbxassetid://8378263543",
      "rbxassetid://9149348937"
    }
    local trs={}; for _,id in ipairs(animsToUse) do local a=G.new("Animation"); a.AnimationId=id; local tr=ani:LoadAnimation(a); tr.Priority=Enum.AnimationPriority.Action; G.ti(trs,tr) end
    if #trs==0 then return function() end end
    local go=true
    G.ts(function()
      local cur=nil
      local reps=0
      local priorities = {
        Enum.AnimationPriority.Action,
        Enum.AnimationPriority.Action2,
        Enum.AnimationPriority.Action3,
        Enum.AnimationPriority.Action4
      }
      local curPriority = Enum.AnimationPriority.Action
      local nextPriorityTime = os.clock() + math.random(4, 8)
      
      while go do
        if not ch.Parent then break end
        
        -- Shift animation priority dynamically between Action and Action1-4
        if os.clock() >= nextPriorityTime then
          curPriority = priorities[math.random(1, #priorities)]
          nextPriorityTime = os.clock() + math.random(4, 8)
          for _, t in ipairs(trs) do
            pcall(function() t.Priority = curPriority end)
          end
        end
        
        -- Reuse same track for 3-5 pulses (smooth transition)
        if not cur or reps<=0 then
          local idx=G.rd(1,#trs)
          local nxt=trs[idx]
          if cur and cur~=nxt then
            pcall(function() cur:Stop(0.5) end) -- Smooth 0.5s fade out
            task.wait(0.12)
          end
          cur=nxt
          reps=G.rd(3,5)
        end
        pcall(function()
          cur:Play(0.5, 0.61, 0.65)
        end)
        reps=reps-1
        -- Natural randomized timing intervals
        task.wait(0.3 + (math.random() - 0.5) * 0.12)
      end
    end)
    return function() go=false; for _,t in ipairs(trs) do pcall(function() t:Stop(0.5); t:Destroy() end) end end
  end
  local function att(ch) if PL_KILLER.stop then PL_KILLER.stop() end; PL_KILLER.stop=nil; if not PL_KILLER.on or not ch then return end; PL_KILLER.stop=run(ch) end
  function PL_KILLER:start() if self.on then return end; self.on=true; if not self.cc then self.cc=G.LP.CharacterAdded:Connect(att) end; att(G.LP.Character or G.LP.CharacterAdded:Wait()) end
  function PL_KILLER:stp() if not self.on then return end; self.on=false; if self.stop then self.stop(); self.stop=nil end; if self.cc then self.cc:Disconnect(); self.cc=nil end end
end

local Players = game:GetService("Players")

local function APBreaker()
  local ANIMS = {
    "rbxassetid://9149348937",
    "rbxassetid://7627889074",
    "rbxassetid://5778357994",
    "rbxassetid://16873988732",
    "rbxassetid://7620630583",
    "rbxassetid://8378263543",
  }

  local PULSES_PER_SECOND = 5000
  local SPEED = 0.8
  local WEIGHT = 0.06
  local FADE_TIME = 0
  local PRIORITY = Enum.AnimationPriority.Action

  local player = Players.LocalPlayer
  local character = player.Character or player.CharacterAdded:Wait()

  local humanoid = character:FindFirstChildOfClass("Humanoid")
  if not humanoid then
    return
  end

  local animator = humanoid:FindFirstChildOfClass("Animator")
  if not animator then
    animator = Instance.new("Animator")
    animator.Parent = humanoid
  end

  local tracks = {}

  for _, id in ipairs(ANIMS) do
    local anim = Instance.new("Animation")
    anim.AnimationId = id
    anim:SetAttribute(AUTO_PARRY_BREAKER_ATTRIBUTE, true)

    local track = animator:LoadAnimation(anim)
    track.Priority = PRIORITY
    track:AdjustWeight(WEIGHT, 0.001)

    table.insert(tracks, track)
  end

  local interval = 1 / PULSES_PER_SECOND

  task.spawn(function()
    local nextTime = os.clock()

    while character.Parent do
      local now = os.clock()

      if now >= nextTime then
        nextTime = nextTime + interval

        local track = tracks[math.random(1, #tracks)]

        pcall(function()
          track:Play(FADE_TIME, 1, SPEED)
          track:AdjustWeight(WEIGHT, 0)
        end)
      else
        task.wait()
      end
    end
  end)
end

local PR_RAIN = {on=false,stop=nil,cc=nil}
do
  local function run(ch)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then
      ani = Instance.new("Animator")
      ani.Parent = hum
    end

    local ANIMS = {
      "rbxassetid://9149348937",
      "rbxassetid://7627889074",
      "rbxassetid://5778357994",
      "rbxassetid://16873988732",
      "rbxassetid://7620630583",
      "rbxassetid://8378263543",
    }

    local PULSES_PER_SECOND = 5000
    local SPEED = 1
    local WEIGHT = 0.07
    local FADE_TIME = 0
    local PRIORITY = Enum.AnimationPriority.Action4

    local tracks = {}
    for _, id in ipairs(ANIMS) do
      local anim = Instance.new("Animation")
      anim.AnimationId = id
      local track = ani:LoadAnimation(anim)
      track.Priority = PRIORITY
      track:AdjustWeight(WEIGHT, 0.001)
      table.insert(tracks, track)
    end

    local interval = 1 / PULSES_PER_SECOND
    task.spawn(function()
      local nextTime = os.clock()
      while ch.Parent do
        local now = os.clock()
        if now >= nextTime then
          nextTime = nextTime + interval
          local track = tracks[math.random(1, #tracks)]
          pcall(function()
            track:Play(FADE_TIME, 1, SPEED)
            track:AdjustWeight(WEIGHT, 0)
          end)
        else
          task.wait()
        end
      end
    end)

    return function()
      for _, t in ipairs(tracks) do
        pcall(function()
          t:Stop(0)
          t:Destroy()
        end)
      end
    end
  end

  local function att(ch)
    if PR_RAIN.stop then PR_RAIN.stop() end
    PR_RAIN.stop = nil
    if not PR_RAIN.on or not ch then return end
    PR_RAIN.stop = run(ch)
  end

  function PR_RAIN:start()
    if self.on then return end
    self.on = true
    if not self.cc then self.cc = G.LP.CharacterAdded:Connect(att) end
    att(G.LP.Character or G.LP.CharacterAdded:Wait())
  end

  function PR_RAIN:stp()
    if not self.on then return end
    self.on = false
    if self.stop then
      self.stop()
      self.stop = nil
    end
    if self.cc then
      self.cc:Disconnect()
      self.cc = nil
    end
  end
end
local COMBO_BRK = {on=false,stop=nil,cc=nil}
do
  local PRIORITIES = {Enum.AnimationPriority.Core, Enum.AnimationPriority.Action, Enum.AnimationPriority.Idle}
  local CYCLE_TIME = 3
  local function runCombo(ch)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then ani = Instance.new("Animator"); ani.Parent = hum end
    local allAnims = CFG.APAnims
    local go = true
    task.spawn(function()
      local pIdx = 1
      local lastSwitch = os.clock()
      while go do
        if not ch.Parent then break end
        local now = os.clock()
        if now - lastSwitch >= CYCLE_TIME then
          pIdx = (pIdx % #PRIORITIES) + 1
          lastSwitch = now
        end
        local curPriority = PRIORITIES[pIdx]
        for i = 1, 5 do
          local id = allAnims[math.random(1, #allAnims)]
          pcall(function()
            local a = Instance.new("Animation")
            a.AnimationId = id
            local tr = ani:LoadAnimation(a)
            tr.Priority = curPriority
            tr:Play(0, 1, 1)
            tr:AdjustWeight(0.04, 0)
          end)
        end
        task.wait()
      end
    end)
    return function() go = false end
  end
  local function attCombo(ch) if COMBO_BRK.stop then COMBO_BRK.stop() end; COMBO_BRK.stop=nil; if not COMBO_BRK.on or not ch then return end; COMBO_BRK.stop=runCombo(ch) end
  function COMBO_BRK:start() if self.on then return end; self.on=true; if not self.cc then self.cc=G.LP.CharacterAdded:Connect(attCombo) end; attCombo(G.LP.Character or G.LP.CharacterAdded:Wait()) end
  function COMBO_BRK:stp() if not self.on then return end; self.on=false; if self.stop then self.stop(); self.stop=nil end; if self.cc then self.cc:Disconnect(); self.cc=nil end end
end

local HITBOXES_ON = {active=false, conn=nil, highlights={}, trackedParts={}}
do
  local function cleanPart(v)
    local data = HITBOXES_ON.highlights[v]
    if data then
      pcall(function()
        if data.sb then data.sb:Destroy() end
        if data.bb then data.bb:Destroy() end
        if data.box then data.box:Destroy() end
      end)
      HITBOXES_ON.highlights[v] = nil
    end
    HITBOXES_ON.trackedParts[v] = nil
  end
  
  local function handlePart(v)
    if not HITBOXES_ON.active then return end
    if not v:IsA("BasePart") then return end
    if HITBOXES_ON.trackedParts[v] then return end
    
    local myRoot = G.myR()
    if not myRoot then return end
    local dist = (myRoot.Position - v.Position).Magnitude
    if dist > 300 then return end
    
    local myChar = G.LP.Character
    if myChar and v:IsDescendantOf(myChar) then return end
    
    local name = string.lower(v.Name)
    local pName = v.Parent and string.lower(v.Parent.Name) or ""
    
    local threatType = nil
    local color = Color3.fromRGB(255, 30, 30)
    local labelText = "MELEE HITBOX"
    
    if string.find(name, "spell") or string.find(pName, "spell") or string.find(name, "mantra") or string.find(pName, "mantra") or string.find(name, "skill") then
      threatType = "MANTRA"
      color = Color3.fromRGB(180, 50, 255)
      labelText = " MANTRA AOE"
    elseif string.find(name, "projectile") or string.find(pName, "projectile") or string.find(name, "bullet") or string.find(name, "arrow") or string.find(name, "thrown") then
      threatType = "PROJECTILE"
      color = Color3.fromRGB(255, 200, 30)
      labelText = " PROJECTILE"
    elseif string.find(name, "hitbox") or string.find(pName, "hitbox") or string.find(name, "slash") or string.find(name, "swing") or string.find(name, "melee") then
      threatType = "MELEE"
      color = Color3.fromRGB(255, 30, 30)
      labelText = " MELEE HITBOX"
    elseif v:FindFirstChildOfClass("TouchTransmitter") then
      local isLimb = name == "head" or name == "humanoidrootpart" 
        or string.find(name, "torso") or string.find(name, "arm") or string.find(name, "leg") 
        or string.find(name, "hand") or string.find(name, "foot")
      local isCharacterPart = v.Parent and v.Parent:FindFirstChildOfClass("Humanoid")
      if not isLimb and not isCharacterPart then
        threatType = "HAZARD"
        color = Color3.fromRGB(0, 220, 255)
        labelText = " HAZARD / TRAP"
      end
    end
    
    if threatType then
      HITBOXES_ON.trackedParts[v] = true
      
      -- SelectionBox Outline
      local sb = Instance.new("SelectionBox")
      sb.Adornee = v
      sb.Color3 = color
      sb.LineThickness = 0.06
      sb.Transparency = 0.1
      sb.Parent = v
      
      -- BoxHandleAdornment for solid Neon Glow Fill
      local box = Instance.new("BoxHandleAdornment")
      box.Adornee = v
      box.Size = v.Size
      box.Color3 = color
      box.Transparency = 0.45
      box.AlwaysOnTop = true
      box.ZIndex = 5
      box.Parent = v
      
      -- 3D Overhead Threat Billboard Label
      local bb = Instance.new("BillboardGui")
      bb.Adornee = v
      bb.Size = UDim2.new(0, 140, 0, 24)
      bb.StudsOffset = Vector3.new(0, v.Size.Y / 2 + 1, 0)
      bb.AlwaysOnTop = true
      bb.Parent = v
      
      local lbl = Instance.new("TextLabel", bb)
      lbl.Size = UDim2.new(1, 0, 1, 0)
      lbl.BackgroundTransparency = 0.3
      lbl.BackgroundColor3 = Color3.fromRGB(15, 15, 20)
      lbl.TextColor3 = color
      lbl.Font = Enum.Font.GothamBold
      lbl.TextSize = 9
      lbl.Text = labelText .. " [" .. math.floor(dist) .. "m]"
      lbl.BorderSizePixel = 0
      G.mkC(lbl, 4)
      G.mkS(lbl, color, 1, 0.2)
      
      HITBOXES_ON.highlights[v] = {sb = sb, bb = bb, box = box}
      
      local conn; conn = v.AncestryChanged:Connect(function()
        if not v.Parent then
          cleanPart(v)
          conn:Disconnect()
        end
      end)
    end
  end
  
  function HITBOXES_ON.en()
    if HITBOXES_ON.active then return end
    HITBOXES_ON.active = true
    
    local function scanFolder(folder)
      if not folder then return end
      for _, v in ipairs(folder:GetChildren()) do
        if not HITBOXES_ON.active then break end
        if v:IsA("BasePart") then
          pcall(handlePart, v)
        elseif v:IsA("Model") or v:IsA("Folder") then
          for _, child in ipairs(v:GetDescendants()) do
            if child:IsA("BasePart") then
              pcall(handlePart, child)
            end
          end
        end
      end
    end
    
    task.spawn(function()
      pcall(function()
        for _, child in ipairs(game.Workspace:GetChildren()) do
          if not HITBOXES_ON.active then break end
          if child:FindFirstChildOfClass("Humanoid") then
            for _, part in ipairs(child:GetDescendants()) do
              if part:IsA("BasePart") then
                pcall(handlePart, part)
              end
            end
          end
        end
        scanFolder(game.Workspace:FindFirstChild("Effects"))
        scanFolder(game.Workspace:FindFirstChild("Ignore"))
        scanFolder(game.Workspace:FindFirstChild("Projectiles"))
        scanFolder(game.Workspace:FindFirstChild("Thrown"))
      end)
    end)
    
    HITBOXES_ON.conn = game.Workspace.DescendantAdded:Connect(function(v)
      pcall(handlePart, v)
    end)
    
    G.noti("Visuals", "Hitboxes On: Neon Threat Trackers Active")
  end
  
  function HITBOXES_ON.dis()
    HITBOXES_ON.active = false
    if HITBOXES_ON.conn then
      HITBOXES_ON.conn:Disconnect()
      HITBOXES_ON.conn = nil
    end
    for part, data in pairs(HITBOXES_ON.highlights) do
      pcall(function()
        if data.sb then data.sb:Destroy() end
        if data.bb then data.bb:Destroy() end
        if data.box then data.box:Destroy() end
      end)
    end
    table.clear(HITBOXES_ON.highlights)
    table.clear(HITBOXES_ON.trackedParts)
  end
end

local NFD = {cc=nil,stConn=nil,velConn=nil,active=false}
do
  local oldHasEffect, cachedEF
  function NFD.en()
    if NFD.active then return end; NFD.active=true
    pcall(function()
      if not cachedEF then local _ef = G.RepS:FindFirstChild("EffectReplicator"); if _ef then cachedEF = require(_ef) end; end
      if cachedEF and not oldHasEffect then
        oldHasEffect = cachedEF.HasEffect
        cachedEF.HasEffect = function(self, effectName, ...)
          if NFD.active and (effectName == "NoFall" or effectName == "FallDamage" or effectName == "Fall") then return true end
          return oldHasEffect(self, effectName, ...)
        end
      end
    end)
    local function hookHum(ch)
      if NFD.stConn then NFD.stConn:Disconnect(); NFD.stConn=nil end
      if NFD.velConn then NFD.velConn:Disconnect(); NFD.velConn=nil end
      if not ch then return end
      local hum = ch:FindFirstChildOfClass("Humanoid"); if not hum then return end
      pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
      NFD.stConn = hum.StateChanged:Connect(function(_, new)
        if not NFD.active then return end
        if new == Enum.HumanoidStateType.FallingDown then
          pcall(function() hum:ChangeState(Enum.HumanoidStateType.Landing) end)
        elseif new == Enum.HumanoidStateType.Landed then
          pcall(function()
            local root = ch:FindFirstChild("HumanoidRootPart")
            if root then
              root.Velocity = G.V3(root.Velocity.X, 0, root.Velocity.Z)
            end
          end)
        end
      end)
      local root = ch:FindFirstChild("HumanoidRootPart")
      if root then
        NFD.velConn = G.RS.Heartbeat:Connect(function()
          if not NFD.active then return end
          pcall(function()
            if hum:GetState() == Enum.HumanoidStateType.Freefall then
              if root.Velocity.Y < -120 then
                root.Velocity = G.V3(root.Velocity.X, -120, root.Velocity.Z)
              end
            end
          end)
        end)
      end
    end
    local ch = G.LP and G.LP.Character; if ch then hookHum(ch) end
    if not NFD.cc then NFD.cc=G.LP.CharacterAdded:Connect(function(c)
      G.tw(0.3); if NFD.active then hookHum(c) end
    end) end
  end
  function NFD.dis()
    NFD.active=false
    if NFD.stConn then NFD.stConn:Disconnect(); NFD.stConn=nil end
    if NFD.velConn then NFD.velConn:Disconnect(); NFD.velConn=nil end
    if NFD.cc then NFD.cc:Disconnect(); NFD.cc=nil end
    pcall(function()
      local ch = G.LP and G.LP.Character
      if ch then
        local hum = ch:FindFirstChildOfClass("Humanoid")
        if hum then hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true) end
      end
    end)
    pcall(function()
      if oldHasEffect and cachedEF then
        cachedEF.HasEffect = oldHasEffect; oldHasEffect=nil
      end
    end)
  end
end
---@note: Never call the roll function from the cache. We only need this to get the last roll move direction.
AP_BREAKER_METHOD_NAMES = {
  [1] = "Method 1",
  [2] = "Method 2",
  [3] = "Method 3",
  [4] = "Method 4",
  [5] = "Method 5",
}

AP_BREAKER_ENGINE = {
  active = false,
  method = 1,
  hookConn = nil,
  characterConn = nil,
  stopCharacter = nil,
  generation = 0,
  poolTracks = {},
  obfTracks = {},
  spamPoolIds = {},
  obfPoolIds = {}
}

do
  local src = CFG.APAnims or {}
  for i, id in ipairs(src) do
    if i <= 8 then
      table.insert(AP_BREAKER_ENGINE.spamPoolIds, id)
    else
      table.insert(AP_BREAKER_ENGINE.obfPoolIds, id)
    end
  end
end

local SPOOF_HEADERS_BRK = { "Walk", "Run", "Idle", "Jump", "Fall", "Climb", "Swim" }

do
  local function destroyPool(tracks, animations)
    for _, tr in ipairs(tracks) do
      pcall(function()
        tr:Stop(0)
        tr:Destroy()
      end)
    end
    for _, animation in ipairs(animations) do
      pcall(function() animation:Destroy() end)
    end
  end

  local function run(ch, generation)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid") or ch:WaitForChild("Humanoid", 3)
    if not hum or not AP_BREAKER_ENGINE.active or generation ~= AP_BREAKER_ENGINE.generation then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 3)
    if not ani or not AP_BREAKER_ENGINE.active or generation ~= AP_BREAKER_ENGINE.generation then return function() end end

    local poolTracks = {}
    local obfTracks = {}
    local poolAnimations = {}
    local obfAnimations = {}
    local ownedTracks = {}
    local mutatedTracks = {}
    local running = true

    for _, id in ipairs(AP_BREAKER_ENGINE.spamPoolIds) do
      pcall(function()
        local a = Instance.new("Animation")
        a.AnimationId = id
        a.Name = SPOOF_HEADERS_BRK[math.random(1, #SPOOF_HEADERS_BRK)]
        local tr = ani:LoadAnimation(a)
        ownedTracks[tr] = true
        table.insert(poolAnimations, a)
        table.insert(poolTracks, tr)
      end)
    end

    for _, id in ipairs(AP_BREAKER_ENGINE.obfPoolIds) do
      pcall(function()
        local a = Instance.new("Animation")
        a.AnimationId = id
        a.Name = SPOOF_HEADERS_BRK[math.random(1, #SPOOF_HEADERS_BRK)]
        local tr = ani:LoadAnimation(a)
        ownedTracks[tr] = true
        table.insert(obfAnimations, a)
        table.insert(obfTracks, tr)
      end)
    end

    if not AP_BREAKER_ENGINE.active or generation ~= AP_BREAKER_ENGINE.generation then
      destroyPool(poolTracks, poolAnimations)
      destroyPool(obfTracks, obfAnimations)
      return function() end
    end

    AP_BREAKER_ENGINE.poolTracks = poolTracks
    AP_BREAKER_ENGINE.obfTracks = obfTracks

    local function rememberTrack(track)
      if mutatedTracks[track] then return end
      local state = {priority = track.Priority}
      pcall(function() state.weight = track.WeightTarget end)
      mutatedTracks[track] = state
    end

    local function boostRealTrackToAction4(track)
      if not track or ownedTracks[track] then return end
      pcall(function()
        track.Priority = Enum.AnimationPriority.Action4
        track:AdjustWeight(1.0, 0)
      end)
    end

    local m5Thread = nil
    local heartbeatConn = nil

    local hookConn = ani.AnimationPlayed:Connect(function(track)
      if not AP_BREAKER_ENGINE.active or not running or not track or not track.Animation or ownedTracks[track] then return end
      local aName = string.lower(track.Animation.Name or "")
      local isCombat = aName:find("m1") or aName:find("swing") or aName:find("slash") or aName:find("attack") or aName:find("mantra") or aName:find("cast") or aName:find("spell")

      local curMethod = CFG.BreakerMethod or AP_BREAKER_ENGINE.method or 1

      if curMethod == 1 then
        if isCombat then
          local w = CFG.Method1_FloodWeight or 0.85
          local picked = {}
          if #poolTracks > 0 then
            for _ = 1, math.min(2, #poolTracks) do
              local idx = math.random(1, #poolTracks)
              if not picked[idx] then
                picked[idx] = true
                local tr = poolTracks[idx]
                pcall(function()
                  tr.Priority = Enum.AnimationPriority.Action
                  tr:Play(0.06 + math.random() * 0.04, w, 1.0)
                  local stopDelay = 0.14 + math.random() * 0.08
                  task.delay(stopDelay, function()
                    if not running then return end
                    pcall(function() tr:Stop(0.10 + math.random() * 0.04) end)
                  end)
                end)
              end
            end
          end
          if aName:find("mantra") or aName:find("cast") or aName:find("spell") then
            task.delay(0.16, function()
              if not running then return end
              pcall(function() track:Stop(0.10) end)
            end)
          end
        end

      elseif curMethod == 2 then
        if isCombat then
          pcall(function()
            track.Priority = Enum.AnimationPriority.Action4
            track:AdjustWeight(1.0, 0)
          end)

          pcall(function()
            local aId = track.Animation and track.Animation.AnimationId
            if aId and aId ~= "" then
              local dupAnim = Instance.new("Animation")
              dupAnim.AnimationId = aId
              dupAnim.Name = SPOOF_HEADERS_BRK[math.random(1, #SPOOF_HEADERS_BRK)]
              local dupTrk = ani:LoadAnimation(dupAnim)
              ownedTracks[dupTrk] = true
              dupTrk.Priority = Enum.AnimationPriority.Movement
              dupTrk:Play(0, 1.0, 1.0)

              task.delay(0.06, function()
                if not running or not dupTrk.IsPlaying then return end
                pcall(function()
                  dupTrk.Priority = Enum.AnimationPriority.Action
                  dupTrk:AdjustWeight(0.7, 0.02)
                end)
              end)
              task.delay(0.12, function()
                if not running or not dupTrk.IsPlaying then return end
                pcall(function()
                  dupTrk.Priority = Enum.AnimationPriority.Action2
                  dupTrk:AdjustWeight(0.5, 0.02)
                end)
              end)
              task.delay(0.18, function()
                if not running or not dupTrk.IsPlaying then return end
                pcall(function()
                  dupTrk.Priority = Enum.AnimationPriority.Core
                  dupTrk:AdjustWeight(0.2, 0.02)
                end)
              end)
              task.delay(0.24, function()
                pcall(function()
                  dupTrk:Stop(0.08)
                  dupTrk:Destroy()
                  dupAnim:Destroy()
                  ownedTracks[dupTrk] = nil
                end)
              end)
            end
          end)
        end

      elseif curMethod == 3 then
        if isCombat then
          pcall(function()
            track.Priority = Enum.AnimationPriority.Action4
            track:AdjustWeight(1.0, 0)
          end)

          pcall(function()
            local aId = track.Animation and track.Animation.AnimationId
            if aId and aId ~= "" then
              local dupAnim = Instance.new("Animation")
              dupAnim.AnimationId = aId
              dupAnim.Name = SPOOF_HEADERS_BRK[math.random(1, #SPOOF_HEADERS_BRK)]
              local dupTrk = ani:LoadAnimation(dupAnim)
              ownedTracks[dupTrk] = true
              dupTrk.Priority = Enum.AnimationPriority.Movement
              dupTrk:Play(0, 1.0, 1.0)

              task.delay(0.06, function()
                if not running or not dupTrk.IsPlaying then return end
                pcall(function()
                  dupTrk.Priority = Enum.AnimationPriority.Action
                  dupTrk:AdjustWeight(0.7, 0.02)
                end)
              end)
              task.delay(0.12, function()
                if not running or not dupTrk.IsPlaying then return end
                pcall(function()
                  dupTrk.Priority = Enum.AnimationPriority.Action2
                  dupTrk:AdjustWeight(0.5, 0.02)
                end)
              end)
              task.delay(0.24, function()
                pcall(function()
                  dupTrk:Stop(0.08)
                  dupTrk:Destroy()
                  dupAnim:Destroy()
                  ownedTracks[dupTrk] = nil
                end)
              end)
            end
          end)

          local w = CFG.Method1_FloodWeight or 0.85
          local picked = {}
          if #poolTracks > 0 then
            for _ = 1, math.min(2, #poolTracks) do
              local idx = math.random(1, #poolTracks)
              if not picked[idx] then
                picked[idx] = true
                local tr = poolTracks[idx]
                pcall(function()
                  tr:Play(0.06 + math.random() * 0.04, w, 1.0)
                  local stopDelay = 0.14 + math.random() * 0.08
                  task.delay(stopDelay, function()
                    if not running then return end
                    pcall(function() tr:Stop(0.10 + math.random() * 0.04) end)
                  end)
                end)
              end
            end
          end

          if #obfTracks > 0 then
            local ghostTr = obfTracks[math.random(1, #obfTracks)]
            pcall(function()
              ghostTr.Priority = Enum.AnimationPriority.Core
              ghostTr:Play(0.02, 0.03, 1.0)
              task.delay(0.12, function()
                if not running then return end
                pcall(function() ghostTr:Stop(0.06) end)
              end)
            end)
          end
        end

      elseif curMethod == 4 then
        if isCombat and #obfTracks > 0 then
          local idx1 = math.random(1, #obfTracks)
          local idx2 = idx1
          if #obfTracks > 1 then
            while idx2 == idx1 do idx2 = math.random(1, #obfTracks) end
          end
          local tr1 = obfTracks[idx1]
          local tr2 = obfTracks[idx2]
          local spd1 = 0.85 + math.random() * 0.30
          local spd2 = 0.85 + math.random() * 0.30
          pcall(function()
            tr1.Priority = Enum.AnimationPriority.Action
            tr1:Play(0.04, 0.75, spd1)
            task.delay(0.20 + math.random() * 0.06, function()
              if not running then return end
              pcall(function() tr1:Stop(0.08) end)
            end)
          end)
          pcall(function()
            tr2.Priority = Enum.AnimationPriority.Movement
            tr2:Play(0.04, 0.45, spd2)
            task.delay(0.18 + math.random() * 0.06, function()
              if not running then return end
              pcall(function() tr2:Stop(0.08) end)
            end)
          end)
        end

      elseif curMethod == 5 then
        -- Method 5: Instant Action4 boost for ALL real animations (movement, idle, attacks, mantras, rolls)
        boostRealTrackToAction4(track)
      end
    end)
    AP_BREAKER_ENGINE.hookConn = hookConn

    local curMethod = CFG.BreakerMethod or AP_BREAKER_ENGINE.method or 1
    if curMethod == 5 then
      -- Boost all already-playing tracks immediately
      pcall(function()
        for _, tr in ipairs(ani:GetPlayingAnimationTracks()) do
          boostRealTrackToAction4(tr)
        end
      end)

      -- Heartbeat sweep to continuously enforce Action4 on all movement and combat tracks
      heartbeatConn = G.RS.Heartbeat:Connect(function()
        if not running or not AP_BREAKER_ENGINE.active or generation ~= AP_BREAKER_ENGINE.generation then return end
        pcall(function()
          for _, tr in ipairs(ani:GetPlayingAnimationTracks()) do
            if tr and tr.IsPlaying and not ownedTracks[tr] then
              if tr.Priority ~= Enum.AnimationPriority.Action4 then
                tr.Priority = Enum.AnimationPriority.Action4
                tr:AdjustWeight(1.0, 0)
              end
            end
          end
        end)
      end)

      if #poolTracks > 0 then
        m5Thread = task.spawn(function()
          local trackIdx = 1
          local trackCount = #poolTracks
          while running and AP_BREAKER_ENGINE.active and generation == AP_BREAKER_ENGINE.generation do
            if not ch.Parent then break end

            if CFG.PT_ProxCheck then
              local myHrp = ch:FindFirstChild("HumanoidRootPart")
              if myHrp then
                local maxDist = tonumber(CFG.PT_ProxRange) or 500
                local inRange = false
                local live = workspace:FindFirstChild("Live") or workspace
                for _, entity in ipairs(live:GetChildren()) do
                  if entity:IsA("Model") and entity ~= ch and entity:FindFirstChild("HumanoidRootPart") then
                    if (entity.HumanoidRootPart.Position - myHrp.Position).Magnitude <= maxDist then
                      inRange = true
                      break
                    end
                  end
                end
                if not inRange then
                  task.wait(0.25)
                  continue
                end
              end
            end

            local tr = poolTracks[trackIdx]
            trackIdx = (trackIdx % trackCount) + 1

            pcall(function()
              tr.Priority = Enum.AnimationPriority.Action
              tr:Play(0.02, 0.75, 1.0)
              tr:AdjustWeight(0.75, 0)
              local pulseLen = 0.08 + math.random() * 0.08
              task.delay(pulseLen, function()
                if not running then return end
                pcall(function() tr:Stop(0.04) end)
              end)
            end)

            task.wait(0.25 + math.random() * 0.25)
          end
        end)
      end
    end

    return function()
      running = false
      hookConn:Disconnect()
      if AP_BREAKER_ENGINE.hookConn == hookConn then AP_BREAKER_ENGINE.hookConn = nil end

      if heartbeatConn then
        pcall(function() heartbeatConn:Disconnect() end)
        heartbeatConn = nil
      end

      if m5Thread then
        pcall(function() task.cancel(m5Thread) end)
        m5Thread = nil
      end

      for track, state in pairs(mutatedTracks) do
        pcall(function()
          track.Priority = state.priority
          if state.weight ~= nil and track.IsPlaying then track:AdjustWeight(state.weight, 0.05) end
        end)
      end

      destroyPool(poolTracks, poolAnimations)
      destroyPool(obfTracks, obfAnimations)
      if AP_BREAKER_ENGINE.poolTracks == poolTracks then AP_BREAKER_ENGINE.poolTracks = {} end
      if AP_BREAKER_ENGINE.obfTracks == obfTracks then AP_BREAKER_ENGINE.obfTracks = {} end
    end
  end

  local function attach(ch)
    AP_BREAKER_ENGINE.generation = AP_BREAKER_ENGINE.generation + 1
    local generation = AP_BREAKER_ENGINE.generation
    if AP_BREAKER_ENGINE.stopCharacter then AP_BREAKER_ENGINE.stopCharacter() end
    AP_BREAKER_ENGINE.stopCharacter = nil
    if not AP_BREAKER_ENGINE.active or not ch then return end
    G.ts(function()
      local stopCharacter = run(ch, generation)
      if not AP_BREAKER_ENGINE.active or generation ~= AP_BREAKER_ENGINE.generation or ch ~= G.LP.Character then
        stopCharacter()
        return
      end
      AP_BREAKER_ENGINE.stopCharacter = stopCharacter
    end)
  end

  function AP_BREAKER_ENGINE:start()
    if self.active then return end
    self.active = true
    S.animationBreaker = true
    self.method = CFG.BreakerMethod or 1
    if not self.characterConn then self.characterConn = G.LP.CharacterAdded:Connect(attach) end
    attach(G.LP.Character)
  end

  function AP_BREAKER_ENGINE:refresh()
    if self.active then attach(G.LP.Character) end
  end

  function AP_BREAKER_ENGINE:stop()
    self.active = false
    S.animationBreaker = false
    self.generation = self.generation + 1
    if self.stopCharacter then
      self.stopCharacter()
      self.stopCharacter = nil
    end
    if self.characterConn then
      self.characterConn:Disconnect()
      self.characterConn = nil
    end
    self.hookConn = nil
    self.poolTracks = {}
    self.obfTracks = {}
  end
end

local InputClient = {
	sprintFunctionCache = nil,
	rollFunctionCache = nil,
	_cacheEnabled = false,
	_cacheGeneration = 0,
	_directDodgeUntil = 0,
}

local Logger, KeyHandling, TaskSpawner

function InputClient.bindDependencies(logger, keyHandling, taskSpawner)
	Logger = logger
	KeyHandling = keyHandling
	TaskSpawner = taskSpawner
end

-- Services.
local runService = game:GetService("RunService")
local replicatedStorage = game:GetService("ReplicatedStorage")
local players = game:GetService("Players")
local tweenService = game:GetService("TweenService")

-- Functions.
local unreliableFireServer = Instance.new("UnreliableRemoteEvent").FireServer
-- Cache.
local inputDataCache = nil
local PACKET_PLK = nil
local getEffectModule = (function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return nil
	end

	return require(effectReplicator)
end)

-- Tracks.
local freefallTrack = nil
local slideJumpTrack = nil
local cancelLeftTrack = nil
local cancelRightTrack = nil
local jumpAnimTrack = nil
local crouchTrack = nil
local groundslideTrack = nil

-- Slide state.
local slideBodyVelocity = nil
local slideActive = false

-- Crouch state.
local crouchActive = false
local crouchSession = 0

function InputClient.clearCache()
	local function clearTrack(track)
		if track then
			pcall(track.Stop, track, 0)
			pcall(track.Destroy, track)
		end
	end

	clearTrack(freefallTrack)
	clearTrack(slideJumpTrack)
	clearTrack(cancelLeftTrack)
	clearTrack(cancelRightTrack)
	clearTrack(jumpAnimTrack)
	clearTrack(crouchTrack)
	clearTrack(groundslideTrack)

	freefallTrack = nil
	slideJumpTrack = nil
	cancelLeftTrack = nil
	cancelRightTrack = nil
	jumpAnimTrack = nil
	crouchTrack = nil
	groundslideTrack = nil
	InputClient.sprintFunctionCache = nil
	InputClient.rollFunctionCache = nil
	InputClient._directDodgeUntil = 0
	inputDataCache = nil

	if slideBodyVelocity and slideBodyVelocity.Parent then
		slideBodyVelocity:Destroy()
	end
	slideBodyVelocity = nil
	slideActive = false
	crouchActive = false
	crouchSession = crouchSession + 1
end

function InputClient.detach()
	InputClient._cacheEnabled = false
	InputClient._cacheGeneration = InputClient._cacheGeneration + 1
	InputClient.clearCache()
	return true
end

function InputClient.isDirectDodgeActive()
	return InputClient._cacheEnabled and os.clock() < InputClient._directDodgeUntil
end

---Check if we landed.
---@return boolean
local landedCheck = (function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local humanController = InputClient.getHumanController()
	if not humanController then
		return
	end

	local sprintSpeed = effectReplicatorModule:FindEffect("SprintSpeed")
	if not sprintSpeed then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local characterHandler = character:FindFirstChild("CharacterHandler")
	local inputClient = characterHandler and characterHandler:FindFirstChild("InputClient")
	if not inputClient then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	local torso = character:FindFirstChild("Torso")
	if not torso then
		return
	end

	local groundSensor = humanController.GroundSensor
	if not groundSensor then
		return
	end

	local stopDodge = KeyHandling.getRemote("StopDodge")
	if not stopDodge then
		return
	end

	local inputData = InputClient.getInputData()
	if not inputData then
		return
	end

	local repDebris = replicatedStorage:FindFirstChild("Debris")
	if not repDebris then
		return
	end

	local sounds = replicatedStorage:FindFirstChild("Sounds")
	local sliding = sounds and sounds:FindFirstChild("Sliding")
	if not sliding then
		return
	end

	local modules = replicatedStorage:FindFirstChild("Modules")
	local vectorMaths = modules and modules:FindFirstChild("VectorMaths")
	local vectorMathModule = vectorMaths and require(vectorMaths)
	if not vectorMathModule then
		return
	end

	local sensedPart = groundSensor.SensedPart

	if not effectReplicatorModule:HasAny("Swimming", "ClientSwim", "Gliding", "Knocked") then
		if not sensedPart then
			return false
		end

		if sensedPart and sensedPart.CollisionGroup == "Ship" then
			effectReplicatorModule:EnsureEffect("OnShip")
		elseif effectReplicatorModule:HasEffect("OnShip") then
			effectReplicatorModule:RemoveEffectsOfClass("OnShip")
		end
	end

	if freefallTrack.IsPlaying then
		freefallTrack:Stop(0.15)
	end

	if not effectReplicatorModule:HasEffect("Falling") then
		return true
	end

	effectReplicatorModule:RemoveEffectsOfClass("Falling")
	effectReplicatorModule:RemoveEffectsOfClass("ShipJump")
	effectReplicatorModule:RemoveEffectsOfClass("WingDashCooldown")

	humanoid.Jump = false

	effectReplicatorModule:CreateEffect("Landed"):Debris(0.05)

	if effectReplicatorModule:HasEffect("SlideJumping") and not effectReplicatorModule:HasEffect("GravityField") then
		effectReplicatorModule:RemoveEffectsOfClass("SlideJumping")

		if sprintSpeed and sprintSpeed.Value >= 9 then
			sprintSpeed.Value = sprintSpeed.Value - 3
		end

		local lookVector = root.CFrame.LookVector * 3
		local slideJump = torso:FindFirstChild("SlideJump")

		if slideJump then
			slideJump:Destroy()
		end

		if effectReplicatorModule:HasEffect("Sprinting") then
			humanoid:LoadAnimation(inputClient.SlideJumpTransition):Play(nil, 0.65)
		else
			humanoid:LoadAnimation(inputClient.LandingAnim):Play(nil, 0.65)
		end

		if slideJumpTrack.IsPlaying and effectReplicatorModule:HasEffect("Equipped") then
			slideJumpTrack:Stop(0.15)
		end

		stopDodge:FireServer(inputData, effectReplicatorModule:HasEffect("LightAttack"), true)

		local lookVectorUnitMulti = lookVector.Unit * 50

		if sensedPart and sensedPart.AssemblyMass > root.AssemblyMass then
			lookVectorUnitMulti = lookVectorUnitMulti
				+ vectorMathModule.getVelocityAtPoint(sensedPart, groundSensor.HitFrame.Position)
		end

		local bodyVelocity = Instance.new("BodyVelocity")
		bodyVelocity.Name = "SlideJump2"
		bodyVelocity.Velocity = lookVectorUnitMulti
		bodyVelocity.MaxForce = Vector3.new(80000, 80000, 80000, 0)
		bodyVelocity:AddTag("AllowedBM")
		bodyVelocity.Parent = torso

		repDebris:Fire(bodyVelocity, 0.2)

		local slidingSound = sliding:Clone()
		slidingSound.Parent = root
		slidingSound:Play()

		repDebris:Fire(slidingSound, 0.25)

		tweenService
			:Create(slidingSound, TweenInfo.new(0.25), {
				Volume = 0,
			})
			:Play()
	end

	task.delay(0.1, function()
		effectReplicatorModule:RemoveEffectsOfClass("WallJumpCD")
		effectReplicatorModule:RemoveEffectsOfClass("BigMomentum")
		task.wait(2)
	end)

	return true
end)

---Check if we're in freefall.
local freefallCheck = (function()
	if landedCheck() then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	if effectReplicatorModule:HasEffect("OnShip") then
		effectReplicatorModule:RemoveEffectsOfClass("OnShip")
		effectReplicatorModule:EnsureEffect("ShipJump"):Debris(5, true)
	end

	effectReplicatorModule:EnsureEffect("Falling")

	local fallTime = tick() - (effectReplicatorModule:GetEffectEpoch("Falling") or 0)

	if
		effectReplicatorModule:HasAny("DashIt", "Jumped", "UsingAbility", "LightAttack", "Action")
		or root.AssemblyLinearVelocity.Y > 0
	then
		return freefallTrack.IsPlaying and freefallTrack:Stop(0.1)
	end

	if freefallTrack.IsPlaying then
		return
	end

	if fallTime > 0.5 and root.AssemblyLinearVelocity.Y < 0 then
		freefallTrack.Priority = Enum.AnimationPriority.Movement
		freefallTrack:Play(0.3)
	end
end)

---In air check.
---@return boolean
local inAirCheck = (function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return
	end

	local humanoid = character:FindFirstChildWhichIsA("Humanoid")
	if not humanoid then
		return
	end

	if effectReplicatorModule:HasEffect("Swimming") then
		return false
	elseif humanoid:GetState() == Enum.HumanoidStateType.Freefall then
		return true
	elseif effectReplicatorModule:HasEffect("AirBorne") then
		return true
	else
		return false
	end
end)

---Movement check.
---@return boolean
local movementCheck = (function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if effectReplicatorModule:HasEffect("Action") then
		return false
	elseif effectReplicatorModule:HasEffect("NoParkour") then
		return false
	elseif effectReplicatorModule:HasEffect("Knocked") or effectReplicatorModule:HasEffect("Unconscious") then
		return false
	elseif effectReplicatorModule:HasEffect("Pinned") or effectReplicatorModule:HasEffect("Carried") then
		return false
	else
		return true
	end
end)

---@param value any
---@return boolean
local manualTableFind = (function(tbl, value)
	for _, val in next, tbl do
		if val ~= value then
			continue
		end

		return true
	end
end)

---@return boolean
local hasNonBooleans = (function(tbl)
	for _, value in next, tbl do
		if typeof(value) == "boolean" then
			continue
		end

		return false
	end

	return true
end)

local getTableLength = (function(tbl)
	local count = 0

	for _ in next, tbl do
		count = count + 1
	end

	return count
end)

---Validate keys.
local validateKeys = (function(tbl)
	local allowedKeys = {
		["Left"] = true,
		["Right"] = true,
		["W"] = true,
		["A"] = true,
		["S"] = true,
		["D"] = true,
		["Thumbstick1"] = true,
		["C"] = true,
		["f"] = true,
		["H"] = true,
		["Space"] = true,
		["ctrl"] = true,
	}

	for key, _ in next, tbl do
		if allowedKeys[key] then
			continue
		end

		return false
	end

	return true
end)

---Fetch last roll move direction.
---@return Vector3?
InputClient.getLastRollMoveDirection = (function()
	local rollFunction = InputClient.rollFunctionCache
	if not rollFunction then
		return nil
	end

	local lastRollMoveDirection = nil

	for _, upvalue in next, debug.getupvalues(rollFunction) do
		if typeof(upvalue) ~= "Vector3" then
			continue
		end

		lastRollMoveDirection = upvalue
		break
	end

	if not lastRollMoveDirection then
		lastRollMoveDirection = Vector3.zero
	end

	if lastRollMoveDirection and typeof(lastRollMoveDirection) ~= "Vector3" then
		return nil
	end

	return lastRollMoveDirection
end)

---Fetch human controller.
InputClient.getHumanController = (function()
	---@note: Shouldn't be too many connections to PreSimulation.
	for _, connection in next, getconnections(runService.PreSimulation) do
		local func = connection.Function
		if not func then
			continue
		end

		if iscclosure(func) or isexecutorclosure(func) then
			continue
		end

		local upvalues = debug.getupvalues(func)
		if not upvalues then
			continue
		end

		for _, upvalue in next, upvalues do
			if typeof(upvalue) ~= "table" then
				continue
			end

			if upvalue.Jumping == nil then
				continue
			end

			return upvalue
		end
	end

	return nil
end)

