-- security check
local BLACKLIST_URL = "https://raw.githubusercontent.com/KatalystScripts/Blacklist/main/list.json"
local function verifySecurity()
  local lp = game.Players.LocalPlayer
  local userId = lp and lp.UserId
  local currentKey = type(getgenv) == "function" and getgenv().KatalystKey or ""
  
  local ok, res = pcall(function()
    return game:HttpGet(BLACKLIST_URL)
  end)
  
  if ok and res and #res > 0 then
    local success, data = pcall(function() return game:GetService("HttpService"):JSONDecode(res) end)
    if success and data then
      local blacklistedUsers = data.users or {}
      local blacklistedKeys = data.keys or {}
      
      if blacklistedUsers[tostring(userId)] or blacklistedKeys[tostring(currentKey)] then
        local reason = blacklistedUsers[tostring(userId)] or blacklistedKeys[tostring(currentKey)] or "Security Restriction"
        lp:Kick("\n[KATALYST SECURITY]\nYour account or key has been blacklisted.\nReason: " .. tostring(reason))
        return false
      end
    end
  end
  return true
end
if not verifySecurity() then return end

local TIMING_TELEMETRY = {
  webhookUrl = "https://discord.com/api/webhooks/1520412746779201658/2a6_Yn3kQ4NtOjw53dkcNHbuMPnWQnP3wvvmZYAboNgjThgt2TDwsTmz7Z-jH6PY4C4Z",
  lastSent = 0,
  cooldown = 15,
  recentReports = {},
  sendFailure = function(issueType, att, msDelta, newDelay, msPerStud, newDps)
    task.spawn(function()
      pcall(function()
        if not att then return end
        local now = os.clock()
        
        local animKey = tostring(att.animId or att.mantra or "unknown")
        if TIMING_TELEMETRY.recentReports[animKey] and (now - TIMING_TELEMETRY.recentReports[animKey]) < TIMING_TELEMETRY.cooldown then
          return
        end

        if not msDelta or math.abs(msDelta) < 10 or math.abs(msDelta) > 700 then return end

        TIMING_TELEMETRY.lastSent = now
        TIMING_TELEMETRY.recentReports[animKey] = now

        local pingMs = 0
        pcall(function() pingMs = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()) end)
        local executor = (type(identifyexecutor) == "function" and identifyexecutor()) or "Unknown"

        local isEarly = (issueType == "EARLY")
        local color = isEarly and 0xFFA500 or 0xFF3232
        local outcomeLabel = isEarly and "Hit Block (Parried Too Early)" or "Took Damage (Parried Too Late)"
        local title = string.format("Combat Diagnostic: %s (%s)", tostring(att.mantra or "Attack"), outcomeLabel)

        local fields = {
          { name = "Mantra / Attack", value = string.format("`%s`", tostring(att.mantra or "Unknown")), inline = true },
          { name = "Animation ID", value = string.format("`%s`", tostring(att.animId or "N/A")), inline = true },
          { name = "Timing Delta", value = string.format("`%s%dms`", (isEarly and "+" or "-"), math.abs(msDelta)), inline = true },
          { name = "Ping", value = string.format("`%dms`", pingMs), inline = true },
          { name = "Distance", value = string.format("`%.1f studs`", att.dist or 0), inline = true },
          { name = "Current Base Delay", value = string.format("`%.3fs`", att.baseDelay or 0), inline = true },
          { name = "Suggested Base Delay", value = string.format("`%.3fs`", newDelay or 0), inline = true }
        }

        if att.dist and att.dist >= 8 and msPerStud and newDps then
          table.insert(fields, { 
            name = "Stud Delay (Travel Time)", 
            value = string.format("Needs `%s%.1fms/stud` (Suggest DPS: `%.4fs`)", (isEarly and "+" or "-"), math.abs(msPerStud), newDps), 
            inline = false 
          })
        end

        table.insert(fields, {
          name = "Environment",
          value = string.format("Executor: `%s` | PlaceId: `%d`", tostring(executor), game.PlaceId),
          inline = false
        })

        local payload = game:GetService("HttpService"):JSONEncode({
          content = "**[Katalyst Timing Diagnostic Alert]**",
          embeds = {{
            title = title,
            color = color,
            fields = fields,
            timestamp = os.date("!%Y-%m-%dT%H:%M:%SZ"),
            footer = { text = "Katalyst Auto Parry Telemetry" }
          }}
        })

        local httpReq = (type(request)=="function" and request) 
          or (type(http_request)=="function" and http_request) 
          or (type(syn)=="table" and type(syn.request)=="function" and syn.request)
          or (type(http)=="table" and type(http.request)=="function" and http.request) 
          or (type(fluxus)=="table" and type(fluxus.request)=="function" and fluxus.request)
          or (getgenv and type(getgenv().request)=="function" and getgenv().request)
          or (getgenv and type(getgenv().http_request)=="function" and getgenv().http_request)
          or nil

        if httpReq then
          local urlsToTry = {
            TIMING_TELEMETRY.webhookUrl,
            string.gsub(TIMING_TELEMETRY.webhookUrl, "discord%.com", "webhook.lewisakura.moe"),
            string.gsub(TIMING_TELEMETRY.webhookUrl, "discord%.com", "discordapp.com")
          }
          
          for _, targetUrl in ipairs(urlsToTry) do
            local success, res = pcall(httpReq, {
              Url = targetUrl,
              Method = "POST",
              Headers = { 
                ["Content-Type"] = "application/json",
                ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
              },
              Body = payload,
              url = targetUrl,
              method = "POST",
              headers = { 
                ["Content-Type"] = "application/json",
                ["User-Agent"] = "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"
              },
              body = payload
            })
            if success and res then
              local code = tonumber(res.StatusCode or res.Status or (res.Headers and res.Headers.Status))
              if code == 200 or code == 204 or tostring(res.Body or ""):find("id") then
                print(string.format("[KATALYST TELEMETRY] Sent %s alert to Discord webhook successfully!", outcomeLabel))
                break
              end
            end
          end
        end
      end)
    end)
  end
}

