function PARRY_LOGS_UI.copyHistory()
  if #PARRY_LOGS_UI.history == 0 then
    G.noti("Telemetry", "No combat logs recorded yet to copy!", 2)
    return
  end
  local pingMs = 0
  pcall(function() pingMs = math.floor(game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()) end)
  local lines = {}
  table.insert(lines, "")
  table.insert(lines, string.format("KATALYST COMBAT TELEMETRY REPORT | Ping: %dms", pingMs))
  table.insert(lines, "")
  for _, item in ipairs(PARRY_LOGS_UI.history) do
    table.insert(lines, item)
  end
  table.insert(lines, "")
  local fullText = table.concat(lines, "\n")
  if type(setclipboard) == "function" then
    setclipboard(fullText)
    G.noti("Telemetry Copied", "Combat telemetry report copied to clipboard!", 3)
  else
    print("\n" .. fullText .. "\n")
    G.noti("Telemetry Printed", "Printed telemetry report to developer console!", 3)
  end
end

