function PARRY_LOGS_UI.add(text, act, isMantra)
  if not S.parryLogs then return end
  if S.parryLogsMantraOnly and isMantra == false then return end
  
  if not PARRY_LOGS_UI.container then PARRY_LOGS_UI.init() end
  local sf = PARRY_LOGS_UI.container
  if not sf then return end
  table.insert(PARRY_LOGS_UI.history, tostring(text))
  while #PARRY_LOGS_UI.history > 80 do
    table.remove(PARRY_LOGS_UI.history, 1)
  end

  local card = Instance.new("Frame")
  card.BackgroundColor3 = Color3.fromRGB(18, 18, 22)
  card.BackgroundTransparency = 0.12
  card.BorderSizePixel = 1
  card.BorderColor3 = Color3.fromRGB(48, 52, 62)
  card.AutomaticSize = Enum.AutomaticSize.X
  card.Size = UDim2.new(0, 0, 0, 22)
  G.mkC(card, 3)
  
  local padding = Instance.new("UIPadding")
  padding.PaddingLeft = UDim.new(0, 6)
  padding.PaddingRight = UDim.new(0, 6)
  padding.PaddingTop = UDim.new(0, 2)
  padding.PaddingBottom = UDim.new(0, 2)
  padding.Parent = card
  
  local lbl = Instance.new("TextLabel")
  lbl.AutomaticSize = Enum.AutomaticSize.X
  lbl.Size = UDim2.new(0, 0, 1, 0)
  lbl.BackgroundTransparency = 1
  lbl.Font = Enum.Font.Code
  lbl.TextSize = 12
  lbl.TextColor3 = Color3.fromRGB(240, 242, 245)
  lbl.TextXAlignment = Enum.TextXAlignment.Left
  lbl.TextYAlignment = Enum.TextYAlignment.Center
  lbl.Text = tostring(text)
  lbl.Parent = card

  local str = tostring(text)
  if str:find("MOD DETECTED") or str:find("VOIDWALKER") or str:find("PROJECTILE DEFENSE") or str:find("RING SPOOF") or str:find("SECURITY ALERT") then
    card.BorderColor3 = Color3.fromRGB(0, 140, 255)
    lbl.TextColor3 = Color3.fromRGB(80, 200, 255)
  elseif str:find("MANTRA ATTEMPT") or str:find("MANTRA DETECTED") or str:find("MANTRA") then
    card.BorderColor3 = Color3.fromRGB(180, 100, 255)
    lbl.TextColor3 = Color3.fromRGB(220, 160, 255)
  elseif str:find("PERFECT PARRY") or str:find("SUCCESS: PARRIED") or str:find("Sync: PERFECT") or str:find("PARRIED") or str:find("PARRY EXECUTED") then
    card.BorderColor3 = Color3.fromRGB(50, 220, 100)
    lbl.TextColor3 = Color3.fromRGB(120, 255, 160)
  elseif str:find("TIMING ISSUE") or str:find("TOO EARLY") or str:find("TOO LATE") or str:find("EARLY") or str:find("LATE") or str:find("DAMAGE") then
    card.BorderColor3 = Color3.fromRGB(255, 90, 60)
    lbl.TextColor3 = Color3.fromRGB(255, 120, 90)
  elseif str:find("NEEDS %+") or str:find("NEEDS %-") or str:find("SUGGESTED TIMING") or str:find("SUGGESTED BASE") or str:find("STUD DELAY") or str:find("FIX") or str:find("DPS") then
    card.BorderColor3 = Color3.fromRGB(60, 180, 255)
    lbl.TextColor3 = Color3.fromRGB(130, 220, 255)
  elseif str:find("AIRSWING") or str:find("FEINT") or str:find("BREAKER IGNORED") or str:find("FLICK") then
    card.BorderColor3 = Color3.fromRGB(255, 190, 40)
    lbl.TextColor3 = Color3.fromRGB(255, 220, 100)
  end

  if act and type(act) == "table" and act.onApply then
    local currentDelay = tonumber(act.initDelay) or 0.30
    local isDps = (act.isDps == true)
    local stepSmall = isDps and 0.002 or 0.010
    local stepBig = isDps and 0.005 or 0.025

    local hLayout = Instance.new("UIListLayout")
    hLayout.FillDirection = Enum.FillDirection.Horizontal
    hLayout.SortOrder = Enum.SortOrder.LayoutOrder
    hLayout.Padding = UDim.new(0, 4)
    hLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    hLayout.Parent = card
    lbl.LayoutOrder = 1

    local function makeNudge(txt, delta, ord)
      local b = Instance.new("TextButton")
      b.Text = txt
      b.AutomaticSize = Enum.AutomaticSize.X
      b.Size = UDim2.new(0, 0, 1, -2)
      b.BackgroundColor3 = Color3.fromRGB(24, 28, 40)
      b.BorderSizePixel = 1
      b.BorderColor3 = Color3.fromRGB(45, 55, 75)
      b.Font = Enum.Font.Code
      b.TextSize = 10
      b.TextColor3 = Color3.fromRGB(200, 215, 240)
      b.AutoButtonColor = false
      b.LayoutOrder = ord
      G.mkC(b, 3)
      local bP = Instance.new("UIPadding")
      bP.PaddingLeft = UDim.new(0, 4); bP.PaddingRight = UDim.new(0, 4); bP.Parent = b
      b.Parent = card
      return b
    end

    local m10 = makeNudge(isDps and "-.002" or "-10ms", -stepSmall, 2)

    local valBox = Instance.new("TextBox")
    valBox.Size = UDim2.new(0, isDps and 52 or 46, 1, -2)
    valBox.BackgroundColor3 = Color3.fromRGB(16, 20, 30)
    valBox.BorderSizePixel = 1
    valBox.BorderColor3 = Color3.fromRGB(60, 90, 130)
    valBox.Font = Enum.Font.Code
    valBox.TextSize = 10
    valBox.TextColor3 = Color3.fromRGB(100, 220, 255)
    valBox.ClearTextOnFocus = false
    valBox.Text = isDps and string.format("%.4fs", currentDelay) or string.format("%.3fs", currentDelay)
    valBox.LayoutOrder = 3
    G.mkC(valBox, 3)
    valBox.Parent = card

    local p10 = makeNudge(isDps and "+.002" or "+10ms", stepSmall, 4)

    local function refreshText()
      valBox.Text = isDps and string.format("%.4fs", currentDelay) or string.format("%.3fs", currentDelay)
    end

    m10.MouseButton1Click:Connect(function() currentDelay = math.max(0.005, currentDelay - stepSmall); refreshText() end)
    p10.MouseButton1Click:Connect(function() currentDelay = currentDelay + stepSmall; refreshText() end)

    valBox.FocusLost:Connect(function()
      local num = tonumber(string.match(valBox.Text, "[%d%.]+"))
      if num then currentDelay = math.max(0.005, num) end
      refreshText()
    end)

    local actBtn = Instance.new("TextButton")
    actBtn.Text = act.btnText or "Apply"
    actBtn.AutomaticSize = Enum.AutomaticSize.X
    actBtn.Size = UDim2.new(0, 0, 1, -2)
    actBtn.BackgroundColor3 = Color3.fromRGB(20, 40, 65)
    actBtn.BorderSizePixel = 1
    actBtn.BorderColor3 = Color3.fromRGB(70, 160, 255)
    actBtn.Font = Enum.Font.GothamBold
    actBtn.TextSize = 10
    actBtn.TextColor3 = Color3.fromRGB(150, 220, 255)
    actBtn.AutoButtonColor = false
    actBtn.LayoutOrder = 5
    G.mkC(actBtn, 3)

    local bPad = Instance.new("UIPadding")
    bPad.PaddingLeft = UDim.new(0, 6)
    bPad.PaddingRight = UDim.new(0, 6)
    bPad.Parent = actBtn

    actBtn.MouseButton1Click:Connect(function()
      local success = act.onApply(currentDelay)
      if success ~= false then
        actBtn.Text = "SAVED"
        actBtn.TextColor3 = Color3.fromRGB(100, 255, 140)
        actBtn.BorderColor3 = Color3.fromRGB(50, 220, 100)
        actBtn.BackgroundColor3 = Color3.fromRGB(15, 45, 25)
        G.noti("Timing Saved", string.format("Applied timing update for %s!", tostring(act.mantra or "Mantra")), 3)
      end
    end)
    actBtn.Parent = card
  end
  
  card.Parent = sf
  table.insert(PARRY_LOGS_UI.logs, card)
  
  while #PARRY_LOGS_UI.logs > 14 do
    local old = table.remove(PARRY_LOGS_UI.logs, 1)
    pcall(function() old:Destroy() end)
  end
  
  local lifetime = (act and 25) or 5.5
  task.delay(lifetime, function()
    if card and card.Parent then
      pcall(function()
        for i = 1, #PARRY_LOGS_UI.logs do
          if PARRY_LOGS_UI.logs[i] == card then
            table.remove(PARRY_LOGS_UI.logs, i)
            break
          end
        end
        card:Destroy()
      end)
    end
  end)
end

-- INNATE MOD DETECTOR & VOIDWALKER BOUNTY SCANNER
local INNATE_SECURITY = {
  active = false,
  playerAdded = nil,
  knownMods = {},
  knownVoidwalkers = {},
  groupStaffRanks = {
    [5212879] = 200,
    [1200769] = 1,   -- Roblox Staff
  }
}

function INNATE_SECURITY.checkPlayer(p)
  if not INNATE_SECURITY.active or not p or p == G.LP then return end
  
  if not INNATE_SECURITY.knownMods[p.UserId] then
    local isMod = false
    local roleName = "Moderator"
    
    pcall(function()
      for groupId, minRank in pairs(INNATE_SECURITY.groupStaffRanks) do
        local r = p:GetRankInGroup(groupId)
        if r and r >= minRank then
          isMod = true
          roleName = p:GetRoleInGroup(groupId) or "Staff"
          break
        end
      end
    end)
    
    if not isMod then
      local n = p.Name:lower()
      if n:find("mod_") or n:find("dev_") or n:find("admin_") then
        isMod = true
        roleName = "Suspected Staff"
      end
    end
    
    if isMod then
      INNATE_SECURITY.knownMods[p.UserId] = true
      pcall(function()
        PARRY_LOGS_UI.add(string.format("[MOD DETECTED] Staff/Admin '%s' (@%s | Role: %s) is in your server!", p.DisplayName, p.Name, tostring(roleName)))
        G.noti("MOD DETECTOR", "Staff member in server: " .. p.Name)
      end)
    end
  end
  
  if not INNATE_SECURITY.knownVoidwalkers[p.UserId] then
    local isHunting = false
    pcall(function()
      local bp = p:FindFirstChild("Backpack")
      local ch = p.Character
      local contract = (bp and bp:FindFirstChild("Talent:Voidwalker Contract")) or 
                       (ch and ch:FindFirstChild("Talent:Voidwalker Contract")) or
                       (bp and bp:FindFirstChild("Voidwalker Contract"))
      if contract then
        local targetAttr = contract:GetAttribute("Target") or contract:GetAttribute("TargetName") or contract:GetAttribute("TargetUserId")
        if targetAttr then
          if tostring(targetAttr) == tostring(G.LP.Name) or tostring(targetAttr) == tostring(G.LP.UserId) or tostring(targetAttr) == tostring(G.LP.DisplayName) then
            isHunting = true
          end
        else
          isHunting = true
        end
      end
    end)
    
    if isHunting then
      INNATE_SECURITY.knownVoidwalkers[p.UserId] = true
      pcall(function()
        PARRY_LOGS_UI.add(string.format("[VOIDWALKER BOUNTY ALERT] Player '%s' (@%s) holds an active Voidwalker Bounty targeting you!", p.DisplayName, p.Name))
        G.noti("VOIDWALKER ALERT", p.Name .. " is hunting you!")
      end)
    end
  end
end

function INNATE_SECURITY.start()
  if INNATE_SECURITY.active then return end
  INNATE_SECURITY.active = true
  pcall(function()
    for _, p in ipairs(G.Plrs:GetPlayers()) do
      INNATE_SECURITY.checkPlayer(p)
    end
    INNATE_SECURITY.playerAdded = G.Plrs.PlayerAdded:Connect(function(p)
      task.wait(1.5)
      if not INNATE_SECURITY.active then return end
      INNATE_SECURITY.checkPlayer(p)
    end)
    task.spawn(function()
      while INNATE_SECURITY.active do
        task.wait(10)
        if not INNATE_SECURITY.active then break end
        for _, p in ipairs(G.Plrs:GetPlayers()) do
          if p ~= G.LP then
            INNATE_SECURITY.checkPlayer(p)
          end
        end
      end
    end)
  end)
end

function INNATE_SECURITY.stop()
  INNATE_SECURITY.active = false
  if INNATE_SECURITY.playerAdded then
    INNATE_SECURITY.playerAdded:Disconnect()
    INNATE_SECURITY.playerAdded = nil
  end
end

task.spawn(INNATE_SECURITY.start)

local RING_SPOOF = {
  active = false,
  characterAdded = nil,
  hashModule = nil,
  oldSnap = nil,
  snapWrapper = nil,
  ownedRings = setmetatable({}, { __mode = "k" }),
  freestyler = false,
  konga = false,
}

local function applyOwnedRing(ch, name, enabled)
  local ring = ch:FindFirstChild(name)
  if enabled then
    if not ring then
      ring = Instance.new("Folder")
      ring.Name = name
      ring.Parent = ch
      RING_SPOOF.ownedRings[ring] = true
    end
  elseif ring and RING_SPOOF.ownedRings[ring] then
    RING_SPOOF.ownedRings[ring] = nil
    ring:Destroy()
  end
end

function RING_SPOOF.apply(ch)
  if not ch then return end
  pcall(function()
    applyOwnedRing(ch, "Ring:Freestyler's Band", S.freestylersSpoof or RING_SPOOF.freestyler)
    applyOwnedRing(ch, "Ring:Konga's Clutch Ring", S.kongaRingSpoof or RING_SPOOF.konga)
  end)
end

function RING_SPOOF.start()
  if RING_SPOOF.active then return end
  RING_SPOOF.active = true
  pcall(function()
    RING_SPOOF.characterAdded = G.LP.CharacterAdded:Connect(function(ch)
      task.wait(0.5)
      if RING_SPOOF.active then RING_SPOOF.apply(ch) end
    end)
    if G.LP.Character then RING_SPOOF.apply(G.LP.Character) end
  end)
  pcall(function()
    local hashMod = G.RepS:FindFirstChild("CharacterHashes")
    if not hashMod then return end
    local realModule = require(hashMod)
    if not realModule or type(realModule.Snap) ~= "function" then return end
    local oldSnap = realModule.Snap
    RING_SPOOF.hashModule = realModule
    RING_SPOOF.oldSnap = oldSnap
    RING_SPOOF.snapWrapper = function(character, ...)
      local result = oldSnap(character, ...)
      if RING_SPOOF.active and type(result) == "table" and character == (G.LP and G.LP.Character) then
        if S.freestylersSpoof then result["Freestyler's Band"] = true end
        if S.kongaRingSpoof then result["Konga's Clutch Ring"] = true end
      end
      return result
    end
    realModule.Snap = RING_SPOOF.snapWrapper
  end)
end

function RING_SPOOF.stop()
  RING_SPOOF.active = false
  if RING_SPOOF.characterAdded then
    RING_SPOOF.characterAdded:Disconnect()
    RING_SPOOF.characterAdded = nil
  end
  if RING_SPOOF.hashModule and RING_SPOOF.oldSnap and RING_SPOOF.hashModule.Snap == RING_SPOOF.snapWrapper then
    RING_SPOOF.hashModule.Snap = RING_SPOOF.oldSnap
  end
  RING_SPOOF.hashModule = nil
  RING_SPOOF.oldSnap = nil
  RING_SPOOF.snapWrapper = nil
  for ring in pairs(RING_SPOOF.ownedRings) do
    pcall(function()
      if ring and ring.Parent then ring:Destroy() end
    end)
  end
  table.clear(RING_SPOOF.ownedRings)
end

RING_SPOOF.start()

local NON_PROJECTILE_KEYWORDS = {
  "dirt", "newdirt", "dust", "footstep", "blood", "debris", "smoke", "sound",
  "particle", "emitter", "mesh", "decal", "light", "spark", "aura", "ground",
  "rock", "pebble", "cloud", "leaf", "grass", "step", "water", "splash", "hitfx",
  "fx", "trail", "ring", "shockwave", "fog", "bubble", "shadow", "wind", "glow",
  "flash", "texture", "billboard", "attachment", "camera", "terrain", "part"
}

local KNOWN_PROJECTILES = {
  ["ArcBeam"] = true, ["BloodCross"] = true, ["GrandJavelin"] = true,
  ["IceLance"] = true, ["IceSpike"] = true, ["IceShard"] = true,
  ["StoneDart"] = true, ["WindBlade"] = true, ["ShadowGun"] = true,
  ["GaleDart"] = true, ["Javelin"] = true, ["Throw"] = true,
  ["Bullet"] = true, ["Fireball"] = true, ["Spear"] = true,
  ["Arrow"] = true, ["Kunai"] = true, ["Lightning"] = true,
  ["Meteor"] = true, ["Thunder"] = true, ["Flame"] = true
}

-- Forward declaration of AUTO_PARRY to prevent scope nil indexing
local AUTO_PARRY = { active = false, initialized = false }

local PROJECTILE_DEFENSE = {
  active = true,
  lastParryTime = 0,
  initialized = false,
  connections = {},
  folderConnections = {},
  seenProjectiles = setmetatable({}, { __mode = "k" }),
  projectileSequence = 0,
}

local function ownConnection(owner, connection)
  if connection then
    owner.connections[#owner.connections + 1] = connection
  end
  return connection
end

local function disconnectOwnedConnections(owner)
  for i = #owner.connections, 1, -1 do
    local connection = owner.connections[i]
    if connection then
      pcall(connection.Disconnect, connection)
    end
    owner.connections[i] = nil
  end
end

local function isBlacklistedName(name)
  local lowerName = string.lower(tostring(name or ""))
  if lowerName == "" then return false end
  for _, kw in ipairs(NON_PROJECTILE_KEYWORDS) do
    if string.find(lowerName, kw) then return true end
  end
  return false
end

local function isLegitProjectile(part)
  if not part or not part:IsA("BasePart") then return false end
  local pName = tostring(part.Name)
  local parentName = part.Parent and tostring(part.Parent.Name) or ""
  local grandParentName = (part.Parent and part.Parent.Parent) and tostring(part.Parent.Parent.Name) or ""

  if isBlacklistedName(pName) or isBlacklistedName(parentName) or isBlacklistedName(grandParentName) then
    return false
  end

  for kName in pairs(KNOWN_PROJECTILES) do
    if pName:find(kName) or parentName:find(kName) or grandParentName:find(kName) then
      return true
    end
  end

  if part:GetAttribute("Damage") or part:GetAttribute("Offensive") or part:GetAttribute("Projectile") then
    return true
  end

  return false
end

local function getProjectile(part)
  local projectile = part
  local parent = part.Parent
  while parent do
    if parent.Name == "Thrown" or parent.Name == "Projectiles" then
      return projectile
    end
    projectile = parent
    parent = parent.Parent
  end
  return part
end

function PROJECTILE_DEFENSE.checkPart(part)
  if not AUTO_PARRY.active then return end
  if not part or typeof(part) ~= "Instance" or not part:IsA("BasePart") then return end

  local myChar = G.LP and G.LP.Character
  if not myChar or part:IsDescendantOf(myChar) then return end

  if not isLegitProjectile(part) then return end

  local projectile = getProjectile(part)
  if PROJECTILE_DEFENSE.seenProjectiles[projectile] then return end
  PROJECTILE_DEFENSE.projectileSequence = PROJECTILE_DEFENSE.projectileSequence + 1
  local projectileId = PROJECTILE_DEFENSE.projectileSequence
  PROJECTILE_DEFENSE.seenProjectiles[projectile] = projectileId

  local pName = tostring(part.Name)
  task.spawn(function()
    pcall(function()
      local hrp = myChar:FindFirstChild("HumanoidRootPart")
      if not hrp then return end
      
      local startT = os.clock()
      while AUTO_PARRY.active and (os.clock() - startT < 2.5) do
        local ok, done = pcall(function()
          if not part or not part.Parent or not hrp or not hrp.Parent then return true end
          local pPos = part.Position
          local myPos = hrp.Position
          local dist = (pPos - myPos).Magnitude
          local vel = Vector3.new(0, 0, 0)
          pcall(function()
            vel = part.AssemblyLinearVelocity or part.Velocity or Vector3.new(0, 0, 0)
          end)
          local speed = vel.Magnitude
          
          if dist <= 28 and dist >= 3.5 and speed >= 35 then
            local toPlayer = (myPos - pPos).Unit
            local headingDot = (speed > 0.01) and vel.Unit:Dot(toPlayer) or 0
            
            if headingDot > 0.70 and (os.clock() - PROJECTILE_DEFENSE.lastParryTime > 0.35) then
              local parried = AUTO_PARRY.requestParry("ProjectileDefense:" .. projectileId)
              if parried then
                PROJECTILE_DEFENSE.lastParryTime = os.clock()
                if S.parryLogs and PARRY_LOGS_UI and PARRY_LOGS_UI.add then
                  PARRY_LOGS_UI.add(string.format("[PROJECTILE DEFENSE] Parried incoming projectile '%s' (Dist: %.1fm | Spd: %.0f)", tostring(pName), dist, speed))
                end
              elseif canDodge and canDodge() and execDodge then
                execDodge()
                if S.parryLogs and PARRY_LOGS_UI and PARRY_LOGS_UI.add then
                  PARRY_LOGS_UI.add(string.format("[PROJECTILE DEFENSE] [SMART ROLL] Parry on CD -> Dodged incoming projectile '%s' (Dist: %.1fm | Spd: %.0f)", tostring(pName), dist, speed))
                end
              end
              return true
            end
          end
          return false
        end)
        
        if not ok or done then break end
        task.wait(0.02)
      end
    end)
  end)
end

function PROJECTILE_DEFENSE.init()
  if PROJECTILE_DEFENSE.initialized then return end
  PROJECTILE_DEFENSE.initialized = true
  PROJECTILE_DEFENSE.lastParryTime = 0
  PROJECTILE_DEFENSE.seenProjectiles = setmetatable({}, { __mode = "k" })
  PROJECTILE_DEFENSE.projectileSequence = 0

  local function watchFolder(folder, includeDescendants)
    if not folder or PROJECTILE_DEFENSE.folderConnections[folder] then return end
    local connection = folder.ChildAdded:Connect(function(child)
      if child:IsA("BasePart") then PROJECTILE_DEFENSE.checkPart(child) end
      if includeDescendants then
        for _, descendant in ipairs(child:GetDescendants()) do
          if descendant:IsA("BasePart") then PROJECTILE_DEFENSE.checkPart(descendant) end
        end
      end
    end)
    PROJECTILE_DEFENSE.folderConnections[folder] = connection
    ownConnection(PROJECTILE_DEFENSE, connection)
  end

  local ok = pcall(function()
    local thrown = workspace:FindFirstChild("Thrown")
    if thrown then watchFolder(thrown, true) end

    local projFolder = workspace:FindFirstChild("Projectiles")
    if projFolder then watchFolder(projFolder, true) end

    ownConnection(PROJECTILE_DEFENSE, workspace.ChildAdded:Connect(function(child)
      if child.Name == "Thrown" or child.Name == "Projectiles" then
        watchFolder(child, false)
      end
    end))
  end)
  if not ok then PROJECTILE_DEFENSE.stop() end
end

function PROJECTILE_DEFENSE.stop()
  disconnectOwnedConnections(PROJECTILE_DEFENSE)
  PROJECTILE_DEFENSE.folderConnections = {}
  PROJECTILE_DEFENSE.lastParryTime = 0
  PROJECTILE_DEFENSE.seenProjectiles = setmetatable({}, { __mode = "k" })
  PROJECTILE_DEFENSE.projectileSequence = 0
  PROJECTILE_DEFENSE.initialized = false
end
task.spawn(PROJECTILE_DEFENSE.init)

function PARRY_LOGS_UI.setVisible(v)
  if not PARRY_LOGS_UI.gui then PARRY_LOGS_UI.init() end
  if PARRY_LOGS_UI.gui then PARRY_LOGS_UI.gui.Enabled = v end
end

local PARRY_DIAGNOSTICS = {
  attempts = {},
  initialized = false,
  connections = {},
  soundConnections = {},
  characterConnections = {},
}

local function getLocalCombatState()
  local char = G.LP and G.LP.Character
  local hum = char and char:FindFirstChildOfClass("Humanoid")
  local hp = hum and hum.Health or 100
  local postPct = 0
  pcall(function()
    if char then
      local bm = char:FindFirstChild("BreakMeter") or char:FindFirstChild("Posture") or (char:FindFirstChild("Values") and char.Values:FindFirstChild("BreakMeter"))
      if bm and (bm:IsA("DoubleConstrainedValue") or bm:IsA("NumberValue") or bm:IsA("IntValue")) then
        local cur = tonumber(bm.Value) or 0
        local maxV = tonumber(bm.MaxValue) or 100
        postPct = cur / math.max(1, maxV)
      else
        local attrBreak = char:GetAttribute("BreakMeter") or char:GetAttribute("Posture") or char:GetAttribute("CurrentPosture")
        if attrBreak and type(attrBreak) == "number" then
          local maxAttr = char:GetAttribute("MaxPosture") or char:GetAttribute("MaxBreakMeter") or 100
          postPct = attrBreak / math.max(1, maxAttr)
        end
      end
    end
  end)
  return hp, postPct
end

function PARRY_DIAGNOSTICS.registerAttempt(mName, animId, baseDelay, calculatedDelay, dist, dps, targetModel, wt, wc, fadeDelta, spd, len, tp, priName, reason, filterSummary)
  local hp, post = getLocalCombatState()
  local attempt = {
    mantra = mName,
    animId = animId,
    baseDelay = baseDelay,
    calculatedDelay = calculatedDelay,
    dist = dist,
    dps = dps,
    target = targetModel,
    castTime = os.clock(),
    fireTime = os.clock() + calculatedDelay,
    startHp = hp,
    startPost = post,
    resolved = false,
    wt = wt or 1,
    wc = wc or 0,
    fadeDelta = fadeDelta or 0,
    spd = spd or 1,
    len = len or 0,
    tp = tp or 0,
    priName = priName or "Action",
    reason = reason or "Real Attack In Range",
    filterSummary = filterSummary or nil
  }
  table.insert(PARRY_DIAGNOSTICS.attempts, attempt)
  while #PARRY_DIAGNOSTICS.attempts > 16 do
    table.remove(PARRY_DIAGNOSTICS.attempts, 1)
  end
  return attempt
end

function PARRY_DIAGNOSTICS.findMatchingAttempt(sourceInstance)
  local now = os.clock()
  local myChar = G.LP and G.LP.Character
  local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")

  if sourceInstance and typeof(sourceInstance) == "Instance" then
    for i = #PARRY_DIAGNOSTICS.attempts, 1, -1 do
      local a = PARRY_DIAGNOSTICS.attempts[i]
      if not a.resolved and (a.target == sourceInstance or sourceInstance:IsDescendantOf(a.target)) then
        return a
      end
    end
  end

  for i = #PARRY_DIAGNOSTICS.attempts, 1, -1 do
    local a = PARRY_DIAGNOSTICS.attempts[i]
    if not a.resolved and math.abs(now - a.fireTime) < 0.45 then
      return a
    end
  end

  return nil
end

function PARRY_DIAGNOSTICS.init()
  if PARRY_DIAGNOSTICS.initialized then return end
  PARRY_DIAGNOSTICS.initialized = true

  local function handleCombatOutcome(outcomeType, sndOrSource, specificAtt)
    local att = specificAtt or PARRY_DIAGNOSTICS.findMatchingAttempt(sndOrSource)
    if not att or att.resolved then return end
    local now = os.clock()
    local dtFire = now - att.fireTime

    local uis = game:GetService("UserInputService")
    local manualBlock = uis:IsKeyDown(Enum.KeyCode.F) or uis:IsKeyDown(Enum.KeyCode.ButtonL1)

    if outcomeType == "PARRY" then
      att.resolved = true
      local hitDeltaMs = math.floor(dtFire * 1000)
      local infoStr = string.format("WT: %.2f | WC: %.2f | Fade: %.2f | Spd: %.2fx | Len: %.2fs | TP: %.2fs | Pri: %s | Dist: %.1fm",
        att.wt or 1, att.wc or 0, att.fadeDelta or 0, att.spd or 1, att.len or 0, att.tp or 0, tostring(att.priName or "Action"), att.dist or 0)
      local reasonStr = att.reason and (" | Reason: " .. tostring(att.reason)) or ""
      PARRY_LOGS_UI.add(string.format(">> [SUCCESS: PARRIED %s%s | Hit Frame: %dms | %s | Sync: PERFECT]", tostring(att.mantra), reasonStr, hitDeltaMs, infoStr), nil, true)
      if att.filterSummary then
        PARRY_LOGS_UI.add(string.format(">> [FILTERS: %s]", tostring(att.filterSummary)), nil, true)
      end
      if att.dist and att.dist >= 8 then
        PARRY_LOGS_UI.add(string.format(">> [STUD DELAY SYNC @ %.1fm: Travel time %.3fs / DPS %.4fs is PERFECT]", att.dist, (now - att.castTime), att.dps or 0))
      end
      return
    end

    if outcomeType == "BLOCK" then
      if manualBlock then return end
      att.resolved = true
      local pCenter = 0.08
      local earlyMs = math.max(15, math.floor((dtFire - pCenter) * 1000))
      if earlyMs > 450 then earlyMs = 45 end -- clamp anomaly spikes
      local newDelay = att.baseDelay + (earlyMs / 1000)
      local infoStr = string.format("WT: %.2f | WC: %.2f | Fade: %.2f | Spd: %.2fx | Pri: %s",
        att.wt or 1, att.wc or 0, att.fadeDelta or 0, att.spd or 1, tostring(att.priName or "Action"))

      local reasonStr = att.reason and (" | Reason: " .. tostring(att.reason)) or ""
      PARRY_LOGS_UI.add(string.format(">> [TIMING ISSUE: %s PARRIED %dms TOO EARLY -> HIT BLOCK%s | %s]", tostring(att.mantra), earlyMs, reasonStr, infoStr))
      local msPerStud = (att.dist and att.dist >= 8) and (earlyMs / att.dist) or nil
      local newDps = msPerStud and ((att.dps or 0) + ((earlyMs / 1000) / att.dist)) or nil
      
      TIMING_TELEMETRY.sendFailure("EARLY", att, earlyMs, newDelay, msPerStud, newDps)

      PARRY_LOGS_UI.add(string.format(">> [SUGGESTED BASE: NEEDS +%dms DELAY (%.3fs -> %.3fs)]", earlyMs, att.baseDelay, newDelay), {
        initDelay = newDelay,
        mantra = att.mantra,
        onApply = function(customVal)
          local finalDelay = tonumber(customVal) or newDelay
          local rawId = string.match(tostring(att.animId or ""), "%d+")
          local fullKey = rawId and ("rbxassetid://" .. rawId) or tostring(att.animId)
          
          local function applyToKey(k)
            if not k then return end
            if TIMINGS[k] and type(TIMINGS[k]) == "table" and TIMINGS[k][1] then
              TIMINGS[k][1].delay = finalDelay
            else
              TIMINGS[k] = {{ action = "Parry", delay = finalDelay }}
            end
            LEARNED_TIMINGS[k] = TIMINGS[k]
          end

          applyToKey(fullKey)
          if rawId then applyToKey(rawId) end
          applyToKey(tostring(att.animId))

          AUTO_PARRY.refreshTimings()
          pcall(G.saveTimings)
          return true
        end
      })

      if att.dist and att.dist >= 8 and newDps then
        PARRY_LOGS_UI.add(string.format(">> [STUD DELAY @ %.1fm: NEEDS +%.1fms/stud (Suggest DPS: %.4fs)]", att.dist, msPerStud, newDps), {
          initDelay = newDps,
          isDps = true,
          mantra = att.mantra,
          onApply = function(customDps)
            local finalDps = tonumber(customDps) or newDps
            local animKey = tostring(att.animId)
            MANTRA_STUD_DELAYS[animKey] = finalDps
            AUTO_PARRY.refreshTimings()
            G.saveTimings()
            return true
          end
        })
      end
      return
    end

    if outcomeType == "DAMAGE" then
      att.resolved = true
      local lateMs = math.max(25, math.floor(((now - att.castTime) - att.calculatedDelay) * 1000))
      if lateMs > 500 then lateMs = 45 end
      local newDelay = math.max(0.02, att.baseDelay - (lateMs / 1000))

      local infoStr = string.format("WT: %.2f | WC: %.2f | Fade: %.2f | Spd: %.2fx | Pri: %s",
        att.wt or 1, att.wc or 0, att.fadeDelta or 0, att.spd or 1, tostring(att.priName or "Action"))
      local reasonStr = att.reason and (" | Reason: " .. tostring(att.reason)) or ""

      PARRY_LOGS_UI.add(string.format(">> [TIMING ISSUE: %s PARRIED %dms TOO LATE -> TOOK DAMAGE%s | %s]", tostring(att.mantra), lateMs, reasonStr, infoStr))

      local msPerStud = (att.dist and att.dist >= 8) and (lateMs / att.dist) or nil
      local newDps = msPerStud and math.max(0, (att.dps or 0) - ((lateMs / 1000) / att.dist)) or nil
      TIMING_TELEMETRY.sendFailure("LATE", att, -lateMs, newDelay, msPerStud, newDps)

      PARRY_LOGS_UI.add(string.format(">> [SUGGESTED BASE: NEEDS -%dms DELAY (%.3fs -> %.3fs)]", lateMs, att.baseDelay, newDelay), {
        initDelay = newDelay,
        mantra = att.mantra,
        onApply = function(customVal)
          local finalDelay = tonumber(customVal) or newDelay
          local rawId = string.match(tostring(att.animId or ""), "%d+")
          local fullKey = rawId and ("rbxassetid://" .. rawId) or tostring(att.animId)
          
          local function applyToKey(k)
            if not k then return end
            if TIMINGS[k] and type(TIMINGS[k]) == "table" and TIMINGS[k][1] then
              TIMINGS[k][1].delay = finalDelay
            else
              TIMINGS[k] = {{ action = "Parry", delay = finalDelay }}
            end
            LEARNED_TIMINGS[k] = TIMINGS[k]
          end

          applyToKey(fullKey)
          if rawId then applyToKey(rawId) end
          applyToKey(tostring(att.animId))

          AUTO_PARRY.refreshTimings()
          pcall(G.saveTimings)
          return true
        end
      })
      return
    end
  end

  ownConnection(PARRY_DIAGNOSTICS, G.RS.Heartbeat:Connect(function()
    if #PARRY_DIAGNOSTICS.attempts == 0 then return end
    local now = os.clock()
    local curHp, curPost = getLocalCombatState()

    for i = #PARRY_DIAGNOSTICS.attempts, 1, -1 do
      local att = PARRY_DIAGNOSTICS.attempts[i]
      if not att.resolved then
        local timeSinceCast = now - att.castTime
        local timeSinceFire = now - att.fireTime

        -- Check damage ONLY during the relevant impact window [-0.05s to +0.35s from fireTime]
        if timeSinceFire >= -0.05 and timeSinceFire <= 0.35 then
          if curHp < (att.startHp - 0.5) then
            handleCombatOutcome("DAMAGE", nil, att)
          elseif (curPost > (att.startPost + 0.02) or curPost >= 0.99) and curHp >= (att.startHp - 0.5) and timeSinceFire > 0.03 then
            handleCombatOutcome("BLOCK", nil, att)
          end
        end

        -- Clean expiry if nothing occurred and impact window has passed
        if timeSinceFire > 0.40 or timeSinceCast >= 2.5 then
          att.resolved = true
        end
      end
    end
  end))

  local function inspectSound(snd)
    if not snd:IsA("Sound") then return end
    local sName = snd.Name:lower()
    local sId = tostring(snd.SoundId):lower()

    if sName:find("parry") or sId:find("parry") or sName:find("perfect") or sName:find("deflect") or sName:find("clash") 
      or sId:find("9114223180") or sId:find("9114223631") or sId:find("9114224097") or sId:find("9114224536") or sId:find("9114225032") then
      handleCombatOutcome("PARRY", snd)
    elseif sName:find("block") or sName:find("shield") or sName:find("guard") or sName:find("defend") or sName:find("absorb") or sName:find("metal") or sName:find("clank") 
      or sId:find("block") or sId:find("shield") or sId:find("9114221760") or sId:find("9114222146") or sId:find("9114222625") then
      handleCombatOutcome("BLOCK", snd)
    elseif sName:find("flesh") or sName:find("slash") or sName:find("blunt") or sName:find("stab") or sName:find("hit") or sName:find("impact") or sName:find("gore") or sName:find("blood") or sName:find("hurt") then
      handleCombatOutcome("DAMAGE", snd)
    end
  end

  local function hookSound(sound)
    if not sound:IsA("Sound") or PARRY_DIAGNOSTICS.soundConnections[sound] then return end
    local connection = sound.Played:Connect(function() inspectSound(sound) end)
    PARRY_DIAGNOSTICS.soundConnections[sound] = connection
    ownConnection(PARRY_DIAGNOSTICS, connection)
  end

  -- Global Sound Listeners
  ownConnection(PARRY_DIAGNOSTICS, G.WS.DescendantAdded:Connect(function(descendant)
    if descendant:IsA("Sound") then
      inspectSound(descendant)
      hookSound(descendant)
    end
  end))

  for _, descendant in ipairs(G.WS:GetDescendants()) do
    if descendant:IsA("Sound") then
      pcall(hookSound, descendant)
    end
  end

  local function hookCharacter(char)
    if not char or PARRY_DIAGNOSTICS.characterConnections[char] then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end

    PARRY_DIAGNOSTICS.characterConnections[char] = true
    local lastHp = hum.Health
    ownConnection(PARRY_DIAGNOSTICS, hum.HealthChanged:Connect(function(newHp)
      if newHp < lastHp then
        handleCombatOutcome("DAMAGE", char)
      end
      lastHp = newHp
    end))

    ownConnection(PARRY_DIAGNOSTICS, char.DescendantAdded:Connect(function(child)
      local cName = child.Name:lower()
      if cName:find("parry") or cName:find("deflect") then
        handleCombatOutcome("PARRY", child)
      elseif cName:find("block") or cName:find("shield") or cName:find("spark") or cName:find("guard") then
        handleCombatOutcome("BLOCK", child)
      elseif cName:find("blood") or cName:find("flesh") or cName:find("slash") or cName:find("damage") then
        handleCombatOutcome("DAMAGE", child)
      end
    end))
  end

  if G.LP and G.LP.Character then hookCharacter(G.LP.Character) end
  if G.LP then
    ownConnection(PARRY_DIAGNOSTICS, G.LP.CharacterAdded:Connect(hookCharacter))
  end
end

function PARRY_DIAGNOSTICS.stop()
  disconnectOwnedConnections(PARRY_DIAGNOSTICS)
  PARRY_DIAGNOSTICS.soundConnections = {}
  PARRY_DIAGNOSTICS.characterConnections = {}
  table.clear(PARRY_DIAGNOSTICS.attempts)
  PARRY_DIAGNOSTICS.initialized = false
end
PARRY_DIAGNOSTICS.init()

local HITBOX_VISUALIZER = {
  active = false,
  conn = nil,
  threatRings = {},
  projHighlights = {},
  weaponHighlights = {}
}

do
  local function findWeaponPart(model)
    if not model then return nil end
    for _, child in ipairs(model:GetChildren()) do
      if child:IsA("Tool") or child.Name:lower():find("weapon") or child.Name:lower():find("sword") or child.Name:lower():find("spear") or child.Name:lower():find("axe") or child.Name:lower():find("dagger") or child.Name:lower():find("blade") then
        local h = child:FindFirstChild("Handle") or child:FindFirstChildWhichIsA("BasePart")
        if h then return h end
      end
    end
    return model:FindFirstChild("RightHand") or model:FindFirstChild("Right Arm") or model:FindFirstChild("RightArm")
  end

  function HITBOX_VISUALIZER.draw(targetModel, radius, hitData, isMantra, attackName, animTrack)
    if not targetModel then return end
    local ehrp = targetModel:FindFirstChild("HumanoidRootPart")
    if not ehrp then return end

    local lp = G.LP and G.LP.Character
    if lp and targetModel == lp then return end

    local aName = tostring(attackName or "Combat Attack")
    local rad = tonumber(radius) or 10
    local baseDelay = (hitData and hitData.delay) or 0.25

    -- Determine threat styling
    local color = Color3.fromRGB(255, 45, 45) -- Melee Red
    local tag = "[M1 / MELEE]"
    local isCrit = aName:lower():find("crit") or aName:lower():find("heavy")
    local isProjectile = aName:lower():find("proj") or aName:lower():find("arrow") or aName:lower():find("bullet") or aName:lower():find("beam")

    if isMantra then
      color = Color3.fromRGB(180, 50, 255) -- Mantra Purple / Neon Violet
      tag = "[MANTRA AOE]"
    elseif isCrit then
      color = Color3.fromRGB(255, 140, 20) -- Critical Orange / Amber
      tag = "[HEAVY CRITICAL]"
    elseif isProjectile then
      color = Color3.fromRGB(0, 225, 255) -- Projectile Cyan
      tag = "[PROJECTILE THREAT]"
    end

    local forwardOffset = isMantra and 0 or (rad * 0.45)
    local boxSize = isMantra and Vector3.new(rad * 2, rad * 1.5, rad * 2) or Vector3.new(rad * 1.2, 5.5, rad * 1.4)

    local reachBox = Instance.new("BoxHandleAdornment")
    reachBox.Name = "AttackHitbox_Box"
    reachBox.Size = boxSize
    reachBox.CFrame = CFrame.new(0, 0, -forwardOffset)
    reachBox.Color3 = color
    reachBox.Transparency = 0.45
    reachBox.AlwaysOnTop = true
    reachBox.ZIndex = 6
    reachBox.Adornee = ehrp
    pcall(function() reachBox.Parent = game:GetService("CoreGui") or workspace end)

    local sphere = Instance.new("SphereHandleAdornment")
    sphere.Name = "AttackHitbox_Sphere"
    sphere.Radius = isMantra and rad or (rad * 0.6)
    sphere.CFrame = CFrame.new(0, 0, -forwardOffset)
    sphere.Color3 = color
    sphere.Transparency = 0.60
    sphere.AlwaysOnTop = true
    sphere.ZIndex = 5
    sphere.Adornee = ehrp
    pcall(function() sphere.Parent = game:GetService("CoreGui") or workspace end)

    local groundRing = Instance.new("CylinderHandleAdornment")
    groundRing.Name = "AttackHitbox_GroundRing"
    groundRing.Radius = rad
    groundRing.Height = 0.3
    groundRing.CFrame = CFrame.Angles(math.rad(90), 0, 0) * CFrame.new(0, 0, 2.8)
    groundRing.Color3 = color
    groundRing.Transparency = 0.4
    groundRing.AlwaysOnTop = true
    groundRing.ZIndex = 4
    groundRing.Adornee = ehrp
    pcall(function() groundRing.Parent = game:GetService("CoreGui") or workspace end)

    local weaponPart = findWeaponPart(targetModel)
    local weaponAdorn = nil
    if weaponPart then
      weaponAdorn = Instance.new("BoxHandleAdornment")
      weaponAdorn.Name = "WeaponHitbox_Glow"
      weaponAdorn.Size = weaponPart.Size + Vector3.new(0.3, 0.3, 0.3)
      weaponAdorn.Color3 = color
      weaponAdorn.Transparency = 0.3
      weaponAdorn.AlwaysOnTop = true
      weaponAdorn.ZIndex = 7
      weaponAdorn.Adornee = weaponPart
      pcall(function() weaponAdorn.Parent = game:GetService("CoreGui") or workspace end)
    end

    local bb = Instance.new("BillboardGui")
    bb.Name = "AttackHitbox_Billboard"
    bb.Size = UDim2.new(0, 160, 0, 36)
    bb.StudsOffset = Vector3.new(0, ehrp.Size.Y + 2.4, 0)
    bb.AlwaysOnTop = true
    bb.Adornee = ehrp
    pcall(function() bb.Parent = game:GetService("CoreGui") or workspace end)

    local card = Instance.new("Frame", bb)
    card.Size = UDim2.new(1, 0, 1, 0)
    card.BackgroundColor3 = Color3.fromRGB(15, 10, 22)
    card.BackgroundTransparency = 0.25
    card.BorderSizePixel = 0
    local corner = Instance.new("UICorner", card)
    corner.CornerRadius = UDim.new(0, 4)
    local stroke = Instance.new("UIStroke", card)
    stroke.Color = color
    stroke.Thickness = 1.5

    local titleLbl = Instance.new("TextLabel", card)
    titleLbl.Size = UDim2.new(1, 0, 0, 18)
    titleLbl.BackgroundTransparency = 1
    titleLbl.Text = string.format("%s %s", tag, aName)
    titleLbl.TextColor3 = color
    titleLbl.Font = Enum.Font.GothamBold
    titleLbl.TextSize = 10
    titleLbl.TextTruncate = Enum.TextTruncate.AtEnd

    local subLbl = Instance.new("TextLabel", card)
    subLbl.Size = UDim2.new(1, 0, 0, 14)
    subLbl.Position = UDim2.new(0, 0, 0, 18)
    subLbl.BackgroundTransparency = 1
    subLbl.Text = string.format("Reach: %.1f studs | Time: %.2fs", rad, baseDelay)
    subLbl.TextColor3 = Color3.fromRGB(220, 220, 240)
    subLbl.Font = Enum.Font.Gotham
    subLbl.TextSize = 9

    local duration = math.clamp(baseDelay + 0.40, 0.45, 2.5)

    task.delay(duration, function()
      pcall(function()
        if reachBox then reachBox:Destroy() end
        if sphere then sphere:Destroy() end
        if groundRing then groundRing:Destroy() end
        if weaponAdorn then weaponAdorn:Destroy() end
        if bb then bb:Destroy() end
      end)
    end)
  end

  function HITBOX_VISUALIZER.en()
    if HITBOX_VISUALIZER.active then return end
    HITBOX_VISUALIZER.active = true
    S.hitboxVis = true

    -- Real-time Threat & Projectile Hitbox Scanner
    HITBOX_VISUALIZER.conn = G.RS.Heartbeat:Connect(function()
      if not S.hitboxVis then return end
      local lp = G.LP and G.LP.Character
      local myHrp = lp and lp:FindFirstChild("HumanoidRootPart")
      if not myHrp then return end

      local myPos = myHrp.Position

      local live = workspace:FindFirstChild("Live") or workspace
      for _, model in ipairs(live:GetChildren()) do
        if model:IsA("Model") and model ~= lp then
          local ehrp = model:FindFirstChild("HumanoidRootPart")
          local hum = model:FindFirstChildOfClass("Humanoid")
          if ehrp and hum and hum.Health > 0 then
            local dist = (ehrp.Position - myPos).Magnitude
            if dist <= 55 then
              if not HITBOX_VISUALIZER.threatRings[model] then
                local ring = Instance.new("CylinderHandleAdornment")
                ring.Name = "EnemyThreatRing"
                ring.Radius = 9.5
                ring.Height = 0.25
                ring.CFrame = CFrame.Angles(math.rad(90), 0, 0) * CFrame.new(0, 0, 2.9)
                ring.Color3 = Color3.fromRGB(255, 60, 60)
                ring.Transparency = 0.75
                ring.AlwaysOnTop = true
                ring.ZIndex = 2
                ring.Adornee = ehrp
                pcall(function() ring.Parent = game:GetService("CoreGui") or workspace end)
                HITBOX_VISUALIZER.threatRings[model] = ring
              end
            else
              if HITBOX_VISUALIZER.threatRings[model] then
                pcall(function() HITBOX_VISUALIZER.threatRings[model]:Destroy() end)
                HITBOX_VISUALIZER.threatRings[model] = nil
              end
            end
          end
        end
      end

      -- Clean up dead / deleted entities from threat rings
      for model, ring in pairs(HITBOX_VISUALIZER.threatRings) do
        if not model.Parent or not model:FindFirstChild("HumanoidRootPart") then
          pcall(function() ring:Destroy() end)
          HITBOX_VISUALIZER.threatRings[model] = nil
        end
      end

      local projFolder = workspace:FindFirstChild("Projectiles") or workspace:FindFirstChild("Effects")
      if projFolder then
        for _, p in ipairs(projFolder:GetChildren()) do
          if (p:IsA("BasePart") or p:IsA("Model")) and not p:IsDescendantOf(lp) then
            local part = p:IsA("BasePart") and p or p.PrimaryPart or p:FindFirstChildWhichIsA("BasePart")
            if part then
              local pDist = (part.Position - myPos).Magnitude
              if pDist <= 80 and not HITBOX_VISUALIZER.projHighlights[part] then
                local pBox = Instance.new("BoxHandleAdornment")
                pBox.Name = "ProjectileHitbox_Box"
                pBox.Size = part.Size + Vector3.new(0.4, 0.4, 0.4)
                pBox.Color3 = Color3.fromRGB(255, 200, 20)
                pBox.Transparency = 0.4
                pBox.AlwaysOnTop = true
                pBox.ZIndex = 5
                pBox.Adornee = part
                pcall(function() pBox.Parent = game:GetService("CoreGui") or workspace end)

                local pOutline = Instance.new("SelectionBox")
                pOutline.Color3 = Color3.fromRGB(255, 220, 50)
                pOutline.LineThickness = 0.05
                pOutline.Transparency = 0.2
                pOutline.Adornee = part
                pcall(function() pOutline.Parent = game:GetService("CoreGui") or workspace end)

                HITBOX_VISUALIZER.projHighlights[part] = { box = pBox, outline = pOutline }

                part.AncestryChanged:Connect(function(_, parent)
                  if not parent and HITBOX_VISUALIZER.projHighlights[part] then
                    pcall(function()
                      if pBox then pBox:Destroy() end
                      if pOutline then pOutline:Destroy() end
                    end)
                    HITBOX_VISUALIZER.projHighlights[part] = nil
                  end
                end)
              end
            end
          end
        end
      end
    end)
  end

  function HITBOX_VISUALIZER.dis()
    HITBOX_VISUALIZER.active = false
    S.hitboxVis = false
    if HITBOX_VISUALIZER.conn then
      pcall(function() HITBOX_VISUALIZER.conn:Disconnect() end)
      HITBOX_VISUALIZER.conn = nil
    end

    for _, ring in pairs(HITBOX_VISUALIZER.threatRings) do
      pcall(function() ring:Destroy() end)
    end
    table.clear(HITBOX_VISUALIZER.threatRings)

    for _, data in pairs(HITBOX_VISUALIZER.projHighlights) do
      pcall(function()
        if data.box then data.box:Destroy() end
        if data.outline then data.outline:Destroy() end
      end)
    end
    table.clear(HITBOX_VISUALIZER.projHighlights)

    for _, adornee in pairs(HITBOX_VISUALIZER.weaponHighlights) do
      pcall(function() adornee:Destroy() end)
    end
    table.clear(HITBOX_VISUALIZER.weaponHighlights)
  end
end

-- anti void / killparts
local NO_KILL_BRICKS = { conn = nil, _descConn = nil, hbConn = nil, charConn = nil, touchConns = {} }
local FAKE_VOID = { conn = nil }

function NO_KILL_BRICKS.en()
  if NO_KILL_BRICKS.conn then return end
  NO_KILL_BRICKS.conn = true
  S.noKill = true

  local KILL_WORDS = {"kill","void","death","lava","damage","acid","fire","trap","hazard","oob","outofbounds","barrier","deathzone","killzone","voidzone","spike","saw","magma"}

  local function isKillPart(p)
    if not p or not p:IsA("BasePart") then return false end
    local nm = string.lower(p.Name)
    local pnm = p.Parent and string.lower(p.Parent.Name) or ""
    for _, w in ipairs(KILL_WORDS) do
      if string.find(nm, w, 1, true) or string.find(pnm, w, 1, true) then return true end
    end
    if p.Transparency >= 0.85 and p.Size.X > 30 and p.Size.Z > 30 and p.Position.Y < -40 then return true end
    return false
  end

  local function neutralizePart(p)
    pcall(function()
      p.CanTouch = false
      p.CanCollide = false
      for _, child in ipairs(p:GetChildren()) do
        if child:IsA("TouchTransmitter") or child:IsA("TouchInterest") or child.ClassName == "TouchTransmitter" then
          pcall(function() child:Destroy() end)
        end
      end
      -- Disconnect character touch connections if touching
      p.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    end)
  end

  for _, obj in ipairs(workspace:GetDescendants()) do
    if isKillPart(obj) then neutralizePart(obj) end
  end

  NO_KILL_BRICKS._descConn = workspace.DescendantAdded:Connect(function(obj)
    if S.noKill and isKillPart(obj) then neutralizePart(obj) end
  end)
  
  -- Heartbeat pulse to neutralize new dynamic parts & prevent touch triggers on character
  NO_KILL_BRICKS.hbConn = G.RS.Heartbeat:Connect(function()
    if not S.noKill then return end
    local char = G.LP.Character
    if not char then return end
    for _, part in ipairs(char:GetChildren()) do
      if part:IsA("BasePart") then
        part.CanTouch = false
      end
    end
  end)

  local function hookTouched(character)
    if not character then return end
    for _, c in ipairs(NO_KILL_BRICKS.touchConns) do pcall(function() c:Disconnect() end) end
    NO_KILL_BRICKS.touchConns = {}
    for _, part in ipairs(character:GetDescendants()) do
      if part:IsA("BasePart") then
        local tc = part.Touched:Connect(function(hit)
          if not S.noKill or not hit or not hit.Parent then return end
          if hit:IsDescendantOf(character) then return end
          if isKillPart(hit) then neutralizePart(hit) end
        end)
        table.insert(NO_KILL_BRICKS.touchConns, tc)
      end
    end
  end

  hookTouched(G.LP.Character)
  NO_KILL_BRICKS.charConn = G.LP.CharacterAdded:Connect(function(ch)
    task.wait(0.3); hookTouched(ch)
  end)
end

function NO_KILL_BRICKS.dis()
  S.noKill = false
  NO_KILL_BRICKS.conn = nil
  if NO_KILL_BRICKS._descConn then pcall(function() NO_KILL_BRICKS._descConn:Disconnect() end); NO_KILL_BRICKS._descConn = nil end
  if NO_KILL_BRICKS.hbConn then pcall(function() NO_KILL_BRICKS.hbConn:Disconnect() end); NO_KILL_BRICKS.hbConn = nil end
  if NO_KILL_BRICKS.charConn then pcall(function() NO_KILL_BRICKS.charConn:Disconnect() end); NO_KILL_BRICKS.charConn = nil end
  for _, c in ipairs(NO_KILL_BRICKS.touchConns) do pcall(function() c:Disconnect() end) end
  NO_KILL_BRICKS.touchConns = {}
end

-- FAKE VOID (Standalone Y Clamp)
function FAKE_VOID.en()
  if FAKE_VOID.conn then return end
  S.nkb = true
  FAKE_VOID.conn = G.RS.RenderStepped:Connect(function()
    if not S.nkb then return end
    local ch = G.LP.Character
    if not ch then return end
    local root = ch:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local pos = root.Position
    local isDepths = pos.X > 30000
    local voidY = isDepths and 39780 or -80
    if pos.Y < voidY then
      pcall(function()
        root.CFrame = G.CF(pos.X, voidY, pos.Z) * (root.CFrame - root.CFrame.Position)
      end)
    end
  end)
end

function FAKE_VOID.dis()
  S.nkb = false
  if FAKE_VOID.conn then pcall(function() FAKE_VOID.conn:Disconnect() end); FAKE_VOID.conn = nil end
end

local ATTACH_SYSTEM = { active = false, targetName = nil, distOffset = 3, conn = nil }
function ATTACH_SYSTEM.en()
  if ATTACH_SYSTEM.active then return end
  ATTACH_SYSTEM.active = true
  S.attachPlayer = true
  
  ATTACH_SYSTEM.conn = game:GetService("RunService").Heartbeat:Connect(function()
    if not ATTACH_SYSTEM.active or not ATTACH_SYSTEM.targetName then return end
    local targetPlr = game.Players:FindFirstChild(ATTACH_SYSTEM.targetName)
    local targetChar = targetPlr and targetPlr.Character
    local targetHRP = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
    
    local lp = game.Players.LocalPlayer.Character
    local hrp = lp and lp:FindFirstChild("HumanoidRootPart")
    
    if targetHRP and hrp then
      for _, part in ipairs(lp:GetChildren()) do
        if part:IsA("BasePart") then part.CanCollide = false end
      end
      local goalCF = targetHRP.CFrame * CFrame.new(0, 0, ATTACH_SYSTEM.distOffset)
      hrp.CFrame = goalCF
      hrp.AssemblyLinearVelocity = targetHRP.AssemblyLinearVelocity
    end
  end)
end

function ATTACH_SYSTEM.dis()
  ATTACH_SYSTEM.active = false
  S.attachPlayer = false
  if ATTACH_SYSTEM.conn then pcall(function() ATTACH_SYSTEM.conn:Disconnect() end) end
end

-- bring mobs (simulation radius + heartbeat TP)
local BRING_MOBS = { active = false, conn = nil }
function BRING_MOBS.en()
  if BRING_MOBS.active then return end
  BRING_MOBS.active = true
  S.bringMobs = true
  
  local rs = game:GetService("RunService")
  local lp = game.Players.LocalPlayer
  
  BRING_MOBS.conn = rs.Heartbeat:Connect(function()
    if not BRING_MOBS.active then return end
    
    -- Set simulation radius to gain network ownership of nearby mob parts
    if setsimulationradius then
      pcall(function() setsimulationradius(math.huge, math.huge) end)
    else
      pcall(function() sethiddenproperty(lp, "SimulationRadius", 9e9) end)
    end
    
    local ch = lp.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    
    local live = workspace:FindFirstChild("Live") or workspace
    for _, mob in ipairs(live:GetChildren()) do
      if mob:IsA("Model") and mob ~= ch and not game.Players:GetPlayerFromCharacter(mob) then
        local mhrp = mob:FindFirstChild("HumanoidRootPart") or mob:FindFirstChild("Torso")
        if mhrp then
          local dist = (hrp.Position - mhrp.Position).Magnitude
          if dist <= 250 then
            for _, part in ipairs(mob:GetChildren()) do
              if part:IsA("BasePart") then part.CanCollide = false end
            end
            local goalCF = hrp.CFrame * CFrame.new(0, 0, -4)
            pcall(function() mob:PivotTo(goalCF) end)
            mhrp.AssemblyLinearVelocity = Vector3.zero
          end
        end
      end
    end
  end)
end

function BRING_MOBS.dis()
  BRING_MOBS.active = false
  S.bringMobs = false
  if BRING_MOBS.conn then pcall(function() BRING_MOBS.conn:Disconnect() end) end
end

local PATHFINDER_BREAKER = { active = false, hbConn = nil, renderConn = nil, lastVel = nil }
function PATHFINDER_BREAKER.en()
  if PATHFINDER_BREAKER.active then return end
  PATHFINDER_BREAKER.active = true
  S.pathfinderBait = true
  
  local rs = game:GetService("RunService")
  local lp = game.Players.LocalPlayer
  
  PATHFINDER_BREAKER.hbConn = rs.Heartbeat:Connect(function()
    if not PATHFINDER_BREAKER.active then return end
    local ch = lp.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if hrp then
      PATHFINDER_BREAKER.lastVel = hrp.AssemblyLinearVelocity
      hrp.AssemblyLinearVelocity = Vector3.new(0, -9e9, 0)
    end
    
    -- Elevate Simulation Radius & Physics Ownership
    pcall(function()
      if setsimulationradius then
        setsimulationradius(math.huge, math.huge)
      else
        sethiddenproperty(lp, "MaxSimulationRadius", 9e9)
        sethiddenproperty(lp, "SimulationRadius", 9e9)
      end
      if sethiddenproperty then
        sethiddenproperty(settings().Physics, "AllowSleep", false)
      end
    end)
    
    -- Target all Mobs (Live, NPCs, Workspace)
    for _, dirName in ipairs({"Live", "NPCs"}) do
      local dir = workspace:FindFirstChild(dirName) or workspace
      for _, mob in ipairs(dir:GetChildren()) do
        if mob:IsA("Model") and mob ~= ch and not game.Players:GetPlayerFromCharacter(mob) then
          pcall(function()
            local hum = mob:FindFirstChildOfClass("Humanoid")
            local mHrp = mob:FindFirstChild("HumanoidRootPart") or mob:FindFirstChild("Torso") or mob.PrimaryPart
            
            -- Freeze Movement AI & Clear Pathfinding
            if hum then
              hum.WalkSpeed = 0
              if mHrp then
                hum.WalkToPoint = mHrp.Position
                hum:MoveTo(mHrp.Position)
              end
              hum:ChangeState(Enum.HumanoidStateType.Physics)
            end
            
            -- Strip Deepwoken AI attributes
            mob:SetAttribute("Target", nil)
            mob:SetAttribute("Aggro", nil)
            mob:SetAttribute("InCombat", nil)
            mob:SetAttribute("Attacking", nil)
            
            -- Remove velocity controllers (ControlVel, SafetyBV, SwimBV, Holder)
            for _, ctrlName in ipairs({"ControlVel", "SafetyBV", "SwimBV", "Holder"}) do
              local ctrl = mob:FindFirstChild(ctrlName, true)
              if ctrl and ctrl:IsA("BodyMover") then
                ctrl:Destroy()
              end
            end
            
            -- Apply Deepwoken Rewrite Void Part Velocity (-10000) & disable collision
            for _, part in ipairs(mob:GetDescendants()) do
              if part:IsA("BasePart") then
                part.CanCollide = false
                if part.Name == "HumanoidRootPart" or part.Name == "Torso" or part.Name == "UpperTorso" then
                  part.AssemblyLinearVelocity = Vector3.new(1000, -10000, 0)
                end
              end
            end
          end)

    pcall(function()
      local ani = hum:FindFirstChildOfClass("Animator")
      if not ani then ani = Instance.new("Animator"); ani.Parent = hum end
      local glideAnim = Instance.new("Animation")
      glideAnim.AnimationId = "rbxassetid://10168663111"
      FLY.glideTrack = ani:LoadAnimation(glideAnim)
      FLY.glideTrack.Priority = Enum.AnimationPriority.Idle
      FLY.glideTrack.Looped = true
      FLY.glideTrack:Play(0.2, 0.3, 1)
    end)

        end
      end
    end
  end)
  
  PATHFINDER_BREAKER.renderConn = rs.RenderStepped:Connect(function()
    if not PATHFINDER_BREAKER.active or not PATHFINDER_BREAKER.lastVel then return end
    local ch = lp.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if hrp then
      hrp.AssemblyLinearVelocity = PATHFINDER_BREAKER.lastVel
    end
  end)
end

function PATHFINDER_BREAKER.dis()
  PATHFINDER_BREAKER.active = false
  S.pathfinderBait = false
  if PATHFINDER_BREAKER.hbConn then pcall(function() PATHFINDER_BREAKER.hbConn:Disconnect() end) end
  if PATHFINDER_BREAKER.renderConn then pcall(function() PATHFINDER_BREAKER.renderConn:Disconnect() end) end
end

local ANIM_LOGGER = {active=false, gui=nil, holder=nil}
do
  local function createToastHUD()
    if ANIM_LOGGER.gui and ANIM_LOGGER.gui.Parent then return ANIM_LOGGER.gui end
    local sg = Instance.new("ScreenGui")
    sg.Name = "KatalystMantraHUD"
    sg.ResetOnSpawn = false
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() G.protG(sg) end)
    sg.Parent = G.getHP()
    
    local container = Instance.new("Frame", sg)
    container.Name = "ToastHolder"
    container.Size = UDim2.new(0, 260, 0, 400)
    container.Position = UDim2.new(1, -270, 0, 80)
    container.BackgroundTransparency = 1
    
    local layout = Instance.new("UIListLayout", container)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 8)
    layout.VerticalAlignment = Enum.VerticalAlignment.Top
    
    ANIM_LOGGER.gui = sg
    ANIM_LOGGER.holder = container
    return sg
  end
  
  local function pushToast(targetName, trackName, animId)
    createToastHUD()
    if not ANIM_LOGGER.holder then return end
    
    local children = {}
    for _, ch in ipairs(ANIM_LOGGER.holder:GetChildren()) do
      if ch:IsA("Frame") then table.insert(children, ch) end
    end
    if #children >= 4 then
      pcall(function() children[1]:Destroy() end)
    end
    
    local toast = Instance.new("Frame", ANIM_LOGGER.holder)
    toast.Size = UDim2.new(1, 0, 0, 44)
    toast.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
    toast.BackgroundTransparency = 0.15
    toast.BorderSizePixel = 0
    G.mkC(toast, 6)
    G.mkS(toast, Color3.fromRGB(120, 90, 255), 1, 0.2)
    
    local accent = Instance.new("Frame", toast)
    accent.Size = UDim2.new(0, 4, 1, 0)
    accent.BackgroundColor3 = Color3.fromRGB(150, 120, 255)
    accent.BorderSizePixel = 0
    G.mkC(accent, 2)
    
    local titleLbl = G.mkL(toast, " " .. targetName, UDim2.new(0, 12, 0, 4), UDim2.new(1, -16, 0, 16), 9, Enum.Font.GothamBold, nil, Color3.fromRGB(245, 245, 248))
    local bodyLbl = G.mkL(toast, tostring(trackName) .. " (" .. tostring(animId) .. ")", UDim2.new(0, 12, 0, 22), UDim2.new(1, -16, 0, 16), 8, Enum.Font.GothamMedium, nil, Color3.fromRGB(160, 160, 190))
    
    toast.Position = UDim2.new(1, 30, 0, 0)
    G.TS:Create(toast, TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = UDim2.new(0, 0, 0, 0)}):Play()
    
    task.delay(2.5, function()
      if toast and toast.Parent then
        local tw = G.TS:Create(toast, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {BackgroundTransparency = 1, Position = UDim2.new(1, 30, 0, 0)})
        tw:Play()
        tw.Completed:Connect(function()
          pcall(function() toast:Destroy() end)
        end)
      end
    end)
  end

  function ANIM_LOGGER.en()
    if ANIM_LOGGER.active then return end; ANIM_LOGGER.active=true
    local function checkAni(v)
      local hum = v:FindFirstChildOfClass("Humanoid")
      local ani = hum and hum:FindFirstChildOfClass("Animator")
      if ani then 
        ani.AnimationPlayed:Connect(function(trk)
          if not ANIM_LOGGER.active then return end
          local lp = G.LP.Character; local hrp = lp and lp:FindFirstChild("HumanoidRootPart")
          local ehrp = v:FindFirstChild("HumanoidRootPart")
          if not hrp or not ehrp or (hrp.Position - ehrp.Position).Magnitude > 60 then return end
          
          -- Reject Roblox default Core priority locomotion
          if trk.Priority == Enum.AnimationPriority.Core then return end
          
          local id = trk.Animation and trk.Animation.AnimationId or "N/A"
          local numId = string.match(tostring(id), "%d+") or id
          if not numId or numId == "" then return end
          
          local animName = string.lower(trk.Name or (trk.Animation and trk.Animation.Name) or "")
          if string.find(animName, "animate") or string.find(animName, "idle") or string.find(animName, "walk") or 
            string.find(animName, "run") or string.find(animName, "jump") or string.find(animName, "fall") or 
            string.find(animName, "land") or string.find(animName, "climb") or string.find(animName, "swim") or 
            string.find(animName, "sit") or string.find(animName, "emote") or string.find(animName, "strafe") or
            string.find(animName, "toolnone") then
            return
          end
          
          local timeStr = os.date("%H:%M:%S")
          local priStr = tostring(trk.Priority):gsub("Enum%.AnimationPriority%.", "")
          
          print(string.format("[Katalyst Combat Log %s] Target: %s | Track: %s [%s] | ID: rbxassetid://%s", timeStr, v.Name, tostring(trk.Name), priStr, tostring(numId)))
          pushToast(v.Name, tostring(trk.Name) .. " [" .. priStr .. "]", "rbxassetid://" .. tostring(numId))
        end) 
      end
    end
    G.ts(function()
      local hooked = {}
      while ANIM_LOGGER.active do
        local live=G.WS:FindFirstChild("Live") or G.WS
        for _,v in ipairs(live:GetChildren()) do
          if v ~= G.LP.Character and not hooked[v] and v:FindFirstChild("HumanoidRootPart") then
            hooked[v] = true
            pcall(checkAni, v)
          end
        end
        G.tw(1)
      end
    end)
  end
  function ANIM_LOGGER.dis()
    ANIM_LOGGER.active = false
    if ANIM_LOGGER.gui then pcall(function() ANIM_LOGGER.gui:Destroy() end); ANIM_LOGGER.gui = nil; ANIM_LOGGER.holder = nil end
  end
end

-- FULL DEEPWOKEN REWRITE AUTO ECHO FARM (Titus Dungeon + Chest + Enchant + Pass-Down Wipe)
local ECHO_FARM = { active = false, running = false, voiding = false }
local ECHO = ECHO_FARM -- alias for backward compatibility

do
  local EASTERN_PLACE_ID = 6473861193
  local TITUS_PLACE_ID = 8668476218
  local ETREAN_PLACE_ID = 4111023553
  local FRAGMENTS_OF_SELF_POS = Vector3.new(2910.00, 1133.03, 1474.00)

  local function getEfData()
    if not _G.EF_DATA then
      _G.EF_DATA = {
        tkill = false,
        wiped = false,
        slot = G.LP and G.LP:GetAttribute("DataSlot") or nil
      }
    end
    return _G.EF_DATA
  end

  local function setEfData(key, val)
    local d = getEfData()
    d[key] = val
  end

  local function queueTeleportScript()
    pcall(function()
      local qot = syn and syn.queue_on_teleport or queue_on_teleport or (Fluxus and Fluxus.queue_on_teleport)
      if qot then
        qot([[
          task.wait(3)
          _G.AUTO_ECHO_RESUME = true
          if _G.START_ECHO_FARM then _G.START_ECHO_FARM() end
        ]])
      end
    end)
  end

  local function isNear(pos, dist)
    local char = G.LP and G.LP.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return false end
    return (pos - hrp.Position).Magnitude <= dist
  end

  local function isPlayerNear(pos, dist)
    for _, plr in ipairs(G.Plrs:GetPlayers()) do
      if plr ~= G.LP and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
        if (pos - plr.Character.HumanoidRootPart.Position).Magnitude <= dist then
          return true
        end
      end
    end
    return false
  end

  local function equipToolByName(toolName)
    local lp = G.LP
    local char = lp and lp.Character
    if not char then return nil end
    local target = string.lower(toolName)
    for _, item in ipairs(char:GetChildren()) do
      if item:IsA("Tool") and string.find(string.lower(item.Name), target) then
        return item
      end
    end
    local bp = lp:FindFirstChild("Backpack")
    if bp then
      for _, item in ipairs(bp:GetChildren()) do
        if item:IsA("Tool") and string.find(string.lower(item.Name), target) then
          item.Parent = char
          task.wait(0.2)
          return item
        end
      end
    end
    return nil
  end

  local function findToolInInventory(toolName)
    local lp = G.LP
    local target = string.lower(toolName)
    if lp.Character then
      for _, item in ipairs(lp.Character:GetChildren()) do
        if item:IsA("Tool") and string.find(string.lower(item.Name), target) then
          return item
        end
      end
    end
    local bp = lp:FindFirstChild("Backpack")
    if bp then
      for _, item in ipairs(bp:GetChildren()) do
        if item:IsA("Tool") and string.find(string.lower(item.Name), target) then
          return item
        end
      end
    end
    return nil
  end

  local function useToolWithChoice(tool, choiceData)
    if not tool then return end
    if tool.Parent ~= G.LP.Character then
      tool.Parent = G.LP.Character
      task.wait(0.2)
    end
    local playerGui = G.LP:WaitForChild("PlayerGui")
    local choicePrompt = nil
    local startT = tick()
    while not choicePrompt and (tick() - startT < 6) do
      pcall(function() tool:Activate() end)
      choicePrompt = playerGui:FindFirstChild("ChoicePrompt")
      task.wait(0.1)
    end
    if choicePrompt then
      local choice = choicePrompt:FindFirstChild("Choice")
      if choice then
        pcall(function() choice:FireServer(choiceData) end)
      end
      repeat task.wait() until not choicePrompt.Parent or (tick() - startT >= 8)
    end
  end

  local function findNearestChest(pos, maxDist)
    local nearest, nearestDist = nil, maxDist or 300
    for _, desc in ipairs(G.WS:GetDescendants()) do
      if desc:IsA("Model") and (string.find(string.lower(desc.Name), "chest") or desc:FindFirstChild("InteractPrompt")) then
        local p = desc.PrimaryPart or desc:FindFirstChildWhichIsA("BasePart")
        if p then
          local d = (pos - p.Position).Magnitude
          if d < nearestDist then
            nearest = desc
            nearestDist = d
          end
        end
      end
    end
    return nearest
  end

  local function serverHop(slot)
    G.noti("Auto Echo Farm", "Server hopping to solo instance...")
    queueTeleportScript()
    pcall(function()
      local ts = game:GetService("TeleportService")
      ts:Teleport(game.PlaceId, G.LP)
    end)
  end

  -- PHASE 1: Character Creation (Fort Merit spawn, Battleaxe, All Meta Modifiers)
  function ECHO_FARM.handleCharacterCreation()
    G.noti("Auto Echo Farm", "Phase 1: Setting up Character Creation (Fort Merit + Battleaxe)...")
    local reqs = game:GetService("ReplicatedStorage"):WaitForChild("Requests", 10)
    if not reqs then return end
    local cc = reqs:WaitForChild("CharacterCreator", 10)
    if not cc then return end

    pcall(function() cc:WaitForChild("PickSpawn", 3):InvokeServer("Merit") end)
    task.wait(0.2)
    pcall(function() cc:WaitForChild("ChangeWeapon", 3):InvokeServer("Battleaxe") end)
    task.wait(0.2)
    pcall(function() reqs:WaitForChild("ToggleMetaModifier", 3):FireServer("All") end)
    task.wait(0.2)

    local playerGui = G.LP:WaitForChild("PlayerGui")
    local startT = tick()
    repeat
      local choicePrompt = playerGui:FindFirstChild("ChoicePrompt")
      local choice = choicePrompt and choicePrompt:FindFirstChild("Choice")
      if choice then
        pcall(function() choice:FireServer(true) end)
      end
      task.wait(0.1)
    until (tick() - startT > 10) or pcall(function() cc:WaitForChild("FinishCreation", 3):InvokeServer() end)
    
    setEfData("wiped", true)
    queueTeleportScript()
  end

  -- PHASE 2: Eastern Luminant Pathing to Titus Gate
  function ECHO_FARM.handleEasternTitusGate()
    G.noti("Auto Echo Farm", "Phase 2: Flying to Titus Gate at Fort Merit...")
    local reqs = game:GetService("ReplicatedStorage"):FindFirstChild("Requests")
    if reqs and reqs:FindFirstChild("StartMenu") and reqs.StartMenu:FindFirstChild("Start") then
      pcall(function() reqs.StartMenu.Start:FireServer() end)
    end

    local char = G.LP.Character or G.LP.CharacterAdded:Wait()
    local hrp = char:WaitForChild("HumanoidRootPart", 10)
    if not hrp then return end

    local positions = {
      CFrame.new(-7518.70, 4825.71, 3483.19),
      CFrame.new(-6877.09, 4825.71, 2829.91),
      CFrame.new(-6877.50, 329.94, 2829.21),
    }

    local firstPos = positions[1].Position
    local curPos = Vector3.new(firstPos.X, hrp.Position.Y, firstPos.Z)
    if not isNear(curPos, 100) then
      table.remove(positions, 1)
    end

    for _, cf in ipairs(positions) do
      if not ECHO_FARM.active then return end
      pcall(function()
        hrp.CFrame = cf
        hrp.Velocity = Vector3.zero
        hrp.AssemblyLinearVelocity = Vector3.zero
      end)
      task.wait(0.5)
    end

    local map = G.WS:WaitForChild("Map", 10)
    local meritEntry = map and map:FindFirstChild("MeritEntry")
    if not meritEntry then
      meritEntry = G.WS:FindFirstChild("MeritEntry", true)
    end

    if meritEntry and isPlayerNear(meritEntry.Position, 100) then
      return serverHop()
    end

    queueTeleportScript()
    G.noti("Auto Echo Farm", "Entering Titus Dungeon...")
    local startT = tick()
    while ECHO_FARM.active and (tick() - startT < 25) do
      if meritEntry then
        for _, desc in ipairs(meritEntry:GetDescendants()) do
          if desc:IsA("ProximityPrompt") then
            pcall(function() fireproximityprompt(desc) end)
          end
        end
      end
      task.wait(0.2)
    end
  end

  -- PHASE 3: Titus Dungeon Chest Looting & Exit
  function ECHO_FARM.handleTitusDungeon()
    G.noti("Auto Echo Farm", "Phase 3: Titus Dungeon started, waiting for chest spawn...")
    local reqs = game:GetService("ReplicatedStorage"):FindFirstChild("Requests")
    if reqs and reqs:FindFirstChild("StartMenu") and reqs.StartMenu:FindFirstChild("Start") then
      pcall(function() reqs.StartMenu.Start:FireServer() end)
    end

    local char = G.LP.Character or G.LP.CharacterAdded:Wait()
    local hrp = char:WaitForChild("HumanoidRootPart", 10)
    if not hrp then return end

    if #G.Plrs:GetPlayers() > 1 then
      return serverHop()
    end

    local startT = tick()
    local chest = nil
    while ECHO_FARM.active and (tick() - startT < 60) do
      chest = findNearestChest(hrp.Position, 300)
      if chest then break end
      task.wait(0.5)
    end

    if chest then
      G.noti("Auto Echo Farm", "Opening Titus Chest...")
      local prompt = chest:FindFirstChildWhichIsA("ProximityPrompt", true)
      if prompt then
        for _ = 1, 5 do
          pcall(function() fireproximityprompt(prompt) end)
          task.wait(0.2)
        end
      end

      -- Loot items via ChoicePrompt
      local playerGui = G.LP:WaitForChild("PlayerGui")
      local choicePrompt = playerGui:FindFirstChild("ChoicePrompt")
      if choicePrompt then
        local choice = choicePrompt:FindFirstChild("Choice")
        if choice then
          pcall(function() choice:FireServer(true) end)
        end
      end
    end

    setEfData("tkill", true)
    queueTeleportScript()

    G.noti("Auto Echo Farm", "Teleporting to Dungeon Exit...")
    local detainmentCore = G.WS:FindFirstChild("DetainmentCore", true)
    local dungeonExit = detainmentCore and detainmentCore:FindFirstChild("DungeonExit")
    if dungeonExit and hrp then
      hrp.CFrame = CFrame.new(dungeonExit.Position)
      task.wait(1.0)
    else
      -- Fallback void exit
      hrp.CFrame = CFrame.new(hrp.Position.X, -350, hrp.Position.Z)
      task.wait(1.5)
    end
  end

  -- PHASE 4: Post-Titus Weapon Enchant & Wipe Process
  function ECHO_FARM.handlePostTitusEnchant()
    G.noti("Auto Echo Farm", "Phase 4: Enchanting Battleaxe & Triggering Pass-Down Wipe...")
    local reqs = game:GetService("ReplicatedStorage"):FindFirstChild("Requests")
    if reqs and reqs:FindFirstChild("StartMenu") and reqs.StartMenu:FindFirstChild("Start") then
      pcall(function() reqs.StartMenu.Start:FireServer() end)
    end

    local char = G.LP.Character or G.LP.CharacterAdded:Wait()
    local hrp = char:WaitForChild("HumanoidRootPart", 10)
    if not hrp then return end

    -- Safe height in air
    pcall(function() hrp.CFrame = CFrame.new(-6877.50, 4825.94, 2829.21) end)
    task.wait(0.5)

    -- Enchant Battleaxe
    local weapon = equipToolByName("Battleaxe")
    if weapon then
      pcall(function() weapon:Activate() end)
      task.wait(0.2)
      local stone = findToolInInventory("Enchant Stone") or findToolInInventory("Stone")
      if stone then
        useToolWithChoice(stone, true)
      end
    end

    -- Use Idol if in inventory
    local idol = findToolInInventory("Idol")
    if idol then
      useToolWithChoice(idol, "Give me relief from my Flaws.")
    end

    -- Process Wipe & Pass-Down at Fragments of Self
    setEfData("tkill", false)
    queueTeleportScript()

    -- Talk to Self NPC or reset character for echoes
    local npcs = G.WS:FindFirstChild("NPCs")
    local selfNpc = npcs and npcs:FindFirstChild("Self")
    if selfNpc then
      local prompt = selfNpc:FindFirstChildWhichIsA("ProximityPrompt", true)
      if prompt then
        pcall(function() fireproximityprompt(prompt) end)
      end
    else
      -- Clean void wipe for echoes
      hrp.CFrame = CFrame.new(hrp.Position.X, -350, hrp.Position.Z)
      pcall(function() hrp.AssemblyLinearVelocity = Vector3.new(0, -2000, 0) end)
    end
  end

  -- MAIN DISPATCHER LOOP
  function ECHO_FARM.en()
    if ECHO_FARM.active then return end
    ECHO_FARM.active = true
    S.echoFarm = true
    S.echo = true
    G.noti("Auto Echo Farm", "Full Deepwoken Rewrite Echo Farm Started!")
    _G.START_ECHO_FARM = ECHO_FARM.en

    task.spawn(function()
      while ECHO_FARM.active do
        pcall(function()
          local lp = G.LP
          local charState = lp and lp:GetAttribute("GameLoaded")
          local data = getEfData()

          if charState == "CharacterCreation" or (lp.PlayerGui and lp.PlayerGui:FindFirstChild("CharacterCreator")) then
            ECHO_FARM.handleCharacterCreation()
          elseif game.PlaceId == EASTERN_PLACE_ID and not data.tkill then
            ECHO_FARM.handleEasternTitusGate()
          elseif game.PlaceId == TITUS_PLACE_ID then
            ECHO_FARM.handleTitusDungeon()
          elseif (game.PlaceId == EASTERN_PLACE_ID or game.PlaceId == ETREAN_PLACE_ID) and data.tkill then
            ECHO_FARM.handlePostTitusEnchant()
          else
            -- Start menu fallback
            local reqs = game:GetService("ReplicatedStorage"):FindFirstChild("Requests")
            if reqs and reqs:FindFirstChild("StartMenu") and reqs.StartMenu:FindFirstChild("Start") then
              pcall(function() reqs.StartMenu.Start:FireServer() end)
            end
          end
        end)
        task.wait(1.5)
      end
    end)
  end

  function ECHO_FARM.dis()
    ECHO_FARM.active = false
    S.echoFarm = false
    S.echo = false
    _G.AUTO_ECHO_RESUME = false
    G.noti("Auto Echo Farm", "Stopped")
  end

  function ECHO.start() ECHO_FARM.en() end
  function ECHO.stop() ECHO_FARM.dis() end
end

-- auto parry core
AUTO_PARRY = AUTO_PARRY or { active = false, initialized = false }
local animConns = {}
local hooked = {}

local remoteTable = nil
local randomTable = nil
local hashCache = {}

local function nts(num, iter)
	local str = ""
	for _ = 1, iter do
		local v78 = num % 256
		str = string.char(v78) .. str
		num = (num - v78) / 256
	end
	return str
end

local function stn(str, len)
	local num = 0
	for i = len, len + 3 do
		num = num * 256 + string.byte(str, i)
	end
	return num
end

local function preprocess(msg, len)
	return msg .. string.char(128) .. string.rep(string.char(0), 64 - (len + 9) % 64) .. nts(8 * len, 8)
end

local function digest(msg, i, H)
	local chunks = {}
	for j = 1, 16 do
		chunks[j] = stn(msg, i + (j - 1) * 4)
	end
	for j = 17, 64 do
		local v103 = chunks[j - 15]
		local v104 = bit32.bxor(bit32.rrotate(v103, 7), bit32.rrotate(v103, 18), bit32.rshift(v103, 3))
		v103 = chunks[j - 2]
		chunks[j] = chunks[j - 16]
			+ v104
			+ chunks[j - 7]
			+ bit32.bxor(bit32.rrotate(v103, 17), bit32.rrotate(v103, 19), bit32.rshift(v103, 10))
	end
	local a = H[1]
	local b = H[2]
	local c = H[3]
	local d = H[4]
	local e = H[5]
	local f = H[6]
	local g = H[7]
	local h = H[8]
	for iter = 1, 64 do
		local v114 = bit32.bxor(bit32.rrotate(a, 2), bit32.rrotate(a, 13), bit32.rrotate(a, 22))
			+ bit32.bxor(bit32.band(a, b), bit32.band(a, c), bit32.band(b, c))
		local v115 = bit32.bxor(bit32.rrotate(e, 6), bit32.rrotate(e, 11), bit32.rrotate(e, 25))
		local v116 = bit32.bxor(bit32.band(e, f), bit32.band(bit32.bnot(e), g))
		local v117 = h + v115 + v116 + randomTable[iter] + chunks[iter]
		local l_g_0 = g
		local l_f_0 = f
		local l_v109_0 = e
		local v121 = d + v117
		local l_v107_0 = c
		local l_v106_0 = b
		local l_v105_0 = a
		a = v117 + v114
		b = l_v105_0
		c = l_v106_0
		d = l_v107_0
		e = v121
		f = l_v109_0
		g = l_f_0
		h = l_g_0
	end
	H[1] = bit32.band(H[1] + a)
	H[2] = bit32.band(H[2] + b)
	H[3] = bit32.band(H[3] + c)
	H[4] = bit32.band(H[4] + d)
	H[5] = bit32.band(H[5] + e)
	H[6] = bit32.band(H[6] + f)
	H[7] = bit32.band(H[7] + g)
	H[8] = bit32.band(H[8] + h)
end

local function hash(remoteName)
	local processed = preprocess(remoteName, #remoteName)
	local ht = {
		1779033703,
		3144134277,
		1013904242,
		2773480762,
		1359893119,
		2600822924,
		528734635,
		1541459225,
	}
	for iter = 1, #remoteName, 64 do
		digest(processed, iter, ht)
	end
	return nts(ht[1], 4)
		.. nts(ht[2], 4)
		.. nts(ht[3], 4)
		.. nts(ht[4], 4)
		.. nts(ht[5], 4)
		.. nts(ht[6], 4)
		.. nts(ht[7], 4)
		.. nts(ht[8], 4)
end

local function findRemoteTables(upvalues)
	for _, upvalue in next, upvalues do
		if typeof(upvalue) ~= "table" then
			continue
		end
		if getrawmetatable(upvalue) then
			continue
		end
		if #upvalue ~= 0 then
			continue
		end
		if upvalue[10] then
			continue
		end
		return upvalue
	end
end

local function searchForRemoteTable(value)
	if remoteTable then return true end
	if typeof(value) ~= "function" then return false end
	if iscclosure(value) or isexecutorclosure(value) then return false end
	local isuccess, info = pcall(debug.getinfo, value)
	if not isuccess or not info then return false end
	if not info.short_src:match("KeyHandler") then return false end
	local usuccess, vupvalues = pcall(debug.getupvalue, value, 10)
	if not usuccess or typeof(vupvalues) ~= "table" then return false end
	if getrawmetatable(vupvalues) then return false end
	remoteTable = findRemoteTables(vupvalues)
	return remoteTable ~= nil
end

local function searchForRandomTable(value)
	if randomTable then return true end
	if typeof(value) ~= "table" then return false end
	if getrawmetatable(value) then return false end
	local firstIndex, firstValue = next(value)
	if typeof(firstIndex) ~= "number" then return false end
	if typeof(firstValue) ~= "number" then return false end
	if firstValue < 100000 or firstValue > 100000000 then return false end
	if #value ~= 68 then return false end
	randomTable = value
	return true
end

local isSearching = false

local function tryDirectKeyHandler()
	pcall(function()
		local lp = game:GetService("Players").LocalPlayer
		if not lp then return end
		local pScripts = lp:FindFirstChild("PlayerScripts")
		if not pScripts then return end
		local keyHandler = pScripts:FindFirstChild("KeyHandler", true)
		if not keyHandler and lp.Character then
			keyHandler = lp.Character:FindFirstChild("KeyHandler", true)
		end
		if keyHandler and type(getsenv) == "function" then
			local env = getsenv(keyHandler)
			if env then
				for k, v in pairs(env) do
					if searchForRandomTable(v) then end
					if searchForRemoteTable(v) then end
					if randomTable and remoteTable then return true end
				end
			end
		end
	end)
	return randomTable ~= nil and remoteTable ~= nil
end

local function searchForKeyHandlerData()
	if randomTable and remoteTable then return true end
	if isSearching then return false end
	isSearching = true

	if tryDirectKeyHandler() then
		isSearching = false
		return true
	end

	if type(getgc) == "function" then
		pcall(function()
			local gc = getgc(true)
			local count = 0
			for _, value in ipairs(gc) do
				count = count + 1
				if searchForRandomTable(value) then end
				if searchForRemoteTable(value) then end
				if randomTable and remoteTable then break end
				if count % 1500 == 0 then
					task.wait()
				end
			end
		end)
	end

	isSearching = false
	return randomTable ~= nil and remoteTable ~= nil
end

getRemote = function(remoteName)
	if not randomTable or not remoteTable then
		pcall(searchForKeyHandlerData)
	end
	if not randomTable or not remoteTable then
		return nil
	end
	local hashedRemoteName = hashCache[remoteName] or hash(remoteName)
	if not hashCache[remoteName] then
		hashCache[remoteName] = hashedRemoteName
	end
	return remoteTable[hashedRemoteName]
end

local effectReplicator = game:GetService("ReplicatedStorage"):FindFirstChild("EffectReplicator")
local effectReplicatorModule = nil
pcall(function()
  if effectReplicator then
    effectReplicatorModule = require(effectReplicator)
  end
end)

-- Smart Cooldown/State checkers extracted from rewrite
inIFrame = function()
  local ch = G.LP and G.LP.Character
  if ch then
    if ch:GetAttribute("Immortal") or ch:GetAttribute("DodgeFrame") or ch:GetAttribute("ParryFrame") or ch:GetAttribute("Ghost") or ch:GetAttribute("IFrames") then
      return true
    end
  end
  if not effectReplicatorModule then return false end
  local ok, res = pcall(function()
    return effectReplicatorModule:FindEffect("Immortal") or 
        effectReplicatorModule:FindEffect("DodgeFrame") or 
        effectReplicatorModule:FindEffect("ParryFrame") or 
        effectReplicatorModule:FindEffect("Ghost")
  end)
  return ok and res
end

local lastParryFireTime = 0
local lastFallbackDodgeTime = 0

canParry = function()
  if os.clock() - lastParryFireTime < 0.45 then return false end
  
  local manualBlocking = false
  pcall(function()
    local uis = game:GetService("UserInputService")
    if uis:IsKeyDown(Enum.KeyCode.F) or uis:IsKeyDown(Enum.KeyCode.ButtonL1) then manualBlocking = true end
  end)
  if manualBlocking then return false end

  local ch = G.LP and G.LP.Character
  if ch then
    if ch:GetAttribute("ParryCool") or ch:GetAttribute("ParryCooldown") or ch:GetAttribute("BlockParryState") or
       ch:GetAttribute("Blocking") or ch:GetAttribute("Stun") or ch:GetAttribute("Ragdoll") or
       ch:GetAttribute("ParryStun") or ch:GetAttribute("BlockBroken") or ch:GetAttribute("Whiff") then
      return false
    end
    local breakMeter = ch:FindFirstChild("BreakMeter")
    if breakMeter and breakMeter:IsA("NumberValue") and breakMeter.Value >= (breakMeter.MaxValue or 100) then
      return false
    end
  end
  
  if not effectReplicatorModule then return true end
  local ok, res = pcall(function()
    if effectReplicatorModule:FindEffect("Blocking") or effectReplicatorModule:FindEffect("BlockParryState") then return false end
    if effectReplicatorModule:FindEffect("ParryCool") or effectReplicatorModule:FindEffect("ParryCooldown") or effectReplicatorModule:FindEffect("ParryRecovery") or effectReplicatorModule:FindEffect("Whiff") then return false end
    if effectReplicatorModule:FindEffect("Stun") or effectReplicatorModule:FindEffect("Ragdoll") or effectReplicatorModule:FindEffect("ParryStun") then return false end
    if effectReplicatorModule:FindEffect("ShakyBlock") or effectReplicatorModule:FindEffect("CancelBlock") then return false end
    return true
  end)
  return ok and (res ~= false)
end

canDodge = function()
  -- If No Roll Cooldown is enabled (infinite rolls), roll is always available whenever needed
  if S.noRollCooldown ~= false then
    local ch = G.LP and G.LP.Character
    if ch then
      local hum = ch:FindFirstChildOfClass("Humanoid")
      if not hum or hum.Health <= 0 then return false end
      if ch:GetAttribute("Ragdoll") or ch:GetAttribute("HardStun") then return false end
    end
    if effectReplicatorModule then
      local ok, res = pcall(function()
        if effectReplicatorModule:FindEffect("Ragdoll") or effectReplicatorModule:FindEffect("HardStun") then return false end
        return true
      end)
      if ok and res == false then return false end
    end
    return true
  end

  -- Finite cooldown legit dodge checks
  if os.clock() - lastFallbackDodgeTime < 0.28 then return false end
  local ch = G.LP and G.LP.Character
  if ch then
    if ch:GetAttribute("NoRoll") or ch:GetAttribute("PreventRoll") or ch:GetAttribute("DodgeCool") or ch:GetAttribute("Stun") or ch:GetAttribute("Ragdoll") then return false end
  end
  if not effectReplicatorModule then return true end
  local ok, res = pcall(function()
    if effectReplicatorModule:FindEffect("NoRoll") or effectReplicatorModule:FindEffect("PreventRoll") or effectReplicatorModule:FindEffect("DodgeCool") or effectReplicatorModule:FindEffect("RollCool") or effectReplicatorModule:FindEffect("RollCooldown") then return false end
    if effectReplicatorModule:FindEffect("Stun") or effectReplicatorModule:FindEffect("Ragdoll") then return false end
    return true
  end)
  return ok and (res ~= false)
end

canVent = function()
  if not effectReplicatorModule then return false end
  local ok, res = pcall(function()
    if effectReplicatorModule:FindEffect("NoBurst") then return false end
    local lp = game.Players.LocalPlayer.Character
    local tempo = lp and lp:FindFirstChild("Tempo")
    if not tempo or tempo.Value < 40 then return false end
    return true
  end)
  return ok and res
end

local function canBlock()
  local lp = game.Players.LocalPlayer.Character
  if not lp then return false end
  local breakMeter = lp:FindFirstChild("BreakMeter")
  if breakMeter and breakMeter.Value / breakMeter.MaxValue > 0.6 then
    return false
  end
  if effectReplicatorModule then
    local ok, res = pcall(function()
      return effectReplicatorModule:FindEffect("ShakyBlock") or 
          effectReplicatorModule:FindEffect("CancelBlock")
    end)
    if ok and res then return false end
  end
  return true
end
