local defenseModules = {}
local defenseLoaded = {}
local nativeRequire = require

local function registerDefenseModule(name, loader)
  assert(defenseModules[name] == nil, "duplicate defense module: " .. name)
  defenseModules[name] = loader
end

local function requireDefenseModule(name)
  if type(name) ~= "string" then
    return nativeRequire(name)
  end

  local loaded = defenseLoaded[name]
  if loaded ~= nil then
    return loaded
  end

  local loader = defenseModules[name]
  assert(loader, "missing defense module: " .. name)

  local module = loader(requireDefenseModule)
  if module == nil then
    module = true
  end
  defenseLoaded[name] = module
  return module
end
registerDefenseModule("Utility/Maid", function(require)
-- https://github.com/Quenty/NevermoreEngine/blob/version2/Modules/Shared/Events/Maid.lua
---@class Maid
local Maid = {}
Maid.__type = "maid"

local function cleanTask(taskToClean)
	if typeof(taskToClean) == "thread" then
		return coroutine.status(taskToClean) == "suspended" and task.cancel(taskToClean) or nil
	end

	if type(taskToClean) == "function" then
		taskToClean()
	elseif typeof(taskToClean) == "RBXScriptConnection" then
		taskToClean:Disconnect()
	elseif typeof(taskToClean) == "Instance" and taskToClean:IsA("Tween") then
		taskToClean:Pause()
		taskToClean:Cancel()
		taskToClean:Destroy()
	elseif taskToClean.Destroy then
		taskToClean:Destroy()
	elseif taskToClean.detach then
		taskToClean:detach()
	end
end

local function retainTask(tasks, preferredKey, taskToClean)
	local key = preferredKey
	if tasks[key] ~= nil then
		key = taskToClean
		if tasks[key] ~= nil then
			key = {}
		end
	end
	tasks[key] = taskToClean
end

---Create new Maid object.
---@return Maid
function Maid.new()
	return setmetatable({
		_tasks = {},
	}, Maid)
end

---Return maid[key] - if not, it's not apart of the maid metatable - so we return the relevant task.
-- @return value
Maid.__index = (function(self, index)
	if Maid[index] then
		return Maid[index]
	else
		return self._tasks[index]
	end
end)

---Clean or add a task with a specific key.
---@param index any
---@param newTask any
Maid.__newindex = (function(self, index, newTask)
	if Maid[index] ~= nil then
		return warn(("'%s' is reserved"):format(tostring(index)), 2)
	end

	local tasks = self._tasks
	local oldTask = tasks[index]

	if oldTask == newTask then
		return
	end

	if oldTask then
		tasks[index] = newTask
		local succeeded, failure = pcall(cleanTask, oldTask)
		if not succeeded then
			retainTask(tasks, index, oldTask)
			error(failure, 0)
		end
		return
	end

	tasks[index] = newTask
end)

---Add a task without a specific ID and return the task.
---@param task any
---@return any
Maid.mark = (function(self, task)
	self:add(task)
	return task
end)

---Add a task without a specific ID.
---@param task any
---@return number
Maid.add = (function(self, task)
	if not task then
		warn("Maid.add rejected false or nil task.")
		return nil
	end

	local taskId = #self._tasks + 1
	self[taskId] = task

	return taskId
end)

---Remove task without cleaning it.
---@param taskId number
Maid.removeTask = (function(self, taskId)
	local tasks = self._tasks
	tasks[taskId] = nil
end)

---Clean up all tasks.
Maid.clean = (function(self)
	local tasks = self._tasks
	local failures = {}
	local function attempt(index, taskToClean, callback)
		local succeeded, failure = pcall(callback, taskToClean)
		if not succeeded then
			failures[#failures + 1] = {
				index = index,
				task = taskToClean,
				reason = failure,
			}
		end
	end

	for index, taskToClean in pairs(tasks) do
		if typeof(taskToClean) == "RBXScriptConnection" then
			tasks[index] = nil
			attempt(index, taskToClean, function(connection)
				connection:Disconnect()
			end)
		end
	end

	local index, _task = next(tasks)

	while _task ~= nil do
		tasks[index] = nil
		attempt(index, _task, cleanTask)
		index, _task = next(tasks)
	end

	for _, failure in ipairs(failures) do
		retainTask(tasks, failure.index, failure.task)
	end
	if #failures > 0 then
		local messages = {}
		for _, failure in ipairs(failures) do
			messages[#messages + 1] = tostring(failure.index) .. ": " .. tostring(failure.reason)
		end
		error("Maid cleanup failed: " .. table.concat(messages, "; "), 0)
	end
end)

-- Return Maid module.
return Maid
end)

registerDefenseModule("Utility/Signal", function(require)
-- Wrapper for Roblox's signals for safe connections to signals.
---@class Signal
---@field signal RBXScriptSignal Underlying roblox script signal
local Signal = {}
Signal.__index = Signal

---Connect without a protected-call wrapper in the event hot path.
---@param label string
---@param eventFunction function
---@return RBXScriptConnection
function Signal:connect(label, eventFunction)
	local signalLabel = type(label) == "string" and label or tostring(label)
	if type(eventFunction) ~= "function" then
		warn(string.format("Signal.connect(%s) expected function, got %s.", signalLabel, type(eventFunction)))
		return nil
	end

	if not self.signal or not self.signal.Connect then
		warn(string.format("Signal.connect(%s) missing underlying signal.", signalLabel))
		return nil
	end

	local connection = self.signal:Connect(eventFunction)
	return connection
end

---Create new wrapper signal object.
---@param robloxSignal RBXScriptSignal
---@return Signal
function Signal.new(robloxSignal)
	-- Create new wrapper signal object.
	local self = setmetatable({}, Signal)
	self.signal = robloxSignal

	-- Return new wrapper signal object.
	return self
end

-- Return Signal module.
return Signal
end)

registerDefenseModule("Utility/TaskSpawner", function(require)
-- Task spawner module.
local TaskSpawner = {}

-- Defense-owned threads are retained only so detach can cancel work that a caller
-- did not place in its own Maid. Native scheduling sleeps without a recurring
-- RunService connection.
local ownedThreads = setmetatable({}, { __mode = "k" })

---Spawn delayed task where the delay can be variable.
---@param label string
---@param delay function
---@param callback function
---@vararg any
function TaskSpawner.delay(label, delay, callback, ...)
	local delayResult = delay()
	delayResult = math.max(0, tonumber(delayResult) or 0)
	local thread
	thread = task.delay(delayResult, (function(...)
		local running = coroutine.running()
		callback(...)
		ownedThreads[running] = nil
	end), ...)
	ownedThreads[thread] = label
	return thread
end

---Spawn task.
---@param label string
---@param callback function
---@vararg any
function TaskSpawner.spawn(label, callback, ...)
	local taskFunction = (function(...)
		local running = coroutine.running()
		callback(...)
		ownedThreads[running] = nil
	end)

	local spawnedTask = task.spawn(taskFunction, ...)
	if spawnedTask and coroutine.status(spawnedTask) ~= "dead" then
		ownedThreads[spawnedTask] = label
	end
	return spawnedTask
end

local function scheduleOwned(owner, label, schedule, callback, ...)
	local thread
	thread = coroutine.create(function(...)
		local running = coroutine.running()
		callback(...)
		ownedThreads[running] = nil
		if owner and owner[running] == running then
			owner[running] = nil
		end
	end)

	ownedThreads[thread] = label
	if owner then
		owner[thread] = thread
	end
	schedule(thread, ...)

	return thread
end

---Spawn a task owned by a Maid-like object. The thread is installed before it
---is scheduled so even a zero-yield callback can remove itself reliably on
---completion. Cleaning the owner still cancels an in-flight callback.
---@param owner Maid
---@param label string
---@param callback function
---@vararg any
---@return thread?
function TaskSpawner.spawnOwned(owner, label, callback, ...)
	if not owner then
		return TaskSpawner.spawn(label, callback, ...)
	end

	return scheduleOwned(owner, label, task.spawn, callback, ...)
end

---Defer a task owned by a Maid-like object.
---@param owner Maid
---@param label string
---@param callback function
---@vararg any
---@return thread?
function TaskSpawner.deferOwned(owner, label, callback, ...)
	return scheduleOwned(owner, label, task.defer, callback, ...)
end

---@param owner Maid
---@param label string
---@param seconds number
---@param callback function
---@vararg any
---@return thread?
function TaskSpawner.delayOwned(owner, label, seconds, callback, ...)
	if not owner then
		return TaskSpawner.delay(label, function()
			return seconds
		end, callback, ...)
	end

	local delayed
	delayed = task.delay(math.max(0, tonumber(seconds) or 0), function(...)
		ownedThreads[delayed] = nil
		if owner[delayed] ~= delayed then
			return
		end
		owner[delayed] = nil
		callback(...)
	end, ...)
	ownedThreads[delayed] = label
	owner[delayed] = delayed
	return delayed
end

function TaskSpawner.detach()
	local failures = {}
	for thread, label in next, ownedThreads do
		if coroutine.status(thread) ~= "suspended" then
			ownedThreads[thread] = nil
			continue
		end

		local success, failure = pcall(task.cancel, thread)
		if success then
			ownedThreads[thread] = nil
		else
			failures[#failures + 1] = string.format("%s: %s", tostring(label), tostring(failure))
		end
	end
	if #failures > 0 then
		error("[Katalyst] failed to cancel owned tasks: " .. table.concat(failures, "; "))
	end
end

-- Return TaskSpawner module.
return TaskSpawner
end)

