local OriginalStore = {}
OriginalStore.__index = OriginalStore

OriginalStore.get = (function(self)
	if self.stored then
		return self.value
	end

	return nil
end)

OriginalStore.mark = (function(self, data, index)
	if self.stored and self.data ~= data then
		self:restore()
	end

	if not self.stored then
		self.data = data
		self.index = index
		self.value = data[index]
		self.stored = true
	end
end)

OriginalStore.set = (function(self, data, index, value)
	self:mark(data, index)
	data[index] = value
end)

OriginalStore.run = (function(self, data, index, value, callback)
	self:set(data, index, value)
	callback()
	self:restore()
end)

OriginalStore.restore = (function(self)
	if not self.stored then
		return
	end

	pcall(function()
		self.data[self.index] = self.value
	end)
	self.stored = false
end)

OriginalStore.detach = (function(self)
	self:restore()
	self.data = nil
	self.index = nil
	self.value = nil
	self.stored = false
end)

OriginalStore.new = (function()
	return setmetatable({
		data = nil,
		index = nil,
		value = nil,
		stored = false,
	}, OriginalStore)
end)

return OriginalStore
end)

registerDefenseModule("Utility/ExecutorCompat", function(require)
-- Optional executor API compatibility helpers.
local ExecutorCompat = {}

local CONNECTION_CALLBACK_KEYS = {
	"Function",
	"Func",
	"func",
	"_function",
	"Callback",
	"callback",
}

local function safeBoolean(callback, ...)
	if type(callback) ~= "function" then
		return false
	end

	local success, result = pcall(callback, ...)
	return success and result == true
end

---Read executor userdata members that may throw when unsupported.
---@param value any
---@param key string
---@return any
---@return boolean
function ExecutorCompat.getMember(value, key)
	if value == nil then
		return nil, false
	end

	local success, result = pcall(function()
		return value[key]
	end)
	if success then
		return result, true
	end

	return nil, false
end

function ExecutorCompat.isCClosure(value)
	return safeBoolean(iscclosure, value)
end

function ExecutorCompat.isExecutorClosure(value)
	return safeBoolean(isexecutorclosure, value)
		or safeBoolean(is_synapse_function, value)
		or safeBoolean(isourclosure, value)
end

function ExecutorCompat.hasRawMetatable(value)
	if type(getrawmetatable) ~= "function" then
		return false
	end

	local success, result = pcall(getrawmetatable, value)
	return success and result ~= nil
end

function ExecutorCompat.getGarbage(includeTables)
	if type(getgc) ~= "function" then
		return nil
	end

	local success, result = pcall(getgc, includeTables)
	if success and type(result) == "table" then
		return result
	end

	return nil
end

---Return a bounded getconnections result without exposing provider errors.
---@param signal RBXScriptSignal
---@return table?
function ExecutorCompat.getConnections(signal)
	if type(getconnections) ~= "function" then
		return nil
	end

	local success, result = pcall(getconnections, signal)
	if success and type(result) == "table" then
		return result
	end

	return nil
end

---Get a Lua callback from the known connection-proxy member variants.
---@param connection any
---@return function?
function ExecutorCompat.getConnectionCallback(connection)
	local isTable = type(connection) == "table"
	for _, key in ipairs(CONNECTION_CALLBACK_KEYS) do
		local callback, readable = ExecutorCompat.getMember(connection, key)
		if type(callback) == "function" then
			return callback
		end

		-- A readable nil marks a native callback; only plain tables use aliases.
		if readable and not isTable then
			return nil
		end
	end

	return nil
end

return ExecutorCompat
end)

