---@return string[]
function ActionContainer:names()
	local names = {}

	for _, action in ipairs(self._stack) do
		table.insert(names, action.name)
	end

	return names
end

---Get action stack.
---@return Action[]
function ActionContainer:stack()
	return self._stack
end

---Get action count.
---@return number
function ActionContainer:count()
	return #self._stack
end

---Clear actions.
function ActionContainer:clear()
	self._data = {}
	self._stack = {}
end

---Get action data.
---@return table<string, Action>
function ActionContainer:get()
	return self._data
end

---Return a serializable table.
---@return table
function ActionContainer:serialize()
	local data = {}

	for _, action in ipairs(self._stack) do
		table.insert(data, action:serialize())
	end

	return data
end

---Create new ActionContainer object.
---@param values table?
---@return ActionContainer
function ActionContainer.new(values)
	local self = setmetatable({}, ActionContainer)

	self._data = {}
	self._stack = {}

	if values then
		self:load(values)
	end

	return self
end

-- Return ActionContainer module.
return ActionContainer
end)

