    AdvancedAntiAPBreak = function() return S.antiAPBreaker == true end,
    ValidateIncomingAnimations = function() return S.antiExploitAnim ~= false end,
    BlatantRoll = function() return S.blatantRoll == true end,
    ParryOnly = function() return S.parryOnly == true end,
    RollCancel = function() return S.blatantRoll == true end,
    DeflectBlockFallback = function() return false end,
    VentFallback = function() return false end,
    RollOnParryCooldown = function() return false end,
    PreventAttackDuringParry = function() return false end,
    CrasherProtection = function() return false end,
    CheckTargetingValue = function() return false end,
    IgnoreMobs = function() return false end,
    IgnorePlayers = function() return false end,
    IgnoreAllies = function() return false end,
    UsePrediction = function() return false end,
    UsePunishment = function() return false end,
    BlockVentState = function() return false end,
    BlockParryState = function() return false end,
    BlockDodgeState = function() return false end,
    NoBlockingState = function() return false end,
  }

  local optionReaders = {
    CrasherProtectionThreshold = function() return 15 end,
    DistanceLimit = function() return 3000 end,
    FOVLimit = function() return 180 end,
    MaxTargets = function() return 10 end,
    PlayerSelectionType = function() return "Closest In Distance" end,
    AutoDefenseFilters = function()
      return S.ignoreM1s and { ["Filter Out M1s"] = true } or {}
    end,
    RollCancelDelay = function() return 0.18 end,
    DefaultPunishableWindow = function() return 0.7 end,
    DefaultAfterWindow = function() return 0.1 end,
  }

  local function copyValue(value)
    return type(value) == "table" and table.clone(value) or value
  end

  local function valuesEqual(left, right)
    if type(left) ~= "table" or type(right) ~= "table" then
      return left == right
    end
    for key, value in next, left do
      if right[key] ~= value then return false end
    end
    for key, value in next, right do
      if left[key] ~= value then return false end
    end
    return true
  end

  local function newControl(read)
    local listeners = {}
    local nextListenerId = 0
    local control = { Value = copyValue(read()) }

    function control:SetValue(value)
      if valuesEqual(self.Value, value) then return false end
      self.Value = copyValue(value)
      for _, listener in next, listeners do
        listener(copyValue(self.Value))
      end
      return true
    end

    function control:Subscribe(callback, replay)
      assert(type(callback) == "function", "Control.Subscribe expects a callback")
      nextListenerId = nextListenerId + 1
      local listenerId = nextListenerId
      listeners[listenerId] = callback
      if replay ~= false then callback(copyValue(self.Value)) end

      local connected = true
      return function()
        if not connected then return end
        connected = false
        listeners[listenerId] = nil
      end
    end

    function control:sync()
      self:SetValue(read())
    end

    function control:detach()
      table.clear(listeners)
    end

    return control
  end

  local function register(target, readers)
    for id, read in next, readers do
      local control = newControl(read)
      controls[id] = control
      target[id] = control
    end
  end

  function ControlStore.init()
    if initialized then return ControlStore end
    initialized = true
    register(toggles, toggleReaders)
    register(options, optionReaders)
    return ControlStore
  end

  function ControlStore.get(id)
    return controls[id]
  end

  function ControlStore.getToggles()
    return toggles
  end

  function ControlStore.getOptions()
    return options
  end

  function ControlStore.syncFromKatalyst()
    if not initialized then ControlStore.init() end
    for _, control in next, controls do
      control:sync()
    end
  end

  function ControlStore.detach()
    for _, control in next, controls do
      control:detach()
    end
    table.clear(controls)
    table.clear(toggles)
    table.clear(options)
    initialized = false
  end

  return ControlStore
end)

