      contains = { "Lightning Hero", "LightningHeroBlade", "Lightning Heroblade" },
    },
    LightningStream = { label = "Mantra:StreamLightning{{Lightning Stream}}", names = { "Mantra:StreamLightning{{Lightning Stream}}" } },
    PressureBlast = { label = "Mantra:StrongPunchWeaponHeavy{{Pressure Blast}}", names = { "Mantra:StrongPunchWeaponHeavy{{Pressure Blast}}" } },
    RapidSlashes = { label = "Mantra:DashWeaponLight{{Rapid Slashes}}", names = { "Mantra:DashWeaponLight{{Rapid Slashes}}" } },
    Revenge = { label = "Mantra:RevengeAgility{{Revenge}}", names = { "Mantra:RevengeAgility{{Revenge}}" } },
    RisingFlame = { label = "Mantra:RisingSlashFire{{Rising Flame}}", names = { "Mantra:RisingSlashFire{{Rising Flame}}" } },
    RisingShadow = { label = "Mantra:RisingSlashShadow{{Rising Shadow}}", names = { "Mantra:RisingSlashShadow{{Rising Shadow}}" } },
    ShadowEruptionCast = {
      label = "Shadow Eruption/Chains",
      names = {
        "Mantra:EruptionShadow{{Shadow Eruption}}",
        "Mantra:RestraintShadow{{Shadow Chains}}",
      },
    },
    ShadowGun = { label = "Mantra:GunShadow{{Shadow Gun}}", names = { "Mantra:GunShadow{{Shadow Gun}}" } },
    ShadowRoar = { label = "Mantra:RoarShadow{{Shadow Roar}}", names = { "Mantra:RoarShadow{{Shadow Roar}}" } },
    WindCarve = { label = "Mantra:CarveWind{{Wind Carve}}", names = { "Mantra:CarveWind{{Wind Carve}}" } },
  }

  local ModuleManager = { modules = {} }

  function ModuleManager.ownership(id)
    return id and ownershipDescriptors[PP_SCRAMBLE_STR(id)] or nil
  end

  function ModuleManager.refresh()
    table.clear(ModuleManager.modules)
  end

  function ModuleManager.detach()
    ModuleManager.refresh()
  end

  return ModuleManager
end)
registerDefenseModule("Game/Timings/SaveManager", function(require)
  local AnimationTiming = require("Game/Timings/AnimationTiming")
  local EffectTiming = require("Game/Timings/EffectTiming")
  local PartTiming = require("Game/Timings/PartTiming")
  local SoundTiming = require("Game/Timings/SoundTiming")
  local TimingContainer = require("Game/Timings/TimingContainer")
  local TimingContainerPair = require("Game/Timings/TimingContainerPair")

  local SaveManager = {
    as = nil,
    es = nil,
    ps = nil,
    ss = nil,
    stats = nil,
  }

  local replicatedStorage = game:GetService("ReplicatedStorage")

  local weaponModuleByKind = {
    basic = "WeaponTest",
    running = "WeaponRunningAttackTest",
    aerial = "WeaponAerialAttackTest",
    uppercut = "WeaponUppercutTest",
    flourish = "WeaponFlourishTest",
  }

  local m1Names = {}
  for _, moduleName in next, weaponModuleByKind do
    m1Names[moduleName] = true
  end

  local weaponKindByName = {
    slash1 = "basic",
    slash2 = "basic",
    slash3 = "basic",
    slash4 = "basic",
    slash5 = "basic",
    slashtest = "basic",
    dualswingsword1 = "basic",
    dualswingsword2 = "basic",
    dualswingsword3 = "basic",
    pistolwhip1 = "basic",
    pistolwhip2 = "basic",
    primaryshot = "basic",
    offhandshot = "basic",
    ["1swordswing1"] = "basic",
    ["1swordswing2"] = "basic",
    runningattack = "running",
    oldrunattack = "running",
    aerialstab = "aerial",
    aerialshot = "aerial",
    aerialshotoffhand = "aerial",
    uppercut = "uppercut",
    flourish = "flourish",
  }

  local weaponKindRank = {
    basic = 1,
    running = 2,
    aerial = 3,
    uppercut = 4,
    flourish = 5,
  }

  local WEAPON_REGISTRY_RETRY_INTERVAL = 0.25
  local WEAPON_REGISTRY_RETRY_WINDOW = 8
  local WEAPON_REGISTRY_RETRY_LIMIT = 24

  local weaponFormulas = {
    basic = {
      Bow = { 0.147, 0.160 },
      Club = { 0.180, 0.100 },
      Dagger = { 0.150, 0.075 },
      Fist = { 0.140, 0.130 },
      Rapier = { 0.155, 0.120 },
      Rifle = { 0.174, 0.125 },
      Spear = { 0.150, 0.100 },
      Sword = { 0.150, 0.100 },
      Twinblade = { 0.150, 0.050 },
      Greatsword = { 0.158, 0.150 },
    },
    running = {
      Bow = { 0.160, 0.130 },
      Club = { 0.173, 0.140, 0.150 },
      Dagger = { 0.147, 0.140 },
      Fist = { 0.153, 0.150 },
      Greatcannon = { 0.160, 0.180, 0.100 },
      Greatsword = { 0.160, 0.180, 0.100 },
      Rapier = { 0.238, 0.060 },
      Rifle = { 0.169, 0.180, 0.100 },
      Spear = { 0.150, 0.170, 0.100 },
      Sword = { 0.135, 0.150, 0.150 },
      Twinblade = { 0.164, 0.140, 0.150 },
    },
    aerial = {
      Bow = { 0.145, 0.170 },
      Club = { 0.163, 0.140 },
      Dagger = { 0.165, 0.100 },
      Fist = { 0.160, 0.130 },
      Greataxe = { 0.168, 0.125 },
      Greatcannon = { 0.163, 0.183 },
      Greathammer = { 0.150, 0.170 },
      Greatsword = { 0.166, 0.160 },
      Rapier = { 0.225, 0.080 },
      Spear = { 0.150, 0.170 },
      Staff = { 0.160, 0.100 },
      Sword = { 0.160, 0.100 },
      Twinblade = { 0.160, 0.100 },
    },
    flourish = {
      Bow = { 0.172, 0.140 },
      Club = { 0.160, 0.150 },
      Dagger = { 0.165, 0.100 },
      Fist = { 0.160, 0.140 },
      Greataxe = { 0.180, 0.100 },
      Greatcannon = { 0.173, 0.160 },
      Greathammer = { 0.140, 0.140 },
      Greatsword = { 0.170, 0.050 },
      Rapier = { 0.163, 0.120 },
      Rifle = { 0.160, 0.150 },
      Spear = { 0.135, 0.180 },
      Staff = { 0.160, 0.120 },
      Sword = { 0.160, 0.120 },
      Twinblade = { 0.166, 0.140 },
    },
    uppercut = {
      Bow = { 0.150, 0.140 },
      Club = { 0.166, 0.140 },
      Dagger = { 0.166, 0.120 },
      Fist = { 0.150, 0.120 },
      Greataxe = { 0.141, 0.100 },
      Greatcannon = { 0.166, 0.100 },
      Greathammer = { 0.150, 0.100 },
      Greatsword = { 0.157, 0.100 },
      Rapier = { 0.181, 0.130 },
      Rifle = { 0.159, 0.140 },
      Spear = { 0.163, 0.100, 0.050 },
      Staff = { 0.150, 0.100 },
      Sword = { 0.150, 0.100 },
      Twinblade = { 0.163, 0.130 },
    },
  }

  local function compact(value)
    return string.lower(tostring(value or "")):gsub("[^%w]", "")
  end

  local function assetId(value)
    local text = tostring(value or "")
    return text:match("^rbxassetid://(%d+)$") or text:match("^(%d+)$")
  end

  local function timingIdentity(value)
    local id = assetId(value)
    if not id then return nil end
    return AUTO_PARRY_TIMING_IDENTITIES[id]
  end

  local function weaponAnimationKind(animation, root)
    local current = animation
    while current and current ~= root do
      local kind = weaponKindByName[compact(current.Name)]
      if kind then return kind, current.Name end
      current = current.Parent
    end
  end

  local function weaponAnimationRegistry(registry)
    registry = registry or {}
    local count = 0
    for _ in next, registry do
      count = count + 1
    end

    local assets = replicatedStorage:FindFirstChild("Assets")
    local anims = assets and assets:FindFirstChild("Anims")
    if not anims then return registry, count, nil, 0 end

    local descendantCount = #anims:GetDescendants()

    for _, rootName in ipairs({ "NewWeapon", "Weapon" }) do
      local root = anims:FindFirstChild(rootName)
      if not root then continue end

      for _, animation in ipairs(root:GetDescendants()) do
        if not animation:IsA("Animation") then continue end
        local id = assetId(animation.AnimationId)
        local kind, sourceName = weaponAnimationKind(animation, root)
        if not id or not kind then continue end

        local current = registry[id]
        local replace = not current
          or weaponKindRank[kind] < weaponKindRank[current.kind]
          or (kind == current.kind and tostring(sourceName) < tostring(current.name))
        if replace then
          if not current then count = count + 1 end
          registry[id] = { kind = kind, name = tostring(sourceName) }
        end
      end
    end

    return registry, count, anims, descendantCount
  end

  local function equippedWeapon(entity)
    if typeof(entity) ~= "Instance" or not entity:IsA("Model") then return nil end

    local handWeapon = nil
    if entity:GetAttribute("MOB_rich_name") then
      local leftHand = entity:FindFirstChild("LeftHand")
      local rightHand = entity:FindFirstChild("RightHand")
      handWeapon = (leftHand and leftHand:FindFirstChild("HandWeapon"))
        or (rightHand and rightHand:FindFirstChild("HandWeapon"))
    else
      local thrown = workspace:FindFirstChild("Thrown")
      local attach = thrown and thrown:FindFirstChild("Attach_" .. entity.Name)
      handWeapon = attach and attach:FindFirstChild("HandWeapon")
    end
    if not handWeapon then return nil end

    local stats = handWeapon:FindFirstChild("Stats")
    local swingSpeed = stats and stats:FindFirstChild("SwingSpeed")
    local length = stats and stats:FindFirstChild("Length")
    local weaponType = handWeapon:FindFirstChild("Type")
    if not swingSpeed or not length or not weaponType then return nil end

    local speedValue = tonumber(swingSpeed.Value)
    local lengthValue = tonumber(length.Value)
    if not speedValue or speedValue <= 0 or not lengthValue or lengthValue <= 0 then return nil end

    return {
      swingSpeed = speedValue,
      length = lengthValue,
      type = tostring(weaponType.Value or "N/A"),
    }
  end

  local function formulaWindup(formula, speed, swingSpeed)
    if not formula or not speed or speed <= 0 then return nil end
    return (formula[1] / speed) + formula[2] + ((formula[3] or 0) / swingSpeed)
  end

  local function deferredWeaponWindup(speedWait, speed)
    speed = tonumber(speed)
    if not speedWait or speed == nil then return nil end
    if speedWait.mode == "minimum" then
      speed = math.max(speed, speedWait.minimum)
    end

    if speedWait.formula == "pistol-shot" then
      return speed == 0 and 0.100 or 0.075 / speed
    elseif speedWait.formula == "rifle-second" then
      return speed == 0 and 0.100 or 0.200 / speed
    elseif speedWait.formula == "running-pistol" then
      return speed > 0 and 0.300 / speed or nil
    elseif speedWait.formula == "aerial-rifle" then
      return speed == 0 and 0.100 or 0.300 / speed
    elseif speedWait.formula == "uppercut-pistol" then
      return speed > 0 and (0.166 / speed) + 0.150 or nil
    elseif speedWait.formula == "titus-fist" then
      local finalSpeed = speed + 0.2
      return finalSpeed > 0 and ((565 * 0.76) / finalSpeed) / 1000 or nil
    end
  end

  local function weaponWindup(kind, sourceName, data, track)
    local weaponType = data.type
    local animationName = tostring(sourceName)
    local speed = tonumber(track.Speed)

    if kind == "basic" then
      if weaponType == "Staff" then return 0.350 end
      if weaponType == "Pistol" then
        if not animationName:find("Shot", 1, true) then
          return 0.350 / data.swingSpeed
        end
        return nil, { mode = "changed", initial = speed, formula = "pistol-shot" }
      end
      if weaponType == "Rifle" and animationName:find("2", 1, true) then
        return nil, { mode = "changed", initial = speed, formula = "rifle-second" }
      end
      if weaponType == "Greataxe" then
        if not speed or speed <= 0 then return nil end
        if speed == 1 then return (0.171 / speed) + (0.250 / data.swingSpeed) end
        return (0.171 / speed) + 0.120
      end
      if weaponType == "Greathammer" then
        if not speed or speed <= 0 then return nil end
        if speed == 1 then return (0.150 / speed) + (0.250 / data.swingSpeed) end
        return (0.150 / speed) + 0.200
      end
      if weaponType == "Greatcannon" then
        if not speed or speed <= 0 then return nil end
        if speed == 1 then return (0.155 / speed) + 0.300 end
        return (0.155 / speed) + 0.160
      end
    elseif kind == "running" and weaponType == "Pistol" then
      return nil, { mode = "minimum", minimum = 0.1, formula = "running-pistol" }
    elseif kind == "aerial" then
      if weaponType == "Pistol" then return 0.500 / data.swingSpeed end
      if weaponType == "Rifle" and not animationName:find("Fist", 1, true) then
        return nil, { mode = "changed", initial = speed, formula = "aerial-rifle" }
      end
      if weaponType == "Rifle" then
        return formulaWindup({ 0.199, 0.100 }, speed, data.swingSpeed)
      end
    elseif kind == "flourish" and weaponType == "Pistol" then
      return 0.500 / data.swingSpeed
    elseif kind == "uppercut" and weaponType == "Pistol" then
      return nil, { mode = "minimum", minimum = 0.1, formula = "uppercut-pistol" }
    end

    return formulaWindup(weaponFormulas[kind] and weaponFormulas[kind][weaponType], speed, data.swingSpeed)
  end

  local function closeWeaponFlags(timing, weaponType, flourish)
    timing.htype = Enum.PartType.Ball
    timing.fhb = false
    timing.hso = -5
    timing.nvfb = true
    timing.pbfb = false
    timing.ndfb = false
    timing.bfht = 0.3
    timing.dp = false
    timing.pfh = true
    timing.phd = true
    timing.pfht = 0.25
    timing.phds = 0.6

    if weaponType == "Fist" or weaponType == "Dagger" then
      timing.pbfb = true
      timing.bfht = 0.6
      timing.pfh = false
      timing.dp = true
      timing.phds = weaponType == "Dagger" and 0.6 or 0.25
      return
    end

    if weaponType == "Sword"
      or weaponType == "Staff"
      or weaponType == "Twinblade"
      or weaponType == "Spear"
      or weaponType == "Club"
      or weaponType == "Rifle"
      or weaponType == "Pistol"
    then
      timing.pbfb = true
      timing.bfht = flourish and 0.6 or 0.3
      timing.phd = false
      timing.duih = false
      timing.ffh = true
      if not flourish then timing.pfht = 0.5 end
      return
    end

    if weaponType == "Greathammer"
      or weaponType == "Greatcannon"
      or weaponType == "Greatsword"
      or weaponType == "Greataxe"
    then
      timing.phd = false
      timing.duih = false
      timing.ffh = true
      timing.pfht = 0.5
      timing.dp = false
    end
  end

  local function makeWeaponTiming(id, definition, entity, track)
    if not definition or not entity or not track or S.ignoreM1s then return nil end
    local sourceKey = compact(definition.name)
    local evengardeSwing = definition.kind == "basic"
      and string.find(string.lower(entity.Name), "evengarde", 1, true) ~= nil
      and (sourceKey == "1swordswing1" or sourceKey == "1swordswing2")
    local data = not evengardeSwing and equippedWeapon(entity) or nil
    if not data and not evengardeSwing then return nil end

    local windup = 0
    local speedWait = nil
    if not evengardeSwing then
      local titusFist = definition.kind == "basic"
        and data.type == "Fist"
        and string.find(string.lower(entity.Name), "titus", 1, true) ~= nil
      if titusFist then
        speedWait = { mode = "positive", formula = "titus-fist" }
      else
        windup, speedWait = weaponWindup(definition.kind, definition.name, data, track)
      end
      if (windup == nil and speedWait == nil) or (windup and windup < 0) then return nil end
      if speedWait then
        windup = deferredWeaponWindup(speedWait, track.Speed) or 0
      end
    end

    local length = data and data.length or 0
    local hitbox = { X = length * 2.1, Y = length * 2.1, Z = length * 2.1 }
    if evengardeSwing then
      hitbox = { X = 55, Y = 55, Z = 55 }
    elseif definition.kind == "running" then
      hitbox = {
        X = length * 2.5,
        Y = length * 2,
        Z = length * (data.type == "Twinblade" and 3.5 or 2.5),
      }
    elseif definition.kind == "aerial" then
      hitbox = { X = length * 2, Y = length * 3.5, Z = length * 3 }
    elseif definition.kind == "uppercut" then
      hitbox = { X = length * 2, Y = length * 2, Z = length * 2.2 }
    end

    local actionName = evengardeSwing
      and "Evengarde Sword Swing"
      or string.format("Dynamic %s %s", data.type, definition.name)
    local actions = {
      {
        _type = "Parry",
        when = (windup or 0) * 1000,
        name = actionName,
        hitbox = hitbox,
        ihbc = false,
      },
    }
    if not evengardeSwing and definition.kind == "running" and data.type == "Twinblade" then
      actions[2] = {
        _type = "Parry",
        when = (windup * 1000) + (300 / data.swingSpeed),
        name = actionName .. " 2",
        hitbox = hitbox,
        ihbc = false,
      }
    end

    local moduleName = weaponModuleByKind[definition.kind]
    local timing = AnimationTiming.new({
      _id = "rbxassetid://" .. id,
      name = definition.name,
      tag = "M1",
      imxd = tonumber(CFG.AutoParryMaxDist) or 28,
      actions = actions,
      smod = moduleName,
      umoa = false,
      iae = false,
      ieae = false,
      mat = 2000,
      nvfb = true,
    })

    if evengardeSwing then
      timing.ndfb = true
      timing.pbfb = true
      timing.bfht = 0.15
    elseif definition.kind == "basic" or definition.kind == "flourish" then
      closeWeaponFlags(timing, data.type, definition.kind == "flourish")
    elseif definition.kind == "running" then
      timing.ffh = true
      timing.duih = false
      timing.fhb = true
      timing.dp = false
      timing.nvfb = true
      timing.pfht = 0.15
    elseif definition.kind == "aerial" then
      timing.iae = false
      timing.ffh = true
      timing.dp = false
      timing.pfht = 0.15
      timing.phd = true
      timing.pfh = true
      timing.nvfb = true
    elseif definition.kind == "uppercut" then
      timing.ffh = true
      timing.phd = true
      timing.nvfb = true
      timing.pfht = 0.25
      timing.phds = 1
    end

    timing.katalystRangeOnly = false
    timing.katalystWeaponTiming = true
    timing.katalystWeaponKind = definition.kind
    timing.katalystSourceName = definition.name
    timing.katalystWeaponWait = speedWait
    timing.katalystTitusFist = speedWait and speedWait.formula == "titus-fist" or false
    timing.katalystEvengardeSwing = evengardeSwing
    return timing
  end

  local function finishWeaponTiming(timing, speed)
    local speedWait = timing and timing.katalystWeaponWait
    speed = tonumber(speed)
    if not speedWait or speed == nil then return false end

    local windup = deferredWeaponWindup(speedWait, speed)
    if not windup or windup < 0 then return false end

    local action = timing.actions:stack()[1]
    if not action then return false end
    action._when = windup * 1000
    if speedWait.formula == "titus-fist" then
      action.name = string.format("(%.2f) Titus M1 Windup", speed + 0.2)
    end
    timing.katalystWeaponWait = nil
    return true
  end

  local function tagFor(name, namedSource)
    name = tostring(name or "")
    local lower = string.lower(name)
    if m1Names[name] then return "M1" end
    if lower:find("critical", 1, true) or lower:find("crit", 1, true) then
      return "Critical"
    end
    if
      lower:find("m1", 1, true)
      or lower:find("swing", 1, true)
      or lower:find("slash", 1, true)
      or lower:find("stab", 1, true)
      or lower:find("punch", 1, true)
      or lower:find("jab", 1, true)
    then
      return "M1"
    end
    if namedSource then return "Mantra" end
    if
      lower:find("mantra", 1, true)
      or lower:find("spell", 1, true)
      or lower:find("cast", 1, true)
      or lower:find("beam", 1, true)
      or lower:find("eruption", 1, true)
      or lower:find("breath", 1, true)
      or lower:find("projectile", 1, true)
    then
      return "Mantra"
    end
    return "Undefined"
  end

  local function distanceDelayFor(key, entry, action)
    local value = action.dps or action.studDelay or action.delayPerStud
      or entry.dps or entry.studDelay or entry.delayPerStud
    if value == nil and MANTRA_STUD_DELAYS then
      local digits = tostring(key):match("%d+")
      value = MANTRA_STUD_DELAYS[key] or (digits and MANTRA_STUD_DELAYS[digits])
    end
    return tonumber(value) or 0
  end

  local function actionData(key, entry)
    local actions = {}
    local hasStartBlock = false
    local hasEndBlock = false
    for _, source in ipairs(entry) do
      if type(source) == "table" then
        hasStartBlock = hasStartBlock or source.action == "Start Block"
        hasEndBlock = hasEndBlock or source.action == "End Block"
      end
    end
    local hasBlockPair = hasStartBlock and hasEndBlock

    for index, source in ipairs(entry) do
      if type(source) == "table" then
        local actionType = tostring(source.action or "Parry")
        if actionType == "Teleport Up"
          or ((actionType == "Start Block" or actionType == "End Block") and not hasBlockPair)
        then
          actionType = "Parry"
        end
        local delay = tonumber(source.delay)
        if delay == nil then delay = 0.22 end
        local hitbox = source.hitbox
        local ignoreHitboxCheck = source.ihbc
        if type(ignoreHitboxCheck) ~= "boolean" then ignoreHitboxCheck = true end
        actions[#actions + 1] = {
          _type = actionType,
          when = delay * 1000,
          name = string.format("%s:%d", actionType, index),
          hitbox = type(hitbox) == "table" and hitbox or { X = 0, Y = 0, Z = 0 },
          ihbc = ignoreHitboxCheck,
          dps = distanceDelayFor(key, entry, source),
        }
      end
    end

    if #actions == 0 then
      local delay = tonumber(entry.delay)
      if delay == nil then delay = 0.22 end
      actions[1] = {
        _type = tostring(entry.action or "Parry"),
        when = delay * 1000,
        name = tostring(entry.action or "Parry") .. ":1",
        hitbox = { X = 0, Y = 0, Z = 0 },
        ihbc = true,
        dps = distanceDelayFor(key, entry, entry),
      }
    end
    return actions
  end

  local function makeTiming(key, source, namedSource)
    local entry = type(source) == "number" and { { action = "Parry", delay = source } } or source
    if type(entry) ~= "table" then return nil end

    if namedSource and m1Names[tostring(key)] then return nil end

    local identity = timingIdentity(key)
    local displayName = tostring((identity and identity[1]) or entry.name or key)
    local convertedActions = actionData(key, entry)
    local timing = AnimationTiming.new({
      _id = tostring(key),
      name = displayName,
      tag = tostring((identity and identity[2]) or entry.tag or tagFor(displayName, namedSource)),
      imdd = tonumber(entry.imdd) or 0,
      imxd = tonumber(entry.imxd) or tonumber(CFG.AutoParryMaxDist) or 28,
      punishable = tonumber(entry.punishable) or 0,
      after = tonumber(entry.after) or 0,
      duih = entry.duih == true,
      actions = convertedActions,
      smod = tostring(
        (identity and (identity[3] or identity[1]))
        or entry.smod
        or entry.name
        or displayName
      ),
      umoa = false,
      iae = S.ignoreAnimEnd == true or entry.iae == true,
      ieae = S.ignoreEarlyAnimEnd == true or entry.ieae == true,
      ha = entry.ha == true,
      mat = tonumber(entry.mat) or 2000,
      dp = entry.dp == true,
      rpue = entry.rpue == true,
      rsd = tonumber(entry.rsd) or 0,
      rpd = tonumber(entry.rpd) or 0,
      bfht = tonumber(entry.bfht) or 0.3,
      nbfb = entry.nbfb == true,
      nvfb = entry.nvfb == true,
    })

    for index, action in ipairs(timing.actions:stack()) do
      action.dps = convertedActions[index].dps
    end
    timing.katalystSourceName = (identity and identity[1]) or entry.name
    timing.katalystMaxDistance = tonumber(entry.imxd)
    timing.katalystRangeOnly = true
    return timing
  end

  local function makeAnimationPair()
    local internal = TimingContainer.new(AnimationTiming)
    local config = TimingContainer.new(AnimationTiming)
    local aliases = {}
    local weaponAnimations, weaponAnimationCount, observedAnims, observedDescendantCount = weaponAnimationRegistry()
    local weaponRetryStartedAt = nil
    local weaponRetryAttempts = 0
    local weaponRetryNextAt = 0
    local primaryCount = 0
    local namedCount = 0
    local learnedCount = 0
    local stats = {
      primary = 0,
      named = 0,
      learned = 0,
      weapon = weaponAnimationCount,
    }

    local function lazyWeaponDefinition(id)
      local definition = weaponAnimations[id]
      if definition then return definition end

      local now = os.clock()
      local assets = replicatedStorage:FindFirstChild("Assets")
      local anims = assets and assets:FindFirstChild("Anims")
      if now < weaponRetryNextAt and anims == observedAnims then return nil end

      local descendantCount = anims and #anims:GetDescendants() or 0
      local assetStateChanged = anims ~= observedAnims or descendantCount ~= observedDescendantCount
      if assetStateChanged then
        weaponRetryStartedAt = nil
        weaponRetryAttempts = 0
        weaponRetryNextAt = 0
      end

      weaponRetryStartedAt = weaponRetryStartedAt or now
      if weaponRetryAttempts >= WEAPON_REGISTRY_RETRY_LIMIT
        or now - weaponRetryStartedAt > WEAPON_REGISTRY_RETRY_WINDOW
      then
        return nil
      end

      weaponRetryAttempts = weaponRetryAttempts + 1
      weaponRetryNextAt = now + WEAPON_REGISTRY_RETRY_INTERVAL
      weaponAnimations, weaponAnimationCount, observedAnims, observedDescendantCount =
        weaponAnimationRegistry(weaponAnimations)
      stats.weapon = weaponAnimationCount
      return weaponAnimations[id]
    end

    local function addAlias(key, timing)
      if key == nil or tostring(key) == "" then return end
      local text = tostring(key)
      aliases[text] = timing
      aliases[string.lower(text)] = timing
      aliases[compact(text)] = timing
      local digits = text:match("%d+")
      if digits then
        aliases[digits] = timing
        aliases["rbxassetid://" .. digits] = timing
      end
    end

    local function add(key, entry, namedSource, learnedSource)
      local storageKey = tostring(key)
      if learnedSource and internal.timings[storageKey] ~= nil then
        learnedCount = learnedCount + 1
        return
      end

      local timing = makeTiming(key, entry, namedSource)
      if not timing then return end
      if internal.timings[storageKey] == nil then primaryCount = primaryCount + 1 end
      internal.timings[storageKey] = timing
      addAlias(storageKey, timing)
      addAlias(type(entry) == "table" and entry.name or nil, timing)
      if namedSource then namedCount = namedCount + 1 end
      if learnedSource then learnedCount = learnedCount + 1 end
    end

    for key, entry in next, TIMINGS or {} do
      add(key, entry, false, false)
    end
    for key, entry in next, NAMED_MANTRA_TIMINGS or {} do
      add(key, entry, true, false)
    end
    for key, entry in next, LEARNED_TIMINGS or {} do
      add(key, entry, false, true)
    end

    local pair = TimingContainerPair.new(internal, config)

    function pair:index(key)
      if key == nil then return nil end
      local text = tostring(PP_SCRAMBLE_STR(key))
      return aliases[text] or aliases[string.lower(text)] or aliases[compact(text)]
    end

    function pair:resolve(key, animationName, entity, track)
      local id = assetId(key)
      local weaponDefinition = id and lazyWeaponDefinition(id)
      if weaponDefinition then
        if S.ignoreM1s then return nil end
        return makeWeaponTiming(id, weaponDefinition, entity, track)
      end

      local identity = timingIdentity(key)
      local timing = self:index(key)
      local identityAlias = false
      if not timing and identity then
        timing = self:index(identity[1]) or self:index(identity[3])
        if not timing and identity[2] == "Mantra" then
          timing = self:index("Mantra")
        end
        identityAlias = timing ~= nil
      end
      timing = timing or self:index(animationName)
      if not timing then return nil end

      local runtimeName = tostring(animationName or "")
      local useRuntimeName = runtimeName ~= ""
        and string.lower(runtimeName) ~= "animation"
        and not identity
        and timing.katalystSourceName == nil
      local configuredLimit = tonumber(CFG.AutoParryMaxDist) or 28
      local explicitLimit = timing.katalystMaxDistance
      local effectiveLimit = explicitLimit and (
        explicitLimit > 50 and explicitLimit or math.min(configuredLimit, explicitLimit)
      ) or configuredLimit

      if not identityAlias and not useRuntimeName and timing.imxd == effectiveLimit then return timing end

      local resolved = timing:clone()
      if identityAlias then
        resolved._id = "rbxassetid://" .. id
        resolved.name = identity[1]
        resolved.tag = identity[2]
        resolved.smod = identity[3] or identity[1]
      elseif useRuntimeName then
        resolved.name = runtimeName
        resolved.smod = runtimeName
        resolved.tag = tagFor(runtimeName, false)
      end
      resolved.imxd = effectiveLimit
      resolved.katalystSourceName = identityAlias and identity[1] or timing.katalystSourceName
      resolved.katalystMaxDistance = explicitLimit
      resolved.katalystRangeOnly = timing.katalystRangeOnly
      local sourceActions = timing.actions:stack()
      for index, action in ipairs(resolved.actions:stack()) do
        action.dps = sourceActions[index].dps
      end
      return resolved
    end

    stats.primary = primaryCount
    stats.named = namedCount
    stats.learned = learnedCount
    return pair, stats
  end

  local function emptyPair(module)
    return TimingContainerPair.new(TimingContainer.new(module), TimingContainer.new(module))
  end

  function SaveManager.refresh()
    SaveManager.as, SaveManager.stats = makeAnimationPair()
  end

  function SaveManager.finishWeaponTiming(timing, speed)
    return finishWeaponTiming(timing, speed)
  end

  function SaveManager.init()
    SaveManager.refresh()
    SaveManager.es = emptyPair(EffectTiming)
    SaveManager.ps = emptyPair(PartTiming)
    SaveManager.ss = emptyPair(SoundTiming)
  end

  function SaveManager.detach()
    SaveManager.as = nil
    SaveManager.es = nil
    SaveManager.ps = nil
    SaveManager.ss = nil
    SaveManager.stats = nil
  end

  return SaveManager
end)
registerDefenseModule("Game/Latency", function(require)
-- Latency module.
local Latency        = {}

-- Services.
local stats          = game:GetService("Stats")

---@note: Perhaps one day, we can get better approximations for these.
--- These used to rely on GetNetworkPing which we assumed would be sending or atleast receiving delay.
--- That is incorrect, it is RakNet ping thereby being RTT.

-- Per-frame cache for raw rtt readings so repeated calls in the same frame do
-- not re-walk the Stats tree.
local cachedRttClock = -math.huge
local cachedRttValue = nil

-- EMA-smoothed rtt and jitter. Updated once per frame when rtt is sampled.
local smoothedRtt    = nil
local smoothedJitter = 0.0
local lastSampledRtt = nil
local lastKnownRtt   = nil

-- Smoothing factor for the EMA (~0.2 roughly matches a 4-5 frame window at 60fps).
local EMA_ALPHA      = 0.2
-- Floor used by safeRtt when we have never sampled a value yet.
local FALLBACK_RTT   = 0.05

---Raw rtt reading without any caching or smoothing. Internal helper.
---@return number?
local function rawRtt()
	local network = stats:FindFirstChild("Network")
	if not network then
		return
	end

	local serverStatsItem = network:FindFirstChild("ServerStatsItem")
	if not serverStatsItem then
		return
	end

	local dataPingItem = serverStatsItem:FindFirstChild("Data Ping")
	if not dataPingItem then
		return
	end

	return (dataPingItem:GetValue() / 1000)
end

---Sample the network stats at most once per frame. Updates the smoothed rtt
---and jitter estimates when a new value is available.
---@return number?
local function sampleRtt()
	local now = os.clock()
	if now - cachedRttClock <= 0.0 then
		return cachedRttValue
	end

	local value = rawRtt()
	cachedRttClock = now
	cachedRttValue = value

	if typeof(value) ~= "number" then
		return value
	end

	lastKnownRtt = value

	if smoothedRtt == nil then
		smoothedRtt    = value
		smoothedJitter = 0.0
	else
		local delta    = math.abs(value - (lastSampledRtt or value))
		smoothedRtt    = smoothedRtt + EMA_ALPHA * (value - smoothedRtt)
		smoothedJitter = smoothedJitter + EMA_ALPHA * (delta - smoothedJitter)
	end

	lastSampledRtt = value
	return value
end

---Get data ping.
---@note: https://devforum.roblox.com/t/in-depth-information-about-robloxs-remoteevents-instance-replication-and-physics-replication-w-sources/1847340
---@note: The forum post above is misleading, not only is it the RTT time, please note that this also takes into account all delays like frame time.
---@note: This is our round-trip time (e.g double the ping) since we have a receiving delay (replication) and a sending delay when we send the input to the server.
---@todo: For every usage, the sending delay needs to be continously updated. The receiving one must be calculated once at initial send for AP ping compensation.
---@return number
function Latency.rtt()
	return sampleRtt()
end

---Get receiving delay.
---@return number
function Latency.rdelay()
	return math.max((Latency.rtt() or 0.0) / 2, 0.0)
end

---Get sending delay.
---@return number
function Latency.sdelay()
	return math.max((Latency.rtt() or 0.0) / 2, 0.0)
end

---Safe rtt accessor that never returns nil. Falls back to the last known value
---if stats briefly unavailable, or to FALLBACK_RTT on cold start.
---@return number
function Latency.safeRtt()
	local value = sampleRtt()
	if typeof(value) == "number" then
		return value
	end

	if typeof(smoothedRtt) == "number" then
		return smoothedRtt
	end

	if typeof(lastKnownRtt) == "number" then
		return lastKnownRtt
	end

	return FALLBACK_RTT
end

---Smoothed rtt. Returns the EMA estimate, never nil.
---@return number
function Latency.srtt()
	sampleRtt()

	if typeof(smoothedRtt) == "number" then
		return smoothedRtt
	end

	return Latency.safeRtt()
end

---Smoothed receive delay variant. Pads the smoothed rtt/2 by the current
---jitter estimate so the caller can plan for the worst recent frame.
---@return number
function Latency.srdelay()
	local srtt   = Latency.srtt()
	local jitter = smoothedJitter or 0.0
	return math.max(srtt / 2 + jitter, 0.0)
end

---Smoothed send delay variant. Same padding logic as srdelay.
---@return number
function Latency.ssdelay()
	local srtt   = Latency.srtt()
	local jitter = smoothedJitter or 0.0
	return math.max(srtt / 2 + jitter, 0.0)
end

---Jitter estimate (absolute mean inter-sample rtt delta, EMA-smoothed).
---@return number
function Latency.jitter()
	sampleRtt()
	return smoothedJitter or 0.0
end

-- Return Latency module.
return Latency
end)

registerDefenseModule("Game/QueuedBlocking", function(require)
-- QueuedBlocking module. Allows of easy control of blocking without failure (e.g constant blocking randomly or w/e) and being frame-perfect.
local QueuedBlocking = {
	BLOCK_TYPE_DEFLECT = 1, -- For parry/deflect frames. This means it will get removed as soon as we are considered as blocking.
	BLOCK_TYPE_NORMAL = 2, -- For normal blocking. This means it will stay in the queue until dead time expires or manually removed.
}

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Signal
local Signal = require("Utility/Signal")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

-- Maids.
local qiMaid = Maid.new()

-- Queue.
local blockQueue = {}
-- Maintained length of blockQueue. Kept in sync by invoke / stop / empty so the
-- RenderStepped path does not need to iterate the queue just to count it.
local blockQueueCount = 0
local blockDispatched = false
-- Stable no-op mirror used until InputClient discovers its internal input table.
local blockInputMirror = { f = false }

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local runService = game:GetService("RunService")

local onRenderStepped
local fireServer = Instance.new("RemoteEvent").FireServer

local function dispatchBlock(blockRemote)
	if blockDispatched or blockQueueCount <= 0 or not blockRemote then
		return false
	end

	fireServer(blockRemote)
	blockDispatched = true
	return true
end

local function stopUpdateLoop()
	qiMaid.update = nil
end

local function startUpdateLoop()
	if qiMaid.update then
		return
	end

	qiMaid.update = Signal.new(runService.RenderStepped):connect("QueuedInputs_Update", onRenderStepped)
end

---Release block state when the final defense-owned demand ends.
---This is tied to queue ownership rather than a timeout: a real multi-hit
---threat keeps its entry, while the last release always sends the matching
---Unblock even if the replicated Blocking effect arrives late.
---@param reason string
local function releaseIdleBlock(reason)
	if blockQueueCount > 0 then
		return false
	end

	if StateListener.hblock() then
		blockDispatched = false
		stopUpdateLoop()
		return false
	end

	local inputData = InputClient.getInputData()
	if inputData then
		inputData["f"] = false
	end

	local unblockRemote = KeyHandling.getRemote("Unblock")
	local released = blockDispatched and unblockRemote ~= nil
	if released then
		unblockRemote:FireServer()
	end
	blockDispatched = false

	stopUpdateLoop()
	return released
end

---On render stepped.
onRenderStepped = (function()
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	local blockRemote = KeyHandling.getRemote("Block")
	if not blockRemote then
		return
	end

	local unblockRemote = KeyHandling.getRemote("Unblock")
	if not unblockRemote then
		return
	end

	local inputData = InputClient.getInputData() or blockInputMirror

	if StateListener.hblock() then
		return QueuedBlocking.empty("manual-block")
	end

	-- Are we blocking?
	local blocking = effectReplicatorModule:HasEffect("Blocking")

	-- Set up input data.
	inputData["f"] = true

	-- Process entries that need to be killed.
	local releasedDuringSweep = false
	for id, data in next, blockQueue do
		local dead = data.dt and os.clock() - data.start >= data.dt
		local deflected = data.type == QueuedBlocking.BLOCK_TYPE_DEFLECT and blocking

		if not deflected and not dead then
			continue
		end

		releasedDuringSweep = QueuedBlocking.stop(id, dead and "dead-time" or "deflected") or releasedDuringSweep
	end

	-- Use maintained count: QueuedBlocking.stop above may have decremented it.
	local blockQueueLength = blockQueueCount

	-- Handle blocking input.
	inputData["f"] = blockQueueLength > 0
	if blockQueueLength <= 0 then
		if not releasedDuringSweep then
			releaseIdleBlock("render-idle")
		end
		return
	end

	if blocking then
		return true
	end

	if not effectReplicatorModule:FindEffect("Action") and not effectReplicatorModule:FindEffect("Knocked") then
		return dispatchBlock(blockRemote)
	end
end)

---Invoke a block action.
---@param type number The block type.
---@param id string Identifier tied to this action.
---@param dt number?
function QueuedBlocking.invoke(type, id, dt)
	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return false
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	local blockRemote = KeyHandling.getRemote("Block")
	if not blockRemote then
		Logger.warn("QueuedBlocking.invoke(...) - Missing block remote.")
		return false
	end

	local sprintFunction = InputClient.sprintFunctionCache
	local inputData = InputClient.getInputData()

	local bufferEffect = effectReplicatorModule:FindEffect("M1Buffering")

	if bufferEffect then
		bufferEffect:Remove()
	end

	if effectReplicatorModule:HasEffect("CastingSpell") then
		return false
	end

	local wasPresent = blockQueue[id] ~= nil
	blockQueue[id] = {
		start = os.clock(),
		type = type,
		dt = dt,
	}
	if not wasPresent then
		blockQueueCount = blockQueueCount + 1
	end
	dispatchBlock(blockRemote)
	startUpdateLoop()

	-- The Block/Unblock remotes own the server-visible block lifecycle. These
	-- local InputClient values only mirror that state when discovery succeeded;
	-- neither may suppress a frame-critical remote because its executor probe is
	-- unavailable or still pending.
	if inputData then
		inputData["f"] = true
	end

	if sprintFunction then
		pcall(sprintFunction, false)
	end
	return true
end

---Empty the block queue.
---@param reason string?
function QueuedBlocking.empty(reason)
	blockQueue = {}
	blockQueueCount = 0
	return releaseIdleBlock(reason or "empty")
end

---Stop a block action from the queue.
---@param id string The block action ID.
---@param reason string?
function QueuedBlocking.stop(id, reason)
	if not blockQueue[id] then
		return
	end

	-- Remove.
	blockQueue[id] = nil
	blockQueueCount = blockQueueCount - 1
	if blockQueueCount <= 0 then
		blockQueueCount = 0
		return releaseIdleBlock(reason or id)
	end

	return false
end

function QueuedBlocking.count()
	return blockQueueCount
end

---Initialize QueuedBlocking module.
function QueuedBlocking.init()
	qiMaid:clean()
	blockQueue = {}
	blockQueueCount = 0
	blockDispatched = false
	blockInputMirror.f = false
end

---Detach QueuedBlocking module.
function QueuedBlocking.detach()
	QueuedBlocking.empty("detach")
	qiMaid:clean()
end

-- Return QueuedBlocking module.
return QueuedBlocking
end)
registerDefenseModule("Features/Combat/Objects/Defender", function(require)
---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.InputClient
local InputClient = require("Game/InputClient")

---@module Features.Combat.Objects.Task
local Task = require("Features/Combat/Objects/Task")

---@module Game.QueuedBlocking
local QueuedBlocking = require("Game/QueuedBlocking")

---@module Game.KeyHandling
local KeyHandling = require("Game/KeyHandling")

---@module Utility.Maid
local Maid = require("Utility/Maid")

---@module Game.Timings.ModuleManager
local ModuleManager = require("Game/Timings/ModuleManager")

---@module Utility.TaskSpawner
local TaskSpawner = require("Utility/TaskSpawner")

---@module Features.Combat.Targeting
local Targeting = require("Features/Combat/Targeting")

---@module Features.Combat.Objects.ValidationOptions
local ValidationOptions = require("Features/Combat/Objects/ValidationOptions")

---@module Features.Combat.EntityHistory
local EntityHistory = require("Features/Combat/EntityHistory")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.OriginalStore
local OriginalStore = require("Utility/OriginalStore")

---@module Features.Combat.StateListener
local StateListener = require("Features/Combat/StateListener")

---@module Game.Latency
local Latency = require("Game/Latency")

---@class Defender
---@field tasks Task[]
---@field tmaid Maid Cleaned up every clean cycle.
---@field rhook table<string, function> Hooked functions that we can restore on clean-up.
---@field markers table<string, boolean> Blocking markers for unknown length timings. If the entry exists and is true, then we're blocking.
---@field maid Maid
local Defender = {}
Defender.__index = Defender
Defender.__type = "Defender"
local defenderSerial = 0

-- Services.
local replicatedStorage = game:GetService("ReplicatedStorage")
local userInputService = game:GetService("UserInputService")
local players = game:GetService("Players")
local textChatService = game:GetService("TextChatService")

-- Constants.
local MAX_REPEAT_WAIT = 10.0
local PREDICTION_LENIENCY_MULTI = 10.0
local MAX_LOOKBACK = 0.5

---@module Game.Objects.DodgeOptions
local DodgeOptions = require("Game/Objects/DodgeOptions")

---Fetch distance.
---@param from Model? | BasePart?
---@return number?
Defender.distance = (function(_, from)
	if not from then
		return
	end

	local entRootPart = from

	if from:IsA("Model") then
		entRootPart = from:FindFirstChild("HumanoidRootPart")
	end

	if not entRootPart then
		return
	end

	local localCharacter = players.LocalPlayer.Character
	if not localCharacter then
		return
	end

	local localRootPart = localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return
	end

	return (entRootPart.Position - localRootPart.Position).Magnitude
end)

---Find target - hookable function.
---@param self Defender
---@param entity Model
---@return Target?
Defender.target = (function(self, entity)
	return Targeting.find(entity)
end)

---Get extrapolated seconds.
---@param self Defender
---@param timing AnimationTiming
---@return number
Defender.fsecs = (function(self, timing)
	local player = players:GetPlayerFromCharacter(self.entity)
	local sd = (player and player:GetAttribute("AveragePing") or 50.0) / 2000
	-- Previous implementation summed sd (attacker->server receive delay) and
	-- rdelay (server->us receive delay), double-counting replication when ping
	-- was high. max() keeps the worst-case single leg without over-predicting.
	return (timing.pfht or 0.15) + math.max(sd, Latency.safeRtt() * 0.5)
end)

---Start repeat until parry end.
---@param self Defender
---@param ref Model|Part
---@param timing Timing
---@param info RepeatInfo
Defender.srpue = (function(self, ref, timing, info)
	if timing.umoa or timing.cbm then
		timing["_rpd"] = PP_SCRAMBLE_RE_NUM(timing["_rpd"])
		timing["_rsd"] = PP_SCRAMBLE_RE_NUM(timing["_rsd"])
		timing["imdd"] = PP_SCRAMBLE_RE_NUM(timing["imdd"])
		timing["imxd"] = PP_SCRAMBLE_RE_NUM(timing["imxd"])
	end

	local cache = {
		["name"] = timing.name,
		["imdd"] = PP_SCRAMBLE_NUM(timing.imdd),
		["imxd"] = PP_SCRAMBLE_NUM(timing.imxd),
		["rsd"] = timing:rsd(),
		["rpd"] = timing:rpd(),
	}

	local target = self:target(ref)
	local part = target and target.root or CFrame.new()

	if ref:IsA("Part") then
		part = ref
	end

	local options = HitboxOptions.new(part, timing)
	options.spredict = not timing.duih
	options.ptime = self:fsecs(timing)
	options.entity = ref:IsA("Model") and target or nil
	options:ucache()

	-- Start RPUE.
	self:mark(Task.new(string.format("RPUE_%s_%i", timing.name, 0), function()
		return cache["rsd"] - info.irdelay - Latency.sdelay()
	end, timing.punishable, timing.after, self.rpue, self, ref, timing, info, cache, options))
end)

---Repeat until parry end.
---@param self Defender
---@param ref Model|Part
---@param timing Timing
---@param info RepeatInfo
---@param cache table Cache table for RPUE to prevent unnecessary recalculations.
---@param options HitboxOptions
Defender.rpue = (function(self, ref, timing, info, cache, options)
	local distance = self:distance(ref)
	if not distance then
		return
	end

	if not self:rc(info) then
		return
	end

	local target = ref:IsA("Model") and self:target(ref) or true
	local success = false

	options.part = ref:IsA("Part") and ref or (target and target.root)
	options.cframe = not options.part and CFrame.new()

	if timing.duih and target then
		success = self:hc(options, info)
	end

	local within = (distance >= cache.imdd and distance <= cache.imxd)

	if timing then
		success = within
	end

	info.index = info.index + 1

	self:mark(Task.new(string.format("RPUE_%s_%i", timing.name, info.index), function()
		return cache.rpd - info.irdelay - Latency.sdelay()
	end, timing.punishable, timing.after, self.rpue, self, ref, timing, info, cache, options))

	if not target then
		return
	end

	if not success then
		return
	end

	self:parry(timing, nil)
end)

---Check if we're in a valid state to proceed with action handling. Extend me.
---@param self Defender
---@param options ValidationOptions
---@return boolean
Defender.valid = (function(self, options)
	local timing = options.timing
	local selectedFilters = Configuration.expectOptionValue("AutoDefenseFilters") or {}

	if selectedFilters["Disable While Holding Block"] and StateListener.hblock() then
		return false
	end

	local chatInputBarConfiguration = textChatService:FindFirstChildOfClass("ChatInputBarConfiguration")

	if
		selectedFilters["Disable When Textbox Focused"]
		and (userInputService:GetFocusedTextBox() or (chatInputBarConfiguration and chatInputBarConfiguration.IsFocused))
	then
		return false
	end

	if selectedFilters["Disable While Using Sightless Beam"] and StateListener.csb() then
		return false
	end

	if
		selectedFilters["Disable When Window Not Active"]
		and type(iswindowactive) == "function"
		and not iswindowactive()
	then
		return false
	end

	if selectedFilters["Disable During Chime Countdown"] and StateListener.ccd() then
		return false
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return false
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	local actionType = options.action and options.action._type or "N/A"
	local isCrouchOrSlide = actionType == "Start Crouch"
		or actionType == "End Crouch"
		or actionType == "Start Slide"
		or actionType == "End Slide"

	if
		not Configuration.expectToggleValue("BlatantRoll")
		or (actionType ~= PP_SCRAMBLE_STR("Dodge") and actionType ~= PP_SCRAMBLE_STR("Forced Full Dodge"))
	then
		if not isCrouchOrSlide and StateListener.astun() then
			return false
		end

		if effectReplicatorModule:FindEffect("Knocked") then
			return false
		end
	end

	if timing.tag == "M1" and selectedFilters["Filter Out M1s"] then
		return false
	end

	if timing.tag == "Mantra" and selectedFilters["Filter Out Mantras"] then
		return false
	end

	if timing.tag == "Critical" and selectedFilters["Filter Out Criticals"] then
		return false
	end

	if timing.tag == "Undefined" and selectedFilters["Filter Out Undefined"] then
		return false
	end

	return true
end)

---Check if any parts that are in our filter were hit.
---@note: Solara fallback.
local function checkParts(parts, filter)
	for _, part in next, parts do
		for _, fpart in next, filter do
			if part ~= fpart and not part:IsDescendantOf(fpart) then
				continue
			end

			return true
		end
	end

	return false
end

---Run hitbox check. Returns wheter if the hitbox is being touched.
---@param self Defender
---@param cframe CFrame
---@param fd boolean
---@param soffset number
---@param size Vector3
---@param filter Instance[]
---@param shape Enum.PartType
---@return boolean?, CFrame?
Defender.hitbox = (function(self, cframe, fd, soffset, size, filter, shape)
	local shouldManualFilter = getexecutorname
		and (getexecutorname():match("Solara") or getexecutorname():match("Xeno"))

	local overlapParams = OverlapParams.new()
	overlapParams.FilterDescendantsInstances = shouldManualFilter and {} or filter
	overlapParams.FilterType = shouldManualFilter and Enum.RaycastFilterType.Exclude or Enum.RaycastFilterType.Include

	local character = players.LocalPlayer.Character
	if not character then
		return nil, nil
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return nil, nil
	end

	-- Used CFrame.
	local usedCFrame = cframe

	if fd then
		usedCFrame = usedCFrame * CFrame.new(0, 0, -(size.Z / 2))
	end

	if soffset and soffset ~= 0 then
		usedCFrame = usedCFrame * CFrame.new(0, 0, soffset)
	end

	-- Create simulation part.
	local simulationPart = Instance.new("Part")
	simulationPart.Size = size
	simulationPart.Material = Enum.Material.ForceField
	simulationPart.Shape = shape
	simulationPart.CFrame = usedCFrame

	if shape == Enum.PartType.Cylinder then
		simulationPart.CFrame = usedCFrame * CFrame.Angles(0, 0, math.rad(90))
	end

	-- Parts in bounds.
	local parts = workspace:GetPartsInPart(simulationPart, overlapParams)

	-- Return result.
	return shouldManualFilter and checkParts(parts, filter) or #parts > 0, usedCFrame
end)

---Check initial state.
---@param self Defender
---@param from Model? | BasePart?
---@param pair TimingContainerPair
---@param name string
---@param key string
---@return Timing?
Defender.initial = (function(self, from, pair, name, key)
	-- Find timing.
	local timing = pair:index(key)

	-- Fetch distance.
	local distance = self:distance(from)
	if not distance then
		return nil
	end

	-- Check for distance; if we have a timing.
	if timing then
		local md = PP_SCRAMBLE_NUM(timing.imdd)

		if md <= 0.01 then
			md = 0.0
		end

		if distance < md or distance > PP_SCRAMBLE_NUM(timing.imxd) then
			return nil
		end
	end

	if not timing then
		return false
	end

	-- Return timing.
	return timing
end)

---Repeat conditional.
---@param self Defender
---@param info RepeatInfo
---@return boolean
Defender.rc = (function(self, info)
	if os.clock() - info.start >= MAX_REPEAT_WAIT then
		return false
	end

	return true
end)

---Handle delay until in hitbox.
---@param self Defender
---@param options HitboxOptions
---@param info RepeatInfo
---@return boolean
Defender.duih = (function(self, options, info)
	local clone = options:clone()
	clone:ucache()

	while task.wait() do
		if not self:rc(info) then
			return false
		end

		if not self:hc(clone, nil) then
			continue
		end

		return true
	end
end)

---Handle hitbox check options.
---@param self Defender
---@param options HitboxOptions
---@param info RepeatInfo? Pass this in if you want to use the delay until in hitbox.
---@return boolean
Defender.hc = (function(self, options, info)
	local action = options.action
	local timing = options.timing

	-- Run basic validation.
	local character = players.LocalPlayer.Character
	if not character then
		return false
	end

	local root = character:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	if action and action.ihbc then
		return true
	end

	-- If we have info, then we want to delay until in hitbox.
	if info then
		return self:duih(options, info)
	end

	-- Fetch the data that we need.
	local hitbox = options:hitbox()
	local eposition = options.spredict and options:extrapolate() or nil
	local position = options:pos()
	local pt = timing.htype or Enum.PartType.Block

	-- Run hitbox check.
	local result = self:hitbox(position, timing.fhb, timing.hso, hitbox, options.filter, pt)

	if not options.spredict or result then
		return result
	end

	-- Run prediction check. Clamp lookback so rtt spikes cannot reach into
	-- ancient history (pre-MAX_LOOKBACK samples are effectively meaningless).
	local lookback = math.min(Latency.safeRtt() * PREDICTION_LENIENCY_MULTI, MAX_LOOKBACK)
	local closest = EntityHistory.pclosest(players.LocalPlayer, os.clock() - lookback)
	if not closest then
		return false
	end

	local store = OriginalStore.new()

	-- Run check.
	store:run(root, "CFrame", closest, function()
		result = self:hitbox(eposition, timing.fhb, timing.hso, hitbox, options.filter, pt)
	end)

	-- Return result.
	return result
end)

---Handle action.
---@param self Defender
---@param timing Timing
---@param action Action
---@param sourceTrack AnimationTrack?
---@param sourceOccurrence number?
---@param blockRequestId string?
Defender.handle = (function(self, timing, action, sourceTrack, sourceOccurrence, blockRequestId)
	local actionType = PP_SCRAMBLE_STR(action._type)

	if actionType == "End Block" then
		QueuedBlocking.stop(blockRequestId or self.blockRequestId, "end-block")
	end

	if actionType ~= "End Block" then
		local options = ValidationOptions.new(action, timing)
		options.track = sourceTrack
		options.occurrence = sourceOccurrence

		if not self:valid(options) then
			return
		end
	end

	if sourceTrack and sourceOccurrence and type(self.markOccurrenceIssued) == "function" then
		self:markOccurrenceIssued(sourceTrack, sourceOccurrence)
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if actionType == "Start Block" then
		return QueuedBlocking.invoke(
			QueuedBlocking.BLOCK_TYPE_NORMAL,
			blockRequestId or self.blockRequestId,
			20.0
		)
	end

	local options = DodgeOptions.new()
	options.rollCancel = Configuration.expectToggleValue("RollCancel") and actionType ~= "Forced Full Dodge"
	options.rollCancelDelay = Configuration.expectOptionValue("RollCancelDelay") or 0.0
	options.direct = Configuration.expectToggleValue("BlatantRoll")

	if
		(actionType == "Dodge" or actionType == "Forced Full Dodge") and Configuration.expectToggleValue("ParryOnly")
	then
		actionType = "Parry"
	end

	if actionType == "Dodge" then
		return InputClient.dodge(options)
	end

	if actionType == "Forced Full Dodge" then
		return InputClient.dodge(options)
	end

	if actionType == "End Block" then
		return
	end

	if actionType == "Start Slide" then
		return InputClient.slide()
	end

	if actionType == "End Slide" then
		return InputClient.unslide()
	end

	if actionType == "Start Crouch" then
		return InputClient.crouch()
	end

	if actionType == "End Crouch" then
		return InputClient.uncrouch()
	end

	if actionType == "Jump" then
		local humanController = InputClient.getHumanController()
		if not humanController then
			return
		end

		if effectReplicatorModule:HasAny("Swimming", "Jumped", "NoJump", "Landed") then
			return
		end

		if not humanController:Jump() then
			return
		end

		return InputClient.ejump()
	end

	if actionType == "Teleport Up" then
		return
	end

	self:parry(timing, action)
end)

---Handle parry.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.parry = (function(self, timing, action)
	local options = DodgeOptions.new()
	options.rollCancel = Configuration.expectToggleValue("RollCancel")
	options.rollCancelDelay = Configuration.expectOptionValue("RollCancelDelay") or 0.0
	options.direct = Configuration.expectToggleValue("BlatantRoll")

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if StateListener.cparry() then
		return QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_DEFLECT, "Defender_Deflect", nil)
	end

	local canBlock = Configuration.expectToggleValue("DeflectBlockFallback")
		and not timing.nbfb
		and StateListener.cblock()

	local canVent = StateListener.cvent()
		and Configuration.expectToggleValue("VentFallback")
		and not timing.nvfb
		and not timing.rpue
		and self.__type ~= "Part"

	local canDodge = StateListener.cdodge()
		and Configuration.expectToggleValue("RollOnParryCooldown")
		and not timing.ndfb

	if canDodge then
		return InputClient.dodge(options)
	end

	if canVent then
		return InputClient.vent()
	end

	if canBlock then
		return QueuedBlocking.invoke(QueuedBlocking.BLOCK_TYPE_NORMAL, "Defender_BlockFallback", timing.bfht)
	end
end)

---Check if we have input blocking tasks.
---@param self Defender
---@return boolean
Defender.blocking = (function(self)
	for _, marker in next, self.markers do
		if not marker then
			continue
		end

		return true
	end

	for _, task in next, self.tasks do
		if not task:blocking() then
			continue
		end

		return true
	end
end)

---Mark task.
---@param task Task
function Defender:mark(task)
	self.tasks[#self.tasks + 1] = task
end

---Clean up hooks.
function Defender:clhook()
	for key, old in next, self.rhook do
		if not self[key] then
			continue
		end

		self[key] = old
	end

	self.rhook = {}
end

---Clean up all tasks.
---@param self Defender
Defender.clean = (function(self)
	-- Clean-up tasks.
	for idx, task in next, self.tasks do
		if task.forced and task.identifier ~= "Start Block" and task.identifier ~= "End Block" then
			continue
		end

		if
			task.identifier == "Start Crouch"
			or task.identifier == "End Crouch"
			or task.identifier == "Start Slide"
			or task.identifier == "End Slide"
		then
			continue
		end

		-- Cancel task.
		task:cancel()

		-- Clear in table.
		self.tasks[idx] = nil

		-- If we are cancelling a stop block or start block, then we want to end the block.
		if task.identifier ~= "End Block" and task.identifier ~= "Start Block" then
			continue
		end

		QueuedBlocking.stop(task.blockRequestId or self.blockRequestId, "task-cleanup")
	end

	self.blockRequestStacks = setmetatable({}, { __mode = "k" })

	-- Clean-up hooks.
	self:clhook()

	-- Clear temporary maid.
	self.tmaid:clean()

	-- Clear markers.
	self.markers = {}

end)

---Process module.
---@param self Defender
---@param timing Timing
---@varargs any
Defender.module = (function(self, timing, ...)
	-- Get loaded function.
	local lf = ModuleManager.modules[PP_SCRAMBLE_STR(timing.smod)]
	if not lf then
		return
	end

	-- Create identifier.
	local identifier = string.format("Defender_RunModule_%s", PP_SCRAMBLE_STR(timing.smod))

	-- Run module.
	TaskSpawner.spawnOwned(self.tmaid, identifier, lf, self, timing, ...)
end)

---Activate Prediction mantra instead of parrying.
---@param self Defender
---@param timing Timing
---@param action Action
---@param sourceTrack AnimationTrack?
---@param sourceOccurrence number?
Defender.prediction = (function(self, timing, action, sourceTrack, sourceOccurrence)
	-- Throw bypasses all counters.
	if PP_SCRAMBLE_STR(timing.smod) == "Throw" then
		return
	end

	-- Only use against players.
	if not players:GetPlayerFromCharacter(self.entity) then
		return
	end

	-- Windup delay.
	task.wait(0.1)

	local options = ValidationOptions.new(action, timing)
	options.track = sourceTrack
	options.occurrence = sourceOccurrence
	if not self:valid(options) then
		return
	end

	-- Feint check.
	local checkTrack = sourceTrack or self.track
	if self.__type == "Animation" and checkTrack and self:stopped(checkTrack, timing, nil, sourceOccurrence) then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	local predictionMantra = backpack and backpack:FindFirstChild("Mantra:PredictionIntelligence{{Prediction}}")

	if not character then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if not effectReplicatorModule then
		return
	end

	-- Hitbox check.
	if self.entity and self.__type == "Animation" then
		local root = self.entity:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local hoptions = HitboxOptions.new(root, timing)
		hoptions.spredict = not timing.duih and not timing.dp
		hoptions.ptime = self:fsecs(timing)
		hoptions.action = action
		hoptions.entity = self.entity
		hoptions:ucache()

		if not self:hc(hoptions, nil) and not self:fpc(timing, hoptions) then
			return
		end
	end

	if not predictionMantra then
		return
	end

	local onCooldown = false
	for _, effect in next, effectReplicatorModule.Effects do
		if
			effect.Class == "ToolLockCD"
			and effect.index
			and effect.index.Value
			and tostring(effect.index.Value):find("PredictionIntelligence")
		then
			onCooldown = true
			break
		end
	end

	if onCooldown then
		return
	end

	local activateMantra = character:FindFirstChild("CharacterHandler")
		and character.CharacterHandler:FindFirstChild("Requests")
		and character.CharacterHandler.Requests:FindFirstChild("ActivateMantra")

	if not activateMantra then
		return
	end

	activateMantra:FireServer(predictionMantra)
end)

---Activate Punishment mantra instead of parrying.
---@param self Defender
---@param timing Timing
---@param action Action
---@param sourceTrack AnimationTrack?
---@param sourceOccurrence number?
Defender.punishment = (function(self, timing, action, sourceTrack, sourceOccurrence)
	-- Throw bypasses all counters.
	if PP_SCRAMBLE_STR(timing.smod) == "Throw" then
		return
	end

	-- Only use against players.
	if not players:GetPlayerFromCharacter(self.entity) then
		return
	end

	-- Windup delay.
	task.wait(0.1)

	local options = ValidationOptions.new(action, timing)
	options.track = sourceTrack
	options.occurrence = sourceOccurrence
	if not self:valid(options) then
		return
	end

	-- Feint check.
	local checkTrack = sourceTrack or self.track
	if self.__type == "Animation" and checkTrack and self:stopped(checkTrack, timing, nil, sourceOccurrence) then
		return
	end

	local localPlayer = players.LocalPlayer
	local character = localPlayer and localPlayer.Character
	local backpack = localPlayer and localPlayer:FindFirstChild("Backpack")
	local punishmentMantra = backpack and backpack:FindFirstChild("Mantra:RevengeWeaponHeavy{{Punishment}}")

	if not character then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	local effectReplicatorModule = effectReplicator and require(effectReplicator)

	if not effectReplicatorModule then
		return
	end

	-- Defer to Prediction.
	if Configuration.expectToggleValue("UsePrediction") then
		local predictionMantra = backpack and backpack:FindFirstChild("Mantra:PredictionIntelligence{{Prediction}}")
		if predictionMantra then
			local predictionOnCooldown = false
			for _, effect in next, effectReplicatorModule.Effects do
				if
					effect.Class == "ToolLockCD"
					and effect.index
					and effect.index.Value
					and tostring(effect.index.Value):find("PredictionIntelligence")
				then
					predictionOnCooldown = true
					break
				end
			end

			if not predictionOnCooldown then
				return
			end
		end
	end

	-- Skip if already absorbing.
	if effectReplicatorModule:FindEffect("AbsorbCharge") then
		return
	end

	-- Hitbox check.
	if self.entity and self.__type == "Animation" then
		local root = self.entity:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local hoptions = HitboxOptions.new(root, timing)
		hoptions.spredict = not timing.duih and not timing.dp
		hoptions.ptime = self:fsecs(timing)
		hoptions.action = action
		hoptions.entity = self.entity
		hoptions:ucache()

		if not self:hc(hoptions, nil) and not self:fpc(timing, hoptions) then
			return
		end
	end

	if not punishmentMantra then
		return
	end

	local onCooldown = false
	for _, effect in next, effectReplicatorModule.Effects do
		if
			effect.Class == "ToolLockCD"
			and effect.index
			and effect.index.Value
			and tostring(effect.index.Value):find("RevengeWeaponHeavy")
		then
			onCooldown = true
			break
		end
	end

	if onCooldown then
		return
	end

	local activateMantra = character:FindFirstChild("CharacterHandler")
		and character.CharacterHandler:FindFirstChild("Requests")
		and character.CharacterHandler.Requests:FindFirstChild("ActivateMantra")

	if not activateMantra then
		return
	end

	activateMantra:FireServer(punishmentMantra)
end)

---Add a action to the defender object.
---@param self Defender
---@param timing Timing
---@param action Action
Defender.action = (function(self, timing, action)
	if timing.umoa and self.__type == "Animation" then
		timing.et = action["_when"]
	end

	if timing.umoa or timing.cbm then
		action["_type"] = PP_SCRAMBLE_STR(action["_type"])
		action["_when"] = PP_SCRAMBLE_RE_NUM(action["_when"])
		action["hitbox"] = Vector3.new(
			PP_SCRAMBLE_RE_NUM(action["hitbox"].X),
			PP_SCRAMBLE_RE_NUM(action["hitbox"].Y),
			PP_SCRAMBLE_RE_NUM(action["hitbox"].Z)
		)
	end

	-- Get initial receive delay.
	local rdelay = Latency.rdelay()
	local sourceTrack = self.__type == "Animation" and self.track or nil
	local sourceOccurrence = self.__type == "Animation" and self.occurrenceToken or nil
	-- A critical can be held briefly for authenticity confirmation. Keep this
	-- timing entry relative to the original animation start, not confirmation.
	local elapsed = self.occurrenceStartedAt and math.max(0, os.clock() - self.occurrenceStartedAt) or 0
	local distanceDelay = 0
	local delayPerStud = tonumber(action.dps) or tonumber(timing.dps) or 0
	if delayPerStud ~= 0 then
		local distance = self:distance(self.entity or self.owner)
		if distance and distance >= 12 then
			distanceDelay = distance * delayPerStud
		end
	end

	local actionType = PP_SCRAMBLE_STR(action._type)
	local blockRequestId = nil
	if actionType == "Start Block" then
		self.blockRequestSerial = self.blockRequestSerial + 1
		blockRequestId = string.format("%s:%d", self.blockRequestId, self.blockRequestSerial)
		local stack = self.blockRequestStacks[timing]
		if not stack then
			stack = {}
			self.blockRequestStacks[timing] = stack
		end
		stack[#stack + 1] = blockRequestId
	elseif actionType == "End Block" then
		local stack = self.blockRequestStacks[timing]
		if stack and #stack > 0 then
			blockRequestId = table.remove(stack)
		end
	end

	-- Add action.
	local atask = Task.new(PP_SCRAMBLE_STR(action._type), function()
		return action:when() + distanceDelay - rdelay - Latency.sdelay() - elapsed
	end, timing.punishable, timing.after, self.handle, self, timing, action, sourceTrack, sourceOccurrence, blockRequestId)
	atask.sourceTrack = sourceTrack
	atask.sourceOccurrence = sourceOccurrence
	atask.blockRequestId = blockRequestId

	if timing.forced then
		atask.forced = true
	end

	self:mark(atask)

	local isParryOrDodge = actionType == "Parry" or actionType == "Dodge"

	if Configuration.expectToggleValue("UsePrediction") and isParryOrDodge then
		local predictionTask = Task.new("Prediction", function()
			return action:when() + distanceDelay - rdelay - Latency.sdelay() - 0.2 - elapsed
		end, timing.punishable, timing.after, self.prediction, self, timing, action, sourceTrack, sourceOccurrence)
		predictionTask.sourceTrack = sourceTrack
		predictionTask.sourceOccurrence = sourceOccurrence
		self:mark(predictionTask)
	end

	if Configuration.expectToggleValue("UsePunishment") and isParryOrDodge then
		local punishmentTask = Task.new("Punishment", function()
			return action:when() + distanceDelay - rdelay - Latency.sdelay() - 0.2 - elapsed
		end, timing.punishable, timing.after, self.punishment, self, timing, action, sourceTrack, sourceOccurrence)
		punishmentTask.sourceTrack = sourceTrack
		punishmentTask.sourceOccurrence = sourceOccurrence
		self:mark(punishmentTask)
	end

end)

---Add actions from timing to defender object.
---@param self Defender
---@param timing Timing
Defender.actions = (function(self, timing)
	for _, action in ipairs(timing.actions:stack()) do
		self:action(timing, action)
	end
end)

---Safely replace a function in the defender object.
---@param key string
---@param new function
---@return boolean, function
function Defender:hook(key, new)
	-- Check if we're already hooked.
	if self.rhook[key] then
		Logger.warn("Cannot hook '%s' because it is already hooked.", key)
		return false, nil
	end

	-- Get our assumed old / target function.
	local old = self[key]

	-- Check if function.
	if typeof(old) ~= "function" then
		Logger.warn("Cannot hook '%s' because it is not a function.", key)
		return false, nil
	end

	-- Create hook.
	self[key] = new

	-- Add to hook table with the old function so we can restore it on clean-up.
	self.rhook[key] = old

	return true, old
end

---Detach defender object.
function Defender:detach()
	-- Clean self.
	self:clean()
	self.maid:clean()

	-- Set object nil.
	self = nil
end

---Create new Defender object.
---@return Defender
function Defender.new()
	local self = setmetatable({}, Defender)
	self.tasks = {}
	self.rhook = {}
	self.tmaid = Maid.new()
	self.maid = Maid.new()
	defenderSerial = defenderSerial + 1
	self.blockRequestSerial = 0
	self.blockRequestId = string.format("Defender_StartBlock:%d", defenderSerial)
	self.blockRequestStacks = setmetatable({}, { __mode = "k" })
	self.markers = {}
	return self
end

-- Return Defender module.
return Defender
end)

registerDefenseModule("Features/Combat/Objects/EffectDefender", function(require)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Utility.Logger
local Logger = require("Utility/Logger")

---@module Game.Latency
local Latency = require("Game/Latency")

---@class EffectDefender: Defender
---@field name string The name of the effect.
---@field data table The data of the effect.
local EffectDefender = setmetatable({}, { __index = Defender })
EffectDefender.__index = EffectDefender
EffectDefender.__type = "Effect"

-- Services.
local players = game:GetService("Players")

---Iteratively find effect owner from effect data.
---@param data table
---@return Model?
local findEffectOwner = (function(data)
	local live = workspace:FindFirstChild("Live")
	if not live then
		return
	end

	for _, value in next, data do
		if typeof(value) ~= "Instance" or value.Parent ~= live then
			continue
		end

		return value
	end
end)

---Check if we're in a valid state to proceed with the action.
---@param self EffectDefender
---@param options ValidationOptions
---@return boolean
EffectDefender.valid = (function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local timing = options.timing
	local action = options.action

	local humanoidRootPart = self.owner:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return false
	end

	local character = players.LocalPlayer.Character
	if not character then
		return false
	end

	if self.owner ~= players.LocalPlayer.Character then
		if not self:target(self.owner) then
			return false
		end

		local hoptions = HitboxOptions.new(humanoidRootPart, timing)
		hoptions.spredict = false
		hoptions.action = action
		hoptions:ucache()

		if not self:hc(hoptions, timing.duih and RepeatInfo.new(timing, Latency.rdelay()) or nil) then
			return false
		end
	end

	return true
end)

---Process effect.
---@param self EffectDefender
EffectDefender.process = (function(self)
	if not self.owner then
		return
	end

	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return
	end

	---@type EffectTiming?
	local timing = self:initial(self.owner, SaveManager.es, self.owner.Name, self.name)
	if not timing then
		return
	end

	if timing.flp and self.owner ~= players.LocalPlayer.Character then
		return Logger.warn(
			"EffectDefender.process - Effect '%s' is not on local player (%s) is being ignored.",
			self.name,
			tostring(self.owner)
		)
	end

	if timing.ilp and self.owner == players.LocalPlayer.Character then
		return
	end

	---@note: Clean up previous tasks that are still waiting or suspended because they're in a different track.
	self:clean()

	-- Handle module.
	if timing.umoa then
		return self:module(timing)
	end

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not timing.rpue then
		return self:actions(timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(timing, Latency.rdelay())
	self:srpue(self.entity, timing, info)
end)

---Create new EffectDefender object.
---@param name string
---@param data table
---@param dao function?
---@return EffectDefender
function EffectDefender.new(name, data, dao)
	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return nil
	end

	local owner = findEffectOwner(data)
	if not owner then
		return nil
	end

	if not SaveManager.es:index(name) then
		return nil
	end

	local self = setmetatable(Defender.new(), EffectDefender)
	self.name = name
	self.data = data or {}
	self.owner = owner
	self.detached = false
	self.onIdle = type(dao) == "function" and dao or nil
	self:process()

	return self
end

function EffectDefender:update()
	for index, actionTask in next, self.tasks do
		if actionTask.thread and coroutine.status(actionTask.thread) ~= "dead" then
			return
		end
		self.tasks[index] = nil
	end

	for _, ownedTask in next, self.tmaid._tasks do
		if typeof(ownedTask) == "thread" and coroutine.status(ownedTask) ~= "dead" then
			return
		end
	end

	local onIdle = self.onIdle
	self.onIdle = nil
	if onIdle then
		onIdle(self)
	end
end

function EffectDefender:detach()
	if self.detached then
		return
	end

	self.detached = true
	self.onIdle = nil
	Defender.detach(self)
end

-- Return EffectDefender module.
return EffectDefender
end)

registerDefenseModule("Features/Combat/Objects/HitboxOptions", function(require)
---@class HitboxOptions
---@note: Options for the hitbox check.
---@field part BasePart? If this is specified and it exists, it will be used for the position.
---@field cframe CFrame? Else, the part's CFrame will be used.
---@field timing Timing|AnimationTiming|SoundTiming
---@field action Action?
---@field cache Vector3 Cached hitbox size.
---@field filter Instance[]
---@field spredict boolean If true, a check will run for predicted positions.
---@field ptime number? The predicted time in seconds for extrapolation.
---@field entity Model? The entity for extrapolation.
local HitboxOptions = {}
HitboxOptions.__index = HitboxOptions

-- Services.
local players = game:GetService("Players")

---Cloned hitbox options.
---@return HitboxOptions
HitboxOptions.clone = (function(self)
	local options = setmetatable({}, HitboxOptions)
	options.action = self.action
	options.spredict = self.spredict
	options.entity = self.entity
	options.ptime = self.ptime
	options.filter = self.filter
	options.part = self.part
	options.cframe = self.cframe
	options.timing = self.timing
	return options
end)

---Update cache.
HitboxOptions.ucache = (function(self)
	if not self.timing then
		return error("HitboxOptions:update - no timing specified")
	end

	local hitbox = self.action and self.action.hitbox or self.timing.hitbox
	-- Dynamic timing modules commonly create an Action at runtime and only
	-- override its type and delay. Action.new() supplies Vector3.zero, which is
	-- an unset/default value rather than a usable volume. Preserve an explicit
	-- action hitbox when present, but inherit the timing volume for these
	-- otherwise valid dynamic actions so their final geometry check matches the
	-- initial timing check.
	if
		typeof(hitbox) == "Vector3"
		and hitbox.Magnitude <= 1e-6
		and self.timing.hitbox
		and self.timing.hitbox.Magnitude > 1e-6
	then
		hitbox = self.timing.hitbox
	end

	if self.timing.duih then
		hitbox = self.timing.hitbox
	end

	if not hitbox then
		self.cache = Vector3.new(0, 0, 0)
	else
		self.cache = Vector3.new(PP_SCRAMBLE_NUM(hitbox.X), PP_SCRAMBLE_NUM(hitbox.Y), PP_SCRAMBLE_NUM(hitbox.Z))
	end
end)

---Get the hitbox size.
---@return Vector3
HitboxOptions.hitbox = (function(self)
	if not self.cache then
		self:ucache()
	end

	return self.cache
end)

---Get extrapolated position.
---@return CFrame
HitboxOptions.extrapolate = (function(self)
	if not self.part then
		return error("HitboxOptions.extrapolate - unimplemented for CFrame")
	end

	if not self.ptime then
		return error("HitboxOptions.extrapolate - no predicted time specified")
	end

	-- Return the extrapolated position.
	return self.part.CFrame + (self.part.AssemblyLinearVelocity * self.ptime)
end)

---Get position.
---@return CFrame
HitboxOptions.pos = (function(self)
	if self.cframe then
		return self.cframe
	end

	if self.part then
		return self.part.CFrame
	end

	return error("HitboxOptions.pos - impossible condition")
end)

---Create new HitboxOptions object.
---@param target Instance|CFrame
---@param timing Timing|AnimationTiming|SoundTiming
---@param filter Instance[]?
---@return HitboxOptions
HitboxOptions.new = (function(target, timing, filter)
	local self = setmetatable({}, HitboxOptions)
	self.part = typeof(target) == "Instance" and target:IsA("BasePart") and target
	self.cframe = typeof(target) == "CFrame" and target
	self.timing = timing
	self.action = nil
	self.filter = filter or {}
	self.cache = Vector3.zero
	self.spredict = false
	self.entity = nil
	self.ptime = nil

	if not self.part and not self.cframe or not self.timing then
		return error("HitboxOptions: No part or CFrame or timing specified.")
	end

	self:ucache()

	if filter then
		return self
	end

	local character = players.LocalPlayer.Character
	if not character then
		return self
	end

	self.filter = { character }

	return self
end)

-- Return HitboxOptions module.
return HitboxOptions
end)

registerDefenseModule("Features/Combat/Objects/PartDefender", function(require)
---@module Features.Combat.Objects.Defender
local Defender = require("Features/Combat/Objects/Defender")

---@module Game.Timings.SaveManager
local SaveManager = require("Game/Timings/SaveManager")

---@module Features.Combat.Objects.RepeatInfo
local RepeatInfo = require("Features/Combat/Objects/RepeatInfo")

---@module Features.Combat.Objects.HitboxOptions
local HitboxOptions = require("Features/Combat/Objects/HitboxOptions")

---@module Utility.Configuration
local Configuration = require("Utility/Configuration")

---@module Game.Latency
local Latency = require("Game/Latency")

---@class PartDefender: Defender
---@field part BasePart
---@field timing PartTiming
---@field touched boolean Determines whether if we touched the timing in the past.
local PartDefender = setmetatable({}, { __index = Defender })
PartDefender.__index = PartDefender
PartDefender.__type = "Part"

-- Services.
local players = game:GetService("Players")

---Get CFrame.
---@param self PartDefender
---@return CFrame
PartDefender.cframe = (function(self)
	return self.timing.uhc and self.part.CFrame or CFrame.new(self.part.Position)
end)

---Check if we're in a valid state to proceed with the action.
---@param self PartDefender
---@param options ValidationOptions
---@return boolean
PartDefender.valid = (function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local timing = options.timing
	local action = options.action

	local character = players.LocalPlayer.Character
	if not character then
		return false
	end

	local hoptions = HitboxOptions.new(self.part, timing)
	hoptions.spredict = false
	hoptions.action = action
	hoptions:ucache()

	if not timing.duih or timing.umoa then
		if not self:hc(hoptions, timing.duih and RepeatInfo.new(timing, Latency.rdelay()) or nil) then
			return false
		end
	end

	return true
end)

---Update PartDefender object.
---@param self PartDefender
PartDefender.update = (function(self)
	-- Skip if we're not handling delay until in hitbox or we want to use modules.
	if not self.timing.duih or self.timing.umoa then
		return
	end

	-- Deny updates if we already have actions in the queue.
	if #self.tasks > 0 then
		return
	end

	local localPlayer = players.LocalPlayer
	if not localPlayer then
		return
	end

	local character = localPlayer.Character
	if not character then
		return
	end

	local hb = self.timing.hitbox

	hb = Vector3.new(PP_SCRAMBLE_NUM(hb.X), PP_SCRAMBLE_NUM(hb.Y), PP_SCRAMBLE_NUM(hb.Z))

	-- Get current hitbox state.
	---@note: If we're using PartDefender, why perserve rotation? It's likely wrong or gonna mess us up.
	local touching = self:hitbox(
		self:cframe(),
		self.timing.fhb,
		self.timing.hso,
		hb,
		{ character },
		self.timing.htype or Enum.PartType.Block
	)

	-- Deny updates if we're not touching the part.
	if not touching then
		return
	end

	-- Deny updates if the we were touching the part last and we are touching it now.
	if self.touched and touching then
		return
	end

	-- Ok, set the new state.
	self.touched = touching

	-- Clean all previous tasks. Just to be safe. We already check if it's empty... so.
	self:clean()

	---@note: Start processing the timing. Add the actions if we're not RPUE.
	if not self.timing.rpue then
		return self:actions(self.timing)
	end

	-- Start RPUE.
	local info = RepeatInfo.new(self.timing, Latency.rdelay())
	self:srpue(self.entity, self.timing, info)
end)

---Create new PartDefender object.
---@param part BasePart
---@param timing PartTiming?
---@return PartDefender?
function PartDefender.new(part, timing)
	if not Configuration.expectToggleValue("EnableAutoDefense") then
		return nil
	end

	local okey = nil

	-- Hotfix for now; too lazy to do it the animation way.
	if part.Name:match("VengefulSlash") then
		okey = "VengefulSlashes"
	end

	local self = setmetatable(Defender.new(), PartDefender)
	self.part = part
	self.timing = timing or self:initial(part, SaveManager.ps, nil, okey or part.Name)
	self.touched = false

	-- Handle no timing.
	if not self.timing then
		return nil
	end

	-- Handle module.
	if self.timing.umoa then
		self:module(self.timing)
	end

	-- Handle no hitbox delay.
	if self.timing.umoa or self.timing.duih then
		return self
	end

	local info = RepeatInfo.new(self.timing, Latency.rdelay())

	if self.timing.rpue then
		self:srpue(self.entity, self.timing, info)
	else
		self:actions(self.timing)
	end

	-- Return self.
	return self
end

-- Return PartDefender module.
return PartDefender
end)

registerDefenseModule("Features/Combat/Objects/RepeatInfo", function(require)
---@note: Typed object that represents information. It's not really a true class but just needs to store the correct data.
---@class RepeatInfo
---@field track AnimationTrack?
---@field occurrence number?
---@field timing Timing
---@field start number
---@field index number
