registerDefenseModule("Features/Combat/Objects/AttackAuthenticator", function(require)
local AttackAuthenticator = {}
AttackAuthenticator.__index = AttackAuthenticator

local MAX_CANDIDATES = 32
local MAX_EVIDENCE = 64
local MAX_BASELINE_SAMPLES = 24

local FEATURE_NAMES = {
	"density",
	"overlap",
	"overdue",
	"mismatch",
	"transition",
	"deficit",
}

local FEATURE_BOOTSTRAP = {
	density = 1,
	overlap = 1,
	overdue = 0,
	mismatch = 0,
	transition = 0,
	deficit = 0,
}

local FEATURE_TOLERANCE = {
	density = 0.75,
	overlap = 0.75,
	overdue = 0.50,
	mismatch = 0.35,
	transition = 0.35,
	deficit = 0.75,
}

local function copyAndSort(values)
	local copy = {}
	for index, value in next, values do
		copy[index] = value
	end
	table.sort(copy)
	return copy
end

local function median(values)
	if #values == 0 then
		return nil
	end

	local sorted = copyAndSort(values)
	local middle = math.floor(#sorted / 2)
	if #sorted % 2 == 1 then
		return sorted[middle + 1]
	end

	return (sorted[middle] + sorted[middle + 1]) / 2
end

local function medianAbsoluteDeviation(values, center)
	if #values == 0 or center == nil then
		return nil
	end

	local deviations = {}
	for _, value in next, values do
		deviations[#deviations + 1] = math.abs(value - center)
	end
	return median(deviations)
end

local function removeArrayValue(array, value)
	for index = #array, 1, -1 do
		if array[index] == value then
			table.remove(array, index)
			return
		end
	end
end

local function categoryCompatible(candidate, evidence)
	local families = evidence.families
	if not families then
		return true
	end

	if families[candidate.category] == true then
		return true
	end

	local weaponFamilies = {
		["weapon-m1"] = true,
		["weapon-critical"] = true,
		["weapon-special"] = true,
	}
	return evidence.allowWeaponFamilyBridge == true
		and weaponFamilies[candidate.category] == true
		and weaponFamilies[evidence.exactFamily] == true
end

local function weaponKey(context)
	local weapon = context.weaponContext
	if not weapon then
		return "unknown"
	end

	return table.concat({
		tostring(weapon.weaponName or weapon.primaryWeapon or "unknown"),
		tostring(weapon.weaponClass or "unknown"),
		tostring(weapon.weaponType or "unknown"),
	}, "|")
end

local function compactActionText(value)
	return string.lower(tostring(value or "")):gsub("[^%w]", "")
end

local GENERIC_ACTION_TOKENS = {
	action = true,
	attack = true,
	cast = true,
	charge = true,
	fire = true,
	flame = true,
	frost = true,
	gale = true,
	go = true,
	ice = true,
	lightning = true,
	mantra = true,
	new = true,
	recall = true,
	release = true,
	shadow = true,
	start = true,
	startup = true,
	wind = true,
	windup = true,
}

local function actionTokens(value)
	local text = tostring(value or "")
	text = string.gsub(text, "(%l)(%u)", "%1 %2")
	text = string.gsub(text, "(%a)(%d)", "%1 %2")
	text = string.gsub(text, "(%d)(%a)", "%1 %2")
	text = string.lower(text)

	local tokens = {}
	for token in string.gmatch(text, "%w+") do
		if #token >= 4 and not GENERIC_ACTION_TOKENS[token] then
			tokens[token] = true
		end
	end
	return tokens
end

local function sharedEdgeLength(left, right, fromEnd)
	local limit = math.min(#left, #right)
	local matched = 0
	for index = 1, limit do
		local leftIndex = fromEnd and (#left - index + 1) or index
		local rightIndex = fromEnd and (#right - index + 1) or index
		if string.sub(left, leftIndex, leftIndex) ~= string.sub(right, rightIndex, rightIndex) then
			break
		end
		matched = matched + 1
	end
	return matched
end

local function timingActionCompatible(candidate, actionKey, actionAliases)
	local expectedValues = { actionKey }
	for key, value in next, actionAliases or {} do
		if typeof(key) == "number" then
			expectedValues[#expectedValues + 1] = value
		elseif value == true then
			expectedValues[#expectedValues + 1] = key
		else
			expectedValues[#expectedValues + 1] = value
		end
	end

	local expectedTokens = {}
	for _, expectedValue in next, expectedValues do
		for token in next, actionTokens(expectedValue) do
			expectedTokens[token] = true
		end
	end

	for _, identity in next, candidate.timingActionNames or {} do
		local actual = compactActionText(identity)
		if #actual < 4 then
			continue
		end

		for _, expectedValue in next, expectedValues do
			local expected = compactActionText(expectedValue)
			if #expected < 4 then
				continue
			end

			if actual == expected then
				return true
			end

			local shorter = math.min(#actual, #expected)
			local contains = string.find(actual, expected, 1, true) ~= nil
				or string.find(expected, actual, 1, true) ~= nil
			if contains and shorter / math.max(#actual, #expected) >= 0.6 then
				return true
			end

			local prefix = sharedEdgeLength(actual, expected, false)
			local suffix = sharedEdgeLength(actual, expected, true)
			if prefix >= 3 and suffix >= 3 and (prefix + suffix) / shorter >= 0.75 then
				return true
			end
		end

		for token in next, actionTokens(identity) do
			if expectedTokens[token] then
				return true
			end
		end
	end

	return false
end

AttackAuthenticator.timingActionCompatible = timingActionCompatible

local function durationCompatibility(candidate, evidence)
	if not evidence.duration or not candidate.expectedDuration or candidate.expectedDuration <= 0 then
		return true, false, math.huge
	end

	local difference = math.abs(candidate.expectedDuration - evidence.duration)
	local scale = math.max(candidate.expectedDuration, evidence.duration, 0.01)
	local ratio = difference / scale

	return ratio <= 0.75, ratio <= 0.35, ratio
end

local function trackProgresses(candidate, now, evidence)
	if candidate.recoveredIngress and evidence and evidence.authoritative then
		return true
	end

	local track = candidate.track
	if not track or not track.IsPlaying then
		return false, "track-not-playing"
	end

	local target = tonumber(track.WeightTarget) or 0
	local position = tonumber(track.TimePosition) or 0
	local weight = tonumber(track.WeightCurrent) or 0
	if target <= 0 then
		return false, "track-target-weight-zero"
	end

	local samples = candidate.progressionSamples
	samples[#samples + 1] = {
		at = now,
		position = position,
		weight = weight,
		target = target,
		speed = tonumber(track.Speed) or 0,
	}
	while #samples > 8 do
		table.remove(samples, 1)
	end

	local initial = samples[1]
	local positionAdvanced = position > candidate.initialTimePosition + 1e-4
	local weightAdvanced = initial and weight > initial.weight + 1e-3

	if positionAdvanced or weightAdvanced or now - candidate.startedAt <= candidate.progressionGrace then
		return true
	end

	return false, "track-did-not-progress"
end

local function compatibilityScore(candidate, evidence, latency, durationTight)
	local score = 0
	local weapon = candidate.weaponContext or {}

	if evidence.exactFamily and candidate.category == evidence.exactFamily then
		score = score + 5
	elseif evidence.allowWeaponFamilyBridge and categoryCompatible(candidate, evidence) then
		score = score + 3
	elseif evidence.families and evidence.families[candidate.category] then
		score = score + 2
	end

	if weapon.status == "confirmed" then
		score = score + 4
	elseif weapon.status == "unknown" then
		score = score + 1
	end

	if durationTight then
		score = score + 2
	end

	if candidate.geometricPlausible and not evidence.authoritative then
		score = score + 2
	end

	if latency >= (evidence.centralLatencyMin or evidence.latencyMin)
		and latency <= (evidence.centralLatencyMax or evidence.latencyMax)
	then
		score = score + 2
	end

	if candidate.comboContinuous then
		score = score + 1
	end

	return score
end

function AttackAuthenticator:_candidateMap(track)
	local map = self.candidatesByTrack[track]
	if not map then
		map = {}
		self.candidatesByTrack[track] = map
	end
	return map
end

function AttackAuthenticator:_removeCandidate(candidate)
	removeArrayValue(self.candidates, candidate)

	local map = self.candidatesByTrack[candidate.track]
	if map then
		map[candidate.occurrence] = nil
		if next(map) == nil then
			self.candidatesByTrack[candidate.track] = nil
		end
	end
end

function AttackAuthenticator:_prune(now)
	for index = #self.candidates, 1, -1 do
		local candidate = self.candidates[index]
		local retainUntil = math.max(
			candidate.deadlineAt or candidate.startedAt,
			candidate.startedAt + candidate.behaviorWindow
		) + candidate.behaviorWindow

		if candidate.status == "pending" and now > (candidate.deadlineAt or now) then
			candidate.status = "expired"
			candidate.reason = "authentication-deadline-expired"
		end

		if now > retainUntil then
			self:_removeCandidate(candidate)
		end
	end

	for index = #self.evidence, 1, -1 do
		local evidence = self.evidence[index]
		if now - evidence.at > self.longestBehaviorWindow * 2 then
			table.remove(self.evidence, index)
		end
	end

	for index = #self.mismatchEvents, 1, -1 do
		if now - self.mismatchEvents[index] > self.longestBehaviorWindow * 2 then
			table.remove(self.mismatchEvents, index)
		end
	end

	while #self.candidates > MAX_CANDIDATES do
		local candidate = self.candidates[1]
		if candidate.status == "pending" then
			candidate.status = "expired"
			candidate.reason = "candidate-capacity"
		end
		self:_removeCandidate(candidate)
	end

	while #self.evidence > MAX_EVIDENCE do
		table.remove(self.evidence, 1)
	end

	while #self.mismatchEvents > MAX_EVIDENCE do
		table.remove(self.mismatchEvents, 1)
	end
end

function AttackAuthenticator:_featureThreshold(name)
	local values = self.baselines[name]
	local center = median(values) or FEATURE_BOOTSTRAP[name]
	local deviation = medianAbsoluteDeviation(values, center) or 0
	return center + math.max(deviation * 3, FEATURE_TOLERANCE[name]), deviation
end

function AttackAuthenticator:_featureVector(now, current)
	local window = current.behaviorWindow
	local legalCapacity = math.max(1, math.ceil(window / current.legalInterval))
	local recent = {}
	local active = 0
	local overdue = 0
	local deficit = 0
	local transitions = 0
	local previous = nil

	for _, candidate in next, self.candidates do
		if now - candidate.startedAt <= window then
			recent[#recent + 1] = candidate

			if candidate.track and candidate.track.IsPlaying then
				active = active + 1
			end

			if candidate.status == "pending" then
				deficit = deficit + 1
				if now - candidate.startedAt > candidate.evidenceLatencyMax then
					overdue = overdue + 1
				end
			end

			if previous
				and candidate.category ~= previous.category
				and candidate.startedAt - previous.startedAt
					< math.min(candidate.legalInterval, previous.legalInterval) * 0.35
			then
				transitions = transitions + 1
			end

			if candidate.weaponContext and candidate.weaponContext.status == "mismatch" then
				transitions = transitions + 1
			end

			previous = candidate
		end
	end

	local mismatch = 0
	for _, event in next, self.mismatchEvents do
		if now - event <= window then
			mismatch = mismatch + 1
		end
	end

	local plausibleLayers = math.max(1, math.min(2, legalCapacity))
	return {
		density = #recent / legalCapacity,
		overlap = active / plausibleLayers,
		overdue = overdue / legalCapacity,
		mismatch = mismatch / legalCapacity,
		transition = transitions / legalCapacity,
		deficit = deficit / legalCapacity,
	}, deficit
end

function AttackAuthenticator:_evaluateFlood(now, current)
	local vector, pending = self:_featureVector(now, current)
	local abnormal = 0
	local severe = 0

	for _, name in next, FEATURE_NAMES do
		local threshold, deviation = self:_featureThreshold(name)
		local tolerance = math.max(deviation * 2, FEATURE_TOLERANCE[name])
		if vector[name] > threshold then
			abnormal = abnormal + 1
		end
		if vector[name] > threshold + tolerance then
			severe = severe + 1
		end
	end

	current.featureVector = vector
	current.abnormalFeatures = abnormal

	if not self.floodActive then
		if abnormal >= 3 then
			self.enterStreak = self.enterStreak + 1
		else
			self.enterStreak = 0
		end

		if self.enterStreak >= 2 or severe >= 4 then
			self.floodActive = true
			self.floodEnteredAt = now
			self.quietSince = nil
		end
	else
		if abnormal <= 1 and pending == 0 and #self.mismatchEvents == 0 then
			self.quietSince = self.quietSince or now
			local exitWindow = math.max(self.longestBehaviorWindow, current.behaviorWindow * 2)
			if now - self.quietSince >= exitWindow then
				self.floodActive = false
				self.enterStreak = 0
				self.quietSince = nil
			end
		else
			self.quietSince = nil
		end
	end

	return vector
end

function AttackAuthenticator:_recordBaseline(vector)
	if self.floodActive or not vector then
		return
	end

	for _, name in next, FEATURE_NAMES do
		local values = self.baselines[name]
		values[#values + 1] = vector[name]
		while #values > MAX_BASELINE_SAMPLES do
			table.remove(values, 1)
		end
	end
end

function AttackAuthenticator:observeCandidate(context)
	local map = self:_candidateMap(context.track)
	local existing = map[context.occurrence]
	if existing then
		return existing, false
	end

	local now = context.startedAt
	local legalInterval = math.clamp(tonumber(context.legalInterval) or 0.6, 0.08, 4)
	local behaviorWindow = math.max(legalInterval, tonumber(context.longestTiming) or legalInterval)
	local evidenceLatencyMax = math.clamp(tonumber(context.evidenceLatencyMax) or legalInterval * 0.2, 0.03, legalInterval)
	local provisionalDelay = math.max(evidenceLatencyMax, legalInterval * 0.2)
	local candidateWeaponKey = weaponKey(context)
	local comboContinuous = context.comboContinuous ~= false
	local last = self.lastTransaction
	if last and not last.cancelled then
		local lastCandidate = last.candidate
		local elapsed = now - last.authenticatedAt
		local continuityFloor = math.clamp(
			math.min(legalInterval, lastCandidate.legalInterval) * 0.1,
			0.025,
			0.12
		)
		if elapsed < 0
			or (
				elapsed < continuityFloor
				and (
					candidateWeaponKey ~= lastCandidate.weaponKey
					or context.category ~= lastCandidate.category
				)
			)
		then
			comboContinuous = false
		end
	end

	self.sequence = self.sequence + 1
	self.longestBehaviorWindow = math.max(self.longestBehaviorWindow, behaviorWindow)

	local candidate = {
		id = self.sequence,
		track = context.track,
		occurrence = context.occurrence,
		timing = context.timing,
		aid = context.aid,
		category = context.category,
		weaponContext = context.weaponContext,
		weaponKey = candidateWeaponKey,
		startedAt = now,
		deadlineAt = context.deadlineAt,
		plannedDefenseAt = context.plannedDefenseAt,
		legalInterval = legalInterval,
		behaviorWindow = behaviorWindow,
		evidenceLatencyMax = evidenceLatencyMax,
		progressionGrace = math.clamp(tonumber(context.progressionGrace) or 0.034, 0.016, 0.10),
		provisionalUntil = math.min(context.deadlineAt, now + provisionalDelay),
		initialTimePosition = tonumber(context.track.TimePosition) or 0,
		progressionSamples = {
			{
				at = now,
				position = tonumber(context.track.TimePosition) or 0,
				weight = tonumber(context.track.WeightCurrent) or 0,
				target = tonumber(context.track.WeightTarget) or 0,
				speed = tonumber(context.track.Speed) or 0,
			},
		},
		expectedDuration = context.expectedDuration,
		geometricPlausible = context.geometricPlausible == true,
		comboContinuous = comboContinuous,
		actionKey = context.actionKey,
		timingActionNames = context.timingActionNames or {},
		classifierBlocked = context.classifierBlocked == true,
		callbackDispatchDeadlineAt = context.callbackDispatchDeadlineAt or context.deadlineAt,
		recoveredIngress = context.recoveredIngress == true,
		status = "pending",
		reason = "awaiting-combat-evidence",
	}

	map[context.occurrence] = candidate
	self.candidates[#self.candidates + 1] = candidate
	self:_prune(now)
	self:_evaluateFlood(now, candidate)
	local retriedCandidate = self:_retryRetainedEvidence(now)
	return candidate, true, retriedCandidate
end

function AttackAuthenticator:getCandidate(track, occurrence)
	local map = self.candidatesByTrack[track]
	return map and map[occurrence] or nil
end

function AttackAuthenticator:retainedEvidenceForTiming(context, matchingAt)
	matchingAt = matchingAt or os.clock()
	self:_prune(matchingAt)
	for index = #self.evidence, 1, -1 do
		local evidence = self.evidence[index]
		if
			evidence.authoritative
			and evidence.retainForFutureCandidate
			and not evidence.claimedBy
			and not evidence.causalCandidateId
		then
			local latency = evidence.at - context.startedAt
			local latencyMin = evidence.latencyMin or -0.02
			local latencyMax = evidence.latencyMax or self.longestBehaviorWindow
			local actionCompatible = not evidence.actionKey
				or not evidence.requireTimingActionMatch
				or timingActionCompatible(context, evidence.actionKey, evidence.actionAliases)
			if
				latency >= latencyMin
				and latency <= latencyMax
				and categoryCompatible(context, evidence)
				and actionCompatible
				and (not context.deadlineAt or evidence.at <= context.deadlineAt)
			then
				return evidence
			end
		end
	end
	return nil
end

function AttackAuthenticator:releaseCandidate(candidate, now)
	if not candidate or candidate.status ~= "pending" then
		return false
	end

	now = now or os.clock()
	self:_prune(now)
	self:_evaluateFlood(now, candidate)

	if now > candidate.deadlineAt then
		candidate.status = "expired"
		candidate.reason = "authentication-deadline-expired"
		return false
	end

	if self.floodActive or self.enterStreak > 0 then
		candidate.status = "rejected"
		candidate.reason = "unauthenticated-realistic-flood-candidate"
		return false
	end

	if candidate.classifierBlocked then
		candidate.status = "rejected"
		candidate.reason = "classifier-rejected"
		return false
	end

	candidate.status = "released"
	candidate.reason = "quiet-release"
	self:_recordBaseline(candidate.featureVector)
	return true
end

local function candidateEligible(self, candidate, evidence, matchingAt)
	if candidate.status ~= "pending" or evidence.claimedBy then
		return false, "candidate-or-evidence-already-claimed"
	end

	if evidence.at > candidate.deadlineAt then
		return false, "safe-deadline-closed"
	end

	local latency = evidence.at - candidate.startedAt
	if latency < evidence.latencyMin or latency > evidence.latencyMax then
		return false, "evidence-latency-outside-distribution"
	end

	if not categoryCompatible(candidate, evidence) then
		return false, "attack-family-mismatch"
	end

	if candidate.weaponContext and candidate.weaponContext.status == "mismatch" then
		return false, "weapon-context-mismatch"
	end

	if evidence.weaponKey and candidate.weaponKey ~= evidence.weaponKey then
		return false, "equipped-weapon-mismatch"
	end

	if evidence.requireExactWeaponType
		and not (candidate.weaponContext and candidate.weaponContext.exactWeaponTypeMatch == true)
	then
		return false, "exact-weapon-type-mismatch"
	end

	if evidence.actionKey then
		if evidence.requireTimingActionMatch then
			local timingMatches = timingActionCompatible(
				candidate,
				evidence.actionKey,
				evidence.actionAliases
			)
			if not timingMatches then
				return false, "timing-action-family-mismatch"
			end
		elseif candidate.actionKey ~= evidence.actionKey then
			return false, "action-context-mismatch"
		end
	end

	if evidence.causalCandidateId and candidate.id ~= evidence.causalCandidateId then
		return false, "causal-anchor-mismatch"
	end

	if evidence.causalTrack and candidate.track ~= evidence.causalTrack then
		return false, "causal-track-mismatch"
	end

	if evidence.causalOccurrence and candidate.occurrence ~= evidence.causalOccurrence then
		return false, "causal-occurrence-mismatch"
	end

	if not candidate.comboContinuous then
		return false, "combo-discontinuity"
	end

	if not candidate.geometricPlausible and not evidence.authoritative then
		return false, "geometry-not-plausible"
	end

	local last = self.lastTransaction
	if last
		and last.candidate ~= candidate
		and not last.cancelled
		and evidence.at - last.authenticatedAt
			< math.min(candidate.legalInterval, last.candidate.legalInterval) * 0.25
	then
		return false, "combat-transaction-already-open"
	end

	local progressed, progressionReason = trackProgresses(candidate, evidence.at, evidence)
	if not progressed then
		return false, progressionReason
	end

	local durationCompatible, durationTight, durationError = durationCompatibility(candidate, evidence)
	if not durationCompatible then
		return false, "track-duration-mismatch"
	end

	return true, {
		candidate = candidate,
		latency = latency,
		durationTight = durationTight,
		durationError = durationError,
		score = compatibilityScore(candidate, evidence, latency, durationTight),
	}
end

function AttackAuthenticator:recordEvidence(evidence, matchingAt)
	matchingAt = matchingAt or os.clock()
	self:_prune(matchingAt)
	if evidence.id == nil then
		self.evidenceSequence = self.evidenceSequence + 1
		evidence.id = self.evidenceSequence
		evidence.latencyMin = evidence.latencyMin or -0.02
		evidence.latencyMax = evidence.latencyMax or self.longestBehaviorWindow
		evidence.uncertainty = evidence.uncertainty or 0.02
		if evidence.retainForFutureCandidate == nil then
			evidence.retainForFutureCandidate = evidence.authoritative == true
		end
		self.evidence[#self.evidence + 1] = evidence
	end
	local matches = {}
	for _, candidate in next, self.candidates do
		local eligible, match = candidateEligible(self, candidate, evidence, matchingAt)
		if eligible then
			matches[#matches + 1] = match
		end
	end

	table.sort(matches, function(left, right)
		if left.score ~= right.score then
			return left.score > right.score
		end
		if left.durationError ~= right.durationError then
			return left.durationError < right.durationError
		end
		return left.latency < right.latency
	end)

	if #matches == 0 then
		if evidence.retainForFutureCandidate then
			return nil, "awaiting-compatible-candidate"
		end
		if not evidence.finalizedUnmatched then
			evidence.finalizedUnmatched = true
			self.mismatchEvents[#self.mismatchEvents + 1] = evidence.at
		end
		return nil, "no-compatible-candidate"
	end

	local selected = matches[1]
	local alternate = matches[2]
	if alternate then
		local sameContext = selected.candidate.category == alternate.candidate.category
			and selected.candidate.weaponKey == alternate.candidate.weaponKey
			and selected.score == alternate.score
		local latencyOverlap = math.abs(selected.latency - alternate.latency) <= evidence.uncertainty
		local durationOverlap = math.abs(selected.durationError - alternate.durationError) <= 0.05

		if sameContext and latencyOverlap and durationOverlap then
			self.mismatchEvents[#self.mismatchEvents + 1] = evidence.at
			evidence.reason = "ambiguous-compatible-candidates"
			return nil, evidence.reason
		end
	end

	local candidate = selected.candidate
	self.transactionSequence = self.transactionSequence + 1
	local transaction = {
		id = self.transactionSequence,
		candidate = candidate,
		evidence = evidence,
		authenticatedAt = evidence.at,
		scheduled = false,
		issued = false,
		cancelled = false,
	}

	evidence.claimedBy = candidate.id
	candidate.status = "authenticated"
	candidate.reason = evidence.kind
	candidate.authenticatedFamily = evidence.exactFamily or candidate.category
	candidate.familyBridged = evidence.allowWeaponFamilyBridge == true
		and evidence.exactFamily ~= nil
		and candidate.category ~= evidence.exactFamily
	candidate.transaction = transaction
	candidate.evidenceLatency = selected.latency
	self.lastTransaction = transaction
	self:_recordBaseline(candidate.featureVector)
	return candidate, "authenticated"
end

function AttackAuthenticator:_retryRetainedEvidence(matchingAt)
	matchingAt = matchingAt or os.clock()
	for _, evidence in next, self.evidence do
		if evidence.retainForFutureCandidate and not evidence.claimedBy then
			local candidate = self:recordEvidence(evidence, matchingAt)
			if candidate then
				return candidate
			end
		end
	end
end

function AttackAuthenticator:cancelFromEvidence(evidence)
	local cancelled = {}
	for _, candidate in next, self.candidates do
		local transaction = candidate.transaction
		local authenticatedDuration = transaction
			and transaction.evidence
			and tonumber(transaction.evidence.duration)
		local terminalAge = transaction and evidence.at - transaction.authenticatedAt or math.huge
		local earlyTerminal = not authenticatedDuration or terminalAge <= authenticatedDuration * 0.65
		if transaction
			and not transaction.issued
			and not transaction.cancelled
			and earlyTerminal
			and evidence.at <= candidate.deadlineAt
			and (not evidence.weaponKey or evidence.weaponKey == candidate.weaponKey)
		then
			transaction.cancelled = true
			transaction.cancelReason = evidence.kind
			candidate.status = "cancelled"
			candidate.reason = evidence.kind
			cancelled[#cancelled + 1] = candidate
		end
	end
	return cancelled
end

function AttackAuthenticator:isAuthenticated(track, occurrence)
	local candidate = self:getCandidate(track, occurrence)
	return candidate ~= nil
		and candidate.status == "authenticated"
		and candidate.transaction ~= nil
		and not candidate.transaction.cancelled
end

function AttackAuthenticator:isOccurrenceValid(track, occurrence)
	local candidate = self:getCandidate(track, occurrence)
	if not candidate then
		return true
	end

	if candidate.status == "released" then
		return true
	end

	return candidate.status == "authenticated"
		and candidate.transaction ~= nil
		and not candidate.transaction.cancelled
end

function AttackAuthenticator:claimSchedule(track, occurrence, now)
	local candidate = self:getCandidate(track, occurrence)
	local transaction = candidate and candidate.transaction
	if
		not candidate
		or candidate.status ~= "authenticated"
		or not transaction
		or transaction.cancelled
	then
		return false, "transaction-not-authenticated"
	end

	if transaction.scheduled then
		return false, "defense-sequence-already-scheduled"
	end

	now = now or os.clock()
	if transaction.authenticatedAt > candidate.deadlineAt then
		transaction.cancelled = true
		transaction.cancelReason = "authentication-deadline-expired"
		candidate.status = "expired"
		candidate.reason = transaction.cancelReason
		return false, transaction.cancelReason
	end

	if now > math.max(candidate.deadlineAt, candidate.callbackDispatchDeadlineAt or candidate.deadlineAt) then
		transaction.cancelled = true
		transaction.cancelReason = "scheduling-dispatch-deadline-expired"
		candidate.status = "expired"
		candidate.reason = transaction.cancelReason
		return false, transaction.cancelReason
	end

	transaction.scheduled = true
	transaction.scheduledAt = now
	return true, "defense-sequence-claimed"
end

function AttackAuthenticator:markIssued(track, occurrence)
	local candidate = self:getCandidate(track, occurrence)
	if candidate and candidate.transaction and not candidate.transaction.cancelled then
		local transaction = candidate.transaction
		if transaction.issued then
			return false
		end

		transaction.issued = true
		transaction.issuedAt = os.clock()
		return true
	end

	return false
end

function AttackAuthenticator:reset(reason)
	for _, candidate in next, self.candidates do
		if candidate.status == "pending" or candidate.status == "authenticated" then
			candidate.status = "cancelled"
			candidate.reason = reason or "reset"
			if candidate.transaction then
				candidate.transaction.cancelled = true
				candidate.transaction.cancelReason = reason or "reset"
			end
		end
	end

	self.candidates = {}
	self.candidatesByTrack = setmetatable({}, { __mode = "k" })
	self.evidence = {}
	self.mismatchEvents = {}
	self.floodActive = false
	self.enterStreak = 0
	self.quietSince = nil
end

function AttackAuthenticator.new()
	local baselines = {}
	for _, name in next, FEATURE_NAMES do
		baselines[name] = {}
	end

	return setmetatable({
		candidates = {},
		candidatesByTrack = setmetatable({}, { __mode = "k" }),
		evidence = {},
		mismatchEvents = {},
		baselines = baselines,
		sequence = 0,
		evidenceSequence = 0,
		transactionSequence = 0,
		longestBehaviorWindow = 0.6,
		floodActive = false,
		enterStreak = 0,
		quietSince = nil,
	}, AttackAuthenticator)
end

return AttackAuthenticator
end)
registerDefenseModule("Features/Combat/EntityHistory", function(require)
local EntityHistory = {}

local histories = {}

local MAX_HISTORY_SECS = 3.0

local COMPACT_HEAD_THRESHOLD = 1024

local function newHistory()
	return {
		entries = {},
		pool = {},
		first = 1,
		last = 0,
	}
end

local compactHistory = (function(history)
	local first = history.first
	local last = history.last
	local count = last - first + 1
	if first < COMPACT_HEAD_THRESHOLD or first <= count then
		return
	end

	local entries = history.entries
	for index = 1, count do
		local oldIndex = first + index - 1
		entries[index] = entries[oldIndex]
		if oldIndex ~= index then
			entries[oldIndex] = nil
		end
	end

	history.first = 1
	history.last = count
end)

EntityHistory.add = (function(idx, position, velocity, timestamp)
	local history = histories[idx]
	if not history then
		history = newHistory()
		histories[idx] = history
	end

	local pool = history.pool
	local poolIndex = #pool
	local entry = pool[poolIndex]
	if entry then
		pool[poolIndex] = nil
	else
		entry = {}
	end

	entry.position = position
	entry.timestamp = timestamp
	entry.velocity = velocity

	local last = history.last + 1
	history.last = last
	history.entries[last] = entry

	local entries = history.entries
	local first = history.first
	local now = os.clock()
	while first <= last do
		local oldest = entries[first]
		if now - oldest.timestamp <= MAX_HISTORY_SECS then
			break
		end

		entries[first] = nil
		pool[#pool + 1] = oldest
		first = first + 1
	end
	history.first = first
	compactHistory(history)
end)

EntityHistory.vall = (function(index, time)
	local history = histories[index]
	if not history then
		return nil
	end

	local out = {}
	local now = os.clock()
	local entries = history.entries

	for dataIndex = history.first, history.last do
		local data = entries[dataIndex]
		if now - data.timestamp > time then
			continue
		end

		out[#out + 1] = data.velocity
	end

	return out
end)

EntityHistory.yrate = (function(index)
	local history = histories[index]
	if not history or history.last - history.first + 1 < 2 then
		return nil
	end

	local entries = history.entries
	local latest = entries[history.last]
	local previous = entries[history.last - 1]
	local dt = latest.timestamp - previous.timestamp
	if dt <= 1e-4 then
		return nil
	end

	local prevLook = Vector3.new(previous.position.LookVector.X, 0, previous.position.LookVector.Z).Unit
	local latestLook = Vector3.new(latest.position.LookVector.X, 0, latest.position.LookVector.Z).Unit
	local dot = prevLook:Dot(latestLook)
	local crossY = prevLook:Cross(latestLook).Y
	local angle = math.atan2(crossY, dot)
	return angle / dt
end)

EntityHistory.pstepped = (function(idx, steps, phds)
	local history = histories[idx]
	if not history or history.last < history.first then
		return nil
	end

	if not steps or steps <= 0 then
		return nil
	end

	local vhistory = {}
	local entries = history.entries
	local vhtime = entries[history.last].timestamp

	for dataIndex = history.first, history.last do
		local data = entries[dataIndex]
		if vhtime - data.timestamp > phds then
			continue
		end

		vhistory[#vhistory + 1] = data.position
	end

	if #vhistory == 0 then
		return {}
	end

	local count = math.min(steps, #vhistory)
	local out = table.create(count)

	for cidx = 1, count do
		out[cidx] = vhistory[math.max(math.floor((cidx * #vhistory) / count), 1)]
	end

	return out
end)

EntityHistory.pclosest = (function(idx, timestamp)
	local history = histories[idx]
	if not history then
		return nil
	end

	local closestDelta = nil
	local closestPosition = nil

	local entries = history.entries
	for dataIndex = history.first, history.last do
		local data = entries[dataIndex]
		local delta = math.abs(timestamp - data.timestamp)

		if closestDelta and delta >= closestDelta then
			continue
		end

		closestPosition = data.position
		closestDelta = delta
	end

	return closestPosition
end)

function EntityHistory.clear(idx)
	histories[idx] = nil
end

function EntityHistory.clearAll()
	histories = {}
end

return EntityHistory
end)

registerDefenseModule("Features/Combat/StateListener", function(require)
local StateListener = {
	lMantraActivated = nil,
	lAnimTiming = nil,
	lAnimFaction = nil,
	lAnimTimestamp = nil,
	chainStacks = nil,
	lastVent = nil,
	lAnimLatency = nil,

	lADAction = nil,
	lADAnimation = nil,
}

local Signal = require("Utility/Signal")

local Maid = require("Utility/Maid")

local Configuration = require("Utility/Configuration")

local SaveManager = require("Game/Timings/SaveManager")

local ModuleManager = require("Game/Timings/ModuleManager")

local Latency = require("Game/Latency")

local stateMaid = Maid.new()
local characterMaid = Maid.new()
local currentCharacter = nil
local currentAnimator = nil
local initialized = false

local players = game:GetService("Players")
local replicatedStorage = game:GetService("ReplicatedStorage")
local userInputService = game:GetService("UserInputService")

local CHIME_ARENA_PLACE_ID = 6832944305

local handleModuleData = (function(track, timing)
	if timing.tag ~= "M1" then
		return
	end

	local lf = ModuleManager.modules[PP_SCRAMBLE_STR(timing.smod)]
	if not lf then
		return
	end

	local extracted = {}
	local fake = {
		tmaid = Maid.new(),
		track = track,
		entity = players.LocalPlayer.Character,
		action = function(_self, _timing, action)
			table.insert(extracted, action)
		end,
	}

	local success, result = pcall(lf, fake, timing)

	fake.tmaid:clean()

	if success and extracted[1] then
		StateListener.lAnimFaction = extracted[1]
	end
end)

local onLocalAnimationPlayed = (function(track)
	local animation = track.Animation
	if animation and animation:GetAttribute(AUTO_PARRY_BREAKER_ATTRIBUTE) then
		return
	end

	local aid = tostring(animation.AnimationId)
	local data = SaveManager.as:index(aid)
	if not data then
		return
	end

	local success, errorMsg = pcall(function()
		StateListener.lAnimTimestamp = os.clock()
		StateListener.lAnimationValidTrack = track
		StateListener.lAnimTiming = data
		StateListener.lAnimLatency = Latency.rtt()

		if data.umoa then
			return pcall(handleModuleData, track, data)
		end

		local extractSuccess, result = pcall(function()
			if data.actions and type(data.actions) == "table" then
				if data.actions.stack and type(data.actions.stack) == "function" then
					local stack = data.actions:stack()
					if stack and stack[1] then
						return stack[1]
					end
				end
			end
			return nil
		end)

		if extractSuccess and result then
			StateListener.lAnimFaction = result
		end
	end)
end)

local attachAnimator = (function(animator, character)
	if currentCharacter ~= character or currentAnimator == animator then
		return
	end

	if not animator:IsDescendantOf(character) then
		return
	end

	currentAnimator = animator
	local animationPlayed = Signal.new(animator.AnimationPlayed)
	characterMaid.AnimationPlayed =
		animationPlayed:connect("StateListener_AnimationPlayed", onLocalAnimationPlayed)
end)

local attachCharacter = (function(character)
	if currentCharacter == character then
		return
	end

	characterMaid:clean()
	currentAnimator = nil
	currentCharacter = character
	if not character then
		return
	end

	local descendantAdded = Signal.new(character.DescendantAdded)
	local descendantRemoving = Signal.new(character.DescendantRemoving)
	characterMaid:add(descendantAdded:connect("StateListener_LocalDescendantAdded", function(descendant)
		if currentCharacter == character and descendant:IsA("Animator") then
			attachAnimator(descendant, character)
		end
	end))
	characterMaid:add(descendantRemoving:connect("StateListener_LocalDescendantRemoving", function(descendant)
		if currentCharacter ~= character or currentAnimator ~= descendant then
			return
		end

		currentAnimator = nil
		characterMaid.AnimationPlayed = nil
	end))

	for _, descendant in next, character:GetDescendants() do
		if descendant:IsA("Animator") then
			attachAnimator(descendant, character)
		end
	end
end)

local withinTime = (function(effect, time, offset)
	if not effect.index then
		return false
	end

	local timestamp = effect.index.Timestamp
	if not timestamp then
		return false
	end

	local dtime = effect.index.DebrisTime
	if not dtime then
		return false
	end

	if offset and time then
		return os.clock() - timestamp <= (dtime + time)
	end

	return os.clock() - timestamp <= (time or dtime)
end)

StateListener.hblock = (function()
	local keybinds = replicatedStorage:FindFirstChild("KeyBinds")
	if not keybinds then
		return false
	end

	local keybindsModule = require(keybinds)
	if not keybindsModule or not keybindsModule.Current then
		return false
	end

	local bindings = keybindsModule:GetBindings() or {}

	for _, keybind in next, bindings["Block"] do
		local success, keyCode = pcall(function()
			return Enum.KeyCode[tostring(keybind)]
		end)

		if not success or not keyCode then
			continue
		end

		if not userInputService:IsKeyDown(keyCode) then
			continue
		end

		return true
	end

	return false
end)

StateListener.csb = (function()
	if not StateListener.lMantraActivated then
		return false
	end

	local name = tostring(StateListener.lMantraActivated)
	if not name or not name:match("Sightless Beam") then
		return false
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	local hrp = character:FindFirstChild("HumanoidRootPart")
	if not hrp then
		return false
	end

	if hrp:FindFirstChild("REP_SOUND_376107250") then
		return true
	end

	for _, child in next, hrp:GetChildren() do
		if not child:IsA("Sound") then
			continue
		end

		if child.Name ~= "Telekin" then
			continue
		end

		if not child.IsPlaying then
			continue
		end

		return true
	end

	return false
end)

StateListener.astun = (function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local lightAttackEffect = effectReplicatorModule:FindEffect("LightAttack")
	local usingCriticalEffect = effectReplicatorModule:FindEffect("UsingCritical")
	local usingSpellEffect = effectReplicatorModule:FindEffect("UsingSpell")

	if lightAttackEffect and withinTime(lightAttackEffect, 0.5, false) then
		return true
	end

	if usingCriticalEffect and withinTime(usingCriticalEffect, -0.1, true) then
		return true
	end

	if usingSpellEffect then
		return true
	end

	return false
end)

StateListener.cvent = (function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local ventCooldownEffect = effectReplicatorModule:FindEffect("NoBurst")

	if Configuration.expectToggleValue("BlockVentState") then
		return false
	end

	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	if StateListener.lastVent and (os.clock() - StateListener.lastVent) <= 8.0 then
		return false
	end

	local tempo = character:FindFirstChild("Tempo")
	if not tempo then
		return false
	end

	if tempo.Value < 40 then
		return false
	end

	if not effectReplicatorModule:FindEffect("Equipped") then
		return false
	end

	if ventCooldownEffect then
		return false
	end

	return true
end)

StateListener.cparry = (function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local parryCooldownEffect = effectReplicatorModule:FindEffect("ParryCool")

	if Configuration.expectToggleValue("BlockParryState") then
		return false
	end

	if not effectReplicatorModule:FindEffect("Equipped") then
		return false
	end

	if parryCooldownEffect then
		return false
	end

	return true
end)

StateListener.cfeint = (function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local feintCooldownEffect = effectReplicatorModule:FindEffect("FeintCool")

	if feintCooldownEffect then
		return false
	end

	return true
end)

StateListener.cblock = (function()
	local character = players.LocalPlayer and players.LocalPlayer.Character
	if not character then
		return false
	end

	if Configuration.expectToggleValue("NoBlockingState") then
		return false
	end

	local breakMeter = character:FindFirstChild("BreakMeter")
	if not breakMeter then
		return false
	end

	if breakMeter.Value / breakMeter.MaxValue > 0.6 then
		return false
	end

	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)

	if effectReplicatorModule:FindEffect("ShakyBlock") then
		return false
	end

	if effectReplicatorModule:FindEffect("CancelBlock") then
		return false
	end

	return true
end)

StateListener.cdodge = (function()
	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local dodgeCooldownEffect = effectReplicatorModule:FindEffect("NoRoll")
	local stunCooldownEffect = effectReplicatorModule:FindEffect("Stun")

	if Configuration.expectToggleValue("BlockDodgeState") then
		return false
	end

	if dodgeCooldownEffect then
		return false
	end

	if stunCooldownEffect and withinTime(stunCooldownEffect, nil, false) then
		return false
	end

	return true
end)

StateListener.ccd = (function()
	return game.PlaceId == CHIME_ARENA_PLACE_ID and workspace.DistributedGameTime < 15
end)

local onEffectReplicated = (function(effect)
	if effect.Class == "LightAttack" then
		effect.index.Timestamp = os.clock()
	end

	if effect.Class == "Stun" then
		effect.index.Timestamp = os.clock()
	end

	if effect.Class == "DodgeCool" then
		effect.index.Timestamp = os.clock()
	end

	if effect.Class == "ParryCool" then
		effect.index.Timestamp = os.clock()
	end

	if effect.Class == "Vented" then
		StateListener.lastVent = os.clock()
	end

	if effect.Class == "PerfectStack" then
		StateListener.chainStacks = 0
	end

	if effect.Class == "PerfectionCool" and StateListener.chainStacks then
		StateListener.chainStacks = math.min(StateListener.chainStacks + 1, 20)
	end
end)

local onEffectRemoving = (function(effect)
	if effect.Class == "PerfectStack" then
		StateListener.chainStacks = nil
	end
end)

function StateListener.init()
	if initialized then
		return
	end
	initialized = true

	local localPlayer = players.LocalPlayer
	local characterAdded = Signal.new(localPlayer.CharacterAdded)
	local characterRemoving = Signal.new(localPlayer.CharacterRemoving)

	local effectReplicator = replicatedStorage:WaitForChild("EffectReplicator")
	local effectReplicatorModule = require(effectReplicator)
	local effectAddedSignal = Signal.new(effectReplicatorModule.EffectAdded)
	local effectRemovedSignal = Signal.new(effectReplicatorModule.EffectRemoved)

	stateMaid:mark(effectAddedSignal:connect("StateListener_EffectReplicated", onEffectReplicated))
	stateMaid:mark(effectRemovedSignal:connect("StateListener_EffectRemoved", onEffectRemoving))
	stateMaid:mark(characterAdded:connect("StateListener_CharacterAdded", attachCharacter))
	stateMaid:mark(characterRemoving:connect("StateListener_CharacterRemoving", function(character)
		if currentCharacter == character then
			attachCharacter(nil)
		end
	end))

	for _, effect in next, effectReplicatorModule.Effects do
		onEffectReplicated(effect)
	end

	attachCharacter(localPlayer.Character)

end

function StateListener.detach()
	initialized = false
	stateMaid:clean()
	characterMaid:clean()
	currentCharacter = nil
	currentAnimator = nil
end

return StateListener
end)

registerDefenseModule("Features/Combat/Targeting", function(require)
local Targeting = {}

local Configuration = require("Utility/Configuration")

local PlayerScanning = require("Game/PlayerScanning")

local Target = require("Features/Combat/Objects/Target")

local Table = require("Utility/Table")

local players = game:GetService("Players")
local userInputService = game:GetService("UserInputService")

local CACHE_TTL = 1 / 240
local viableCacheClock = -math.huge
local viableCacheValue = nil
local bestCacheClock = -math.huge
local bestCacheValue = nil

local computeViable = (function()
	local live = workspace:FindFirstChild("Live")
	if not live then
		return {}
	end

	local localCharacter = players.LocalPlayer.Character
	if not localCharacter then
		return {}
	end

	local localRootPart = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
	if not localRootPart then
		return {}
	end

	local currentCamera = workspace.CurrentCamera
	if not currentCamera then
		return {}
	end

	local ignoreMobs = Configuration.expectToggleValue("IgnoreMobs")
	local ignorePlayers = Configuration.expectToggleValue("IgnorePlayers")
	local ignoreAllies = Configuration.expectToggleValue("IgnoreAllies")
	local fieldOfViewLimit = Configuration.expectOptionValue("FOVLimit")
	local distanceLimit = Configuration.expectOptionValue("DistanceLimit")
	local fieldOfViewCosine = math.cos(math.rad(fieldOfViewLimit))
	local cameraLookVector = currentCamera.CFrame.LookVector
	local localRootPosition = localRootPart.Position
	local mousePosition = userInputService:GetMouseLocation()
	local unitRay = currentCamera:ScreenPointToRay(mousePosition.X, mousePosition.Y)

	local targets = {}

	for _, entity in next, live:GetChildren() do
		if entity == localCharacter then
			continue
		end

		local playerFromCharacter = players:GetPlayerFromCharacter(entity)
		if not playerFromCharacter and ignoreMobs then
			continue
		end

		if playerFromCharacter and ignorePlayers then
			continue
		end

		local humanoid = entity:FindFirstChildWhichIsA("Humanoid")
		if not humanoid then
			continue
		end

		local rootPart = entity:FindFirstChild("HumanoidRootPart")
		if not rootPart then
			continue
		end

		if humanoid.Health <= 0 then
			continue
		end

		if
			playerFromCharacter
			and PlayerScanning.isAlly(playerFromCharacter)
			and ignoreAllies
		then
			continue
		end

		local rootPosition = rootPart.Position
		local fieldOfViewToEntity = cameraLookVector:Dot((localRootPosition - rootPosition).Unit)

		if fieldOfViewLimit <= 0 or (fieldOfViewToEntity * -1) <= fieldOfViewCosine then
			continue
		end

		local currentDistance = (rootPosition - localRootPosition).Magnitude
		if currentDistance > distanceLimit then
			continue
		end

		local distanceToCrosshair = unitRay:Distance(rootPosition)

		targets[#targets + 1] =
			Target.new(entity, humanoid, rootPart, distanceToCrosshair, fieldOfViewToEntity, currentDistance)
	end

	return targets
end)

Targeting.viable = (function()
	local now = os.clock()
	if viableCacheValue and now - viableCacheClock <= CACHE_TTL then
		return viableCacheValue
	end

	viableCacheValue = computeViable()
	viableCacheClock = now
	return viableCacheValue
end)

local function sortByCrosshair(first, second)
	return first.dc < second.dc
end

local function sortByDistance(first, second)
	return first.du < second.du
end

local function sortByHealth(first, second)
	return first.humanoid.Health < second.humanoid.Health
end

local computeBest = (function()
	local targets = Targeting.viable()
	local sortType = Configuration.expectOptionValue("PlayerSelectionType")
	local sortFunction = nil

	if sortType == "Closest To Crosshair" then
		sortFunction = sortByCrosshair
	end

	if sortType == "Closest In Distance" then
		sortFunction = sortByDistance
	end

	if sortType == "Least Health" then
		sortFunction = sortByHealth
	end

	table.sort(targets, sortFunction)

	return Table.slice(targets, 1, Configuration.expectOptionValue("MaxTargets"))
end)

Targeting.best = (function()
	local now = os.clock()
	if bestCacheValue and now - bestCacheClock <= CACHE_TTL then
		return bestCacheValue
	end

	bestCacheValue = computeBest()
	bestCacheClock = now
	return bestCacheValue
end)

Targeting.find = (function(model)
	for _, target in next, Targeting.best() do
		if target.character ~= model then
			continue
		end

		return target
	end
end)

return Targeting
end)

registerDefenseModule("Features/Combat/Objects/AnimationIngressGuard", function(require)
local AnimationIngressGuard = {}

local PER_PLAYER_BURST_SECONDS = 0.10
local MAX_PLAYER_BURST = 4
local GLOBAL_RATE_MULTIPLIER = 1.5
local GLOBAL_RATE_LIMIT = 120
local PRESSURE_HOLD_SECONDS = 0.50

local CANDIDATE_PLAYER_RATE = 12
local CANDIDATE_GLOBAL_RATE = 24
local CANDIDATE_PLAYER_BURST = 3
local CANDIDATE_GLOBAL_BURST = 6
local CANDIDATE_ID_SLOTS = 16
local CANDIDATE_SAME_ID_GAP = 0.06

local RECOVERY_PLAYER_RATE = 20
local RECOVERY_GLOBAL_RATE = 40
local RECOVERY_PLAYER_BURST = 6
local RECOVERY_GLOBAL_BURST = 12
local configuredRate = 15
local perPlayerCapacity = 2
local globalRate = 22.5
local globalCapacity = 4
local ownerStates = setmetatable({}, { __mode = "k" })
local ownerCount = 0
local globalBucket = nil
local candidateGlobalBucket = nil
local recoveryGlobalBucket = nil
local globalPressureUntil = 0
local metrics = nil
local lifecycleGeneration = 0

local function newMetrics()
	return {
		incoming = 0,
		admittedSuspicious = 0,
		admittedCandidate = 0,
		quarantinedCandidate = 0,
		coalescedQuarantine = 0,
		admittedRecovery = 0,
		recoveredEvidence = 0,
		rejectedUniversal = 0,
		rejectedPlayerBudget = 0,
		rejectedGlobalBudget = 0,
		rejectedCandidateBudget = 0,
		rejectedRecoveryBudget = 0,
		advancedEntered = 0,
		autoDefenderReached = 0,
		activeMonitors = 0,
	}
end

local function newBucket(capacity, now)
	return { tokens = capacity, updatedAt = now }
end

local function refill(bucket, rate, capacity, now)
	local elapsed = now - bucket.updatedAt
	if elapsed > 0 then
		bucket.tokens = math.min(capacity, bucket.tokens + elapsed * rate)
		bucket.updatedAt = now
	end
end

local function consumePair(ownerBucket, ownerRate, ownerCapacity, sharedBucket, sharedRate, sharedCapacity, now)
	refill(ownerBucket, ownerRate, ownerCapacity, now)
	refill(sharedBucket, sharedRate, sharedCapacity, now)
	if ownerBucket.tokens < 1 then
		return false, "player-budget"
	end
	if sharedBucket.tokens < 1 then
		return false, "global-budget"
	end
	ownerBucket.tokens = ownerBucket.tokens - 1
	sharedBucket.tokens = sharedBucket.tokens - 1
	return true
end

local function resetBuckets(now)
	lifecycleGeneration = lifecycleGeneration + 1
	ownerStates = setmetatable({}, { __mode = "k" })
	ownerCount = 0
	globalBucket = newBucket(globalCapacity, now)
	candidateGlobalBucket = newBucket(CANDIDATE_GLOBAL_BURST, now)
	recoveryGlobalBucket = newBucket(RECOVERY_GLOBAL_BURST, now)
	globalPressureUntil = 0
	metrics = newMetrics()
end

local function stateFor(owner, now)
	local character = owner.Character
	local state = ownerStates[owner]
	if state and state.character == character then
		return state
	end

	state = {
		character = character,
		suspicious = newBucket(perPlayerCapacity, now),
		candidate = newBucket(CANDIDATE_PLAYER_BURST, now),
		recovery = newBucket(RECOVERY_PLAYER_BURST, now),
		candidateIds = {},
		candidateIdRing = table.create(CANDIDATE_ID_SLOTS),
		candidateIdCount = 0,
		candidateIdCursor = 1,
		pressureUntil = 0,
	}
	if not ownerStates[owner] then
		ownerCount = ownerCount + 1
	end
	ownerStates[owner] = state
	return state
end

local function noteCandidateId(state, animationId, now)
	local previous = state.candidateIds[animationId]
	if previous and now - previous < CANDIDATE_SAME_ID_GAP then
		return false
	end
	if not previous then
		if state.candidateIdCount < CANDIDATE_ID_SLOTS then
			state.candidateIdCount = state.candidateIdCount + 1
			state.candidateIdRing[state.candidateIdCount] = animationId
		else
			local cursor = state.candidateIdCursor
			local evicted = state.candidateIdRing[cursor]
			if evicted then
				state.candidateIds[evicted] = nil
			end
			state.candidateIdRing[cursor] = animationId
			state.candidateIdCursor = cursor % CANDIDATE_ID_SLOTS + 1
		end
	end
	state.candidateIds[animationId] = now
	return true
end

function AnimationIngressGuard.configure(rate)
	rate = math.clamp(tonumber(rate) or 15, 1, 200)
	if configuredRate == rate and globalBucket then
		return
	end
	configuredRate = rate
	perPlayerCapacity = math.max(2, math.min(MAX_PLAYER_BURST, rate * PER_PLAYER_BURST_SECONDS))
	globalRate = math.min(GLOBAL_RATE_LIMIT, math.max(rate, rate * GLOBAL_RATE_MULTIPLIER))
	globalCapacity = math.max(4, math.min(MAX_PLAYER_BURST * 2, globalRate * PER_PLAYER_BURST_SECONDS))

	local now = os.clock()
	if not globalBucket then
		resetBuckets(now)
		return
	end
	refill(globalBucket, globalRate, globalCapacity, now)
	globalBucket.tokens = math.min(globalBucket.tokens, globalCapacity)
	for _, state in next, ownerStates do
		refill(state.suspicious, configuredRate, perPlayerCapacity, now)
		state.suspicious.tokens = math.min(state.suspicious.tokens, perPlayerCapacity)
	end
end

function AnimationIngressGuard.reset()
	resetBuckets(os.clock())
end

function AnimationIngressGuard.generation()
	return lifecycleGeneration
end

function AnimationIngressGuard.removeOwner(owner)
	if owner and ownerStates[owner] then
		ownerStates[owner] = nil
		ownerCount = math.max(0, ownerCount - 1)
	end
end

function AnimationIngressGuard.admitSuspicious(owner)
	local now = os.clock()
	metrics.incoming = metrics.incoming + 1
	local state = stateFor(owner, now)
	local admitted, reason = consumePair(
		state.suspicious,
		configuredRate,
		perPlayerCapacity,
		globalBucket,
		globalRate,
		globalCapacity,
		now
	)
	if admitted then
		metrics.admittedSuspicious = metrics.admittedSuspicious + 1
	else
		state.pressureUntil = now + PRESSURE_HOLD_SECONDS
		if reason == "global-budget" then
			globalPressureUntil = now + PRESSURE_HOLD_SECONDS
		end
	end
	local underPressure = now < state.pressureUntil or now < globalPressureUntil
	return admitted, reason, underPressure
end

function AnimationIngressGuard.admitCandidate(owner, animationId)
	local now = os.clock()
	local state = stateFor(owner, now)
	if not noteCandidateId(state, animationId, now) then
		metrics.rejectedCandidateBudget = metrics.rejectedCandidateBudget + 1
		return false, "repeated-candidate-id"
	end
	local admitted, reason = consumePair(
		state.candidate,
		CANDIDATE_PLAYER_RATE,
		CANDIDATE_PLAYER_BURST,
		candidateGlobalBucket,
		CANDIDATE_GLOBAL_RATE,
		CANDIDATE_GLOBAL_BURST,
		now
	)
	if admitted then
		metrics.admittedCandidate = metrics.admittedCandidate + 1
	else
		metrics.rejectedCandidateBudget = metrics.rejectedCandidateBudget + 1
	end
	return admitted, reason
end

function AnimationIngressGuard.admitRecovery(owner)
	local now = os.clock()
	local state = stateFor(owner, now)
	local admitted, reason = consumePair(
		state.recovery,
		RECOVERY_PLAYER_RATE,
		RECOVERY_PLAYER_BURST,
		recoveryGlobalBucket,
		RECOVERY_GLOBAL_RATE,
		RECOVERY_GLOBAL_BURST,
		now
	)
	if admitted then
		metrics.admittedRecovery = metrics.admittedRecovery + 1
	else
		metrics.rejectedRecoveryBudget = metrics.rejectedRecoveryBudget + 1
	end
	return admitted, reason
end

function AnimationIngressGuard.reject(reason)
	if reason == "global-budget" then
		metrics.rejectedGlobalBudget = metrics.rejectedGlobalBudget + 1
	elseif reason == "player-budget" then
		metrics.rejectedPlayerBudget = metrics.rejectedPlayerBudget + 1
	else
		metrics.rejectedUniversal = metrics.rejectedUniversal + 1
	end
end

function AnimationIngressGuard.quarantineCandidate(coalesced)
	metrics.quarantinedCandidate = metrics.quarantinedCandidate + 1
	if coalesced then
		metrics.coalescedQuarantine = metrics.coalescedQuarantine + 1
	end
end

function AnimationIngressGuard.recoveredEvidence()
	metrics.recoveredEvidence = metrics.recoveredEvidence + 1
end

function AnimationIngressGuard.advancedEntered()
	metrics.advancedEntered = metrics.advancedEntered + 1
end

function AnimationIngressGuard.autoDefenderReached()
	metrics.autoDefenderReached = metrics.autoDefenderReached + 1
end

function AnimationIngressGuard.monitorAdded()
	metrics.activeMonitors = metrics.activeMonitors + 1
end

function AnimationIngressGuard.monitorRemoved()
	metrics.activeMonitors = math.max(0, metrics.activeMonitors - 1)
end

function AnimationIngressGuard.snapshot()
	local result = {}
	for name, value in next, metrics do
		result[name] = value
	end
	result.owners = ownerCount
	result.queued = 0
	result.pending = 0
	return result
end

AnimationIngressGuard.configure(configuredRate)

return AnimationIngressGuard
end)

registerDefenseModule("Game/PlayerScanning", function(require)
local Signal = require("Utility/Signal")
local Maid = require("Utility/Maid")

local PlayerScanning = {
	friendCache = {},
	loadoutCache = {},
	loadoutMaids = {},
}

local players = game:GetService("Players")
local collectionService = game:GetService("CollectionService")

local playerScanningMaid = Maid.new()
local initialized = false
local loadoutTrackingActive = false

local LOADOUT_STABLE_GRACE = 3.0
local LOADOUT_CHANGE_GRACE = 0.35

local function clearTable(target)
	for key in next, target do
		target[key] = nil
	end
end

local function isOwnableTool(instance)
	return instance
		and typeof(instance) == "Instance"
		and (instance:IsA("Tool") or instance:GetAttribute("ItemName") ~= nil or instance.Name:match("^Mantra:"))
end

local function clearLoadoutCache(player)
	local cache = PlayerScanning.loadoutCache[player]
	if cache then
		cache.backpackMaid:clean()
		cache.characterMaid:clean()
		cache.weaponMaid:clean()
	end

	local maid = PlayerScanning.loadoutMaids[player]
	if maid then
		maid:clean()
	end

	PlayerScanning.loadoutMaids[player] = nil
	PlayerScanning.loadoutCache[player] = nil
end

local function newLoadoutCache(player)
	local now = os.clock()
	return {
		player = player,
		tools = {},
		itemNames = {},
		backpack = nil,
		character = nil,
		firstSeen = now,
		lastChanged = now,
		backpackLoaded = false,
		weaponInstance = nil,
		weaponContext = nil,
		backpackMaid = Maid.new(),
		characterMaid = Maid.new(),
		weaponMaid = Maid.new(),
	}
end

local function markLoadoutChanged(cache)
	cache.lastChanged = os.clock()
end

local function countKeys(target)
	local count = 0
	for _ in next, target do
		count = count + 1
	end
	return count
end

local function loadoutReliable(cache)
	if not cache or not cache.backpack then
		return false
	end

	local now = os.clock()
	local stable = now - cache.lastChanged >= LOADOUT_CHANGE_GRACE
	local loaded = cache.backpackLoaded or collectionService:HasTag(cache.backpack, "Loaded")
	local graceElapsed = now - cache.firstSeen >= LOADOUT_STABLE_GRACE
	return stable and (loaded or graceElapsed)
end

local function loadoutStatus(cache)
	if not cache then
		return "cache=none"
	end

	local now = os.clock()
	return string.format(
		"cache=%s backpack=%s loaded=%s stable=%.2f age=%.2f tools=%d itemNames=%d",
		loadoutReliable(cache) and "reliable" or "warming",
		cache.backpack and "yes" or "no",
		cache.backpackLoaded and "yes" or "no",
		now - (cache.lastChanged or now),
		now - (cache.firstSeen or now),
		countKeys(cache.tools),
		countKeys(cache.itemNames)
	)
end

local function recordTool(cache, tool)
	if not isOwnableTool(tool) then
		return
	end

	cache.tools[tool.Name] = true
	local itemName = tool:GetAttribute("ItemName")
	if typeof(itemName) == "string" and itemName ~= "" then
		cache.itemNames[itemName] = true
	end
end

local function trim(value)
	if typeof(value) ~= "string" then
		return nil
	end

	local trimmed = value:match("^%s*(.-)%s*$")
	if trimmed == "" then
		return nil
	end

	return trimmed
end

local function richStatsText(value)
	if typeof(value) ~= "string" then
		return ""
	end

	return value
		:gsub("<[^>]*>", "")
		:gsub("&amp;", "&")
		:gsub("&lt;", "<")
		:gsub("&gt;", ">")
end

local function firstRichStatsLine(statsText)
	for line in string.gmatch(statsText or "", "[^\r\n]+") do
		local cleaned = trim(line)
		if cleaned and not string.find(cleaned, ":", 1, true) then
			return cleaned
		end
	end
end

local function splitTypeLine(typeLine)
	local parts = {}
	for part in string.gmatch(typeLine or "", "([^|]+)") do
		parts[#parts + 1] = trim(part)
	end

	return parts
end

local function parseNumber(pattern, statsText)
	local value = statsText and statsText:match(pattern)
	return tonumber(value)
end

local function parseWeaponContext(weapon)
	if not weapon then
		return nil
	end

	local primaryWeapon = trim(weapon:GetAttribute("PrimaryWeapon"))
	local richStatsRaw = weapon:GetAttribute("RichStats")
	local statsText = richStatsText(richStatsRaw)
	local typeLine = statsText:match("[Tt]ype%s*:%s*([^\r\n]+)")
	local typeParts = splitTypeLine(typeLine)
	local weaponName = primaryWeapon or firstRichStatsLine(statsText)

	if not weaponName and weapon.Name ~= "Weapon" then
		weaponName = weapon.Name
	end

	local context = {
		instance = weapon,
		primaryWeapon = primaryWeapon,
		weaponName = weaponName,
		weaponType = typeParts[1],
		weaponClass = typeParts[2],
		weaponDamageType = typeParts[3],
		weaponSwingSpeed = parseNumber("[Ss]wing%s+[Ss]peed%s*:%s*([%d%.]+)", statsText),
		weaponAttackDuration = parseNumber("[Aa]ttack%s+[Dd]uration%s*:%s*([%d%.]+)", statsText),
		weaponRange = parseNumber("[Rr]ange%s*:%s*([%d%.]+)", statsText),
		richStats = typeof(richStatsRaw) == "string" and richStatsRaw or nil,
	}

	if
		not context.weaponName
		and not context.weaponType
		and not context.weaponClass
		and not context.weaponDamageType
	then
		return nil
	end

	return context
end

local function bindWeaponContext(cache, weapon)
	if cache.weaponInstance == weapon then
		return
	end

	cache.weaponInstance = weapon
	cache.weaponMaid:clean()
	if not weapon then
		return
	end

	local function refresh()
		cache.weaponContext = parseWeaponContext(weapon)
		markLoadoutChanged(cache)
	end

	cache.weaponMaid:add(Signal.new(weapon:GetAttributeChangedSignal("PrimaryWeapon")):connect(
		"PlayerScanning_WeaponPrimaryChanged",
		refresh
	))
	cache.weaponMaid:add(Signal.new(weapon:GetAttributeChangedSignal("RichStats")):connect(
		"PlayerScanning_WeaponRichStatsChanged",
		refresh
	))
end

local function snapshotWeaponContext(cache)
	local weapon = cache.backpack and cache.backpack:FindFirstChild("Weapon")
	bindWeaponContext(cache, weapon)
	cache.weaponContext = parseWeaponContext(weapon)
end

local function snapshotLoadout(player)
	local cache = PlayerScanning.loadoutCache[player]
	if not cache then
		return
	end

	cache.tools = {}
	cache.itemNames = {}
	local backpack = cache.backpack
	cache.backpackLoaded = backpack and collectionService:HasTag(backpack, "Loaded") == true or false
	if backpack then
		for _, child in next, backpack:GetChildren() do
			recordTool(cache, child)
		end
	end
	snapshotWeaponContext(cache)

	if cache.character then
		for _, child in next, cache.character:GetChildren() do
			recordTool(cache, child)
		end
	end
end

local function watchContainer(player, maid, container)
	if not container then
		return
	end

	maid:add(Signal.new(container.ChildAdded):connect("PlayerScanning_LoadoutChildAdded", function(child)
		local cache = PlayerScanning.loadoutCache[player]
		if not cache then
			return
		end
		recordTool(cache, child)
		if container == cache.backpack and child.Name == "Weapon" then
			snapshotLoadout(player)
		end
		markLoadoutChanged(cache)
	end))
	maid:add(Signal.new(container.ChildRemoved):connect("PlayerScanning_LoadoutChildRemoved", function()
		local cache = PlayerScanning.loadoutCache[player]
		if not cache then
			return
		end
		snapshotLoadout(player)
		markLoadoutChanged(cache)
	end))
end

local function bindBackpackContainer(player, cache, backpack)
	if cache.backpack == backpack then
		return false
	end

	cache.backpackMaid:clean()
	cache.backpack = backpack
	cache.backpackLoaded = false
	cache.firstSeen = os.clock()
	watchContainer(player, cache.backpackMaid, backpack)
	return true
end

local function bindCharacterContainer(player, cache, character)
	if cache.character == character then
		return false
	end

	cache.characterMaid:clean()
	cache.character = character
	watchContainer(player, cache.characterMaid, character)
	return true
end

local function bindLoadoutCache(player)
	if player == players.LocalPlayer then
		return nil
	end
	if PlayerScanning.loadoutCache[player] then
		return PlayerScanning.loadoutCache[player]
	end

	clearLoadoutCache(player)
	local maid = Maid.new()
	local cache = newLoadoutCache(player)
	PlayerScanning.loadoutMaids[player] = maid
	PlayerScanning.loadoutCache[player] = cache

	local function rebind()
		if PlayerScanning.loadoutCache[player] ~= cache then
			return
		end
		snapshotLoadout(player)
		markLoadoutChanged(cache)
	end

	maid:add(Signal.new(player.ChildAdded):connect("PlayerScanning_LoadoutPlayerChildAdded", function(child)
		if child.Name == "Backpack" and bindBackpackContainer(player, cache, child) then
			rebind()
		end
	end))
	maid:add(Signal.new(player.ChildRemoved):connect("PlayerScanning_LoadoutPlayerChildRemoved", function(child)
		if child == cache.backpack then
			bindBackpackContainer(player, cache, player:FindFirstChild("Backpack"))
			rebind()
		end
	end))
	maid:add(Signal.new(player.CharacterAdded):connect("PlayerScanning_LoadoutCharacterAdded", function(character)
		if bindCharacterContainer(player, cache, character) then
			rebind()
		end
	end))
	maid:add(Signal.new(player.CharacterRemoving):connect("PlayerScanning_LoadoutCharacterRemoving", function(character)
		if character == cache.character then
			bindCharacterContainer(player, cache, nil)
			rebind()
		end
	end))

	bindBackpackContainer(player, cache, player:FindFirstChild("Backpack"))
	bindCharacterContainer(player, cache, player.Character)
	rebind()
	return cache
end

local function clearAllLoadoutCaches()
	local playersToClear = {}
	for player in next, PlayerScanning.loadoutMaids do
		playersToClear[player] = true
	end
	for player in next, PlayerScanning.loadoutCache do
		playersToClear[player] = true
	end
	for player in next, playersToClear do
		clearLoadoutCache(player)
	end
end

local function prewarmLoadoutCaches()
	for _, player in next, players:GetPlayers() do
		if player ~= players.LocalPlayer then
			bindLoadoutCache(player)
		end
	end
end

function PlayerScanning.setLoadoutTrackingActive(active)
	active = active == true
	if loadoutTrackingActive == active then
		if not active then
			clearAllLoadoutCaches()
		end
		return
	end

	loadoutTrackingActive = active
	if active and initialized then
		prewarmLoadoutCaches()
	else
		clearAllLoadoutCaches()
	end
end

local function matchesDescriptor(cache, descriptor)
	local names = descriptor.names or descriptor.exact or {}
	if typeof(names) == "string" then
		names = { names }
	end
	for _, name in next, names do
		if cache.tools[name] or cache.itemNames[name] then
			return true, name
		end
	end

	local contains = descriptor.contains or {}
	if typeof(contains) == "string" then
		contains = { contains }
	end
	for candidate in next, cache.tools do
		for _, needle in next, contains do
			if string.find(candidate, needle, 1, true) then
				return true, candidate
			end
		end
	end
	for candidate in next, cache.itemNames do
		for _, needle in next, contains do
			if string.find(candidate, needle, 1, true) then
				return true, candidate
			end
		end
	end
	return false, names[1] or contains[1]
end

function PlayerScanning.toolOwnership(player, descriptor)
	if not player or player == players.LocalPlayer then
		return { status = "not-applicable", reason = "npc-or-local" }
	end
	if typeof(descriptor) ~= "table" or descriptor.notApplicable then
		return { status = "not-applicable", reason = "unmapped" }
	end
	if not descriptor.names and not descriptor.exact and not descriptor.contains then
		return { status = "not-applicable", reason = "no-tool-descriptor" }
	end

	local cache = PlayerScanning.loadoutCache[player] or bindLoadoutCache(player)
	if not cache then
		return { status = "unknown", reason = "no-cache", attack = descriptor.label, cache = "cache=none" }
	end

	local matched, expected = matchesDescriptor(cache, descriptor)
	local attack = descriptor.label or expected
	local cacheStatus = loadoutStatus(cache)
	if matched then
		return { status = "confirmed", reason = "matched", attack = attack, matched = matched, cache = cacheStatus }
	end
	if loadoutReliable(cache) then
		return { status = "missing", reason = "not-found", attack = attack, expected = expected, cache = cacheStatus }
	end
	return {
		status = "unknown",
		reason = cache.backpack and "loading-or-unstable" or "no-backpack",
		attack = attack,
		expected = expected,
		cache = cacheStatus,
	}
end

function PlayerScanning.weaponContext(player)
	if not player or player == players.LocalPlayer then
		return { status = "not-applicable", reason = "npc-or-local", cache = "cache=none" }
	end

	local cache = PlayerScanning.loadoutCache[player] or bindLoadoutCache(player)
	if not cache then
		return { status = "unknown", reason = "no-cache", cache = "cache=none" }
	end
	local cacheStatus = loadoutStatus(cache)
	if not loadoutReliable(cache) then
		return {
			status = "unknown",
			reason = cache.backpack and "loading-or-unstable" or "no-backpack",
			cache = cacheStatus,
		}
	end
	if not cache.weaponContext then
		return {
			status = "unknown",
			reason = cache.weaponInstance and "unparsed-weapon" or "no-backpack-weapon",
			cache = cacheStatus,
		}
	end

	local context = {}
	for key, value in next, cache.weaponContext do
		context[key] = value
	end
	context.status = "available"
	context.reason = "backpack-weapon"
	context.cache = cacheStatus
	return context
end

function PlayerScanning.isAlly(player)
	if not player then
		return false
	end
	local localGuild = players.LocalPlayer:GetAttribute("Guild")
	return PlayerScanning.friendCache[player] == true
		or (localGuild and localGuild ~= "" and player:GetAttribute("Guild") == localGuild)
end

function PlayerScanning.friend(player, status)
	PlayerScanning.friendCache[player] = status == Enum.FriendStatus.Friend
end

function PlayerScanning.onPlayerAdded(player)
	if player == players.LocalPlayer then
		return
	end
	PlayerScanning.friendCache[player] = players.LocalPlayer:GetFriendStatus(player) == Enum.FriendStatus.Friend
	if loadoutTrackingActive then
		bindLoadoutCache(player)
	end
end

function PlayerScanning.onPlayerRemoving(player)
	clearLoadoutCache(player)
	PlayerScanning.friendCache[player] = nil
end

function PlayerScanning.init()
	if initialized then
		return
	end
	initialized = true

	playerScanningMaid:add(Signal.new(players.LocalPlayer.FriendStatusChanged):connect(
		"PlayerScanning_OnFriendStatusChanged",
		PlayerScanning.friend
	))
	playerScanningMaid:add(Signal.new(players.PlayerAdded):connect(
		"PlayerScanning_OnPlayerAdded",
		PlayerScanning.onPlayerAdded
	))
	playerScanningMaid:add(Signal.new(players.PlayerRemoving):connect(
		"PlayerScanning_OnPlayerRemoving",
		PlayerScanning.onPlayerRemoving
	))

	for _, player in next, players:GetPlayers() do
		PlayerScanning.onPlayerAdded(player)
	end
end

function PlayerScanning.detach()
	initialized = false
	loadoutTrackingActive = false
	playerScanningMaid:clean()
	clearAllLoadoutCaches()
	clearTable(PlayerScanning.friendCache)
	clearTable(PlayerScanning.loadoutCache)
	clearTable(PlayerScanning.loadoutMaids)
end

return PlayerScanning
end)
