local adcLastRefresh = -1e9
local adcEnableAutoDefense = false
local adcValidateIncomingAnimations = false
local adcCrasherProtection = false
local adcCrasherProtectionThreshold = 15
local adcAdvancedAntiAPBreak = false
local ADVANCED_AP_WINDOW = 1.0

local function numberOption(key, default, min, max)
	local value = tonumber(Configuration.expectOptionValue(key)) or default

	if min and value < min then
		return min
	end

	if max and value > max then
		return max
	end

	return value
end

local function refreshADCache()
	local now = os.clock()
	if now - adcLastRefresh < AD_CACHE_INTERVAL then
		return
	end

	adcLastRefresh = now
	local previousCrasherProtection = adcCrasherProtection
	local previousCrasherThreshold = adcCrasherProtectionThreshold
	adcEnableAutoDefense = Configuration.expectToggleValue("EnableAutoDefense") == true
	adcValidateIncomingAnimations = adcEnableAutoDefense
		and Configuration.expectToggleValue("ValidateIncomingAnimations") == true
	adcCrasherProtection = Configuration.expectToggleValue("CrasherProtection") == true
	adcCrasherProtectionThreshold = numberOption("CrasherProtectionThreshold", 15, 1, 200)
	if previousCrasherThreshold ~= adcCrasherProtectionThreshold then
		AnimationIngressGuard.configure(adcCrasherProtectionThreshold)
	end
	if previousCrasherProtection ~= adcCrasherProtection then
		AnimationIngressGuard.reset()
	end
	adcAdvancedAntiAPBreak = adcEnableAutoDefense
		and Configuration.expectToggleValue("AdvancedAntiAPBreak") == true
end

function AnimatorDefender.forceConfigurationRefresh()
	adcLastRefresh = -1e9
	refreshADCache()
end

local function pruneHistory(history, now, window, limit)
	local oldCount = #history
	local write = 1

	for idx = 1, oldCount do
		local timestamp = history[idx]
		if now - timestamp <= window then
			history[write] = timestamp
			write = write + 1
		end
	end

	for idx = write, oldCount do
		history[idx] = nil
	end

	while #history > limit do
		table.remove(history, 1)
	end
end

local function pruneIdHistory(history, now, window, limit)
	local oldCount = #history
	local write = 1

	for idx = 1, oldCount do
		local entry = history[idx]
		if entry and now - entry.time <= window then
			history[write] = entry
			write = write + 1
		end
	end

	for idx = write, oldCount do
		history[idx] = nil
	end

	while #history > limit do
		table.remove(history, 1)
	end
end

local function tableCount(t)
	local count = 0

	for _ in next, t do
		count = count + 1
	end

	return count
end

local function disconnectAPActiveData(data)
	if not data then
		return
	end
	if data.stopConn then
		data.stopConn:Disconnect()
		data.stopConn = nil
	end
	if data.monitorCounted then
		data.monitorCounted = false
		AnimationIngressGuard.monitorRemoved()
	end
end

local function ingressQuarantineLane(category)
	if category == "mantra" or category == "weapon-critical" then
		return category
	end
	if category == "weapon-m1" or category == "weapon-special" then
		return "weapon"
	end
	return "other"
end

local function ingressQuarantineIndex(lane, cursor)
	return AP_INGRESS_QUARANTINE_LANES[lane] * AP_INGRESS_QUARANTINE_CATEGORY_LIMIT + cursor
end

local function clearIngressQuarantineSlot(self, slot)
	local track = slot.track
	local lane = slot.lane
	if track and lane then
		local byTrack = self.apIngressQuarantineByTrack and self.apIngressQuarantineByTrack[lane]
		if byTrack and byTrack[track] == slot then
			byTrack[track] = nil
		end
	end
	if track then
		self.apIngressQuarantineCount = math.max(0, (self.apIngressQuarantineCount or 0) - 1)
	end
	slot.track = nil
	slot.timing = nil
	slot.aid = nil
	slot.category = nil
	slot.lane = nil
	slot.startedAt = nil
end

local function resetIngressQuarantine(self)
	local quarantine = self.apIngressQuarantine
	if not quarantine then
		quarantine = table.create(AP_INGRESS_QUARANTINE_LIMIT)
		for index = 1, AP_INGRESS_QUARANTINE_LIMIT do
			quarantine[index] = {}
		end
		self.apIngressQuarantine = quarantine
	else
		for index = 1, AP_INGRESS_QUARANTINE_LIMIT do
			local slot = quarantine[index]
			slot.track = nil
			slot.timing = nil
			slot.aid = nil
			slot.category = nil
			slot.lane = nil
			slot.startedAt = nil
		end
	end

	self.apIngressQuarantineCursors = {
		mantra = 1,
		["weapon-critical"] = 1,
		weapon = 1,
		other = 1,
	}
	self.apIngressQuarantineByTrack = {
		mantra = setmetatable({}, { __mode = "k" }),
		["weapon-critical"] = setmetatable({}, { __mode = "k" }),
		weapon = setmetatable({}, { __mode = "k" }),
		other = setmetatable({}, { __mode = "k" }),
	}
	self.apIngressQuarantinePruneCursor = 1
	self.apIngressQuarantineCount = 0
	self.apRecoveredOccurrences = setmetatable({}, { __mode = "k" })
end

local function resetAPBreakFields(self)
	self.apHistory = {}
	self.apHistorySlots = table.create(AP_HISTORY_ID_LIMIT)
	self.apHistorySlotCount = 0
	self.apHistorySlotCursor = 1
	self.apGlobalHistory = {}
	self.apRecentIds = {}
	self.apActive = {}
	self.apActiveCount = 0
	self.apNextMaintenanceAt = 0
	self.apCriticalPending = {}
	self.apCriticalConfirmed = {}
	self.apCriticalConfirmedSources = {}
	self.apOccurrencePending = {}
	self.apOccurrenceConfirmed = {}
	self.apOccurrenceStartedAt = setmetatable({}, { __mode = "k" })
	self.apRootAudioAt = nil
	self.apShortDurations = {}
	self.apLastKnownTime = nil
	self.apMantraEther = nil
	self.apMantraEtherValue = nil
	self.apMantraEtherLastSpendAt = nil
	self.apMantraEtherLastSpendAmount = 0
	self.apMantraEtherResolvedAt = nil
	self.apMantraEtherSpendSerial = 0
	self.apMantraEtherClaimedSerial = nil
	self.apMantraEtherClaimedKey = nil
	self.apMantraEtherClaimedAid = nil
	self.apMantraIntentRecordedSerial = nil
	self.apQueuedMantraEvidence = {}
end

local function resetAPBreakState(self)
	if self.apAuthenticator then
		self.apAuthenticator:reset("anti-ap-state-reset")
	end

	if self.apMantraEtherConn then
		self.apMaid.antiAPMantraEther = nil
		self.apMantraEtherConn = nil
	end

	for _, data in next, self.apActive or {} do
		disconnectAPActiveData(data)
	end

	resetAPBreakFields(self)
	self.apRootAttachmentAt = nil
	self.apMantraRootClaimedAction = nil
	self.apMantraRootClaimedUntil = nil
	resetIngressQuarantine(self)
	self.apEvidenceGeneration = (self.apEvidenceGeneration or 0) + 1
end

local function resetAdvancedAPState(self, reason)
	if self.apAuthenticator then
		for _, candidate in next, self.apAuthenticator.candidates or {} do
			if
				(candidate.status == "pending" or candidate.status == "authenticated")
				and type(self.cancelAuthenticatedOccurrence) == "function"
			then
				self:cancelAuthenticatedOccurrence(candidate)
			end
		end
		self.apAuthenticator:reset(reason or "advanced-anti-ap-state-reset")
	end

	self.apMantraIntentRecordedSerial = nil
	self.apQueuedMantraEvidence = {}
	self.apMantraRootClaimedAction = nil
	self.apMantraRootClaimedUntil = nil
	resetIngressQuarantine(self)
	self.apEvidenceGeneration = (self.apEvidenceGeneration or 0) + 1
end

function AnimatorDefender:syncIngressGeneration()
	local generation = AnimationIngressGuard.generation()
	if self._ingressGeneration == generation then
		return
	end

	self._ingressGeneration = generation
	resetAdvancedAPState(self, "animation-ingress-reset")
	resetAPBreakState(self)
end

local setAPMantraEtherSource
local refreshAPWeaponSounds
local bindAPWeaponSoundCarrier
local disconnectAPWeaponSounds

function AnimatorDefender:setPlayerOwner(player, character)
	if not player or (character and character ~= self.entity) then
		return false
	end

	self._playerOwner = player
	self._isFromPlayer = true
	return true
end

function AnimatorDefender:setAdvancedAntiAP(active)
	active = active == true and self.apTrackingActive and adcAdvancedAntiAPBreak
	if self.apAdvancedEnabled == active then
		return
	end

	self.apAdvancedEnabled = active
	resetAdvancedAPState(self, active and "advanced-anti-ap-enabled" or "advanced-anti-ap-disabled")

	if not active then
		self.apMaid:clean()
		if disconnectAPWeaponSounds then
			disconnectAPWeaponSounds(self)
		end
		if setAPMantraEtherSource then
			setAPMantraEtherSource(self, nil, os.clock())
		end

		return
	end

	if setAPMantraEtherSource then
		setAPMantraEtherSource(self, self.entity:FindFirstChild("Ether"), os.clock())
	end
	if refreshAPWeaponSounds then
		refreshAPWeaponSounds(self)
	end

	local requests = replicatedStorage:FindFirstChild("Requests")
	local clientEffect = requests and requests:FindFirstChild("ClientEffect")
	if clientEffect and (clientEffect:IsA("RemoteEvent") or clientEffect:IsA("UnreliableRemoteEvent")) then
		self.apMaid.antiAPWeaponEvidence = Signal.new(clientEffect.OnClientEvent):connect(
			"AnimatorDefender_AntiAPWeaponEvidence",
			function(effect, data)
				self:apce(effect, data)
			end
		)
	end

	self.apMaid.antiAPAttributes = Signal.new(self.entity.AttributeChanged):connect(
		"AnimatorDefender_AntiAPAttributeEvidence",
		function(name)
			self:apae(name)
		end
	)
end

function AnimatorDefender:setAntiAPTracking(active)
	active = active == true
	local owner = players:GetPlayerFromCharacter(self.entity)
	if owner then
		self:setPlayerOwner(owner, self.entity)
	end
	if self.apTrackingActive == active then
		return
	end

	self.apTrackingActive = active
	if not active then
		self:setAdvancedAntiAP(false)
		resetAPBreakState(self)
		return
	end

	self.apMaid.antiAPCritical = Signal.new(self.entity.DescendantAdded):connect(
		"AnimatorDefender_AntiAPCriticalEvidence",
		function(instance)
			if self.apAdvancedEnabled and instance.Name == "Ether" and setAPMantraEtherSource then
				setAPMantraEtherSource(self, instance, os.clock())
			end
			self:apcr(instance)
		end
	)
end

local function readAPMantraEtherValue(ether)
	if not ether then
		return nil
	end

	local ok, value = pcall(function()
		return ether.Value
	end)

	if ok and typeof(value) == "number" then
		return value
	end

	ok, value = pcall(function()
		return ether.ConstrainedValue
	end)

	if ok and typeof(value) == "number" then
		return value
	end
end

local recordReplicatedMantraIntent

local function noteAPMantraEtherValue(self, value, now)
	if typeof(value) ~= "number" then
		return
	end

	local previous = self.apMantraEtherValue
	local spendSerial = nil
	if previous and value < previous - AP_MANTRA_ETHER_EPSILON then
		self.apMantraEtherLastSpendAt = now
		self.apMantraEtherLastSpendAmount = previous - value
		self.apMantraEtherSpendSerial = (self.apMantraEtherSpendSerial or 0) + 1
		spendSerial = self.apMantraEtherSpendSerial
		self.apMantraEtherClaimedSerial = nil
		self.apMantraEtherClaimedKey = nil
		self.apMantraEtherClaimedAid = nil
	end

	self.apMantraEtherValue = value

	if spendSerial and adcAdvancedAntiAPBreak then
		local generation = self.apEvidenceGeneration
		TaskSpawner.delayOwned(self.apMaid, "AnimatorDefender_MantraEtherSettle", AP_MANTRA_EVIDENCE_SETTLE, function()
			if
				adcAdvancedAntiAPBreak
				and self.apTrackingActive
				and self.apAdvancedEnabled
				and self.apEvidenceGeneration == generation
				and self.apMantraEtherSpendSerial == spendSerial
				and recordReplicatedMantraIntent
			then
				recordReplicatedMantraIntent(self, spendSerial)
			end
		end)
	end
end

local function disconnectAPMantraEther(self)
	if self.apMantraEtherConn then
		self.apMaid.antiAPMantraEther = nil
		self.apMantraEtherConn = nil
	end

	self.apMantraEther = nil
	self.apMantraEtherValue = nil
	self.apMantraEtherLastSpendAt = nil
	self.apMantraEtherLastSpendAmount = 0
	self.apMantraEtherResolvedAt = nil
	self.apMantraEtherSpendSerial = 0
	self.apMantraEtherClaimedSerial = nil
	self.apMantraEtherClaimedKey = nil
	self.apMantraEtherClaimedAid = nil
	self.apMantraIntentRecordedSerial = nil
end

setAPMantraEtherSource = function(self, ether, now)
	if self.apMantraEther == ether then
		return
	end

	disconnectAPMantraEther(self)

	self.apMantraEther = ether
	self.apMantraEtherResolvedAt = now

	if not ether then
		return
	end

	noteAPMantraEtherValue(self, readAPMantraEtherValue(ether), now)

	self.apMantraEtherConn = Signal.new(ether.Changed):connect("AnimatorDefender_MantraEtherChanged", function(value)
		local current = typeof(value) == "number" and value or readAPMantraEtherValue(ether)
		noteAPMantraEtherValue(self, current, os.clock())
	end)

	if self.apMantraEtherConn then
		self.apMaid.antiAPMantraEther = self.apMantraEtherConn
	end
end

local function timingOwnershipDescriptor(timing, aid)
	local candidates = {}

	local function try(value, source)
		if typeof(value) ~= "string" or value == "" or value == "N/A" then
			return nil
		end

		candidates[#candidates + 1] = source .. "=" .. value

		local descriptor = ModuleManager.ownership(value)
		if descriptor then
			return descriptor, source .. "=" .. value
		end
	end

	local descriptor, source = try(timing.smod, "smod")
	if descriptor then
		return descriptor, source, table.concat(candidates, "|")
	end

	descriptor, source = try(timing.name, "name")
	if descriptor then
		return descriptor, source, table.concat(candidates, "|")
	end

	descriptor, source = try(timing._id, "_id")
	if descriptor then
		return descriptor, source, table.concat(candidates, "|")
	end

	descriptor, source = try(aid, "aid")
	if descriptor then
		return descriptor, source, table.concat(candidates, "|")
	end

	return nil, "unmapped", table.concat(candidates, "|")
end

local function apBreakOwnership(self, timing, aid)
	local player = players:GetPlayerFromCharacter(self.entity)
	if not player then
		return {
			status = "not-applicable",
			reason = "npc",
			timingName = timing and timing.name,
			timingId = aid or (timing and timing._id),
			smod = timing and timing.smod,
			tag = timing and timing.tag,
		}
	end

	local descriptor, source, candidates = timingOwnershipDescriptor(timing, aid)
	local ownership = PlayerScanning.toolOwnership(player, descriptor)

	ownership.mappingSource = source
	ownership.mappingCandidates = candidates ~= "" and candidates or "none"
	ownership.timingName = timing.name
	ownership.timingId = aid or timing._id
	ownership.smod = timing.smod
	ownership.tag = timing.tag
	ownership.mappedAttack = descriptor and descriptor.label or nil

	return ownership
end

local function lowerText(value)
	if typeof(value) ~= "string" then
		return ""
	end

	return string.lower(PP_SCRAMBLE_STR(value))
end

local function timingSmod(timing)
	return timing and lowerText(timing.smod) or ""
end

local function timingName(timing)
	return timing and lowerText(timing.name) or ""
end

local function timingWeaponCategory(category)
	return category == "weapon-m1" or category == "weapon-critical" or category == "weapon-special"
end

local function apTimingCategory(timing)
	if not timing then
		return "other"
	end

	local smod = timingSmod(timing)
	local name = timingName(timing)

	if timing.tag == "Mantra" then
		return "mantra"
	end

	if timing.tag == "Critical" or string.find(smod, "critical", 1, true) or string.find(name, "critical", 1, true) then
		return "weapon-critical"
	end

	if
		timing.tag == "M1"
		or string.find(smod, "swing", 1, true)
		or string.find(smod, "weapontest", 1, true)
		or string.find(smod, "weaponrunningattacktest", 1, true)
		or string.find(smod, "weaponaerialattacktest", 1, true)
		or string.find(smod, "weaponuppercuttest", 1, true)
		or string.find(smod, "weaponflourishtest", 1, true)
	then
		return "weapon-m1"
	end

	if
		string.find(smod, "silentheart", 1, true)
		or string.find(smod, "veinbreaker", 1, true)
		or string.find(smod, "curved", 1, true)
		or string.find(smod, "pyre", 1, true)
		or string.find(smod, "wraithclaw", 1, true)
		or string.find(smod, "mayhem", 1, true)
		or string.find(smod, "relentless", 1, true)
		or string.find(smod, "risingstar", 1, true)
		or string.find(smod, "runningcrit", 1, true)
	then
		return "weapon-special"
	end

	if timing.umoa then
		return "module"
	end

	return "other"
end

local function compactText(value)
	if typeof(value) ~= "string" then
		return ""
	end

	return string.gsub(lowerText(value), "[^%w]+", "")
end

local function identityText(timing, aid)
	return table.concat({
		compactText(timing and timing.smod),
		compactText(timing and timing.name),
		compactText(timing and timing._id),
		compactText(aid),
	}, " ")
end

local function storedMantraDisplayName(storedTool)
	if typeof(storedTool) ~= "string" then
		return nil
	end

	return string.match(storedTool, "{{(.-)}}")
		or string.match(storedTool, "^RecalledMantra:(.-)%$")
end

local function storedMantraInternalName(storedTool)
	if typeof(storedTool) ~= "string" or storedTool == "" then
		return nil
	end

	local descriptor = string.match(storedTool, "^(.-){{") or storedTool
	descriptor = string.match(descriptor, "([^:]+)$") or descriptor
	descriptor = string.gsub(descriptor, "%$$", "")
	if descriptor == "" or lowerText(descriptor) == "mantra" then
		return nil
	end
	return descriptor
end

local function replicatedMantraActionAliases(entity)
	local aliases = {}
	local seen = {}
	local storedTool = entity and entity:GetAttribute("StoredToolName")

	local function add(value)
		if typeof(value) ~= "string" or value == "" then
			return
		end
		local compact = compactText(value)
		if compact == "" or seen[compact] then
			return
		end
		seen[compact] = true
		aliases[#aliases + 1] = value
	end

	add(entity and entity:GetAttribute("StoredAction"))
	add(storedMantraDisplayName(storedTool))
	add(storedMantraInternalName(storedTool))
	return aliases
end

local MANTRA_CAST_SUFFIXES = {
	"newcharge",
	"windup",
	"startup",
	"release",
	"recall",
	"charge",
	"spring",
	"start",
	"cast",
	"spin",
	"go",
}

local MANTRA_CAST_ALIAS_OVERRIDES = {
	IceEruption = { "Ice Eruption", "Metal Eruption", "Mantra:EruptionMetal{{Metal Eruption}}" },
}

local function addCompactMantraAlias(aliases, compact, source, value)
	if compact == "" then
		return
	end

	aliases[compact] = aliases[compact] or string.format("%s=%s", source, tostring(value))
end

local function addMantraAlias(aliases, value, source)
	if typeof(value) ~= "string" or value == "" or value == "N/A" then
		return
	end

	local compact = compactText(value)
	addCompactMantraAlias(aliases, compact, source, value)

	local display = storedMantraDisplayName(value)
	if display then
		addCompactMantraAlias(aliases, compactText(display), source .. ":display", display)
	end

	for _, suffix in next, MANTRA_CAST_SUFFIXES do
		if #compact > #suffix + 3 and string.sub(compact, -#suffix) == suffix then
			addCompactMantraAlias(aliases, string.sub(compact, 1, -#suffix - 1), source .. ":base", value)
		end
	end
end

local function addMantraAliasesFromList(aliases, values, source)
	if typeof(values) == "string" then
		addMantraAlias(aliases, values, source)
		return
	end

	if typeof(values) ~= "table" then
		return
	end

	for _, value in next, values do
		addMantraAlias(aliases, value, source)
	end
end

local function mantraCastAliasSet(timing, aid)
	local aliases = {}

	addMantraAlias(aliases, timing and timing.smod, "timing.smod")
	addMantraAlias(aliases, timing and timing.name, "timing.name")
	addMantraAlias(aliases, timing and timing._id, "timing.id")
	addMantraAlias(aliases, aid, "aid")

	local descriptor = timing and timingOwnershipDescriptor(timing, aid)
	if descriptor then
		addMantraAlias(aliases, descriptor.label, "descriptor.label")
		addMantraAliasesFromList(aliases, descriptor.names or descriptor.exact, "descriptor.names")
		addMantraAliasesFromList(aliases, descriptor.contains, "descriptor.contains")
	end

	local smod = timing and typeof(timing.smod) == "string" and PP_SCRAMBLE_STR(timing.smod) or nil
	local name = timing and typeof(timing.name) == "string" and PP_SCRAMBLE_STR(timing.name) or nil

	addMantraAliasesFromList(aliases, smod and MANTRA_CAST_ALIAS_OVERRIDES[smod], "override.smod")
	addMantraAliasesFromList(aliases, name and MANTRA_CAST_ALIAS_OVERRIDES[name], "override.name")

	return aliases
end

local function mantraCastContext(entity, timing, aid)
	if not entity then
		return { status = "unknown", reason = "no-entity" }
	end

	local storedTool = entity:GetAttribute("StoredToolName")
	local storedAction = entity:GetAttribute("StoredAction")
	local storedDisplay = storedMantraDisplayName(storedTool)
	local aliases = mantraCastAliasSet(timing, aid)
	local candidates = {}

	local function addCandidate(value, source)
		local compact = compactText(value)
		if compact == "" then
			return
		end

		candidates[#candidates + 1] = source .. "=" .. tostring(value)

		if aliases[compact] then
			return compact
		end
	end

	local key = addCandidate(storedAction, "StoredAction")
		or addCandidate(storedDisplay, "StoredToolDisplay")

	if key then
		return {
			status = "match",
			reason = "stored-mantra-match",
			key = key,
			storedAction = storedAction,
			storedTool = storedTool,
			candidates = table.concat(candidates, "|"),
		}
	end

	if #candidates > 0 then
		return {
			status = "mismatch",
			reason = "stored-mantra-mismatch",
			key = compactText(storedAction) ~= "" and compactText(storedAction) or compactText(storedDisplay),
			storedAction = storedAction,
			storedTool = storedTool,
			candidates = table.concat(candidates, "|"),
		}
	end

	return {
		status = "unknown",
		reason = "missing-stored-mantra",
		storedAction = storedAction,
		storedTool = storedTool,
		candidates = "none",
	}
end

local function containsNeedle(haystack, needles)
	for _, needle in next, needles or {} do
		local compactNeedle = compactText(needle)
		if compactNeedle ~= "" and string.find(haystack, compactNeedle, 1, true) then
			return true
		end
	end

	return false
end

local function exactSmod(timing)
	if not timing or typeof(timing.smod) ~= "string" then
		return nil
	end

	return PP_SCRAMBLE_STR(timing.smod)
end

local function timingWeaponExpected(timing, category, aid)
	if not timingWeaponCategory(category) then
		return nil, "non-weapon-timing"
	end

	local smod = exactSmod(timing)
	local exact = smod and SPECIFIC_WEAPON_TIMINGS[smod]
	if exact then
		return exact, exact.reason or "specific-smod"
	end

	local haystack = identityText(timing, aid)

	for _, rule in next, SPECIFIC_WEAPON_PATTERNS do
		if containsNeedle(haystack, rule.needles) then
			return rule, rule.reason
		end
	end

	if containsNeedle(haystack, { "silentheart" }) then
		if containsNeedle(haystack, { "light" }) then
			return { classes = { Light = true }, family = "SilentheartLight", reason = "specific-silentheart-class" }, "specific-silentheart-class"
		elseif containsNeedle(haystack, { "medium", "med" }) then
			return { classes = { Medium = true }, family = "SilentheartMedium", reason = "specific-silentheart-class" }, "specific-silentheart-class"
		elseif containsNeedle(haystack, { "heavy" }) then
			return { classes = { Heavy = true }, family = "SilentheartHeavy", reason = "specific-silentheart-class" }, "specific-silentheart-class"
		end

		return nil, "silentheart-unknown-class"
	end

	for _, rule in next, GENERIC_WEAPON_PATTERNS do
		if containsNeedle(haystack, rule.needles) then
			return rule, rule.reason
		end
	end

	if containsNeedle(haystack, {
		"weapontest",
		"weaponaerialattacktest",
		"weaponflourishtest",
		"weaponrunningattacktest",
		"weaponuppercuttest",
	}) then
		return WEAPON_CONTEXT_ANY, WEAPON_CONTEXT_ANY.reason
	end

	return nil, "unmapped"
end

local function contextHasWeaponData(context)
	return context
		and (
			context.weaponName
			or context.primaryWeapon
			or context.weaponClass
			or context.weaponType
			or context.weaponDamageType
	)
end

local function weaponContextKey(context)
	if not contextHasWeaponData(context) then
		return nil
	end

	return table.concat({
		tostring(context.weaponName or context.primaryWeapon or "unknown"),
		tostring(context.weaponClass or "unknown"),
		tostring(context.weaponType or "unknown"),
	}, "|")
end

local function currentWeaponEvidenceKey(self)
	local player = self._playerOwner or players:GetPlayerFromCharacter(self.entity)
	if not player then
		return nil
	end

	local ok, context = pcall(PlayerScanning.weaponContext, player)
	if not ok or not context or context.status ~= "available" then
		return nil
	end

	return weaponContextKey(context)
end

local function carrierConnectedToEntity(entity, carrier)
	if not entity or not carrier or not carrier.Parent then
		return false
	end

	local checked = 0
	local function belongsTo(instance, ancestor)
		return instance == ancestor or instance:IsDescendantOf(ancestor)
	end
	local function jointConnects(joint)
		if not (joint:IsA("JointInstance") or joint:IsA("WeldConstraint")) then
			return false
		end

		local part0 = joint.Part0
		local part1 = joint.Part1
		return part0 ~= nil
			and part1 ~= nil
			and (
				(belongsTo(part0, entity) and belongsTo(part1, carrier))
				or (belongsTo(part1, entity) and belongsTo(part0, carrier))
			)
	end

	if jointConnects(carrier) then
		return true
	end

	for _, descendant in next, carrier:GetDescendants() do
		checked = checked + 1
		if jointConnects(descendant) then
			return true
		end
		if checked >= AP_WEAPON_SOUND_CARRIER_INSTANCE_LIMIT then
			break
		end
	end

	return false
end

local function weaponSoundCarrierRoot(instance)
	return instance:FindFirstAncestorWhichIsA("Model")
		or instance:FindFirstAncestorWhichIsA("BasePart")
end

local function exactWeaponSoundCandidate(self, now, weaponKey)
	local selected = nil
	for _, candidate in next, self.apAuthenticator.candidates or {} do
		local latency = now - candidate.startedAt
		if
			candidate.status == "pending"
			and timingWeaponCategory(candidate.category)
			and candidate.weaponKey == weaponKey
			and candidate.weaponContext
			and candidate.weaponContext.status == "confirmed"
			and candidate.weaponContext.exactWeaponTypeMatch == true
			and latency >= 0
			and latency <= AP_WEAPON_SOUND_EVIDENCE_LATENCY_MAX
			and now <= candidate.deadlineAt
			and candidate.track
			and candidate.track.IsPlaying
		then
			if selected then
				return nil
			end
			selected = candidate
		end
	end
	return selected
end

local function recordAPWeaponSound(self, sound, carrier)
	if
		not adcAdvancedAntiAPBreak
		or not self.apAdvancedEnabled
		or not self.apTrackingActive
		or not self._isFromPlayer
		or not sound:IsDescendantOf(carrier)
		or not carrierConnectedToEntity(self.entity, carrier)
	then
		return
	end

	local weaponKey = currentWeaponEvidenceKey(self)
	if not weaponKey then
		return
	end

	local now = os.clock()
	local candidate = exactWeaponSoundCandidate(self, now, weaponKey)
	if not candidate then
		return
	end

	self:recordAttackEvidence({
		kind = "replicated-weapon-sound",
		at = now,
		authoritative = true,
		retainForFutureCandidate = false,
		weaponKey = weaponKey,
		exactFamily = candidate.category,
		families = { [candidate.category] = true },
		requireExactWeaponType = true,
		latencyMin = 0,
		latencyMax = AP_WEAPON_SOUND_EVIDENCE_LATENCY_MAX,
		centralLatencyMin = 0,
		centralLatencyMax = AP_WEAPON_SOUND_EVIDENCE_LATENCY_MAX,
		uncertainty = AP_WEAPON_SOUND_EVIDENCE_LATENCY_MAX,
		causalCandidateId = candidate.id,
		causalTrack = candidate.track,
		causalOccurrence = candidate.occurrence,
	})
end

local function bindAPWeaponSound(self, sound, carrier)
	if self.apWeaponSounds[sound] then
		return
	end

	self.apWeaponSounds[sound] = carrier
	self.apMaid[sound] = sound.Played:Connect(function()
		recordAPWeaponSound(self, sound, carrier)
	end)
end

bindAPWeaponSoundCarrier = function(self, carrier)
	if self.apWeaponSoundRoots[carrier] then
		return true
	end
	if
		not carrier
		or not carrier.Parent
		or not carrierConnectedToEntity(self.entity, carrier)
	then
		return false
	end

	local root = carrier:IsA("Model") and carrier or weaponSoundCarrierRoot(carrier)
	if not root or not carrierConnectedToEntity(self.entity, root) then
		return false
	end
	if self.apWeaponSoundRoots[root] then
		return true
	end

	self.apWeaponSoundRoots[root] = true
	self.apMaid[root] = root.DescendantAdded:Connect(function(descendant)
		if descendant:IsA("Sound") then
			bindAPWeaponSound(self, descendant, root)
		end
	end)

	for _, descendant in next, root:GetDescendants() do
		if descendant:IsA("Sound") then
			bindAPWeaponSound(self, descendant, root)
		end
	end
	return true
end

refreshAPWeaponSounds = function(self)
	if not self.apAdvancedEnabled or not self.entity or not self.entity.Parent then
		return
	end

	self.apNextWeaponSoundRefreshAt = os.clock() + AP_WEAPON_SOUND_REFRESH_INTERVAL
	local thrown = workspace:FindFirstChild("Thrown")
	local carrier = thrown and thrown:FindFirstChild("Attach_" .. self.entity.Name)
	if carrier then
		bindAPWeaponSoundCarrier(self, carrier)
	end
end

disconnectAPWeaponSounds = function(self)
	for sound in next, self.apWeaponSounds or {} do
		self.apMaid[sound] = nil
	end
	for root in next, self.apWeaponSoundRoots or {} do
		self.apMaid[root] = nil
	end
	self.apWeaponSounds = setmetatable({}, { __mode = "k" })
	self.apWeaponSoundRoots = setmetatable({}, { __mode = "k" })
	self.apNextWeaponSoundRefreshAt = 0
end

local function setMatchesExact(set, value)
	if not set or typeof(value) ~= "string" or value == "" then
		return false, false
	end

	local compactValue = compactText(value)
	if compactValue == "" then
		return false, false
	end

	for expected, _ in next, set do
		if compactValue == compactText(expected) then
			return true, true
		end
	end

	return false, true
end

local function exactNameMatches(descriptor, context)
	local nameText = table.concat({
		compactText(context.primaryWeapon),
		compactText(context.weaponName),
	}, " ")

	if nameText == "" then
		return nil, "missing-weapon-name"
	end

	for _, expected in next, descriptor.exactNames or {} do
		local compactExpected = compactText(expected)
		if compactExpected ~= "" and string.find(nameText, compactExpected, 1, true) then
			return true, "exact-name"
		end
	end

	return false, "exact-name-conflict"
end

local function familyMatches(descriptor, context)
	if descriptor.classes and context.weaponClass then
		local matched = setMatchesExact(descriptor.classes, context.weaponClass)
		if matched then
			return true, "class"
		end

		return false, "class-conflict"
	end

	local typeMatched, typeChecked = setMatchesExact(descriptor.types, context.weaponType)
	if typeMatched then
		return true, "type"
	end

	local damageMatched, damageChecked = setMatchesExact(descriptor.damageTypes, context.weaponDamageType)
	if damageMatched then
		return true, "damage-type"
	end

	if typeChecked or damageChecked then
		return false, "family-conflict"
	end

	return nil, "missing-family-context"
end

local function replicatedNamedWeaponDescriptor(timing, aid, data)
	if not data or data.status ~= "available" then
		return nil
	end

	local haystack = identityText(timing, aid)
	local exactNames = {}
	local seen = {}
	for _, value in next, { data.primaryWeapon, data.weaponName } do
		local compactValue = compactText(value)
		if
			#compactValue >= 5
			and string.find(haystack, compactValue, 1, true)
			and not seen[compactValue]
		then
			seen[compactValue] = true
			exactNames[#exactNames + 1] = value
		end
	end

	if #exactNames == 0 then
		return nil
	end

	return {
		exactNames = exactNames,
		family = data.weaponType or data.weaponClass or "NamedWeapon",
		reason = "replicated-weapon-name",
	}
end

local function readEquippedWeaponContext(entity, timing, category, aid)
	if not entity then
		return { status = "unknown", reason = "no-entity" }
	end

	local player = players:GetPlayerFromCharacter(entity)
	if not player then
		return { status = "not-applicable", reason = "npc" }
	end

	if not timingWeaponCategory(category) then
		return { status = "not-applicable", reason = "non-weapon-timing" }
	end

	local expected, expectedReason = timingWeaponExpected(timing, category, aid)
	local context = {
		status = "unknown",
		reason = expectedReason,
		timingWeaponFamily = expected and expected.family or nil,
	}

	if not expected and not adcAdvancedAntiAPBreak then
		context.reason = expectedReason or "unmapped"
		context.expectedDescriptor = expected
		return context
	end

	local dataOk, data = pcall(PlayerScanning.weaponContext, player)
	if not dataOk or not data then
		return {
			status = "unknown",
			reason = "weapon-context-read-failed",
			expectedDescriptor = expected,
			timingWeaponFamily = expected and expected.family or nil,
		}
	end

	for key, value in next, data do
		context[key] = value
	end

	context.status = "unknown"
	context.reason = data.status == "available" and expectedReason or (data.reason or "weapon-context-unknown")
	context.expectedDescriptor = expected
	context.timingWeaponFamily = expected and expected.family or nil

	if data.status ~= "available" or not contextHasWeaponData(data) then
		return context
	end

	if not expected then
		expected = replicatedNamedWeaponDescriptor(timing, aid, data)
		if not expected then
			context.reason = expectedReason or "unmapped"
			return context
		end

		expectedReason = expected.reason
		context.expectedDescriptor = expected
		context.timingWeaponFamily = expected.family
		context.reason = expectedReason
	end

	local exactTypeMatch, exactTypeChecked = setMatchesExact(expected.types, data.weaponType)
	context.exactWeaponTypeMatch = exactTypeMatch == true
	context.exactWeaponTypeChecked = exactTypeChecked == true

	if expected.anyWeapon then
		context.status = "confirmed"
		context.reason = expected.reason or "any-weapon-context"
		return context
	end

	local matched, reason
	if expected.exactNames then
		matched, reason = exactNameMatches(expected, data)
	else
		matched, reason = familyMatches(expected, data)
	end

	if matched == true then
		context.status = "confirmed"
		context.reason = reason
	elseif matched == false then
		context.status = "mismatch"
		context.reason = reason
	else
		context.reason = reason or context.reason
	end

	return context
end

local function earliestTimingAction(timing)
	local earliest = nil
	if not timing or not timing.actions or timing.actions:count() <= 0 then
		return nil
	end

	for _, action in next, timing.actions:get() do
		local ok, when = pcall(function()
			return action:when()
		end)
		when = ok and tonumber(when) or tonumber(action._when)
		if when and when >= 0 and (earliest == nil or when < earliest) then
			earliest = when
		end
	end

	return earliest
end

local function realPhysicsFps()
	local ok, fps = pcall(function()
		return workspace:GetRealPhysicsFPS()
	end)
	if not ok or typeof(fps) ~= "number" or fps <= 0 then
		return 60
	end
	return math.max(15, fps)
end

local function occurrenceAuthenticationContext(self, track, timing, aid, report, startedAt)
	local category = apTimingCategory(timing)
	local weaponContext = readEquippedWeaponContext(self.entity, timing, category, aid)
	local speed = math.abs(tonumber(track.Speed) or 0)
	local length = tonumber(track.Length) or 0
	local expectedDuration = speed > SPEED_EPSILON and length / speed or length
	local legalInterval = tonumber(weaponContext.weaponAttackDuration)
		or (expectedDuration > 0 and expectedDuration)
		or AP_ACTIVE_TIMEOUT
	local earliest = earliestTimingAction(timing)
	local schedulingDelay = earliest and math.max(0, earliest - Latency.rdelay() - Latency.sdelay()) or legalInterval
	local safetyMargin = math.max(2 / realPhysicsFps(), 0.02)
	local authenticationDelay = schedulingDelay
	if category == "mantra" and timing.katalystRangeOnly then
		authenticationDelay = math.max(
			authenticationDelay,
			math.min(legalInterval, AP_MANTRA_ROOT_EVIDENCE_LATENCY_MAX)
		)
	end
	local plannedDefenseAt = startedAt + schedulingDelay
	local deadlineAt = startedAt + math.max(0, authenticationDelay - safetyMargin)
	local raw = report and report.raw or {}
	local geometricPlausible = raw.plausible == true
		or (raw.geometricPlausibility ~= nil and raw.geometricPlausibility ~= "none")
	local actionKey = raw.mantraEtherContextKey or raw.mantraEtherClaimedKey

	return {
		track = track,
		occurrence = self.apTrackOccurrences[track],
		timing = timing,
		aid = aid,
		category = category,
		weaponContext = weaponContext,
		startedAt = startedAt,
		plannedDefenseAt = plannedDefenseAt,
		deadlineAt = deadlineAt,
		legalInterval = legalInterval,
		longestTiming = math.max(legalInterval, expectedDuration, earliest or 0),
		expectedDuration = expectedDuration,
		evidenceLatencyMax = category == "weapon-critical"
				and AP_CRITICAL_EVIDENCE_LATENCY_MAX
			or AP_WEAPON_EVIDENCE_LATENCY_MAX,
		progressionGrace = safetyMargin,
		geometricPlausible = geometricPlausible,
		comboContinuous = true,
		actionKey = actionKey,
		timingActionNames = {
			timing.name,
			timing.smod,
		},
		classifierBlocked = report and report.block == true,
		callbackDispatchDeadlineAt = startedAt + safetyMargin,
		recoveredIngress = self.apRecoveredOccurrences[track] == self.apTrackOccurrences[track],
	}
end

local function evidenceInstanceBelongsToEntity(self, instance, data)
	if typeof(data) == "table" and data.char == self.entity then
		return true
	end

	if typeof(instance) ~= "Instance" then
		return false
	end

	if instance:IsDescendantOf(self.entity) then
		return true
	end

	local owner = self._playerOwner or players:GetPlayerFromCharacter(self.entity)
	local ownerName = owner and owner.Name or self.entity.Name
	local current = instance
	for _ = 1, 6 do
		if not current then
			break
		end

		if string.find(current.Name, ownerName, 1, true) then
			return true
		end
		current = current.Parent
	end

	return false
end

function AnimatorDefender:cancelAuthenticatedOccurrence(candidate)
	for index, actionTask in next, self.tasks do
		if
			actionTask.sourceTrack == candidate.track
			and actionTask.sourceOccurrence == candidate.occurrence
			and coroutine.status(actionTask.thread) ~= "dead"
		then
			actionTask:cancel()
			self.tasks[index] = nil

			if actionTask.identifier == "End Block" or actionTask.identifier == "Start Block" then
				QueuedBlocking.stop(actionTask.blockRequestId or self.blockRequestId, "authenticated-cancel")
			end
		end
	end
end

local promoteQuarantinedIngress
local pruneIngressQuarantine

function AnimatorDefender:recordAttackEvidence(evidence)
	if
		not self.apAuthenticator
		or not adcAdvancedAntiAPBreak
		or not self.apAdvancedEnabled
		or not self._isFromPlayer
	then
		return nil, "inactive"
	end

	if evidence.allowWeaponFamilyBridge and not evidence.candidateSetSettled then
		local retry = {}
		for key, value in next, evidence do
			retry[key] = value
		end
		retry.candidateSetSettled = true

		local generation = self.apEvidenceGeneration
		local settleDelay = math.max(2 / realPhysicsFps(), AP_CRITICAL_CANDIDATE_SETTLE_FLOOR)
		TaskSpawner.delayOwned(self.apMaid, "AnimatorDefender_CriticalCandidateSettle", settleDelay, function()
			if
				adcAdvancedAntiAPBreak
				and self.apAdvancedEnabled
				and self.apTrackingActive
				and self.apEvidenceGeneration == generation
			then
				self:recordAttackEvidence(retry)
			end
		end)
		return nil, "candidate-settle-pending"
	end

	if evidence.authoritative and not evidence.causalCandidateId and promoteQuarantinedIngress then
		if evidence._ingressRecoveryAdmitted == nil then
			local owner = self._playerOwner or players:GetPlayerFromCharacter(self.entity)
			evidence._ingressRecoveryAdmitted = owner == nil
				or AnimationIngressGuard.admitRecovery(owner)
		end
		if evidence._ingressRecoveryAdmitted then
			local promoted = promoteQuarantinedIngress(self, evidence)
			if promoted then
				evidence.causalCandidateId = promoted.id
				evidence.causalTrack = promoted.track
				evidence.causalOccurrence = promoted.occurrence
			end
		end
	end

	local candidate, reason = self.apAuthenticator:recordEvidence(evidence)
	if not candidate then
		return nil, reason
	end

	TaskSpawner.deferOwned(self.apMaid, "AnimatorDefender_AuthenticatedEvidence", function()
		if
			self.apAuthenticator:isAuthenticated(candidate.track, candidate.occurrence)
		then
			self:process(candidate.track, candidate.occurrence)
		end
	end)

	return candidate, reason
end

recordReplicatedMantraIntent = function(self, serial)
	if
		not adcAdvancedAntiAPBreak
		or not self.apAdvancedEnabled
		or self.apMantraIntentRecordedSerial == serial
		or self.apMantraEtherSpendSerial ~= serial
	then
		return
	end

	local actionKey = string.lower(tostring(self.entity:GetAttribute("StoredAction") or "")):gsub("[^%w]", "")
	local storedTool = self.entity:GetAttribute("StoredToolName")
	if actionKey == "" or actionKey == "criticalattack" or typeof(storedTool) ~= "string" or storedTool == "" then
		return
	end

	local spendAt = self.apMantraEtherLastSpendAt
	if not spendAt or os.clock() - spendAt > AP_MANTRA_ETHER_SPEND_WINDOW then
		return
	end

	self.apMantraIntentRecordedSerial = serial
	local frameWindow = math.max(2 / realPhysicsFps(), AP_MANTRA_EVIDENCE_SETTLE)
	self:recordAttackEvidence({
		kind = "replicated-mantra-intent",
		at = spendAt,
		authoritative = true,
		retainForFutureCandidate = true,
		exactFamily = "mantra",
		families = { mantra = true },
		actionKey = actionKey,
		actionAliases = replicatedMantraActionAliases(self.entity),
		requireTimingActionMatch = true,
		latencyMin = -AP_MANTRA_ETHER_SPEND_WINDOW,
		latencyMax = AP_MANTRA_ROOT_EVIDENCE_LATENCY_MAX,
		centralLatencyMin = -frameWindow,
		centralLatencyMax = frameWindow,
		uncertainty = frameWindow,
		serial = serial,
	})
end

function AnimatorDefender:queueMantraEvidence(candidate, report)
	local raw = report and report.raw
	if not raw or candidate.category ~= "mantra" then
		return
	end

	local serial = tonumber(raw.mantraEtherSerial)
	local contextStatus = raw.mantraEtherContext
	local actionKey = raw.mantraEtherContextKey or raw.mantraEtherClaimedKey
	local spendStatus = raw.mantraEtherStatus
	if not serial or not actionKey or contextStatus ~= "match" or spendStatus ~= "spent" then
		return
	end

	if self.apQueuedMantraEvidence[serial] then
		return
	end

	local queue = {
		serial = serial,
		actionKey = actionKey,
		createdAt = os.clock(),
		candidateId = candidate.id,
		track = candidate.track,
		occurrence = candidate.occurrence,
	}
	self.apQueuedMantraEvidence[serial] = queue

	TaskSpawner.delayOwned(self.apMaid, "AnimatorDefender_MantraEvidenceSettle", AP_MANTRA_EVIDENCE_SETTLE, function()
		if
			self.apQueuedMantraEvidence[serial] ~= queue
			or not adcAdvancedAntiAPBreak
			or not self.apAdvancedEnabled
			or not self.apTrackingActive
			or self.apAuthenticator:getCandidate(queue.track, queue.occurrence) ~= candidate
			or candidate.id ~= queue.candidateId
			or candidate.status ~= "pending"
		then
			return
		end

		self.apQueuedMantraEvidence[serial] = nil
		self:recordAttackEvidence({
			kind = "replicated-mantra-ether-action",
			at = os.clock(),
			authoritative = true,
			exactFamily = "mantra",
			families = { mantra = true },
			actionKey = actionKey,
			latencyMin = -0.05,
			latencyMax = 0.25,
			centralLatencyMin = -0.02,
			centralLatencyMax = 0.12,
			uncertainty = AP_MANTRA_EVIDENCE_SETTLE,
			serial = serial,
			causalCandidateId = queue.candidateId,
			causalTrack = queue.track,
			causalOccurrence = queue.occurrence,
		})
	end)
end

function AnimatorDefender:apce(effect, data)
	if
		not adcAdvancedAntiAPBreak
		or not self.apAdvancedEnabled
		or not self._isFromPlayer
		or typeof(effect) ~= "string"
		or typeof(data) ~= "table"
	then
		return
	end

	local prop = data.prop
	if not evidenceInstanceBelongsToEntity(self, prop, data) then
		return
	end
	if typeof(prop) == "Instance" and bindAPWeaponSoundCarrier then
		bindAPWeaponSoundCarrier(self, prop)
	end

	local now = os.clock()
	local currentWeaponKey = currentWeaponEvidenceKey(self)
	if effect == "WeaponTrailOff" then
		local cancelled = self.apAuthenticator:cancelFromEvidence({
			kind = "replicated-weapon-trail-off",
			at = now,
			weaponKey = currentWeaponKey,
		})
		for _, candidate in next, cancelled do
			self:cancelAuthenticatedOccurrence(candidate)
		end
		return
	end

	if effect == "WeaponTrail" then
		self:recordAttackEvidence({
			kind = "replicated-weapon-trail",
			at = now,
			authoritative = true,
			weaponKey = currentWeaponKey,
			duration = tonumber(data.dur),
			families = {
				["weapon-m1"] = true,
				["weapon-critical"] = true,
				["weapon-special"] = true,
			},
			latencyMin = AP_WEAPON_EVIDENCE_LATENCY_MIN,
			latencyMax = AP_WEAPON_EVIDENCE_LATENCY_MAX,
			centralLatencyMin = AP_WEAPON_EVIDENCE_LATENCY_MIN,
			centralLatencyMax = AP_WEAPON_EVIDENCE_CENTRAL_MAX,
			uncertainty = 0.02,
		})
	elseif effect == "CriticalSwirl" then
		self:recordAttackEvidence({
			kind = "replicated-critical-effect",
			at = now,
			authoritative = true,
			weaponKey = currentWeaponKey,
			duration = tonumber(data.dur),
			exactFamily = "weapon-critical",
			families = { ["weapon-critical"] = true },
			allowWeaponFamilyBridge = true,
			latencyMin = AP_CRITICAL_EVIDENCE_LATENCY_MIN,
			latencyMax = AP_CRITICAL_EVIDENCE_LATENCY_MAX,
			centralLatencyMin = AP_WEAPON_EVIDENCE_LATENCY_MIN,
			centralLatencyMax = AP_WEAPON_EVIDENCE_CENTRAL_MAX,
			uncertainty = 0.02,
		})
	end
end

function AnimatorDefender:apae(name)
	if
		not adcAdvancedAntiAPBreak
		or not self.apAdvancedEnabled
		or not self._isFromPlayer
	then
		return
	end

	if name == "StoredToolName" or name == "PrimaryWeapon" or name == "Weapon" then
		if refreshAPWeaponSounds then
			refreshAPWeaponSounds(self)
		end
		return
	end
	if name ~= "StoredAction" then
		return
	end

	if recordReplicatedMantraIntent and self.apMantraEtherSpendSerial > 0 then
		recordReplicatedMantraIntent(self, self.apMantraEtherSpendSerial)
	end

	local storedAction = self.entity:GetAttribute("StoredAction")
	if compactText(storedAction) ~= "criticalattack" then
		return
	end

	self:recordAttackEvidence({
		kind = "replicated-stored-critical",
		at = os.clock(),
		authoritative = true,
		weaponKey = currentWeaponEvidenceKey(self),
		exactFamily = "weapon-critical",
		families = { ["weapon-critical"] = true },
		allowWeaponFamilyBridge = true,
		latencyMin = AP_CRITICAL_EVIDENCE_LATENCY_MIN,
		latencyMax = AP_CRITICAL_EVIDENCE_LATENCY_MAX,
		centralLatencyMin = AP_WEAPON_EVIDENCE_LATENCY_MIN,
		centralLatencyMax = AP_WEAPON_EVIDENCE_CENTRAL_MAX,
		uncertainty = 0.02,
	})
end

function AnimatorDefender:isOccurrenceCurrent(track, occurrence)
	return occurrence == nil or self.apTrackOccurrences[track] == occurrence
end

function AnimatorDefender:isOccurrenceAuthenticated(track, occurrence)
	if not occurrence then
		return false
	end

	if
		adcAdvancedAntiAPBreak
		and self.apAdvancedEnabled
		and self.apAuthenticator
		and self.apAuthenticator:isAuthenticated(track, occurrence)
	then
		return true
	end

	local confirmed = self.apOccurrenceConfirmed[track]
	if confirmed and confirmed.occurrence == occurrence then
		return true
	end

	local critical = self.apCriticalConfirmed[track]
	return critical ~= nil and critical.occurrence == occurrence
end

function AnimatorDefender:markOccurrenceIssued(track, occurrence)
	if adcAdvancedAntiAPBreak and self.apAdvancedEnabled and self.apAuthenticator then
		self.apAuthenticator:markIssued(track, occurrence)
	end
end

function AnimatorDefender:claimOccurrenceSchedule(track, occurrence)
	if not occurrence then
		return true
	end

	if self.apScheduledOccurrences[track] == occurrence then
		return false
	end

	self.apScheduledOccurrences[track] = occurrence
	return true
end

AnimatorDefender.stopped = (function(self, track, timing, _, occurrence)
	local authenticated = self:isOccurrenceAuthenticated(track, occurrence)
	local advancedTransaction = adcAdvancedAntiAPBreak and self.apAdvancedEnabled and authenticated
	if not self:isOccurrenceCurrent(track, occurrence) and not advancedTransaction then
		return true
	end

	if
		adcAdvancedAntiAPBreak
		and self.apAdvancedEnabled
		and self.apAuthenticator
		and occurrence
		and not self.apAuthenticator:isOccurrenceValid(track, occurrence)
	then
		return true
	end

	if authenticated then
		return false
	end

	if not timing.iae and not track.IsPlaying then
		return true
	end

	if timing.iae and not timing.ieae and not track.IsPlaying and track.TimePosition < track.Length then
		return true
	end
end)

AnimatorDefender.rc = (function(self, info)
	if not info.track then
		return false
	end

	if self:stopped(info.track, info.timing, nil, info.occurrence) then
		return false
	end

	if info.timing.iae and os.clock() - info.start >= ((info.timing.mat / 1000) or MAX_REPEAT_TIME) then
		return false
	end

	return true
end)

AnimatorDefender.pfh = (function(self, options)
	local root = self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	local localRoot = players.LocalPlayer.Character and players.LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
	if not localRoot then
		return false
	end

	if not options.timing.ffh then
		local yrate = EntityHistory.yrate(self.entity)
		if not yrate then
			return false
		end

		if math.abs(yrate) < PREDICT_FACING_DELTA then
			return
		end
	end

	local clone = options:clone()
	clone.hcolor = Color3.new(0, 1, 1)
	clone.mcolor = Color3.new(1, 1, 0)
	clone:ucache()

	local result = false
	local store = OriginalStore.new()

	store:run(root, "CFrame", CFrame.lookAt(root.Position, localRoot.Position), function()
		result = self:hc(clone, nil)
	end)

	return result
end)

AnimatorDefender.phd = (function(self, timing, options)
	for _, cframe in next, EntityHistory.pstepped(self.entity, HISTORY_STEPS, timing.phds) or {} do
		local clone = options:clone()
		clone.cframe = cframe
		clone.hcolor = Color3.new(0.839215, 0.976470, 0.537254)
		clone.mcolor = Color3.new(0.564705, 0, 1)
		clone:ucache()

		if not self:hc(clone, nil) then
			continue
		end

		return true
	end
end)

AnimatorDefender.fpc = (function(self, timing, options)
	if timing.duih then
		return false
	end

	if (timing.ffh or timing.pfh) and self:pfh(options) then
		return true
	end

	if timing.phd and self:phd(timing, options) then
		return true
	end
end)

AnimatorDefender.capb = (function(self, now)
	if now < (self.apNextMaintenanceAt or 0) then
		return
	end
	self.apNextMaintenanceAt = now + AP_MAINTENANCE_INTERVAL

	self.apRecentIds = self.apRecentIds or {}
	self.apTrackOccurrences = self.apTrackOccurrences or {}
	self.apCriticalPending = self.apCriticalPending or {}
	self.apCriticalConfirmed = self.apCriticalConfirmed or {}
	self.apCriticalConfirmedSources = self.apCriticalConfirmedSources or {}
	self.apOccurrencePending = self.apOccurrencePending or {}
	self.apOccurrenceConfirmed = self.apOccurrenceConfirmed or {}

	for track, data in next, self.apCriticalPending do
		if
			self.apTrackOccurrences[track] ~= data.occurrence
			or not track.IsPlaying
			or now - data.startedAt > AP_CRITICAL_CONFIRM_DELAY * 2
		then
			self.apCriticalPending[track] = nil
		end
	end

	for track, data in next, self.apCriticalConfirmed do
		if self.apTrackOccurrences[track] ~= data.occurrence or now - data.startedAt > AP_ACTIVE_TIMEOUT then
			self.apCriticalConfirmed[track] = nil
			self.apCriticalConfirmedSources[track] = nil
		end
	end

	for track, data in next, self.apOccurrencePending do
		if
			self.apTrackOccurrences[track] ~= data.occurrence
			or now - data.startedAt > AP_OCCURRENCE_BLEND_CONFIRM_DELAY * 3
		then
			self.apOccurrencePending[track] = nil
		end
	end

	for track, data in next, self.apOccurrenceConfirmed do
		if self.apTrackOccurrences[track] ~= data.occurrence or now - data.startedAt > AP_ACTIVE_TIMEOUT then
			self.apOccurrenceConfirmed[track] = nil
		end
	end

	for track, data in next, self.apActive do
		if track.IsPlaying and now - data.start <= AP_ACTIVE_TIMEOUT then
			continue
		end

		disconnectAPActiveData(data)

		if data.suspicious and not data.shortRecorded and now - data.start <= AP_SHORT_ACTIVE_DURATION then
			self.apShortDurations[#self.apShortDurations + 1] = now
		end

		self.apActive[track] = nil
		self.apActiveCount = math.max(0, (self.apActiveCount or 1) - 1)
	end

	pruneHistory(self.apGlobalHistory, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)
	pruneHistory(self.apShortDurations, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)
	pruneIdHistory(self.apRecentIds, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)

	for _, history in next, self.apHistory do
		pruneHistory(history, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)
	end
end)

AnimatorDefender.sapb = (function(self)
	if self.apTrackingActive and self.apAdvancedEnabled ~= adcAdvancedAntiAPBreak then
		self:setAdvancedAntiAP(adcAdvancedAntiAPBreak)
	end
end)

AnimatorDefender.apme = (function(self, timing, aid, now)
	if not self._isFromPlayer then
		return { status = "not-applicable", reason = "npc" }
	end

	if not self.entity then
		return { status = "unknown", reason = "no-entity" }
	end

	local castContext = mantraCastContext(self.entity, timing, aid)
	local ether = self.entity:FindFirstChild("Ether")
	setAPMantraEtherSource(self, ether, now)

	if not ether then
		return { status = "unknown", reason = "missing-ether" }
	end

	local current = readAPMantraEtherValue(ether)
	noteAPMantraEtherValue(self, current, now)

	if not self.apMantraEtherValue then
		return { status = "unknown", reason = "unreadable-ether" }
	end

	if self.apMantraEtherLastSpendAt then
		local spendAge = now - self.apMantraEtherLastSpendAt
		if spendAge <= AP_MANTRA_ETHER_SPEND_WINDOW then
			local serial = self.apMantraEtherSpendSerial or 0
			local contextStatus = castContext.status
			local contextKey = castContext.key or "unknown"
			local base = {
				value = self.apMantraEtherValue,
				age = spendAge,
				delta = self.apMantraEtherLastSpendAmount,
				serial = serial,
				context = contextStatus,
				contextReason = castContext.reason,
				contextKey = contextKey,
				storedAction = castContext.storedAction,
				storedTool = castContext.storedTool,
				candidates = castContext.candidates,
			}

			if self.apMantraEtherClaimedSerial == serial then
				base.status = "claimed"
				base.reason = "ether-spend-already-claimed"
				base.claimedKey = self.apMantraEtherClaimedKey
				base.claimedAid = self.apMantraEtherClaimedAid
				return base
			end

			if contextStatus == "mismatch" then
				base.status = "mismatch"
				base.reason = "stored-mantra-mismatch"
				return base
			end

			self.apMantraEtherClaimedSerial = serial
			self.apMantraEtherClaimedKey = contextKey
			self.apMantraEtherClaimedAid = aid

			base.status = "spent"
			base.reason = contextStatus == "match" and "recent-ether-drop-matched" or "recent-ether-drop-unmatched"
			return {
				status = base.status,
				reason = base.reason,
				value = base.value,
				age = base.age,
				delta = base.delta,
				serial = base.serial,
				context = base.context,
				contextReason = base.contextReason,
				contextKey = base.contextKey,
				storedAction = base.storedAction,
				storedTool = base.storedTool,
				candidates = base.candidates,
			}
		end
	end

	if self.apMantraEtherResolvedAt and now - self.apMantraEtherResolvedAt <= AP_MANTRA_ETHER_BASELINE_GRACE then
		return {
			status = "unknown",
			reason = "fresh-ether-baseline",
			value = self.apMantraEtherValue,
			context = castContext.status,
			contextReason = castContext.reason,
			contextKey = castContext.key,
			storedAction = castContext.storedAction,
			storedTool = castContext.storedTool,
			candidates = castContext.candidates,
		}
	end

	return {
		status = "no-spend",
		reason = "no-recent-ether-drop",
		value = self.apMantraEtherValue,
		age = self.apMantraEtherLastSpendAt and (now - self.apMantraEtherLastSpendAt) or nil,
		context = castContext.status,
		contextReason = castContext.reason,
		contextKey = castContext.key,
		storedAction = castContext.storedAction,
		storedTool = castContext.storedTool,
		candidates = castContext.candidates,
	}
end)

AnimatorDefender.apbh = (function(self, timing)
	local root = self.entity and self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return false, "no-root"
	end

	local character = players.LocalPlayer.Character
	if not character then
		return false, "no-local-character"
	end

	if not self:target(self.entity) then
		return false, "not-target"
	end

	local action = nil
	if timing.actions and timing.actions:count() > 0 then
		for _, candidate in next, timing.actions:get() do
			action = candidate
			break
		end
	end

	if timing.katalystRangeOnly then
		return true, "range-only"
	end

	local hoptions = HitboxOptions.new(root, timing)
	hoptions.spredict = not timing.duih and not timing.dp
	hoptions.ptime = self:fsecs(timing)
	hoptions.action = action
	hoptions.entity = self.entity
	hoptions:ucache()

	if self:hc(hoptions, nil) then
		return true, "direct-hitbox"
	end

	if timing.duih then
		return false, "delay-until-hitbox"
	end

	if (timing.ffh or timing.pfh) and self:pfh(hoptions) then
		return true, "facing-prediction"
	end

	if timing.phd and self:phd(timing, hoptions) then
		return true, "past-position"
	end

	return false, "no-real-hit-evidence"
end)

AnimatorDefender.rapb = (function(self, track, timing, aid, report, now, occurrence)
	self.apRecentIds = self.apRecentIds or {}

	local history = self.apHistory[aid]
	if not history then
		if self.apHistorySlotCount < AP_HISTORY_ID_LIMIT then
			self.apHistorySlotCount = self.apHistorySlotCount + 1
			self.apHistorySlots[self.apHistorySlotCount] = aid
		else
			local cursor = self.apHistorySlotCursor
			local evictedAid = self.apHistorySlots[cursor]
			if evictedAid then
				self.apHistory[evictedAid] = nil
			end
			self.apHistorySlots[cursor] = aid
			self.apHistorySlotCursor = cursor % AP_HISTORY_ID_LIMIT + 1
		end
		history = {}
		self.apHistory[aid] = history
	end

	history[#history + 1] = now
	self.apGlobalHistory[#self.apGlobalHistory + 1] = now
	self.apRecentIds[#self.apRecentIds + 1] = {
		time = now,
		aid = aid,
		category = report and report.raw and report.raw.category or apTimingCategory(timing),
	}
	self.apLastKnownTime = now

	pruneHistory(history, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)
	pruneHistory(self.apGlobalHistory, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)
	pruneIdHistory(self.apRecentIds, now, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)

	if report and report.score >= 3 then
		local previous = self.apActive[track]
		if previous then
			disconnectAPActiveData(previous)
		else
			if self.apActiveCount >= AP_ACTIVE_LIMIT then
				local oldestTrack = nil
				local oldestStart = math.huge
				for activeTrack, activeData in next, self.apActive do
					if activeData.start < oldestStart then
						oldestTrack = activeTrack
						oldestStart = activeData.start
					end
				end
				if oldestTrack then
					disconnectAPActiveData(self.apActive[oldestTrack])
					self.apActive[oldestTrack] = nil
					self.apActiveCount = math.max(0, self.apActiveCount - 1)
				end
			end
			self.apActiveCount = self.apActiveCount + 1
		end

		local data = {
			start = now,
			occurrence = occurrence,
			suspicious = true,
			timing = timing,
			aid = aid,
		}
		self.apActive[track] = data

		if track.Stopped then
			data.stopConn = Signal.new(track.Stopped):connect("AnimatorDefender_AntiAPBreakStopped", function()
				local active = self.apActive[track]
				if not active or active.occurrence ~= occurrence then
					return
				end

				local stoppedAt = os.clock()
				active.activeTime = stoppedAt - active.start

				if active.suspicious and not active.shortRecorded and active.activeTime <= AP_SHORT_ACTIVE_DURATION then
					active.shortRecorded = true
					self.apShortDurations[#self.apShortDurations + 1] = stoppedAt
					pruneHistory(self.apShortDurations, stoppedAt, ADVANCED_AP_WINDOW, AP_HISTORY_LIMIT)
				end

				if report.raw then
					report.raw.activeTime = active.activeTime
				end

				if active.stopConn then
					active.stopConn:Disconnect()
					active.stopConn = nil
				end
			end)
			if data.stopConn then
				data.monitorCounted = true
				AnimationIngressGuard.monitorAdded()
			end
		end
	end
end)

AnimatorDefender.aapb = (function(self, track, timing, aid)
	local now = os.clock()
	self:capb(now)

	local score = 0
	local trust = 0
	local suspiciousCount = 0
	local protected = false
	local plausible = false
	local realHitEvidence = "none"
	local geometricPlausible = false
	local geometricPlausibility = "none"
	local signals = {}
	local trustSignals = {}
	local facts = {}
	local ownership = apBreakOwnership(self, timing, aid)
	local category = apTimingCategory(timing)
	local weaponContext = readEquippedWeaponContext(self.entity, timing, category, aid)
	local mantraEther = nil
	local mantraNoEtherSpend = false
	local breakerTimerSignal = false
	local weaponMismatch = weaponContext.status == "mismatch"
	local weaponConfirmed = weaponContext.status == "confirmed"

	local function suspicious(points, name)
		score = score + points
		suspiciousCount = suspiciousCount + 1
		signals[#signals + 1] = name
	end

	local function trusted(points, name)
		if points <= 0 then
			facts[#facts + 1] = name
			return
		end

		trust = trust + points
		trustSignals[#trustSignals + 1] = name
	end

	local function fact(name)
		facts[#facts + 1] = name
	end

	fact("known-timing")
	fact("category-" .. category)
	fact("weapon-" .. tostring(weaponContext.status or "unknown"))

	if not self._isFromPlayer then
		trusted(4, "npc-source")
	end

	if weaponMismatch then
		suspicious(4, "weapon-context-mismatch")
	elseif weaponConfirmed then
		trusted(3, "weapon-context-confirmed")
	end

	if timing.actions and timing.actions:count() > 0 then
		fact("actions")
	end

	if timing.hitbox and timing.hitbox.Magnitude > 0 then
		fact("timing-hitbox")
	end

	if timing.umoa then
		fact("module-timing")

		if weaponConfirmed or ownership.status == "confirmed" then
			trusted(2, "module-confirmed-context")
		end
	end

	if timing.tag then
		fact("tag-" .. tostring(timing.tag))
	end

	if self._isFromPlayer and category == "mantra" then
		mantraEther = self:apme(timing, aid, now)
		fact("mantra-ether-" .. tostring(mantraEther.status))

		if mantraEther.status == "spent" then
			protected = true
			trusted(8, "mantra-ether-spent")
		elseif mantraEther.status == "no-spend" then
			mantraNoEtherSpend = true
			suspicious(8, "mantra-no-ether-spend")
		elseif mantraEther.status == "claimed" then
			mantraNoEtherSpend = true
			suspicious(8, "mantra-ether-spend-claimed")
		elseif mantraEther.status == "mismatch" then
			mantraNoEtherSpend = true
			suspicious(8, "mantra-ether-spend-mismatch")
		elseif mantraEther.reason then
			fact("mantra-ether-" .. tostring(mantraEther.reason))
		end
	end

	if ownership.status == "missing" then
		suspicious(2, "ownership-missing")
	elseif ownership.status == "confirmed" then
		trusted(4, "ownership-confirmed")
	elseif ownership.status == "unknown" then
		fact("ownership-unknown")
	elseif ownership.reason == "unmapped" then
		fact("ownership-unmapped")
	else
		fact("ownership-not-applicable")
	end

	if timing.rpue then
		geometricPlausible = true
		geometricPlausibility = "rpue"
		realHitEvidence = "rpue"
		fact("rpue-context")
		trusted(3, "rpue-context")
	end

	if timing.duih then
		geometricPlausible = true
		geometricPlausibility = "delay-until-hitbox"
		if realHitEvidence == "none" then
			realHitEvidence = "delay-until-hitbox"
		end
		fact("delay-until-hitbox")

		if weaponConfirmed or ownership.status == "confirmed" or not self._isFromPlayer then
			trusted(2, "duih-confirmed-context")
		end
	end

	if timing.tag == "Critical" then
		fact("critical-unconfirmed")
	elseif timing.tag == "Mantra" then
		fact("mantra-unconfirmed")
	elseif timing.tag == "M1" then
		fact("M1")
	end

	local weightTarget = tonumber(track.WeightTarget) or 0
	local weightCurrent = tonumber(track.WeightCurrent) or 0
	local weight = weightTarget > 0 and weightTarget or weightCurrent
	local speed = tonumber(track.Speed) or 0
	local length = tonumber(track.Length) or 0
	local timePosition = tonumber(track.TimePosition) or 0
	local priority = track.Priority
	local priorityName = priority and priority.Name or tostring(priority)
	local lowWeightSignal = false
	local badPrioritySignal = false
	local abnormalSpeedSignal = false
	local extremeSpeedSignal = false
	local shortTrackSignal = false
	local blendMismatchSignal = false
	local missingLegitimacy = false
	local hasBurstPattern = false
	local playerMobAnimationSignal = false

	if weightTarget >= 1.0 and weightCurrent <= 0.01 then
		blendMismatchSignal = true
		suspicious(2, "high-target-zero-current")
	elseif weightTarget >= 0.5 and weightCurrent <= AP_SOFT_LOW_WEIGHT then
		blendMismatchSignal = true
		fact("target-weight-before-blend")
	end

	if weightTarget > 0 and weightTarget <= AP_LOW_WEIGHT then
		lowWeightSignal = true
		suspicious(1, "very-low-weight")
	elseif weightTarget > 0 and weightTarget <= AP_SOFT_LOW_WEIGHT then
		lowWeightSignal = true
		suspicious(1, "low-weight")
	end

	if priority == Enum.AnimationPriority.Core then
		badPrioritySignal = true
		suspicious(2, "core-priority")
	elseif priority == Enum.AnimationPriority.Idle then
		badPrioritySignal = true
		suspicious(1, "idle-priority")
	end

	if speed >= AP_EXTREME_SPEED then
		abnormalSpeedSignal = true
		extremeSpeedSignal = true
		suspicious(4, "extreme-speed")
	elseif speed >= AP_FAST_SPEED then
		abnormalSpeedSignal = true
		suspicious(2, "fast-speed")
	elseif speed > 0 and speed < 0.5 then
		abnormalSpeedSignal = true
		suspicious(1, "slow-speed")
	end

	if length > 0 and length < AP_SHORT_ACTIVE_DURATION then
		shortTrackSignal = true
		suspicious(2, "very-short-length")
	end

	if not track.IsPlaying then
		shortTrackSignal = true
		suspicious(2, "not-playing")
	end

	if self._isFromPlayer and self.manimations[track.Animation.AnimationId] ~= nil then
		playerMobAnimationSignal = true
		suspicious(5, "player-mob-animation")
	end

	local gap = nil
	if self.apLastKnownTime then
		gap = now - self.apLastKnownTime
		if gap < 0.05 then
			breakerTimerSignal = true
			suspicious(3, "tiny-gap")
		elseif gap < 0.12 then
			breakerTimerSignal = true
			suspicious(2, "short-gap")
		elseif gap < AP_BREAKER_GAP then
			breakerTimerSignal = true
			suspicious(gap <= AP_BREAKER_REPEAT_GAP and 2 or 1, "breaker-gap")
		end
	end

	local history = self.apHistory[aid]
	local recentSame = history and (#history + 1) or 1
	if recentSame >= 5 then
		suspicious(3, "same-id-spam")
	elseif recentSame >= 3 then
		suspicious(2, "same-id-repeat")
	end

	local recentGlobal = #self.apGlobalHistory + 1
	local seenIds = { [aid] = true }
	local seenCategories = { [category] = true }
	local recentUnique = 1
	local recentCategoryUnique = 1
	for _, entry in next, self.apRecentIds do
		if entry.aid and not seenIds[entry.aid] then
			seenIds[entry.aid] = true
			recentUnique = recentUnique + 1
		end

		if entry.category and not seenCategories[entry.category] then
			seenCategories[entry.category] = true
			recentCategoryUnique = recentCategoryUnique + 1
		end
	end

	if recentGlobal >= 8 then
		hasBurstPattern = true
		suspicious(3, "global-spam")
	elseif recentGlobal >= 5 then
		hasBurstPattern = true
		suspicious(2, "global-burst")
	elseif recentGlobal >= 3 then
		hasBurstPattern = true
		suspicious(2, "burst-pressure")
	end

	if recentGlobal >= 3 and recentUnique >= 3 then
		hasBurstPattern = true
		suspicious(2, "rotating-id-burst")
	elseif recentGlobal >= 3 and recentUnique >= 2 then
		hasBurstPattern = true
		suspicious(1, "rotating-id-pair")
	end

	if recentGlobal >= 3 and recentCategoryUnique >= 2 then
		hasBurstPattern = true
		suspicious(2, "rotating-category-burst")
	end

	if breakerTimerSignal and recentGlobal >= 2 and recentUnique >= 2 then
		hasBurstPattern = true
		suspicious(2, "breaker-window-rotation")
	end

	if timingWeaponCategory(category) and recentGlobal >= 3 and (recentUnique >= 2 or recentCategoryUnique >= 2) then
		hasBurstPattern = true
		suspicious(1, "weapon-rotation-pressure")
	end

	local activeSuspicious = tableCount(self.apActive)
	if activeSuspicious >= 4 then
		hasBurstPattern = true
		suspicious(2, "active-suspicious-limit")
	end

	local shortDurationCount = #self.apShortDurations
	if shortDurationCount >= 3 then
		hasBurstPattern = true
		shortTrackSignal = true
		suspicious(3, "stopped-track-pattern")
	elseif shortDurationCount >= 1 and recentGlobal >= 2 then
		hasBurstPattern = true
		shortTrackSignal = true
		suspicious(2, "recent-short-stop")
	end

	local hasWeakTrackPattern = lowWeightSignal
		or badPrioritySignal
		or abnormalSpeedSignal
		or shortTrackSignal
		or blendMismatchSignal
	local ownershipMissing = ownership.status == "missing"
	local ownershipConfirmed = ownership.status == "confirmed"
	local attackNeedsLegitimacy = self._isFromPlayer
		and (
			timing.tag == "Mantra"
			or timing.tag == "Critical"
			or timing.tag == "M1"
			or timing.tag == "Undefined"
			or timing.umoa
			or ownership.reason == "unmapped"
			or weaponMismatch
			or timingWeaponCategory(category)
		)

	if
		attackNeedsLegitimacy
		and not ownershipConfirmed
		and not weaponConfirmed
		and (ownershipMissing or weaponMismatch or hasWeakTrackPattern or hasBurstPattern or breakerTimerSignal)
	then
		missingLegitimacy = true

		if not ownershipMissing then
			suspicious(hasBurstPattern and 3 or 2, "missing-attack-legitimacy")
		end
	end

	if
		self._isFromPlayer
		and ownership.reason == "unmapped"
		and timing.tag == "Undefined"
		and (hasWeakTrackPattern or hasBurstPattern)
	then
		suspicious(2, "player-unmapped-undefined-timing")
	end

	if
		self._isFromPlayer
		and ownership.reason == "unmapped"
		and timing.tag == "Critical"
		and (hasWeakTrackPattern or hasBurstPattern)
	then
		suspicious(2, "player-unmapped-critical-timing")
	end

	if
		self._isFromPlayer
		and ownership.reason == "unmapped"
		and timing.tag == "M1"
		and (hasWeakTrackPattern or hasBurstPattern or breakerTimerSignal)
	then
		suspicious(2, "player-unmapped-m1-timing")
	end

	if
		self._isFromPlayer
		and timing.umoa
		and ownership.reason == "unmapped"
		and timing.tag ~= "M1"
		and (hasWeakTrackPattern or hasBurstPattern)
	then
		suspicious(1, "unmapped-module-timing")
	end

	if not protected then
		plausible, realHitEvidence = self:apbh(timing)

		if plausible then
			geometricPlausible = true
			geometricPlausibility = realHitEvidence
			fact(tostring(realHitEvidence))
			fact("geometry-" .. tostring(realHitEvidence))
		elseif realHitEvidence == "delay-until-hitbox" then
			geometricPlausible = true
			geometricPlausibility = "delay-until-hitbox"
			fact("delay-until-hitbox")
			fact("geometry-delay-until-hitbox")
		elseif self._isFromPlayer then
			suspicious(3, "no-real-hit-evidence")
			suspicious(2, "known-timing-without-hit")
		end
	end

	local trackLooksReal = not hasWeakTrackPattern
		and track.IsPlaying
		and (weight <= 0 or weight >= AP_SOFT_LOW_WEIGHT)
		and (speed <= 0 or (speed >= 0.5 and speed <= 2.25))

	if trackLooksReal then
		fact("realistic-track")
	else
		fact("track-fake-shape")
	end

	if geometricPlausible and trackLooksReal then
		fact("geometric-realistic-track")

		if timing.tag == "Critical" then
			fact("critical-plausible")
		elseif timing.tag == "Mantra" then
			fact("mantra-plausible")
		elseif timing.umoa then
			fact("module-plausible")
		end
	end

	if ownershipConfirmed and trackLooksReal then
		trusted(hasBurstPattern and 2 or 4, "owned-realistic-track")
	end

	local stoppedTrackPattern = shortDurationCount >= 3
	local currentStoppedTrack = not track.IsPlaying
	local strongOverrideContext = ownershipConfirmed or weaponConfirmed
	local projectContextRaw = timing.rpue
		or (timing.duih and (strongOverrideContext or not self._isFromPlayer))
		or (timing.umoa and strongOverrideContext)
	local projectContext = projectContextRaw and not hasBurstPattern
	local realLegitimacy = not mantraNoEtherSpend
		and (not self._isFromPlayer or protected or strongOverrideContext or projectContext)
	local currentBreakerPressure = breakerTimerSignal and not strongOverrideContext
	local historicalBreakerPressure = hasBurstPattern and not strongOverrideContext
	local breakerPressure = currentBreakerPressure or historicalBreakerPressure

	local credibleTrack = trackLooksReal
		and not playerMobAnimationSignal
		and not extremeSpeedSignal
		and not weaponMismatch
	local recoveryLegitimacy = self._isFromPlayer
		and credibleTrack
		and geometricPlausible
		and not currentStoppedTrack
		and realLegitimacy

	local strongLegitimacy = not mantraNoEtherSpend
		and (
			protected
			or not self._isFromPlayer
			or (
				credibleTrack
				and geometricPlausible
				and (
					strongOverrideContext
					or (projectContext and not breakerTimerSignal)
				)
			)
		)

	local likelyReal = not mantraNoEtherSpend
		and (
			strongLegitimacy
			or recoveryLegitimacy
			or (
				self._isFromPlayer
				and credibleTrack
				and geometricPlausible
				and not currentStoppedTrack
				and realLegitimacy
			)
		)

	local threshold = 7
	local enoughSignals = suspiciousCount >= 3
	local stackedBreakerEvidence = self._isFromPlayer
		and (
			(breakerTimerSignal and (recentUnique >= 2 or recentCategoryUnique >= 2 or recentGlobal >= 3))
			or (hasBurstPattern and (recentUnique >= 2 or recentCategoryUnique >= 2))
			or (shortDurationCount >= 1 and recentGlobal >= 2)
			or activeSuspicious >= 4
		)
	local breakerOverride = stackedBreakerEvidence
		and not strongLegitimacy
		and not strongOverrideContext
		and not projectContext
		and (missingLegitimacy or enoughSignals or score >= threshold)
	local downgradedFromReal = breakerOverride and likelyReal
	local effectiveRecoveryLegitimacy = recoveryLegitimacy and not breakerOverride
	local effectiveLikelyReal = likelyReal and not breakerOverride
	local hardFake = self._isFromPlayer and not effectiveLikelyReal and (
		mantraNoEtherSpend
		or playerMobAnimationSignal
		or extremeSpeedSignal
		or (currentStoppedTrack and missingLegitimacy and (hasWeakTrackPattern or breakerPressure))
		or (weaponMismatch and (hasWeakTrackPattern or breakerPressure or not geometricPlausible))
	)
	local fakeExtreme = hardFake
		or stoppedTrackPattern
		or (
			suspiciousCount >= AP_EXTREME_SIGNAL_COUNT
			and (missingLegitimacy or hasWeakTrackPattern or not geometricPlausible)
		)
	local stackedBalancedFake = self._isFromPlayer
		and not effectiveLikelyReal
		and (
			breakerOverride
			or (
				missingLegitimacy
				and enoughSignals
				and score >= threshold
				and (hasWeakTrackPattern or breakerPressure or not geometricPlausible or stoppedTrackPattern)
			)
		)
	local likelyFake = hardFake or stackedBalancedFake

	local tier = "Uncertain"
	if not self._isFromPlayer then
		tier = "Real"
	elseif strongLegitimacy then
		tier = "Real"
	elseif effectiveRecoveryLegitimacy then
		tier = "Likely Real"
	elseif hardFake then
		tier = "Fake"
	elseif likelyFake then
		tier = "Likely Fake"
	elseif effectiveLikelyReal then
		tier = "Likely Real"
	elseif score > 0 or missingLegitimacy or hasBurstPattern then
		tier = "Suspicious"
	end

	local wouldBlock = hardFake or stackedBalancedFake
	local block = wouldBlock
	local decision = "AllowUncertain"
	if block then
		decision = "BlockFakeOccurrence"
	elseif strongLegitimacy or effectiveRecoveryLegitimacy or effectiveLikelyReal then
		decision = "AllowReal"
	end
	local defer = false

	local reason = "allow-" .. string.lower(string.gsub(tier, "%s+", "-"))
	if wouldBlock then
		reason = breakerOverride and "block-stacked-breaker-no-legitimacy" or "block-fake-occurrence"
	elseif protected then
		reason = "protected-real-timing"
	elseif strongLegitimacy then
		reason = "attack-legitimacy"
	elseif effectiveRecoveryLegitimacy then
		reason = "real-attack-recovery"
	elseif effectiveLikelyReal then
		reason = "legitimate-context"
	elseif not enoughSignals then
		reason = "weak-evidence-allowed"
	elseif score < threshold then
		reason = "below-balanced-threshold"
	else
		reason = "balanced-uncertain-allowed"
	end
	local whyReal = protected and "protected-real-timing"
		or (strongLegitimacy and "strong-legitimacy")
		or (effectiveRecoveryLegitimacy and "recovery-legitimacy")
		or (effectiveLikelyReal and "legitimate-context")
		or "none"
	local whyBlocked = wouldBlock
		and (breakerOverride and "stacked-breaker-without-strong-legitimacy" or reason)
		or "none"
	local whyAllowed = wouldBlock and "none" or reason
	local schedulingProceeded = not block

	return {
		block = block,
		wouldBlock = wouldBlock,
		defer = defer,
		decision = decision,
		tier = tier,
		reason = reason,
		score = score,
		trust = trust,
		threshold = threshold,
		signals = signals,
		trustSignals = trustSignals,
		facts = facts,
		ownership = ownership,
		raw = {
			priority = priorityName,
			weight = weight,
			weightCurrent = weightCurrent,
			weightTarget = weightTarget,
			speed = speed,
			length = length,
			timePosition = timePosition,
			gap = gap,
			category = category,
			weaponContext = weaponContext,
			recentSame = recentSame,
			recentGlobal = recentGlobal,
			recentUnique = recentUnique,
			recentCategoryUnique = recentCategoryUnique,
			breakerTimer = breakerTimerSignal,
			activeSuspicious = activeSuspicious,
			shortDurations = shortDurationCount,
			realHitEvidence = realHitEvidence,
			geometricPlausibility = geometricPlausibility,
			legitimacy = breakerOverride and "downgraded"
				or (strongLegitimacy and "strong"
					or (effectiveLikelyReal and "partial" or (trust > 0 and "partial" or "missing"))),
			realLegitimacy = realLegitimacy,
			fakeExtreme = fakeExtreme,
			missingLegitimacy = missingLegitimacy,
			hasBurstPattern = hasBurstPattern,
			breakerOverride = breakerOverride,
			downgradedFromReal = downgradedFromReal,
			mantraEtherStatus = mantraEther and mantraEther.status or "not-applicable",
			mantraEtherReason = mantraEther and mantraEther.reason or "not-applicable",
			mantraEtherSerial = mantraEther and mantraEther.serial or nil,
			mantraEtherContext = mantraEther and mantraEther.context or "not-applicable",
			mantraEtherContextReason = mantraEther and mantraEther.contextReason or "not-applicable",
			mantraEtherContextKey = mantraEther and mantraEther.contextKey or nil,
			mantraEtherClaimedKey = mantraEther and mantraEther.claimedKey or nil,
			mantraEtherClaimedAid = mantraEther and mantraEther.claimedAid or nil,
			mantraEtherStoredAction = mantraEther and mantraEther.storedAction or nil,
			mantraEtherStoredTool = mantraEther and mantraEther.storedTool or nil,
			plausible = plausible,
			schedulingProceeded = schedulingProceeded,
			whyReal = whyReal,
			whyBlocked = whyBlocked,
			whyAllowed = whyAllowed,
		},
	}
end)

AnimatorDefender.valid = (function(self, options)
	if not Defender.valid(self, options) then
		return false
	end

	local timing = options.timing
	local action = options.action

	local checkTrack = options.track or self.track
	if not checkTrack then
		return false
	end

	if not self.entity then
		return false
	end

	local target = self:target(self.entity)
	if not target then
		return false
	end

	local root = self.entity:FindFirstChild("HumanoidRootPart")
	if not root then
		return false
	end

	local character = players.LocalPlayer.Character
	if not character then
		return false
	end

    local targetInstance = self.entity:FindFirstChild("Target")
	if not self._isFromPlayer
		and Configuration.expectToggleValue("CheckTargetingValue")
		and targetInstance
		and targetInstance:IsA("ObjectValue")
		and targetInstance.Value ~= character
	then
		return false
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return false
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return false
	end

	if
		not timing.imb
		and root:FindFirstChild("MegalodauntBroken")
		and not players:GetPlayerFromCharacter(self.entity)
	then
		return false
	end

	if self:stopped(checkTrack, timing, nil, options.occurrence) then
		return false
	end

	local hoptions = HitboxOptions.new(root, timing)
	hoptions.spredict = not timing.duih and not timing.dp
	hoptions.ptime = self:fsecs(timing)
	hoptions.action = action
	hoptions.entity = self.entity
	hoptions:ucache()

	local info = RepeatInfo.new(timing, Latency.rdelay())
	info.track = checkTrack
	info.occurrence = options.occurrence

	local hc = self:hc(hoptions, timing.duih and info or nil)
	if hc then
		return true
	end

	local pc = self:fpc(timing, hoptions)
	if pc then
		return true
	end

	return false
end)

AnimatorDefender.update = (function(self)
	refreshADCache()
	self:syncIngressGeneration()
	self:sapb()
	if
		self.apAdvancedEnabled
		and refreshAPWeaponSounds
		and os.clock() >= (self.apNextWeaponSoundRefreshAt or 0)
	then
		refreshAPWeaponSounds(self)
	end
	if pruneIngressQuarantine and (self.apIngressQuarantineCount or 0) > 0 then
		pruneIngressQuarantine(self, os.clock(), 8)
	end

	local hasAPMaintenance = adcAdvancedAntiAPBreak
		and (
			next(self.apActive) ~= nil
			or next(self.apCriticalPending) ~= nil
			or next(self.apCriticalConfirmed) ~= nil
			or next(self.apOccurrencePending) ~= nil
			or next(self.apOccurrenceConfirmed) ~= nil
		)
	if hasAPMaintenance then
		self:capb(os.clock())
	end
end)

local function protectedIngressTiming(self, track)
	local animation = track.Animation
	if not animation or animation:GetAttribute(AUTO_PARRY_BREAKER_ATTRIBUTE) then
		return nil
	end

	local aid = tostring(animation.AnimationId)
	local timing = SaveManager.as:resolve(aid, animation.Name, self.entity, track)
	if not timing or track.Priority == Enum.AnimationPriority.Core or not track.IsPlaying then
		return nil, aid
	end

	local speed = math.abs(tonumber(track.Speed) or 0)
	local targetWeight = tonumber(track.WeightTarget) or 0
	local timePosition = tonumber(track.TimePosition) or 0
	if speed < 0.05 or speed > 4 or targetWeight <= AP_SOFT_LOW_WEIGHT or targetWeight > 2 or timePosition > 0.4 then
		return nil, aid
	end

	local distance = self:distance(self.entity)
	if not distance then
		return nil, aid
	end
	local minimumDistance = PP_SCRAMBLE_NUM(timing.imdd)
	if minimumDistance <= 0.01 then
		minimumDistance = 0
	end
	if distance < minimumDistance or distance > PP_SCRAMBLE_NUM(timing.imxd) then
		return nil, aid
	end

	return timing, aid
end

local function quarantineCategoryCompatible(category, evidence)
	local families = evidence.families
	if not families or families[category] == true then
		return true
	end

	local weaponFamilies = {
		["weapon-m1"] = true,
		["weapon-critical"] = true,
		["weapon-special"] = true,
	}
	return evidence.allowWeaponFamilyBridge == true
		and weaponFamilies[category] == true
		and weaponFamilies[evidence.exactFamily] == true
end

local function quarantineKnownIngress(self, track, timing, aid, startedAt)
	local category = apTimingCategory(timing)
	local lane = ingressQuarantineLane(category)
	local byTrack = self.apIngressQuarantineByTrack[lane]
	local slot = byTrack[track]
	local coalesced = slot ~= nil
	if not slot then
		local cursor = self.apIngressQuarantineCursors[lane]
		slot = self.apIngressQuarantine[ingressQuarantineIndex(lane, cursor)]
		clearIngressQuarantineSlot(self, slot)
		self.apIngressQuarantineCursors[lane] = cursor % AP_INGRESS_QUARANTINE_CATEGORY_LIMIT + 1
		self.apIngressQuarantineCount = math.min(
			AP_INGRESS_QUARANTINE_LIMIT,
			(self.apIngressQuarantineCount or 0) + 1
		)
		byTrack[track] = slot
	end
	slot.track = track
	slot.timing = timing
	slot.aid = aid
	slot.category = category
	slot.lane = lane
	slot.startedAt = startedAt
	AnimationIngressGuard.quarantineCandidate(coalesced)
	return not coalesced
end

pruneIngressQuarantine = function(self, now, budget)
	local cursor = self.apIngressQuarantinePruneCursor or 1
	for _ = 1, budget do
		local slot = self.apIngressQuarantine[cursor]
		if slot.track and now - slot.startedAt > AP_INGRESS_QUARANTINE_MAX_AGE then
			clearIngressQuarantineSlot(self, slot)
		end
		cursor = cursor % AP_INGRESS_QUARANTINE_LIMIT + 1
	end
	self.apIngressQuarantinePruneCursor = cursor
end

promoteQuarantinedIngress = function(self, evidence)
	local evidenceAt = tonumber(evidence.at) or os.clock()
	local latencyMin = tonumber(evidence.latencyMin) or -0.02
	local latencyMax = math.min(
		tonumber(evidence.latencyMax) or AP_INGRESS_QUARANTINE_MAX_AGE,
		AP_INGRESS_QUARANTINE_MAX_AGE
	)
	local best = nil
	local bestScore = -math.huge

	for index = 1, AP_INGRESS_QUARANTINE_LIMIT do
		local slot = self.apIngressQuarantine[index]
		local track = slot.track
		local startedAt = slot.startedAt
		if not track or not startedAt then
			continue
		end

		local age = evidenceAt - startedAt
		if age > AP_INGRESS_QUARANTINE_MAX_AGE then
			clearIngressQuarantineSlot(self, slot)
			continue
		end

		local actionCompatible = not evidence.actionKey
			or not evidence.requireTimingActionMatch
			or AttackAuthenticator.timingActionCompatible({
				timingActionNames = { slot.timing.name, slot.timing.smod },
			}, evidence.actionKey, evidence.actionAliases)

		local current = self.apOccurrenceStartedAt[track]
		if
			age < latencyMin
			or age > latencyMax
			or not quarantineCategoryCompatible(slot.category, evidence)
			or not actionCompatible
			or (current and current.startedAt >= startedAt - 1e-4)
		then
			continue
		end

		local speed = math.abs(tonumber(track.Speed) or 0)
		local expectedDuration = speed > SPEED_EPSILON and (tonumber(track.Length) or 0) / speed or 0
		local evidenceDuration = tonumber(evidence.duration)
		local durationScore = 0
		if evidenceDuration and expectedDuration > 0 then
			local durationError = math.abs(expectedDuration - evidenceDuration)
				/ math.max(expectedDuration, evidenceDuration, 0.01)
			if durationError > 0.75 then
				continue
			end
			durationScore = (1 - durationError) * 8
		end

		local score = durationScore
		local weaponContext = readEquippedWeaponContext(
			self.entity,
			slot.timing,
			slot.category,
			slot.aid
		)
		if evidence.weaponKey and weaponContext.status == "mismatch" then
			continue
		elseif weaponContext.status == "confirmed" then
			score = score + 40
		end
		if evidence.exactFamily == slot.category then
			score = score + 100
		elseif evidence.families and evidence.families[slot.category] then
			score = score + 50
		end
		if (tonumber(track.WeightCurrent) or 0) > AP_SOFT_LOW_WEIGHT then
			score = score + 20
		end
		if (tonumber(track.TimePosition) or 0) > 1e-4 then
			score = score + 10
		end
		if
			age >= (tonumber(evidence.centralLatencyMin) or latencyMin)
			and age <= (tonumber(evidence.centralLatencyMax) or latencyMax)
		then
			score = score + 10
		end
		score = score + startedAt * 1e-6

		if score > bestScore then
			best = slot
			bestScore = score
		end
	end

	if not best then
		return false
	end

	local track = best.track
	local timing = best.timing
	local startedAt = best.startedAt
	clearIngressQuarantineSlot(self, best)

	for index = 1, AP_INGRESS_QUARANTINE_LIMIT do
		local slot = self.apIngressQuarantine[index]
		if slot.track == track and slot.startedAt <= startedAt then
			clearIngressQuarantineSlot(self, slot)
		end
	end

	local occurrence = (self.apTrackOccurrences[track] or 0) + 1
	self.apTrackOccurrences[track] = occurrence
	self.apOccurrenceStartedAt[track] = {
		occurrence = occurrence,
		startedAt = startedAt,
	}
	self.apRecoveredOccurrences[track] = occurrence
	AnimationIngressGuard.recoveredEvidence()
	self:process(track, occurrence, timing, true)
	return self.apAuthenticator:getCandidate(track, occurrence)
end

AnimatorDefender.rlimit = (function(self, track)
	refreshADCache()
	self:syncIngressGeneration()
	if not self._isFromPlayer or not adcCrasherProtection then
		return true, nil, false
	end

	local owner = self._playerOwner or players:GetPlayerFromCharacter(self.entity)
	if not owner then
		return true, nil, false
	end
	self._playerOwner = owner

	local admitted, reason, underPressure = AnimationIngressGuard.admitSuspicious(owner)
	if admitted and not underPressure then
		return true, nil, false
	end

	local priority = track.Priority
	local actionPriority = priority == Enum.AnimationPriority.Action
		or priority == Enum.AnimationPriority.Action2
		or priority == Enum.AnimationPriority.Action3
		or priority == Enum.AnimationPriority.Action4
	if underPressure and not actionPriority then
		AnimationIngressGuard.reject("universal-noncombat-priority")
		return false, nil, false
	end

	local timing, aid = protectedIngressTiming(self, track)
	if timing and aid then
		local candidate, candidateReason = AnimationIngressGuard.admitCandidate(owner, aid)
		if candidate then
			return true, timing, true
		end
		reason = candidateReason or reason

		if adcAdvancedAntiAPBreak and self.apAdvancedEnabled then
			local startedAt = os.clock()
			local isNewTrack = quarantineKnownIngress(self, track, timing, aid, startedAt)
			if isNewTrack and self.apAuthenticator then
				local retained = self.apAuthenticator:retainedEvidenceForTiming({
					category = apTimingCategory(timing),
					startedAt = startedAt,
					timingActionNames = { timing.name, timing.smod },
				}, startedAt)
				if retained then
					self:recordAttackEvidence(retained)
				end
			end
			reason = "advanced-candidate-quarantine"
		end
	else
		reason = "untrusted-overflow"
	end

	AnimationIngressGuard.reject(reason)
	local now = os.clock()
	if now - (self._ingressLastWarn or -1e9) >= 2 then
		self._ingressLastWarn = now
		Logger.warn("Crasher Protection: shedding excess animation work from %s at ingress.", self.entity.Name)
	end
	return false, nil, false
end)

AnimatorDefender.apcr = (function(self, instance)
	if not adcAdvancedAntiAPBreak or not self._isFromPlayer then
		return
	end

	local root = self.entity and self.entity:FindFirstChild("HumanoidRootPart")
	if not root or instance.Parent ~= root then
		return
	end

	local now = os.clock()
	local advanced = adcAdvancedAntiAPBreak and self.apAdvancedEnabled
	local paired = false
	if not advanced then
		if instance:IsA("AudioPlayer") then
			self.apRootAudioAt = now
			return
		end
		if not instance:IsA("Attachment") then
			return
		end
		paired = self.apRootAudioAt ~= nil
			and now - self.apRootAudioAt <= AP_CRITICAL_REPLICATED_PAIR_GAP
	else
		if instance:IsA("AudioPlayer") then
			self.apRootAudioAt = now
			paired = self.apRootAttachmentAt ~= nil
				and now - self.apRootAttachmentAt <= AP_CRITICAL_REPLICATED_PAIR_GAP
		elseif instance:IsA("Attachment") then
			self.apRootAttachmentAt = now
			paired = self.apRootAudioAt ~= nil
				and now - self.apRootAudioAt <= AP_CRITICAL_REPLICATED_PAIR_GAP
		else
			return
		end
	end

	if not paired then
		return
	end

	if advanced then
		local storedAction = compactText(self.entity:GetAttribute("StoredAction"))
		if storedAction ~= "criticalattack" then
			if storedAction == "" then
				return
			end

			if
				self.apMantraRootClaimedAction == storedAction
				and self.apMantraRootClaimedUntil
				and now <= self.apMantraRootClaimedUntil
			then
				return
			end

			local candidate = self:recordAttackEvidence({
				kind = "replicated-mantra-root-action-pair",
				at = now,
				authoritative = true,
				retainForFutureCandidate = true,
				exactFamily = "mantra",
				families = { mantra = true },
				actionKey = storedAction,
				actionAliases = replicatedMantraActionAliases(self.entity),
				requireTimingActionMatch = true,
				latencyMin = -AP_MANTRA_ETHER_SPEND_WINDOW,
				latencyMax = AP_MANTRA_ROOT_EVIDENCE_LATENCY_MAX,
				centralLatencyMin = -0.02,
				centralLatencyMax = 0.12,
				uncertainty = AP_CRITICAL_REPLICATED_PAIR_GAP,
			})
			if candidate then
				self.apMantraRootClaimedAction = storedAction
				self.apMantraRootClaimedUntil = candidate.startedAt
					+ math.max(candidate.behaviorWindow or 0, candidate.legalInterval or 0)
			end
			return
		end

		local authenticated = self:recordAttackEvidence({
			kind = "replicated-critical-root-pair",
			at = now,
			authoritative = true,
			weaponKey = currentWeaponEvidenceKey(self),
			exactFamily = "weapon-critical",
			families = { ["weapon-critical"] = true },
			allowWeaponFamilyBridge = true,
			latencyMin = AP_CRITICAL_EVIDENCE_LATENCY_MIN,
			latencyMax = AP_CRITICAL_EVIDENCE_LATENCY_MAX,
			centralLatencyMin = 0,
			centralLatencyMax = AP_CRITICAL_REPLICATED_WINDOW,
			uncertainty = AP_CRITICAL_REPLICATED_PAIR_GAP,
		})
		if authenticated then
			return
		end

		if self.apAuthenticator and self.apAuthenticator.floodActive then
			return
		end
	end

	for track, data in next, self.apCriticalPending do
		if
			self.apTrackOccurrences[track] ~= data.occurrence
			or now - data.startedAt > AP_CRITICAL_REPLICATED_WINDOW
		then
			continue
		end

		self.apCriticalPending[track] = nil
		self.apCriticalConfirmed[track] = data
		self.apCriticalConfirmedSources[track] = "replicated-root-event"

		TaskSpawner.deferOwned(self.apMaid, "AnimatorDefender_CriticalReplication", function()
			if self.apTrackOccurrences[track] == data.occurrence and track.IsPlaying then
				self:process(track, data.occurrence)
			end
		end)
		return
	end
end)

function AnimatorDefender:pvalidate(track, timing, report)
	if not adcValidateIncomingAnimations then
		return true
	end

	if adcAdvancedAntiAPBreak and timing then
		if report and report.block then
			return false
		end

		return true
	end

	if track.Priority == Enum.AnimationPriority.Core then
		return false
	end

	if self._isFromPlayer and track.WeightTarget <= 0.05 then
		return false
	end

	if self._isFromPlayer and self.manimations[track.Animation.AnimationId] ~= nil then
		return false
	end

	if track.Speed >= 1000 then
		return false
	end

	return true
end

local function weaponSpeedReady(speedWait, speed)
	if speed == nil then return false end
	if speedWait.mode == "changed" then
		return speed ~= speedWait.initial
	end
	if speedWait.mode == "minimum" then
		return speed >= speedWait.minimum
	end
	return speedWait.mode == "positive" and speed > 0
end

local function scheduleWeaponSpeedWait(self, timing, track, occurrence, startedAt)
	local speedWait = timing.katalystWeaponWait
	if not speedWait then return false end

	TaskSpawner.spawnOwned(self.tmaid, "AnimatorDefender_WeaponSpeed", function()
		local deadline = startedAt + AP_ACTIVE_TIMEOUT
		repeat
			task.wait()
			if
				self.track ~= track
				or not self:isOccurrenceCurrent(track, occurrence)
				or not track.IsPlaying
			then
				return
			end

			local speed = tonumber(track.Speed)
			if weaponSpeedReady(speedWait, speed) then
				if SaveManager.finishWeaponTiming(timing, speed) then
					self:actions(timing)
				end
				return
			end
		until os.clock() >= deadline
	end)
	return true
end

local function runEvengardeSwing(self, timing)
	if not timing.katalystEvengardeSwing then return false end

	local now = os.clock()
	if self.apEvengardeSwingGuard and now - self.apEvengardeSwingGuard < 4 then
		return true
	end
	self.apEvengardeSwingGuard = now

	TaskSpawner.spawnOwned(self.weaponMaid, "AnimatorDefender_EvengardeSwing", function()
		task.wait(0.4)
		local startedAt = os.clock()
		while adcEnableAutoDefense and self.entity.Parent and os.clock() - startedAt < 3 do
			local action = Action.new()
			action._when = 0
			action._type = "Parry"
			action.hitbox = Vector3.new(55, 55, 55)
			action.name = "Evengarde Sword Swing"
			self:action(timing, action)
			task.wait(0.01)
		end
	end)
	return true
end

AnimatorDefender.process = (function(self, track, occurrence, ingressTiming, protectedIngress)
	refreshADCache()
	self:syncIngressGeneration()
	self:sapb()

	occurrence = occurrence or self.apTrackOccurrences[track]
	local preauthenticated = adcAdvancedAntiAPBreak
		and self.apAdvancedEnabled
		and self.apAuthenticator
		and self.apAuthenticator:isAuthenticated(track, occurrence)
	if not self:isOccurrenceCurrent(track, occurrence) and not preauthenticated then
		return
	end

	local startedData = self.apOccurrenceStartedAt[track]
	local occurrenceStartedAt = startedData
			and startedData.occurrence == occurrence
			and startedData.startedAt
		or os.clock()

	if self._playerOwner == players.LocalPlayer
		or (players.LocalPlayer.Character and self.entity == players.LocalPlayer.Character)
	then
      return
    end

	local criticalConfirmation = self.apCriticalConfirmed[track]
	if criticalConfirmation and criticalConfirmation.occurrence ~= occurrence then
		criticalConfirmation = nil
	end

	local occurrenceConfirmation = self.apOccurrenceConfirmed[track]
	if occurrenceConfirmation and occurrenceConfirmation.occurrence ~= occurrence then
		occurrenceConfirmation = nil
	end

	local prevalidated = false
	if not adcAdvancedAntiAPBreak then
		if not self:pvalidate(track) then
			return
		end

		prevalidated = true
	end

	local aid = tostring(track.Animation.AnimationId)

    local timing = ingressTiming or SaveManager.as:resolve(aid, track.Animation.Name, self.entity, track)
	if timing then
		local distance = self:distance(self.entity)
		local minimumDistance = PP_SCRAMBLE_NUM(timing.imdd)
		if minimumDistance <= 0.01 then minimumDistance = 0 end
		if not distance or distance < minimumDistance or distance > PP_SCRAMBLE_NUM(timing.imxd) then
			timing = nil
		end
	end

	if not timing then
		return
	end

	local apReport = nil
	local authCandidate = nil
	local authConfirmed = false
	if
		adcAdvancedAntiAPBreak
		and self.apAdvancedEnabled
		and self._isFromPlayer
		and self.apAuthenticator
	then
		AnimationIngressGuard.advancedEntered()
		apReport = occurrenceConfirmation and occurrenceConfirmation.report or self:aapb(track, timing, aid)
		local context = occurrenceAuthenticationContext(self, track, timing, aid, apReport, occurrenceStartedAt)
		context.occurrence = occurrence
		local isNew, retriedCandidate
		authCandidate, isNew, retriedCandidate = self.apAuthenticator:observeCandidate(context)

		if retriedCandidate and retriedCandidate ~= authCandidate then
			TaskSpawner.deferOwned(self.apMaid, "AnimatorDefender_RetriedCandidate", function()
				if
					self.apAuthenticator:isAuthenticated(
						retriedCandidate.track,
						retriedCandidate.occurrence
					)
				then
					self:process(retriedCandidate.track, retriedCandidate.occurrence)
				end
			end)
		end

		if isNew and not occurrenceConfirmation then
			self:rapb(track, timing, aid, apReport, occurrenceStartedAt, occurrence)
			authCandidate.historyRecorded = true
			self:queueMantraEvidence(authCandidate, apReport)
		end

		if authCandidate.status == "authenticated" then
			authConfirmed = self.apAuthenticator:isAuthenticated(track, occurrence)
		elseif authCandidate.status == "released" then
		elseif authCandidate.status == "pending" then
			if not authCandidate.releaseScheduled then
				authCandidate.releaseScheduled = true
				TaskSpawner.delayOwned(self.apMaid, "AnimatorDefender_ProvisionalRelease", math.max(0, authCandidate.provisionalUntil - os.clock()), function()
					if
						self.apTrackOccurrences[track] ~= occurrence
						or self.apAuthenticator:getCandidate(track, occurrence) ~= authCandidate
					then
						return
					end

					local released = self.apAuthenticator:releaseCandidate(authCandidate, os.clock())
					if released and track.IsPlaying then
						self:process(track, occurrence)
					end
				end)
			end
			return
		else
			return
		end
	end

	local criticalConfirmed = criticalConfirmation ~= nil
	if adcAdvancedAntiAPBreak and timing.tag == "Critical" and not criticalConfirmed and not authConfirmed then
		local now = os.clock()
		self:capb(now)

		local floodPressure = protectedIngress == true
			or (
				#self.apGlobalHistory >= 3
				and self.apLastKnownTime ~= nil
				and now - self.apLastKnownTime <= AP_BREAKER_GAP
			)

		if floodPressure then
			if not self.apCriticalPending[track] then
				local pending = {
					startedAt = now,
					occurrence = occurrence,
				}
				self.apCriticalPending[track] = pending
				TaskSpawner.delayOwned(self.apMaid, "AnimatorDefender_CriticalConfirm", AP_CRITICAL_CONFIRM_DELAY, function()
					if self.apCriticalPending[track] ~= pending then
						return
					end

					self.apCriticalPending[track] = nil
					if
						self.apTrackOccurrences[track] ~= occurrence
						or not track.IsPlaying
						or track.WeightTarget <= AP_SOFT_LOW_WEIGHT
						or track.WeightCurrent <= AP_SOFT_LOW_WEIGHT
					then
						return
					end

					self.apCriticalConfirmed[track] = pending
					self.apCriticalConfirmedSources[track] = "persistence"
					self:process(track, occurrence)
				end)
			end

			return
		end
	end

	if not adcEnableAutoDefense then
		return
	end
	AnimationIngressGuard.autoDefenderReached()

	if adcAdvancedAntiAPBreak then
		apReport = apReport or occurrenceConfirmation and occurrenceConfirmation.report or self:aapb(track, timing, aid)

		if authConfirmed then
			local evidence = authCandidate.transaction and authCandidate.transaction.evidence
			local confirmationSignal = evidence and evidence.kind or "replicated-combat-evidence"
			apReport.block = false
			apReport.wouldBlock = false
			apReport.decision = "AllowAuthenticatedEvidence"
			apReport.tier = "Real"
			apReport.reason = confirmationSignal
			apReport.trust = (apReport.trust or 0) + 8
			table.insert(apReport.trustSignals, confirmationSignal)
			table.insert(apReport.facts, confirmationSignal)
		end

		if criticalConfirmed then
			local confirmationSource = self.apCriticalConfirmedSources[track] or "persistence"
			local confirmationSignal = confirmationSource == "replicated-root-event"
				and "critical-replicated-root-event"
				or "critical-survived-flood-window"
			apReport.block = false
			apReport.wouldBlock = false
			apReport.decision = "AllowConfirmedCritical"
			apReport.tier = "Real"
			apReport.reason = "critical-" .. confirmationSource
			apReport.trust = (apReport.trust or 0) + 6
			table.insert(apReport.trustSignals, confirmationSignal)
			table.insert(apReport.facts, confirmationSignal)
		end

		if occurrenceConfirmation then
			local confirmationSignal = "replicated-blend-confirmed"
			apReport.block = false
			apReport.wouldBlock = false
			apReport.decision = "AllowAuthenticatedOccurrence"
			apReport.tier = "Real"
			apReport.reason = "replicated-blend-confirmation"
			apReport.trust = (apReport.trust or 0) + 6
			table.insert(apReport.trustSignals, confirmationSignal)
			table.insert(apReport.facts, confirmationSignal)
		end

		local raw = apReport.raw or {}
		local breakerPressure = self._isFromPlayer
			and (raw.hasBurstPattern or raw.breakerTimer or (raw.recentGlobal or 0) >= 3)
		local nonStartingReplay = not criticalConfirmed
			and not authConfirmed
			and not occurrenceConfirmation
			and breakerPressure
			and (tonumber(track.WeightTarget) or 0) <= AP_SOFT_LOW_WEIGHT
			and math.abs(tonumber(track.Speed) or 0) <= AP_MANTRA_ETHER_EPSILON

		if nonStartingReplay then
			local signal = "non-starting-track-replay"
			apReport.block = true
			apReport.wouldBlock = true
			apReport.decision = "BlockNonStartingReplay"
			apReport.tier = "Fake"
			apReport.reason = signal
			apReport.score = math.max(apReport.score or 0, apReport.threshold or 0)
			table.insert(apReport.signals, signal)
			table.insert(apReport.facts, signal)
			raw.nonStartingReplay = true
		end

		if not occurrenceConfirmation and not (authCandidate and authCandidate.historyRecorded) then
			self:rapb(track, timing, aid, apReport, os.clock(), occurrence)
		end

		if apReport.block then
			return
		end

		local needsBlendConfirmation = not criticalConfirmed
			and not authConfirmed
			and not occurrenceConfirmation
			and breakerPressure
			and (tonumber(track.WeightTarget) or 0) > AP_SOFT_LOW_WEIGHT
			and (tonumber(track.WeightCurrent) or 0) <= AP_SOFT_LOW_WEIGHT

		if needsBlendConfirmation then
			local pending = {
				startedAt = os.clock(),
				occurrence = occurrence,
				report = apReport,
			}
			self.apOccurrencePending[track] = pending

			TaskSpawner.delayOwned(self.apMaid, "AnimatorDefender_BlendConfirm", AP_OCCURRENCE_BLEND_CONFIRM_DELAY, function()
				if self.apOccurrencePending[track] ~= pending then
					return
				end

				self.apOccurrencePending[track] = nil
				if
					self.apTrackOccurrences[track] ~= occurrence
					or not track.IsPlaying
					or track.WeightTarget <= AP_SOFT_LOW_WEIGHT
					or track.WeightCurrent <= AP_SOFT_LOW_WEIGHT
				then
					return
				end

				self.apOccurrenceConfirmed[track] = pending
				self:process(track, occurrence)
			end)

			return
		end
	end

	if not prevalidated and not self:pvalidate(track, timing, apReport) then
		return
	end

	local humanoidRootPart = self.entity:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	local effectReplicator = replicatedStorage:FindFirstChild("EffectReplicator")
	if not effectReplicator then
		return
	end

	local effectReplicatorModule = require(effectReplicator)
	if not effectReplicatorModule then
		return
	end

	if timing.tag == "Critical" then
		timing.nbfb = true
		timing.ha = true
	end

	if authConfirmed then
		local claimed = self.apAuthenticator:claimSchedule(track, occurrence, os.clock())
		if not claimed then
			return
		end
	end
	if not self:claimOccurrenceSchedule(track, occurrence) then
		return
	end

    self:cleanForOccurrence(track, apReport)

	self.timing = timing
	self.track = track
	self.offset = Latency.rdelay()
	self.occurrenceStartedAt = (authCandidate and authCandidate.startedAt)
		or (criticalConfirmation and criticalConfirmation.startedAt)
		or (occurrenceConfirmation and occurrenceConfirmation.startedAt)
		or occurrenceStartedAt
	self.occurrenceToken = occurrence

	if runEvengardeSwing(self, timing) then
		return
	end

	if timing.katalystWeaponKind == "basic"
		and timing.smod == "WeaponTest"
		and not timing.katalystTitusFist
	then
		local descendantAdded = Signal.new(self.entity.DescendantAdded)
		self.tmaid:add(descendantAdded:connect("WeaponTiming_DetectFakeSwing", function(child)
			if child.Name ~= "REP_SOUND_5115545256" and child.Name ~= "REP_SOUND_4954198253" then
				return
			end

			local current = self.tasks[#self.tasks]
			if current then current:cancel() end
		end))
	end

	if scheduleWeaponSpeedWait(self, timing, track, occurrence, self.occurrenceStartedAt) then
		return
	end

	if timing.umoa then
		return self:module(timing)
	end

	if not timing.rpue then
		return self:actions(timing)
	end

	local info = RepeatInfo.new(timing, Latency.rdelay())
	info.track = track
	info.occurrence = occurrence
	self:srpue(self.entity, timing, info)
end)

function AnimatorDefender:cleanForOccurrence(track, report)
	local preservePending = adcAdvancedAntiAPBreak
		and report
		and report.decision == "AllowUncertain"

	if not preservePending then
		return self:clean()
	end

	self.keyframes = {}

	for idx, task in next, self.tasks do
		if task.forced and task.identifier ~= "Start Block" and task.identifier ~= "End Block" then
			continue
		end

		if
			task.identifier == "Start Crouch"
			or task.identifier == "End Crouch"
			or task.identifier == "Start Slide"
			or task.identifier == "End Slide"
		then
			continue
		end

		local sourceTrack = task.sourceTrack
		if
			sourceTrack
			and sourceTrack ~= track
			and self:isOccurrenceCurrent(sourceTrack, task.sourceOccurrence)
			and sourceTrack.IsPlaying
			and coroutine.status(task.thread) ~= "dead"
		then
			continue
		end

		task:cancel()
		self.tasks[idx] = nil

		if task.identifier == "End Block" or task.identifier == "Start Block" then
			QueuedBlocking.stop(task.blockRequestId or self.blockRequestId, "occurrence-cleanup")
		end
	end

end

function AnimatorDefender:clean()
	self.keyframes = {}
	self.occurrenceStartedAt = nil
	self.occurrenceToken = nil

	Defender.clean(self)
end

function AnimatorDefender:detach()
	if disconnectAPWeaponSounds then
		disconnectAPWeaponSounds(self)
	end
	self.weaponMaid:clean()
	self.apMaid:clean()
	resetAdvancedAPState(self, "animator-defender-detach")
	resetAPBreakState(self)
	local owner = self._playerOwner
	if owner and (owner.Parent ~= players or owner.Character ~= self.entity) then
		AnimationIngressGuard.removeOwner(owner)
	end
	Defender.detach(self)
end

function AnimatorDefender.new(animator, manimations)
	local entity = animator:FindFirstAncestorWhichIsA("Model")
	if not entity then
		return error(string.format("AnimatorDefender.new(%s) - no entity.", animator:GetFullName()))
	end

	local self = setmetatable(Defender.new(), AnimatorDefender)
	local animationPlayed = Signal.new(animator.AnimationPlayed)
	self.apMaid = Maid.new()
	self.weaponMaid = Maid.new()

	self.animator = animator
	self.manimations = manimations
	self.entity = entity

	self.track = nil
	self.timing = nil
	self.offset = nil
	self.occurrenceStartedAt = nil
	self.occurrenceToken = nil
	self.apEvengardeSwingGuard = nil

	self.keyframes = {}
	resetAPBreakFields(self)
	self.apTrackOccurrences = setmetatable({}, { __mode = "k" })
	self.apScheduledOccurrences = setmetatable({}, { __mode = "k" })
	self.apTrackingActive = false
	self.apAdvancedEnabled = false
	self.apWeaponSounds = setmetatable({}, { __mode = "k" })
	self.apWeaponSoundRoots = setmetatable({}, { __mode = "k" })
	self.apNextWeaponSoundRefreshAt = 0
	self.apMantraEtherConn = nil
	self.apEvidenceGeneration = 0
	self.apAuthenticator = AttackAuthenticator.new()
	resetIngressQuarantine(self)

	self._playerOwner = players:GetPlayerFromCharacter(entity)
	self._isFromPlayer = self._playerOwner ~= nil
	self._ingressGeneration = AnimationIngressGuard.generation()
	self._ingressLastWarn = nil

	self.maid:mark(animationPlayed:connect(
		"AnimatorDefender_OnAnimationPlayed",
		(function(track)
			local admitted, ingressTiming, protectedIngress = self:rlimit(track)
			if not admitted then
				return
			end

			local occurrence = (self.apTrackOccurrences[track] or 0) + 1
			self.apTrackOccurrences[track] = occurrence
			self.apOccurrenceStartedAt[track] = {
				occurrence = occurrence,
				startedAt = os.clock(),
			}

			self:process(track, occurrence, ingressTiming, protectedIngress)
		end)
	))
	return self
end

return AnimatorDefender
end)
registerDefenseModule("Features/Combat/Defense", function(require)
local Signal = require("Utility/Signal")

local Maid = require("Utility/Maid")

local AnimatorDefender = require("Features/Combat/Objects/AnimatorDefender")

local PartDefender = require("Features/Combat/Objects/PartDefender")

local SoundDefender = require("Features/Combat/Objects/SoundDefender")

local EffectDefender = require("Features/Combat/Objects/EffectDefender")

local Configuration = require("Utility/Configuration")

local PlayerScanning = require("Game/PlayerScanning")

local EntityHistory = require("Features/Combat/EntityHistory")

local TaskSpawner = require("Utility/TaskSpawner")

local SaveManager = require("Game/Timings/SaveManager")

local Defense = {}

local replicatedStorage = game:GetService("ReplicatedStorage")
local players = game:GetService("Players")
local runService = game:GetService("RunService")

local defenseBindingMaid = Maid.new()
local defenderMaid = Maid.new()
local defenseEffectMaid = Maid.new()
local defenseHistoryMaid = Maid.new()
local defenseAntiAPMaid = Maid.new()
local antiAPPlayerMaids = {}
local antiAPLifecycleGeneration = 0
local defenderSignals = nil
local boundToggles = nil
local initialized = false

local toggleValue = (function(name)
	local control = boundToggles and boundToggles[name]
	if control then
		return control.Value == true
	end
	return Configuration.expectToggleValue(name)
end)

local defensePostSimulation = nil

local defenderPartObjects = {}
local defenderAnimationObjects = {}
local defenderEffectObjects = {}
local defenderAnimationsByEntity = {}
local defenderObjects = {}
local defenderKinds = {}

local defenderDemand = {
	animatorGlobal = false,
	sound = false,
	part = false,
	effect = false,
	history = false,
	advancedAntiAP = false,
}

local mobAnimations = {}

local parryBlockActive = false
local blockGeneration = 0
local lockOwner = nil
local WATCHDOG_SECS = 2.0

local interceptorDefender = nil
local interceptorQueuedBlocking = nil
local interceptorOriginals = {}
local interceptorWrappers = {}

local function registerDefender(instance, defender, kind)
	if not defender then
		return nil
	end

	defenderObjects[instance] = defender
	defenderKinds[instance] = kind
	if kind == "animation" and defender.entity then
		local byEntity = defenderAnimationsByEntity[defender.entity]
		if not byEntity then
			byEntity = {}
			defenderAnimationsByEntity[defender.entity] = byEntity
		end
		byEntity[instance] = defender
	end
	return defender
end

local function unregisterDefender(instance, kind)
	local defender = defenderObjects[instance]
	if not defender then
		return nil
	end

	kind = kind or defenderKinds[instance]
	defenderObjects[instance] = nil
	defenderKinds[instance] = nil
	if kind == "animation" and defender.entity then
		local byEntity = defenderAnimationsByEntity[defender.entity]
		if byEntity then
			byEntity[instance] = nil
			if next(byEntity) == nil then
				defenderAnimationsByEntity[defender.entity] = nil
			end
		end
	end
	return defender
end

local remotePlayers = {}

local function setAttackBlockState(blocked, opts)
	opts = opts or {}

	if not toggleValue("PreventAttackDuringParry") then
		defenseBindingMaid.lockWatchdog = nil
		local wasBlocked = parryBlockActive or _G.canAttack == false
		if wasBlocked then
			blockGeneration = blockGeneration + 1
		end
		_G.canAttack     = true
		parryBlockActive = false
		lockOwner        = nil
		return
	end

	if opts.expectedGen and opts.expectedGen ~= blockGeneration then
		return
	end

	if parryBlockActive == blocked then
		if blocked and opts.owner then
			lockOwner = opts.owner
		elseif not blocked then
			defenseBindingMaid.lockWatchdog = nil
			_G.canAttack = true
			lockOwner = nil
		end
		return
	end

	if blocked then
		blockGeneration = blockGeneration + 1
		lockOwner       = opts.owner
	else
		defenseBindingMaid.lockWatchdog = nil
		lockOwner       = nil
	end

	parryBlockActive = blocked
	_G.canAttack     = not blocked

	if blocked then
		local armedGen = blockGeneration
		defenseBindingMaid.lockWatchdog = task.delay(WATCHDOG_SECS, function()
			setAttackBlockState(false, { expectedGen = armedGen })
		end)
	end
end

local function initializeInterceptors()
	interceptorDefender = require("Features/Combat/Objects/Defender")
	interceptorQueuedBlocking = require("Game/QueuedBlocking")

	local O = interceptorOriginals
	local W = interceptorWrappers
	local function capture(name, object, key)
		if object[key] ~= W[name] then
			O[name] = object[key]
		end
	end

	capture("action", interceptorDefender, "action")
	capture("srpue", interceptorDefender, "srpue")
	capture("clean", interceptorDefender, "clean")
	capture("handle", interceptorDefender, "handle")
	capture("parry", interceptorDefender, "parry")
	capture("qbInvoke", interceptorQueuedBlocking, "invoke")
	capture("qbStop", interceptorQueuedBlocking, "stop")

	if W.action then
		return
	end

	local lockTypes = {
		["Parry"] = true,
		["Dodge"] = true,
		["Forced Full Dodge"] = true,
	}

	W.action = function(self, timing, action)
		local result = O.action(self, timing, action)
		if lockTypes[PP_SCRAMBLE_STR(action._type)] then
			setAttackBlockState(true, { owner = self })
		end
		return result
	end

	W.srpue = function(self, ref, timing, info)
		setAttackBlockState(true, { owner = self })
		return O.srpue(self, ref, timing, info)
	end

	W.clean = function(self, ...)
		local result = O.clean(self, ...)
		if parryBlockActive and self == lockOwner then
			setAttackBlockState(false)
		end
		return result
	end

	W.handle = function(self, timing, action, started, sourceTrack, sourceOccurrence, blockRequestId)
		local generation = blockGeneration
		local ok, err = pcall(O.handle, self, timing, action, started, sourceTrack, sourceOccurrence, blockRequestId)
		setAttackBlockState(false, { expectedGen = generation })
		if not ok then
			error(err)
		end
	end

	W.parry = function(self, timing, action)
		local generation = blockGeneration
		local ok, err = pcall(O.parry, self, timing, action)
		setAttackBlockState(false, { expectedGen = generation })
		if not ok then
			error(err)
		end
	end

	W.qbInvoke = function(blockType, id, ...)
		if id == "Defender_Deflect" then
			setAttackBlockState(true)
		end
		return O.qbInvoke(blockType, id, ...)
	end

	W.qbStop = function(id, ...)
		local result = O.qbStop(id, ...)
		if id == "Defender_Deflect" then
			setAttackBlockState(false)
			_G.lastAutoDefenseParry = os.clock()
		end
		return result
	end
end

local function setInterceptorSlot(object, key, originalName, active)
	if not object then
		return
	end
	local original = interceptorOriginals[originalName]
	local wrapper = interceptorWrappers[originalName]
	if not original or not wrapper then
		return
	end

	if active then
		if object[key] == original then
			object[key] = wrapper
		end
	elseif object[key] == wrapper then
		object[key] = original
	end
end

local function setDefenseInterceptors(lockActive)
	if not lockActive then
		setAttackBlockState(false)
	end

	setInterceptorSlot(interceptorDefender, "action", "action", lockActive)
	setInterceptorSlot(interceptorDefender, "srpue", "srpue", lockActive)
	setInterceptorSlot(interceptorDefender, "clean", "clean", lockActive)
	setInterceptorSlot(interceptorDefender, "handle", "handle", lockActive)
	setInterceptorSlot(interceptorDefender, "parry", "parry", lockActive)
	setInterceptorSlot(interceptorQueuedBlocking, "invoke", "qbInvoke", lockActive)
	setInterceptorSlot(interceptorQueuedBlocking, "stop", "qbStop", lockActive)
end

local addAnimatorDefender = (function(animator)
	if defenderObjects[animator] then
		return defenderObjects[animator]
	end

	local animationDefender = registerDefender(animator, AnimatorDefender.new(animator, mobAnimations), "animation")
	defenderAnimationObjects[animator] = animationDefender
	if animationDefender then
		local localCharacter = players.LocalPlayer.Character
		local owner = players:GetPlayerFromCharacter(animationDefender.entity)
		if owner then
			animationDefender:setPlayerOwner(owner, animationDefender.entity)
		end
		animationDefender:setAntiAPTracking(
			defenderDemand.advancedAntiAP and animationDefender.entity ~= localCharacter
		)
		animationDefender:setAdvancedAntiAP(
			defenderDemand.advancedAntiAP and animationDefender.entity ~= localCharacter
		)
	end
	return animationDefender
end)

local addSoundDefender = (function(sound)
	if defenderObjects[sound] then
		return defenderObjects[sound]
	end

	local part = sound:FindFirstAncestorWhichIsA("BasePart")
	if not part then
		return
	end

	return registerDefender(sound, SoundDefender.new(sound, part), "sound")
end)

local discoveryKindByClassName = {}
local discoveryPartEligibilityCache = nil
local onGameDescendantAdded = (function(descendant)
	local className = descendant.ClassName
	local kind = discoveryKindByClassName[className]
	if kind == nil then
		if descendant:IsA("Animator") then
			kind = "animator"
		elseif descendant:IsA("Sound") then
			kind = "sound"
		elseif descendant:IsA("BasePart") then
			kind = "part"
		else
			kind = false
		end
		discoveryKindByClassName[className] = kind
	end

	if kind == "animator" then
		if defenderDemand.animatorGlobal then
			return addAnimatorDefender(descendant)
		end
		return
	end

	if defenderDemand.sound and kind == "sound" then
		return addSoundDefender(descendant)
	end

	if defenderDemand.part and kind == "part" then
		if discoveryPartEligibilityCache then
			local timingKey = descendant.Name:match("VengefulSlash") and "VengefulSlashes" or descendant.Name
			local eligible = discoveryPartEligibilityCache[timingKey]
			if eligible == nil then
				eligible = SaveManager.ps:index(timingKey) ~= nil
				discoveryPartEligibilityCache[timingKey] = eligible
			end
			if not eligible then return nil end
		end
		return Defense.cdpo(descendant)
	end
end)

local function removeDefender(instance)
	local object = defenderObjects[instance]
	if not object then
		return
	end

	local kind = defenderKinds[instance]
	if kind == "part" then
		defenderPartObjects[instance] = nil
	elseif kind == "animation" then
		defenderAnimationObjects[instance] = nil
	elseif kind == "effect" then
		defenderEffectObjects[instance] = nil
	end

	unregisterDefender(instance, kind)
	object:detach()
end

local onGameDescendantRemoved = (function(descendant)
	removeDefender(descendant)
end)

local onClientEffectEvent = (function(name, data)
	if not defenderDemand.effect then
		return
	end
	if not name then
		return
	end

	if not data or typeof(data) ~= "table" then
		data = {}
	end

	if defenderObjects[data] then
		removeDefender(data)
	end

	local effectDefender
	effectDefender = EffectDefender.new(name, data, function()
		if defenderObjects[data] ~= effectDefender then
			return
		end
		removeDefender(data)
	end)
	effectDefender = registerDefender(data, effectDefender, "effect")
	if effectDefender then
		defenderEffectObjects[data] = effectDefender
	end
end)

local updateHistory = (function()
	local character = players.LocalPlayer.Character
	if not character then
		return
	end

	local humanoidRootPart = character:FindFirstChild("HumanoidRootPart")
	if not humanoidRootPart then
		return
	end

	local now = os.clock()

	EntityHistory.add(players.LocalPlayer, humanoidRootPart.CFrame, humanoidRootPart.AssemblyLinearVelocity, now)

	for _, player in next, remotePlayers do
		local pcharacter = player.Character
		if not pcharacter then
			continue
		end

		local proot = pcharacter:FindFirstChild("HumanoidRootPart")
		if not proot then
			continue
		end

		EntityHistory.add(pcharacter, proot.CFrame, proot.AssemblyLinearVelocity, now)
	end
end)

local updateDefenders = (function()
	for _, object in next, defenderAnimationObjects do
		object:update()
	end
	for _, object in next, defenderPartObjects do
		object:update()
	end
	for _, object in next, defenderEffectObjects do
		object:update()
	end
end)

Defense.cdpo = (function(part, timing)
	if defenderObjects[part] then
		return defenderObjects[part]
	end

	if timing and (timing.cbm or timing.umoa) then
		timing["imxd"] = PP_SCRAMBLE_RE_NUM(timing["imxd"])
		timing["imdd"] = PP_SCRAMBLE_RE_NUM(timing["imdd"])
		timing["hitbox"] = Vector3.new(
			PP_SCRAMBLE_RE_NUM(timing["hitbox"].X),
			PP_SCRAMBLE_RE_NUM(timing["hitbox"].Y),
			PP_SCRAMBLE_RE_NUM(timing["hitbox"].Z)
		)
	end

	if not timing then
		local timingKey = part.Name:match("VengefulSlash") and "VengefulSlashes" or part.Name
		if not SaveManager.ps:index(timingKey) then
			return nil
		end
	end

	local partDefender = PartDefender.new(part, timing)
	if not partDefender then
		return nil
	end

	registerDefender(part, partDefender, "part")
	defenderPartObjects[part] = partDefender

	return partDefender
end)

Defense.dao = (function(entity)
	local objects = defenderAnimationsByEntity[entity]
	if objects then
		local _, object = next(objects)
		return object
	end
end)

function Defense.init()
	if initialized then return Defense end

	local assetFolder = assert(replicatedStorage:FindFirstChild("Assets"), "missing Assets")
	local animationFolder = assert(assetFolder:FindFirstChild("Anims"), "missing Assets.Anims")
	local mobsAnimationFolder = assert(animationFolder:FindFirstChild("Mobs"), "missing Assets.Anims.Mobs")
	for _, animation in next, mobsAnimationFolder:GetDescendants() do
		if animation:IsA("Animation") and animation.Name ~= "RunningAttack" then
			mobAnimations[animation.AnimationId] = animation
		end
	end

	local requests = assert(replicatedStorage:FindFirstChild("Requests"), "missing Requests")
	local clientEffect = assert(requests:FindFirstChild("ClientEffect"), "missing Requests.ClientEffect")
	local clientEffectLarge = assert(requests:FindFirstChild("ClientEffectLarge"), "missing Requests.ClientEffectLarge")
	local clientEffectDirect = assert(requests:FindFirstChild("ClientEffectDirect"), "missing Requests.ClientEffectDirect")
	defenderSignals = {
		workspaceDescendantAdded = Signal.new(workspace.DescendantAdded),
		workspaceDescendantRemoved = Signal.new(workspace.DescendantRemoving),
		clientEffectEvent = Signal.new(clientEffect.OnClientEvent),
		clientEffectLargeEvent = Signal.new(clientEffectLarge.OnClientEvent),
		clientEffectDirect = Signal.new(clientEffectDirect.Event),
	}
	defensePostSimulation = Signal.new(runService.PostSimulation)
	_G.canAttack = true
	initializeInterceptors()
	initialized = true
	return Defense
end

local function clearDefenderObjects()
	for instance in next, defenderObjects do
		removeDefender(instance)
	end
	defenderObjects = {}
	defenderKinds = {}
	defenderPartObjects = {}
	defenderAnimationObjects = {}
	defenderEffectObjects = {}
	defenderAnimationsByEntity = {}
	remotePlayers = {}
	setAttackBlockState(false)
end

local function clearDefenderKind(kind, keep)
	for instance, currentKind in next, defenderKinds do
		local object = defenderObjects[instance]
		if currentKind == kind and (not keep or not keep(object)) then
			removeDefender(instance)
		end
	end
end

local function setDiscoveryDemand(animatorGlobal, sound, part)
	local oldAnimatorGlobal = defenderDemand.animatorGlobal
	local oldSound = defenderDemand.sound
	local oldPart = defenderDemand.part
	defenderDemand.animatorGlobal = animatorGlobal
	defenderDemand.sound = sound
	defenderDemand.part = part

	local active = animatorGlobal or sound or part
	local signals = defenderSignals
	if active and signals and not defenderMaid.workspaceAdded then
		defenderMaid.workspaceAdded = signals.workspaceDescendantAdded:connect(
			"Defense_OnDescendantAdded",
			onGameDescendantAdded
		)
		defenderMaid.workspaceRemoved = signals.workspaceDescendantRemoved:connect(
			"Defense_OnDescendantRemoved",
			onGameDescendantRemoved
		)
	end

	if oldAnimatorGlobal and not animatorGlobal then
		clearDefenderKind("animation")
	end
	if oldSound and not sound then
		clearDefenderKind("sound")
	end
	if oldPart and not part then
		clearDefenderKind("part")
	end

	if
		(animatorGlobal and not oldAnimatorGlobal)
		or (sound and not oldSound)
		or (part and not oldPart)
	then
		discoveryPartEligibilityCache = {}
		for _, descendant in next, workspace:GetDescendants() do
			onGameDescendantAdded(descendant)
		end
		discoveryPartEligibilityCache = nil
	end

	if not active then
		defenderMaid:clean()
	end
end

local function setEffectDemand(active)
	if defenderDemand.effect == active then
		return
	end
	defenderDemand.effect = active
	defenseEffectMaid:clean()
	if not active then
		clearDefenderKind("effect")
		return
	end

	local signals = defenderSignals
	if signals then
		defenseEffectMaid:mark(signals.clientEffectEvent:connect("Defense_ClientEffectEvent", onClientEffectEvent))
		defenseEffectMaid:mark(
			signals.clientEffectLargeEvent:connect("Defense_ClientEffectEventLarge", onClientEffectEvent)
		)
		defenseEffectMaid:mark(signals.clientEffectDirect:connect("Defense_ClientEffectEventDirect", onClientEffectEvent))
	end
end

local function setHistoryDemand(active)
	if defenderDemand.history == active then
		return
	end
	defenderDemand.history = active
	defenseHistoryMaid:clean()
	remotePlayers = {}
	if not active then
		EntityHistory.clearAll()
		return
	end

	local function trackRemotePlayer(player)
		if player == players.LocalPlayer then
			return
		end
		remotePlayers[player] = player
		defenseHistoryMaid[player] = Signal.new(player.CharacterRemoving):connect(
			"Defense_RemoteCharacterRemoving",
			EntityHistory.clear
		)
	end

	defenseHistoryMaid.playerAdded = Signal.new(players.PlayerAdded):connect(
		"Defense_RemotePlayerAdded",
		trackRemotePlayer
	)
	defenseHistoryMaid.playerRemoving = Signal.new(players.PlayerRemoving):connect(
		"Defense_RemotePlayerRemoving",
		function(player)
			remotePlayers[player] = nil
			defenseHistoryMaid[player] = nil
			EntityHistory.clear(player)
			if player.Character then
				EntityHistory.clear(player.Character)
			end
		end
	)
	for _, player in next, players:GetPlayers() do
		trackRemotePlayer(player)
	end

	TaskSpawner.spawnOwned(defenseHistoryMaid, "Defense_UpdateHistory", function()
		while true do
			updateHistory()
			task.wait(0.05)
		end
	end)
end

local function retireAntiAPCharacter(character)
	local byEntity = character and defenderAnimationsByEntity[character]
	if not byEntity then
		return
	end

	local animators = {}
	for animator in next, byEntity do
		animators[#animators + 1] = animator
	end
	for _, animator in next, animators do
		removeDefender(animator)
	end
end

local function refreshAntiAPCharacter(player, character)
	if
		not defenderDemand.advancedAntiAP
		or player == players.LocalPlayer
		or player.Parent ~= players
		or player.Character ~= character
		or not character
	then
		return
	end

	for _, descendant in next, character:GetDescendants() do
		if descendant:IsA("Animator") then
			local object = addAnimatorDefender(descendant)
			if object then
				object:setPlayerOwner(player, character)
				object:setAntiAPTracking(true)
				object:setAdvancedAntiAP(true)
			end
		end
	end
end

local function removeAntiAPPlayer(player)
	if antiAPPlayerMaids[player] then
		defenseAntiAPMaid[player] = nil
	end
end

local function trackAntiAPPlayer(player)
	if player == players.LocalPlayer or antiAPPlayerMaids[player] then
		return
	end

	local lifecycleMaid = Maid.new()
	antiAPPlayerMaids[player] = lifecycleMaid
	defenseAntiAPMaid[player] = function()
		if antiAPPlayerMaids[player] == lifecycleMaid then
			antiAPPlayerMaids[player] = nil
		end
		lifecycleMaid:clean()
	end

	local generation = antiAPLifecycleGeneration
	local function attach(character)
		refreshAntiAPCharacter(player, character)
		TaskSpawner.deferOwned(lifecycleMaid, "Defense_AntiAPCharacterRefresh", function()
			if
				generation == antiAPLifecycleGeneration
				and defenderDemand.advancedAntiAP
				and player.Character == character
			then
				refreshAntiAPCharacter(player, character)
			end
		end)
	end

	lifecycleMaid.characterAdded = Signal.new(player.CharacterAdded):connect(
		"Defense_AntiAPCharacterAdded",
		attach
	)
	lifecycleMaid.characterRemoving = Signal.new(player.CharacterRemoving):connect(
		"Defense_AntiAPCharacterRemoving",
		retireAntiAPCharacter
	)
	lifecycleMaid.characterChanged = Signal.new(player:GetPropertyChangedSignal("Character")):connect(
		"Defense_AntiAPCharacterChanged",
		function()
			if player.Character then
				attach(player.Character)
			end
		end
	)

	if player.Character then
		attach(player.Character)
	end
end

local function setAntiAPDemand(advancedActive)
	advancedActive = advancedActive == true
	if defenderDemand.advancedAntiAP == advancedActive then
		return
	end

	defenderDemand.advancedAntiAP = advancedActive
	AnimatorDefender.forceConfigurationRefresh()
	antiAPLifecycleGeneration = antiAPLifecycleGeneration + 1
	defenseAntiAPMaid:clean()
	antiAPPlayerMaids = {}

	if advancedActive then
		defenseAntiAPMaid.playerAdded = Signal.new(players.PlayerAdded):connect(
			"Defense_AntiAPPlayerAdded",
			trackAntiAPPlayer
		)
		defenseAntiAPMaid.playerRemoving = Signal.new(players.PlayerRemoving):connect(
			"Defense_AntiAPPlayerRemoving",
			function(player)
				if player.Character then
					retireAntiAPCharacter(player.Character)
				end
				removeAntiAPPlayer(player)
			end
		)
		for _, player in next, players:GetPlayers() do
			trackAntiAPPlayer(player)
		end
	end

	local localCharacter = players.LocalPlayer.Character
	for _, object in next, defenderAnimationObjects do
		local owner = players:GetPlayerFromCharacter(object.entity)
		if owner then
			object:setPlayerOwner(owner, object.entity)
		end
		local active = advancedActive and object.entity ~= localCharacter
		object:setAntiAPTracking(active)
		object:setAdvancedAntiAP(active)
	end
	PlayerScanning.setLoadoutTrackingActive(advancedActive)
end

local function controlEnabled(toggles, name)
	local control = toggles and toggles[name]
	return control and control.Value == true or false
end

local function setBoundLoop(key, enabled, signal, label, callback)
	if not enabled then
		defenseBindingMaid[key] = nil
		return
	end
	if not defenseBindingMaid[key] and signal then
		defenseBindingMaid[key] = signal:connect(label, callback)
	end
end

local function subscribeControl(collection, name, callback)
	local control = collection and collection[name]
	if control and type(control.Subscribe) == "function" then
		defenseBindingMaid:add(control:Subscribe(callback))
	end
end

function Defense.bindControls(toggles, options)
	defenseBindingMaid:clean()
	boundToggles = toggles

	local function sync()
		local autoDefense = controlEnabled(toggles, "EnableAutoDefense")
		local advancedAntiAP = autoDefense and controlEnabled(toggles, "AdvancedAntiAPBreak")
		local crasherProtection = controlEnabled(toggles, "CrasherProtection")
		local animatorGlobal = autoDefense or crasherProtection

		AnimatorDefender.forceConfigurationRefresh()
		setDiscoveryDemand(animatorGlobal, autoDefense, autoDefense)
		setEffectDemand(autoDefense)
		setHistoryDemand(autoDefense)
		setAntiAPDemand(advancedAntiAP)
		for _, object in next, defenderAnimationObjects do
			object:setAdvancedAntiAP(object.apTrackingActive)
			object:syncIngressGeneration()
		end
		setDefenseInterceptors(autoDefense and controlEnabled(toggles, "PreventAttackDuringParry"))
		setBoundLoop(
			"updateDefenders",
			autoDefense,
			defensePostSimulation,
			"Defense_UpdateDefenders",
			updateDefenders
		)
	end

	for _, name in next, {
		"EnableAutoDefense",
		"AdvancedAntiAPBreak",
		"CrasherProtection",
		"ValidateIncomingAnimations",
		"PreventAttackDuringParry",
	} do
		subscribeControl(toggles, name, sync)
	end
	subscribeControl(options, "CrasherProtectionThreshold", sync)
	sync()
end

function Defense.defenderCount()
	local count = 0
	for _ in next, defenderObjects do count = count + 1 end
	return count
end

function Defense.detach()
	defenseBindingMaid:clean()
	setDefenseInterceptors(false)
	setAntiAPDemand(false)
	setHistoryDemand(false)
	setEffectDemand(false)
	setDiscoveryDemand(false, false, false)
	boundToggles = nil
	defenderMaid:clean()
	defenseEffectMaid:clean()
	defenseHistoryMaid:clean()
	defenseAntiAPMaid:clean()
	antiAPPlayerMaids = {}
	clearDefenderObjects()
	table.clear(mobAnimations)
	defensePostSimulation = nil
	defenderSignals = nil
	initialized = false
end

return Defense
end)
local defenseRuntime = {
  modules = nil,
  initializing = false,
  detaching = false,
  terminalRequested = false,
  detached = false,
  generation = 0,
}

local INITIALIZATION_CANCELLED = {}

local function loadDefenseModules()
  if defenseRuntime.modules then return defenseRuntime.modules end
  defenseRuntime.modules = {
    ControlStore = requireDefenseModule("Lite/ControlStore"),
    InputClient = requireDefenseModule("Game/InputClient"),
    QueuedBlocking = requireDefenseModule("Game/QueuedBlocking"),
    SaveManager = requireDefenseModule("Game/Timings/SaveManager"),
    ModuleManager = requireDefenseModule("Game/Timings/ModuleManager"),
    PlayerScanning = requireDefenseModule("Game/PlayerScanning"),
    StateListener = requireDefenseModule("Features/Combat/StateListener"),
    Defense = requireDefenseModule("Features/Combat/Defense"),
    TaskSpawner = requireDefenseModule("Utility/TaskSpawner"),
    Logger = requireDefenseModule("Utility/Logger"),
  }
  return defenseRuntime.modules
end

local function detachDefenseModules(ownedModules)
  local modules = ownedModules or defenseRuntime.modules
  if not modules then return true end

  local cleanup = {
    { "Defense", modules.Defense.detach },
    { "StateListener", modules.StateListener.detach },
    { "PlayerScanning", modules.PlayerScanning.detach },
    { "ModuleManager", modules.ModuleManager.detach },
    { "SaveManager", modules.SaveManager.detach },
    { "QueuedBlocking", modules.QueuedBlocking.detach },
    { "InputClient", modules.InputClient.detach },
    { "TaskSpawner", modules.TaskSpawner.detach },
    { "ControlStore", modules.ControlStore.detach },
  }

  for _, owned in ipairs(cleanup) do
    local called, result = pcall(owned[2])
    if not called or result == false then
      local failure = called and "returned false" or tostring(result)
      return false, owned[1] .. ": " .. failure
    end
  end

  if defenseRuntime.modules == modules then
    defenseRuntime.modules = nil
  end
  return true
end

local function completeDetach()
  AUTO_PARRY.active = false
  AUTO_PARRY.initialized = false
  defenseRuntime.detached = true
  if type(shared) == "table" and rawget(shared, "KatalystAutoDefense") == AUTO_PARRY then
    rawset(shared, "KatalystAutoDefense", nil)
  end
end

local function initializeDefense(modules, generation)
  local function checkOwnership()
    if defenseRuntime.terminalRequested or defenseRuntime.generation ~= generation then
      error(INITIALIZATION_CANCELLED, 0)
    end
  end

  local function runStep(callback)
    checkOwnership()
    callback()
    checkOwnership()
  end

  runStep(modules.ControlStore.init)
  runStep(modules.ControlStore.syncFromKatalyst)

  checkOwnership()
  local cacheSucceeded, cacheReady = pcall(modules.InputClient.cache)
  checkOwnership()
  if not cacheSucceeded then
    modules.Logger.warn("Input cache failed: %s", tostring(cacheReady))
  elseif cacheReady == false and not modules.InputClient.recover() then
    modules.Logger.warn("Input cache is not ready and recovery could not start.")
  end

  runStep(modules.QueuedBlocking.init)
  runStep(modules.SaveManager.init)
  runStep(modules.ModuleManager.refresh)
  runStep(modules.PlayerScanning.init)
  runStep(modules.StateListener.init)
  runStep(modules.Defense.init)
  runStep(function()
    modules.Defense.bindControls(
      modules.ControlStore.getToggles(),
      modules.ControlStore.getOptions()
    )
  end)
end

function AUTO_PARRY.en()
  if defenseRuntime.terminalRequested or defenseRuntime.detached then
    return false
  end
  if AUTO_PARRY.active then
    AUTO_PARRY.sync()
    return true
  end
  if defenseRuntime.initializing or defenseRuntime.detaching then
    return false
  end

  S.autoP = true
  if not AUTO_PARRY.initialized then
    defenseRuntime.generation = defenseRuntime.generation + 1
    local generation = defenseRuntime.generation
    local modules = loadDefenseModules()
    defenseRuntime.initializing = true
    local succeeded, failure = xpcall(function()
      initializeDefense(modules, generation)
    end, function(reason)
      if reason == INITIALIZATION_CANCELLED then return reason end
      return debug.traceback(reason)
    end)
    defenseRuntime.initializing = false
    local cancelled = failure == INITIALIZATION_CANCELLED
      or defenseRuntime.terminalRequested
      or defenseRuntime.generation ~= generation
    if not succeeded or cancelled then
      S.autoP = false
      AUTO_PARRY.active = false
      AUTO_PARRY.initialized = false
      defenseRuntime.detaching = cancelled
      local cleanupSucceeded, cleanupFailure = detachDefenseModules(modules)
      defenseRuntime.detaching = false
      if cancelled then
        if cleanupSucceeded then completeDetach() end
        return false, cleanupFailure or "initialization cancellation requested"
      end
      if cleanupFailure then
        failure = tostring(failure) .. " | cleanup: " .. cleanupFailure
      end
      error(failure, 0)
    end
    AUTO_PARRY.initialized = true
  end

  AUTO_PARRY.active = true
  AUTO_PARRY.sync()
  return true
end

function AUTO_PARRY.dis()
  S.autoP = false
  AUTO_PARRY.active = false
  local modules = defenseRuntime.modules
  if modules then
    modules.ControlStore.syncFromKatalyst()
    modules.QueuedBlocking.empty("auto-defense-disabled")
  end
  return true
end

function AUTO_PARRY.sync()
  local modules = defenseRuntime.modules
  if modules then modules.ControlStore.syncFromKatalyst() end
end

function AUTO_PARRY.refreshTimings()
  local modules = defenseRuntime.modules
  if not modules then return false end
  modules.SaveManager.refresh()
  return true
end

local function ownsParryRequest(modules, generation)
  return AUTO_PARRY.active
    and not defenseRuntime.terminalRequested
    and not defenseRuntime.detaching
    and not defenseRuntime.detached
    and defenseRuntime.modules == modules
    and defenseRuntime.generation == generation
end

function AUTO_PARRY.requestParry(requestId)
  local modules = defenseRuntime.modules
  local generation = defenseRuntime.generation
  if not modules or not ownsParryRequest(modules, generation) then return false end
  if not modules.StateListener.cparry() then return false end
  if not ownsParryRequest(modules, generation) then return false end
  return modules.QueuedBlocking.invoke(
    modules.QueuedBlocking.BLOCK_TYPE_DEFLECT,
    "Katalyst:" .. tostring(requestId or "DefenseRequest")
  ) == true
end

function AUTO_PARRY.detach()
  if defenseRuntime.detached then return true end
  if defenseRuntime.detaching then return false, "detach is already in progress" end
  defenseRuntime.terminalRequested = true
  defenseRuntime.generation = defenseRuntime.generation + 1
  if defenseRuntime.initializing then
    S.autoP = false
    AUTO_PARRY.active = false
    return false, "initialization cancellation requested"
  end

  defenseRuntime.detaching = true
  local disabled, disableResult = pcall(AUTO_PARRY.dis)
  if not disabled or disableResult == false then
    defenseRuntime.detaching = false
    local failure = disabled and "returned false" or tostring(disableResult)
    return false, "disable failed: " .. failure
  end
  local succeeded, failure = detachDefenseModules()
  defenseRuntime.detaching = false
  if not succeeded then return false, failure end
  completeDetach()
  return true
end

function AUTO_PARRY.debug()
  local modules = defenseRuntime.modules
  local timingStats = modules and modules.SaveManager.stats or nil
  return {
    active = AUTO_PARRY.active,
    initialized = AUTO_PARRY.initialized,
    initializing = defenseRuntime.initializing,
    terminalRequested = defenseRuntime.terminalRequested,
    detached = defenseRuntime.detached,
    antiAP = S.antiAPBreaker == true,
    timingPrimary = timingStats and timingStats.primary or 0,
    timingNamed = timingStats and timingStats.named or 0,
    timingLearned = timingStats and timingStats.learned or 0,
    weaponAnimations = timingStats and timingStats.weapon or 0,
    defenders = modules and modules.Defense.defenderCount() or 0,
    queuedBlocks = modules and modules.QueuedBlocking.count() or 0,
  }
end

if type(shared) == "table" then
  rawset(shared, "KatalystAutoDefense", AUTO_PARRY)
end
end
local ANIM_LOGGER = {active=false, gui=nil, holder=nil}
do
  local function createToastHUD()
    if ANIM_LOGGER.gui and ANIM_LOGGER.gui.Parent then return ANIM_LOGGER.gui end
    local sg = Instance.new("ScreenGui")
    sg.Name = "KatalystMantraHUD"
    sg.ResetOnSpawn = false
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() G.protG(sg) end)
    sg.Parent = G.getHP()
    
    local container = Instance.new("Frame", sg)
    container.Name = "ToastHolder"
    container.Size = UDim2.new(0, 260, 0, 400)
    container.Position = UDim2.new(1, -270, 0, 80)
    container.BackgroundTransparency = 1
    
    local layout = Instance.new("UIListLayout", container)
    layout.SortOrder = Enum.SortOrder.LayoutOrder
    layout.Padding = UDim.new(0, 8)
    layout.VerticalAlignment = Enum.VerticalAlignment.Top
    
    ANIM_LOGGER.gui = sg
    ANIM_LOGGER.holder = container
    return sg
  end
  
  local function pushToast(targetName, trackName, animId)
    createToastHUD()
    if not ANIM_LOGGER.holder then return end
    
    -- Keep max 4 visible toasts on screen
    local children = {}
    for _, ch in ipairs(ANIM_LOGGER.holder:GetChildren()) do
      if ch:IsA("Frame") then table.insert(children, ch) end
    end
    if #children >= 4 then
      pcall(function() children[1]:Destroy() end)
    end
    
    local toast = Instance.new("Frame", ANIM_LOGGER.holder)
    toast.Size = UDim2.new(1, 0, 0, 44)
    toast.BackgroundColor3 = Color3.fromRGB(16, 16, 22)
    toast.BackgroundTransparency = 0.15
    toast.BorderSizePixel = 0
    G.mkC(toast, 6)
    G.mkS(toast, Color3.fromRGB(120, 90, 255), 1, 0.2)
    
    local accent = Instance.new("Frame", toast)
    accent.Size = UDim2.new(0, 4, 1, 0)
    accent.BackgroundColor3 = Color3.fromRGB(150, 120, 255)
    accent.BorderSizePixel = 0
    G.mkC(accent, 2)
    
    local titleLbl = G.mkL(toast, " " .. targetName, UDim2.new(0, 12, 0, 4), UDim2.new(1, -16, 0, 16), 9, Enum.Font.GothamBold, nil, Color3.fromRGB(245, 245, 248))
    local bodyLbl = G.mkL(toast, tostring(trackName) .. " (" .. tostring(animId) .. ")", UDim2.new(0, 12, 0, 22), UDim2.new(1, -16, 0, 16), 8, Enum.Font.GothamMedium, nil, Color3.fromRGB(160, 160, 190))
    
    -- Smooth Slide In & Auto-fade/Destroy in 2.5 seconds
    toast.Position = UDim2.new(1, 30, 0, 0)
    G.TS:Create(toast, TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = UDim2.new(0, 0, 0, 0)}):Play()
    
    task.delay(2.5, function()
      if toast and toast.Parent then
        local tw = G.TS:Create(toast, TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {BackgroundTransparency = 1, Position = UDim2.new(1, 30, 0, 0)})
        tw:Play()
        tw.Completed:Connect(function()
          pcall(function() toast:Destroy() end)
        end)
      end
    end)
  end

  function ANIM_LOGGER.en()
    if ANIM_LOGGER.active then return end; ANIM_LOGGER.active=true
    local function checkAni(v)
      local hum = v:FindFirstChildOfClass("Humanoid")
      local ani = hum and hum:FindFirstChildOfClass("Animator")
      if ani then 
        ani.AnimationPlayed:Connect(function(trk)
          if not ANIM_LOGGER.active then return end
          local lp = G.LP.Character; local hrp = lp and lp:FindFirstChild("HumanoidRootPart")
          local ehrp = v:FindFirstChild("HumanoidRootPart")
          if not hrp or not ehrp or (hrp.Position - ehrp.Position).Magnitude > 60 then return end
          
          -- Reject Roblox default Core priority locomotion
          if trk.Priority == Enum.AnimationPriority.Core then return end
          
          local id = trk.Animation and trk.Animation.AnimationId or "N/A"
          local numId = string.match(tostring(id), "%d+") or id
          if not numId or numId == "" then return end
          
          local animName = string.lower(trk.Name or (trk.Animation and trk.Animation.Name) or "")
          if string.find(animName, "animate") or string.find(animName, "idle") or string.find(animName, "walk") or 
            string.find(animName, "run") or string.find(animName, "jump") or string.find(animName, "fall") or 
            string.find(animName, "land") or string.find(animName, "climb") or string.find(animName, "swim") or 
            string.find(animName, "sit") or string.find(animName, "emote") or string.find(animName, "strafe") or
            string.find(animName, "toolnone") then
            return
          end
          
          local timeStr = os.date("%H:%M:%S")
          local priStr = tostring(trk.Priority):gsub("Enum%.AnimationPriority%.", "")
          
          print(string.format("[Katalyst Combat Log %s] Target: %s | Track: %s [%s] | ID: rbxassetid://%s", timeStr, v.Name, tostring(trk.Name), priStr, tostring(numId)))

          -- Sleek Self-Destroying Toast Feed (Auto-disappears in 2.5s)
          pushToast(v.Name, tostring(trk.Name) .. " [" .. priStr .. "]", "rbxassetid://" .. tostring(numId))
        end) 
      end
    end
    G.ts(function()
      local hooked = {}
      while ANIM_LOGGER.active do
        local live=G.WS:FindFirstChild("Live") or G.WS
        for _,v in ipairs(live:GetChildren()) do
          if v ~= G.LP.Character and not hooked[v] and v:FindFirstChild("HumanoidRootPart") then
            hooked[v] = true
            pcall(checkAni, v)
          end
        end
        G.tw(1)
      end
    end)
    G.noti("Anim Logger", "Active! Sleek self-fading toasts live on screen.")
  end
  function ANIM_LOGGER.dis()
    ANIM_LOGGER.active = false
    if ANIM_LOGGER.gui then
      pcall(function() ANIM_LOGGER.gui:Destroy() end)
      ANIM_LOGGER.gui = nil
      ANIM_LOGGER.holder = nil
    end
  end
end

local BUFF_LOGGER = {active=false, lastScan=""}
do
  function BUFF_LOGGER.en()
    if BUFF_LOGGER.active then return end; BUFF_LOGGER.active=true
    G.ts(function()
      local cachedEFR; pcall(function() cachedEFR = require(G.RepS:WaitForChild("EffectReplicator", 5)) end)
      while BUFF_LOGGER.active do
        local ch = G.LP.Character
        if ch then
          local scanStr = ""
          local function lprint(s) print(s); scanStr = scanStr .. tostring(s) .. "\n" end
          
          lprint("")
          lprint("[Katalyst] BUFF SCAN")
          lprint("")
          lprint(" Character Attributes ")
          for k, v in pairs(ch:GetAttributes()) do
            lprint(" "..tostring(k).." = "..tostring(v).." ("..typeof(v)..")")
          end
          lprint(" Descendant Attributes ")
          pcall(function()
            for _, d in ipairs(ch:GetDescendants()) do
              local attrs = d:GetAttributes()
              local hasAny = false
              for _ in pairs(attrs) do hasAny = true; break end
              if hasAny then
                lprint(" ["..d.ClassName.."] "..d.Name)
                for k, v in pairs(attrs) do
                  lprint("  "..tostring(k).." = "..tostring(v))
                end
              end
            end
          end)
          lprint(" ValueBase Objects ")
          pcall(function()
            for _, d in ipairs(ch:GetDescendants()) do
              if d:IsA("ValueBase") then
                lprint(" ["..d.ClassName.."] "..d.Name.." = "..tostring(d.Value))
              end
            end
          end)
          lprint(" Equipped Tools ")
          pcall(function()
            for _, t in ipairs(ch:GetChildren()) do
              if t:IsA("Tool") then
                lprint(" Tool: "..t.Name)
                for k, v in pairs(t:GetAttributes()) do
                  lprint("  "..tostring(k).." = "..tostring(v))
                end
                for _, d in ipairs(t:GetDescendants()) do
                  if d:IsA("ValueBase") then
                    lprint("  [Val] "..d.Name.." = "..tostring(d.Value))
                  end
                  for k, v in pairs(d:GetAttributes()) do
                    lprint("  "..d.Name.."."..tostring(k).." = "..tostring(v))
                  end
                end
              end
            end
          end)
          lprint(" EffectReplicator (data only) ")
          if cachedEFR and cachedEFR.Effects then
            for id, eff in pairs(cachedEFR.Effects) do
              local parts = {}
              pcall(function()
                for k, v in pairs(eff) do
                  local t = type(v)
                  if t == "string" or t == "number" or t == "boolean" then
                    table.insert(parts, tostring(k).."="..tostring(v))
                  end
                end
              end)
              if #parts > 0 then
                lprint(" "..table.concat(parts, " | "))
              end
            end
          else
            lprint(" (not found or empty)")
          end
          lprint(" GC Scan (damage/poser/stored) ")
          if type(getgc) == "function" then
            pcall(function()
              local found = 0
              for _, o in ipairs(getgc(true)) do
                if type(o) == "table" and found < 30 then
                  for k, v in pairs(o) do
                    if type(k) == "string" and (type(v) == "number" or type(v) == "string" or type(v) == "boolean") then
                      local kl = string.lower(k)
                      if string.find(kl,"poser",1,true) or string.find(kl,"stored",1,true) or string.find(kl,"accum",1,true) or string.find(kl,"stack",1,true) or string.find(kl,"chain",1,true) or string.find(kl,"dmg",1,true) or string.find(kl,"damage",1,true) or string.find(kl,"burst",1,true) or string.find(kl,"ring",1,true) or string.find(kl,"sheathe",1,true) or string.find(kl,"buffer",1,true) then
                        lprint(" "..tostring(k).." = "..tostring(v))
                        found = found + 1
                      end
                    end
                  end
                end
              end
              if found == 0 then lprint(" (no matching keys found)") end
            end)
          else
            lprint(" (getgc not available)")
          end
          lprint("")
          BUFF_LOGGER.lastScan = scanStr
        end
        G.tw(3)
      end
    end)
    G.noti("Buff Scanner", "Press F9  scans attrs, effects & GC every 3s.")
  end
  function BUFF_LOGGER.dis() BUFF_LOGGER.active=false end
end

local FLY = {
  active = false,
  conn = nil,
  mover = nil,
  activeCharacter = nil,
  currentAnimator = nil,
  currentAnimation = nil,
  animationTracks = {},
  detachedFlights = {},
  controlBound = false,
  control = {
    forward = 0,
    backward = 0,
    left = 0,
    right = 0,
  },
  controllerManager = nil,
  controllerOriginal = nil,
  controllerCaptured = false,
  controllerConn = nil,
  ragdollHumanoid = nil,
  ragdollPlatformStand = nil,
  ragdollAutoRotate = nil,
}
local BOAT_FLY = {active=false, conn=nil}
local CFRAME_SPEED = {active=false, conn=nil}
local SPEEDHACK_ENGINE = {active=false, conn=nil}
local INFINITE_JUMP = {active=false, conn=nil}
local MAX_MOMENTUM = {active=false, conn=nil}
local AUTO_SPRINT_ENGINE = {active=false, conn=nil}

local ensureEffectHook
do
  local flyAnimationIds = {
    forward = "rbxassetid://11219267220",
    backward = "rbxassetid://11222147878",
    idle = "rbxassetid://11220296193",
  }
  local flyActionNames = {
    "KatalystFlyForward",
    "KatalystFlyBackward",
    "KatalystFlyLeft",
    "KatalystFlyRight",
  }
  local noclipeffects = {
    PrepareTP = true,
    TPSafe = true,
  }

  local nofalleffects = {
    NoFall = true,
    SlowFall = true,
  }

  local flyeffects = {
    FlameFlight = true,
    Levitate = true,
    Gliding = true,
    NoFall = true,
    SlowFall = true,
  }

  local blockedNoFall = {
    FallDamage = true,
    Falling = true,
    FallingDown = true,
    AntiAir = true,
    AirTime = true,
  }

  ensureEffectHook = function()
    pcall(function()
      if not cachedEF then
        local _ef = G.RepS:FindFirstChild("EffectReplicator")
        if _ef then cachedEF = require(_ef) end
      end
      if cachedEF and not oldHasEffect then
        oldHasEffect = cachedEF.HasEffect
        oldHasAny = cachedEF.HasAny

        cachedEF.HasEffect = function(self, effectName, ...)
          if S.nc and noclipeffects[effectName] then
            return true
          end
          if S.nfd and nofalleffects[effectName] then
            return true
          end
          if S.fly and flyeffects[effectName] then
            return true
          end
          if (S.nfd or S.fly) and blockedNoFall[effectName] then
            return false
          end
          if S.noStun then
            if effectName == "Stun" or effectName == "Stunned"
              or effectName == "PostureBreak" or effectName == "Stagger"
              or effectName == "Grabbed" or effectName == "CarryStun"
              or effectName == "PB" or effectName == "PostureBroken"
              or effectName == "GettingUp" or effectName == "HeavyStun" then
              return false
            end
          end
          return oldHasEffect(self, effectName, ...)
        end

        if oldHasAny then
          cachedEF.HasAny = function(self, ...)
            if S.nc then
              for i = 1, select("#", ...) do
                if noclipeffects[select(i, ...)] then return true end
              end
            end
            if S.nfd then
              for i = 1, select("#", ...) do
                if nofalleffects[select(i, ...)] then return true end
              end
            end
            if S.fly then
              for i = 1, select("#", ...) do
                if flyeffects[select(i, ...)] then return true end
              end
            end
            return oldHasAny(self, ...)
          end
        end

        local oldCreate = cachedEF.CreateEffect
        if oldCreate then
          cachedEF.CreateEffect = function(self, effectName, ...)
            if (S.nfd or S.fly) and blockedNoFall[effectName] then
              return nil
            end
            if S.noStun then
              if effectName == "Stun" or effectName == "Stunned"
                or effectName == "PostureBreak" or effectName == "Stagger"
                or effectName == "PB" or effectName == "HeavyStun"
                or effectName == "CarryStun" or effectName == "GettingUp" then
                return nil
              end
            end
            return oldCreate(self, effectName, ...)
          end
        end
      end
    end)
  end

  local function directionCallback(field, pressedValue)
    return function(_, inputState)
      if inputState == Enum.UserInputState.Begin then
        FLY.control[field] = pressedValue
      elseif inputState == Enum.UserInputState.End or inputState == Enum.UserInputState.Cancel then
        FLY.control[field] = 0
      end

      return Enum.ContextActionResult.Pass
    end
  end

  local function bindControls()
    if FLY.controlBound then
      return
    end

    FLY.controlBound = true
    contextActionService:BindAction(
      flyActionNames[1],
      directionCallback("forward", -1),
      false,
      Enum.KeyCode.W
    )
    contextActionService:BindAction(
      flyActionNames[2],
      directionCallback("backward", 1),
      false,
      Enum.KeyCode.S
    )
    contextActionService:BindAction(
      flyActionNames[3],
      directionCallback("left", -1),
      false,
      Enum.KeyCode.A
    )
    contextActionService:BindAction(
      flyActionNames[4],
      directionCallback("right", 1),
      false,
      Enum.KeyCode.D
    )
  end

  local function unbindControls()
    if not FLY.controlBound then
      return
    end

    for _, actionName in ipairs(flyActionNames) do
      contextActionService:UnbindAction(actionName)
    end

    FLY.control.forward = 0
    FLY.control.backward = 0
    FLY.control.left = 0
    FLY.control.right = 0
    FLY.controlBound = false
  end

  local function getMoveVector()
    local x = 0
    local z = 0
    if G.UIS:IsKeyDown(Enum.KeyCode.W) then z = z - 1 end
    if G.UIS:IsKeyDown(Enum.KeyCode.S) then z = z + 1 end
    if G.UIS:IsKeyDown(Enum.KeyCode.A) then x = x - 1 end
    if G.UIS:IsKeyDown(Enum.KeyCode.D) then x = x + 1 end

    if z == 0 then z = FLY.control.forward + FLY.control.backward end
    if x == 0 then x = FLY.control.left + FLY.control.right end

    local vec = Vector3.new(x, 0, z)
    return vec.Magnitude > 0 and vec.Unit or Vector3.zero
  end

  local function stopFlyAnimations()
    for name, entry in pairs(FLY.animationTracks) do
      pcall(entry.track.Stop, entry.track, 0)
      pcall(entry.track.Destroy, entry.track)
      pcall(entry.animation.Destroy, entry.animation)
      FLY.animationTracks[name] = nil
    end

    FLY.currentAnimator = nil
    FLY.currentAnimation = nil
  end

  local function loadFlyAnimations(animator)
    stopFlyAnimations()
    FLY.currentAnimator = animator

    for name, animationId in pairs(flyAnimationIds) do
      local animation = Instance.new("Animation")
      animation.AnimationId = animationId

      local success, track = pcall(animator.LoadAnimation, animator, animation)
      if success and track then
        track.Priority = Enum.AnimationPriority.Action4
        track.Looped = true
        FLY.animationTracks[name] = {
          animation = animation,
          track = track,
        }
      else
        animation:Destroy()
      end
    end
  end

  local function getAnimationName()
    local moveVector = getMoveVector()
    if moveVector.Z < -0.001 then
      return "forward"
    elseif moveVector.Z > 0.001 then
      return "backward"
    end

    return "idle"
  end

  local function updateFlyAnimation(humanoid)
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if not animator then
      stopFlyAnimations()
      return
    end

    if FLY.currentAnimator ~= animator then
      loadFlyAnimations(animator)
    end

    local animationName = getAnimationName()
    local entry = FLY.animationTracks[animationName] or FLY.animationTracks.idle
    if not entry or (FLY.currentAnimation == animationName and entry.track.IsPlaying) then
      return
    end

    for name, other in pairs(FLY.animationTracks) do
      if name ~= animationName then
        pcall(other.track.Stop, other.track, 0.08)
      end
    end

    local success = pcall(entry.track.Play, entry.track, 0.08, 1, 1)
    FLY.currentAnimation = success and animationName or nil
  end

  local function destroyFlyMover()
    local mover = FLY.mover
    FLY.mover = nil
    if mover then
      pcall(mover.Destroy, mover)
    end
    pcall(function()
      local char = G.LP and G.LP.Character
      local hrp = char and char:FindFirstChild("HumanoidRootPart")
      if hrp then
        for _, obj in ipairs(hrp:GetChildren()) do
          if obj.Name == "KainLiteFlyVelocity" or (obj:IsA("BodyVelocity") and obj:HasTag("AllowedBM")) then
            pcall(obj.Destroy, obj)
          end
        end
      end
    end)
  end

  local function restoreFlights()
    for flight, parent in pairs(FLY.detachedFlights) do
      pcall(function()
        flight.Parent = parent
      end)
      FLY.detachedFlights[flight] = nil
    end
  end

  local function restoreController()
    if FLY.controllerConn then
      FLY.controllerConn:Disconnect()
      FLY.controllerConn = nil
    end

    local controllerManager = FLY.controllerManager
    local originalController = FLY.controllerOriginal
    local captured = FLY.controllerCaptured
    FLY.controllerManager = nil
    FLY.controllerOriginal = nil
    FLY.controllerCaptured = false

    if captured and controllerManager then
      pcall(function()
        controllerManager.ActiveController = originalController
      end)
    end
  end

  local function restoreRagdoll()
    local humanoid = FLY.ragdollHumanoid
    if not humanoid then
      local char = G.LP and G.LP.Character
      humanoid = char and char:FindFirstChildOfClass("Humanoid")
    end
    local platformStand = FLY.ragdollPlatformStand
    local autoRotate = FLY.ragdollAutoRotate
    FLY.ragdollHumanoid = nil
    FLY.ragdollPlatformStand = nil
    FLY.ragdollAutoRotate = nil

    if not (humanoid and humanoid.Parent) then
      return
    end

    local knocked = false
    pcall(function()
      if not cachedEF then
        local module = G.RepS:FindFirstChild("EffectReplicator")
        if module then cachedEF = require(module) end
      end
      local effects = cachedEF and cachedEF:GetEffectsHash()
      knocked = effects and effects.Knocked ~= nil or false
    end)

    if knocked then
      return
    end

    pcall(function()
      humanoid.PlatformStand = false
      humanoid.AutoRotate = true
      humanoid:ChangeState(Enum.HumanoidStateType.Running)
    end)
  end

  local function keepRagdoll(humanoid)
    if FLY.ragdollHumanoid ~= humanoid then
      restoreRagdoll()
      FLY.ragdollHumanoid = humanoid
      FLY.ragdollPlatformStand = humanoid.PlatformStand
      FLY.ragdollAutoRotate = humanoid.AutoRotate
    end

    humanoid.PlatformStand = true
    humanoid.AutoRotate = false
    humanoid:ChangeState(Enum.HumanoidStateType.Physics)
  end

  local function keepAirController(controllerManager)
    if FLY.controllerManager ~= controllerManager or not (FLY.active and S.fly and S.nc) then
      return
    end

    local airController = controllerManager:FindFirstChild("AirController")
    if airController and controllerManager.ActiveController ~= airController then
      controllerManager.ActiveController = airController
    end
  end

  function FLY.syncController(character)
    if not (FLY.active and S.fly) then
      restoreController()
      return
    end

    local controllerManager = character and character:FindFirstChild("ControllerManager")
    if not controllerManager then
      restoreController()
      return
    end

    if FLY.controllerManager ~= controllerManager then
      restoreController()
      FLY.controllerManager = controllerManager
      FLY.controllerOriginal = controllerManager.ActiveController
      FLY.controllerCaptured = true
    end

    if not FLY.controllerConn then
      FLY.controllerConn = controllerManager:GetPropertyChangedSignal("ActiveController"):Connect(function()
        keepAirController(controllerManager)
      end)
    end

    local controller = controllerManager:FindFirstChild("AirController")
    if controller and controllerManager.ActiveController ~= controller then
      controllerManager.ActiveController = controller
    end
  end

  function FLY.noClipDisabled()
    restoreController()
  end

  local function stopCharacter()
    destroyFlyMover()
    restoreFlights()
    stopFlyAnimations()
    restoreController()
    restoreRagdoll()
    FLY.activeCharacter = nil
  end

  local function updateFly(rootPart, humanoid)
    keepRagdoll(humanoid)

    local existingFlight = rootPart:FindFirstChild("HelioFlight")
    if existingFlight then
      FLY.detachedFlights[existingFlight] = existingFlight.Parent
      existingFlight.Parent = nil
    end

    local mover = FLY.mover
    if not mover or mover.Parent ~= rootPart then
      destroyFlyMover()
      mover = Instance.new("BodyVelocity")
      mover.Name = "KainLiteFlyVelocity"
      mover.MaxForce = Vector3.new(9e9, 9e9, 9e9)
      mover:AddTag("AllowedBM")
      mover.Parent = rootPart
      FLY.mover = mover
    end

    local camera = G.WS.CurrentCamera
    if camera then
      local moveVec = getMoveVector()
      local flySpeed = tonumber(CFG.FlySpeed) or 200
      local flyUpSpeed = tonumber(CFG.FlyUpSpeed) or 150
      local velocity = camera.CFrame:VectorToWorldSpace(moveVec * flySpeed)

      if G.UIS:IsKeyDown(Enum.KeyCode.Space) then
        velocity = velocity + Vector3.new(0, flyUpSpeed, 0)
      end
      if G.UIS:IsKeyDown(Enum.KeyCode.LeftShift) or G.UIS:IsKeyDown(Enum.KeyCode.LeftControl) then
        velocity = velocity - Vector3.new(0, flyUpSpeed, 0)
      end
      mover.Velocity = velocity
    end

    updateFlyAnimation(humanoid)
  end

  local function updateMovement()
    if not FLY.active then
      return
    end

    local character = G.LP and G.LP.Character
    local rootPart = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not rootPart or not humanoid then
      if FLY.activeCharacter then
        stopCharacter()
      end
      return
    end

    if FLY.activeCharacter ~= character then
      stopCharacter()
      FLY.activeCharacter = character
    end

    FLY.syncController(character)
    updateFly(rootPart, humanoid)
  end

  function FLY.en()
    if FLY.active then
      return
    end

    FLY.active = true
    S.fly = true
    bindControls()
    FLY.conn = G.RS.PreSimulation:Connect(updateMovement)
    G.noti("Fly", "Enabled (WASD + Space)")
  end

  function FLY.clr()
    if FLY.conn then
      FLY.conn:Disconnect()
      FLY.conn = nil
    end
    stopCharacter()
    unbindControls()
  end

  function FLY.dis()
    FLY.active = false
    S.fly = false
    FLY.clr()
    if S.nc then
      FLY.syncController(G.LP and G.LP.Character)
    end
    G.noti("Fly", "Disabled")
  end
end

do
  function BOAT_FLY.en()
    if BOAT_FLY.conn then return end
    S.boatSpeed = true
    ensureEffectHook()
    BOAT_FLY.conn = G.RS.Heartbeat:Connect(function(dt)
      if not S.boatSpeed then return end
      local lp = G.LP
      local ch = lp and lp.Character
      local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      if not hrp or not hum then return end

      local effectReplicator = G.RepS:FindFirstChild("EffectReplicator")
      local effectReplicatorModule = effectReplicator and require(effectReplicator)
      if not effectReplicatorModule then return end

      local steeringEffect = effectReplicatorModule:FindEffect("Steering")
      if not steeringEffect or not steeringEffect.Value then return end

      local steeringValue = steeringEffect.Value
      local ship = steeringValue:FindFirstAncestorWhichIsA("Model")
      if not ship then return end

      local chHandler = ch:FindFirstChild("CharacterHandler")
      if chHandler then
        local requests = chHandler:FindFirstChild("Requests")
        local equipWeapon = requests and requests:FindFirstChild("DrawWeapon")
        if equipWeapon then
          pcall(function()
            equipWeapon:FireServer(true)
            equipWeapon:FireServer(false)
          end)
        end
      end

      local speed = tonumber(CFG.BoatSpeed) or 1000
      local moveDirection = hum.MoveDirection

      if moveDirection.Magnitude > 0 then
        local velocityVector = moveDirection.Unit * speed
        local bv = ship:FindFirstChild("BodyVelocity", true)
        if bv then
          bv.Velocity = velocityVector
          bv.P = 99999
        else
          ship:TranslateBy(moveDirection.Unit * dt * speed)
        end
      else
        local bv = ship:FindFirstChild("BodyVelocity", true)
        if bv then
          bv.Velocity = Vector3.zero
          bv.P = 99999
        end
      end

      local shipControls = steeringValue:FindFirstChild("ShipControls")
      if shipControls then
        pcall(function()
          shipControls:FireServer("s", true, hrp.CFrame)
        end)
      end
    end)
    G.noti("Boat Speed", "Enabled  Speed: " .. tostring(CFG.BoatSpeed or 1000), 2)
  end

  function BOAT_FLY.dis()
    S.boatSpeed = false
    if BOAT_FLY.conn then
      BOAT_FLY.conn:Disconnect()
      BOAT_FLY.conn = nil
    end
    G.noti("Boat Speed", "Disabled", 2)
  end
end

do
  function CFRAME_SPEED.en()
    if CFRAME_SPEED.conn then return end
    S.cframeSpeed = true
    CFRAME_SPEED.conn = G.RS.Heartbeat:Connect(function(dt)
      if not S.cframeSpeed or S.fly then return end
      local ch = G.LP and G.LP.Character
      local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      if not hrp or not hum then return end

      local moveDirection = hum.MoveDirection
      if not moveDirection or moveDirection.Magnitude <= 0.001 then return end

      local mult = tonumber(CFG.CFrameSpeedMult) or 2
      hrp.CFrame = hrp.CFrame + (moveDirection * (mult * dt * 16))
    end)
    G.noti("CFrame Speed", "Enabled  Multiplier: " .. tostring(CFG.CFrameSpeedMult or 2) .. "x", 2)
  end

  function CFRAME_SPEED.dis()
    S.cframeSpeed = false
    if CFRAME_SPEED.conn then
      CFRAME_SPEED.conn:Disconnect()
      CFRAME_SPEED.conn = nil
    end
    G.noti("CFrame Speed", "Disabled", 2)
  end
end

do
  function SPEEDHACK_ENGINE.en()
    if SPEEDHACK_ENGINE.conn then return end
    S.speedhack = true
    SPEEDHACK_ENGINE.conn = G.RS.Heartbeat:Connect(function()
      if not S.speedhack or S.fly then return end
      local ch = G.LP and G.LP.Character
      local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      if not hrp or not hum then return end

      local moveDirection = hum.MoveDirection
      if moveDirection.Magnitude <= 0.001 then return end

      local spd = tonumber(CFG.SpeedhackSpeed) or 200
      local curY = hrp.AssemblyLinearVelocity.Y
      hrp.AssemblyLinearVelocity = (moveDirection.Unit * spd) + Vector3.new(0, curY, 0)
    end)
    G.noti("Speedhack", "Enabled  Speed: " .. tostring(CFG.SpeedhackSpeed or 200), 2)
  end

  function SPEEDHACK_ENGINE.dis()
    S.speedhack = false
    if SPEEDHACK_ENGINE.conn then
      SPEEDHACK_ENGINE.conn:Disconnect()
      SPEEDHACK_ENGINE.conn = nil
    end
    G.noti("Speedhack", "Disabled", 2)
  end
end

do
  function INFINITE_JUMP.en()
    if INFINITE_JUMP.conn then return end
    S.infiniteJump = true
    INFINITE_JUMP.conn = G.RS.Heartbeat:Connect(function()
      if not S.infiniteJump or S.fly then return end
      if not G.UIS:IsKeyDown(Enum.KeyCode.Space) then return end
      local ch = G.LP and G.LP.Character
      local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
      if not hrp then return end

      local boost = tonumber(CFG.InfiniteJumpBoost) or 50
      local curX = hrp.AssemblyLinearVelocity.X
      local curZ = hrp.AssemblyLinearVelocity.Z
      hrp.AssemblyLinearVelocity = Vector3.new(curX, boost, curZ)
    end)
    G.noti("Infinite Jump", "Enabled", 2)
  end

  function INFINITE_JUMP.dis()
    S.infiniteJump = false
    if INFINITE_JUMP.conn then
      INFINITE_JUMP.conn:Disconnect()
      INFINITE_JUMP.conn = nil
    end
    G.noti("Infinite Jump", "Disabled", 2)
  end
end

do
  function MAX_MOMENTUM.en()
    if MAX_MOMENTUM.conn then return end
    S.maxMomentum = true
    MAX_MOMENTUM.conn = G.RS.Heartbeat:Connect(function()
      if not S.maxMomentum then return end
      pcall(function()
        local effectReplicator = G.RepS:FindFirstChild("EffectReplicator")
        local effectReplicatorModule = effectReplicator and require(effectReplicator)
        if not effectReplicatorModule then return end

        local forcedMomentumEffect = effectReplicatorModule:FindEffect("ForceMomentum")
        if not forcedMomentumEffect then
          forcedMomentumEffect = effectReplicatorModule:CreateEffect("ForceMomentum")
        end
        if forcedMomentumEffect then
          if forcedMomentumEffect.Value ~= 10 then
            forcedMomentumEffect.Value = 10
          end
          forcedMomentumEffect.Disabled = false
        end
      end)
    end)
    G.noti("Max Momentum Spoofer", "Enabled", 2)
  end

  function MAX_MOMENTUM.dis()
    S.maxMomentum = false
    if MAX_MOMENTUM.conn then
      MAX_MOMENTUM.conn:Disconnect()
      MAX_MOMENTUM.conn = nil
    end
    pcall(function()
      local effectReplicator = G.RepS:FindFirstChild("EffectReplicator")
      local effectReplicatorModule = effectReplicator and require(effectReplicator)
      if effectReplicatorModule then
        local forcedMomentumEffect = effectReplicatorModule:FindEffect("ForceMomentum")
        if forcedMomentumEffect then forcedMomentumEffect.Disabled = true end
      end
    end)
    G.noti("Max Momentum Spoofer", "Disabled", 2)
  end
end

do
  function AUTO_SPRINT_ENGINE.en()
    if AUTO_SPRINT_ENGINE.conn then return end
    S.autoSprint = true
    AUTO_SPRINT_ENGINE.conn = G.RS.Heartbeat:Connect(function()
      if not S.autoSprint then return end
      local ch = G.LP and G.LP.Character
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      if not hum then return end
      if hum.MoveDirection.Magnitude > 0.001 then
        pcall(function()
          local chHandler = ch:FindFirstChild("CharacterHandler")
          local requests = chHandler and chHandler:FindFirstChild("Requests")
          local sprint = requests and requests:FindFirstChild("Sprint")
          if sprint then sprint:FireServer(true) end
        end)
      end
    end)
    G.noti("Auto Sprint", "Enabled", 2)
  end

  function AUTO_SPRINT_ENGINE.dis()
    S.autoSprint = false
    if AUTO_SPRINT_ENGINE.conn then
      AUTO_SPRINT_ENGINE.conn:Disconnect()
      AUTO_SPRINT_ENGINE.conn = nil
    end
    G.noti("Auto Sprint", "Disabled", 2)
  end
end

local AGIL = { active = false, conn = nil, preConn = nil, charConn = nil }
do
  local function applyAgility()
    if not (S.agil or S.agSpd) then return end
    local ch = G.LP and G.LP.Character
    if not ch then return end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    local root = ch:FindFirstChild("HumanoidRootPart")
    if not hum or not root then return end

    local state = hum:GetState()
    if state == Enum.HumanoidStateType.Climbing
      or state == Enum.HumanoidStateType.Swimming
      or state == Enum.HumanoidStateType.Physics
      or state == Enum.HumanoidStateType.Ragdoll then
      return
    end

    local isDodging = false
    pcall(function()
      if not cachedEF then
        local module = G.RepS:FindFirstChild("EffectReplicator")
        if module then cachedEF = require(module) end
      end
      if cachedEF and cachedEF.HasEffect then
        isDodging = cachedEF:HasEffect("Dodge") or cachedEF:HasEffect("Roll") or cachedEF:HasEffect("Slide")
      end
    end)
    if isDodging or ch:GetAttribute("Rolling") or ch:GetAttribute("Dashing") or ch:GetAttribute("Dodging") then
      return
    end

    -- Calculate target WalkSpeed from both Agility and WalkSpeed settings
    local agSpd = 16.0
    if S.agil then
      local agVal = tonumber(CFG.AgilVal) or 100
      agSpd = math.max(22.0, 16.0 + (agVal * 0.25))
    end

    local wsSpd = 16.0
    if S.agSpd then
      wsSpd = tonumber(CFG.SpdVal) or 26.0
    end

    local targetSpd = math.max(agSpd, wsSpd)

    -- Strip slowdown attributes
    ch:SetAttribute("ssv_Slowdown", nil)
    ch:SetAttribute("LowHealth", false)
    ch:SetAttribute("Injured", false)
    ch:SetAttribute("Crippled", false)
    ch:SetAttribute("Limp", false)
    ch:SetAttribute("Slow", false)

    -- Apply attribute spoofing to Player Data and Character
    local data = G.LP:FindFirstChild("Data")
    if data and S.agil and CFG.AgilVal then
      pcall(function() data:SetAttribute("Agility", tonumber(CFG.AgilVal) or 100) end)
    end
    if S.agil and CFG.AgilVal then
      pcall(function() ch:SetAttribute("Agility", tonumber(CFG.AgilVal) or 100) end)
      pcall(function() ch:SetAttribute("AgilityBoost", true) end)
      pcall(function() ch:SetAttribute("SpeedBoost", true) end)
    end

    -- Apply WalkSpeed directly
    hum.WalkSpeed = targetSpd

    -- Direct Agility boost on movement vector (enabled by default or when moving)
    local moveDir = hum.MoveDirection
    if moveDir.Magnitude > 0.01 and not S.fly and hum.FloorMaterial ~= Enum.Material.Air then
      local curVel = root.AssemblyLinearVelocity
      local flatMove = moveDir.Unit * targetSpd
      root.AssemblyLinearVelocity = Vector3.new(flatMove.X, curVel.Y, flatMove.Z)
    end
  end

  function AGIL.en()
    if AGIL.active then return end
    AGIL.active = true
    ensureEffectHook()
    if not AGIL.conn then
      AGIL.conn = G.RS.Heartbeat:Connect(function()
        if not (S.agil or S.agSpd) then return end
        pcall(applyAgility)
      end)
    end
    if not AGIL.preConn then
      AGIL.preConn = G.RS.PreSimulation:Connect(function()
        if not (S.agil or S.agSpd) then return end
        pcall(applyAgility)
      end)
    end
    if not AGIL.charConn then
      AGIL.charConn = G.LP.CharacterAdded:Connect(function()
        task.wait(0.2)
        pcall(applyAgility)
      end)
    end
    pcall(applyAgility)
  end

  function AGIL.dis()
    AGIL.active = false
    if AGIL.conn then
      AGIL.conn:Disconnect()
      AGIL.conn = nil
    end
    if AGIL.preConn then
      AGIL.preConn:Disconnect()
      AGIL.preConn = nil
    end
    if AGIL.charConn then
      AGIL.charConn:Disconnect()
      AGIL.charConn = nil
    end
    pcall(function()
      local ch = G.LP and G.LP.Character
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      if hum then hum.WalkSpeed = 16.0 end
    end)
  end
end

