  active = false,
  conns = {},
  customEmotes = {
    ["Point"] = "rbxassetid://10875024765",
    ["Bow"] = "rbxassetid://10875027582",
    ["Wave"] = "rbxassetid://10875029381",
    ["Cheer"] = "rbxassetid://10875031024",
