    ["JumpingJacks"] = "rbxassetid://10875094412",
    ["Roar"] = "rbxassetid://10875096219"
  }
}
do
  local currentTrack = nil

  function EMOTE_SPOOFER.stopGesture()
    if currentTrack then
      pcall(function() currentTrack:Stop(0.15) end)
      currentTrack = nil
    end
  end

  function EMOTE_SPOOFER.playGesture(name)
    if not name or name == "" then return end
    pcall(function()
      local ch = G.LP and G.LP.Character
      if not ch then return end
      local hum = ch:FindFirstChildOfClass("Humanoid")
      local ani = hum and (hum:FindFirstChildOfClass("Animator") or hum:FindFirstChild("Animator"))

      EMOTE_SPOOFER.stopGesture()

      -- Play locally if track exists
      local animId = EMOTE_SPOOFER.customEmotes[name]
      if ani and animId then
        local anim = Instance.new("Animation")
        anim.AnimationId = animId
        currentTrack = ani:LoadAnimation(anim)
        currentTrack.Priority = Enum.AnimationPriority.Action4
        currentTrack:Play(0.15)
      end

      -- Fire Deepwoken Gesture/Emote Remote
      local gestureRemote = (getRemote and getRemote("Gesture")) or (getRemote and getRemote("Emote"))
      if not gestureRemote then
        local chHandler = ch:FindFirstChild("CharacterHandler")
        local requests = chHandler and chHandler:FindFirstChild("Requests")
        gestureRemote = requests and (requests:FindFirstChild("Gesture") or requests:FindFirstChild("Emote"))
      end
      if not gestureRemote then
        local repRequests = G.RepS:FindFirstChild("Requests")
        gestureRemote = repRequests and (repRequests:FindFirstChild("Gesture") or repRequests:FindFirstChild("Emote"))
      end
      if not gestureRemote then
        gestureRemote = G.RS:FindFirstChild("Gesture", true) or G.RS:FindFirstChild("Emote", true)
      end

      if gestureRemote then
        if gestureRemote:IsA("RemoteEvent") or gestureRemote:IsA("UnreliableRemoteEvent") then
          pcall(function() gestureRemote:FireServer(name) end)
          pcall(function() gestureRemote:FireServer(name:lower()) end)
        elseif gestureRemote:IsA("RemoteFunction") then
          pcall(function() gestureRemote:InvokeServer(name) end)
          pcall(function() gestureRemote:InvokeServer(name:lower()) end)
        end
      end
    end)
  end

  local hookedButtons = setmetatable({}, { __mode = "k" })

  function EMOTE_SPOOFER.unlockGuiEmotes()
    pcall(function()
      local allGestures = {}
      for gName, _ in pairs(EMOTE_SPOOFER.customEmotes) do
        table.insert(allGestures, gName)
      end
      local joinedGestures = table.concat(allGestures, ",")
      
      -- Spoof attributes on Player Data and Character
      local data = G.LP:FindFirstChild("Data")
      if data then
        pcall(function() data:SetAttribute("Gestures", joinedGestures) end)
        pcall(function() data:SetAttribute("Emotes", joinedGestures) end)
        
        -- Create/spoof gesture values in Data folder if present
        local gesturesFolder = data:FindFirstChild("Gestures") or data:FindFirstChild("Emotes")
        if gesturesFolder then
          for _, gName in ipairs(allGestures) do
            if not gesturesFolder:FindFirstChild(gName) then
              local gVal = Instance.new("BoolValue")
              gVal.Name = gName
              gVal.Value = true
              gVal.Parent = gesturesFolder
            end
          end
        end
      end

      local ch = G.LP and G.LP.Character
      if ch then
        pcall(function() ch:SetAttribute("Gestures", joinedGestures) end)
        pcall(function() ch:SetAttribute("Emotes", joinedGestures) end)
      end

      -- Unlock all Wheel/Radial GUI items in PlayerGui
      local pgui = G.LP:FindFirstChildOfClass("PlayerGui")
      if pgui then
        for _, desc in ipairs(pgui:GetDescendants()) do
          local dName = desc.Name:lower()
          if desc:IsA("GuiObject") and (dName:find("gesture") or dName:find("emote") or dName:find("wheel") or dName:find("radial") or dName:find("action") or dName:find("slot") or dName:find("choice")) then
            if desc:IsA("ImageButton") or desc:IsA("TextButton") then
              desc.Active = true
              desc.Selectable = true
              desc.AutoButtonColor = true
              pcall(function() desc.Interactable = true end)
              
              -- Hook button click to trigger emote
              if not hookedButtons[desc] then
                hookedButtons[desc] = true
                desc.MouseButton1Click:Connect(function()
                  if not S.unlockEmotes then return end
                  local emoteTarget = desc.Name
                  local label = desc:FindFirstChildOfClass("TextLabel")
                  if label and label.Text ~= "" then
                    emoteTarget = label.Text
                  end
                  EMOTE_SPOOFER.playGesture(emoteTarget)
                end)
              end
            end

            -- Remove lock icons & overlays
            for _, lockName in ipairs({"Lock", "Locked", "Padlock", "LockIcon", "LockedIcon", "LockOverlay", "LockFrame", "LockedFrame"}) do
              local lockIcon = desc:FindFirstChild(lockName)
              if lockIcon and lockIcon:IsA("GuiObject") then
                lockIcon.Visible = false
              end
            end

            -- Remove grayed-out overlays & transparencies
            if desc:IsA("ImageButton") or desc:IsA("ImageLabel") then
              pcall(function()
                if desc.ImageTransparency > 0.5 then desc.ImageTransparency = 0 end
              end)
            end
          end
        end
      end
    end)
  end

  function EMOTE_SPOOFER.en()
    if EMOTE_SPOOFER.active then return end
    EMOTE_SPOOFER.active = true
    S.unlockEmotes = true
    EMOTE_SPOOFER.unlockGuiEmotes()

    local pgui = G.LP:FindFirstChildOfClass("PlayerGui")
    if pgui then
      local c = pgui.DescendantAdded:Connect(function(desc)
        if S.unlockEmotes then
          task.defer(EMOTE_SPOOFER.unlockGuiEmotes)
        end
      end)
      table.insert(EMOTE_SPOOFER.conns, c)
    end

    local charAddedConn = G.LP.CharacterAdded:Connect(function()
      if S.unlockEmotes then
        task.wait(0.3)
        EMOTE_SPOOFER.unlockGuiEmotes()
      end
    end)
    table.insert(EMOTE_SPOOFER.conns, charAddedConn)

    pcall(function()
      local chatConn = G.LP.Chatted:Connect(function(msg)
        if not S.unlockEmotes then return end
        local cleanMsg = tostring(msg or ""):lower()
        if cleanMsg:sub(1, 3) == "/e " or cleanMsg:sub(1, 7) == "/emote " then
          local emoteName = cleanMsg:sub(1, 3) == "/e " and msg:sub(4) or msg:sub(8)
          emoteName = emoteName:gsub("%s+", "")
          for realName, _ in pairs(EMOTE_SPOOFER.customEmotes) do
            if realName:lower() == emoteName:lower() then
              EMOTE_SPOOFER.playGesture(realName)
              break
            end
          end
        end
      end)
      table.insert(EMOTE_SPOOFER.conns, chatConn)
    end)

    G.noti("Emotes", "All Emotes & Gestures Unlocked", 2)
  end

  function EMOTE_SPOOFER.dis()
    EMOTE_SPOOFER.active = false
    S.unlockEmotes = false
    for _, c in ipairs(EMOTE_SPOOFER.conns) do
      pcall(function() c:Disconnect() end)
    end
    EMOTE_SPOOFER.conns = {}
    EMOTE_SPOOFER.stopGesture()
    G.noti("Emotes", "Emote Unlocker Disabled", 2)
  end
end

local VENT_PARRY = {
  active = false,
  conns = {},
  parryPending = false,
  lastStandalone = -math.huge,
}

function VENT_PARRY.requestAuxiliaryParry(requestId, cooldown, fallback)
  if AUTO_PARRY.active then
    return AUTO_PARRY.requestParry(requestId)
  end

  local now = os.clock()
  if VENT_PARRY.parryPending or now - VENT_PARRY.lastStandalone < cooldown then
    return false
  end

  VENT_PARRY.parryPending = true
  local called, result = pcall(fallback)
  VENT_PARRY.parryPending = false
  if not called or result == false then return false end

  VENT_PARRY.lastStandalone = now
  return true
end

do
  function VENT_PARRY.en()
    if VENT_PARRY.active then return end
    VENT_PARRY.active = true
    S.vp = true
    
    local lastParry = 0
    local function checkAnimation(character, animTrack)
      if not VENT_PARRY.active or not character then return end
      local myChar = G.LP.Character
      local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
      local enemyRoot = character:FindFirstChild("HumanoidRootPart")
      if not myRoot or not enemyRoot then return end
      
      local dist = (enemyRoot.Position - myRoot.Position).Magnitude
      if dist > 18 then return end
      
      local ventWeight = animTrack.WeightTarget or animTrack.WeightCurrent or 1
      if ventWeight > 1.0 or (animTrack.WeightCurrent and animTrack.WeightCurrent > 1.0) or (animTrack.WeightTarget and animTrack.WeightTarget > 1.0) then
        return
      end
      
      local animId = animTrack.Animation and tostring(animTrack.Animation.AnimationId) or ""
      if not string.find(animId, "9657469282") then return end

      local now = os.clock()
      if now - lastParry < 0.4 then return end

      local parried = VENT_PARRY.requestAuxiliaryParry("VentParry", 0.4, function()
        local remote = G.RS:FindFirstChild("Remotes") and G.RS.Remotes:FindFirstChild("Parry")
        if remote then
          remote:FireServer()
        else
          G.pressKey(Enum.KeyCode.F)
        end
        return true
      end)
      if parried then lastParry = now end
    end

    local function hookModel(m)
      if not m or m == G.LP.Character or not m:IsA("Model") then return end
      if G.Plrs:GetPlayerFromCharacter(m) or (m:FindFirstChildOfClass("Humanoid") and m:FindFirstChild("HumanoidRootPart")) then
        local hum = m:FindFirstChildOfClass("Humanoid")
        local ani = hum and (hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 2))
        if ani then
          local c = ani.AnimationPlayed:Connect(function(track)
            checkAnimation(m, track)
          end)
          table.insert(VENT_PARRY.conns, c)
        end
      end
    end

    local live = G.WS:FindFirstChild("Live") or G.WS
    for _, v in ipairs(live:GetChildren()) do hookModel(v) end
    local cAdd = live.ChildAdded:Connect(function(ch)
      task.wait(0.2)
      hookModel(ch)
    end)
    table.insert(VENT_PARRY.conns, cAdd)
  end

  function VENT_PARRY.dis()
    VENT_PARRY.active = false
    S.vp = false
    for _, c in ipairs(VENT_PARRY.conns) do
      pcall(function() c:Disconnect() end)
    end
    VENT_PARRY.conns = {}
  end
end

local NOVIS = {conn=nil, conn2=nil, conn3=nil, childConn=nil, origFogEnd=nil, origFogStart=nil, origDensity=nil, origShadows=nil, _applying=false}
do
  local L = game:GetService("Lighting")
  local function applyNoFog()
    if not S.noVis then return end
    if NOVIS._applying then return end
    NOVIS._applying = true
    pcall(function()
      L.FogStart = 9e9
      L.FogEnd = 9e9
      L.GlobalShadows = false
      local at2 = L:FindFirstChildOfClass("Atmosphere")
      if at2 then at2.Density = 0 end
      local gb = L:FindFirstChild("GenericBlur")
      if gb then gb.Enabled = false end
      local ub = L:FindFirstChild("UnderwaterBlur")
      if ub then ub.Enabled = false end
    end)
    NOVIS._applying = false
  end
  function NOVIS.en()
    if NOVIS.conn then return end
    NOVIS.origFogEnd = L.FogEnd
    NOVIS.origFogStart = L.FogStart
    NOVIS.origShadows = L.GlobalShadows
    local at = L:FindFirstChildOfClass("Atmosphere")
    if at then NOVIS.origDensity = at.Density end
    applyNoFog()
    NOVIS.conn = L:GetPropertyChangedSignal("FogEnd"):Connect(function()
      if not NOVIS._applying then applyNoFog() end
    end)
    NOVIS.conn2 = L:GetPropertyChangedSignal("FogStart"):Connect(function()
      if not NOVIS._applying then applyNoFog() end
    end)
    NOVIS.conn3 = L:GetPropertyChangedSignal("GlobalShadows"):Connect(function()
      if not NOVIS._applying then applyNoFog() end
    end)
    NOVIS.childConn = L.ChildAdded:Connect(function(child)
      if child:IsA("Atmosphere") or child.Name == "GenericBlur" or child.Name == "UnderwaterBlur" then
        task.defer(applyNoFog)
      end
    end)
  end
  function NOVIS.dis()
    if NOVIS.conn then pcall(function() NOVIS.conn:Disconnect() end); NOVIS.conn=nil end
    if NOVIS.conn2 then pcall(function() NOVIS.conn2:Disconnect() end); NOVIS.conn2=nil end
    if NOVIS.conn3 then pcall(function() NOVIS.conn3:Disconnect() end); NOVIS.conn3=nil end
    if NOVIS.childConn then pcall(function() NOVIS.childConn:Disconnect() end); NOVIS.childConn=nil end
    pcall(function()
      if NOVIS.origFogEnd then L.FogEnd = NOVIS.origFogEnd end
      if NOVIS.origFogStart then L.FogStart = NOVIS.origFogStart end
      if NOVIS.origShadows ~= nil then L.GlobalShadows = NOVIS.origShadows end
      local at = L:FindFirstChildOfClass("Atmosphere")
      if at and NOVIS.origDensity ~= nil then at.Density = NOVIS.origDensity end
    end)
  end
end

local OPTIMIZE = {active=false, conn=nil, conn2=nil, conn3=nil}
do
  local function nukeEngineSettings()
    pcall(function()
      if type(setfpscap) == "function" then
        setfpscap(9999)
      end
    end)
    pcall(function()
      local rend = settings():GetService("RenderSettings") or settings().Rendering
      if rend then
        rend.QualityLevel = Enum.QualityLevel.Level01
        rend.MeshPartDetailLevel = Enum.MeshPartDetailLevel.Level01
        rend.EditQualityLevel = Enum.QualityLevel.Level01
      end
    end)
    pcall(function()
      local L = game:GetService("Lighting")
      if sethiddenproperty then
        pcall(sethiddenproperty, L, "Technology", Enum.Technology.Compatibility)
      end
    end)
  end

  local function nukeLighting()
    pcall(function()
      local L = game:GetService("Lighting")
      L.GlobalShadows = false
      L.Brightness = 2
      L.FogEnd = 9e9
      L.FogStart = 9e9
      L.ClockTime = 14
      L.EnvironmentDiffuseScale = 0
      L.EnvironmentSpecularScale = 0
      L.OutdoorAmbient = Color3.fromRGB(128, 128, 128)
      L.Ambient = Color3.fromRGB(128, 128, 128)

      for _, v in ipairs(L:GetDescendants()) do
        if v:IsA("PostEffect") or v:IsA("BlurEffect") or v:IsA("SunRaysEffect") or v:IsA("ColorCorrectionEffect")
          or v:IsA("BloomEffect") or v:IsA("DepthOfFieldEffect") or v:IsA("Atmosphere") or v:IsA("Clouds") or v:IsA("Sky") then
          pcall(function()
            v.Enabled = false
            v:Destroy()
          end)
        end
      end

      local T = game.Workspace:FindFirstChildOfClass("Terrain")
      if T then
        T.WaterWaveSize = 0
        T.WaterWaveSpeed = 0
        T.WaterReflectance = 0
        T.WaterTransparency = 1
        T.Decoration = false
        if sethiddenproperty then
          pcall(sethiddenproperty, T, "GrassLength", 0)
          pcall(sethiddenproperty, T, "Decoration", false)
        end
      end
    end)
  end

  local function optimizeObj(v)
    if not OPTIMIZE.active then return end
    pcall(function()
      if v:IsA("BasePart") and not v:IsA("Terrain") then
        v.CastShadow = false
        if v.Material ~= Enum.Material.SmoothPlastic then
          v.Material = Enum.Material.SmoothPlastic
        end
        if v.Reflectance ~= 0 then
          v.Reflectance = 0
        end
      elseif v:IsA("Decal") or v:IsA("Texture") then
        v:Destroy()
      elseif v:IsA("ParticleEmitter") then
        v.Enabled = false
        v.Rate = 0
        v:Destroy()
      elseif v:IsA("Trail") or v:IsA("Beam") then
        v.Enabled = false
        v:Destroy()
      elseif v:IsA("Fire") or v:IsA("Smoke") or v:IsA("Sparkles") then
        v.Enabled = false
        v:Destroy()
      elseif v:IsA("Highlight") then
        if not v.Name:find("ESP") and not v.Name:find("Katalyst") then
          v.Enabled = false
          v:Destroy()
        end
      elseif v:IsA("Explosion") then
        v.Visible = false
        v:Destroy()
      elseif v:IsA("PointLight") or v:IsA("SpotLight") or v:IsA("SurfaceLight") then
        v.Enabled = false
        v.Shadows = false
        v:Destroy()
      elseif v:IsA("PostEffect") or v:IsA("BlurEffect") or v:IsA("BloomEffect") or v:IsA("DepthOfFieldEffect") or v:IsA("SunRaysEffect") or v:IsA("ColorCorrectionEffect") or v:IsA("Atmosphere") or v:IsA("Clouds") or v:IsA("Sky") then
        v.Enabled = false
        v:Destroy()
      elseif v:IsA("Sound") then
        local sName = string.lower(v.Name)
        if sName:find("ambient") or sName:find("wind") or sName:find("ocean") or sName:find("water") or sName:find("rain") then
          v.Volume = 0
          v:Stop()
        end
      end
    end)
  end

  local function nukeEffects(root)
    local count = 0
    for _, v in ipairs(root:GetDescendants()) do
      if not OPTIMIZE.active then break end
      optimizeObj(v)
      count = count + 1
      if count % 600 == 0 then task.wait() end
    end
  end

  function OPTIMIZE.en()
    if OPTIMIZE.active then return end
    OPTIMIZE.active = true

    nukeEngineSettings()
    nukeLighting()

    task.spawn(function() nukeEffects(game.Workspace) end)
    task.spawn(function() pcall(function() nukeEffects(game:GetService("Lighting")) end) end)
    task.spawn(function() pcall(function() nukeEffects(game:GetService("ReplicatedStorage")) end) end)

    OPTIMIZE.conn = game.Workspace.DescendantAdded:Connect(optimizeObj)
    OPTIMIZE.conn2 = game:GetService("Lighting").ChildAdded:Connect(optimizeObj)
    OPTIMIZE.conn3 = game:GetService("Lighting").DescendantAdded:Connect(optimizeObj)

    G.noti("Super Optimizer", "EXTREME MODE ACTIVE - Max FPS & Zero Latency", 3)
  end

  function OPTIMIZE.dis()
    if not OPTIMIZE.active then return end
    OPTIMIZE.active = false

    if OPTIMIZE.conn then
      OPTIMIZE.conn:Disconnect()
      OPTIMIZE.conn = nil
    end
    if OPTIMIZE.conn2 then
      OPTIMIZE.conn2:Disconnect()
      OPTIMIZE.conn2 = nil
    end
    if OPTIMIZE.conn3 then
      OPTIMIZE.conn3:Disconnect()
      OPTIMIZE.conn3 = nil
    end

    G.noti("Super Optimizer", "Super Optimizer Disabled", 2)
  end
end

