    autoIntelligence = "Auto Intelligence",
    autoArdour = "Auto Ardour",
    autoWisp = "Auto Wisp",
    autoGoldenTongue = "Auto Golden Tongue",
    bankai = "Bankai",
    combatStance = "Combat Stance",
    weaponVfx = "Weapon VFX",
    combatSfx = "Combat SFX"
  }

  local function formatKeyName(kcName)
    if not kcName then return "" end
    if kcName == "LeftShift" then return "LSh"
    elseif kcName == "RightShift" then return "RSh"
    elseif kcName == "LeftControl" then return "LCtrl"
    elseif kcName == "RightControl" then return "RCtrl"
    elseif kcName == "LeftAlt" then return "LAlt"
    elseif kcName == "RightAlt" then return "RAlt"
    end
    return kcName
  end

  function KEYBINDS_HUD.update()
    if not KEYBINDS_HUD.listFrame or not KEYBINDS_HUD.frame then return end
    for _, child in ipairs(KEYBINDS_HUD.listFrame:GetChildren()) do
      if child:IsA("TextLabel") then child:Destroy() end
    end

    -- Collect all active (ON) features and bound keybind features
    local displayList = {}
    local seen = {}
    
    for fKey, fName in pairs(featureNames) do
      if fKey ~= "menuKey" and fKey ~= "keybindsHud" then
        local isOn = (S[fKey] == true)
        local kcObj = kb[fKey]
        if isOn or kcObj then
          seen[fKey] = true
          local kName = kcObj and formatKeyName(kcObj.Name) or "None"
          table.insert(displayList, {
            fKey = fKey,
            fName = fName,
            kName = kName,
            isOn = isOn
          })
        end
      end
    end

    for fKey, val in pairs(S) do
      if val == true and fKey ~= "menu" and fKey ~= "keybindsHud" and not seen[fKey] then
        local kcObj = kb[fKey]
        local kName = kcObj and formatKeyName(kcObj.Name) or "None"
        table.insert(displayList, {
          fKey = fKey,
          fName = fKey,
          kName = kName,
          isOn = true
        })
      end
    end

    -- Sort: Active/ON (Green) first, then OFF (Red)
    table.sort(displayList, function(a, b)
      if a.isOn ~= b.isOn then
        return a.isOn
      end
      return a.fName < b.fName
    end)

    local count = 0
    for _, item in ipairs(displayList) do
      local lb = G.new("TextLabel", KEYBINDS_HUD.listFrame)
      lb.Size = G.UD2(1, 0, 0, 18)
      lb.Position = G.UD2(0, 0, 0, count * 18)
      lb.BackgroundTransparency = 1
      lb.Font = Enum.Font.GothamBold
      lb.TextSize = 11
      lb.TextXAlignment = Enum.TextXAlignment.Left
      lb.TextColor3 = item.isOn and G.RGB(100, 255, 120) or G.RGB(255, 90, 90)
      lb.Text = string.format("[%s]: %s", item.kName, item.fName)
      count = count + 1
    end

    local contentH = math.max(30, count * 18 + 8)
    KEYBINDS_HUD.frame.Size = G.UD2(0, 175, 0, contentH + 32)
  end

  function KEYBINDS_HUD.en()
    if KEYBINDS_HUD.gui then return end
    local sg = G.new("ScreenGui")
    sg.Name = UC.RN .. "_KEYBINDS"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 150
    sg:SetAttribute("KI", true)
    G.protG(sg)
    sg.Parent = G.getHP()
    KEYBINDS_HUD.gui = sg

    local f = G.new("Frame", sg)
    f.Size = G.UD2(0, 170, 0, 100)
    f.Position = G.UD2(0, 20, 0.4, 0)
    f.BackgroundColor3 = G.RGB(24, 32, 40)
    f.BackgroundTransparency = 0.25
    f.BorderSizePixel = 0
    G.mkC(f, 8)
    G.mkS(f, G.RGB(70, 90, 110), 0.6, 0.5)
    KEYBINDS_HUD.frame = f
    G.makeDraggable(f)

    local header = G.new("TextLabel", f)
    header.Size = G.UD2(1, 0, 0, 26)
    header.Position = G.UD2(0, 0, 0, 2)
    header.BackgroundTransparency = 1
    header.Font = Enum.Font.GothamBold
    header.TextSize = 13
    header.TextColor3 = G.RGB(230, 230, 245)
    header.Text = "Keybinds"

    local divider = G.new("Frame", f)
    divider.Size = G.UD2(1, -20, 0, 1)
    divider.Position = G.UD2(0, 10, 0, 28)
    divider.BackgroundColor3 = G.RGB(60, 80, 100)
    divider.BorderSizePixel = 0

    local lf = G.new("Frame", f)
    lf.Size = G.UD2(1, -20, 1, -34)
    lf.Position = G.UD2(0, 10, 0, 32)
    lf.BackgroundTransparency = 1
    lf.BorderSizePixel = 0
    KEYBINDS_HUD.listFrame = lf

    KEYBINDS_HUD.update()
  end

  function KEYBINDS_HUD.dis()
    if KEYBINDS_HUD.gui then
      pcall(function() KEYBINDS_HUD.gui:Destroy() end)
      KEYBINDS_HUD.gui = nil
      KEYBINDS_HUD.frame = nil
      KEYBINDS_HUD.listFrame = nil
    end
  end
end

local PING_HUD = {gui=nil, lbl=nil, conn=nil}
do
  function PING_HUD.en()
    if PING_HUD.gui then return end
    local sg = G.new("ScreenGui"); sg.Name=UC.RN.."_PING"
    sg.ResetOnSpawn=false; sg.IgnoreGuiInset=true; sg.DisplayOrder=150
    sg:SetAttribute("KI",true); G.protG(sg); sg.Parent=G.getHP()
    PING_HUD.gui = sg
    local f = G.new("Frame", sg); f.Size=G.UD2(0,130,0,36); f.Position=G.UD2(1,-140,0,10)
    f.BackgroundColor3=G.RGB(10,8,20); f.BackgroundTransparency=0.3; f.BorderSizePixel=0; G.mkC(f,6)
    G.mkS(f,G.RGB(80,60,140),0.6,0.5)
    local lb = G.new("TextLabel", f); lb.Size=G.UD2(1,-10,1,0); lb.Position=G.UD2(0,5,0,0)
    lb.BackgroundTransparency=1; lb.Font=Enum.Font.Code; lb.TextSize=11
    lb.TextColor3=G.RGB(200,255,200); lb.TextXAlignment=Enum.TextXAlignment.Left; lb.Text="FPS: -- | Ping: --"
    PING_HUD.lbl = lb
    local frameCount, lastTime = 0, G.ck()
    local curFps = 0
    PING_HUD.conn = G.RS.Heartbeat:Connect(function()
      frameCount = frameCount + 1
      local now = G.ck()
      if now - lastTime >= 1.0 then
        curFps = frameCount
        frameCount = 0
        lastTime = now
      end
      if frameCount % 15 == 0 then
        local ping = "--"
        pcall(function()
          local stats = game:GetService("Stats")
          local ns = stats:FindFirstChild("Network")
          if ns then
            local si = ns:FindFirstChild("ServerStatsItem")
            if si then
              local dp = si:FindFirstChild("Data Ping")
              if dp then ping = tostring(math.floor(dp:GetValue())) end
            end
          end
        end)
        if ping == "--" then
          pcall(function()
            ping = tostring(math.floor(G.LP:GetNetworkPing() * 1000))
          end)
        end
        if PING_HUD.lbl then
          PING_HUD.lbl.Text = "FPS: " .. curFps .. " | Ping: " .. ping .. "ms"
        end
      end
    end)
  end
  function PING_HUD.dis()
    if PING_HUD.conn then PING_HUD.conn:Disconnect(); PING_HUD.conn=nil end
    if PING_HUD.gui then PING_HUD.gui:Destroy(); PING_HUD.gui=nil end
    PING_HUD.lbl = nil
  end
end

local HITBOX = {boxes = {}, origSizes = {}}
do
  function HITBOX.en()
    HITBOX.dis()
    local val = CFG.HbxVal or 15
    local mult = val / 10
    for _,p in ipairs(G.Plrs:GetPlayers()) do
      if p ~= G.LP and p.Character then
        for _,part in ipairs(p.Character:GetDescendants()) do
          if part:IsA("BasePart") and not part.Parent:IsA("Accessory") then
            pcall(function()
              if not HITBOX.origSizes[part] then
                HITBOX.origSizes[part] = part.Size
              end
              part.Size = HITBOX.origSizes[part] * mult
              local sb = Instance.new("SelectionBox")
              sb.Adornee = part
              sb.Color3 = Color3.fromRGB(255, 0, 100)
              sb.LineThickness = 0.02
              sb.Transparency = 0.4
              sb.Parent = part
              table.insert(HITBOX.boxes, sb)
            end)
          end
        end
      end
    end
  end
  function HITBOX.dis()
    for _,box in ipairs(HITBOX.boxes) do
      pcall(function() box:Destroy() end)
    end
    table.clear(HITBOX.boxes)
    for part,size in pairs(HITBOX.origSizes) do
      pcall(function()
        if part and part.Parent then
          part.Size = size
        end
      end)
    end
    table.clear(HITBOX.origSizes)
  end
end

local PERF = {
  focusConn1 = nil,
  focusConn2 = nil,
  origMaterials = {},
  potatoActive = false,
  savedFps = 60
}

function PERF.setResolutionScale(pct)
  CFG.ResolutionScale = math.clamp(pct, 10, 100)
  pcall(function()
    local settings = UserSettings():GetService("UserGameSettings")
    local level = math.clamp(math.floor((CFG.ResolutionScale / 100) * 10), 1, 10)
    settings.SavedQualityLevel = Enum.SavedQualitySetting["QualityLevel" .. tostring(level)]
  end)
  pcall(function()
    local rend = settings():GetService("RenderSettings")
    if rend then
      local lvl = math.clamp(math.floor((CFG.ResolutionScale / 100) * 21), 1, 21)
      rend.QualityLevel = Enum.QualityLevel["Level" .. string.format("%02d", lvl)]
    end
  end)
  G.saveConfig()
end

function PERF.enablePotatoGraphics()
  if PERF.potatoActive then return end
  PERF.potatoActive = true
  
  pcall(function()
    workspace.Terrain.Decoration = false
    game:GetService("Lighting").GlobalShadows = false
    game:GetService("Lighting").FogEnd = 9e9
  end)

  pcall(function()
    for _, v in ipairs(workspace:GetDescendants()) do
      if v:IsA("BasePart") and not v:IsA("Terrain") then
        if not PERF.origMaterials[v] then
          PERF.origMaterials[v] = {mat = v.Material, refl = v.Reflectance}
        end
        v.Material = Enum.Material.SmoothPlastic
        v.Reflectance = 0
      elseif v:IsA("Decal") or v:IsA("Texture") then
        v.Transparency = 1
      elseif v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Smoke") or v:IsA("Fire") or v:IsA("Sparkles") then
        v.Enabled = false
      end
    end
  end)
  G.noti("Performance", "Potato Graphics Active (Smooth Plastic & Max FPS)")
end

function PERF.disablePotatoGraphics()
  if not PERF.potatoActive then return end
  PERF.potatoActive = false
  
  pcall(function()
    for part, data in pairs(PERF.origMaterials) do
      if part and part.Parent then
        part.Material = data.mat
        part.Reflectance = data.refl
      end
    end
  end)
  table.clear(PERF.origMaterials)
  G.noti("Performance", "Potato Graphics Disabled")
end

function PERF.enableFocusSaver()
  if PERF.focusConn1 then return end
  local uis = game:GetService("UserInputService")
  
  PERF.focusConn1 = uis.WindowFocusReleased:Connect(function()
    if S.focusSaver then
      PERF.savedFps = CFG.FpsVal or 60
      if type(setfpscap) == "function" then setfpscap(10) end
    end
  end)
  
  PERF.focusConn2 = uis.WindowFocused:Connect(function()
    if S.focusSaver then
      if type(setfpscap) == "function" then setfpscap(S.fps and CFG.FpsVal or 9999) end
    end
  end)
end

function PERF.disableFocusSaver()
  if PERF.focusConn1 then PERF.focusConn1:Disconnect(); PERF.focusConn1 = nil end
  if PERF.focusConn2 then PERF.focusConn2:Disconnect(); PERF.focusConn2 = nil end
end

function PERF.purgeMemory()
  pcall(function() collectgarbage("collect") end)
  local gcKb = math.floor(gcinfo())
  G.noti("Memory Purge", string.format("RAM Cleared! Current Memory: %d KB", gcKb))
end
local ASPD = {conn=nil,cc=nil}
do
  function ASPD.en()
    if ASPD.conn then return end
    local function hook(ch)
      if ASPD.conn then ASPD.conn:Disconnect(); ASPD.conn=nil end
      if not ch then return end
      local hum=ch:FindFirstChildOfClass("Humanoid"); if not hum then return end
      local ani=hum:FindFirstChildOfClass("Animator"); if not ani then return end
      ASPD.conn=ani.AnimationPlayed:Connect(function(track)
        if not S.aSpd then return end
        local pr = track.Priority
        if pr==Enum.AnimationPriority.Action or pr==Enum.AnimationPriority.Movement then
          local spd=CFG.ASpdVal or 1.5; pcall(function() track:AdjustSpeed(spd) end)
        elseif S.mSpd and (pr==Enum.AnimationPriority.Action2 or pr==Enum.AnimationPriority.Action3 or pr==Enum.AnimationPriority.Action4) then
          local spd=CFG.MSpdVal or 1.5; pcall(function() track:AdjustSpeed(spd) end)
        end
      end)
    end
    hook(G.LP and G.LP.Character)
    if not ASPD.cc then ASPD.cc=G.LP.CharacterAdded:Connect(function(ch) G.tw(0.3); if S.aSpd then hook(ch) end end) end
  end
  function ASPD.dis()
    if ASPD.conn then ASPD.conn:Disconnect(); ASPD.conn=nil end
    if ASPD.cc then ASPD.cc:Disconnect(); ASPD.cc=nil end
  end
end
PC = {cache={},conns={},addC=nil,remC=nil}
do
  function PC.add(p)
    if p == G.LP then return end
    local cs = {}
    PC.conns[p] = cs
    
    local function oc(ch)
      if not ch then PC.cache[p] = nil; return end
      local r = ch:FindFirstChild("HumanoidRootPart") or ch.PrimaryPart
      local h = ch:FindFirstChildOfClass("Humanoid")
      if r and h then
        PC.cache[p] = {R = r, H = h, Char = ch}
      else
        G.ts(function()
          local r2 = ch:WaitForChild("HumanoidRootPart", 5) or ch.PrimaryPart
          local h2 = ch:WaitForChild("Humanoid", 5)
          if r2 and h2 and ch.Parent then
            PC.cache[p] = {R = r2, H = h2, Char = ch}
          end
        end)
      end
    end
    
    G.ti(cs, p.CharacterAdded:Connect(oc))
    G.ti(cs, p.CharacterRemoving:Connect(function() PC.cache[p] = nil end))
    
    local live = G.WS:FindFirstChild("Live") or G.WS
    local char = p.Character or live:FindFirstChild(p.Name)
    if char then oc(char) end
  end

  function PC.init()
    PC.stop()
    
    PC.addC = G.Plrs.PlayerAdded:Connect(function(p)
      PC.add(p)
    end)
    
    PC.remC = G.Plrs.PlayerRemoving:Connect(function(p)
      local cs = PC.conns[p]
      if cs then for _, c in ipairs(cs) do c:Disconnect() end; PC.conns[p] = nil end
      PC.cache[p] = nil
      if UI.espF then
        local d = UI.espF[p]
        if d then
          pcall(function() d.Ct:Destroy() end)
          if d.Tracer then pcall(function() d.Tracer:Destroy() end) end
          if d.Lines3D then for l = 1, 12 do pcall(function() d.Lines3D[l]:Destroy() end) end end
          UI.espF[p] = nil
        end
      end
    end)
    
    for _, p in ipairs(G.Plrs:GetPlayers()) do PC.add(p) end
  end

  function PC.stop()
    if PC.addC then
      pcall(function() PC.addC:Disconnect() end)
      PC.addC = nil
    end
    if PC.remC then
      pcall(function() PC.remC:Disconnect() end)
      PC.remC = nil
    end
    for _, connections in pairs(PC.conns) do
      for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
      end
    end
    G.tc(PC.conns)
    G.tc(PC.cache)
  end
end

