  iconBox.BorderColor3 = G.RGB(55, 45, 75)
  G.mkC(iconBox, 4)

  local iconTxt = G.new("TextLabel", iconBox)
  iconTxt.Size = G.UD2(1, 0, 1, 0)
  iconTxt.BackgroundTransparency = 1
  iconTxt.Font = Enum.Font.GothamBold
  iconTxt.TextSize = 10
  iconTxt.TextColor3 = G.RGB(210, 130, 255)
  iconTxt.Text = ""

  local lastBarScan = 0
  local cachedTargetPos, cachedTargetSize = nil, nil

  SANITY_TRACKER.conn = G.RS.Heartbeat:Connect(function()
    if S.sanityTracker == false then
      outer.Visible = false
      return
    end
    outer.Visible = true

    -- Cache in-game Deepwoken stat bar positions every 1.5s instead of scanning descendants 240x/sec
    local now = os.clock()
    if now - lastBarScan > 1.5 or not cachedTargetPos then
      lastBarScan = now
      pcall(function()
        local pg = G.LP:FindFirstChildOfClass("PlayerGui")
        if pg then
          local statGui = pg:FindFirstChild("Stats") or pg:FindFirstChild("Bars") or pg:FindFirstChild("HUD") or pg:FindFirstChild("StatBars")
          if statGui then
            local bars = {}
            for _, v in ipairs(statGui:GetDescendants()) do
              if v:IsA("Frame") and v.AbsoluteSize.Y > 100 and v.AbsoluteSize.X < 30 then
                table.insert(bars, v)
              end
            end
            table.sort(bars, function(a, b) return a.AbsolutePosition.X < b.AbsolutePosition.X end)
            if #bars >= 3 then
              local b3 = bars[3]
              local b2 = bars[2]
              local gap = b3.AbsolutePosition.X - b2.AbsolutePosition.X
              local targetX = b3.AbsolutePosition.X + gap
              cachedTargetPos = G.UD2(0, targetX, 0, b3.AbsolutePosition.Y)
              cachedTargetSize = G.UD2(0, b3.AbsoluteSize.X, 0, b3.AbsoluteSize.Y)
            end
          end
        end
      end)
    end

    if cachedTargetPos and cachedTargetSize then
      outer.Position = cachedTargetPos
      outer.Size = cachedTargetSize
    end

    local sanityVal = 100
    pcall(function()
      local lp = G.LP
      local char = lp and lp.Character
      if char then
        local sObj = char:FindFirstChild("Sanity") or char:FindFirstChild("sanity")
        if sObj then
          if type(sObj) == "number" then
            sanityVal = sObj
          else
            local val = rawget(sObj, "Value") or sObj.Value
            if val then sanityVal = tonumber(val) or 100 end
          end
        end
      end
    end)

    local insanityVal = G.mc(100 - sanityVal, 0, 100)
    local fillPct = insanityVal / 100
    fill.Size = G.UD2(1, 0, fillPct, 0)
    fill.Position = G.UD2(0, 0, 1 - fillPct, 0)
  end)
end

function SANITY_TRACKER.stop()
  if SANITY_TRACKER.conn then SANITY_TRACKER.conn:Disconnect(); SANITY_TRACKER.conn = nil end
  if SANITY_TRACKER.gui then SANITY_TRACKER.gui:Destroy(); SANITY_TRACKER.gui = nil end
end

local ANTI_ESP = { conn = nil, active = false, lastRun = 0 }
function ANTI_ESP.start()
  if ANTI_ESP.conn then return end
  ANTI_ESP.active = true
  ANTI_ESP.conn = G.RS.Heartbeat:Connect(function()
    if not S.antiEsp then return end
    local now = os.clock()
    if now - ANTI_ESP.lastRun < 0.1 then return end
    ANTI_ESP.lastRun = now
    pcall(function()
      local char = G.LP and G.LP.Character
      if char then
        for _, obj in ipairs(char:GetDescendants()) do
          if obj:IsA("Highlight") or obj:IsA("SelectionBox") or obj:IsA("BoxHandleAdornment") or obj:IsA("LineHandleAdornment") or obj:IsA("CylinderHandleAdornment") or obj:IsA("SphereHandleAdornment") then
            if obj.Name ~= "KatalystChams" then
              pcall(function() obj:Destroy() end)
            end
          end
        end
        for _, child in ipairs(char:GetChildren()) do
          if child:IsA("BillboardGui") and child.Name ~= "DisplayHeader" and child.Name ~= "Nametag" then
            pcall(function() child:Destroy() end)
          end
        end
        local head = char:FindFirstChild("Head")
        if head then
          for _, obj in ipairs(head:GetChildren()) do
            if obj:IsA("BillboardGui") and obj.Name ~= "DisplayHeader" and obj.Name ~= "Nametag" then
              pcall(function() obj:Destroy() end)
            end
          end
        end
      end
    end)
  end)
end

function ANTI_ESP.stop()
  ANTI_ESP.active = false
  if ANTI_ESP.conn then
    pcall(function() ANTI_ESP.conn:Disconnect() end)
    ANTI_ESP.conn = nil
  end
end

