-- You can easily copy/paste or add your game's exact attribute names below!
  -- DEEPWOKEN BREAKMETER POSTURE EXTRACTOR
  local function getEntityPosture(char, player)
    if not char then return 0, false, 0, 100 end
    
    local bm = char:FindFirstChild("BreakMeter") or char:FindFirstChild("Posture") or (char:FindFirstChild("Values") and char.Values:FindFirstChild("BreakMeter"))
    if bm and (bm:IsA("DoubleConstrainedValue") or bm:IsA("NumberValue") or bm:IsA("IntValue")) then
      local cur = tonumber(bm.Value) or 0
      local maxV = tonumber(bm.MaxValue) or 100
      local minV = tonumber(bm.MinValue) or 0
      local range = math.max(1, maxV - minV)
      local pct = math.clamp((cur - minV) / range, 0, 1)
      local isBroken = pct >= 0.98 or (char:GetAttribute("PostureBreak") == true) or (char:GetAttribute("PostureBroken") == true)
      return pct, isBroken, cur, maxV
    end

    local attrBreak = char:GetAttribute("BreakMeter") or char:GetAttribute("Posture") or char:GetAttribute("CurrentPosture")
    if attrBreak and type(attrBreak) == "number" then
      local maxAttr = char:GetAttribute("MaxPosture") or char:GetAttribute("MaxBreakMeter") or 100
      local pct = math.clamp(attrBreak / math.max(1, maxAttr), 0, 1)
      local isBroken = pct >= 0.98 or (char:GetAttribute("PostureBreak") == true)
      return pct, isBroken, attrBreak, maxAttr
    end

    if player == G.LP then
      local pgui = G.LP:FindFirstChild("PlayerGui")
      local statsGui = pgui and pgui:FindFirstChild("StatsGui")
      local postureFrame = statsGui and statsGui:FindFirstChild("Posture")
      if postureFrame and postureFrame:IsA("GuiObject") then
        local sz = postureFrame.Size
        local pct = math.clamp(sz.X.Scale > 0 and sz.X.Scale or sz.Y.Scale, 0, 1)
        return pct, pct >= 0.98, pct * 100, 100
      end
    end

    return 0, false, 0, 100
  end

