  local function draw2DLine(lineFrame, p1, p2, thickness, color)
    local dx = p2.X - p1.X
    local dy = p2.Y - p1.Y
    local len = math.sqrt(dx * dx + dy * dy)
    local angle = math.atan2(dy, dx)

    lineFrame.Size = UDim2.new(0, len, 0, thickness or 1.5)
    lineFrame.Position = UDim2.new(0, (p1.X + p2.X) * 0.5, 0, (p1.Y + p2.Y) * 0.5)
    lineFrame.Rotation = math.deg(angle)
    lineFrame.BackgroundColor3 = color or G.RGB(0, 255, 255)
    lineFrame.Visible = true
  end

  local function update3DBox(linesTable, cf, size, cam, color, thickness)
    local sx, sy, sz = size.X * 0.5, size.Y * 0.5, size.Z * 0.5
    local corners3D = {
      cf * CFrame.new(-sx, sy, -sz),
      cf * CFrame.new( sx, sy, -sz),
      cf * CFrame.new( sx, -sy, -sz),
      cf * CFrame.new(-sx, -sy, -sz),
      cf * CFrame.new(-sx, sy, sz),
      cf * CFrame.new( sx, sy, sz),
      cf * CFrame.new( sx, -sy, sz),
      cf * CFrame.new(-sx, -sy, sz),
    }

    local pts2D = {}
    for i = 1, 8 do
      local pos, onScreen = cam:WorldToViewportPoint(corners3D[i].Position)
      if not onScreen or pos.Z <= 0 then
        for l = 1, 12 do linesTable[l].Visible = false end
        return
      end
      pts2D[i] = pos
    end

    local edges = {
      {1,2}, {2,3}, {3,4}, {4,1},
      {5,6}, {6,7}, {7,8}, {8,5},
      {1,5}, {2,6}, {3,7}, {4,8}
    }

    for idx, edge in ipairs(edges) do
      draw2DLine(linesTable[idx], pts2D[edge[1]], pts2D[edge[2]], thickness or 1.5, color)
    end
  end

  local function updateChams(p, char, enable)
    if not enable then
      if ESP.chamsCache[p] then
        pcall(function() ESP.chamsCache[p]:Destroy() end)
        ESP.chamsCache[p] = nil
      end
      return
    end

    if not ESP.chamsCache[p] or not ESP.chamsCache[p].Parent then
      pcall(function()
        local hl = Instance.new("Highlight")
        hl.Name = "KatalystChams"
        hl.FillColor = CFG.EspChamsFill or G.RGB(255, 0, 100)
        hl.FillTransparency = 0.5
        hl.OutlineColor = CFG.EspChamsOutline or G.RGB(255, 255, 255)
        hl.OutlineTransparency = 0
        hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
        hl.Adornee = char
        hl.Parent = char
        ESP.chamsCache[p] = hl
      end)
    end
  end

  function ESP.clr()
