      updateChams(p, nil, false)
    end
    G.tc(UI.espF)
    if ESP.gui then ESP.gui:Destroy(); ESP.gui = nil end
  end

  -- Robust Power/Level & Slot Name Scanners
local _slotCache = {}
local _lvlCache = {}

local function getPowerLvl(p, char)
  local cached = _lvlCache[p]
  local now = os.clock()
  if cached and (now - cached.t < 1.5) then return cached.v end
  local lv = nil
  pcall(function()
    if p then
      lv = p:GetAttribute("Power") or p:GetAttribute("Level")
      if not lv and p:FindFirstChild("leaderstats") then
        local ls = p.leaderstats
        local l = ls:FindFirstChild("Power") or ls:FindFirstChild("Level")
        if l then lv = l.Value end
      end
    end
    if not lv and char then
      lv = char:GetAttribute("Power") or char:GetAttribute("Level")
      if not lv then
        local l = char:FindFirstChild("Power") or char:FindFirstChild("Level")
        if l then lv = (type(l.Value) == "number" and l.Value) or l end
      end
    end
  end)
  local res = lv or "?"
  _lvlCache[p] = { v = res, t = now }
  return res
end

local function getSlotName(p, char)
  local cached = _slotCache[p]
  local now = os.clock()
  if cached and (now - cached.t < 1.5) then return cached.v end
  local sName = nil
  pcall(function()
    if char then
      local fn = char:GetAttribute("FirstName") or (p and p:GetAttribute("FirstName"))
      local ln = char:GetAttribute("LastName") or (p and p:GetAttribute("LastName"))
      if fn and ln then
        sName = tostring(fn) .. " " .. tostring(ln)
      elseif fn then
        sName = tostring(fn)
      else
        sName = char:GetAttribute("SlotName") or char:GetAttribute("CharacterName") or (p and (p:GetAttribute("SlotName") or p:GetAttribute("CharacterName")))
      end
      if not sName then
        local sObj = char:FindFirstChild("SlotName") or char:FindFirstChild("CharacterName") or char:FindFirstChild("FirstName")
        if sObj then sName = tostring(sObj.Value or sObj) end
      end
      if not sName and char:FindFirstChild("Head") then
        for _, b in ipairs(char.Head:GetChildren()) do
          if b:IsA("BillboardGui") then
            for _, t in ipairs(b:GetDescendants()) do
              if t:IsA("TextLabel") and t.Text ~= "" then
                local strVal = tostring(t.Text)
                if not string.find(strVal, "Guild") and not string.find(strVal, "Level") then
                  local cleanStr = string.split(strVal, "[")[1]
                  if cleanStr then cleanStr = string.split(cleanStr, "(")[1] end
                  if cleanStr then cleanStr = string.match(cleanStr, "^%s*(.-)%s*$") end
                  if cleanStr and #cleanStr > 0 and cleanStr ~= p.Name and cleanStr ~= p.DisplayName then
                    sName = cleanStr
                    break
                  end
                end
              end
            end
          end
          if sName then break end
        end
      end
    end
  end)
  local res = (sName and tostring(sName) ~= "" and sName) or (p and (p.DisplayName or p.Name)) or "Player"
  _slotCache[p] = { v = res, t = now }
  return res
end

-- Theoretical PvP Poser's Ring & M1 Damage Calculator
  function ESP.getTheoreticalPvPPoserDamage(displayHits, targetChar)
    local char = G.LP.Character
    if not char then return 0 end
    
    local statVal = char:GetAttribute("Medium Weapon") or char:GetAttribute("Heavy Weapon") or char:GetAttribute("Light Weapon") or 75
    local profVal = char:GetAttribute("Proficiency") or 5
    local wepBase = char:GetAttribute("WeaponBase") or 22
    local scaling = char:GetAttribute("WeaponScaling") or 0.28
    local generalDmgMulti = char:GetAttribute("DamageMultiplier") or 0.15
    
    local profPen = profVal * 2.5
    local armorPen = math.clamp(profPen / 100, 0, 1.0)
    
    local enemyArmor = 0.25
    if targetChar then
      enemyArmor = targetChar:GetAttribute("PhysicalResistance") or targetChar:GetAttribute("Armor") or 0.25
    end
    local effectiveArmor = enemyArmor * (1 - armorPen)
    
    local rawDmg = wepBase + (statVal * scaling) + profPen
    local pvpDmgPerHit = rawDmg * (1 + generalDmgMulti) * (1 - effectiveArmor)
    
    -- Poser's Ring PvP Burst Multiplier (1.25x stored damage in PvP)
    return math.floor(pvpDmgPerHit * displayHits * 1.25)
  end

          local function checkIsAlly(plr, chr)
    if not plr or plr == G.LP then return false end
    -- Manual ally list check
    if S.allies and (S.allies[plr.Name] or S.allies[tostring(plr.UserId)] or (chr and S.allies[chr.Name])) then
      return true
    end

    -- Guild detection helper: checks all known attribute/child patterns
    local function getGuild(player, character)
      local guild = nil
      pcall(function()
        guild = player:GetAttribute("Guild") or player:GetAttribute("GuildName") or player:GetAttribute("guild")
        -- Check character attributes
        if (not guild or tostring(guild) == "") and character then
          guild = character:GetAttribute("Guild") or character:GetAttribute("GuildName") or character:GetAttribute("guild")
        end
        -- Check Data folder (Deepwoken stores some data here)
        if (not guild or tostring(guild) == "") then
          local data = player:FindFirstChild("Data") or (character and character:FindFirstChild("Data"))
          if data then
            guild = data:GetAttribute("Guild") or data:GetAttribute("GuildName")
            if not guild or tostring(guild) == "" then
              local gv = data:FindFirstChild("Guild") or data:FindFirstChild("GuildName")
              if gv and gv:IsA("StringValue") then guild = gv.Value end
            end
          end
        end
        -- Check character children for GuildName StringValue
        if (not guild or tostring(guild) == "") and character then
          local gv = character:FindFirstChild("GuildName") or character:FindFirstChild("Guild")
          if gv and gv:IsA("StringValue") then guild = gv.Value end
        end
      end)
      return (guild and tostring(guild) ~= "") and tostring(guild) or nil
    end

    local myGuild = getGuild(G.LP, G.LP and G.LP.Character) or CFG.GuildName
    if myGuild and myGuild ~= "" then
      local pGuild = getGuild(plr, chr)
      if pGuild and string.lower(pGuild) == string.lower(myGuild) then
        return true
      end
    end
    return false
  end
  function ESP.upd()
    if not S.esp then
      for p, d in pairs(UI.espF) do
        if d.Ct and d.Ct.Visible then d.Ct.Visible = false end
        if d.Lines3D then
          for l = 1, 12 do if d.Lines3D[l] then d.Lines3D[l].Visible = false end end
        end
        if d.Tracer then d.Tracer.Visible = false end
        updateChams(p, nil, false)
      end
      return
    end

    local cam = G.WS.CurrentCamera
    if not cam then return end
    local mr = G.myR()
    if not mr then return end

    local mp = mr.Position
    local rsq = (CFG.EspRange or 4000) * (CFG.EspRange or 4000)
    local hpWidth = CFG.EspHpWidth or 4

    for _, p in ipairs(G.Plrs:GetPlayers()) do
      if p ~= G.LP and not UI.espF[p] then
        UI.mkEF(p)
      end
    end

    for p, ed in pairs(UI.espF) do
      if not p or not p.Parent or p.Parent ~= G.Plrs then
        pcall(function()
          if ed.Ct then ed.Ct:Destroy() end
          if ed.Tracer then ed.Tracer:Destroy() end
          if ed.Lines3D then for l = 1, 12 do if ed.Lines3D[l] then ed.Lines3D[l]:Destroy() end end end
          updateChams(p, nil, false)
        end)
        UI.espF[p] = nil
      else
        local show = false
        local char = p.Character or (G.WS:FindFirstChild("Live") and G.WS.Live:FindFirstChild(p.Name)) or G.WS:FindFirstChild(p.Name)
        local r = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head") or char.PrimaryPart)
        local h = char and char:FindFirstChildOfClass("Humanoid")

        -- Only display if character is alive and in workspace
        if r and h and r.Parent and h.Parent and (tonumber(h.Health) or 0) > 0 then
          local rp = r.Position
          local dx, dy, dz = rp.X - mp.X, rp.Y - mp.Y, rp.Z - mp.Z
          local dsq = dx * dx + dy * dy + dz * dz

          if dsq <= rsq then
            local rs, onScreen = cam:WorldToViewportPoint(rp)
            -- Strictly check onScreen AND rs.Z > 0 (completely prevents drawing behind camera)
            if onScreen and rs.Z > 0 then
              local ts2 = cam:WorldToViewportPoint(rp + UC.ETOP)
              local bs = cam:WorldToViewportPoint(rp - UC.EBOT)
              local sh = math.max(bs.Y - ts2.Y, 14)
              local sw = sh * 0.55
              local cx = (ts2.X + bs.X) * 0.5

              ed.Ct.Position = G.UD2(0, cx - sw * 0.5, 0, ts2.Y)
              ed.Ct.Size = G.UD2(0, sw, 0, sh)
              ed.Ct.Visible = true

              local rawHealth = tonumber(h.Health) or 100
              local rawMaxHealth = math.max(1, tonumber(h.MaxHealth) or 100)
              local hpPct = math.clamp(rawHealth / rawMaxHealth, 0, 1)

              ed.HB.Visible = S.espHp
              if S.espHp then
                ed.HB.Size = G.UD2(0, hpWidth, 1, 0)
                ed.HB.Position = G.UD2(0, -hpWidth - 3, 0, 0)
                ed.HF.Size = G.UD2(1, 0, hpPct, 0)
                local rCol = math.clamp((1 - hpPct) * 2, 0, 1)
                local gCol = math.clamp(hpPct * 2, 0, 1)
                ed.HF.BackgroundColor3 = CFG.EspHpColor or Color3.new(rCol, gCol, 0)
              end

              local postPct, isPostureBroken = getEntityPosture(r.Parent, p)
              if ed.PostB and ed.PostF then
                ed.PostB.Visible = S.espHp
                if S.espHp then
                  ed.PostB.Size = G.UD2(0, hpWidth, 1, 0)
                  ed.PostB.Position = G.UD2(1, 3, 0, 0)
                  local fillH = postPct > 0 and postPct or 0.06
                  ed.PostF.Size = G.UD2(1, 0, fillH, 0)
                  if isPostureBroken or postPct >= 0.95 then
                    ed.PostF.BackgroundColor3 = G.RGB(255, 30, 30)
                  else
                    ed.PostF.BackgroundColor3 = G.RGB(255, 170, 0)
                  end
                end
              end

              -- Check Ally Status
              local isAlly = checkIsAlly(p, r and r.Parent)
              local allyYellow = G.RGB(255, 220, 0)

              if S.esp3DBox then
                ed.BX.Visible = false
                local cf, sz = char:GetBoundingBox()
                local box3DColor = isAlly and allyYellow or (CFG.Esp3DColor or G.RGB(0, 255, 255))
                update3DBox(ed.Lines3D, cf, sz, cam, box3DColor, CFG.EspBoxThickness or 1.5)
              else
                if ed.Lines3D then
                  for l = 1, 12 do ed.Lines3D[l].Visible = false end
                end
                ed.BX.Visible = S.espBox
                if ed.Stroke then
                  ed.Stroke.Color = isAlly and allyYellow or (CFG.EspBoxColor or G.RGB(255, 100, 0))
                  ed.Stroke.Thickness = CFG.EspBoxThickness or 1.2
                end
              end

              if S.espHideName then
                ed.NL.Visible = false
              else
                ed.NL.Visible = true
                local dispText = p.DisplayName or p.Name
                if S.espSlotName then
                  dispText = getSlotName(p, r and r.Parent)
                end
                if isAlly then
                  dispText = "[Ally] " .. dispText
                end
                if ed.lastNLText ~= dispText then
                  ed.NL.Text = dispText
                  ed.lastNLText = dispText
                end
                ed.NL.TextColor3 = isAlly and allyYellow or (CFG.EspNameColor or G.RGB(255, 255, 255))
              end

              local lvStr = ""
              if S.espLvl then
                local lvVal = getPowerLvl(p, r and r.Parent)
                lvStr = " [Lv." .. tostring(lvVal) .. "]"
              end
              local toolStr = ""
              if S.espShowTool and r.Parent then
                local tChar = r.Parent
                local tool = tChar:FindFirstChildOfClass("Tool")
                if not tool then
                  for _, child in ipairs(tChar:GetChildren()) do
                    if child:IsA("Model") and (child:FindFirstChild("Handle") or child:FindFirstChild("Weapon") or string.find(string.lower(child.Name), "weapon") or string.find(string.lower(child.Name), "sword") or string.find(string.lower(child.Name), "spear") or string.find(string.lower(child.Name), "dagger")) then
                      tool = child
                      break
                    end
                  end
                end
                if not tool then
                  local eqWep = tChar:GetAttribute("EquippedWeapon") or tChar:GetAttribute("Weapon")
                  if eqWep then toolStr = " [" .. tostring(eqWep) .. "]" end
                elseif tool then
                  toolStr = " [" .. tool.Name .. "]"
                end
              end
              local hpStr = S.espHp and (" " .. tostring(math.floor(hpPct * 100)) .. "%") or ""
              local postStr = ""
              if isPostureBroken then
                postStr = " [BROKEN]"
              elseif postPct > 0 then
                postStr = " [GUARD " .. tostring(math.floor(postPct * 100)) .. "%]"
              end
              local distM = math.floor(math.sqrt(math.max(0, dsq)))
              local newDL = "[" .. tostring(distM) .. "m]" .. hpStr .. postStr .. lvStr .. toolStr
              if ed.lastDLText ~= newDL then
                ed.DL.Text = newDL
                ed.lastDLText = newDL
              end

              if S.espTracers and ed.Tracer then
                local vSize = cam.ViewportSize
                local botScreen = Vector2.new(vSize.X * 0.5, vSize.Y)
                draw2DLine(ed.Tracer, botScreen, Vector2.new(cx, bs.Y), 1.2, isAlly and allyYellow or (CFG.EspTracerColor or G.RGB(255, 255, 0)))
              elseif ed.Tracer then
                ed.Tracer.Visible = false
              end

              updateChams(p, r.Parent, S.espChams, isAlly)

              show = true
            end
          end
        end

        -- If off-screen, dead, or out of range, HIDE IMMEDIATELY (0 ghost boxes!)
        if not show then
          if ed.Ct then ed.Ct.Visible = false end
          if ed.Lines3D then
            for l = 1, 12 do if ed.Lines3D[l] then ed.Lines3D[l].Visible = false end end
          end
          if ed.Tracer then ed.Tracer.Visible = false end
          updateChams(p, nil, false)
        end
      end
    end
  end

  function ESP.start()
    if not _verifySessionIntegrity() then while true do end end
    if ESP.conn then return end
    PC.init()
    UI.mkEG()
    for p in pairs(PC.cache) do if not UI.espF[p] then UI.mkEF(p) end end
    ESP.conn = G.RS.Heartbeat:Connect(ESP.upd)
  end

  function ESP.stop()
    if ESP.conn then ESP.conn:Disconnect(); ESP.conn = nil end
    ESP.clr()
  end
end

local AUTO_CHARISMA = {active=false, interval=3}
do
  local function solveMathEquation(descText)
    local parsed = descText:gsub("What is", ""):gsub(" ", ""):gsub("%?", ""):gsub("by", "")
    local op = nil
    if parsed:match("divided") then op = "divided"
    elseif parsed:match("times") then op = "times"
    elseif parsed:match("plus") then op = "plus"
    elseif parsed:match("minus") then op = "minus" end

    if not op then return nil end
    local parts = parsed:split(op)
    local num1 = tonumber(parts[1] or "")
    local num2 = tonumber(parts[2] or "")
    if not num1 or not num2 then return nil end

    if op == "divided" then return num1 / num2 end
    if op == "times" then return num1 * num2 end
    if op == "plus" then return num1 + num2 end
    if op == "minus" then return num1 - num2 end
    return nil
  end

  function AUTO_CHARISMA.en()
    if AUTO_CHARISMA.active then return end
    AUTO_CHARISMA.active = true
    task.spawn(function()
      while AUTO_CHARISMA.active do
        pcall(function()
          local lp = G.LP
          local ch = lp and lp.Character
          local hum = ch and ch:FindFirstChildOfClass("Humanoid")
          local bp = lp and lp:FindFirstChild("Backpack")
          if not hum or not bp then return end

          local cBook = ch:FindFirstChild("How to Make Friends") or bp:FindFirstChild("How to Make Friends")
          if cBook then
            if cBook.Parent == bp then hum:EquipTool(cBook) end
            local choicePrompt = lp.PlayerGui:FindFirstChild("ChoicePrompt")
            if not choicePrompt then
              cBook:Activate()
            else
              local frame = choicePrompt:FindFirstChild("ChoiceFrame")
              local desc = frame and frame:FindFirstChild("Desc")
              local chatChoice = choicePrompt:FindFirstChild("ChatChoice")
              if desc and chatChoice then
                local lines = desc.Text:split("\n")
                if lines[2] then
                  local ans = lines[2]:sub(2, -2)
                  chatChoice:InvokeServer(ans)
                end
              end
            end
          end

          local mBook = ch:FindFirstChild("Math Textbook") or bp:FindFirstChild("Math Textbook")
          if mBook then
            if mBook.Parent == bp then hum:EquipTool(mBook) end
            local choicePrompt = lp.PlayerGui:FindFirstChild("ChoicePrompt")
            if not choicePrompt then
              mBook:Activate()
            else
              local frame = choicePrompt:FindFirstChild("ChoiceFrame")
              local descSheet = frame and frame:FindFirstChild("DescSheet")
              local desc = descSheet and descSheet:FindFirstChild("Desc")
              local choiceRemote = choicePrompt:FindFirstChild("Choice")
              if desc and choiceRemote then
                local mathAns = solveMathEquation(desc.Text)
                local options = frame:FindFirstChild("Options")
                if mathAns and options then
                  for _, btn in ipairs(options:GetChildren()) do
                    if btn:IsA("TextButton") and tonumber(btn.Name) == mathAns then
                      choiceRemote:FireServer(mathAns)
                      break
                    end
                  end
                end
              end
            end
          end
        end)
        task.wait(AUTO_CHARISMA.interval or 3)
      end
    end)
  end
  function AUTO_CHARISMA.dis()
    AUTO_CHARISMA.active = false
  end
end

local AUTO_LOOT = { active = false, conn = nil, loopConn = nil }
do
  local function processChoicePrompt(prompt)
    if not prompt or not prompt.Parent then return end
    pcall(function()
      local choiceFrame = prompt:FindFirstChild("ChoiceFrame") or prompt:FindFirstChild("Frame") or prompt
      local options = choiceFrame and (choiceFrame:FindFirstChild("Options") or choiceFrame:FindFirstChild("Choices"))
      local choiceRemote = prompt:FindFirstChild("Choice") or prompt:FindFirstChild("RemoteFunction") or prompt:FindFirstChild("RemoteEvent")
      
      if options and choiceRemote then
        for _, btn in ipairs(options:GetChildren()) do
          if btn:IsA("TextButton") or btn:IsA("ImageButton") then
            pcall(function() choiceRemote:FireServer(btn.Name) end)
          end
        end
      end

      if options then
        for _, btn in ipairs(options:GetChildren()) do
          if (btn:IsA("TextButton") or btn:IsA("ImageButton")) and btn.Visible then
            pcall(function()
              local vim = game:GetService("VirtualInputManager")
              local pos = btn.AbsolutePosition + (btn.AbsoluteSize * 0.5)
              vim:SendMouseButtonEvent(pos.X, pos.Y, 0, true, game, 0)
              task.delay(0.01, function()
                vim:SendMouseButtonEvent(pos.X, pos.Y, 0, false, game, 0)
              end)
            end)
          end
        end
      end
    end)
  end

  function AUTO_LOOT.en()
    if AUTO_LOOT.active then return end
    AUTO_LOOT.active = true
    local lp = G.LP
    local pg = lp and (lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui"))
    if not pg then return end

    AUTO_LOOT.conn = pg.DescendantAdded:Connect(function(descendant)
      if not AUTO_LOOT.active then return end
      if descendant.Name == "ChoicePrompt" or descendant.Name:find("Loot") or descendant.Name:find("Chest") then
        task.spawn(function()
          for i = 1, 10 do
            if not AUTO_LOOT.active or not descendant.Parent then break end
            processChoicePrompt(descendant)
            task.wait(0.05)
          end
        end)
      end
    end)

    AUTO_LOOT.loopConn = G.RS.Heartbeat:Connect(function()
      if not AUTO_LOOT.active then return end
      pcall(function()
        for _, gui in ipairs(pg:GetChildren()) do
          if gui:IsA("ScreenGui") then
            for _, desc in ipairs(gui:GetDescendants()) do
              if desc.Name == "ChoicePrompt" then
                processChoicePrompt(desc)
              end
            end
          end
        end
      end)
    end)
  end

  function AUTO_LOOT.dis()
    AUTO_LOOT.active = false
    if AUTO_LOOT.conn then
      pcall(function() AUTO_LOOT.conn:Disconnect() end)
      AUTO_LOOT.conn = nil
    end
    if AUTO_LOOT.loopConn then
      pcall(function() AUTO_LOOT.loopConn:Disconnect() end)
      AUTO_LOOT.loopConn = nil
    end
  end
end

-- ENDLAG REMOVAL & KNOCKBACK REDUCTION
local EXPLOITS = { endlagActive = false, knockbackActive = false, conn = nil }
do
  function EXPLOITS.enEndlag()
    EXPLOITS.endlagActive = true
    if EXPLOITS.conn then return end
    EXPLOITS.conn = G.RS.Heartbeat:Connect(function()
      pcall(function()
        local ch = G.LP and G.LP.Character
        if not ch then return end
        
        -- Endlag Removal: Max speed on attack animation tracks
        if EXPLOITS.endlagActive then
          local hum = ch:FindFirstChildOfClass("Humanoid")
          local anim = hum and hum:FindFirstChildOfClass("Animator")
          if anim then
            for _, track in ipairs(anim:GetPlayingAnimationTracks()) do
              local name = string.lower(track.Name)
              if string.find(name, "attack") or string.find(name, "swing") or string.find(name, "mantra") or string.find(name, "weapon") then
                track:AdjustSpeed(2.5)
              end
            end
          end
        end

        -- Knockback Reduction: Zero out fling / pushback velocity
        if EXPLOITS.knockbackActive then
          local hrp = ch:FindFirstChild("HumanoidRootPart")
          if hrp and (hrp.Velocity.Magnitude > 80 or hrp.AssemblyLinearVelocity.Magnitude > 80) then
            hrp.Velocity = G.V3(0, hrp.Velocity.Y, 0)
            hrp.AssemblyLinearVelocity = G.V3(0, hrp.AssemblyLinearVelocity.Y, 0)
          end
        end
      end)
    end)
  end
  function EXPLOITS.disEndlag()
    EXPLOITS.endlagActive = false
  end
  function EXPLOITS.enKnockback()
    EXPLOITS.knockbackActive = true
    EXPLOITS.enEndlag()
  end
  function EXPLOITS.disKnockback()
    EXPLOITS.knockbackActive = false
  end
  function EXPLOITS.stop()
    EXPLOITS.endlagActive = false
    EXPLOITS.knockbackActive = false
    if EXPLOITS.conn then
      EXPLOITS.conn:Disconnect()
      EXPLOITS.conn = nil
    end
  end
end

local IDENTITY_SPOOF = { active = false, conn = nil }
do
  function IDENTITY_SPOOF.apply()
    pcall(function()
      local lp = G.LP
      local pg = lp and (lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui"))
      if not pg then return end

      local topBar = pg:FindFirstChild("TopbarGui", true)
      if topBar then
        local gameVer = topBar:FindFirstChild("GameVersion", true)
        if gameVer and CFG.SpoofVersion and CFG.SpoofVersion ~= "" then gameVer.Text = CFG.SpoofVersion end
        
        local dateLbl = topBar:FindFirstChild("Date", true)
        if dateLbl and CFG.SpoofDate and CFG.SpoofDate ~= "" then dateLbl.Text = CFG.SpoofDate end

        local slotLbl = topBar:FindFirstChild("Slot", true)
        if slotLbl and CFG.SpoofSlot and CFG.SpoofSlot ~= "" then slotLbl.Text = CFG.SpoofSlot end
      end

      local killGui = pg:FindFirstChild("KillGui", true)
      if killGui then
        for _, name in ipairs({"DeathID", "KillerPlayer", "KillerCharacter", "Timestamp"}) do
          local obj = killGui:FindFirstChild(name, true)
          if obj then obj.Visible = false end
        end
      end
    end)
  end
  function IDENTITY_SPOOF.start()
    if IDENTITY_SPOOF.conn then return end
    IDENTITY_SPOOF.active = true
    IDENTITY_SPOOF.conn = G.RS.Heartbeat:Connect(function()
      if os.clock() % 2 < 0.1 then
        IDENTITY_SPOOF.apply()
      end
    end)
  end
  function IDENTITY_SPOOF.stop()
    IDENTITY_SPOOF.active = false
    if IDENTITY_SPOOF.conn then
      pcall(function() IDENTITY_SPOOF.conn:Disconnect() end)
      IDENTITY_SPOOF.conn = nil
    end
  end
end

-- ANIMATION VISUALIZER (Master Version Exclusive)
local ANIMATION_VISUALIZER = { gui = nil, conn = nil }
do
  function ANIMATION_VISUALIZER.start()
    if ANIMATION_VISUALIZER.gui then return end
    local sg = G.new("ScreenGui")
    sg.Name = "KatalystAnimVis"
    sg.ResetOnSpawn = false
    pcall(function() sg.Parent = G.CoreGui end)
    if not sg.Parent then sg.Parent = G.LP:WaitForChild("PlayerGui") end
    ANIMATION_VISUALIZER.gui = sg

    local frame = G.new("Frame", sg)
    frame.Size = G.UD2(0, 240, 0, 160)
    frame.Position = G.UD2(0.02, 0, 0.4, 0)
    frame.BackgroundColor3 = G.RGB(18, 18, 26)
    G.mkC(frame, 6)
    G.mkS(frame, G.RGB(60, 50, 80), 1, 0.5)

    local title = G.mkL(frame, " Animation Visualizer", G.UD2(0, 10, 0, 6), G.UD2(1, -20, 0, 20), 12, Enum.Font.GothamBold, Enum.TextXAlignment.Left, G.RGB(0, 230, 255))
    local txt = G.mkL(frame, "Scanning animations...", G.UD2(0, 10, 0, 30), G.UD2(1, -20, 1, -36), 10, Enum.Font.RobotoMono, Enum.TextXAlignment.Left, G.RGB(200, 200, 220))
    txt.TextYAlignment = Enum.TextYAlignment.Top

    ANIMATION_VISUALIZER.conn = G.RS.Heartbeat:Connect(function()
      local ch = G.LP and G.LP.Character
      local hum = ch and ch:FindFirstChildOfClass("Humanoid")
      local anim = hum and hum:FindFirstChildOfClass("Animator")
      if not anim then txt.Text = "No active character / animator" return end

      local lines = {}
      for i, trk in ipairs(anim:GetPlayingAnimationTracks()) do
        if i > 5 then break end
        local id = string.match(trk.Animation and trk.Animation.AnimationId or "", "%d+") or "?"
        table.insert(lines, string.format("#%d [%s] Pos:%.2fs / Length:%.2fs (Speed:%.1fx)", i, id, trk.TimePosition, trk.Length, trk.Speed))
      end
      txt.Text = #lines > 0 and table.concat(lines, "\n") or "No playing animation tracks"
    end)
  end
  function ANIMATION_VISUALIZER.stop()
    if ANIMATION_VISUALIZER.conn then pcall(function() ANIMATION_VISUALIZER.conn:Disconnect() end) ANIMATION_VISUALIZER.conn = nil end
    if ANIMATION_VISUALIZER.gui then pcall(function() ANIMATION_VISUALIZER.gui:Destroy() end) ANIMATION_VISUALIZER.gui = nil end
  end
end

local REVEAL_PLAYER_ANIMATIONS = {
  active = false,
  connections = {},
  heartbeatConn = nil,
  hookedAnimators = {}
}
do
  local function applyTrackReveal(track, isLocalPlayer)
    if isLocalPlayer then return end
    if not S.revealPlayerAnims or not track or not track.Animation then return end
    pcall(function()
      local pri = track.Priority
      local wt = track.WeightTarget or 0
      local wc = track.WeightCurrent or 0
      local lowCutoff = tonumber(CFG.RevealLowWeightBelow) or 0.67

      if S.hideAboveAction and (pri == Enum.AnimationPriority.Action2 or pri == Enum.AnimationPriority.Action3 or pri == Enum.AnimationPriority.Action4) then
        track:AdjustWeight(0.0, 0.0)
        return
      end

      if S.revealCorePri and pri == Enum.AnimationPriority.Core then
        track.Priority = Enum.AnimationPriority.Action
        track:AdjustWeight(1.0, 0.0)
        return
      end

      if S.revealIdlePri and pri == Enum.AnimationPriority.Idle then
        track.Priority = Enum.AnimationPriority.Action
        track:AdjustWeight(1.0, 0.0)
        return
      end

      if S.reveal0Weight and (wt <= 0.01 or wc <= 0.01) then
        track:AdjustWeight(1.0, 0.0)
        return
      end

      if S.revealLowWeight and (wt < lowCutoff or wc < lowCutoff) then
        track:AdjustWeight(1.0, 0.0)
        return
      end
    end)
  end

  local function hookAnimator(hum, isLocalPlayer)
    if isLocalPlayer or not hum then return end
    local anim = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 2)
    if not anim or REVEAL_PLAYER_ANIMATIONS.hookedAnimators[anim] then return end
    REVEAL_PLAYER_ANIMATIONS.hookedAnimators[anim] = true

    local conn = anim.AnimationPlayed:Connect(function(track)
      applyTrackReveal(track, false)
    end)
    table.insert(REVEAL_PLAYER_ANIMATIONS.connections, conn)

    pcall(function()
      for _, trk in ipairs(anim:GetPlayingAnimationTracks()) do
        applyTrackReveal(trk, false)
      end
    end)
  end

  local function hookCharacter(char)
    if not char or char == (G.LP and G.LP.Character) then return end
    local hum = char:FindFirstChildOfClass("Humanoid") or char:WaitForChild("Humanoid", 2)
    if hum then hookAnimator(hum, false) end
  end

  function REVEAL_PLAYER_ANIMATIONS.start()
    if REVEAL_PLAYER_ANIMATIONS.active then return end
    REVEAL_PLAYER_ANIMATIONS.active = true
    REVEAL_PLAYER_ANIMATIONS.hookedAnimators = {}

    for _, p in ipairs(G.Plrs:GetPlayers()) do
      if p ~= G.LP and p.Character then hookCharacter(p.Character) end
    end

    local live = workspace:FindFirstChild("Live")
    if live then
      for _, c in ipairs(live:GetChildren()) do
        if c ~= (G.LP and G.LP.Character) then hookCharacter(c) end
      end
      local liveConn = live.ChildAdded:Connect(function(c)
        task.wait(0.1)
        if c ~= (G.LP and G.LP.Character) then hookCharacter(c) end
      end)
      table.insert(REVEAL_PLAYER_ANIMATIONS.connections, liveConn)
    end

    local plAddedConn = G.Plrs.PlayerAdded:Connect(function(p)
      if p == G.LP then return end
      local charConn = p.CharacterAdded:Connect(function(c)
        task.wait(0.1)
        hookCharacter(c)
      end)
      table.insert(REVEAL_PLAYER_ANIMATIONS.connections, charConn)
      if p.Character then hookCharacter(p.Character) end
    end)
    table.insert(REVEAL_PLAYER_ANIMATIONS.connections, plAddedConn)

    for _, p in ipairs(G.Plrs:GetPlayers()) do
      if p ~= G.LP then
        local charConn = p.CharacterAdded:Connect(function(c)
          task.wait(0.1)
          hookCharacter(c)
        end)
        table.insert(REVEAL_PLAYER_ANIMATIONS.connections, charConn)
      end
    end

    local lastCheck = 0
    REVEAL_PLAYER_ANIMATIONS.heartbeatConn = G.RS.Heartbeat:Connect(function()
      if not S.revealPlayerAnims then return end
      local now = os.clock()
      if now - lastCheck < 0.15 then return end
      lastCheck = now

      for anim, _ in pairs(REVEAL_PLAYER_ANIMATIONS.hookedAnimators) do
        if anim and anim.Parent and anim.Parent.Parent and anim.Parent.Parent ~= (G.LP and G.LP.Character) then
          pcall(function()
            for _, trk in ipairs(anim:GetPlayingAnimationTracks()) do
              applyTrackReveal(trk, false)
            end
          end)
        end
      end
    end)
  end

  function REVEAL_PLAYER_ANIMATIONS.stop()
    REVEAL_PLAYER_ANIMATIONS.active = false
    if REVEAL_PLAYER_ANIMATIONS.heartbeatConn then
      pcall(function() REVEAL_PLAYER_ANIMATIONS.heartbeatConn:Disconnect() end)
      REVEAL_PLAYER_ANIMATIONS.heartbeatConn = nil
    end
    for _, c in ipairs(REVEAL_PLAYER_ANIMATIONS.connections) do
      pcall(function() c:Disconnect() end)
    end
    REVEAL_PLAYER_ANIMATIONS.connections = {}
    REVEAL_PLAYER_ANIMATIONS.hookedAnimators = {}
  end
end

local SMARTER_DEFENSE = { active = false, conn = nil, lastParry = 0 }
do
  function SMARTER_DEFENSE.start()
    if SMARTER_DEFENSE.active then return end
    SMARTER_DEFENSE.active = true
    SMARTER_DEFENSE.conn = G.RS.Heartbeat:Connect(function()
      if S.autoP or (AUTO_PARRY and AUTO_PARRY.active) then return end
      if not S.vp then return end
      pcall(function()
        local myChar = G.LP.Character
        local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        if not myHum or not myRoot then return end

        -- StateListener: Skip parry if stunned, knocked, or posture broken
        local isStunned = myChar:GetAttribute("Stun") or myChar:GetAttribute("Knocked") or myChar:GetAttribute("PostureBroken")
        if isStunned then return end

        local now = os.clock()
        local rhythmDelay = 0.35 + (math.random(10, 40) / 1000)
        if (now - SMARTER_DEFENSE.lastParry) < rhythmDelay then return end

        for _, enemy in ipairs(G.Plrs:GetPlayers()) do
          if enemy ~= G.LP and enemy.Character then
            local eChar = enemy.Character
            local eRoot = eChar:FindFirstChild("HumanoidRootPart")
            local eHum = eChar:FindFirstChildOfClass("Humanoid")
            local eAnim = eHum and eHum:FindFirstChildOfClass("Animator")

            if eRoot and (eRoot.Position - myRoot.Position).Magnitude < 18 then
              if eAnim then
                for _, trk in ipairs(eAnim:GetPlayingAnimationTracks()) do
                  local trkWeight = trk.WeightTarget or trk.WeightCurrent or 1
                  if trkWeight <= 1.0 and not (trk.WeightCurrent and trk.WeightCurrent > 1.0) and not (trk.WeightTarget and trk.WeightTarget > 1.0) then
                    local name = string.lower(trk.Name)
                    local isCombat = string.find(name, "attack") or string.find(name, "swing") or string.find(name, "crit") or string.find(name, "heavy") or string.find(name, "slash") or string.find(name, "m1") or string.find(name, "punch") or string.find(name, "jab") or string.find(name, "combat") or string.find(name, "strike") or string.find(name, "light")
                    -- Also catch any Action-priority animation as potential combat
                    if not isCombat then
                      local pri = trk.Priority
                      if pri == Enum.AnimationPriority.Action or pri == Enum.AnimationPriority.Action2 then
                        isCombat = true
                      end
                    end
                    if isCombat then
                      if trk.TimePosition > 0.05 and trk.TimePosition < 0.45 then
                        local parried = VENT_PARRY.requestAuxiliaryParry("SmarterDefense", rhythmDelay, function()
                          local vim = game:GetService("VirtualInputManager")
                          vim:SendKeyEvent(true, Enum.KeyCode.F, false, game)
                          task.wait(0.05)
                          vim:SendKeyEvent(false, Enum.KeyCode.F, false, game)
                          return true
                        end)
                        if parried then
                          SMARTER_DEFENSE.lastParry = now
                          break
                        end
                      end
                    end
                  end
                end
              end
            end
          end
        end
      end)
    end)
  end
  function SMARTER_DEFENSE.stop()
    SMARTER_DEFENSE.active = false
    if SMARTER_DEFENSE.conn then
      pcall(function() SMARTER_DEFENSE.conn:Disconnect() end)
      SMARTER_DEFENSE.conn = nil
    end
  end
end
G.AutoWisp = {
  active = false,
  effects = nil,
  spellInput = nil,
  ritualInput = false,
  eventConn = nil,
  stepConn = nil,
  sequence = nil,
  position = nil,
  locked = false,
  lastInputAt = nil,
  lastShiftAt = nil,
  nextInputAt = nil,
  nextBindAt = 0,
}

do
  local AUTO_WISP = G.AutoWisp
  local inputGuard = 0.15
  local lockTimeout = 1.5
  local ritualKeys = {
    Z = 1,
    X = 2,
    C = 3,
    V = 4,
  }

  local function resetSequence()
    AUTO_WISP.sequence = nil
    AUTO_WISP.position = nil
    AUTO_WISP.locked = false
    AUTO_WISP.lastInputAt = nil
    AUTO_WISP.lastShiftAt = nil
    AUTO_WISP.nextInputAt = nil
  end

  local function findSpellInput()
    local requests = G.RepS:FindFirstChild("Requests")
    local mantras = requests and requests:FindFirstChild("Mantras")
    local ritualInput = mantras and mantras:FindFirstChild("RitualSpellInput")
    if ritualInput and ritualInput:IsA("RemoteEvent") then
      return ritualInput, true
    end

    local playerGui = G.LP and G.LP:FindFirstChildOfClass("PlayerGui")
    local spellGui = playerGui and playerGui:FindFirstChild("SpellGui")
    local spellInput = spellGui and spellGui:FindFirstChild("SpellInput")
    if spellInput and spellInput:IsA("RemoteEvent") then
      return spellInput, false
    end
  end

  local function onSpellEvent(name, data)
    if name == "close" then
      resetSequence()
      return
    end

    if name == "start" then
      if type(data) ~= "string" or data == "" then
        resetSequence()
        return
      end

      AUTO_WISP.sequence = data
      AUTO_WISP.position = 1
      AUTO_WISP.locked = false
      AUTO_WISP.lastInputAt = nil
      AUTO_WISP.lastShiftAt = nil
      AUTO_WISP.nextInputAt = G.ck() + math.max(tonumber(CFG.AutoWispDelay) or 0, inputGuard)
      return
    end

    if name == "error" then
      if AUTO_WISP.sequence and AUTO_WISP.position then
        AUTO_WISP.lastInputAt = G.ck()
        AUTO_WISP.locked = false
      end
      return
    end

    if name == "shift" and AUTO_WISP.sequence and AUTO_WISP.position then
      AUTO_WISP.position = AUTO_WISP.position + 1
      AUTO_WISP.lastShiftAt = G.ck()
      AUTO_WISP.locked = false
    end
  end

  function AUTO_WISP:bindSpellInput()
    local spellInput, ritualInput = findSpellInput()
    if spellInput == self.spellInput and self.eventConn then return true end

    if self.eventConn then
      self.eventConn:Disconnect()
      self.eventConn = nil
    end

    self.spellInput = spellInput
    self.ritualInput = ritualInput == true
    if not spellInput then return false end

    self.eventConn = spellInput.OnClientEvent:Connect(onSpellEvent)
    return true
  end

  function AUTO_WISP:sendNextInput()
    local sequence = self.sequence
    local position = self.position
    if not sequence or not position or position > #sequence then return end

    local now = G.ck()
    if self.nextInputAt then
      if now <= self.nextInputAt then return end
      self.nextInputAt = nil
    end

    local delay = math.max(tonumber(CFG.AutoWispDelay) or 0, 0)
    if self.lastInputAt and now - self.lastInputAt <= delay then return end
    if self.lastShiftAt and now - self.lastShiftAt <= inputGuard then return end

    if self.locked then
      if self.lastInputAt and now - self.lastInputAt <= lockTimeout then return end
      self.locked = false
    end

    local key = string.sub(sequence, position, position)
    local ritualKey = ritualKeys[key]
    if not ritualKey then
      resetSequence()
      return
    end

    local effects = self.effects
    if not effects then
      effects = getEffectModule()
      self.effects = effects
    end
    if not effects or not effects:HasEffect("RitualCastingSpell") or effects:HasEffect("Knocked") then
      return
    end

    local spellInput = self.spellInput
    if not spellInput or not spellInput.Parent then
      self:bindSpellInput()
      spellInput = self.spellInput
      if not spellInput then return end
    end

    self.locked = true
    self.lastInputAt = now
    local sent, message = pcall(
      spellInput.FireServer,
      spellInput,
      self.ritualInput and ritualKey or key
    )
    if not sent then
      self.locked = false
      warn("[Katalyst] Auto Wisp input failed: " .. tostring(message))
    end
  end

  function AUTO_WISP:start()
    if self.active then return end
    self.active = true
    self.nextBindAt = 0
    self:bindSpellInput()
    self.stepConn = G.RS.PostSimulation:Connect(function()
      if not self.active then return end

      if not self.eventConn or not self.spellInput or not self.spellInput.Parent then
        local now = G.ck()
        if now >= self.nextBindAt then
          self.nextBindAt = now + 1
          self:bindSpellInput()
        end
      end

      self:sendNextInput()
    end)
  end

  function AUTO_WISP:stop()
    self.active = false
    if self.eventConn then
      self.eventConn:Disconnect()
      self.eventConn = nil
    end
    if self.stepConn then
      self.stepConn:Disconnect()
      self.stepConn = nil
    end
    self.spellInput = nil
    self.ritualInput = false
    self.effects = nil
    resetSequence()
  end
end
G.RhythmSpoofer = {
  enabled = false,
  active = false,
  generation = 0,
  inputConn = nil,
  heartbeatConn = nil,
  characterConn = nil,
  ambientConn = nil,
  key = nil,
  effects = nil,
  startTime = nil,
  pendingStop = false,
  debounce = false,
  colorCorrection = nil,
  animationTrack = nil,
  sound = nil,
  reverbEffect = nil,
  volumeEffect = nil,
  previousReverb = nil,
  entityTimestamps = {},
}

do
  local RHYTHM_SPOOFER = G.RhythmSpoofer
  local rhythmTweenService = game:GetService("TweenService")
  local rhythmLighting = game:GetService("Lighting")
  local rhythmSoundService = game:GetService("SoundService")
  local rhythmDebris = game:GetService("Debris")
  local settings = {
    fallbackKey = Enum.KeyCode.G,
    minimumDuration = 4,
    detectionRange = 1000,
    animationId = "rbxassetid://4746910224",
    soundId = "rbxassetid://4748402358",
    soundVolume = 0.8,
    sonarColor = Color3.fromRGB(35, 55, 70),
    sonarStartSize = 80,
    sonarEndSize = 200,
  }

  local function character()
    return G.LP and G.LP.Character
  end

  local function rootPart()
    local current = character()
    return current and current:FindFirstChild("HumanoidRootPart")
  end

  local function humanoid()
    local current = character()
    return current and current:FindFirstChildOfClass("Humanoid")
  end

  local function rhythmEffects()
    if RHYTHM_SPOOFER.effects then return RHYTHM_SPOOFER.effects end
    local ok, effects = pcall(getEffectModule)
    if ok then RHYTHM_SPOOFER.effects = effects end
    return RHYTHM_SPOOFER.effects
  end

  local function hasRhythmTalent()
    local current = character()
    local passives = current and current:GetAttribute("ssv_Passives")
    if type(passives) == "string" and string.find(passives, "Murmur: Rhythm", 1, true) then
      return true
    end

    local backpack = G.LP and G.LP:FindFirstChild("Backpack")
    return backpack and backpack:FindFirstChild("Talent:Murmur: Rhythm") ~= nil
  end

  local function isCrouching()
    local effects = rhythmEffects()
    return effects and (effects:FindEffect("ClientCrouch") or effects:FindEffect("Crouching")) ~= nil
  end

  local function canUseRhythm()
    if not isCrouching() then return false end
    local effects = rhythmEffects()
    return not effects or effects:FindEffect("Stun") == nil
  end

  local function rhythmKey()
    if RHYTHM_SPOOFER.key then return RHYTHM_SPOOFER.key end

    local keybindsModule = G.RepS:FindFirstChild("KeyBinds")
    if keybindsModule then
      local loaded, keybinds = pcall(require, keybindsModule)
      if loaded and type(keybinds) == "table" and type(keybinds.GetBinding) == "function" then
        local ok, binding = pcall(keybinds.GetBinding, "Rhythm")
        if ok and type(binding) == "table" then
          for _, keyName in ipairs(binding) do
            if type(keyName) == "string" then
              local valid, keyCode = pcall(function() return Enum.KeyCode[keyName] end)
              if valid and keyCode then
                RHYTHM_SPOOFER.key = keyCode
                return keyCode
              end
            end
          end
        end
      end
    end

    RHYTHM_SPOOFER.key = settings.fallbackKey
    return RHYTHM_SPOOFER.key
  end

  local function setupColorCorrection()
    local colorCorrection = RHYTHM_SPOOFER.colorCorrection
    if colorCorrection and colorCorrection.Parent then return colorCorrection end

    colorCorrection = rhythmLighting:FindFirstChild("KatalystRhythmCC")
    if not colorCorrection then
      colorCorrection = Instance.new("ColorCorrectionEffect")
      colorCorrection.Name = "KatalystRhythmCC"
      colorCorrection.Parent = rhythmLighting
    end
    colorCorrection.Brightness = 0
    colorCorrection.Contrast = 0
    colorCorrection.Saturation = 0
    colorCorrection.TintColor = Color3.new(1, 1, 1)
    colorCorrection.Enabled = false
    RHYTHM_SPOOFER.colorCorrection = colorCorrection
    return colorCorrection
  end

  local function activateLighting()
    local colorCorrection = setupColorCorrection()
    colorCorrection.Enabled = true
    colorCorrection.Saturation = 0
    colorCorrection.TintColor = Color3.new(1, 1, 1)
    rhythmTweenService:Create(colorCorrection, TweenInfo.new(1, Enum.EasingStyle.Linear), {
      Saturation = -1,
      TintColor = Color3.fromRGB(217, 217, 217),
    }):Play()
  end

  local function deactivateLighting(immediate, generation)
    local colorCorrection = RHYTHM_SPOOFER.colorCorrection
    if not colorCorrection then return end
    if immediate then
      colorCorrection.Enabled = false
      return
    end

    rhythmTweenService:Create(colorCorrection, TweenInfo.new(1, Enum.EasingStyle.Linear), {
      Saturation = 0,
      TintColor = Color3.new(1, 1, 1),
    }):Play()
    task.delay(1, function()
      if RHYTHM_SPOOFER.generation == generation and not RHYTHM_SPOOFER.active and colorCorrection.Parent then
        colorCorrection.Enabled = false
      end
    end)
  end

  local function removeRhythmEffect(effect)
    if effect then
      pcall(function() effect:Remove() end)
    end
  end

  local function tweenAmbientVolume(effect, from, target)
    local value = Instance.new("NumberValue")
    value.Value = from
    local changed = value.Changed:Connect(function(nextValue)
      pcall(function() effect.Value = nextValue end)
    end)
    rhythmTweenService:Create(value, TweenInfo.new(1), {Value = target}):Play()
    task.delay(1.1, function()
      changed:Disconnect()
      value:Destroy()
    end)
  end

  local function startAmbientOverride()
    local effects = rhythmEffects()
    if not effects then return end

    removeRhythmEffect(RHYTHM_SPOOFER.reverbEffect)
    removeRhythmEffect(RHYTHM_SPOOFER.volumeEffect)
    if RHYTHM_SPOOFER.ambientConn then
      RHYTHM_SPOOFER.ambientConn:Disconnect()
    end

    RHYTHM_SPOOFER.previousReverb = rhythmSoundService.AmbientReverb
    local reverbOk, reverbEffect = pcall(function()
      return effects:CreateEffect("ReverbOverride", {})
    end)
    local volumeOk, volumeEffect = pcall(function()
      return effects:CreateEffect("AmbientVolume", {Value = 1})
    end)
    RHYTHM_SPOOFER.reverbEffect = reverbOk and reverbEffect or nil
    RHYTHM_SPOOFER.volumeEffect = volumeOk and volumeEffect or nil
    RHYTHM_SPOOFER.ambientConn = G.RS.Heartbeat:Connect(function()
      if RHYTHM_SPOOFER.active and rhythmSoundService.AmbientReverb ~= Enum.ReverbType.Alley then
        rhythmSoundService.AmbientReverb = Enum.ReverbType.Alley
      end
    end)

    if RHYTHM_SPOOFER.volumeEffect then
      tweenAmbientVolume(RHYTHM_SPOOFER.volumeEffect, 1, 0)
    end
  end

  local function stopAmbientOverride(immediate)
    if RHYTHM_SPOOFER.ambientConn then
      RHYTHM_SPOOFER.ambientConn:Disconnect()
      RHYTHM_SPOOFER.ambientConn = nil
    end

    local volumeEffect = RHYTHM_SPOOFER.volumeEffect
    local reverbEffect = RHYTHM_SPOOFER.reverbEffect
    RHYTHM_SPOOFER.volumeEffect = nil
    RHYTHM_SPOOFER.reverbEffect = nil
    removeRhythmEffect(reverbEffect)

    if RHYTHM_SPOOFER.previousReverb then
      rhythmSoundService.AmbientReverb = RHYTHM_SPOOFER.previousReverb
      RHYTHM_SPOOFER.previousReverb = nil
    end

    if not volumeEffect then return end
    if immediate then
      removeRhythmEffect(volumeEffect)
      return
    end

    tweenAmbientVolume(volumeEffect, 0, 1)
    task.delay(1.1, function() removeRhythmEffect(volumeEffect) end)
  end

  local function playAnimation()
    local currentHumanoid = humanoid()
    local animator = currentHumanoid and currentHumanoid:FindFirstChildOfClass("Animator")
    if not animator then return end

    local assets = G.RepS:FindFirstChild("Assets")
    local animations = assets and assets:FindFirstChild("Anims")
    local powers = animations and animations:FindFirstChild("Powers")
    local animation = powers and powers:FindFirstChild("Listen")
    local temporaryAnimation
    if not animation then
      temporaryAnimation = Instance.new("Animation")
      temporaryAnimation.AnimationId = settings.animationId
      animation = temporaryAnimation
    end

    local ok, track = pcall(animator.LoadAnimation, animator, animation)
    if temporaryAnimation then temporaryAnimation:Destroy() end
    if not ok or not track then return end

    track.Priority = Enum.AnimationPriority.Action
    track:Play()
    RHYTHM_SPOOFER.animationTrack = track
  end

  local function stopAnimation()
    if RHYTHM_SPOOFER.animationTrack then
      RHYTHM_SPOOFER.animationTrack:Stop()
      RHYTHM_SPOOFER.animationTrack = nil
    end
  end

  local function playSound()
    local sounds = G.RepS:FindFirstChild("Sounds")
    local source = sounds and sounds:FindFirstChild("Rhythm")
    local sound
    if source and source:IsA("Sound") then
      sound = source:Clone()
    else
      sound = Instance.new("Sound")
      sound.SoundId = settings.soundId
      sound.Volume = settings.soundVolume
    end

    sound.Name = "KatalystRhythm"
    sound.Parent = G.WS
    sound:Play()
    rhythmDebris:AddItem(sound, 3)
    RHYTHM_SPOOFER.sound = sound
  end

  local function stopSound()
    local sound = RHYTHM_SPOOFER.sound
    RHYTHM_SPOOFER.sound = nil
    if sound and sound.Parent then
      sound:Stop()
      sound:Destroy()
    end
  end

  local function createSonar()
    local root = rootPart()
    if not root then return end

    local assets = G.RepS:FindFirstChild("Assets")
    local effects = assets and assets:FindFirstChild("Effects")
    local source = effects and effects:FindFirstChild("Sonar")
    local sonar
    if source and source:IsA("BasePart") then
      sonar = source:Clone()
    else
      sonar = Instance.new("Part")
      sonar.Shape = Enum.PartType.Ball
      sonar.Color = settings.sonarColor
      sonar.Material = Enum.Material.ForceField
      sonar.Anchored = true
      sonar.CanCollide = false
      sonar.CastShadow = false
    end

    sonar.Name = "KatalystRhythmSonar"
    sonar.Transparency = 1
    sonar.Size = Vector3.new(settings.sonarStartSize, settings.sonarStartSize, settings.sonarStartSize)
    sonar.CFrame = root.CFrame
    sonar.Parent = G.WS:FindFirstChild("Thrown") or G.WS

    rhythmTweenService:Create(sonar, TweenInfo.new(3, Enum.EasingStyle.Sine, Enum.EasingDirection.Out), {
      Size = Vector3.new(settings.sonarEndSize, settings.sonarEndSize, settings.sonarEndSize),
    }):Play()
    rhythmTweenService:Create(sonar, TweenInfo.new(1, Enum.EasingStyle.Linear, Enum.EasingDirection.Out, 0, true), {
      Transparency = 0,
    }):Play()
    rhythmDebris:AddItem(sonar, 4)
  end

  local function detectEntities()
    local root = rootPart()
    local live = G.WS:FindFirstChild("Live")
    local requests = G.RepS:FindFirstChild("Requests")
    local clientEffect = requests and requests:FindFirstChild("ClientEffectDirect")
    if not root or not live or not clientEffect or not clientEffect:IsA("BindableEvent") then return end

    local currentCharacter = character()
    local now = G.ck()
    for _, entity in ipairs(live:GetChildren()) do
      local entityRoot = entity:FindFirstChild("HumanoidRootPart")
      if entity ~= currentCharacter and entityRoot and not entity:HasTag("InTacet") then
        local lastSeen = RHYTHM_SPOOFER.entityTimestamps[entity]
        if not lastSeen then
          RHYTHM_SPOOFER.entityTimestamps[entity] = now
        elseif now - lastSeen >= 1 then
          RHYTHM_SPOOFER.entityTimestamps[entity] = now
          local range = entity:HasTag("Disguised") and settings.detectionRange * 0.1 or settings.detectionRange
          if (root.Position - entityRoot.Position).Magnitude < range then
            local color = Color3.new(1, 1, 1)
            local targetHumanoid = entity:FindFirstChildOfClass("Humanoid")
            if targetHumanoid and not entity:HasTag("NoVisibleDamage") then
              local health = targetHumanoid.Health / targetHumanoid.MaxHealth
              if health < 0.33 then
                color = Color3.fromRGB(255, 0, 0)
              elseif health < 0.66 then
                color = Color3.fromRGB(255, 179, 0)
              end
            end
            clientEffect:Fire("sonarsmall", {pos = entityRoot.Position, col = color})
          end
        end
      end
    end
  end

  local function canDeactivate()
    return not RHYTHM_SPOOFER.startTime
      or G.ck() - RHYTHM_SPOOFER.startTime >= settings.minimumDuration
  end

  local function stopRhythm(immediate)
    if not RHYTHM_SPOOFER.active then return end
    RHYTHM_SPOOFER.active = false
    RHYTHM_SPOOFER.generation = RHYTHM_SPOOFER.generation + 1
    local generation = RHYTHM_SPOOFER.generation
    RHYTHM_SPOOFER.startTime = nil
    RHYTHM_SPOOFER.pendingStop = false
    RHYTHM_SPOOFER.debounce = true
    RHYTHM_SPOOFER.entityTimestamps = {}

    stopAnimation()
    if immediate then
      stopSound()
    else
      RHYTHM_SPOOFER.sound = nil
    end
    deactivateLighting(immediate, generation)
    stopAmbientOverride(immediate)

    task.delay(0.2, function()
      if RHYTHM_SPOOFER.generation == generation then
        RHYTHM_SPOOFER.debounce = false
      end
    end)
  end

  local function startRhythm()
    if RHYTHM_SPOOFER.debounce or RHYTHM_SPOOFER.active then return end
    RHYTHM_SPOOFER.active = true
    RHYTHM_SPOOFER.generation = RHYTHM_SPOOFER.generation + 1
    local generation = RHYTHM_SPOOFER.generation
    RHYTHM_SPOOFER.startTime = G.ck()
    RHYTHM_SPOOFER.pendingStop = false
    RHYTHM_SPOOFER.debounce = true

    task.spawn(function()
      playAnimation()
      task.wait(0.1)
      if not RHYTHM_SPOOFER.active or RHYTHM_SPOOFER.generation ~= generation then return end
      playSound()

      task.wait(0.2)
      if not RHYTHM_SPOOFER.active or RHYTHM_SPOOFER.generation ~= generation then return end
      if not isCrouching() then
        stopRhythm(true)
        return
      end

      activateLighting()
      startAmbientOverride()
      RHYTHM_SPOOFER.entityTimestamps = {}
      detectEntities()

      task.spawn(function()
        while RHYTHM_SPOOFER.active and RHYTHM_SPOOFER.generation == generation do
          task.wait(0.2)
          detectEntities()
        end
      end)

      for _ = 1, 10 do
        if not RHYTHM_SPOOFER.active or RHYTHM_SPOOFER.generation ~= generation then return end
        task.spawn(createSonar)
        task.wait(0.1)
      end

      task.wait(0.7)
      if RHYTHM_SPOOFER.generation == generation then
        RHYTHM_SPOOFER.debounce = false
      end
    end)
  end

  local function onRhythmInput(input, processed)
    if processed or not RHYTHM_SPOOFER.enabled or hasRhythmTalent() then return end
    if input.KeyCode ~= rhythmKey() then return end

    if RHYTHM_SPOOFER.active then
      if canDeactivate() then
        stopRhythm(false)
      else
        RHYTHM_SPOOFER.pendingStop = true
      end
    elseif canUseRhythm() then
      startRhythm()
    end
  end

  local function updateRhythm()
    if not RHYTHM_SPOOFER.active then return end
    if not RHYTHM_SPOOFER.enabled then
      stopRhythm(true)
      return
    end

    if canDeactivate() and (RHYTHM_SPOOFER.pendingStop or not canUseRhythm()) then
      stopRhythm(false)
    end
  end

  function RHYTHM_SPOOFER:start()
    if self.enabled then return end
    self.enabled = true
    self.key = nil
    rhythmKey()
    self.inputConn = G.UIS.InputBegan:Connect(onRhythmInput)
    self.heartbeatConn = G.RS.Heartbeat:Connect(updateRhythm)
    self.characterConn = G.LP.CharacterAdded:Connect(function()
      self.animationTrack = nil
      self.sound = nil
      if self.active then stopRhythm(true) end
    end)
  end

  function RHYTHM_SPOOFER:stop()
    self.enabled = false
    if self.active then stopRhythm(true) end
    if self.inputConn then self.inputConn:Disconnect() self.inputConn = nil end
    if self.heartbeatConn then self.heartbeatConn:Disconnect() self.heartbeatConn = nil end
    if self.characterConn then self.characterConn:Disconnect() self.characterConn = nil end
    stopAmbientOverride(true)
    stopAnimation()
    stopSound()

    if self.colorCorrection then
      self.colorCorrection:Destroy()
      self.colorCorrection = nil
    end
    self.key = nil
    self.effects = nil
    self.entityTimestamps = {}
    self.pendingStop = false
    self.debounce = false
  end
end
local GLOBAL_CHAT = {active=false, conns={}, gui=nil, scr=nil}
do
  function GLOBAL_CHAT.en()
    if GLOBAL_CHAT.active then return end; GLOBAL_CHAT.active = true
    if not GLOBAL_CHAT.gui then
      local g = G.new("ScreenGui")
      g.Name = "Katalyst_GlobalChat"
      g.ResetOnSpawn = false
      pcall(function() if syn and syn.protect_gui then syn.protect_gui(g) elseif protectgui then protectgui(g) end end)
      g.Parent = game:GetService("CoreGui") or G.LP:WaitForChild("PlayerGui")
      
      local f = G.new("Frame", g)
      f.Size = G.UD2(0, 300, 0, 200)
      f.Position = G.UD2(1, -310, 1, -250)
      f.BackgroundColor3 = G.RGB(15, 10, 25)
      f.BackgroundTransparency = 0.3
      f.BorderSizePixel = 0
      G.mkC(f, 6)
      
      local hdr = G.new("TextLabel", f)
      hdr.Size = G.UD2(1, 0, 0, 20)
      hdr.BackgroundTransparency = 1
      hdr.Text = " GLOBAL CHAT SPY"
      hdr.TextColor3 = G.RGB(140, 60, 255)
      hdr.Font = Enum.Font.GothamBold
      hdr.TextSize = 12
      hdr.TextXAlignment = Enum.TextXAlignment.Left
      
      local scr = G.new("ScrollingFrame", f)
      scr.Size = G.UD2(1, -10, 1, -25)
      scr.Position = G.UD2(0, 5, 0, 20)
      scr.BackgroundTransparency = 1
      scr.BorderSizePixel = 0
      scr.ScrollBarThickness = 4
      scr.AutomaticCanvasSize = Enum.AutomaticSize.Y
      scr.CanvasSize = G.UD2(0, 0, 0, 0)
      
      local lay = G.new("UIListLayout", scr)
      lay.SortOrder = Enum.SortOrder.LayoutOrder
      lay.Padding = G.UD(0, 2)
      
      GLOBAL_CHAT.gui = g
      GLOBAL_CHAT.scr = scr
    end
    GLOBAL_CHAT.gui.Enabled = true
    
    local order = 0
    local recentMsgs = {}
    local function addMsg(name, txt)
      if not GLOBAL_CHAT.active or not name or not txt then return end
      local now = os.clock()
      local hash = tostring(name) .. "::" .. tostring(txt)
      if recentMsgs[hash] and (now - recentMsgs[hash]) < 1.5 then return end
      recentMsgs[hash] = now
      order = order + 1
      local lbl = G.new("TextLabel", GLOBAL_CHAT.scr)
      lbl.BackgroundTransparency = 1
      lbl.Size = G.UD2(1, 0, 0, 0)
      lbl.AutomaticSize = Enum.AutomaticSize.Y
      lbl.Font = Enum.Font.Gotham
      lbl.TextSize = 12
      lbl.TextColor3 = G.RGB(230, 225, 245)
      lbl.TextXAlignment = Enum.TextXAlignment.Left
      lbl.TextWrapped = true
      lbl.RichText = true
      lbl.Text = "<b>["..name.."]:</b> "..txt
      lbl.LayoutOrder = order
      
      local msgs = GLOBAL_CHAT.scr:GetChildren()
      local count = 0
      for _, v in ipairs(msgs) do if v:IsA("TextLabel") then count = count + 1 end end
      if count > 50 then
        for _, v in ipairs(msgs) do
          if v:IsA("TextLabel") then v:Destroy(); break end
        end
      end
      
      task.delay(0.1, function()
        GLOBAL_CHAT.scr.CanvasPosition = Vector2.new(0, 999999)
      end)
    end
    
    local function onPlr(p)
      local c = p.Chatted:Connect(function(msg)
        addMsg(p.Name, msg)
      end)
      table.insert(GLOBAL_CHAT.conns, c)
    end
    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
      if p ~= G.LP then onPlr(p) end
    end
    local c2 = game:GetService("Players").PlayerAdded:Connect(onPlr)
    table.insert(GLOBAL_CHAT.conns, c2)
    pcall(function()
      local tcs = game:GetService("TextChatService")
      if tcs.ChatVersion == Enum.ChatVersion.TextChatService then
        local c3 = tcs.MessageReceived:Connect(function(txtMsg)
          if txtMsg.TextSource and txtMsg.TextSource.UserId ~= G.LP.UserId then
            local p = game:GetService("Players"):GetPlayerByUserId(txtMsg.TextSource.UserId)
            local name = p and p.Name or "Unknown"
            addMsg(name, txtMsg.Text)
          end
        end)
        table.insert(GLOBAL_CHAT.conns, c3)
      end
    end)
  end
  
  function GLOBAL_CHAT.dis()
    GLOBAL_CHAT.active = false
    if GLOBAL_CHAT.gui then GLOBAL_CHAT.gui.Enabled = false end
    for _, c in ipairs(GLOBAL_CHAT.conns) do c:Disconnect() end
    GLOBAL_CHAT.conns = {}
  end
end
local IESP = {gui=nil,lbls={},conn=nil,lastScan=0,tracked={}}
do
  local IGN={Baseplate=1,Terrain=1,Camera=1,Live=1,Effects=1,Ignore=1,Projectiles=1}
  local function isItem(i) if i:IsA("Tool") or i:IsA("Accessory") then return true end
    if i:IsA("Model") then if i:FindFirstChildOfClass("Humanoid") then return false end; if i:FindFirstChild("Handle") or i:FindFirstChildOfClass("ClickDetector") then return true end end
    if i:IsA("BasePart") and i:FindFirstChildOfClass("ClickDetector") then return true end; return false end
  local function iPos(i) if i:IsA("Model") then local p=i.PrimaryPart or i:FindFirstChildWhichIsA("BasePart"); return p and p.Position
    elseif i:IsA("BasePart") then return i.Position
    elseif i:IsA("Tool") or i:IsA("Accessory") then local h=i:FindFirstChild("Handle"); return h and h.Position end; return nil end
  function IESP.mkG() if IESP.gui and IESP.gui.Parent then return IESP.gui end
    IESP.gui=G.new("ScreenGui"); IESP.gui.Name=UC.RN.."_I"; IESP.gui.ResetOnSpawn=false; IESP.gui.IgnoreGuiInset=true; IESP.gui.DisplayOrder=99
    IESP.gui:SetAttribute("KI",true); G.protG(IESP.gui); IESP.gui.Parent=G.getHP(); return IESP.gui end
  function IESP.clr() for _,l in pairs(IESP.lbls) do pcall(function() l:Destroy() end) end; G.tc(IESP.lbls); G.tc(IESP.tracked); if IESP.gui then pcall(function() IESP.gui:Destroy() end); IESP.gui=nil end end
  
  local function scanFolders()
    local list = {}
    local myC = G.LP and G.LP.Character
    local function checkItem(ch)
      if not ch or ch == myC then return end
      if IGN[ch.Name] then return end
      if isItem(ch) then table.insert(list, ch) end
    end
    for _, ch in ipairs(game.Workspace:GetChildren()) do
      checkItem(ch)
    end
    local function scanFolder(f, d)
      if not f or d > 3 then return end
      for _, ch in ipairs(f:GetChildren()) do
        if not (IGN[ch.Name] or ch == myC or ch:FindFirstChildOfClass("Humanoid")) then
          if isItem(ch) then
            table.insert(list, ch)
          elseif ch:IsA("Folder") or ch:IsA("Model") then
            scanFolder(ch, d + 1)
          end
        end
      end
    end
    for _, n in ipairs({"Drops","Items","Loot","DroppedItems","Thrown","Interactables","Collectibles","Chest","Chests"}) do
      local f = game.Workspace:FindFirstChild(n)
      if f then scanFolder(f, 0) end
    end
    return list
  end

  function IESP.upd()
    if not S.iEsp or S.str then for _,l in pairs(IESP.lbls) do if l.Visible then l.Visible=false end end; return end
    local cam=G.WS.CurrentCamera; if not cam then return end; local mr=G.myR(); if not mr then return end
    
    local now = os.clock()
    if now - IESP.lastScan > 1.5 then
      IESP.lastScan = now
      local found = scanFolders()
      local foundMap = {}
      for _, item in ipairs(found) do
        foundMap[item] = true
        IESP.tracked[item] = true
      end
      for item, lb in pairs(IESP.lbls) do
        if not foundMap[item] or not item.Parent then
          pcall(function() lb:Destroy() end)
          IESP.lbls[item] = nil
          IESP.tracked[item] = nil
        end
      end
    end
    
    local mp=mr.Position; local rsq=CFG.ItemEspRange*CFG.ItemEspRange; local gui=IESP.mkG()
    for item in pairs(IESP.tracked) do
      if item.Parent then
        local pos = iPos(item)
        if pos then
          local dx,dy,dz=pos.X-mp.X,pos.Y-mp.Y,pos.Z-mp.Z; local dsq=dx*dx+dy*dy+dz*dz
          if dsq<=rsq then
            local sp=cam:WorldToViewportPoint(pos)
            if sp.Z>0 then
              local lb=IESP.lbls[item]
              if not lb then
                lb=G.new("TextLabel"); lb.BackgroundColor3=G.RGB(10,5,20); lb.BackgroundTransparency=0.3; lb.BorderSizePixel=0
                lb.AnchorPoint=G.V2(0.5,0.5); lb.AutomaticSize=Enum.AutomaticSize.X; lb.Size=G.UD2(0,0,0,18)
                lb.Font=Enum.Font.GothamBold; lb.TextSize=11; lb.TextColor3=P.itm; lb.TextStrokeTransparency=0.2; lb.Parent=gui
                G.mkC(lb,4); local pd=G.new("UIPadding",lb); pd.PaddingLeft=G.UD(0,6); pd.PaddingRight=G.UD(0,6); IESP.lbls[item]=lb
              end
              lb.Position=G.UD2(0,sp.X,0,sp.Y); lb.Text=item.Name.." ["..G.mr(G.sq(dsq)).."m]"; lb.Visible=true
            else
              local lb=IESP.lbls[item]
              if lb then lb.Visible=false end
            end
          else
            local lb=IESP.lbls[item]
            if lb then lb.Visible=false end
          end
        end
      end
    end
  end
  function IESP.start() if not _verifySessionIntegrity() then while true do end end; if IESP.conn then return end; IESP.lastScan=0; IESP.mkG(); IESP.conn=G.RS.Heartbeat:Connect(IESP.upd) end
  function IESP.stop() if IESP.conn then IESP.conn:Disconnect(); IESP.conn=nil end; IESP.clr() end
end

local MESP = {gui=nil, espF={}, conn=nil, poserStates={}, healthConns={}, lastHealths={},
       calibratedBurstPerHit=nil, wasArmed=false, efr=nil, seenEffects={}}
do
  function MESP.mkEG()
    if MESP.gui and MESP.gui.Parent then return MESP.gui end
    MESP.gui=G.new("ScreenGui"); MESP.gui.Name=UC.RN.."_ME"; MESP.gui.ResetOnSpawn=false; MESP.gui.IgnoreGuiInset=true; MESP.gui.DisplayOrder=101
    MESP.gui:SetAttribute("KI",true); G.protG(MESP.gui); MESP.gui.Parent=G.getHP(); return MESP.gui
  end
  function MESP.mkEF(m)
    if MESP.espF[m] then return end; local g=MESP.mkEG()
    local ct=G.new("Frame"); ct.BackgroundTransparency=1; ct.BorderSizePixel=0; ct.Visible=false; ct.Parent=g
    local bx=G.new("Frame",ct); bx.Name="Box"; bx.BackgroundTransparency=1; bx.Size=G.UD2(1,0,1,0); bx.BorderSizePixel=0; G.new("UIStroke",bx).Color=G.RGB(255,100,0); bx:FindFirstChildOfClass("UIStroke").Thickness=1.2
    local hb=G.new("Frame",ct); hb.Size=G.UD2(0,3,1,0); hb.Position=G.UD2(0,-6,0,0); hb.BackgroundColor3=G.RGB(8,8,8); hb.BorderSizePixel=0
    local hf=G.new("Frame",hb); hf.BackgroundColor3=G.RGB(0,255,0); hf.BorderSizePixel=0; hf.Size=G.UD2(1,0,1,0); hf.AnchorPoint=G.V2(0,1); hf.Position=G.UD2(0,0,1,0)
    local dl=G.new("TextLabel",ct); dl.BackgroundTransparency=1; dl.AnchorPoint=G.V2(0.5,0); dl.Position=G.UD2(0.5,0,1,2); dl.Size=G.UD2(0,250,0,12)
    dl.Font=Enum.Font.GothamMedium; dl.TextSize=10; dl.TextColor3=G.RGB(200,200,200); dl.TextStrokeTransparency=0.4
    local kl=G.new("TextLabel",ct); kl.BackgroundTransparency=1; kl.AnchorPoint=G.V2(0.5,0); kl.Position=G.UD2(0.5,0,1,14); kl.Size=G.UD2(0,250,0,12)
    kl.Font=Enum.Font.GothamBold; kl.TextSize=9; kl.TextColor3=G.RGB(255,220,50); kl.TextStrokeTransparency=0.4
    MESP.espF[m]={Ct=ct,HF=hf,DL=dl,KL=kl}
  end
  function MESP.clr()
    for _,d in pairs(MESP.espF) do d.Ct:Destroy() end; G.tc(MESP.espF);
    if MESP.gui then MESP.gui:Destroy(); MESP.gui=nil end
  end
  
  -- Called when a landed hit is detected via EffectReplicator
  function MESP.triggerHitCount()
    local lpChar = G.LP.Character
    local root = lpChar and lpChar:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local bestTgt, bestDist = nil, 20
    local live = G.WS:FindFirstChild("Live") or G.WS
    for _, m in ipairs(live:GetChildren()) do
      if m:IsA("Model") and m ~= lpChar and not G.Plrs:GetPlayerFromCharacter(m) then
        local eRoot = m:FindFirstChild("HumanoidRootPart")
        local eHum = m:FindFirstChildOfClass("Humanoid")
        if eRoot and eHum and eHum.Health > 0 then
          local dist = (eRoot.Position - root.Position).Magnitude
          if dist < bestDist then
            local dir = (eRoot.Position - root.Position).Unit
            local dot = root.CFrame.LookVector:Dot(dir)
            if dot > 0.35 then
              bestDist = dist; bestTgt = m
            end
          end
        end
      end
    end
    if bestTgt then
      if not MESP.poserStates[bestTgt] then
        MESP.poserStates[bestTgt] = { hits = 0 }
      end
      local ps = MESP.poserStates[bestTgt]
      -- If starting a new combo, clear previous calibration tracker
      if ps.hits == 0 then
        ps.hitsAtPop = nil
      end
      ps.hits = ps.hits + 1
    end
  end
  
  
  -- Calculated Poser & M1 Damage Fallback based on Deepwoken Damage Formulas
  function MESP.getTheoreticalPoserDamage(displayHits, mobModel)
    local char = G.LP.Character
    if not char then return 0 end
    
    local statVal = char:GetAttribute("Medium Weapon") or char:GetAttribute("Heavy Weapon") or char:GetAttribute("Light Weapon") or 75
    local profVal = char:GetAttribute("Proficiency") or 5
    local wepBase = char:GetAttribute("WeaponBase") or 22
    local scaling = char:GetAttribute("WeaponScaling") or 0.28
    
    -- PvE Specific Multipliers (Monster Dmg %, Charms, Talents)
    local pveBonus = char:GetAttribute("PvEDamage") or char:GetAttribute("MonsterDamage") or char:GetAttribute("DmgVsMonsters") or 0.25
    local generalDmgMulti = char:GetAttribute("DamageMultiplier") or 0.15
    
    -- Base M1 Hit Dmg
    local rawDmg = wepBase + (statVal * scaling) + (profVal * 2.5)
    local pveDmgPerHit = rawDmg * (1 + generalDmgMulti) * (1 + pveBonus)
    
    -- Mob Defense Factor (Bosses vs Normal Mobs)
    local mobName = mobModel and mobModel.Name or ""
    local mobDefense = 0.0 -- Standard mob 0% armor
    if string.find(mobName, "Ferryman") or string.find(mobName, "Duke") or string.find(mobName, "Chaser") then
      mobDefense = 0.20 -- 20% Boss Armor Reduction
    end
    
    local netDmgPerHit = pveDmgPerHit * (1 - mobDefense)
    
    -- Poser's Ring PvE Burst Multiplier (1.5x stored damage)
    return math.floor(netDmgPerHit * displayHits * 1.5)
  end

  function MESP.upd()
    -- Throttle mob ESP heavy calculations to reduce frame load
    local now = os.clock()
    MESP.lastUpdate = now
    if not S.mobEsp or S.str then
      for _,d in pairs(MESP.espF) do if d.Ct.Visible then d.Ct.Visible=false end end
      return
    end
    local cam=G.WS.CurrentCamera; if not cam then return end; local mr=G.myR(); if not mr then return end
    local mp=mr.Position; local rsq=CFG.EspRange*CFG.EspRange
    
    -- Detect weapon equipped/unequipped
    local lpChar = G.LP.Character
    local hasWeapon = false
    if lpChar then
      if lpChar:FindFirstChildOfClass("Tool") then
        hasWeapon = true
      else
        local rh = lpChar:FindFirstChild("RightHand") or lpChar:FindFirstChild("Right Hand")
        if rh and rh:FindFirstChild("HandWeapon") then
          hasWeapon = true
        end
      end
    end
    
    -- Detect weapon draw (equip) -> Reset hits on all targets (new fight starting)
    if not MESP.wasArmed and hasWeapon then
      for _, ps in pairs(MESP.poserStates) do
        ps.hits = 0
        ps.hitsAtPop = nil
      end
    end
    
    -- Detect weapon unequip = Poser burst fired
    if MESP.wasArmed and not hasWeapon then
      -- Weapon just unequipped -> burst is firing.
      -- Save hits per-target for calibration before resetting them.
      MESP.poserJustPopped = true
      for m, ps in pairs(MESP.poserStates) do
        if ps.hits and ps.hits > 0 then
          ps.hitsAtPop = ps.hits
          ps.hits = 0
        end
      end
      task.delay(1.2, function()
        MESP.poserJustPopped = false
        for _, ps in pairs(MESP.poserStates) do
          ps.hitsAtPop = nil
        end
      end)
    end
    MESP.wasArmed = hasWeapon
    
    local seen = {}
    local live=G.WS:FindFirstChild("Live") or G.WS
    local filter = CFG.MobEspFilter
    local filterActive = filter and filter ~= "" and filter ~= "ALL"
    local filterLower = filterActive and string.lower(filter) or ""

    for _,m in ipairs(live:GetChildren()) do
      if m:IsA("Model") and m ~= G.LP.Character and not G.Plrs:GetPlayerFromCharacter(m) then
        local passesFilter = true
        if filterActive then
          passesFilter = string.find(string.lower(m.Name), filterLower, 1, true) ~= nil
        end
        if not passesFilter then
          if MESP.espF[m] and MESP.espF[m].Ct and MESP.espF[m].Ct.Visible then
            MESP.espF[m].Ct.Visible = false
          end
        else
          local r = m:FindFirstChild("HumanoidRootPart")
        local h = m:FindFirstChildOfClass("Humanoid")
        if r and h and h.Health > 0 then
          seen[m] = true
          if not MESP.espF[m] then MESP.mkEF(m) end
          local ed = MESP.espF[m]
          local rp=r.Position; local dx,dy,dz=rp.X-mp.X,rp.Y-mp.Y,rp.Z-mp.Z; local dsq=dx*dx+dy*dy+dz*dz
          local show = false
          if dsq<=rsq then
            local rs, vis=cam:WorldToViewportPoint(rp)
            if rs.Z>0 then
              local ts2=cam:WorldToViewportPoint(rp+G.V3(0,3,0)); local bs=cam:WorldToViewportPoint(rp-G.V3(0,3.5,0))
              local sh=G.mx(bs.Y-ts2.Y,14); local sw=sh*0.55; local cx=(ts2.X+bs.X)*0.5
              ed.Ct.Position=G.UD2(0,cx-sw*0.5,0,ts2.Y); ed.Ct.Size=G.UD2(0,sw,0,sh)
              
              local chp = h.Health
              local maxHp = h.MaxHealth
              local hp2=G.mc(chp/G.mx(1,maxHp),0,1)
              ed.HF.Size=G.UD2(1,0,hp2,0); ed.HF.BackgroundColor3=G.C3(G.mc((1-hp2)*2,0,1),G.mc(hp2*2,0,1),0)
              
              if not MESP.poserStates[m] then
                MESP.poserStates[m] = { hits = 0 }
              end
              
              -- Health tracking: detect Poser burst for auto-calibration
              if not MESP.healthConns[m] then
                MESP.lastHealths[m] = chp
                MESP.healthConns[m] = h:GetPropertyChangedSignal("Health"):Connect(function()
                  pcall(function()
                    local current = h.Health
                    local old = MESP.lastHealths[m] or current
                    
                    if current <= 0 then
                      local targetPs = MESP.poserStates[m]
                      if targetPs then
                        targetPs.hits = 0
                        targetPs.hitsAtPop = nil
                      end
                    elseif current > old then
                      local targetPs = MESP.poserStates[m]
                      if targetPs then
                        targetPs.hits = 0
                        targetPs.hitsAtPop = nil
                      end
                    elseif current < old then
                      local drop = old - current
                      local targetPs = MESP.poserStates[m]
                      if targetPs then
                        local char = G.LP.Character
                        local lpArmed = false
                        if char then
                          if char:GetAttribute("Equipped") or char:GetAttribute("HasWeapon") or char:GetAttribute("WeaponEquipped") or char:FindFirstChildOfClass("Tool") then
                            lpArmed = true
                          else
                            local rh = char:FindFirstChild("RightHand") or char:FindFirstChild("Right Hand")
                            if rh and rh:FindFirstChild("HandWeapon") then
                              lpArmed = true
                            end
                          end
                        end
                        
                        local hitsToCalibrate = (targetPs.hits and targetPs.hits > 0 and targetPs.hits) or targetPs.hitsAtPop
                        if MESP.poserJustPopped and hitsToCalibrate and hitsToCalibrate > 0 then
                          MESP.calibratedBurstPerHit = drop / hitsToCalibrate
                          MESP.poserJustPopped = false
                          targetPs.hits = 0
                          targetPs.hitsAtPop = nil
                        else
                          local root = char and char:FindFirstChild("HumanoidRootPart")
                          local eRoot = m:FindFirstChild("HumanoidRootPart")
                          if root and eRoot and (eRoot.Position - root.Position).Magnitude < 22 then
                            targetPs.hits = (targetPs.hits or 0) + 1
                          end
                        end
                      end
                    end
                    MESP.lastHealths[m] = current
                  end)
                end)
              end
              
              local ps = MESP.poserStates[m]
              local actualHp = math.floor(chp)
              local maxHpFloor = math.floor(maxHp)
              
              -- Predict burst damage
              local predictedBurst = 0
              local canKill = false
              local calibrated = MESP.calibratedBurstPerHit ~= nil
              local currentHits = ps.hits or 0
              local displayHits = currentHits
              local isBurstActive = false
              
              if displayHits == 0 and ps.hitsAtPop and ps.hitsAtPop > 0 then
                displayHits = ps.hitsAtPop
                isBurstActive = true
              end
              
              if displayHits > 0 and calibrated then
                predictedBurst = math.floor(MESP.calibratedBurstPerHit * displayHits)
                canKill = predictedBurst >= actualHp
              end
              
              -- Box outline: green = KILL, orange = normal
              local stroke = ed.Ct:FindFirstChild("Box") and ed.Ct.Box:FindFirstChildOfClass("UIStroke")
              if stroke then
                stroke.Color = canKill and G.RGB(0,255,80) or G.RGB(255,100,0)
              end
              
              ed.DL.Text=m.Name.." ["..G.mr(G.sq(dsq)).."m] "..actualHp.."/"..maxHpFloor.." HP"
              
              if (S.espPoser or S.mobEsp) and ed.KL then
                if displayHits > 0 then
                  if calibrated then
                    local labelPrefix = isBurstActive and "Poser (POP!): " or "Poser: "
                    ed.KL.Text=labelPrefix..predictedBurst.." dmg | "..displayHits.." hits "..(canKill and "| KILL" or "| NO")
                    ed.KL.TextColor3 = canKill and G.RGB(0,255,80) or (isBurstActive and G.RGB(255,165,0) or G.RGB(255,80,80))
                  else
                    local labelPrefix = isBurstActive and "Poser (POP!): " or "Poser: "
                    local est = MESP.getTheoreticalPoserDamage(displayHits, m)
                    local estKill = est >= actualHp
                    ed.KL.Text=labelPrefix..displayHits.." hits (~"..est.." dmg)"..(estKill and " | KILL" or "")
                    ed.KL.TextColor3 = estKill and G.RGB(0,255,80) or G.RGB(255,220,50)
                  end
                else
                  if calibrated then
                    ed.KL.Text="Calibrated: "..math.floor(MESP.calibratedBurstPerHit).." burst/hit"
                    ed.KL.TextColor3 = G.RGB(100,200,255)
                  else
                    ed.KL.Text=""
                  end
                end
              end
              
              show=true
            end
          end
          ed.Ct.Visible=show
          end
        end
      end
    end
    for m,ed in pairs(MESP.espF) do
      if not seen[m] or not m.Parent then
        ed.Ct:Destroy(); MESP.espF[m]=nil
        if MESP.healthConns[m] then MESP.healthConns[m]:Disconnect(); MESP.healthConns[m]=nil end
        MESP.lastHealths[m] = nil
        MESP.poserStates[m] = nil
      end
    end
  end

  function MESP.start() if not _verifySessionIntegrity() then while true do end end
    if MESP.conn then return end; 
    MESP.mkEG(); 
    MESP.healthConns = MESP.healthConns or {}
    MESP.lastHealths = MESP.lastHealths or {}
    MESP.poserStates = MESP.poserStates or {}
    MESP.wasArmed = false
    MESP.seenEffects = {}
    
    -- Try to load EffectReplicator for accurate hit detection
    MESP.efr = nil
    pcall(function()
      MESP.efr = require(G.RepS:FindFirstChild("EffectReplicator") or G.RepS:WaitForChild("EffectReplicator", 2))
    end)
    
    MESP.conn=G.RS.Heartbeat:Connect(MESP.upd) 
  end
  function MESP.stop() 
    if MESP.conn then MESP.conn:Disconnect(); MESP.conn=nil end; 
    for m, c in pairs(MESP.healthConns) do c:Disconnect() end
    MESP.healthConns = {}
    MESP.lastHealths = {}
    MESP.clr()
  end
end

CUSTOM_VISUALS_STANCE_NAMES = {
    [1] = "Default",
    [2] = "Blade Forward",
    [3] = "Void Stance",
    [4] = "Shinobi Guard",
    [5] = "Reverse Grip",
    [6] = "Reaper Hold",
}

CUSTOM_VISUALS_ENGINE = {
    active = false,
    currentStance = 1,
    conn = nil,
