    rightShoulder = nil,
    originalShoulderC0 = nil
}

FROST_HUD_ENGINE = {
    active = false,
    hookConn = nil,
    descConn = nil,
    savedColors = {}
}

BANKAI_ENGINE = {
    active = false,
    persistentMode = false,
    cooldown = false,
    objects = {},
    camShakeConn = nil,
    rotConn = nil,
    stepConn = nil,
    haloPart = nil,
