}

do
    -- Audio playback helper (Stereo / direct sound, no 3D attenuation)
    local function playDirectAudio(soundId, volume, pitch)
        pcall(function()
            local ss = game:GetService("SoundService")
            local snd = Instance.new("Sound")
            snd.SoundId = soundId
            snd.Volume = volume or 1.0
            snd.PlaybackSpeed = pitch or 1.0
            snd.RollOffMaxDistance = 100000
            snd.Parent = ss
            
            if ss.PlayLocalSound then
                ss:PlayLocalSound(snd)
            else
                snd:Play()
            end
            
            game:GetService("Debris"):AddItem(snd, 4.0)
        end)
    end

    -- Infallible Deepwoken weapon part resolver
    local function findWeaponPart(char)
        if not char then return nil end
        local rArm = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")

        if rArm then
            for _, v in ipairs(char:GetDescendants()) do
                if (v:IsA("Motor6D") or v:IsA("Weld") or v:IsA("WeldConstraint")) then
                    if v.Part0 == rArm and v.Part1 and v.Part1:IsA("BasePart") and v.Part1 ~= char:FindFirstChild("Torso") and v.Part1 ~= char:FindFirstChild("Head") then
                        return v.Part1
                    elseif v.Part1 == rArm and v.Part0 and v.Part0:IsA("BasePart") and v.Part0 ~= char:FindFirstChild("Torso") and v.Part0 ~= char:FindFirstChild("Head") then
                        return v.Part0
                    end
                end
            end
        end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Model") and child.Name ~= char.Name then
                for _, p in ipairs(child:GetDescendants()) do
                    if p:IsA("BasePart") and (p:FindFirstChildOfClass("SpecialMesh") or p:IsA("MeshPart") or string.find(string.lower(p.Name), "handle") or string.find(string.lower(p.Name), "blade") or string.find(string.lower(p.Name), "sword")) then
                        return p
                    end
                end
            end
        end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") then
                local h = child:FindFirstChild("Handle") or child:FindFirstChildWhichIsA("BasePart")
                if h then return h end
            end
        end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("BasePart") then
                local n = string.lower(child.Name)
                if string.find(n, "blade") or string.find(n, "sword") or string.find(n, "weapon") 
                or string.find(n, "dagger") or string.find(n, "spear") or string.find(n, "axe") 
                or string.find(n, "scythe") or string.find(n, "staff") or string.find(n, "cestus") then
                    return child
                end
            end
        end

        return rArm
    end

    -- ==========================================
    -- 1. FROST HP BAR & HUD THEME ENGINE
    -- ==========================================
    local ICE_BLUE_ACCENT = G.RGB(70, 185, 255)
    local ICE_BLUE_GLOW   = G.RGB(170, 235, 255)
    local ICE_BLUE_DEEP   = G.RGB(25, 100, 215)

    local function isHealthOrStatBar(obj)
        if not obj or not obj.Parent then return false end
        local n = string.lower(obj.Name)
        local pName = string.lower(obj.Parent.Name)
        
        if string.find(n, "health") or string.find(n, "hp") or string.find(n, "posture") or string.find(n, "ether")
        or string.find(pName, "health") or string.find(pName, "hp") or string.find(pName, "stat") or string.find(pName, "bar") then
            if obj:IsA("Frame") or obj:IsA("ImageLabel") or obj:IsA("UIGradient") then
                return true
            end
        end
        return false
    end

    local function applyFrostToElement(elem)
        if not elem or not elem.Parent then return end
        if not FROST_HUD_ENGINE.savedColors[elem] then
            if elem:IsA("Frame") then
                FROST_HUD_ENGINE.savedColors[elem] = {type = "Frame", bg = elem.BackgroundColor3}
            elseif elem:IsA("ImageLabel") then
                FROST_HUD_ENGINE.savedColors[elem] = {type = "ImageLabel", col = elem.ImageColor3}
            elseif elem:IsA("UIGradient") then
                FROST_HUD_ENGINE.savedColors[elem] = {type = "UIGradient", col = elem.Color}
            end
        end

        pcall(function()
            if elem:IsA("Frame") then
                elem.BackgroundColor3 = ICE_BLUE_ACCENT
            elseif elem:IsA("ImageLabel") then
                elem.ImageColor3 = ICE_BLUE_GLOW
            elseif elem:IsA("UIGradient") then
                elem.Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, ICE_BLUE_GLOW),
                    ColorSequenceKeypoint.new(0.5, ICE_BLUE_ACCENT),
                    ColorSequenceKeypoint.new(1, ICE_BLUE_DEEP)
                })
            end
        end)
    end

    local function restoreElement(elem, data)
        pcall(function()
            if not elem or not elem.Parent or not data then return end
            if data.type == "Frame" and data.bg then
                elem.BackgroundColor3 = data.bg
            elseif data.type == "ImageLabel" and data.col then
                elem.ImageColor3 = data.col
            elseif data.type == "UIGradient" and data.col then
                elem.Color = data.col
            end
        end)
    end

    function FROST_HUD_ENGINE:scanAndApply()
        local lp = G.LP
        local pg = lp and (lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui"))
        if not pg then return end

        for _, desc in ipairs(pg:GetDescendants()) do
            if isHealthOrStatBar(desc) then
                applyFrostToElement(desc)
            end
        end
    end

    function FROST_HUD_ENGINE:start()
        if self.active then return end
        self.active = true

        self:scanAndApply()

        local lp = G.LP
        local pg = lp and (lp:FindFirstChildOfClass("PlayerGui") or lp:FindFirstChild("PlayerGui"))
        if pg then
            self.descConn = trk(pg.DescendantAdded:Connect(function(desc)
                if not self.active then return end
                if isHealthOrStatBar(desc) then
                    G.ts(function()
                        G.tw(0.05)
                        applyFrostToElement(desc)
                    end)
                end
            end))
        end

        self.hookConn = trk(G.RS.Heartbeat:Connect(function()
            if not self.active then return end
            self:scanAndApply()
        end))
    end

    function FROST_HUD_ENGINE:stop()
        if not self.active then return end
        self.active = false

        if self.hookConn then self.hookConn:Disconnect() self.hookConn = nil end
        if self.descConn then self.descConn:Disconnect() self.descConn = nil end

        for elem, data in pairs(self.savedColors) do
            restoreElement(elem, data)
        end
        G.tc(self.savedColors)
    end

    -- ==========================================
    -- 2. ORGANIC CINEMATIC FROST VIGNETTE OVERLAY
    -- ==========================================
    local function createOrganicFrostOverlay(guiParent)
        local sg = G.new("ScreenGui")
        sg.Name = "BankaiOrganicFrost"
        sg.IgnoreGuiInset = true
        sg.DisplayOrder = 999999
        sg.ResetOnSpawn = false
        if G.protG then G.protG(sg) end
