        -- Soft radial shadow vignette with ice-blue grading
        local vignette = G.new("ImageLabel", sg)
        vignette.Size = UDim2.new(1, 0, 1, 0)
        vignette.Position = UDim2.new(0, 0, 0, 0)
        vignette.BackgroundTransparency = 1
        vignette.Image = "rbxassetid://6014261993"
        vignette.ImageColor3 = G.RGB(130, 210, 255)
        vignette.ImageTransparency = 0.5
        vignette.BorderSizePixel = 0

        -- Secondary cold frost rim
        local edgeMist = G.new("ImageLabel", sg)
        edgeMist.Size = UDim2.new(1, 0, 1, 0)
        edgeMist.BackgroundTransparency = 1
        edgeMist.Image = "rbxassetid://6014261993"
        edgeMist.ImageColor3 = G.RGB(210, 245, 255)
        edgeMist.ImageTransparency = 0.75
        edgeMist.BorderSizePixel = 0

        -- Procedural diamond frost needles along viewport perimeter
        local crystalContainer = G.new("Frame", sg)
        crystalContainer.Size = UDim2.new(1, 0, 1, 0)
        crystalContainer.BackgroundTransparency = 1
        crystalContainer.BorderSizePixel = 0

        local shardPositions = {
            {pos = UDim2.new(0.12, 0, 0, -8), size = UDim2.new(0, 24, 0, 40), rot = 35, col = G.RGB(200, 240, 255), trans = 0.55},
            {pos = UDim2.new(0.28, 0, 0, -12), size = UDim2.new(0, 30, 0, 48), rot = -25, col = G.RGB(170, 225, 255), trans = 0.5},
            {pos = UDim2.new(0.72, 0, 0, -10), size = UDim2.new(0, 28, 0, 45), rot = 20, col = G.RGB(180, 230, 255), trans = 0.55},
            {pos = UDim2.new(0.88, 0, 0, -8), size = UDim2.new(0, 22, 0, 36), rot = -40, col = G.RGB(200, 240, 255), trans = 0.55},
            {pos = UDim2.new(0.08, 0, 1, -28), size = UDim2.new(0, 26, 0, 42), rot = 45, col = G.RGB(190, 235, 255), trans = 0.5},
            {pos = UDim2.new(0.22, 0, 1, -22), size = UDim2.new(0, 22, 0, 35), rot = -30, col = G.RGB(160, 220, 255), trans = 0.6},
            {pos = UDim2.new(0.78, 0, 1, -25), size = UDim2.new(0, 30, 0, 46), rot = 35, col = G.RGB(180, 230, 255), trans = 0.5},
            {pos = UDim2.new(0.92, 0, 1, -28), size = UDim2.new(0, 24, 0, 40), rot = -45, col = G.RGB(200, 240, 255), trans = 0.55},
        }

        for _, s in ipairs(shardPositions) do
            local shard = G.new("Frame", crystalContainer)
            shard.Size = s.size
            shard.Position = s.pos
            shard.Rotation = s.rot
            shard.BackgroundColor3 = s.col
            shard.BackgroundTransparency = s.trans
            shard.BorderSizePixel = 0
            G.mkC(shard, 3)
            
            local grad = G.new("UIGradient", shard)
            grad.Rotation = 90
            grad.Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.15),
                NumberSequenceKeypoint.new(0.6, 0.5),
                NumberSequenceKeypoint.new(1, 1.0)
            })
        end

        return sg
    end

    -- ==========================================
    -- 3. HAKKA NO TOGAME WEAPON TRANSFORMATION
    -- ==========================================
    local function transformWeaponToHakka(char)
        if not char then return end
        local weapon = findWeaponPart(char)
        if not weapon then return end

        if not BANKAI_ENGINE.savedWeaponProps[weapon] then
            BANKAI_ENGINE.savedWeaponProps[weapon] = {
                Color = weapon.Color,
                Material = weapon.Material,
                Transparency = weapon.Transparency,
                Reflectance = weapon.Reflectance
            }
        end

        BANKAI_ENGINE.transformedWeapon = weapon

        pcall(function()
            weapon.Material = Enum.Material.Glass
            weapon.Color = G.RGB(245, 255, 255)
            weapon.Transparency = 0.15
            weapon.Reflectance = 0.85
        end)

        -- Hakka no Togame Hilt Ribbon Streamer (Ethereal white flowing silk tassel)
        local ribbonAtt = G.new("Attachment", weapon)
        ribbonAtt.Name = "HakkaRibbonAtt"
        ribbonAtt.Position = G.V3(0, -1.8, 0)
        G.ti(BANKAI_ENGINE.objects, ribbonAtt)

        local ribbonEmitter = G.new("ParticleEmitter", ribbonAtt)
        ribbonEmitter.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, G.RGB(255, 255, 255)),
            ColorSequenceKeypoint.new(0.6, G.RGB(210, 245, 255)),
            ColorSequenceKeypoint.new(1, G.RGB(140, 210, 255))
        })
        ribbonEmitter.Rate = 50
        ribbonEmitter.Speed = NumberRange.new(0.5, 2.0)
        ribbonEmitter.Lifetime = NumberRange.new(0.4, 0.9)
        ribbonEmitter.SpreadAngle = Vector2.new(30, 30)
        ribbonEmitter.Size = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.25),
            NumberSequenceKeypoint.new(0.5, 0.18),
            NumberSequenceKeypoint.new(1, 0.0)
        })
        ribbonEmitter.LightEmission = 0.95
        ribbonEmitter.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.1),
            NumberSequenceKeypoint.new(0.7, 0.3),
            NumberSequenceKeypoint.new(1, 1.0)
        })
        G.ti(BANKAI_ENGINE.objects, ribbonEmitter)

        -- Blade Tip Ice Light
        local tipLight = G.new("PointLight", weapon)
        tipLight.Range = 12
        tipLight.Color = G.RGB(210, 245, 255)
        tipLight.Brightness = 3.2
        G.ti(BANKAI_ENGINE.objects, tipLight)
    end

    local function restoreTransformedWeapon()
        for weapon, props in pairs(BANKAI_ENGINE.savedWeaponProps) do
            if weapon and weapon.Parent and props then
                pcall(function()
                    weapon.Color = props.Color
                    weapon.Material = props.Material
                    weapon.Transparency = props.Transparency
                    weapon.Reflectance = props.Reflectance
                end)
            end
        end
        G.tc(BANKAI_ENGINE.savedWeaponProps)
        BANKAI_ENGINE.transformedWeapon = nil
    end

