    local function setupCharacterGlacialHalo(char)
        if not char then return end
        local torso = char:FindFirstChild("Torso") or char:FindFirstChild("UpperTorso")
        if not torso then return end

        local halo = G.new("Part")
        halo.Name = "HakkaGlacialHalo"
        halo.Shape = Enum.PartType.Cylinder
        halo.Size = G.V3(0.08, 3.6, 3.6)
        halo.Material = Enum.Material.Neon
        halo.Color = G.RGB(190, 240, 255)
        halo.Transparency = 0.45
        halo.CanCollide = false
        halo.Anchored = false
        halo.Parent = workspace
        BANKAI_ENGINE.haloPart = halo
        G.ti(BANKAI_ENGINE.objects, halo)

        local haloWeld = G.new("Weld", halo)
        haloWeld.Part0 = torso
        haloWeld.Part1 = halo
        haloWeld.C0 = CFrame.new(0, 0.8, 1.2) * CFrame.Angles(0, 0, math.rad(90))

        -- Slow ethereal rotation on Stepped
        local curAngle = 0
        BANKAI_ENGINE.rotConn = trk(G.RS.RenderStepped:Connect(function(dt)
            if not BANKAI_ENGINE.active or not halo or not halo.Parent then return end
            curAngle = (curAngle + (dt * 30)) % 360
            haloWeld.C0 = CFrame.new(0, 0.8, 1.2) * CFrame.Angles(math.rad(curAngle), 0, math.rad(90))
        end))
    end

    -- ==========================================
    -- 5. BANKAI: HAKKA NO TOGAME DOMAIN ENGINE
    -- ==========================================
    function BANKAI_ENGINE:activate()
        if self.active or self.cooldown then return end
        self.active = true
        self.cooldown = true

        pcall(function()
            local guiParent = G.CoreGui or (G.LP and G.LP:FindFirstChild("PlayerGui"))
            local char = G.LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local cam = workspace.CurrentCamera
            local lighting = game:GetService("Lighting")

            if not guiParent or not char or not hrp or not cam then
                self:stop()
                return
            end

            local domainOrigin = hrp.Position

            -- Enable Frost Blue HP Bar
            FROST_HUD_ENGINE:start()

            -- Transform weapon into Hakka no Togame pure white blade
            transformWeaponToHakka(char)

            -- Setup character glacial halo
            setupCharacterGlacialHalo(char)

            -- ==========================================
            -- AUTHENTIC BLEACH BANKAI AUDIO SEQUENCE
            -- ==========================================
            -- (0.0s) Absolute zero spatial vacuum + blade draw
            playDirectAudio("rbxassetid://541909763", 0.95, 0.85)
            playDirectAudio("rbxassetid://260430079", 0.9, 1.1)

            -- (0.15s) Deep sub-bass domain expansion rumble
            G.ts(function()
                G.tw(0.15)
                playDirectAudio("rbxassetid://138081509", 0.9, 0.75)
                playDirectAudio("rbxassetid://2785493", 0.8, 0.9)
            end)

            -- (0.35s) Glacial ice spire fracturing
            G.ts(function()
                G.tw(0.35)
                playDirectAudio("rbxassetid://18435214", 0.85, 0.9)
            end)

            -- ==========================================
            -- VISUAL CINEMATIC SEQUENCE
            -- ==========================================
            -- 1. White Screen Flash Burst
            local flashGui = G.new("ScreenGui")
            flashGui.Name = "BankaiBurstFlash"
            flashGui.IgnoreGuiInset = true
            flashGui.DisplayOrder = 1000000
            if G.protG then G.protG(flashGui) end
            flashGui.Parent = guiParent
            G.ti(self.objects, flashGui)

            local flashFrame = G.new("Frame", flashGui)
            flashFrame.Size = UDim2.new(1, 0, 1, 0)
            flashFrame.BackgroundColor3 = G.RGB(255, 255, 255)
            flashFrame.BackgroundTransparency = 0
            flashFrame.BorderSizePixel = 0
            G.TS:Create(flashFrame, G.TI(0.35), {BackgroundTransparency = 1}):Play()

            -- 2. Cold Bleach Anime Lighting Grade
            local cc = G.new("ColorCorrectionEffect")
            cc.Saturation = 0.05
            cc.Contrast = 0.18
            cc.TintColor = G.RGB(195, 225, 255)
            cc.Brightness = -0.02
            cc.Parent = lighting
            G.ti(self.objects, cc)

            local bloom = G.new("BloomEffect")
            bloom.Intensity = 0.75
            bloom.Size = 22
            bloom.Threshold = 0.85
            bloom.Parent = lighting
            G.ti(self.objects, bloom)

            local blur = G.new("BlurEffect")
            blur.Size = 10
            blur.Parent = lighting
            G.ti(self.objects, blur)
            G.TS:Create(blur, G.TI(0.45), {Size = 0}):Play()

            -- 3. Organic Frost Screen Overlay
            local frostScreen = createOrganicFrostOverlay(guiParent)
            G.ti(self.objects, frostScreen)

            -- 4. Glacial Domain Floor Disk
            local iceGround = G.new("Part")
            iceGround.Name = "BankaiGlacierDisk"
            iceGround.Shape = Enum.PartType.Cylinder
            iceGround.Size = G.V3(0.3, 48, 48)
            iceGround.CFrame = CFrame.new(domainOrigin - G.V3(0, 2.7, 0)) * CFrame.Angles(0, 0, math.rad(90))
            iceGround.Anchored = true
            iceGround.CanCollide = false
            iceGround.Material = Enum.Material.Glass
            iceGround.Color = G.RGB(185, 235, 255)
            iceGround.Transparency = 0.8
            iceGround.Reflectance = 0.75
            iceGround.Parent = workspace
            G.ti(self.objects, iceGround)
            G.TS:Create(iceGround, G.TI(0.4), {Transparency = 0.3}):Play()

            -- 5. Expanding Ground Cryo-Wave Ring
            local ring = G.new("Part")
            ring.Name = "BankaiShockwaveRing"
            ring.Shape = Enum.PartType.Cylinder
            ring.Size = G.V3(0.1, 2, 2)
            ring.CFrame = CFrame.new(domainOrigin - G.V3(0, 2.6, 0)) * CFrame.Angles(0, 0, math.rad(90))
            ring.Anchored = true
            ring.CanCollide = false
            ring.Material = Enum.Material.Neon
            ring.Color = G.RGB(190, 240, 255)
            ring.Transparency = 0.2
            ring.Parent = workspace
            G.ti(self.objects, ring)
            G.TS:Create(ring, G.TI(0.8, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                Size = G.V3(0.1, 52, 52),
                Transparency = 1.0
            }):Play()

            -- 6. 16 Towering Hakka no Togame Glacial Spikes
            local pillars = {}
            for i = 1, 16 do
                local angle = math.rad((i / 16) * 360)
                local radius = 14 + (i % 2 == 0 and 1.5 or -1.0)
                local offset = G.V3(math.cos(angle) * radius, 0, math.sin(angle) * radius)
                local pPos = domainOrigin + offset

                local pillar = G.new("Part")
                pillar.Name = "BankaiGlacialSpike_" .. i
                pillar.Size = G.V3(0.8, 1, 0.8)
                pillar.CFrame = CFrame.new(pPos - G.V3(0, 2, 0)) * CFrame.Angles(
                    math.rad(G.rd(-8, 8)),
                    angle,
                    math.rad(G.rd(-8, 8))
                )
                pillar.Transparency = 0.4
                pillar.Anchored = true
                pillar.CanCollide = false
                pillar.Material = Enum.Material.Neon
                pillar.Color = G.RGB(175, 225, 255)
                pillar.Parent = workspace
                G.ti(self.objects, pillar)
                G.ti(pillars, pillar)

                local targetH = 7 + (i % 4) * 3.2 + G.rd(1, 3)
                G.TS:Create(pillar, G.TI(0.35 + (i * 0.015), Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
                    Size = G.V3(1.1, targetH, 1.1),
                    CFrame = CFrame.new(pPos + G.V3(0, targetH / 2 - 2, 0)) * CFrame.Angles(
                        math.rad(G.rd(-6, 6)),
                        angle,
                        math.rad(G.rd(-6, 6))
                    ),
                    Transparency = 0.1
                }):Play()
            end

            -- 7. Blizzard Vortex & Character Frost Robe Emitters
            local blizzardPart = G.new("Part")
            blizzardPart.Size = G.V3(1, 1, 1)
            blizzardPart.Transparency = 1
            blizzardPart.Anchored = true
            blizzardPart.CanCollide = false
            blizzardPart.Position = domainOrigin
            blizzardPart.Parent = workspace
            G.ti(self.objects, blizzardPart)

            local blizzardEmitter = G.new("ParticleEmitter")
            blizzardEmitter.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, G.RGB(255, 255, 255)),
                ColorSequenceKeypoint.new(0.5, G.RGB(180, 230, 255)),
                ColorSequenceKeypoint.new(1, G.RGB(120, 195, 255))
            })
            blizzardEmitter.Rate = 180
            blizzardEmitter.Speed = NumberRange.new(8, 20)
            blizzardEmitter.Lifetime = NumberRange.new(0.5, 1.5)
            blizzardEmitter.SpreadAngle = Vector2.new(360, 360)
            blizzardEmitter.Size = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.2),
                NumberSequenceKeypoint.new(0.5, 0.1),
                NumberSequenceKeypoint.new(1, 0.0)
            })
            blizzardEmitter.LightEmission = 0.85
            blizzardEmitter.Parent = blizzardPart

            local auraLight = G.new("PointLight")
            auraLight.Range = 18
            auraLight.Color = G.RGB(170, 220, 255)
            auraLight.Brightness = 3.5
            auraLight.Parent = hrp
            G.ti(self.objects, auraLight)

            local mistEmitter = G.new("ParticleEmitter")
            mistEmitter.Color = ColorSequence.new(G.RGB(200, 240, 255), G.RGB(140, 210, 255))
            mistEmitter.Rate = 35
            mistEmitter.Speed = NumberRange.new(1, 2.5)
            mistEmitter.Lifetime = NumberRange.new(0.4, 0.8)
            mistEmitter.SpreadAngle = Vector2.new(180, 180)
            mistEmitter.Size = NumberSequence.new(0.35, 0.1)
            mistEmitter.LightEmission = 0.8
            mistEmitter.Parent = hrp
            G.ti(self.objects, mistEmitter)

            -- 8. Footstep Blossom Tracker
            self.lastStepPos = hrp.Position
            self.stepConn = trk(G.RS.Heartbeat:Connect(function()
                if not self.active or not hrp or not hrp.Parent then return end
                local curPos = hrp.Position
                if self.lastStepPos and (curPos - self.lastStepPos).Magnitude > 3.2 then
                    self.lastStepPos = curPos
                    spawnIceFootstepBlossom(curPos)
                end
            end))

            -- 9. Cinematic Camera Shake
            local shakeEnd = tick() + 1.5
            self.camShakeConn = G.RS.RenderStepped:Connect(function()
                if tick() < shakeEnd and self.active then
                    cam.CFrame = cam.CFrame * CFrame.new(
                        G.rd(-10, 10) / 90,
                        G.rd(-10, 10) / 90,
                        G.rd(-10, 10) / 90
                    ) * CFrame.Angles(
                        math.rad(G.rd(-3, 3) / 10),
                        math.rad(G.rd(-3, 3) / 10),
                        math.rad(G.rd(-3, 3) / 10)
                    )
                else
                    if self.camShakeConn then
                        self.camShakeConn:Disconnect()
                        self.camShakeConn = nil
                    end
                end
            end)

            -- 10. Automatic Domain Decay (if not in persistent mode)
            G.ts(function()
                G.tw(5.5)
                if not self.persistentMode then
                    for _, p in ipairs(pillars) do
                        if p and p.Parent then
                            G.TS:Create(p, G.TI(0.6), {Transparency = 1}):Play()
                        end
                    end
                    if iceGround and iceGround.Parent then
                        G.TS:Create(iceGround, G.TI(0.6), {Transparency = 1}):Play()
                    end
                    if blizzardEmitter then blizzardEmitter.Enabled = false end
                    if mistEmitter then mistEmitter.Enabled = false end

                    G.tw(0.7)
                    self:stop()
                    FROST_HUD_ENGINE:stop()
                end
            end)

            -- 11. Reset Cooldown
            G.ts(function()
                G.tw(10.0)
                self.cooldown = false
            end)
        end)
    end

    function BANKAI_ENGINE:stop()
        self.active = false
        pcall(function()
            if self.camShakeConn then
                self.camShakeConn:Disconnect()
                self.camShakeConn = nil
            end
            if self.rotConn then
                self.rotConn:Disconnect()
                self.rotConn = nil
            end
            if self.stepConn then
                self.stepConn:Disconnect()
                self.stepConn = nil
            end
            for _, obj in pairs(self.objects) do
                if obj and obj.Parent then
                    obj:Destroy()
                end
            end
            G.tc(self.objects)
            restoreTransformedWeapon()
            self.haloPart = nil
            self.lastStepPos = nil
        end)
    end

    function BANKAI_ENGINE:togglePersistent()
        self.persistentMode = not self.persistentMode
        if self.persistentMode then
            self:activate()
        else
            self:stop()
            FROST_HUD_ENGINE:stop()
        end
        return self.persistentMode
    end

    -- ==========================================
    -- 6. MOTOR6D COMBAT STANCES ENGINE (R6)
    -- ==========================================
    local stanceRotations = {
        [1] = CFrame.new(),
        [2] = CFrame.Angles(math.rad(-45), math.rad(10), math.rad(-15)),      -- Blade Forward
        [3] = CFrame.Angles(math.rad(40), math.rad(-20), math.rad(-35)),      -- Void Stance
        [4] = CFrame.Angles(math.rad(90), math.rad(175), math.rad(-10)),      -- Shinobi Guard
        [5] = CFrame.Angles(math.rad(180), math.rad(0), math.rad(10)),        -- Reverse Grip
        [6] = CFrame.Angles(math.rad(-85), math.rad(25), math.rad(30)),       -- Reaper Hold
    }

    local function getIntensity()
        local cfg = type(CFG) == "table" and CFG or {}
        return (cfg.StanceIntensity or 100) / 100
    end

    local function applyIntensity(cf, intensity)
        local x, y, z = cf:ToEulerAnglesXYZ()
        return CFrame.Angles(x * intensity, y * intensity, z * intensity)
    end

    local function resolveJoints(char)
        if not char then return nil, nil end
        local rGrip = nil
        local rShoulder = nil

        local torso = char:FindFirstChild("Torso")
        if torso then
            local s = torso:FindFirstChild("Right Shoulder")
            if s and s:IsA("Motor6D") then
                rShoulder = s
            end
        end

        for _, v in pairs(char:GetDescendants()) do
            if (v:IsA("Motor6D") or v:IsA("Weld")) and v.Part1 then
                local p1Name = string.lower(v.Part1.Name)
                local vName = string.lower(v.Name)
                if string.find(vName, "grip") or string.find(vName, "weapon") or string.find(p1Name, "handle") 
                or string.find(p1Name, "blade") or string.find(p1Name, "sword") or string.find(p1Name, "weapon") then
                    rGrip = v
                    break
                end
            end
        end

        return rGrip, rShoulder
    end

    function CUSTOM_VISUALS_ENGINE:start()
        if self.active then return end
        self.active = true

        local function hookChar(char)
            if not char then return end
            self.rightGrip = nil
            self.originalC0 = nil
            self.rightShoulder = nil
            self.originalShoulderC0 = nil

            local grip, shoulder = resolveJoints(char)
            if grip then
                self.rightGrip = grip
                self.originalC0 = grip.C0
            end
            if shoulder then
                self.rightShoulder = shoulder
                self.originalShoulderC0 = shoulder.C0
            end
        end

        if G.LP.Character then
            hookChar(G.LP.Character)
        end

        self.charConn = trk(G.LP.CharacterAdded:Connect(function(char)
            G.ts(function()
                G.tw(0.3)
                hookChar(char)
            end)
        end))

        self.conn = trk(G.RS.Stepped:Connect(function()
            if not self.active then return end
            local char = G.LP.Character
            if not char then return end

            local grip, shoulder = resolveJoints(char)
            if grip and not self.originalC0 then
                self.rightGrip = grip
                self.originalC0 = grip.C0
            end
            if shoulder and not self.originalShoulderC0 then
                self.rightShoulder = shoulder
                self.originalShoulderC0 = shoulder.C0
            end

            local baseRot = stanceRotations[self.currentStance] or CFrame.new()
            local intensity = getIntensity()
            local rot = applyIntensity(baseRot, intensity)

            if grip and self.originalC0 then
                grip.C0 = self.originalC0 * rot
            elseif shoulder and self.originalShoulderC0 and self.currentStance > 1 then
                shoulder.C0 = self.originalShoulderC0 * rot
            end
        end))
    end

    function CUSTOM_VISUALS_ENGINE:stop()
        if not self.active then return end
        self.active = false

        if self.conn then self.conn:Disconnect() self.conn = nil end
        if self.charConn then self.charConn:Disconnect() self.charConn = nil end

        if self.rightGrip and self.rightGrip.Parent and self.originalC0 then
            self.rightGrip.C0 = self.originalC0
        end
        if self.rightShoulder and self.rightShoulder.Parent and self.originalShoulderC0 then
            self.rightShoulder.C0 = self.originalShoulderC0
        end

        self.rightGrip = nil
        self.originalC0 = nil
        self.rightShoulder = nil
        self.originalShoulderC0 = nil
    end

    function CUSTOM_VISUALS_ENGINE:setStance(idx)
        self.currentStance = idx
        self:refresh()
    end

    function CUSTOM_VISUALS_ENGINE:refresh()
        if not self.active then return end
        local char = G.LP.Character
        if not char then return end
        local grip, shoulder = resolveJoints(char)
        if grip and not self.originalC0 then
            self.rightGrip = grip
            self.originalC0 = grip.C0
        end
        if shoulder and not self.originalShoulderC0 then
            self.rightShoulder = shoulder
            self.originalShoulderC0 = shoulder.C0
        end
    end
end
WEAPON_VFX_STYLE_NAMES = {
    [1] = "Ember Trail",
    [2] = "Void Edge",
    [3] = "Frost Bite",
    [4] = "Lightning Arc",
    [5] = "Shadow Cleave",
}

WEAPON_VFX_ENGINE = {
    active = false, 
    style = 1, 
    hookConn = nil, 
    charConn = nil, 
    inputConn = nil,
    stepConn = nil,
    currentWeapon = nil,
    ambientEmitter = nil,
    ambientLight = nil,
    ambientAtt = nil,
    activeTrails = {},
    lastSwingTime = 0
}

do
    local function getIntensity()
        local cfg = type(CFG) == "table" and CFG or {}
        return cfg.VfxIntensity or 1.0
    end

    local function isCombatAnim(track)
        if not track then return false end
        local anim = track.Animation
        local n = string.lower((track.Name or "") .. " " .. (anim and anim.Name or ""))
        local keywords = {"m1", "swing", "slash", "attack", "light", "heavy", "crit", "uppercut", "running", "flourish", "mantra", "cast", "spell", "strike", "thrust", "blade"}
        for _, k in ipairs(keywords) do
            if string.find(n, k) then
                return true
            end
        end
        if track.Priority and track.Priority.Value >= Enum.AnimationPriority.Action.Value then
            return true
        end
        return false
    end

    local function getWeaponPart(char)
        if not char then return nil end
        local rArm = char:FindFirstChild("Right Arm") or char:FindFirstChild("RightHand")

        if rArm then
            for _, v in ipairs(char:GetDescendants()) do
                if (v:IsA("Motor6D") or v:IsA("Weld") or v:IsA("WeldConstraint")) then
                    if v.Part0 == rArm and v.Part1 and v.Part1:IsA("BasePart") and v.Part1 ~= char:FindFirstChild("Torso") and v.Part1 ~= char:FindFirstChild("Head") then
                        return v.Part1
                    elseif v.Part1 == rArm and v.Part0 and v.Part0:IsA("BasePart") and v.Part0 ~= char:FindFirstChild("Torso") and v.Part0 ~= char:FindFirstChild("Head") then
                        return v.Part0
                    end
                end
            end
        end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Model") and child.Name ~= char.Name then
                for _, p in ipairs(child:GetDescendants()) do
                    if p:IsA("BasePart") and (p:FindFirstChildOfClass("SpecialMesh") or p:IsA("MeshPart") or string.find(string.lower(p.Name), "handle") or string.find(string.lower(p.Name), "blade") or string.find(string.lower(p.Name), "sword")) then
                        return p
                    end
                end
            end
        end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") then
                local h = child:FindFirstChild("Handle") or child:FindFirstChildWhichIsA("BasePart")
                if h then return h end
            end
        end

        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("BasePart") then
                local n = string.lower(child.Name)
                if string.find(n, "blade") or string.find(n, "sword") or string.find(n, "weapon") 
                or string.find(n, "dagger") or string.find(n, "spear") or string.find(n, "axe") 
                or string.find(n, "scythe") or string.find(n, "staff") or string.find(n, "cestus") then
                    return child
                end
            end
        end

        return rArm
    end

    local function getStyleConfig(s)
        local i = getIntensity()
        
        -- Override style to pure diamond frost if Bankai is active
        if BANKAI_ENGINE and (BANKAI_ENGINE.active or BANKAI_ENGINE.persistentMode) then
            return {
                trailColor = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, G.RGB(255, 255, 255)),
                    ColorSequenceKeypoint.new(0.5, G.RGB(190, 240, 255)),
                    ColorSequenceKeypoint.new(1, G.RGB(80, 180, 255))
                }),
                emitterColor = ColorSequence.new(G.RGB(255, 255, 255), G.RGB(160, 230, 255)),
                lightColor = G.RGB(210, 245, 255),
                lightEmission = 1.0,
                trailLifetime = 0.32,
                rate = 140 * i,
                size = NumberSequence.new(0.35, 0.0)
            }
        end

        if s == 1 then -- Ember Trail
            return {
                trailColor = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, G.RGB(255, 180, 50)),
                    ColorSequenceKeypoint.new(0.5, G.RGB(255, 80, 0)),
                    ColorSequenceKeypoint.new(1, G.RGB(180, 20, 0))
                }),
                emitterColor = ColorSequence.new(G.RGB(255, 160, 20), G.RGB(255, 40, 0)),
                lightColor = G.RGB(255, 100, 20),
                lightEmission = 1.0,
                trailLifetime = 0.28,
                rate = 90 * i,
                size = NumberSequence.new(0.35, 0.05)
            }
        elseif s == 2 then -- Void Edge
            return {
                trailColor = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, G.RGB(200, 100, 255)),
                    ColorSequenceKeypoint.new(0.5, G.RGB(120, 0, 220)),
                    ColorSequenceKeypoint.new(1, G.RGB(40, 0, 90))
                }),
                emitterColor = ColorSequence.new(G.RGB(170, 50, 255), G.RGB(60, 0, 120)),
                lightColor = G.RGB(150, 20, 255),
                lightEmission = 0.9,
                trailLifetime = 0.32,
                rate = 75 * i,
                size = NumberSequence.new(0.4, 0.1)
            }
        elseif s == 3 then -- Frost Bite
            return {
                trailColor = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, G.RGB(240, 250, 255)),
                    ColorSequenceKeypoint.new(0.5, G.RGB(140, 215, 255)),
                    ColorSequenceKeypoint.new(1, G.RGB(50, 140, 255))
                }),
                emitterColor = ColorSequence.new(G.RGB(200, 240, 255), G.RGB(100, 190, 255)),
                lightColor = G.RGB(130, 210, 255),
                lightEmission = 1.0,
                trailLifetime = 0.25,
                rate = 100 * i,
                size = NumberSequence.new(0.3, 0.0)
            }
        elseif s == 4 then -- Lightning Arc
            return {
                trailColor = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, G.RGB(255, 255, 200)),
                    ColorSequenceKeypoint.new(0.5, G.RGB(255, 220, 50)),
                    ColorSequenceKeypoint.new(1, G.RGB(0, 210, 255))
                }),
                emitterColor = ColorSequence.new(G.RGB(255, 255, 120), G.RGB(0, 220, 255)),
                lightColor = G.RGB(255, 240, 100),
                lightEmission = 1.0,
                trailLifetime = 0.18,
                rate = 150 * i,
                size = NumberSequence.new(0.2, 0.0)
            }
        else -- Shadow Cleave
            return {
                trailColor = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, G.RGB(90, 90, 100)),
                    ColorSequenceKeypoint.new(0.5, G.RGB(35, 30, 45)),
                    ColorSequenceKeypoint.new(1, G.RGB(10, 5, 15))
                }),
                emitterColor = ColorSequence.new(G.RGB(60, 40, 70), G.RGB(15, 10, 20)),
                lightColor = G.RGB(50, 30, 70),
                lightEmission = 0.3,
                trailLifetime = 0.35,
                rate = 60 * i,
                size = NumberSequence.new(0.5, 0.15)
            }
        end
    end

    local function clearAmbient()
        if WEAPON_VFX_ENGINE.ambientEmitter and WEAPON_VFX_ENGINE.ambientEmitter.Parent then
            WEAPON_VFX_ENGINE.ambientEmitter:Destroy()
        end
        if WEAPON_VFX_ENGINE.ambientLight and WEAPON_VFX_ENGINE.ambientLight.Parent then
            WEAPON_VFX_ENGINE.ambientLight:Destroy()
        end
        if WEAPON_VFX_ENGINE.ambientAtt and WEAPON_VFX_ENGINE.ambientAtt.Parent then
            WEAPON_VFX_ENGINE.ambientAtt:Destroy()
        end
        WEAPON_VFX_ENGINE.ambientEmitter = nil
        WEAPON_VFX_ENGINE.ambientLight = nil
        WEAPON_VFX_ENGINE.ambientAtt = nil
    end

    local function setupWeaponAmbient(weapon)
        clearAmbient()
        if not WEAPON_VFX_ENGINE.active or not weapon then return end

        local cfg = getStyleConfig(WEAPON_VFX_ENGINE.style)

        local att = G.new("Attachment", weapon)
        att.Name = "KatalystWeaponVFXAtt"
        att.Position = G.V3(0, 1.6, 0)
        WEAPON_VFX_ENGINE.ambientAtt = att

        local emitter = G.new("ParticleEmitter", att)
        emitter.Color = cfg.emitterColor
        emitter.Rate = cfg.rate * 0.45
        emitter.Speed = NumberRange.new(1, 3)
        emitter.Lifetime = NumberRange.new(0.2, 0.5)
        emitter.SpreadAngle = Vector2.new(60, 60)
        emitter.Size = cfg.size
        emitter.LightEmission = cfg.lightEmission
        WEAPON_VFX_ENGINE.ambientEmitter = emitter

        local light = G.new("PointLight", att)
        light.Range = 8
        light.Color = cfg.lightColor
        light.Brightness = 2.5
        WEAPON_VFX_ENGINE.ambientLight = light
    end

    -- Spawns a crescent frost wave during Bankai attacks
    local function spawnBankaiCrescentArc(char, weapon)
        pcall(function()
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local arc = G.new("Part")
            arc.Name = "BankaiCrescentWave"
            arc.Shape = Enum.PartType.Cylinder
            arc.Size = G.V3(0.08, 4.5, 4.5)
            arc.CFrame = hrp.CFrame * CFrame.new(0, 0, -2.5) * CFrame.Angles(0, 0, math.rad(90))
            arc.Material = Enum.Material.Neon
            arc.Color = G.RGB(210, 245, 255)
            arc.Transparency = 0.25
            arc.Anchored = true
            arc.CanCollide = false
            arc.Parent = workspace

            G.TS:Create(arc, G.TI(0.35, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                CFrame = hrp.CFrame * CFrame.new(0, 0, -7.0) * CFrame.Angles(0, 0, math.rad(90)),
                Size = G.V3(0.08, 7.5, 7.5),
                Transparency = 1.0
            }):Play()

            G.ts(function()
                G.tw(0.4)
                pcall(function() arc:Destroy() end)
            end)
        end)
    end

    local function triggerSlashVFX()
        if not WEAPON_VFX_ENGINE.active then return end
        local char = G.LP.Character
        if not char then return end

        local weapon = getWeaponPart(char)
        if not weapon then return end

        local cfg = getStyleConfig(WEAPON_VFX_ENGINE.style)

        local att0 = G.new("Attachment", weapon)
        att0.Position = G.V3(0, -1.8, 0)

        local att1 = G.new("Attachment", weapon)
        att1.Position = G.V3(0, 1.8, 0)

        local trail = G.new("Trail", weapon)
        trail.Attachment0 = att0
        trail.Attachment1 = att1
        trail.FaceCamera = true
        trail.Color = cfg.trailColor
        trail.Lifetime = cfg.trailLifetime
        trail.LightEmission = cfg.lightEmission
        trail.LightInfluence = 0
        trail.WidthScale = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1.3),
            NumberSequenceKeypoint.new(0.7, 0.85),
            NumberSequenceKeypoint.new(1, 0.0)
        })
        trail.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.05),
            NumberSequenceKeypoint.new(0.8, 0.35),
            NumberSequenceKeypoint.new(1, 1.0)
        })

        local burstEmitter = G.new("ParticleEmitter", att1)
        burstEmitter.Color = cfg.emitterColor
        burstEmitter.Rate = cfg.rate * 1.6
        burstEmitter.Speed = NumberRange.new(3, 9)
        burstEmitter.Lifetime = NumberRange.new(0.15, 0.35)
        burstEmitter.SpreadAngle = Vector2.new(120, 120)
        burstEmitter.Size = cfg.size
        burstEmitter.LightEmission = cfg.lightEmission

        G.ti(WEAPON_VFX_ENGINE.activeTrails, att0)
        G.ti(WEAPON_VFX_ENGINE.activeTrails, att1)
        G.ti(WEAPON_VFX_ENGINE.activeTrails, trail)
        G.ti(WEAPON_VFX_ENGINE.activeTrails, burstEmitter)

        -- If Bankai is active, also spawn the crescent moon wave
        if BANKAI_ENGINE and (BANKAI_ENGINE.active or BANKAI_ENGINE.persistentMode) then
            spawnBankaiCrescentArc(char, weapon)
        end

        G.ts(function()
            G.tw(0.4)
            if trail and trail.Parent then trail.Enabled = false end
            if burstEmitter and burstEmitter.Parent then burstEmitter.Enabled = false end

            G.tw(0.35)
            pcall(function()
                if att0 and att0.Parent then att0:Destroy() end
                if att1 and att1.Parent then att1:Destroy() end
                if trail and trail.Parent then trail:Destroy() end
                if burstEmitter and burstEmitter.Parent then burstEmitter:Destroy() end
            end)
        end)
    end

    local function onAnimationPlayed(track)
        if not WEAPON_VFX_ENGINE.active or not track then return end
        if isCombatAnim(track) then
            local now = tick()
            if now - WEAPON_VFX_ENGINE.lastSwingTime > 0.1 then
                WEAPON_VFX_ENGINE.lastSwingTime = now
                triggerSlashVFX()
            end
        end
    end

    function WEAPON_VFX_ENGINE:start()
        if self.active then return end
        self.active = true
        self.style = type(CFG) == "table" and (CFG.VfxStyle or 1) or 1

        local function hookChar(char)
            if not char then return end
            local hum = char:WaitForChild("Humanoid", 5)
            if hum then
                local ani = hum:WaitForChild("Animator", 5)
                if ani then
                    self.hookConn = trk(ani.AnimationPlayed:Connect(onAnimationPlayed))
                end
            end

            G.ts(function()
                G.tw(0.4)
                local w = getWeaponPart(char)
                self.currentWeapon = w
                setupWeaponAmbient(w)
            end)
        end

        if G.LP.Character then
            hookChar(G.LP.Character)
        end

        self.charConn = trk(G.LP.CharacterAdded:Connect(function(char)
            clearAmbient()
            G.ts(function()
                G.tw(0.3)
                hookChar(char)
            end)
        end))

        self.inputConn = trk(G.UIS.InputBegan:Connect(function(input, gpe)
            if not self.active or gpe then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                local now = tick()
                if now - self.lastSwingTime > 0.1 then
                    self.lastSwingTime = now
                    triggerSlashVFX()
                end
            end
        end))

        self.stepConn = trk(G.RS.Heartbeat:Connect(function()
            if not self.active then return end
            local char = G.LP.Character
            if not char then return end
            local w = getWeaponPart(char)
            if w ~= self.currentWeapon then
                self.currentWeapon = w
                setupWeaponAmbient(w)
            end
        end))
    end

    function WEAPON_VFX_ENGINE:stop()
        if not self.active then return end
        self.active = false

        if self.hookConn then self.hookConn:Disconnect() self.hookConn = nil end
        if self.charConn then self.charConn:Disconnect() self.charConn = nil end
        if self.inputConn then self.inputConn:Disconnect() self.inputConn = nil end
        if self.stepConn then self.stepConn:Disconnect() self.stepConn = nil end

        clearAmbient()
        for _, obj in pairs(self.activeTrails) do
            if obj and obj.Parent then pcall(function() obj:Destroy() end) end
        end
        G.tc(self.activeTrails)
        self.currentWeapon = nil
    end

    function WEAPON_VFX_ENGINE:setStyle(idx)
        self.style = idx
        if self.active and self.currentWeapon then
            setupWeaponAmbient(self.currentWeapon)
        end
    end

    function WEAPON_VFX_ENGINE:refresh()
        if self.active and G.LP.Character then
            local w = getWeaponPart(G.LP.Character)
            self.currentWeapon = w
            setupWeaponAmbient(w)
        end
    end
end
COMBAT_SFX_PRESET_NAMES = {
    [1] = "Metallic Clash",
    [2] = "Thunder Impact",
    [3] = "Crystal Shatter",
    [4] = "Void Echo",
    [5] = "Clean Slice",
}

COMBAT_SFX_ENGINE = {
    active = false, 
    preset = 1, 
    hookConn = nil, 
    charConn = nil, 
    killConn = nil,
    inputConn = nil,
    lastSwing = 0
}

do
    -- Verified 100% public, unblockable Roblox official sound assets
    local SOUND_IDS = {
        [1] = "rbxassetid://12222216", -- Sharp steel clash
        [2] = "rbxassetid://138081509", -- Booming thunder shockwave
        [3] = "rbxassetid://18435214",  -- Resonant crystal fracture
        [4] = "rbxassetid://62339698",  -- Ethereal void echo
        [5] = "rbxassetid://1369158879", -- Katana clean air slice
    }
    
    local function getVolume()
        local cfg = type(CFG) == "table" and CFG or {}
        return cfg.SfxVolume or 0.75
    end

    local function playLocalSFX(soundId, volume, pitch)
        pcall(function()
            local ss = game:GetService("SoundService")
            local snd = Instance.new("Sound")
            snd.SoundId = soundId
            snd.Volume = volume or getVolume()
            snd.PlaybackSpeed = pitch or (0.95 + (G.rd(-4, 4) / 100))
            snd.RollOffMaxDistance = 100000
            snd.Parent = ss
            
            if ss.PlayLocalSound then
                ss:PlayLocalSound(snd)
            else
                snd:Play()
            end
            
            game:GetService("Debris"):AddItem(snd, 3.0)
        end)
    end

    local function executeFlash()
        pcall(function()
            local core = G.CoreGui or (G.LP and G.LP:FindFirstChild('PlayerGui'))
            if not core then return end
            
            local sg = G.new('ScreenGui')
            sg.Name = "KillFlash"
            sg.IgnoreGuiInset = true
            sg.DisplayOrder = 999999
            if G.protG then G.protG(sg) end
            sg.Parent = core
            
            local fr = G.new('Frame', sg)
            fr.Size = UDim2.new(1, 0, 1, 0)
            fr.BackgroundColor3 = G.RGB(255, 255, 255)
            fr.BackgroundTransparency = 0
            fr.BorderSizePixel = 0
            
            playLocalSFX("rbxassetid://138081509", 0.9, 1.2) -- Kill impact sound
            
            local tween = G.TS:Create(fr, G.TI(0.25), {BackgroundTransparency = 1})
            tween:Play()
            
            tween.Completed:Connect(function()
                pcall(function() sg:Destroy() end)
            end)
        end)
    end

    local function onAnimationPlayed(track)
        if not COMBAT_SFX_ENGINE.active or not track then return end
        local anim = track.Animation
        local name = string.lower((track.Name or "") .. " " .. (anim and anim.Name or ""))
        if string.find(name, "m1") or string.find(name, "swing") or 
           string.find(name, "slash") or string.find(name, "attack") or 
           string.find(name, "light") or string.find(name, "heavy") or
           string.find(name, "crit") or string.find(name, "uppercut") or
           string.find(name, "strike") or string.find(name, "thrust") or
           (track.Priority and track.Priority.Value >= Enum.AnimationPriority.Action.Value) then
           
           local now = tick()
           if now - COMBAT_SFX_ENGINE.lastSwing > 0.1 then
               COMBAT_SFX_ENGINE.lastSwing = now
               local sId = SOUND_IDS[COMBAT_SFX_ENGINE.preset] or SOUND_IDS[1]
               playLocalSFX(sId, getVolume())
           end
        end
    end

    local function setupCharacter(char)
        if not char then return end
        if COMBAT_SFX_ENGINE.hookConn then 
            COMBAT_SFX_ENGINE.hookConn:Disconnect() 
            COMBAT_SFX_ENGINE.hookConn = nil 
        end
        
        local hum = char:WaitForChild("Humanoid", 5)
        if not hum then return end
        local ani = hum:WaitForChild("Animator", 5)
        if not ani then return end
        
        COMBAT_SFX_ENGINE.hookConn = trk(ani.AnimationPlayed:Connect(onAnimationPlayed))
    end

    local function setupKillTracker()
        local Players = game:GetService("Players")
        local deadPlayers = {}
        
        COMBAT_SFX_ENGINE.killConn = trk(G.RS.Heartbeat:Connect(function()
            if not COMBAT_SFX_ENGINE.active then return end
            
            local char = G.LP.Character
            local myHrp = char and char:FindFirstChild("HumanoidRootPart")
            if not myHrp then return end
            
            local now = tick()
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= G.LP and p.Character then
                    local hum = p.Character:FindFirstChild("Humanoid")
                    local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                    if hum and hrp then
                        local dist = (myHrp.Position - hrp.Position).Magnitude
                        if dist <= 30 then
                            if hum.Health <= 0 then
                                if not deadPlayers[p.Name] then
                                    deadPlayers[p.Name] = true
                                    if (now - COMBAT_SFX_ENGINE.lastSwing) <= 1.0 then
                                        executeFlash()
                                    end
                                end
                            elseif hum.Health > 0 then
                                deadPlayers[p.Name] = false
                            end
                        end
                    end
                end
            end
        end))
    end

    function COMBAT_SFX_ENGINE:start()
        if self.active then return end
        self.active = true
        self.preset = type(CFG) == "table" and (CFG.SfxPreset or 1) or 1
        
        if G.LP.Character then
            G.ts(setupCharacter, G.LP.Character)
        end
        
        self.charConn = trk(G.LP.CharacterAdded:Connect(function(char)
            G.ts(setupCharacter, char)
        end))

        -- M1 click trigger fallback
        self.inputConn = trk(G.UIS.InputBegan:Connect(function(input, gpe)
            if not self.active or gpe then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
                local now = tick()
                if now - self.lastSwing > 0.1 then
                    self.lastSwing = now
                    local sId = SOUND_IDS[self.preset] or SOUND_IDS[1]
                    playLocalSFX(sId, getVolume())
                end
            end
        end))
        
        setupKillTracker()
    end

    function COMBAT_SFX_ENGINE:stop()
        if not self.active then return end
        self.active = false
        
        if self.hookConn then self.hookConn:Disconnect() self.hookConn = nil end
        if self.charConn then self.charConn:Disconnect() self.charConn = nil end
        if self.killConn then self.killConn:Disconnect() self.killConn = nil end
        if self.inputConn then self.inputConn:Disconnect() self.inputConn = nil end
    end

    function COMBAT_SFX_ENGINE:setPreset(idx)
        self.preset = idx
        -- Play a preview sound when selected
        local sId = SOUND_IDS[idx] or SOUND_IDS[1]
        playLocalSFX(sId, getVolume())
    end

    function COMBAT_SFX_ENGINE:refresh()
        if self.active and G.LP.Character then
            setupCharacter(G.LP.Character)
        end
    end
end
VOIDWALKER_RADAR = {active=false, conn=nil, alerted={}}

do
  local function scan()
    local myChar = G.LP and G.LP.Character
    local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return end
    local now = os.clock()
    for name, t in pairs(VOIDWALKER_RADAR.alerted) do
      if now - t > 30 then VOIDWALKER_RADAR.alerted[name] = nil end
    end
    for _, plr in ipairs(G.Plrs:GetPlayers()) do
      if plr ~= G.LP and plr.Character then
        pcall(function()
          local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
          if not hrp then return end
          local dist = (hrp.Position - myRoot.Position).Magnitude
          if dist > 300 then return end
          local isThreat = false
          for _, item in ipairs(plr.Character:GetChildren()) do
            local n = string.lower(item.Name)
            if n:find("bounty") or n:find("warrant") or n:find("tracker") or n:find("hunter") or n:find("voidwalker") or n:find("authority") or n:find("enforcer") then
              isThreat = true
              break
            end
          end
          if not isThreat then
            local bp = plr:FindFirstChild("Backpack")
            if bp then
              for _, item in ipairs(bp:GetChildren()) do
                local n = string.lower(item.Name)
                if n:find("bounty") or n:find("warrant") or n:find("hunter") or n:find("authority") then
                  isThreat = true
                  break
                end
              end
            end
          end
          if isThreat and not VOIDWALKER_RADAR.alerted[plr.Name] then
            VOIDWALKER_RADAR.alerted[plr.Name] = now
            G.noti("VOIDWALKER ALERT", plr.Name .. " detected " .. math.floor(dist) .. " studs away -- possible bounty hunter", 4)
          end
        end)
      end
    end
  end

  function VOIDWALKER_RADAR.start()
    if VOIDWALKER_RADAR.active then return end
    VOIDWALKER_RADAR.active = true
    local elapsed = 0
    VOIDWALKER_RADAR.conn = G.RS.Heartbeat:Connect(function(dt)
      if not VOIDWALKER_RADAR.active then return end
      elapsed = elapsed + dt
      if elapsed >= 2 then
        elapsed = 0
        pcall(scan)
      end
    end)
  end

  function VOIDWALKER_RADAR.stop()
    VOIDWALKER_RADAR.active = false
    if VOIDWALKER_RADAR.conn then
      pcall(function() VOIDWALKER_RADAR.conn:Disconnect() end)
      VOIDWALKER_RADAR.conn = nil
    end
    table.clear(VOIDWALKER_RADAR.alerted)
  end
end
local PATHFIND_BREAKER = { hbConn = nil }
function PATHFIND_BREAKER.start()
  if PATHFIND_BREAKER.hbConn then return end

  -- Direct NPC Target & Movement Freeze
  PATHFIND_BREAKER.hbConn = G.RS.Heartbeat:Connect(function()
    if not S.pathfindBreaker and not S.npcFreeze and not S.ferrymanBoss then return end
    local character = G.LP.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then return end
    
    local myPos = root.Position
    local live = G.WS:FindFirstChild("Live") or G.WS
    local npcs = G.WS:FindFirstChild("NPCs") or G.WS
    
    for _, dir in ipairs({live, npcs, G.WS}) do
      if dir then
        for _, m in ipairs(dir:GetChildren()) do
          if m:IsA("Model") and m ~= character and not G.Plrs:GetPlayerFromCharacter(m) then
            local hum = m:FindFirstChildOfClass("Humanoid")
            local hrp = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso") or m:FindFirstChild("UpperTorso") or m.PrimaryPart
            if hum and hrp and hum.Health > 0 then
              local dist = (hrp.Position - myPos).Magnitude
              if dist <= 400 then
                pcall(function()
                  hrp.Velocity = G.V3(0, 0, 0)
                  hrp.AssemblyLinearVelocity = G.V3(0, 0, 0)
                  hrp.AssemblyAngularVelocity = G.V3(0, 0, 0)
                  
                  hum.WalkToPoint = hrp.Position
                  hum:MoveTo(hrp.Position)
                  hum.WalkSpeed = 0
                  
                  m:SetAttribute("Target", nil)
                  m:SetAttribute("Aggro", nil)
                  m:SetAttribute("InCombat", nil)
                  m:SetAttribute("Attacking", nil)
                  
                  local anim = hum:FindFirstChildOfClass("Animator")
                  if anim then pcall(function() anim:Destroy() end) end
                  hum.WalkSpeed = 0
                  hum.JumpPower = 0
                end)
              end
            end
          end
        end
      end
    end
  end)
end

function PATHFIND_BREAKER.stop()
  if PATHFIND_BREAKER.hbConn then
    PATHFIND_BREAKER.hbConn:Disconnect()
    PATHFIND_BREAKER.hbConn = nil
  end
end

-- BRING MOBS (bring mobs & sync server hitboxes)
-- Uses SimulationRadius elevation + network ownership + PivotTo
local BRING_MOBS = { conn = nil, range = 200 }
function BRING_MOBS.start()
  if BRING_MOBS.conn then return end
  BRING_MOBS.conn = G.RS.Heartbeat:Connect(function()
    if not S.bringMob then return end
    local character = G.LP.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then return end
    local myPos = root.Position
    
    -- Claim network ownership over unanchored workspace mobs via simulation radius elevation
    pcall(function()
      if setsimulationradius then setsimulationradius(9e9, 9e9) end
      if sethiddenproperty then
        sethiddenproperty(G.LP, "SimulationRadius", 9e9)
        sethiddenproperty(G.LP, "MaxSimulationRadius", 9e9)
        sethiddenproperty(settings().Physics, "AllowSleep", false)
      end
    end)
    
    local live = G.WS:FindFirstChild("Live") or G.WS
    for _, m in ipairs(live:GetChildren()) do
      if m:IsA("Model") and m ~= character and not G.Plrs:GetPlayerFromCharacter(m) then
        local hrp = m:FindFirstChild("HumanoidRootPart")
        local hum = m:FindFirstChildOfClass("Humanoid")
        if hrp and hum and hum.Health > 0 then
          local dist = (hrp.Position - myPos).Magnitude
          if dist <= BRING_MOBS.range and dist > 6 then
            pcall(function()
              local targetCF = root.CFrame * G.CF(0, 0, -6)
              
              -- Force network ownership if executor supports setnetworkowner
              if setnetworkowner then pcall(function() setnetworkowner(hrp, G.LP) end) end
              
              -- Move model & HRP
              m:PivotTo(targetCF)
              hrp.CFrame = targetCF
              
              hrp.AssemblyLinearVelocity = G.V3(0.01, 0, 0.01)
              
              for _, p in ipairs(m:GetDescendants()) do
                if p:IsA("BasePart") then
                  p.CanCollide = false
                end
              end
            end)
          end
        end
      end
    end
  end)
end
function BRING_MOBS.stop()
  if BRING_MOBS.conn then
    BRING_MOBS.conn:Disconnect()
    BRING_MOBS.conn = nil
  end
end

-- ATTACH TO BACK (Standalone Undetected Attach - Range 300-1000 Studs)
-- Smoothly attaches your character directly to selected target's back
local ATTACH_PLAYER = {
  target = nil,
  conn = nil,
  offset = G.CF(0, 1.5, 3.5),
  tweenInfo = G.TI(0.08, Enum.EasingStyle.Linear, Enum.EasingDirection.Out)
}

function ATTACH_PLAYER.start(targetPlayer)
  if not targetPlayer or targetPlayer == G.LP then return end
  local myChar = G.LP.Character
  local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
  local tChar = targetPlayer.Character
  local tRoot = tChar and tChar:FindFirstChild("HumanoidRootPart")
  if not myRoot or not tRoot then return end
  
  local maxRange = CFG.AttachRange or 500
  local dist = (tRoot.Position - myRoot.Position).Magnitude
  if dist > maxRange then
    G.noti("Attach", "Target beyond range ("..math.floor(dist).."m > "..maxRange.."m)")
    return
  end
  
  ATTACH_PLAYER.target = targetPlayer
  S.attach = true
  if UI and UI.updTog then UI.updTog() end
  if UI and UI.syncValue then UI.syncValue("AttachPlayerTarget") end
  if ATTACH_PLAYER.conn then return end
  
  ATTACH_PLAYER.conn = G.RS.RenderStepped:Connect(function()
    if not S.attach or not ATTACH_PLAYER.target or not ATTACH_PLAYER.target.Character then
      ATTACH_PLAYER.stop()
      return
    end
    local mChar = G.LP.Character
    local mRoot = mChar and mChar:FindFirstChild("HumanoidRootPart")
    local trRoot = ATTACH_PLAYER.target.Character:FindFirstChild("HumanoidRootPart")
    if not mRoot or not trRoot then
      ATTACH_PLAYER.stop()
      return
    end
    
    -- Auto-detach if target moves past configured attach range
    local limit = CFG.AttachRange or 500
    local curDist = (trRoot.Position - mRoot.Position).Magnitude
    if curDist > limit then
      ATTACH_PLAYER.stop()
      G.noti("Attach", "Target moved beyond range limit!")
      return
    end
    
    -- Target CFrame with back offset
    local targetCF = trRoot.CFrame * ATTACH_PLAYER.offset
    
    -- Undetected attach via TweenService + linear velocity match
    pcall(function()
      G.TS:Create(mRoot, ATTACH_PLAYER.tweenInfo, {CFrame = targetCF}):Play()
      mRoot.AssemblyLinearVelocity = trRoot.AssemblyLinearVelocity
    end)
    
    -- Turn off collisions while attached
    for _, p in ipairs(mChar:GetDescendants()) do
      if p:IsA("BasePart") then
        p.CanCollide = false
      end
    end
  end)
end

function ATTACH_PLAYER.stop()
  if ATTACH_PLAYER.conn then
    ATTACH_PLAYER.conn:Disconnect()
    ATTACH_PLAYER.conn = nil
  end
  ATTACH_PLAYER.target = nil
  S.attach = false
  if UI and UI.updTog then UI.updTog() end
  if UI and UI.syncValue then UI.syncValue("AttachPlayerTarget") end
end

