local GAMMA_LOCK = {
  conn = nil,
  childConn = nil,
  cc = nil,
  original = nil,
  _applying = false,
}
function GAMMA_LOCK.apply()
  local v = CFG.GammaVal or 0
  if GAMMA_LOCK._applying then return end
  GAMMA_LOCK._applying = true
  pcall(function()
    local light = game:GetService("Lighting")
    local cc = light:FindFirstChild("KatalystGammaCC")
    
    if v <= 0 then
      if cc then cc.Enabled = false end
      light.ExposureCompensation = 0
      GAMMA_LOCK._applying = false
      return
    end

    light.Brightness = math.clamp(1 + v * 1.5, 1, 10)
    light.ExposureCompensation = v * 0.8
    
    local brightVal = math.clamp(math.floor(70 + v * 30), 0, 255)
    light.Ambient = Color3.fromRGB(brightVal, brightVal, brightVal)
    light.OutdoorAmbient = Color3.fromRGB(brightVal, brightVal, brightVal)
    light.GlobalShadows = false

    if not cc then
      cc = Instance.new("ColorCorrectionEffect")
      cc.Name = "KatalystGammaCC"
      cc.Parent = light
    end
    cc.Brightness = v * 0.15
    cc.Contrast = v * 0.08
    cc.TintColor = Color3.fromRGB(255, 255, 255)
    cc.Enabled = true
    GAMMA_LOCK.cc = cc
  end)
  GAMMA_LOCK._applying = false
end

function GAMMA_LOCK.start()
  local light = game:GetService("Lighting")
  if not GAMMA_LOCK.original then
    GAMMA_LOCK.original = {
      Brightness = light.Brightness,
      ExposureCompensation = light.ExposureCompensation,
      Ambient = light.Ambient,
      OutdoorAmbient = light.OutdoorAmbient,
      GlobalShadows = light.GlobalShadows,
    }
  end
  GAMMA_LOCK.apply()
  if not GAMMA_LOCK.conn then
    GAMMA_LOCK.conn = light:GetPropertyChangedSignal("Brightness"):Connect(function()
      if not GAMMA_LOCK._applying then GAMMA_LOCK.apply() end
    end)
    GAMMA_LOCK.childConn = light:GetPropertyChangedSignal("ExposureCompensation"):Connect(function()
      if not GAMMA_LOCK._applying then GAMMA_LOCK.apply() end
    end)
  end
end

function GAMMA_LOCK.stop()
  if GAMMA_LOCK.conn then
    GAMMA_LOCK.conn:Disconnect()
    GAMMA_LOCK.conn = nil
  end
  if GAMMA_LOCK.childConn then
    GAMMA_LOCK.childConn:Disconnect()
    GAMMA_LOCK.childConn = nil
  end

  local light = game:GetService("Lighting")
  GAMMA_LOCK._applying = true
  pcall(function()
    local cc = GAMMA_LOCK.cc or light:FindFirstChild("KatalystGammaCC")
    if cc then cc:Destroy() end
    if GAMMA_LOCK.original then
      light.Brightness = GAMMA_LOCK.original.Brightness
      light.ExposureCompensation = GAMMA_LOCK.original.ExposureCompensation
      light.Ambient = GAMMA_LOCK.original.Ambient
      light.OutdoorAmbient = GAMMA_LOCK.original.OutdoorAmbient
      light.GlobalShadows = GAMMA_LOCK.original.GlobalShadows
    end
  end)
  GAMMA_LOCK._applying = false
  GAMMA_LOCK.cc = nil
  GAMMA_LOCK.original = nil
end

local FOV_LOCK = { conn = nil, originals = {}, _applying = false }
function FOV_LOCK.apply()
  if FOV_LOCK._applying then return end
  FOV_LOCK._applying = true
  pcall(function()
    local cam = workspace.CurrentCamera or workspace:FindFirstChildOfClass("Camera")
    if cam then
      if S.fovEnabled then
        if FOV_LOCK.originals[cam] == nil then
          FOV_LOCK.originals[cam] = cam.FieldOfView
        end
        local targetFov = math.clamp(CFG.FovVal or 70, 30, 160)
        cam.FieldOfView = targetFov
      end
    end
  end)
  FOV_LOCK._applying = false
end

function FOV_LOCK.start()
  FOV_LOCK.apply()
  if not FOV_LOCK.conn then
    FOV_LOCK.conn = G.RS.RenderStepped:Connect(function()
      if S.fovEnabled then FOV_LOCK.apply() end
    end)
  end
end

function FOV_LOCK.stop()
  S.fovEnabled = false
  if FOV_LOCK.conn then
    FOV_LOCK.conn:Disconnect()
    FOV_LOCK.conn = nil
  end
  for camera, fieldOfView in pairs(FOV_LOCK.originals) do
    pcall(function()
      if camera and camera.Parent then camera.FieldOfView = fieldOfView end
    end)
  end
  table.clear(FOV_LOCK.originals)
  FOV_LOCK._applying = false
end

EGIRL_DETECTOR = { scanned = {}, conn = nil }
function EGIRL_DETECTOR.scanPlayer(p)
  if not p or p == G.LP or (EGIRL_DETECTOR.scanned and EGIRL_DETECTOR.scanned[p.UserId]) then return end
  EGIRL_DETECTOR.scanned[p.UserId] = true
  task.spawn(function()
    pcall(function()
      local uId = p.UserId
      local url = "https://users.roblox.com/v1/users/" .. uId
      local raw = G.httpGet(url)
      if not raw or #raw < 5 then return end
      
      local okDec, data = pcall(function() return G.HS:JSONDecode(raw) end)
      if not okDec or type(data) ~= "table" then return end

      local desc = tostring(data.description or ""):lower()
      local keywords = {"she/her", "she/them", "she / her", "she", "girl", "e-girl", "egirl", "princess", "cutie", "queen", "female", "woman", "gf", "girlfriend"}
      
      local matched = {}
      for _, kw in ipairs(keywords) do
        if string.find(desc, kw, 1, true) then
          table.insert(matched, kw)
        end
      end

      if #matched > 0 then
        local pName = string.format("%s (@%s)", p.DisplayName or p.Name, p.Name)
        local matchStr = table.concat(matched, ", ")
        G.noti("E-GIRL DETECTED", string.format("%s (Keywords: %s)", pName, matchStr), 8)
        print(string.format("[Katalyst]  E-GIRL DETECTED: %s | Profile Bio: %s | Matched: %s", pName, data.description or "", matchStr))
      end
    end)
  end)
end

function EGIRL_DETECTOR.start()
  for _, p in ipairs(G.Plrs:GetPlayers()) do EGIRL_DETECTOR.scanPlayer(p) end
  if not EGIRL_DETECTOR.conn then
    EGIRL_DETECTOR.conn = G.Plrs.PlayerAdded:Connect(function(p)
      if S.egirlDetector then EGIRL_DETECTOR.scanPlayer(p) end
    end)
  end
end

function EGIRL_DETECTOR.stop()
  if EGIRL_DETECTOR.conn then EGIRL_DETECTOR.conn:Disconnect(); EGIRL_DETECTOR.conn = nil end
end

local SPEC = { cur = nil, conn = nil }
function SPEC.start(targetPlayer)
  if not targetPlayer or targetPlayer == G.LP then
    SPEC.stop()
    return
  end
  SPEC.cur = targetPlayer
  S.spec = true
  if UI and UI.updDyn then pcall(UI.updDyn) end
  G.noti("Spectate", "Spectating: " .. (targetPlayer.DisplayName or targetPlayer.Name))
  
  if SPEC.conn then pcall(function() SPEC.conn:Disconnect() end); SPEC.conn = nil end
  pcall(function() G.RS:UnbindFromRenderStep("KatalystSpectate") end)

  -- Stream map chunks around target on initial click without repeating network calls
  pcall(function()
    local char = targetPlayer.Character
    local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head"))
    if root then workspace:RequestStreamAroundAsync(root.Position) end
  end)

  SPEC.conn = G.RS.RenderStepped:Connect(function()
    if not S.spec or not SPEC.cur or not SPEC.cur.Parent then
      SPEC.stop()
      return
    end
    local char = SPEC.cur.Character
    if not char then
      pcall(function()
        local cam = G.WS.CurrentCamera
        if cam then cam.CameraType = Enum.CameraType.Scriptable end
      end)
      return
    end
    local root = char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("Head")
    if not root then return end

    local cam = G.WS.CurrentCamera
    if cam then
      cam.CameraType = Enum.CameraType.Scriptable
      local rootPos = root.Position
      local focusPos = rootPos + Vector3.new(0, 2, 0)
      local camPos = rootPos + (root.CFrame.LookVector * -12) + Vector3.new(0, 5, 0)
      cam.CFrame = CFrame.new(camPos, focusPos)
      cam.Focus = CFrame.new(focusPos)
    end
  end)
end

function SPEC.stop()
  SPEC.cur = nil
  S.spec = false
  if SPEC.conn then
    pcall(function() SPEC.conn:Disconnect() end)
    SPEC.conn = nil
  end
  pcall(function() G.RS:UnbindFromRenderStep("KatalystSpectate") end)
  
  local cam = G.WS.CurrentCamera
  if cam then
    pcall(function()
      local lpChar = G.LP.Character
      local lpRoot = lpChar and lpChar:FindFirstChild("HumanoidRootPart")
      local lpHum = lpChar and lpChar:FindFirstChildOfClass("Humanoid")
      
      cam.CameraType = Enum.CameraType.Custom
      if lpHum then
        cam.CameraSubject = lpHum
      elseif lpRoot then
        cam.CameraSubject = lpRoot
      end
      
      if lpRoot then
        cam.Focus = lpRoot.CFrame
        cam.CFrame = lpRoot.CFrame * CFrame.new(0, 3, 10)
      end
    end)
  end

  if UI and UI.updDyn then pcall(UI.updDyn) end
end

function SPEC.tog()
  if S.spec then
    if SPEC.cur then
      SPEC.start(SPEC.cur)
    else
      for _, p in ipairs(G.Plrs:GetPlayers()) do
        if p ~= G.LP then
          SPEC.start(p)
          break
        end
      end
    end
  else
    SPEC.stop()
  end
end
function SPEC.next()
  local plrs = {}
  for _, p in ipairs(G.Plrs:GetPlayers()) do
    if p ~= G.LP then table.insert(plrs, p) end
  end
  if #plrs == 0 then return end
  local curIdx = table.find(plrs, SPEC.cur) or 0
  local nextIdx = (curIdx % #plrs) + 1
  SPEC.start(plrs[nextIdx])
end
function SPEC.prev()
  local plrs = {}
  for _, p in ipairs(G.Plrs:GetPlayers()) do
    if p ~= G.LP then table.insert(plrs, p) end
  end
  if #plrs == 0 then return end
  local curIdx = table.find(plrs, SPEC.cur) or 1
  local prevIdx = curIdx - 1
  if prevIdx < 1 then prevIdx = #plrs end
  SPEC.start(plrs[prevIdx])
end
