-- are locked to Action4 priority with 1.0 weight so they NEVER break!
local FALLBACK_NUKER_ANIMS = {
  "rbxassetid://9149348937",
  "rbxassetid://7627889074",
  "rbxassetid://7620630583",
  "rbxassetid://8378263543",
  "rbxassetid://18897116048",
  "rbxassetid://18897118423",
  "rbxassetid://18897121015"
}

local SPOOF_HEADERS = { "Walk", "Run", "Idle", "Jump", "Fall", "Climb", "Swim" }

local function getClientPing()
  local ping = 50
  pcall(function()
    local statsItem = game:GetService("Stats").Network.ServerStatsItem:FindFirstChild("Data Ping")
    if statsItem then ping = statsItem:GetValue() end
  end)
  return ping
end

local function isPlayerMovingNow(ch, hum)
  if not hum or not ch then return false end
  if hum.MoveDirection.Magnitude > 0.05 then return true end
  local hrp = ch:FindFirstChild("HumanoidRootPart")
  if hrp then
    local vel = hrp.AssemblyLinearVelocity or hrp.Velocity
    if Vector2.new(vel.X, vel.Z).Magnitude > 1.2 then return true end
  end
  return false
end

local function isPlayerM1ingNow(ch, ani)
  if not ch then return false end
  local isMouseHeld = false
  pcall(function()
    isMouseHeld = game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
  end)
  if isMouseHeld then return true end
  if ch:GetAttribute("Attacking") or ch:GetAttribute("InAttack")
  or ch:GetAttribute("Swing")     or ch:GetAttribute("Action") == "Attack" then
    return true
  end
  pcall(function()
    local rep = game:GetService("ReplicatedStorage"):FindFirstChild("EffectReplicator")
    if rep then
      local mod = require(rep)
      if mod and type(mod.HasEffect) == "function" then
        if mod:HasEffect("LightAttack") or mod:HasEffect("CriticalAttack")
        or mod:HasEffect("HeavyAttack") or mod:HasEffect("Followup") then
          return true
        end
      end
    end
  end)
  if ani then
    for _, trk in ipairs(ani:GetPlayingAnimationTracks()) do
      if trk and trk.IsPlaying and trk.Animation then
        local aName = string.lower(trk.Animation.Name or "")
        if string.find(aName, "attack") or string.find(aName, "swing")
        or string.find(aName, "slash")  or string.find(aName, "crit")
        or string.find(aName, "light")  or string.find(aName, "m1") then
          return true
        end
      end
    end
  end
  return false
end

AP_NUKER = { on = false, stop = nil, cc = nil }

do
  local function runMovementNuker(ch)
    if not ch then return function() end end

    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end

    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then
      ani = Instance.new("Animator")
      ani.Parent = hum
    end

    local loadedTracks  = {}
    local isNukerTrack  = {}

    for _, id in ipairs(FALLBACK_NUKER_ANIMS) do
      pcall(function()
        local animation = Instance.new("Animation")
        animation.AnimationId = id
        animation.Name = SPOOF_HEADERS[math.random(1, #SPOOF_HEADERS)]
        local track = ani:LoadAnimation(animation)
        table.insert(loadedTracks, track)
        isNukerTrack[track] = true
        animation:Destroy()
      end)
    end

    pcall(function()
      local animateScript = ch:FindFirstChild("Animate")
      for _, item in ipairs(ch:GetDescendants()) do
        if item:IsA("Animation") and item.AnimationId ~= "" then
          if animateScript and item:IsDescendantOf(animateScript) then continue end
          pcall(function()
            local animClone = item:Clone()
            animClone.Name = SPOOF_HEADERS[math.random(1, #SPOOF_HEADERS)]
            local track = ani:LoadAnimation(animClone)
            table.insert(loadedTracks, track)
            isNukerTrack[track] = true
            animClone:Destroy()
          end)
        end
      end
    end)

    local trackCount   = #loadedTracks
    if trackCount == 0 then return function() end end

    local running      = true
    local trackIdx     = 1
    local activeTracks = {}
    local wasMoving    = false

    task.spawn(function()
      while running and AP_NUKER.on and S.apNuker do
        if not ch.Parent then break end

        if wasMoving then
          for _, tr in ipairs(activeTracks) do
            pcall(function()
              if tr and tr.IsPlaying and isNukerTrack[tr] then
                tr:Stop(0)
              end
            end)
          end
        end
        table.clear(activeTracks)

        if isPlayerM1ingNow(ch, ani) or not isPlayerMovingNow(ch, hum) then
          wasMoving = false
          task.wait(0.03)
          continue
        end

        -- Proximity Range Check
        if CFG.PT_ProxCheck then
          local myHrp = ch:FindFirstChild("HumanoidRootPart")
          if myHrp then
            local maxDist = tonumber(CFG.PT_ProxRange) or 500
            local inRange = false
            local live = workspace:FindFirstChild("Live") or workspace
            for _, entity in ipairs(live:GetChildren()) do
              if entity:IsA("Model") and entity ~= ch
              and entity:FindFirstChild("HumanoidRootPart") then
                if (entity.HumanoidRootPart.Position - myHrp.Position).Magnitude <= maxDist then
                  inRange = true
                  break
                end
              end
            end
            if not inRange then
              wasMoving = false
              task.wait(0.05)
              continue
            end
          end
        end

        -- Ping-Safe Network Throttling
        local currentPing = getClientPing()
        local targetPPS   = math.clamp(tonumber(CFG.PT_PPS) or 5000, 250, 25000)
        local batchStep   = 0.025
        local actualPPS   = targetPPS

        if currentPing > 50 then
          actualPPS = math.clamp(actualPPS, 250, 700)
          batchStep = 0.04
        end

        local batchCount = math.clamp(math.floor(actualPPS * batchStep), 1, 50)
        local wt = math.clamp(tonumber(CFG.PT_Weight) or 1.0, 0.01, 1.0)

        pcall(function()
          for i = 1, batchCount do
            if not running or not AP_NUKER.on then break end
            local tr = loadedTracks[trackIdx]
            trackIdx = (trackIdx % trackCount) + 1
            if tr then
              tr.Priority = Enum.AnimationPriority.Movement
              tr:Play(0.001, wt, 1.0)
              tr:AdjustWeight(wt)
              tr:AdjustSpeed(1.0)
              table.insert(activeTracks, tr)
            end
          end
        end)

        wasMoving = true
        task.wait(batchStep)
      end

      -- Clean loop termination
      for _, tr in ipairs(loadedTracks) do
        pcall(function() tr:Stop(0); tr:Destroy() end)
      end
    end)

    return function()
      running = false
      for _, tr in ipairs(loadedTracks) do
        pcall(function()
          tr:Stop(0)
          tr:Destroy()
        end)
      end
      pcall(function()
        for _, tr in ipairs(ani:GetPlayingAnimationTracks()) do
          if isNukerTrack[tr] then
            tr:Stop(0)
            tr:Destroy()
          end
        end
      end)
    end
  end

  function AP_NUKER:start()
    if self.on then return end
    self.on = true
    local lp = G.LP or game:GetService("Players").LocalPlayer
    if not self.cc then
      self.cc = lp.CharacterAdded:Connect(function(ch)
        if self.stop then pcall(self.stop) end
        if self.on and S.apNuker then self.stop = runMovementNuker(ch) end
      end)
    end
    task.spawn(function()
      if self.stop then pcall(self.stop) end
      local character = lp.Character or lp.CharacterAdded:Wait()
      if self.on and S.apNuker then self.stop = runMovementNuker(character) end
    end)
  end

  function AP_NUKER:stp()
    self.on = false
    S.apNuker = false
    if self.stop then
      pcall(self.stop)
      self.stop = nil
    end
    if self.cc then
      pcall(function() self.cc:Disconnect() end)
      self.cc = nil
    end
  end
end

local M1_FALLBACK_NUKER_ANIMS = {
  "rbxassetid://9149348937",
  "rbxassetid://7627889074",
  "rbxassetid://5778357994",
  "rbxassetid://16873988732",
  "rbxassetid://7620630583",
  "rbxassetid://8378263543",
}

local function isDeveloperM1ingNow(ch, ani, isNukerTrack, nukerIds)
  if not ch then return false end
  local isMouseHeld = false
  pcall(function()
    isMouseHeld = game:GetService("UserInputService"):IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
  end)
  if isMouseHeld then return true end
  if ch:GetAttribute("Attacking") or ch:GetAttribute("InAttack")
  or ch:GetAttribute("Swing")     or ch:GetAttribute("Action") == "Attack" then
    return true
  end
  pcall(function()
    local rep = game:GetService("ReplicatedStorage"):FindFirstChild("EffectReplicator")
    if rep then
      local mod = require(rep)
      if mod and type(mod.HasEffect) == "function" then
        if mod:HasEffect("LightAttack") or mod:HasEffect("CriticalAttack")
        or mod:HasEffect("HeavyAttack") or mod:HasEffect("Followup")
        or mod:HasEffect("Uppercut") or mod:HasEffect("RunningAttack") then
          return true
        end
      end
    end
  end)
  if ani then
    for _, trk in ipairs(ani:GetPlayingAnimationTracks()) do
      if trk and trk.IsPlaying and (not isNukerTrack or not isNukerTrack[trk]) then
        local aName = string.lower(trk.Name or (trk.Animation and trk.Animation.Name) or "")
        local aId = trk.Animation and tostring(trk.Animation.AnimationId):match("%d+")
        if not (aId and nukerIds and nukerIds[aId]) then
          if not (aName:find("walk") or aName:find("run") or aName:find("idle") or aName:find("jump") or aName:find("fall") or aName:find("climb") or aName:find("swim") or aName:find("slide") or aName:find("crouch") or aName:find("equip") or aName:find("sheathe")) then
            local pri = trk.Priority
            if pri.Value >= Enum.AnimationPriority.Action.Value or aName:find("attack") or aName:find("swing") or aName:find("slash") or aName:find("crit") or aName:find("m1") or aName:find("uppercut") or aName:find("running") then
              return true
            end
          end
        end
      end
    end
  end
  return false
end

M1_NUKER = { on = false, stop = nil, cc = nil }

do
  local function runM1Nuker(ch)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then ani = Instance.new("Animator"); ani.Parent = hum end

    local loadedTracks = {}
    local isNukerTrack = {}
    local nukerIds = {}

    -- Use verified Deepwoken combat animation assets
    local animPool = CFG.APAnims or M1_FALLBACK_NUKER_ANIMS
    for _, id in ipairs(animPool) do
      pcall(function()
        local a = Instance.new("Animation")
        a.AnimationId = id
        local tr = ani:LoadAnimation(a)
        tr.Priority = Enum.AnimationPriority.Action
        table.insert(loadedTracks, tr)
        isNukerTrack[tr] = true
        local numId = tostring(id):match("%d+")
        if numId then nukerIds[numId] = true end
      end)
    end

    -- Also load weapon and character animations for authentic packets
    pcall(function()
      for _, item in ipairs(ch:GetDescendants()) do
        if item:IsA("Animation") and item.AnimationId ~= "" then
          local numId = tostring(item.AnimationId):match("%d+")
          if numId and not nukerIds[numId] then
            pcall(function()
              local tr = ani:LoadAnimation(item)
              tr.Priority = Enum.AnimationPriority.Action
              table.insert(loadedTracks, tr)
              isNukerTrack[tr] = true
              nukerIds[numId] = true
            end)
          end
        end
      end
    end)

    local trackCount = #loadedTracks
    if trackCount == 0 then return function() end end

    local running = true
    local trackIdx = 1
    local lastPrioritySweep = 0

    -- Real Combat Attack Priority Booster (M1, Running Attack, Uppercut, Flourish, Mantras)
    local function boostRealAttack(trk)
      if not trk or isNukerTrack[trk] then return end
      local anim = trk.Animation
      local aName = string.lower(trk.Name or (anim and anim.Name) or "")

      -- Never touch locomotion or emote tracks
      if aName:find("walk") or aName:find("run") or aName:find("idle") or aName:find("jump") 
      or aName:find("fall") or aName:find("climb") or aName:find("swim") or aName:find("slide") 
      or aName:find("crouch") or aName:find("equip") or aName:find("sheathe") or aName:find("unsheathe") then
        return
      end

      pcall(function()
        trk.Priority = Enum.AnimationPriority.Action4
        trk:AdjustWeight(1.0, 0)
      end)
    end

    local animPlayConn = ani.AnimationPlayed:Connect(function(trk)
      if running then boostRealAttack(trk) end
    end)

    task.spawn(function()
      while running and M1_NUKER.on and S.m1Nuker do
        if not ch.Parent then break end

        local now = os.clock()

        -- Periodic sweep to guarantee real attack stays at Action4
        if now - lastPrioritySweep >= 0.10 then
          lastPrioritySweep = now
          pcall(function()
            for _, playingTrk in ipairs(ani:GetPlayingAnimationTracks()) do
              if playingTrk and playingTrk.IsPlaying and not isNukerTrack[playingTrk] then
                boostRealAttack(playingTrk)
              end
            end
          end)
        end

        local isAttacking = isDeveloperM1ingNow(ch, ani)

        if not isAttacking then
          task.wait(0.02)
          continue
        end

        -- Proximity Range Check
        if CFG.PT_ProxCheck then
          local myHrp = ch:FindFirstChild("HumanoidRootPart")
          if myHrp then
            local maxDist = tonumber(CFG.PT_ProxRange) or 500
            local inRange = false
            local live = workspace:FindFirstChild("Live") or workspace
            for _, entity in ipairs(live:GetChildren()) do
              if entity:IsA("Model") and entity ~= ch and entity:FindFirstChild("HumanoidRootPart") then
                if (entity.HumanoidRootPart.Position - myHrp.Position).Magnitude <= maxDist then
                  inRange = true
                  break
                end
              end
            end
            if not inRange then
              task.wait(0.05)
              continue
            end
          end
        end

        local targetPPS = math.clamp(tonumber(CFG.M1_PPS) or tonumber(CFG.PT_PPS) or 2000, 100, 10000)
        local wt = math.clamp(tonumber(CFG.M1_Weight) or 1.0, 0.1, 1.0)
        local spd = math.clamp(tonumber(CFG.M1_Speed) or 2.5, 0.1, 5.0)
        local fadeIn = math.max(0, (tonumber(CFG.M1_FadeIn) or 0) / 1000)
        local batchStep = 0.016
        local batchCount = math.clamp(math.floor(targetPPS * batchStep), 1, 300)

        pcall(function()
          for i = 1, batchCount do
            if not running or not M1_NUKER.on then break end
            local tr = loadedTracks[trackIdx]
            trackIdx = (trackIdx % trackCount) + 1
            if tr then
              tr.Priority = Enum.AnimationPriority.Action
              tr:Play(fadeIn, wt, spd)
              tr.TimePosition = 0.04 + (i * 0.001)
            end
          end
        end)

        task.wait(batchStep)
      end

      for _, tr in ipairs(loadedTracks) do
        pcall(function() tr:Stop(0); tr:Destroy() end)
      end
    end)

    return function()
      running = false
      if animPlayConn then pcall(function() animPlayConn:Disconnect() end) end
      for _, tr in ipairs(loadedTracks) do
        pcall(function() tr:Stop(0); tr:Destroy() end)
      end
      pcall(function()
        for _, tr in ipairs(ani:GetPlayingAnimationTracks()) do
          if isNukerTrack[tr] then
            tr:Stop(0)
            tr:Destroy()
          end
        end
      end)
    end
  end

  function M1_NUKER:start()
    if self.on then return end
    self.on = true
    local lp = G.LP or game:GetService("Players").LocalPlayer
    if not self.cc then
      self.cc = lp.CharacterAdded:Connect(function(ch)
        if self.stop then pcall(self.stop) end
        if self.on and S.m1Nuker then self.stop = runM1Nuker(ch) end
      end)
    end
    task.spawn(function()
      if self.stop then pcall(self.stop) end
      local character = lp.Character or lp.CharacterAdded:Wait()
      if self.on and S.m1Nuker then self.stop = runM1Nuker(character) end
    end)
  end

  function M1_NUKER:stp()
    self.on = false
    S.m1Nuker = false
    if self.stop then
      pcall(self.stop)
      self.stop = nil
    end
    if self.cc then
      pcall(function() self.cc:Disconnect() end)
      self.cc = nil
    end
  end
end

-- How it works:
--    c. Stop(0.0) -> Fires track.Stopped event and sets IsPlaying = false on all enemy clients.
--    finish registering before the stop signal is replicated.
local DESYNC_BREAKER = { on = false, stop = nil, cc = nil }
do
  local function runStopSignalBreaker(ch)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then ani = Instance.new("Animator"); ani.Parent = hum end
    
    local processedTracks = {}
    local animConn = nil

    local function handleTrack(track)
      if not DESYNC_BREAKER.on and not S.desyncBreaker then return end
      if not track or not track.Animation then return end
      if processedTracks[track] then return end
      
      local animObj = track.Animation
      local animId = tostring(animObj.AnimationId or "")
      local animName = string.lower(animObj.Name or track.Name or "")
      local pri = track.Priority

      if pri == Enum.AnimationPriority.Idle or pri == Enum.AnimationPriority.Core then
        return
      end

      -- Ignore movement/idle/roll/dodge/emote tracks
      if animName:find("idle") or animName:find("walk") or animName:find("run") or animName:find("jump") or animName:find("fall") or animName:find("land") or animName:find("sit") or animName:find("dance") or animName:find("strafe") or animName:find("roll") or animName:find("dodge") or animName:find("slide") then
        return
      end

      local isMantra = animName:find("spell") or animName:find("mantra") or animName:find("skill") or 
        animName:find("cast") or animName:find("chant") or animName:find("magic") or animName:find("ability") or
        animName:find("flame") or animName:find("frost") or animName:find("gale") or animName:find("thunder") or 
        animName:find("shadow") or animName:find("blood") or animName:find("iron")
        
      if not isMantra and NAMED_MANTRA_TIMINGS then
        local pureId = animId:gsub("%D+", "")
        if pureId ~= "" then
          for mantraId, _ in pairs(NAMED_MANTRA_TIMINGS) do
            if tostring(mantraId):find(pureId) then
              isMantra = true
              break
            end
          end
        end
      end

      local isM1 = false
      if isM1Track and isM1Track(track) then
        isM1 = true
      elseif animName:find("m1") or animName:find("swing") or animName:find("slash") or 
        animName:find("strike") or animName:find("light") or animName:find("heavy") or 
        animName:find("weapon") or animName:find("attack") or animName:find("crit") or animName:find("flourish") or
        pri == Enum.AnimationPriority.Action or pri == Enum.AnimationPriority.Action2 or pri == Enum.AnimationPriority.Action3 then
        isM1 = true
      end

      if isMantra and (S.desyncMantras == false) then return end
      if isM1 and (S.stopSignalM1 == false) then return end
      if not isM1 and not isMantra then return end

      processedTracks[track] = true

      -- Scaled micro delay: M1s vs Mantras
      local delayMs
      if isMantra then
        delayMs = tonumber(CFG.StopSignalDelayMantra) or 75
      else
        delayMs = tonumber(CFG.StopSignalDelayM1) or tonumber(CFG.StopSignalDelay) or 28
      end
      local stopDelaySec = math.clamp(delayMs / 1000, 0.012, 0.30)

      task.spawn(function()
        task.wait(stopDelaySec)
        pcall(function()
          if track.IsPlaying then
            pcall(function() track:AdjustWeight(0.0001, 0.0) end)
            pcall(function() track:AdjustSpeed(0) end)
            -- Vector 3: Fire Stopped signal + set IsPlaying = false on network
            track:Stop(0.0)

            pcall(function()
              if effectReplicatorModule and effectReplicatorModule.CreateEffect then
                local feintEff = effectReplicatorModule:CreateEffect("ClientFeint")
                if feintEff and feintEff.Debris then feintEff:Debris(0.20) end
              end
            end)

            if PARRY_LOGS_UI and PARRY_LOGS_UI.add then
              PARRY_LOGS_UI.add(string.format("[AP BREAKER] Multi-Vector Stop Signal on %s '%s' (Ghost Feint @ %dms)", 
                isMantra and "Mantra" or "M1", animName ~= "" and animName or animId:gsub("%D+", ""), delayMs))
            end
          end
        end)
      end)
    end

    animConn = ani.AnimationPlayed:Connect(handleTrack)
    for _, tr in ipairs(ani:GetPlayingAnimationTracks()) do
      task.spawn(function() handleTrack(tr) end)
    end

    return function()
      if animConn then pcall(function() animConn:Disconnect() end); animConn = nil end
      processedTracks = {}
    end
  end

  local function attDesync(ch)
    if DESYNC_BREAKER.stop then DESYNC_BREAKER.stop() end
    DESYNC_BREAKER.stop = nil
    if not DESYNC_BREAKER.on or not ch then return end
    DESYNC_BREAKER.stop = runStopSignalBreaker(ch)
  end

  function DESYNC_BREAKER:start()
    if self.on then return end
    self.on = true
    if not self.cc then
      self.cc = G.LP.CharacterAdded:Connect(attDesync)
    end
    pcall(function() if OWN_ID_SPOOFER and OWN_ID_SPOOFER.start then OWN_ID_SPOOFER:start() end end)
    task.spawn(function()
      attDesync(G.LP.Character or G.LP.CharacterAdded:Wait())
    end)
  end

  function DESYNC_BREAKER:stp()
    if not self.on then return end
    self.on = false
    pcall(function() if OWN_ID_SPOOFER and OWN_ID_SPOOFER.stop then OWN_ID_SPOOFER:stop() end end)
    if self.stop then self.stop(); self.stop = nil end
    if self.cc then self.cc:Disconnect(); self.cc = nil end
  end
end

MANTRA_FEINT_BREAKER = DESYNC_BREAKER
FEINT_BREAKER = DESYNC_BREAKER

