local function setOwnedRingAttribute(ch, name)
  local owned = PACKET_DISRUPTION.ringAttributes[ch]
  if not owned then
    owned = {}
    PACKET_DISRUPTION.ringAttributes[ch] = owned
  end
  if owned[name] == nil then
    local original = ch:GetAttribute(name)
    if original == true then return end
    owned[name] = original == nil and NIL_RING_ATTRIBUTE or original
  end
  ch:SetAttribute(name, true)
end

