              ch:SetAttribute(name, original)
            end
          end
        end)
      end
    end
  end
  table.clear(PACKET_DISRUPTION.ringAttributes)
  EXTRA_ESP.stop()
end

local NO_LOW_HP_SLOWDOWN = { conn = nil }
function NO_LOW_HP_SLOWDOWN.start()
  if NO_LOW_HP_SLOWDOWN.conn then return end
  NO_LOW_HP_SLOWDOWN.conn = G.RS.Heartbeat:Connect(function()
    if S.noLowHpSlowdown == false then return end
    pcall(function()
      local ch = G.LP and G.LP.Character
      if not ch then return end
      local hum = ch:FindFirstChildOfClass("Humanoid")
      if not hum then return end
      
      local state = hum:GetState()
      if state == Enum.HumanoidStateType.Climbing
        or state == Enum.HumanoidStateType.Swimming
        or state == Enum.HumanoidStateType.Physics
        or state == Enum.HumanoidStateType.Ragdoll
        or state == Enum.HumanoidStateType.Seated
        or ch:GetAttribute("Climbing")
        or ch:GetAttribute("WallClimb")
        or ch:GetAttribute("Mantling")
        or ch:GetAttribute("Rolling")
        or ch:GetAttribute("Dashing")
        or ch:GetAttribute("Dodging") then
        return
      end

      -- Strip low-health speed penalties and injured/crippled attributes
      ch:SetAttribute("ssv_Slowdown", nil)
      ch:SetAttribute("LowHealth", false)
      ch:SetAttribute("Injured", false)
      ch:SetAttribute("Crippled", false)
      ch:SetAttribute("Limp", false)
      ch:SetAttribute("Slow", false)
      
      -- Enforce full 100% health WalkSpeed (or customized speed) regardless of current HP
      if hum.FloorMaterial ~= Enum.Material.Air then
        local agSpd = S.agil and math.max(22.0, 16.0 + ((tonumber(CFG.AgilVal) or 100) * 0.25)) or 16.0
        local wsSpd = S.agSpd and (tonumber(CFG.SpdVal) or 26.0) or 16.0
        local targetSpd = math.max(agSpd, wsSpd)
        if hum.WalkSpeed < targetSpd then
          hum.WalkSpeed = targetSpd
        end
      end
    end)
  end)
end
function NO_LOW_HP_SLOWDOWN.stop()
  if NO_LOW_HP_SLOWDOWN.conn then NO_LOW_HP_SLOWDOWN.conn:Disconnect(); NO_LOW_HP_SLOWDOWN.conn = nil end
end
task.spawn(NO_LOW_HP_SLOWDOWN.start)

