local NO_STUN_ENGINE = { conn = nil }
function NO_STUN_ENGINE.start()
  if NO_STUN_ENGINE.conn then return end
  ensureEffectHook()
  NO_STUN_ENGINE.conn = G.RS.Heartbeat:Connect(function()
    if not S.noStun then return end
    pcall(function()
      local ch = G.LP and G.LP.Character
      if not ch then return end

      ch:SetAttribute("Stun", false)
      ch:SetAttribute("Stunned", false)
      ch:SetAttribute("Stagger", false)
      ch:SetAttribute("PostureBreak", false)
      ch:SetAttribute("PB", false)
      ch:SetAttribute("HeavyStun", false)
      ch:SetAttribute("CarryStun", false)
      ch:SetAttribute("Grabbed", false)

      for _, name in ipairs({"Stun", "Stunned", "Stagger", "PostureBreak", "PB", "HeavyStun", "CarryStun", "Grabbed"}) do
        local obj = ch:FindFirstChild(name)
        if obj and (obj:IsA("BoolValue") or obj:IsA("Folder") or obj:IsA("ObjectValue")) then
          pcall(function() obj:Destroy() end)
        end
      end

      pcall(function()
        local _ef = G.RepS:FindFirstChild("EffectReplicator")
        local efMod = _ef and require(_ef)
        if efMod and efMod.Effects then
          for k, eff in pairs(efMod.Effects) do
            local cls = eff and (eff.Class or (type(eff) == "table" and rawget(eff, "index") and rawget(eff, "index").Class))
            if cls and (cls == "Stun" or cls == "Stunned" or cls == "PostureBreak"
              or cls == "Stagger" or cls == "PB" or cls == "HeavyStun"
              or cls == "CarryStun" or cls == "GettingUp" or cls == "Grabbed"
              or cls == "PostureBroken") then
              pcall(function()
                if eff.Destroy then eff:Destroy()
                elseif eff.Remove then eff:Remove() end
                efMod.Effects[k] = nil
              end)
            end
          end
        end
      end)

      local hum = ch:FindFirstChildOfClass("Humanoid")
      if hum then
        pcall(function()
          local state = hum:GetState()
          if state == Enum.HumanoidStateType.FallingDown
            or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.PlatformStanding then
            hum:ChangeState(Enum.HumanoidStateType.Running)
          end
          hum.PlatformStand = false
        end)
      end
    end)
  end)
end

function NO_STUN_ENGINE.stop()
  if NO_STUN_ENGINE.conn then NO_STUN_ENGINE.conn:Disconnect(); NO_STUN_ENGINE.conn = nil end
end
