-- Uses Temporary Safety Platforms, Ground Raycast Snapping, Physics
-- 200 studs/sec with continuous CFrame interpolation, full noclip,
-- 100% Instant teleport with Kill-Brick Neutralization, Character CanTouch
-- 100% Instant teleport with Y-Level Void Clamping, Temporary Safety Floor,
-- Zero Physics Pollution: Does NOT corrupt humanoid states or character
-- collision matrices. Uses local safety platform & chunk pre-streaming!
local TELEPORT_SYSTEM = { destination = nil, active = false, lastTp = 0 }
do
  local REALM_DESTINATIONS = {
    EasternLuminant = Vector3.new(-2632.86, 628.63, -6707.99),
    EtreanLuminant = Vector3.new(-514.26, 665.17, -4772.32),
    Depths = Vector3.new(39911.36, 39980.93, 39708.32),
    TrialOfOne = Vector3.new(-959.78, 146.99, -6659.63),
    Voidheart = Vector3.new(-20000.0, 19713.96, -20000.0)
  }

  local function findPortal(destName)
    local dLow = string.lower(tostring(destName or ""))
    if dLow == "" or dLow:find("custom") then return nil end
    -- Check known realm transition parts in workspace
    for _, path in ipairs({{"ValleyExit", "RealmTeleport"}, {"ValleyExit", "RealmTeleporter"}, {"ModOffice", "OfficePit"}}) do
      local cur = workspace
      for _, n in ipairs(path) do cur = cur and cur:FindFirstChild(n) end
      if cur and cur:IsA("BasePart") then
        local attr = string.lower(tostring(cur:GetAttribute("Realm") or ""))
        if attr ~= "" and (attr == dLow or string.find(dLow, attr, 1, true) or string.find(attr, dLow, 1, true)) then
          return cur
        elseif cur.Name == "OfficePit" and string.find(dLow, "depth", 1, true) then
          return cur
        end
      end
    end
    -- Search workspace for any portal part matching Realm
    for _, p in ipairs(workspace:GetDescendants()) do
      if p:IsA("BasePart") then
        local r = p:GetAttribute("Realm")
        if r and type(r) == "string" and #r > 1 then
          local rLow = string.lower(r)
          if rLow == dLow or string.find(dLow, rLow, 1, true) or string.find(rLow, dLow, 1, true) then
            return p
          end
        end
      end
    end
    return nil
  end

  local function executeCleanTeleport(targetPos, destName, portalPart)
    local ch = G.LP and G.LP.Character
    if not ch then return end
    local root = ch:FindFirstChild("HumanoidRootPart") or ch:FindFirstChild("Head") or ch.PrimaryPart
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not root or not hum then return end

    -- If a physical portal part exists in this server, teleport on top of it
    if portalPart then
      targetPos = portalPart.Position + Vector3.new(0, 3, 0)
    end

    pcall(function()
      if G.LP.RequestStreamAroundAsync then
        G.LP:RequestStreamAroundAsync(targetPos, 0.5)
      elseif workspace.RequestStreamAroundAsync then
        workspace:RequestStreamAroundAsync(targetPos, 0.5)
      end
    end)

    local safeFloor = Instance.new("Part")
    safeFloor.Name = "_KataSafeFloor"
    safeFloor.Size = Vector3.new(30, 2, 30)
    safeFloor.Position = targetPos - Vector3.new(0, 2.5, 0)
    safeFloor.Anchored = true
    safeFloor.CanCollide = true
    safeFloor.Transparency = 1
    safeFloor.Parent = workspace

    local targetCF = CFrame.new(targetPos + Vector3.new(0, 2, 0))
    pcall(function() ch:PivotTo(targetCF) end)
    root.CFrame = targetCF
    root.AssemblyLinearVelocity = Vector3.zero
    root.AssemblyAngularVelocity = Vector3.zero
    root.Velocity = Vector3.zero

    if portalPart then
      pcall(function()
        if type(firetouchinterest) == "function" then
          firetouchinterest(root, portalPart, 0)
          task.wait(0.05)
          firetouchinterest(root, portalPart, 1)
        end
      end)
    end

    task.delay(0.5, function()
      pcall(function()
        if safeFloor and safeFloor.Parent then
          safeFloor:Destroy()
        end
        if root and root.Parent then
          root.AssemblyLinearVelocity = Vector3.zero
          root.AssemblyAngularVelocity = Vector3.zero
          root.Velocity = Vector3.zero
        end
      end)
    end)

    G.noti("Teleport", "Teleported to " .. tostring(destName or "Destination") .. "!", 2)
  end

  function TELEPORT_SYSTEM.teleportTo(destName, customCFrame)
    local now = os.clock()
    if now - (TELEPORT_SYSTEM.lastTp or 0) < 0.2 then return end
    TELEPORT_SYSTEM.lastTp = now

    pcall(function()
      local targetPos = nil
      local portal = nil

      if customCFrame and typeof(customCFrame) == "CFrame" then
        targetPos = customCFrame.Position
      elseif customCFrame and typeof(customCFrame) == "Vector3" then
        targetPos = customCFrame
      elseif typeof(destName) == "Vector3" then
        targetPos = destName
      elseif typeof(destName) == "CFrame" then
        targetPos = destName.Position
      elseif REALM_DESTINATIONS[destName] then
        targetPos = REALM_DESTINATIONS[destName]
        portal = findPortal(tostring(destName))
      else
        portal = findPortal(tostring(destName))
        if portal then targetPos = portal.Position end
      end

      if not targetPos then return end
      executeCleanTeleport(targetPos, destName, portal)
    end)
  end

  function TELEPORT_SYSTEM.cancel()
    -- Teleport completes cleanly
  end

  function EXTRA_AUTO.teleportTo(pos)
    TELEPORT_SYSTEM.teleportTo("Custom", typeof(pos) == "CFrame" and pos or CFrame.new(pos))
  end
end

local CUSTOM_APB = {on=false,stop=nil,cc=nil}
do
  local function runPacketTimed(ch)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then ani = Instance.new("Animator"); ani.Parent = hum end
    
    -- Combine selected animation categories into active pool
    local ids = {}
    local useM1 = (CFG.PT_UseM1Anims == nil) and true or CFG.PT_UseM1Anims
    local useDef = (CFG.PT_UseDefAnims == nil) and true or CFG.PT_UseDefAnims
    local useCustom = (CFG.PT_UseCustomAnims == nil) and true or CFG.PT_UseCustomAnims

    if useM1 then
      for _, id in ipairs(CFG.APAnims or {}) do
        local cleanId = tostring(id):match("%d+")
        if cleanId then ids[cleanId] = true end
      end
    end
    if useDef then
      for _, id in ipairs(CFG.PRAnims or {}) do
        local cleanId = tostring(id):match("%d+")
        if cleanId then ids[cleanId] = true end
      end
    end
    if useCustom and CFG.CABAnimsStr and CFG.CABAnimsStr ~= "" then
      for id in string.gmatch(CFG.CABAnimsStr, "[%d]+") do
        ids[id] = true
      end
    end
    if not next(ids) then
      for _, id in ipairs(CFG.APAnims or {}) do
        local cleanId = tostring(id):match("%d+")
        if cleanId then ids[cleanId] = true end
      end
    end
    
    local tracks = {}
    for id in pairs(ids) do
      pcall(function()
        local a = Instance.new("Animation")
        a.AnimationId = "rbxassetid://" .. id
        local tr = ani:LoadAnimation(a)
        table.insert(tracks, tr)
      end)
    end
    
    if #tracks == 0 then return function() end end
    
    local activeTracks = {}
    local go = true
    local lastM1Time = 0
    
    -- REAL BASIC ATTACK PRIORITY PROTECTION
    -- Detect real character attacks and force them to Action4 (Highest Priority)
    local realAttackTrack = nil
    local attackConn = nil
    pcall(function()
      attackConn = ani.AnimationPlayed:Connect(function(trk)
        if not trk or not trk.Animation then return end
        local isBreakerTrack = false
        for _, bTr in ipairs(tracks) do
          if bTr == trk then isBreakerTrack = true; break end
        end
        if not isBreakerTrack then
          pcall(function()
            trk.Priority = Enum.AnimationPriority.Action4
            trk:AdjustWeight(1.0)
            realAttackTrack = trk
          end)
        end
      end)
    end)

    local lastJumpTime = 0
    local moveConns = {}
    pcall(function()
      local uis = game:GetService("UserInputService")
      table.insert(moveConns, uis.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if UI.library and UI.library:IsCapturingKeybind() then return end
        if input.KeyCode == Enum.KeyCode.Space then
          lastJumpTime = os.clock()
        end
      end))
      if hum then
        table.insert(moveConns, hum.Jumping:Connect(function()
          lastJumpTime = os.clock()
        end))
      end
    end)

    task.spawn(function()
      local lastPulse = os.clock()
      local frameStart = os.clock()
      local priorities = {
        Enum.AnimationPriority.Core,
        Enum.AnimationPriority.Idle,
        Enum.AnimationPriority.Movement,
        Enum.AnimationPriority.Action,
        Enum.AnimationPriority.Action2,
        Enum.AnimationPriority.Action3,
        Enum.AnimationPriority.Action4
      }
      while go do
        if not ch.Parent then break end
        if not S.apBreaker and not S.customApb then
          if #activeTracks > 0 then
            for _, tr in ipairs(activeTracks) do
              pcall(function() tr:Stop(0) end)
            end
            table.clear(activeTracks)
          end
          go = false
          break
        end
        
        -- Ensures continuous, unbroken 55k PPS animation flooding while M1 / Left-Click is held during attack combos!
        local isLmbHeld = false
        pcall(function()
          local uis = game:GetService("UserInputService")
          isLmbHeld = uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
        end)

        local isMidAttack = false
        pcall(function()
          for _, playingTrk in ipairs(ani:GetPlayingAnimationTracks()) do
            if playingTrk and playingTrk.IsPlaying and playingTrk.Animation then
              local aId = tostring(playingTrk.Animation.AnimationId):match("%d+")
              local aName = string.lower(tostring(playingTrk.Animation.Name or ""))
              
              local isBreaker = false
              if aId and ids[aId] then isBreaker = true end
              if not isBreaker then
                for _, bTr in ipairs(tracks) do
                  if bTr == playingTrk then isBreaker = true; break end
                end
              end
              
              if not isBreaker and not string.find(aName, "equip") and not string.find(aName, "unsheathe") and not string.find(aName, "sheathe") and not string.find(aName, "idle") and not string.find(aName, "walk") and not string.find(aName, "run") then
                local pVal = playingTrk.Priority.Value
                if pVal >= Enum.AnimationPriority.Action.Value then
                  isMidAttack = true
                  lastM1Time = os.clock()
                  playingTrk.Priority = Enum.AnimationPriority.Action4
                  playingTrk:AdjustWeight(1.0)
                  realAttackTrack = playingTrk
                  break
                end
              end
            end
          end
        end)

        if not isMidAttack then
          if isLmbHeld and (os.clock() - lastM1Time < 0.45) then
            isMidAttack = true
          end
        end

        if not isMidAttack then
          if #activeTracks > 0 then
            for _, tr in ipairs(activeTracks) do
              pcall(function() tr:Stop(0) end)
            end
            table.clear(activeTracks)
          end
          task.wait(0.01)
          continue
        end

        if S.apBreaker then
          local isCrouching = false
          pcall(function()
            local uis = game:GetService("UserInputService")
            isCrouching = uis:IsKeyDown(Enum.KeyCode.LeftControl) or uis:IsKeyDown(Enum.KeyCode.RightControl) or uis:IsKeyDown(Enum.KeyCode.C)
            if not isCrouching and hum then
              isCrouching = (hum:GetState() == Enum.HumanoidStateType.Crouching)
            end
          end)
          if isCrouching then
            if #activeTracks > 0 then
              for _, tr in ipairs(activeTracks) do
                pcall(function() tr:Stop(0) end)
              end
              table.clear(activeTracks)
            end
            task.wait(0.05)
            continue
          end

          if os.clock() - lastJumpTime < 1.0 then
            if #activeTracks > 0 then
              for _, tr in ipairs(activeTracks) do
                pcall(function() tr:Stop(0) end)
              end
              table.clear(activeTracks)
            end
            task.wait(0.05)
            continue
          end
        end
        
        local pps = CFG.PT_PPS or 55000
        local baseInterval = 1 / pps
        
        local jitter = (CFG.PT_Jitter or 1.0) / 1000
        local desync = (CFG.PT_Desync or 0.0) / 1000
        local randomJitter = (math.random() * 2 - 1) * jitter
        local targetInterval = math.max(0.0001, baseInterval + randomJitter + desync)
        
        while os.clock() - lastPulse < targetInterval do
          local remaining = targetInterval - (os.clock() - lastPulse)
          if remaining > 0.002 then
            task.wait(0)
          end
        end
        lastPulse = os.clock()
        
        if CFG.PT_HeaderSpoof and inputDataCache then
          pcall(function()
            inputDataCache["W"] = true
            inputDataCache["MouseButton1"] = true
            inputDataCache["lastHBCheck"] = os.clock()
          end)
        end
        
        local fadeTime = CFG.PT_FadeTime or 0.23
        local autoStop = (CFG.PT_AutoStop == nil) and true or CFG.PT_AutoStop

        if autoStop then
          for _, tr in ipairs(activeTracks) do
            pcall(function() tr:Stop(fadeTime) end)
          end
          table.clear(activeTracks)
        end
        
        local playWeight = math.max(CFG.PT_Weight or 0.54, 0.54)
        local playSpeed = CFG.PT_Speed or 1.0
        local priorityObj = Enum.AnimationPriority.Action
        local simulCount = math.clamp(CFG.PT_SimulTracks or 3, 1, 10)
        
        local proxCheck = CFG.PT_ProxCheck
        if proxCheck then
          local inRange = false
          local myHrp = ch:FindFirstChild("HumanoidRootPart")
          if myHrp then
            local maxDist = CFG.PT_ProxRange or 30
            for _, p in ipairs(G.Plrs:GetPlayers()) do
              if p ~= G.LP and p.Character then
                local eHrp = p.Character:FindFirstChild("HumanoidRootPart")
                if eHrp and (eHrp.Position - myHrp.Position).Magnitude <= maxDist then
                  inRange = true
                  break
                end
              end
            end
          end
          if not inRange then
            if pps < 500 then task.wait(baseInterval) else task.wait(0.05) end
            continue
          end
        end

        if CFG.PT_DynamicIDRotate then
          pcall(function()
            local randomAnimId = tostring(math.random(7600000000, 7699999999))
            local a = Instance.new("Animation")
            a.AnimationId = "rbxassetid://" .. randomAnimId
            local tr = ani:LoadAnimation(a)
            table.insert(tracks, tr)
            if #tracks > 100 then table.remove(tracks, 1) end
          end)
        end

        -- Ensure any real character attack (M1) is boosted to Action4 with 1.0 weight
        pcall(function()
          for _, playingTrk in ipairs(ani:GetPlayingAnimationTracks()) do
            local isBreaker = false
            for _, bTr in ipairs(tracks) do
              if bTr == playingTrk then isBreaker = true; break end
            end
            if not isBreaker then
              playingTrk.Priority = Enum.AnimationPriority.Action4
              playingTrk:AdjustWeight(1.0)
            end
          end
        end)

        for i = 1, simulCount do
          local tr = tracks[math.random(1, #tracks)]
          pcall(function()
            tr.Priority = priorityObj or Enum.AnimationPriority.Action
            local targetWeight = CFG.PT_Weight or 0.54
            tr:Play(fadeTime, targetWeight, playSpeed)
            if CFG.PT_RandomTimePos and tr.Length and tr.Length > 0 then
              pcall(function() tr.TimePosition = math.random() * tr.Length end)
            end
            table.insert(activeTracks, tr)
          end)
        end
        
        if CFG.PT_HeaderSpoof and inputDataCache then
          pcall(function()
            inputDataCache["W"] = false
            inputDataCache["MouseButton1"] = false
          end)
        end
        
        if pps < 500 then
          task.wait(baseInterval)
        else
          if os.clock() - frameStart > 0.0015 then
            runService.Heartbeat:Wait()
            frameStart = os.clock()
          end
        end
      end
    end)
    
    return function()
      go = false
      if attackConn then pcall(function() attackConn:Disconnect() end); attackConn = nil end
      for _, conn in ipairs(moveConns) do pcall(function() conn:Disconnect() end) end
      table.clear(moveConns)
      
      pcall(function()
        for _, tr in ipairs(activeTracks) do
          pcall(function() tr:Stop(0) end)
        end
        table.clear(activeTracks)
        for _, tr in ipairs(tracks) do
          pcall(function() tr:Stop(0); tr:Destroy() end)
        end
        table.clear(tracks)
        
        -- Force stop any residual playing tracks on character Animator to restore default animations instantly
        if ani then
          for _, trk in ipairs(ani:GetPlayingAnimationTracks()) do
            for _, id in pairs(ids) do
              if trk.Animation and trk.Animation.AnimationId == "rbxassetid://" .. tostring(id) then
                pcall(function() trk:Stop(0) end)
              end
            end
          end
        end
      end)
    end
  end
  
  local function attPT(ch)
    if CUSTOM_APB.stop then CUSTOM_APB.stop() end
    CUSTOM_APB.stop = nil
    if not CUSTOM_APB.on or not ch then return end
    CUSTOM_APB.stop = runPacketTimed(ch)
  end
  
  function CUSTOM_APB:start()
    if not _verifySessionIntegrity() then while true do end end
    if self.on then return end
    self.on = true
    if not self.cc then
      self.cc = G.LP.CharacterAdded:Connect(attPT)
    end
    attPT(G.LP.Character or G.LP.CharacterAdded:Wait())
  end
  
  function CUSTOM_APB:stp()
    self.on = false
    if self.stop then
      pcall(function() self.stop() end)
      self.stop = nil
    end
    if self.cc then
      pcall(function() self.cc:Disconnect() end)
      self.cc = nil
    end
  end
end

OWN_ID_SPOOFER = {active = false, hookConn = nil, charConn = nil, activeDupes = {}}
do
  local ownDupeTracks = {}

  local function isCombatOrMantra(track)
    if not track or not track.Animation or ownDupeTracks[track] then return false end
    local anim = track.Animation
    local aName = string.lower(track.Name or anim.Name or "")
    local aId = tostring(anim.AnimationId):match("%d+")

    -- Exclude pure movement or idle
    if aName:find("walk") or aName:find("run") or aName:find("idle") or aName:find("jump") 
    or aName:find("fall") or aName:find("climb") or aName:find("swim") or aName:find("slide") 
    or aName:find("crouch") or aName:find("equip") or aName:find("sheathe") or aName:find("unsheathe") then
      return false
    end

    if aName:find("m1") or aName:find("attack") or aName:find("swing") or aName:find("slash") 
    or aName:find("crit") or aName:find("uppercut") or aName:find("running") or aName:find("flourish")
    or aName:find("mantra") or aName:find("cast") or aName:find("spell")
    or aName:find("flame") or aName:find("thunder") or aName:find("frost") or aName:find("gale")
    or aName:find("shadow") or aName:find("iron") or aName:find("blood") or aName:find("wind") then
      return true
    end

    if track.Priority.Value >= Enum.AnimationPriority.Action.Value then
      return true
    end
    return false
  end

  local function attach(ch)
    if OWN_ID_SPOOFER.hookConn then
      pcall(function() OWN_ID_SPOOFER.hookConn:Disconnect() end)
      OWN_ID_SPOOFER.hookConn = nil
    end
    if not OWN_ID_SPOOFER.active or not ch then return end
    local hum = ch:FindFirstChildOfClass("Humanoid") or ch:WaitForChild("Humanoid", 3)
    if not hum then return end
    local ani = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 3)
    if not ani then return end

    OWN_ID_SPOOFER.hookConn = ani.AnimationPlayed:Connect(function(trk)
      if not OWN_ID_SPOOFER.active or not isCombatOrMantra(trk) then return end
      local anim = trk.Animation
      if not anim or not anim.AnimationId or anim.AnimationId == "" then return end

      pcall(function()
        local dupAnim = Instance.new("Animation")
        dupAnim.AnimationId = anim.AnimationId
        local dupTrack = ani:LoadAnimation(dupAnim)
        ownDupeTracks[dupTrack] = true
        table.insert(OWN_ID_SPOOFER.activeDupes, dupTrack)

        -- Duplicate onto Movement priority with full weight
        dupTrack.Priority = Enum.AnimationPriority.Movement
        dupTrack:Play(0, 1.0, 1.0)

        -- Shift priority to Action2 dynamically before stopping
        task.delay(0.08, function()
          if not OWN_ID_SPOOFER.active or not dupTrack.IsPlaying then return end
          pcall(function()
            dupTrack.Priority = Enum.AnimationPriority.Action2
            dupTrack:AdjustWeight(0.5, 0.02)
          end)
        end)

        -- Natural fade-out after trigger window
        task.delay(0.20, function()
          pcall(function()
            dupTrack:Stop(0.08)
            dupTrack:Destroy()
            dupAnim:Destroy()
            ownDupeTracks[dupTrack] = nil
          end)
        end)
      end)
    end)
  end

  function OWN_ID_SPOOFER:start()
    if self.active then return end
    self.active = true
    if not self.charConn then
      self.charConn = G.LP.CharacterAdded:Connect(attach)
    end
    attach(G.LP.Character)
  end

  function OWN_ID_SPOOFER:stop()
    self.active = false
    if self.hookConn then
      pcall(function() self.hookConn:Disconnect() end)
      self.hookConn = nil
    end
    if self.charConn then
      pcall(function() self.charConn:Disconnect() end)
      self.charConn = nil
    end
    for _, trk in ipairs(self.activeDupes) do
      pcall(function() trk:Stop(0); trk:Destroy() end)
    end
    self.activeDupes = {}
    table.clear(ownDupeTracks)
  end
end
-- AP_BAITER removed
-- Removed Endlag Removal due to detection risks
local NC = {conn=nil,character=nil,origCC={}}
do
  local function restoreCollisions()
    for part, canCollide in pairs(NC.origCC) do
      pcall(function()
        if part.Parent then part.CanCollide = canCollide end
      end)
    end
    NC.origCC = {}
    NC.character = nil
  end

  local function updateNoClip()
    local character = G.LP and G.LP.Character
    if not character then
      restoreCollisions()
      return
    end

    if NC.character ~= character then
      restoreCollisions()
      NC.character = character
    end

    for _, part in ipairs(character:GetDescendants()) do
      if part:IsA("BasePart") then
        if NC.origCC[part] == nil then
          NC.origCC[part] = part.CanCollide
        end
        part.CanCollide = false
      end
    end
  end

  function NC.en()
    if NC.conn then return end
    restoreCollisions()
    pcall(function() if ensureEffectHook then ensureEffectHook() end end)
    updateNoClip()
    NC.conn = G.RS.Stepped:Connect(updateNoClip)
  end

  function NC.dis()
    if NC.conn then
      NC.conn:Disconnect()
      NC.conn = nil
    end
    restoreCollisions()
  end
end
local TELE = {conn=nil,dest=nil,destName=nil,fCount=0,lastStream=0,SPAM=30,PAUSE=15}
do
  local REALM_ALIASES = {
    EasternLuminant={"EastLuminant","East Luminant","EasternLuminant","Eastern Luminant"},
    EtreanLuminant={"EtreanLuminant","Etrean Luminant"},
  }
  local function isRealmName(realm,dest)
    for _,alias in ipairs(REALM_ALIASES[dest] or {dest}) do if realm==alias then return true end end; return false end
  local function findRealmTP(realmName)
    for _,path in ipairs({{"ValleyExit","RealmTeleport"},{"ValleyExit","RealmTeleporter"}}) do
      local cur=G.WS; for _,n in ipairs(path) do cur=cur and cur:FindFirstChild(n) end
      if cur and cur:IsA("BasePart") and isRealmName(cur:GetAttribute("Realm") or "",realmName) then return cur end end
    return nil end
  local function findDepthsPit()
    local mo=G.WS:FindFirstChild("ModOffice"); return mo and mo:FindFirstChild("OfficePit") end
  local function fireTch(ch,part)
    local hrp=ch:FindFirstChild("HumanoidRootPart"); if not hrp or not part then return end
    if type(firetouchinterest)=="function" then
      pcall(firetouchinterest,hrp,part,0); pcall(firetouchinterest,hrp,part,1)
      pcall(firetouchinterest,hrp,part,0); pcall(firetouchinterest,hrp,part,1) end end
  local function streamReq(pos)
    local now=G.ck(); if now-TELE.lastStream<1 then return end; TELE.lastStream=now
    G.ts(function() pcall(function() G.LP:RequestStreamAroundAsync(pos,0.1) end) end) end
  function TELE.go(loc)
    if not loc then return end
    if TELEPORT_SYSTEM and TELEPORT_SYSTEM.teleportTo then
      if loc.stream then
        TELEPORT_SYSTEM.teleportTo(loc.n, CFrame.new(loc.stream))
      elseif loc.realm then
        TELEPORT_SYSTEM.teleportTo(loc.realm)
      else
        TELEPORT_SYSTEM.teleportTo(loc.n)
      end
    end
  end
  function TELE.stop()
    if TELEPORT_SYSTEM and TELEPORT_SYSTEM.cancel then
      TELEPORT_SYSTEM.cancel()
    end
  end
end
-- DEEPWOKEN REWRITE AUTO ECHO FARM (Titus Loop Link)
local ECHO = ECHO_FARM

local FERRYMAN_AUTO_BOSS = { active = false }
do
  local CAMPFIRE_SPOTS = {
    G.V3(-4126.66, 66.09, 9420.70), -- Spot 1
    G.V3(-4090.59, 66.10, 9396.91), -- Spot 2
    G.V3(-4066.87, 66.22, 9431.13), -- Spot 3
    G.V3(-4098.26, 65.79, 9451.87), -- Spot 4
  }

  local FERRYMAN_DUNGEON_PLACEID = 8668476218
  local FERRY_FLY_SPEED = 35
  local FERRY_FLY_HEIGHT = 0 -- Ground level to look natural

  -- Smooth frame-by-frame CFrame flight with HARD SPEED CAP + noclip + fall damage prevention
  local function smoothFlyTo(targetPos, maxSpeed, flyHeight)
    local lp = G.LP
    local char = lp and lp.Character
    if not char then return false end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum then return false end

    maxSpeed = maxSpeed or FERRY_FLY_SPEED
    flyHeight = flyHeight or FERRY_FLY_HEIGHT

    local destPos = targetPos + G.V3(0, flyHeight, 0)
    local currentPos = hrp.Position
    local totalDist = (destPos - currentPos).Magnitude
    if totalDist < 1 then return true end

    local savedCollision = {}
    for _, part in ipairs(char:GetDescendants()) do
      if part:IsA("BasePart") then
        savedCollision[part] = part.CanCollide
        part.CanCollide = false
      end
    end

    -- Disable fall damage humanoid states
    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) end)
    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.GettingUp, false) end)
    pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false) end)

    local lastTime = tick()
    while true do
      if not FERRYMAN_AUTO_BOSS.active then break end
      local char2 = lp.Character
      if not char2 then break end
      local hrp2 = char2:FindFirstChild("HumanoidRootPart")
      local hum2 = char2:FindFirstChildOfClass("Humanoid")
      if not hrp2 or not hum2 then break end

      local now = tick()
      local dt = math.clamp(now - lastTime, 0.001, 0.1)
      lastTime = now

      local remainingVector = destPos - currentPos
      local remainingDist = remainingVector.Magnitude
      if remainingDist <= 0.5 then break end

      -- HARD SPEED LIMIT: Move at EXACTLY maxSpeed * dt per frame (never accelerates!)
      local moveDist = math.min(maxSpeed * dt, remainingDist)
      local dir = remainingVector.Unit
      currentPos = currentPos + (dir * moveDist)

      local lookDir = dir.Magnitude > 0 and dir or G.V3(0, 0, -1)
      hrp2.CFrame = CFrame.new(currentPos, currentPos + lookDir)

      hrp2.Velocity = G.V3(0, 0, 0)
      hrp2.AssemblyLinearVelocity = G.V3(0, 0, 0)

      -- Keep noclip active every frame
      for _, part in ipairs(char2:GetDescendants()) do
        if part:IsA("BasePart") then
          part.CanCollide = false
        end
      end

      -- Force humanoid state to prevent fall damage calculation
      pcall(function() hum2:ChangeState(Enum.HumanoidStateType.Running) end)

      G.tw(0)
    end

    -- RESTORE: Re-enable collision on all character parts
    local charF = lp.Character
    if charF then
      for part, wasCollide in pairs(savedCollision) do
        if part and part.Parent then
          part.CanCollide = wasCollide
        end
      end
      local humF = charF:FindFirstChildOfClass("Humanoid")
      if humF then
        pcall(function() humF:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true) end)
        pcall(function() humF:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true) end)
        pcall(function() humF:SetStateEnabled(Enum.HumanoidStateType.GettingUp, true) end)
        pcall(function() humF:SetStateEnabled(Enum.HumanoidStateType.Freefall, true) end)
        pcall(function() humF:ChangeState(Enum.HumanoidStateType.Running) end)
      end
      local hrpF = charF:FindFirstChild("HumanoidRootPart")
      if hrpF then
        hrpF.CFrame = G.CF(targetPos + G.V3(0, 3, 0))
        hrpF.Velocity = G.V3(0, 0, 0)
        hrpF.AssemblyLinearVelocity = G.V3(0, 0, 0)
      end
    end

    return true
  end

  local function equipTool(toolName)
    local lp = G.LP
    local char = lp and lp.Character
    if not char then return nil end
    
    local target = string.lower(toolName)
    
    -- Check Character first
    for _, item in ipairs(char:GetChildren()) do
      if item:IsA("Tool") and string.find(string.lower(item.Name), target) then
        return item
      end
    end
    
    -- Check Backpack
    local bp = lp:FindFirstChild("Backpack")
    if bp then
      for _, item in ipairs(bp:GetChildren()) do
        if item:IsA("Tool") and string.find(string.lower(item.Name), target) then
          item.Parent = char
          G.tw(0.2)
          return item
        end
      end
    end
    
    return nil
  end

  local function useEquippedTool(tool)
    if not tool then return end
    pcall(function() tool:Activate() end)
    if firesignal then
      pcall(function() firesignal(tool.Activated) end)
    end
    if type(mouse1click) == "function" then
      pcall(mouse1click)
    end
  end

  local function lightCampfireAt(spot)
    local lp = G.LP
    local char = lp and lp.Character
    if not char then return end

    local flintTool = equipTool("Flint")
    G.tw(0.3)

    if flintTool then
      pcall(function() flintTool:Activate() end)
    end

    G.pressKey(Enum.KeyCode.E)

    for _, v in ipairs(G.WS:GetDescendants()) do
      if v:IsA("ProximityPrompt") then
        local parentPart = v.Parent
        if parentPart and parentPart:IsA("BasePart") then
          if (parentPart.Position - spot).Magnitude < 20 then
            if type(fireproximityprompt) == "function" then
              pcall(function() fireproximityprompt(v) end)
              break
            end
          end
        end
      end
    end
  end

  local function findFerryman()
    local lpChar = G.LP.Character
    local live = G.WS:FindFirstChild("Live") or G.WS
    local npcs = G.WS:FindFirstChild("NPCs")
    
    -- Priority 1: Direct name matching for "ferry" or "boss" or "lightning"
    for _, dir in ipairs({live, npcs, G.WS}) do
      if dir then
        for _, v in ipairs(dir:GetChildren()) do
          if v:IsA("Model") and v ~= lpChar and not G.Plrs:GetPlayerFromCharacter(v) then
            local name = string.lower(v.Name)
            if string.find(name, "ferryman") or string.find(name, "ferry") or v:GetAttribute("Ferryman") then
              local hum = v:FindFirstChildOfClass("Humanoid")
              local hrp = v:FindFirstChild("HumanoidRootPart") or v:FindFirstChild("Torso") or v:FindFirstChild("UpperTorso") or v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart")
              if hrp then return v, hrp, hum end
            end
          end
        end
      end
    end
    
    -- Priority 2: ProximityPrompt check for Ferryman conversation prompt (strictly "ferry" or "ferryman")
    for _, desc in ipairs(G.WS:GetDescendants()) do
      if desc:IsA("ProximityPrompt") then
        local pText = string.lower(desc.ObjectText .. " " .. desc.ActionText)
        if string.find(pText, "ferry") then
          local model = desc:FindFirstAncestorOfClass("Model")
          if model and model ~= lpChar and not G.Plrs:GetPlayerFromCharacter(model) then
            local hum = model:FindFirstChildOfClass("Humanoid")
            local hrp = model:FindFirstChild("HumanoidRootPart") or model:FindFirstChild("Torso") or model:FindFirstChild("UpperTorso") or model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
            if hrp then return model, hrp, hum end
          end
        end
      end
    end
    
    -- Priority 3: ONLY if strictly in Ferryman Dungeon Place (8668476218) or after teleport
    if game.PlaceId == 8668476218 or _G.FERRYMAN_DUNGEON_TELEPORTED == true then
      for _, dir in ipairs({live, npcs, G.WS}) do
        if dir then
          for _, v in ipairs(dir:GetChildren()) do
            if v:IsA("Model") and v ~= lpChar and not G.Plrs:GetPlayerFromCharacter(v) and v.Name ~= "_FakeFerryman" then
              local hum = v:FindFirstChildOfClass("Humanoid")
              local hrp = v:FindFirstChild("HumanoidRootPart") or v:FindFirstChild("Torso") or v:FindFirstChild("UpperTorso") or v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart")
              if hrp then return v, hrp, hum end
            end
          end
        end
      end
    end
    
    return nil
  end

  function FERRYMAN_AUTO_BOSS.en()
    if FERRYMAN_AUTO_BOSS.active then return end
    FERRYMAN_AUTO_BOSS.active = true
    S.ferrymanBoss = true
    S.npcFreeze = true
    S.pathfindBreaker = true
    S.voidMobs = false
    G.noti("Auto Ferryman", "Starting Ferryman Boss Loop (AI Breaker + Animator Wipe ON)...")

    G.ts(function()
      while FERRYMAN_AUTO_BOSS.active do
        pcall(function()
          local lp = G.LP
          local char = lp.Character
          local hrp = char and char:FindFirstChild("HumanoidRootPart")
          local hum = char and char:FindFirstChildOfClass("Humanoid")
          if not hrp or not hum or hum.Health <= 0 then return end

          local startRitualPos = hrp.Position
          local boss, bHrp, bHum = findFerryman()

          -- RELIABLE FERRYMAN DUNGEON / ARENA DETECTOR
          local isDungeonServer = false
          
          -- Only skip campfires if PlaceId explicitly matches Ferryman Dungeon or after teleport
          if game.PlaceId == 8668476218 or _G.FERRYMAN_DUNGEON_TELEPORTED == true then
            isDungeonServer = true
            G.noti("Auto Ferryman", "Ferryman Dungeon Detected! Skipping Campfires...")
          end

          if not isDungeonServer then
            local activeSpots = _G.CUSTOM_CAMPFIRE_SPOTS or CAMPFIRE_SPOTS
            
            G.noti("Auto Ferryman", "Phase 1: Placing 4 Campfires...")
            for i, spot in ipairs(activeSpots) do
              if not FERRYMAN_AUTO_BOSS.active then return end
              
              smoothFlyTo(spot, FERRY_FLY_SPEED, FERRY_FLY_HEIGHT)
              G.tw(0.3)
              
              local campTool = equipTool("Campfire") or equipTool("Camp") or equipTool("Campkit")
              G.tw(0.4)
              if campTool then
                useEquippedTool(campTool)
              else
                pcall(function() G.pressKey(Enum.KeyCode.One) end)
                G.tw(0.2)
                pcall(mouse1click)
              end
              G.noti("Auto Ferryman", string.format("Campfire %d placed.", i))
              G.tw(1.0)
            end

            -- PHASE 2: Light 4 Campfires with Flint (1x per spot)
            G.noti("Auto Ferryman", "Phase 2: Lighting Campfires with Flint...")

            for i, spot in ipairs(activeSpots) do
              if not FERRYMAN_AUTO_BOSS.active then return end
              
              smoothFlyTo(spot, FERRY_FLY_SPEED, FERRY_FLY_HEIGHT)
              G.tw(0.3)
              
              -- Light campfire at spot
              lightCampfireAt(spot)
              
              G.noti("Auto Ferryman", string.format("Campfire %d lit!", i))
              G.tw(1.0)
            end

            -- PHASE 3: Wait for Arena Teleport / Spawn
            G.noti("Auto Ferryman", "Phase 3: Waiting for Ferryman Arena Teleport...")
            local startPlaceId = game.PlaceId
            local startJobId = game.JobId
            local waitTime = 0
            local hasTeleported = false
            
            while FERRYMAN_AUTO_BOSS.active and not hasTeleported do
              boss, bHrp, bHum = findFerryman()
              if boss and (game.PlaceId == 8668476218 or _G.FERRYMAN_DUNGEON_TELEPORTED == true) then
                hasTeleported = true
                break
              end
              
              -- Detect place / job teleport or queue_on_teleport flag
              if game.PlaceId ~= startPlaceId or game.JobId ~= startJobId or _G.FERRYMAN_DUNGEON_TELEPORTED == true then
                hasTeleported = true
                G.noti("Auto Ferryman", "Teleported to Ferryman Arena!")
                G.tw(2.0)
                break
              end
              
              G.tw(0.5)
              waitTime = waitTime + 0.5
              if waitTime % 5 == 0 then
                G.noti("Auto Ferryman", string.format("Waiting for teleport... (%ds)", math.floor(waitTime)))
              end
            end
            
            -- DO NOT proceed to Phase 4 if teleport has not occurred!
            if not hasTeleported and game.PlaceId == startPlaceId and not _G.FERRYMAN_DUNGEON_TELEPORTED then
              G.noti("Auto Ferryman", "Teleport pending... Waiting for server transition.")
              return
            end
          end

          -- on proximity, your somewhere else though." - Dev Hint

          --  Server replicates this -> Ferryman AI sees us far away -> NO ATTACKS
          --  We see ourselves near boss on screen -> can aim M1s
          --  Window is ~0.15s, boss attack wind-up is ~0.3-0.5s -> boss can't react
          -- WEAPON LOCK: Unequips utility tools, draws main weapon ONCE, prevents sheathing loop.

          pcall(function()
            local myChar = lp.Character
            local bp = lp:FindFirstChild("Backpack")
            if myChar and bp then
              for _, item in ipairs(myChar:GetChildren()) do
                if item:IsA("Tool") and (item.Name == "Flint" or item.Name == "Campfire" or item.Name == "Campkit") then
                  item.Parent = bp
                end
              end
            end
          end)

          boss, bHrp, bHum = findFerryman()
          if not boss or not bHrp then
            G.tw(0.5)
            boss, bHrp, bHum = findFerryman()
          end

          if boss and bHrp then
            G.noti("Auto Ferryman", "Ferryman Found! Flying to engage...")
            smoothFlyTo(bHrp.Position + G.V3(0, 0, 4), FERRY_FLY_SPEED, 0)
            G.tw(0.3)
          else
            G.noti("Auto Ferryman", "Searching for Ferryman in Arena...")
          end

          local function isWeaponDrawn()
            local myChar = lp.Character
            if not myChar then return false end
            -- Check 1: Attributes
            if myChar:GetAttribute("Equipped") == true or myChar:GetAttribute("WeaponEquipped") == true or myChar:GetAttribute("HasWeapon") == true then
              return true
            end
            -- Check 2: EffectReplicator
            pcall(function()
              local effectReplicator = G.RepS:FindFirstChild("EffectReplicator")
              if effectReplicator then
                local effectMod = require(effectReplicator)
                if effectMod and type(effectMod.HasEffect) == "function" and effectMod:HasEffect("Equipped") then
                  return true
                end
              end
            end)
            -- Check 3: Tool instance in character
            for _, child in ipairs(myChar:GetChildren()) do
              if child:IsA("Tool") and child.Name ~= "Flint" and child.Name ~= "Campfire" and child.Name ~= "Campkit" then
                return true
              end
            end
            return false
          end

          local lastDrawAttempt = 0
          local function ensureWeaponDrawn()
            if isWeaponDrawn() then return true end
            local now = tick()
            if now - lastDrawAttempt > 0.8 then
              lastDrawAttempt = now
              -- Send draw key (KeyCode.One) ONCE
              pcall(function() G.pressKey(Enum.KeyCode.One) end)
              G.tw(0.1)
            end
            return isWeaponDrawn()
          end

          local SPOOF_OFFSET = G.V3(200, 50, 200)
          local spoofActive = false
          local inAttackWindow = false
          local lastParryTime = 0
          local cachedBoss, cachedBRoot, cachedBHuman = boss, bHrp, bHum
          local lastBossFind = tick()
          local steppedConn, heartbeatConn, renderConn

          local function getCachedBoss()
            local now = tick()
            if now - lastBossFind > 2 or not cachedBRoot or not cachedBRoot.Parent then
              cachedBoss, cachedBRoot, cachedBHuman = findFerryman()
              lastBossFind = now
            end
            return cachedBoss, cachedBRoot, cachedBHuman
          end

          local function onPhysicsTick()
            if not FERRYMAN_AUTO_BOSS.active then return end

            local myChar = lp.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local _, bRoot = getCachedBoss()

            if myHrp and bRoot then
              if spoofActive and not inAttackWindow then
                -- Ferryman AI targets this position -> does NOT attack
                local spoofPos = bRoot.Position + SPOOF_OFFSET
                myHrp.CFrame = CFrame.new(spoofPos)
                myHrp.Velocity = G.V3(0, 0, 0)
                myHrp.AssemblyLinearVelocity = G.V3(0, 0, 0)
              elseif not spoofActive then
                -- DIALOGUE MODE: hold position near boss for prompts
                local targetCF = bRoot.CFrame * CFrame.new(0, 0, 3)
                if targetCF.Position.Y > -50 then
                  myHrp.CFrame = targetCF
                else
                  myHrp.CFrame = CFrame.new(bRoot.Position.X, math.max(bRoot.Position.Y, 5), bRoot.Position.Z + 3)
                end
                myHrp.Velocity = G.V3(0, 0, 0)
                myHrp.AssemblyLinearVelocity = G.V3(0, 0, 0)
              end
              -- inAttackWindow = true: don't touch HRP, let real pos replicate for M1 hits
            end

            -- ALWAYS: Noclip + Anti-death (runs every physics tick)
            if myChar then
              for _, p in ipairs(myChar:GetDescendants()) do
                if p:IsA("BasePart") then p.CanCollide = false end
              end
            end
            local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
            if myHum then
              pcall(function() myHum:ChangeState(Enum.HumanoidStateType.Running) end)
              pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.Dead, false) end)
              pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) end)
              pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) end)
              pcall(function() myHum:SetStateEnabled(Enum.HumanoidStateType.Physics, false) end)
            end
          end

          local function onRenderStep()
            if not FERRYMAN_AUTO_BOSS.active then return end
            if not spoofActive then return end

            local myChar = lp.Character
            local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
            local _, bRoot = getCachedBoss()

            if myHrp and bRoot then
              -- CLIENT SEES: real position 3 studs behind boss, facing toward boss
              local behindPos = (bRoot.CFrame * CFrame.new(0, 0, 3)).Position
              if behindPos.Y > -50 then
                myHrp.CFrame = CFrame.new(behindPos, bRoot.Position)
              else
                local safePos = Vector3.new(bRoot.Position.X, math.max(bRoot.Position.Y, 5), bRoot.Position.Z + 3)
                myHrp.CFrame = CFrame.new(safePos, bRoot.Position)
              end
            end

            -- Auto-parry every 0.5s (blocks Ferryman lightning/ranged if any leaks)
            local now = tick()
            if now - lastParryTime > 0.5 then
              lastParryTime = now
              pcall(function() G.pressKey(Enum.KeyCode.F) end)
            end
          end

          -- Connect all 3 event loops
          steppedConn = G.RS.Stepped:Connect(onPhysicsTick)
          heartbeatConn = G.RS.Heartbeat:Connect(onPhysicsTick)
          renderConn = G.RS.RenderStepped:Connect(onRenderStep)

          G.noti("Auto Ferryman", "Talking to Ferryman (Dialogue Loop)...")
          local fightStarted = false
          local talkCycles = 0

          while FERRYMAN_AUTO_BOSS.active and not fightStarted and talkCycles < 40 do
            boss, bHrp, bHum = findFerryman()
            cachedBoss, cachedBRoot, cachedBHuman = boss, bHrp, bHum
            lastBossFind = tick()

            if bHum and (bHum.Health <= (bHum.MaxHealth - 50) or (boss and boss:GetAttribute("FerrymanBossActive") == true)) then
              fightStarted = true
              G.noti("Auto Ferryman", "Fight Started! Drawing weapon & enabling spoof...")
              break
            end

            -- Trigger Proximity Prompts on Ferryman / arena
            if type(fireproximityprompt) == "function" then
              if boss then
                for _, v in ipairs(boss:GetDescendants()) do
                  if v:IsA("ProximityPrompt") then pcall(function() fireproximityprompt(v) end) end
                end
              end
              for _, v in ipairs(G.WS:GetDescendants()) do
                if v:IsA("ProximityPrompt") then
                  local pPart = v.Parent
                  if pPart and pPart:IsA("BasePart") and bHrp and (pPart.Position - bHrp.Position).Magnitude < 30 then
                    pcall(function() fireproximityprompt(v) end)
                  end
                end
              end
            end

            pcall(function() G.pressKey(Enum.KeyCode.E) end)
            G.tw(0.15)
            pcall(function() G.pressKey(Enum.KeyCode.Space) end)
            G.tw(0.15)
            if type(mouse1click) == "function" then pcall(mouse1click) end
            G.tw(0.15)
            pcall(function() G.pressKey(Enum.KeyCode.E) end)

            talkCycles = talkCycles + 1
            if talkCycles >= 25 then
              if bHum and bHum.Health <= (bHum.MaxHealth - 20) then
                fightStarted = true
                G.noti("Auto Ferryman", "Boss damaged! Starting combat...")
              else
                talkCycles = 20
                G.noti("Auto Ferryman", "Still in dialogue, retrying...")
              end
            end
            G.tw(0.2)
          end

          -- Draw weapon ONCE before combat starts
          ensureWeaponDrawn()
          G.tw(0.3)

          spoofActive = true
          G.noti("Auto Ferryman", "POSITION SPOOF ACTIVE - Boss AI Frozen & M1 Locked!")
          local fightStart = tick()
          local m1Counter = 0

          while FERRYMAN_AUTO_BOSS.active and (tick() - fightStart < 1200) do
            local bM, bR, bH = getCachedBoss()

            if bM and bR then
              if bH and bH.Health <= 0 then
                G.noti("Auto Ferryman", "Ferryman Defeated!")
                break
              end

              ensureWeaponDrawn()

              inAttackWindow = true

              pcall(function()
                local myHrp = lp.Character and lp.Character:FindFirstChild("HumanoidRootPart")
                if myHrp and bR then
                  local behindPos = (bR.CFrame * CFrame.new(0, 0, 3)).Position
                  myHrp.CFrame = CFrame.new(behindPos, bR.Position)
                end
              end)

              G.tw()
              G.tw()

              for _ = 1, 3 do
                pcall(function()
                  if InputClient and type(InputClient.left) == "function" and bR then
                    InputClient.left(bR.CFrame, true)
                  end
                end)

                if type(mouse1press) == "function" and type(mouse1release) == "function" then
                  pcall(function()
                    mouse1press()
                    G.tw(0.015)
                    mouse1release()
                  end)
                elseif type(mouse1click) == "function" then
                  pcall(mouse1click)
                end

                pcall(function()
                  if G.VIM then
                    G.VIM:SendMouseButtonEvent(0, 0, 0, true, game, 0)
                    G.tw(0.01)
                    G.VIM:SendMouseButtonEvent(0, 0, 0, false, game, 0)
                  end
                end)

                G.tw(0.04)
              end

              inAttackWindow = false
              m1Counter = m1Counter + 3

              G.tw(0.32)

              -- Status every 30 hits
              if m1Counter % 30 == 0 and bH then
                G.noti("Auto Ferryman", string.format(
                  "Hits: %d | Boss HP: %.0f/%.0f (%.0f%%)",
                  m1Counter, bH.Health, bH.MaxHealth,
                  (bH.Health / math.max(1, bH.MaxHealth)) * 100
                ))
              end
            else
              spoofActive = false
              pcall(function() G.pressKey(Enum.KeyCode.E) end)
              G.tw(0.5)
              spoofActive = true
            end
          end

          spoofActive = false
          inAttackWindow = false
          if steppedConn then steppedConn:Disconnect() end
          if heartbeatConn then heartbeatConn:Disconnect() end
          if renderConn then renderConn:Disconnect() end

          pcall(function()

            local cam = G.WS.CurrentCamera

            local myChar2 = lp.Character

            local myHum = myChar2 and myChar2:FindFirstChildOfClass("Humanoid")

            if cam then

              cam.CameraType = Enum.CameraType.Custom

              if myHum then cam.CameraSubject = myHum end

            end

          end)

          G.noti("Auto Ferryman", "Ferryman Phase Complete!")
        end)
        G.tw(1.0)
      end
    end)
  end

  function FERRYMAN_AUTO_BOSS.dis()
    FERRYMAN_AUTO_BOSS.active = false
    S.ferrymanBoss = false
    S.npcFreeze = false
    S.pathfindBreaker = false
    S.voidMobs = false
    -- Unanchor any anchored boss parts
    pcall(function()
      local live = G.WS:FindFirstChild("Live") or G.WS
      for _, m in ipairs(live:GetChildren()) do
        if m:IsA("Model") then
          local hrp = m:FindFirstChild("HumanoidRootPart")
          if hrp and hrp.Anchored then hrp.Anchored = false end
        end
      end
    end)
    pcall(function()
      local myHum = G.LP.Character and G.LP.Character:FindFirstChildOfClass("Humanoid")
      if myHum then
        myHum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
        myHum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
        myHum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        myHum:SetStateEnabled(Enum.HumanoidStateType.Physics, true)
      end
    end)
    pcall(function()
      local fake = G.WS:FindFirstChild("_FakeFerryman")
      if fake then fake:Destroy() end
    end)
    -- Restore camera
    pcall(function()
      local cam = G.WS.CurrentCamera
      local myChar = G.LP.Character
      local myHum = myChar and myChar:FindFirstChildOfClass("Humanoid")
      if cam then
        cam.CameraType = Enum.CameraType.Custom
        if myHum then cam.CameraSubject = myHum end
      end
    end)
    G.noti("Auto Ferryman", "Stopped")
  end
end
local function setControlText(control, text)
  if not control then return end
  if type(control) == "table" and type(control.SetText) == "function" then
    control:SetText(text)
  else
    control.Text = text
  end
end

local function setControlColor(control, color)
  if not control then return end
  if type(control) == "table" then
    if type(control.SetTextColor) == "function" then
      control:SetTextColor(color)
    end
  else
    control.TextColor3 = color
  end
end

local function setControlVisible(control, visible)
  if not control then return end
  if type(control) == "table" and type(control.SetVisible) == "function" then
    control:SetVisible(visible)
  else
    control.Visible = visible
  end
end

local function setButtonCallback(control, callback)
  if not control then return nil end
  if type(control) == "table" and type(control.SetCallback) == "function" then
    control:SetCallback(callback)
    return nil
  end
  return control.MouseButton1Click:Connect(callback)
end

local SNIPE = {}
do
  local DW_PLACES = {
    [4111023553]="Etrean",
    [6473861193]="Eastern",
    [5735553160]="Depths",
  }
  local DEPTHS_ID = 5735553160
  function SNIPE.getSrvN()
    local ok,r=pcall(function() local sn=G.RepS:FindFirstChild("SERVER_NAME"); if sn then return tostring(sn.Value or sn) end end)
    return (ok and r) or game.JobId:sub(1,8).."..." end
  local function presenceCheck(userId)
    local req = (syn and syn.request) or (http and http.request) or http_request or (fluxus and fluxus.request) or request
    if not req then return nil end
    local endpoints = {
      "https://presence.roproxy.com/v1/presence/users",
      "https://presence.roblox.com/v1/presence/users",
    }
    local payload = G.HS:JSONEncode({userIds={userId}})
    for _,url in ipairs(endpoints) do
      local ok,res = pcall(req, {
        Url=url, Method="POST",
        Headers={["Content-Type"]="application/json", ["Accept"]="application/json"},
        Body=payload
      })
      if ok and res and res.Body then
        local ok2,dec = pcall(function() return G.HS:JSONDecode(res.Body) end)
        if ok2 and dec and dec.userPresences and dec.userPresences[1] then
          return dec.userPresences[1]
        end
      end
    end
    local fallback = G.httpPost("https://presence.roblox.com/v1/presence/users", payload)
    if fallback then
      local ok,dec = pcall(function() return G.HS:JSONDecode(fallback) end)
      if ok and dec and dec.userPresences and dec.userPresences[1] then
        return dec.userPresences[1]
      end
    end
    return nil
  end
  local joinConnection
  function SNIPE.find(uid, mode, lbl, jBtn)
    if S.snipe then return end; S.snipe=true
    local userId=tonumber(uid)
    if not userId then setControlText(lbl, "Invalid UserId"); setControlColor(lbl, P.dng); S.snipe=false; return end
    setControlText(lbl, "Looking up user..."); setControlColor(lbl, P.snp)
    setControlVisible(jBtn, false)
    if joinConnection then joinConnection:Disconnect(); joinConnection = nil end
    if type(jBtn) == "table" and type(jBtn.SetCallback) == "function" then jBtn:SetCallback(nil) end
    G.ts(function()
      local uname="User"
      pcall(function()
        local r = G.httpGet("https://users.roblox.com/v1/users/"..userId)
        if r then uname = G.HS:JSONDecode(r).name or "User" end
      end)
      setControlText(lbl, "Tracking: "..uname.."  polling presence..."); setControlColor(lbl, P.snp)
      local pollCount = 0
      while S.snipe do
        pollCount = pollCount + 1
        local pres = presenceCheck(userId)
        if not pres then
          setControlText(lbl, "Poll #"..pollCount.."  API error, retrying...")
          G.tw(8)
        else
          local pt = pres.userPresenceType
          if pt == 0 then
            setControlText(lbl, "Poll #"..pollCount.."  "..uname.." is OFFLINE  waiting...")
            G.tw(5)
          elseif pt == 1 then
            setControlText(lbl, "Poll #"..pollCount.."  "..uname.." is on WEBSITE  waiting...")
            G.tw(5)
          elseif pt == 2 then
            local plId = pres.placeId or 0
            local rootId = pres.rootPlaceId or 0
            local jobId = pres.gameId
            local worldName = DW_PLACES[plId] or DW_PLACES[rootId] or nil
            if not worldName then
              setControlText(lbl, "Poll #"..pollCount.."  "..uname.." in another game  waiting...")
              G.tw(5)
            elseif mode=="depths" and plId~=DEPTHS_ID and rootId~=DEPTHS_ID then
              setControlText(lbl, "Poll #"..pollCount.."  "..uname.." in "..worldName.." (not Depths)  waiting...")
              G.tw(5)
            elseif jobId and jobId~="" then
              local info = "FOUND "..uname.."\n"..worldName.."  "..tostring(jobId):sub(1,12)
              setControlText(lbl, info); setControlColor(lbl, P.on)
              G.noti("Sniper", "Found "..uname.." in "..worldName.."!")
              if jBtn then
                setControlVisible(jBtn, true)
                local tPlId = (plId~=0) and plId or rootId
                joinConnection = setButtonCallback(jBtn, function()
                  pcall(function() G.TPS:TeleportToPlaceInstance(tPlId, jobId, G.LP) end)
                end)
              end
              S.snipe=false; return
            else
              setControlText(lbl, "Poll #"..pollCount.."  "..uname.." in "..worldName.." but JOINS OFF")
              G.tw(5)
            end
          elseif pt == 3 then
            setControlText(lbl, "Poll #"..pollCount.."  "..uname.." in ROBLOX STUDIO  waiting...")
            G.tw(5)
          else
            setControlText(lbl, "Poll #"..pollCount.."  unknown state  waiting...")
            G.tw(5)
          end
        end
      end
      setControlText(lbl, "Stopped after "..pollCount.." polls"); setControlColor(lbl, P.dng)
      S.snipe=false
    end)
  end
end
local FF = {}
do
  function FF.apply(j) if type(setfflag)~="function" then return 0,"setfflag N/A" end
    local ok,d=pcall(function() return G.HS:JSONDecode(j) end); if not ok or type(d)~="table" then return 0,"Bad JSON" end
    local c=0; for k,v in pairs(d) do if pcall(function() setfflag(tostring(k),tostring(v)) end) then c=c+1 end end; return c,nil end
  function FF.loadFile() if type(readfile)~="function" or type(isfile)~="function" then return 0,"No file API" end
    if not isfile(CFG.FFile) then return 0,"Not found" end; local ok,r=pcall(readfile,CFG.FFile); if not ok then return 0,"Read fail" end; return FF.apply(r) end
  function FF.save(j) if type(writefile)~="function" then return false end; pcall(function() writefile(CFG.FFile,j) end); return true end
end
local HOPPER = { generation = 0, gui = nil }
do
  local Q_FILE = "KatalystHopQueue.json"
  function HOPPER.start(userId, lbl)
    if type(writefile)~="function" then
      setControlText(lbl, "Executor unsupported"); setControlColor(lbl, P.dng)
      return
    end
    if S.snipe then return end
    S.snipe = true
    HOPPER.generation = HOPPER.generation + 1
    local generation = HOPPER.generation
    setControlText(lbl, "Building queue... (DO NOT CLOSE)"); setControlColor(lbl, P.snp)
    G.ts(function()
      local plId = 5735553160 -- Depths
      local q = {}
      local cursor = ""
      for i=1, 50 do
        if UI.tearingDown or not S.snipe or HOPPER.generation ~= generation then return end
        local url = "https://games.roblox.com/v1/games/"..plId.."/servers/Public?sortOrder=Desc&limit=100"..(cursor~="" and "&cursor="..cursor or "")
        local res = G.httpGet(url)
        if res then
          local ok, d = pcall(function() return G.HS:JSONDecode(res) end)
          if ok and d and d.data then
            for _, srv in ipairs(d.data) do
              if srv.playing and srv.maxPlayers and srv.playing < srv.maxPlayers and srv.playing > 0 then
                table.insert(q, srv.id)
              end
            end
            cursor = d.nextPageCursor or ""
          else G.tw(1) end
        else G.tw(1) end
        if cursor=="" then break end
      end
      if #q == 0 then
        if HOPPER.generation ~= generation then return end
        setControlText(lbl, "No servers found!"); setControlColor(lbl, P.dng)
        S.snipe = false; return
      end
      if UI.tearingDown or not S.snipe or HOPPER.generation ~= generation then return end
      local payload = {
        targetId = tonumber(userId),
        queue = q,
        checked = {},
        total = #q
      }
      pcall(function() writefile(Q_FILE, G.HS:JSONEncode(payload)) end)
      setControlText(lbl, "Queue built ("..#q.." servers). Initiating Hop..."); setControlColor(lbl, P.on)
      G.tw(2)
      if UI.tearingDown or not S.snipe or HOPPER.generation ~= generation then return end
      pcall(function() G.TPS:TeleportToPlaceInstance(plId, q[1], G.LP) end)
    end)
  end
  function HOPPER.stop(lbl)
    S.snipe = false
    HOPPER.generation = HOPPER.generation + 1
    if HOPPER.gui then
      pcall(function() HOPPER.gui:Destroy() end)
      HOPPER.gui = nil
    end
    pcall(function() if isfile(Q_FILE) then delfile(Q_FILE) end end)
    setControlText(lbl, "Hopper Stopped / Queue Cleared"); setControlColor(lbl, P.dng)
  end
  function HOPPER.checkAndHop()
    if type(readfile)~="function" or type(isfile)~="function" then return end
    if not isfile(Q_FILE) then return end
    local ok, raw = pcall(readfile, Q_FILE)
    if not ok or not raw then return end
    local ok2, dec = pcall(function() return G.HS:JSONDecode(raw) end)
    if not ok2 or not dec or not dec.targetId then return end

    S.snipe = true
    HOPPER.generation = HOPPER.generation + 1
    local generation = HOPPER.generation
    if HOPPER.gui then pcall(function() HOPPER.gui:Destroy() end) end
    local ui = G.new("ScreenGui", G.CG)
    ui.Name = "KatalystHopper"
    ui.ResetOnSpawn = false
    HOPPER.gui = ui
    local frm = G.new("Frame", ui); frm.Size=G.UD2(0,300,0,50); frm.Position=G.UD2(0.5,-150,0,20); frm.BackgroundColor3=G.RGB(20,20,20)
    local txt = G.new("TextLabel", frm); txt.Size=G.UD2(1,0,1,0); txt.BackgroundTransparency=1; txt.TextColor3=G.RGB(255,255,255); txt.TextScaled=true
    txt.Text = "Hopper Active: Scanning server..."

    G.ts(function()
      if UI.tearingDown or HOPPER.generation ~= generation then return end
      local isTargetRegion = false
      local detectedRegion = "Unknown"
      
      -- Deepwoken hides region in different StringValues for Depths
      for _, v in ipairs(G.RepS:GetDescendants()) do
        if v:IsA("StringValue") then
          local val = tostring(v.Value)
          for _, r in ipairs({"North", "Paris", "England", "Hesse"}) do
            if string.find(val, r) then
              isTargetRegion = true
              detectedRegion = r
              break
            end
          end
        end
        if isTargetRegion then break end
      end
      
      if isTargetRegion then
        txt.Text = "Scanning: "..detectedRegion
        G.tw(3)
        if UI.tearingDown or HOPPER.generation ~= generation then return end
        local found = false
        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
          if p.UserId == dec.targetId then found = true; break end
        end
        if found then
          txt.Text = "TARGET FOUND IN THIS SERVER!"
          txt.TextColor3 = G.RGB(100,255,100)
          pcall(function() delfile(Q_FILE) end)
          S.snipe = false
          G.noti("Hopper", "Target acquired in "..detectedRegion.."!")
          return
        end
      else
        txt.Text = "Skipping Region: "..detectedRegion
        txt.TextColor3 = G.RGB(255,150,50)
      end
      
      local currJob = game.JobId
      local nextQ = {}
      for _, j in ipairs(dec.queue) do
        if j ~= currJob then table.insert(nextQ, j) end
      end
      table.insert(dec.checked, currJob)
      
      if #nextQ == 0 then
        txt.Text = "All servers checked. Not found."
        txt.TextColor3 = G.RGB(255,100,100)
        pcall(function() delfile(Q_FILE) end)
        S.snipe = false
        return
      end
      
      dec.queue = nextQ
      pcall(function() writefile(Q_FILE, G.HS:JSONEncode(dec)) end)
      txt.Text = "Not here. Hopping to next... ("..#nextQ.." left)"
      G.tw(1)
      if UI.tearingDown or HOPPER.generation ~= generation then return end
      pcall(function() G.TPS:TeleportToPlaceInstance(5735553160, nextQ[1], G.LP) end)
    end)
  end
end
local AUTO_LEARN = {
  active = false,
  en = function()
    AUTO_LEARN.active = true
    G.noti("Auto Learn", "Auto-Learn Enabled", 2)
  end,
  dis = function()
    AUTO_LEARN.active = false
    G.noti("Auto Learn", "Auto-Learn Disabled", 2)
