}

local MACRO_ENGINE = {
  exec = function(idx)
    local macroStr = CFG and CFG["M" .. tostring(idx)]
    if not macroStr or macroStr == "" then return end
    for key in string.gmatch(macroStr, "[^,]+") do
      key = string.gsub(key, "^%s+", ""):gsub("%s+$", "")
      if key == "M1" then G.pressKey(Enum.KeyCode.F)
      elseif key == "M2" then G.pressM2()
      elseif key == "Q" then G.pressKey(Enum.KeyCode.Q)
      elseif key == "E" then G.pressKey(Enum.KeyCode.E)
      elseif key == "R" then G.pressKey(Enum.KeyCode.R)
      elseif key == "F" then G.pressKey(Enum.KeyCode.F)
      elseif key == "G" then G.pressKey(Enum.KeyCode.G)
      end
      task.wait(0.05)
    end
  end
}

local FLIP = {}
do
  local streamerConns = {}
  local streamerHidden = {}
  local function syncAutoDefense()
    AUTO_PARRY.sync()
  end
  local function cleanStreamer()
    for _, c in ipairs(streamerConns) do pcall(function() c:Disconnect() end) end
    table.clear(streamerConns)
    for desc in pairs(streamerHidden) do
      pcall(function() desc.Visible = true end)
    end
    table.clear(streamerHidden)
  end
  local function applyStreamer()
    cleanStreamer()
    if not S.str then return end
    local pg = G.LP:FindFirstChildOfClass("PlayerGui")
    if not pg then return end
    local function handle(desc)
      if desc:IsA("TextLabel") then
        local function check()
          if not S.str then return end
          local txt = desc.Text
          if string.find(txt, "pv_") or string.find(txt, ":A|") then
            if desc.Visible then
              streamerHidden[desc] = true
              desc.Visible = false
            end
          end
        end
        check()
        table.insert(streamerConns, desc:GetPropertyChangedSignal("Text"):Connect(check))
        table.insert(streamerConns, desc:GetPropertyChangedSignal("Visible"):Connect(check))
      end
    end
    for _, desc in ipairs(pg:GetDescendants()) do
      handle(desc)
    end
    table.insert(streamerConns, pg.DescendantAdded:Connect(handle))
  end
  FLIP.applyStreamer = applyStreamer

  local mouseUnlockConn = nil

  function UI.applyV()
    if UI.library then
      UI.library:SetVisible(S.menu)
    end
    if S.menu then
      pcall(function()
        G.UIS.MouseIconEnabled = true
        G.UIS.MouseBehavior = Enum.MouseBehavior.Default
      end)
      pcall(function()
        G.RS:UnbindFromRenderStep("KatalystMouseUnlock")
      end)
      pcall(function()
        G.RS:BindToRenderStep("KatalystMouseUnlock", Enum.RenderPriority.Last.Value, function()
          if S.menu then
            pcall(function()
              G.UIS.MouseIconEnabled = true
              if G.UIS.MouseBehavior ~= Enum.MouseBehavior.Default then
                G.UIS.MouseBehavior = Enum.MouseBehavior.Default
              end
            end)
          else
            pcall(function() G.RS:UnbindFromRenderStep("KatalystMouseUnlock") end)
          end
        end)
      end)
    else
      pcall(function()
        G.RS:UnbindFromRenderStep("KatalystMouseUnlock")
      end)
    end
  end
  function UI.togMenu()
    if not _verifySessionIntegrity() then while true do end end
    S.menu = not S.menu
    UI.applyV()
  end
  function FLIP.filtZeroWeight()
    S.filtZeroWeight = not S.filtZeroWeight
    UI.updTog()
    pcall(G.saveConfig)
    G.noti("Defense Filters", "Filter Zero Weight: " .. (S.filtZeroWeight and "Enabled" or "Disabled"), 2)
  end
  function FLIP.ap() S.ap=not S.ap; if S.ap then APB:start() else APB:stp() end; UI.updTog() end
  function FLIP.plk() S.plk=not S.plk; if S.plk then PL_KILLER:start() else PL_KILLER:stp() end; UI.updTog() end
