    G.noti("Reveal Player Animations", S.revealPlayerAnims and "Enabled (Counter AP Breakers)" or "Disabled", 2)
  end

  function FLIP.panicHide()
    S.panicHide = not S.panicHide
    if S.panicHide then
      if S.autoP then pcall(FLIP.apL) end
      if S.vp then pcall(FLIP.vp) end
      if S.esp then pcall(FLIP.esp) end
      if S.iEsp then pcall(FLIP.ie) end
      if S.mobEsp then pcall(FLIP.mobEsp) end
      if S.fly then pcall(FLIP.fly) end
      if S.agil then pcall(FLIP.ag) end
      if S.agSpd then pcall(FLIP.agSpd) end
      if S.nc then pcall(FLIP.nc) end
      if S.nfd then pcall(FLIP.nf) end
      if S.aSpd then pcall(FLIP.as) end
      if S.apNuker then pcall(FLIP.apNuker) end
      if S.m1Nuker then pcall(FLIP.m1Nuker) end
      if S.desyncBreaker then pcall(FLIP.desyncBreaker) end
      if S.customApb then pcall(FLIP.customApb) end
      if S.combatStance then pcall(FLIP.combatStance) end
      if S.weaponVfx then pcall(FLIP.weaponVfx) end
      if S.combatSfx then pcall(FLIP.combatSfx) end
      if S.voidwalkerRadar then pcall(FLIP.voidwalkerRadar) end
      pcall(function() BANKAI_ENGINE:stop() end)
      pcall(function() FROST_HUD_ENGINE:stop() end)
      if S.logAni then pcall(FLIP.logAni) end
      if S.animVis then pcall(FLIP.animVis) end
      if S.keybindsHud then pcall(FLIP.keybindsHud) end
      if S.noVis then pcall(FLIP.nv) end
      if S.hbx then pcall(FLIP.hbx) end
      if S.hitboxesOn then pcall(FLIP.hitboxesOn) end
      if S.endlag then pcall(FLIP.endlag) end
      if S.knockback then pcall(FLIP.knockback) end
      if S.npcFreeze then pcall(FLIP.npcFreeze) end
      if S.bringMob then pcall(FLIP.bringMob) end
      if S.ferrymanBoss then pcall(FLIP.ferrymanBoss) end
      if S.boatSpeed then pcall(FLIP.boatSpeed) end
      if S.cframeSpeed then pcall(FLIP.cframeSpeed) end
      if S.speedhack then pcall(FLIP.speedhack) end
      if S.identitySpoof then pcall(FLIP.identitySpoof) end
      if S.autoLoot then pcall(FLIP.autoLoot) end
      if S.pHud then pcall(FLIP.pHud) end
      if S.sanityTracker then pcall(FLIP.sanityTracker) end
      if S.autoSprint then pcall(FLIP.autoSprint) end
      if S.infiniteJump then pcall(FLIP.infiniteJump) end
      if S.maxMomentum then pcall(FLIP.maxMomentum) end

      if not S.revealPlayerAnims then pcall(FLIP.revealPlayerAnims) end

      pcall(function()
        if PARRY_LOGS_UI and PARRY_LOGS_UI.container then PARRY_LOGS_UI.container.Visible = false end
        if KEYBINDS_HUD and KEYBINDS_HUD.gui then KEYBINDS_HUD.gui.Enabled = false end
        if PING_HUD and PING_HUD.gui then PING_HUD.gui.Enabled = false end
        if ANIM_LOGGER and ANIM_LOGGER.gui then ANIM_LOGGER.gui.Enabled = false end
        if SANITY_TRACKER and SANITY_TRACKER.gui then SANITY_TRACKER.gui.Enabled = false end
        if ANIMATION_VISUALIZER and ANIMATION_VISUALIZER.gui then ANIMATION_VISUALIZER.gui.Enabled = false end
        if ESP and ESP.stop then ESP.stop() end
        if IESP and IESP.stop then IESP.stop() end
        if MESP and MESP.stop then MESP.stop() end
      end)

      G.noti("PANIC HIDE (Clip Mode)", "ENABLED - All features off except Animation Revealer. HUD overlays hidden.", 3)
    else
      G.noti("PANIC HIDE (Clip Mode)", "DISABLED - Re-enable features manually.", 3)
    end
    UI.updTog()
    UI.applyV()
    pcall(G.saveConfig)
  end
  function FLIP.reveal0Weight()
    S.reveal0Weight = not S.reveal0Weight
    UI.updTog()
    pcall(G.saveConfig)
    G.noti("Show 0-Weight Animations", S.reveal0Weight and "Enabled" or "Disabled", 2)
  end
  function FLIP.revealLowWeight()
    S.revealLowWeight = not S.revealLowWeight
    UI.updTog()
    pcall(G.saveConfig)
    G.noti("Show Low-Weight Animations", S.revealLowWeight and "Enabled" or "Disabled", 2)
  end
  function FLIP.revealCorePri()
    S.revealCorePri = not S.revealCorePri
    UI.updTog()
    pcall(G.saveConfig)
    G.noti("Show Core Priority", S.revealCorePri and "Enabled" or "Disabled", 2)
  end
  function FLIP.revealIdlePri()
    S.revealIdlePri = not S.revealIdlePri
    UI.updTog()
    pcall(G.saveConfig)
    G.noti("Show Idle Priority", S.revealIdlePri and "Enabled" or "Disabled", 2)
  end
  function FLIP.hideAboveAction()
    S.hideAboveAction = not S.hideAboveAction
    UI.updTog()
    pcall(G.saveConfig)
    G.noti("Hide Above Action", S.hideAboveAction and "Enabled" or "Disabled", 2)
  end
  function FLIP.smarterDefense() S.smarterDefense=not S.smarterDefense; if S.smarterDefense then SMARTER_DEFENSE.start() else SMARTER_DEFENSE.stop() end; UI.updTog() end
  function FLIP.potatoGraphics() S.potatoGraphics=not S.potatoGraphics; if S.potatoGraphics then PERF.enablePotatoGraphics() else PERF.disablePotatoGraphics() end; UI.updTog() end
  function FLIP.focusSaver() S.focusSaver=not S.focusSaver; if S.focusSaver then PERF.enableFocusSaver() else PERF.disableFocusSaver() end; UI.updTog() end
  function FLIP.nkb() S.nkb=not S.nkb; if S.nkb then FAKE_VOID.en() else FAKE_VOID.dis() end; UI.updTog() end
  function FLIP.attach()
    S.attach = not S.attach
    if S.attach then
      if ATTACH_PLAYER.target then
        ATTACH_PLAYER.start(ATTACH_PLAYER.target)
      else
        local myChar = G.LP.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local nearest, nearestDist = nil, CFG.AttachRange or 500
        if myRoot then
          for _, p in ipairs(G.Plrs:GetPlayers()) do
            if p ~= G.LP and p.Character then
              local hrp = p.Character:FindFirstChild("HumanoidRootPart")
              if hrp then
                local d = (hrp.Position - myRoot.Position).Magnitude
                if d < nearestDist then nearest = p; nearestDist = d end
              end
            end
          end
        end
        if nearest then
          ATTACH_PLAYER.start(nearest)
        else
          S.attach = false
          G.noti("Attach", "No target in range!")
        end
      end
    else
      ATTACH_PLAYER.stop()
    end
    UI.updTog()
  end
  function FLIP.attachMob()
    S.attachMob = not S.attachMob
    if S.attachMob then
      if ATTACH_MOB.target then
        ATTACH_MOB.start(ATTACH_MOB.target)
      else
        local myChar = G.LP.Character
        local myRoot = myChar and myChar:FindFirstChild("HumanoidRootPart")
        local nearest, nearestDist = nil, CFG.AttachRange or 500
        if myRoot then
          local live = G.WS:FindFirstChild("Live") or G.WS
          for _, d in ipairs(live:GetChildren()) do
            if d ~= myChar and d:IsA("Model") and d:FindFirstChildOfClass("Humanoid") then
              local isPlr = G.Plrs:GetPlayerFromCharacter(d)
              if not isPlr then
                local hrp = d:FindFirstChild("HumanoidRootPart") or d.PrimaryPart
                if hrp then
                  local dist = (hrp.Position - myRoot.Position).Magnitude
                  if dist < nearestDist then nearest = d; nearestDist = dist end
                end
              end
            end
          end
        end
        if nearest then
          ATTACH_MOB.start(nearest)
        else
          S.attachMob = false
          G.noti("Attach Mob", "No mob/NPC in range!")
        end
      end
    else
      ATTACH_MOB.stop()
    end
    UI.updTog()
  end
  function FLIP.unlockEmotes()
    S.unlockEmotes = not S.unlockEmotes
    if S.unlockEmotes then
      EMOTE_SPOOFER.en()
    else
      EMOTE_SPOOFER.dis()
    end
    UI.updTog()
    pcall(G.saveConfig)
  end
end
do
local function rollCancelSessionActive()
  return UI.tearingDown ~= true
end

local function canRunRollCancel()
  return rollCancelSessionActive()
    and S.blatantRoll == true
    and not InputClient.isDirectDodgeActive()
end

local function performRollCancel()
  if not canRunRollCancel() then return end
  pcall(function()
    local stopDodge = getRemote("StopDodge")
    if stopDodge then
      pcall(function()
        stopDodge:FireServer({ A = false, D = false, S = false, W = false }, false, true)
      end)
    end

    local feintRemote = getRemote("FeintClick")
    if feintRemote then
      pcall(function() feintRemote:FireServer() end)
    elseif G.VIM or (type(mouse2press) == "function" and type(mouse2release) == "function") then
      pcall(G.pressM2)
    end

    local ch = G.LP and G.LP.Character
    if ch then
      local hum = ch:FindFirstChildOfClass("Humanoid")
      local ani = hum and hum:FindFirstChildOfClass("Animator")
      if ani then
        for _, tr in ipairs(ani:GetPlayingAnimationTracks()) do
          local name = (tr.Name or ""):lower()
          if name:find("roll") or name:find("dodge") or name:find("slide") then
            pcall(function() tr:Stop(0) end)
          end
        end
      end
    end
  end)
end

local rollCancelPending = false
local function scheduleRollCancel()
  if not canRunRollCancel() or rollCancelPending then return end
  rollCancelPending = true
  task.delay(0.18, function()
    rollCancelPending = false
    if not canRunRollCancel() then return end
    performRollCancel()
  end)
end

  trk(G.UIS.InputBegan:Connect(function(inp, gpe)
    if gpe or G.UIS:GetFocusedTextBox() then return end
    if UI.library and UI.library:IsCapturingKeybind() then return end
    if inp.KeyCode == Enum.KeyCode.Q and S.blatantRoll then
      scheduleRollCancel()
    end
  end))

pcall(function()
  local function hookCharRollCancel(ch)
    local function ownsCharacter()
      return rollCancelSessionActive() and G.LP and G.LP.Character == ch
    end

    if not ch or not ownsCharacter() then return end
    local hum = ch:WaitForChild("Humanoid", 3)
    if not hum or not ownsCharacter() then return end
    local ani = hum:WaitForChild("Animator", 3)
    if not ani or not ownsCharacter() then return end

    trk(ani.AnimationPlayed:Connect(function(tr)
      if not ownsCharacter() or InputClient.isDirectDodgeActive() then return end
      if S.blatantRoll then
        local name = (tr.Name or ""):lower()
        if name:find("roll") or name:find("dodge") then
          scheduleRollCancel()
        end
      end
    end))
  end
  if G.LP then
    trk(G.LP.CharacterAdded:Connect(hookCharRollCancel))
    if G.LP.Character then hookCharRollCancel(G.LP.Character) end
  end
end)

local flipAlias = {
  freestylersSpoof = "freestylerSpoof",
  kongaRingSpoof = "kongaSpoof",
  autoP = "apL",
  iEsp = "ie",
  agil = "ag",
  nfd = "nf",
  str = "st",
  noVis = "nv",
  echo = "ef",
  aSpd = "as",
  opt = "op",
  gChat = "gc",
}

local stateAlias = {
  apL = "autoP",
  ie = "iEsp",
  ag = "agil",
  nf = "nfd",
  st = "str",
  nv = "noVis",
  ef = "echo",
  as = "aSpd",
  op = "opt",
  gc = "gChat",
  apBreaker = "apNuker",
}

local function stateForBinding(binding)
  return stateAlias[binding] or binding
end

local function flipForBinding(binding)
  return flipAlias[binding] or binding
end

CFG.KeybindModes = type(CFG.KeybindModes) == "table" and CFG.KeybindModes or {}

local function modeForBinding(binding)
  local modes = CFG.KeybindModes
  return type(modes) == "table" and modes[binding] == "Hold" and "Hold" or "Toggle"
end

function UI.bindInp()
  if UI.inputBound then return end
  UI.inputBound = true
  local heldBindings = {}

  trk(G.UIS.InputBegan:Connect(function(inp, gpe)
    if gpe or G.UIS:GetFocusedTextBox() then return end
    if UI.library and UI.library.IsCapturingKeybind and UI.library:IsCapturingKeybind() then return end

    local kc = inp.KeyCode
    if kc == Enum.KeyCode.Unknown then return end
    if kc == (kb.menuKey or CFG.MenuKey) then
      UI.togMenu()
      return
    end

    if S.autoSpoof then
      local isPlus = kc == Enum.KeyCode.Equals or kc == Enum.KeyCode.KeypadPlus
      local isMinus = kc == Enum.KeyCode.Minus or kc == Enum.KeyCode.KeypadMinus
      if isPlus or isMinus then
        local increase = (S.autoSpoofMode == "+") == isPlus
        if S.agil then
          CFG.AgilVal = increase and math.min(CFG.AgilMax, CFG.AgilVal + 10) or math.max(CFG.AgilMin, CFG.AgilVal - 10)
          UI.syncValue("AgilVal")
        end
        if S.agSpd then
          CFG.SpdVal = increase and math.min(CFG.SpdMax, CFG.SpdVal + 2) or math.max(CFG.SpdMin, CFG.SpdVal - 2)
          UI.syncValue("SpdVal")
        end
        pcall(G.saveConfig)
      end
    end

    local matched = {}
    for binding, boundKey in pairs(kb) do
      if binding ~= "menuKey" and boundKey == kc then
        matched[#matched + 1] = binding
      end
    end
    if #matched == 0 then return end

    local allTogglesOn = true
    for _, binding in ipairs(matched) do
      local action = FLIP[flipForBinding(binding)]
      local state = S[stateForBinding(binding)]
      if action and type(state) == "boolean" and modeForBinding(binding) == "Toggle" then
        if not state then
          allTogglesOn = false
        end
      end
    end
    local targetState = not allTogglesOn

    for _, binding in ipairs(matched) do
      pcall(function()
        if binding == "m1" then
          MACRO_ENGINE.exec(1)
        elseif binding == "m2" then
          MACRO_ENGINE.exec(2)
        elseif binding == "m3" then
          MACRO_ENGINE.exec(3)
        else
          local action = FLIP[flipForBinding(binding)]
          if not action then return end

          local stateKey = stateForBinding(binding)
          local state = S[stateKey]
          if type(state) ~= "boolean" then
            action()
          elseif modeForBinding(binding) == "Hold" then
            if not heldBindings[binding] and not state then
              action()
              if S[stateKey] == true then
                heldBindings[binding] = {
                  action = action,
                  keyCode = kc,
                  stateKey = stateKey,
                }
              end
            end
          elseif state ~= targetState then
            action()
          end
        end
      end)
    end

    UI.updTog(true)
    pcall(G.saveConfig)
  end))

  trk(G.UIS.InputEnded:Connect(function(inp)
    local kc = inp.KeyCode
    if kc == Enum.KeyCode.Unknown then return end

    local released = false
    for binding, held in pairs(heldBindings) do
      if held.keyCode == kc then
        heldBindings[binding] = nil
        released = true
        if S[held.stateKey] == true then
          pcall(held.action)
        end
      end
    end
    if not released then return end

    UI.updTog(true)
    pcall(G.saveConfig)
  end))
end
end

UI.stateControls = {}
UI.valueControls = {}
UI.stateSnapshots = {}
UI.valueSnapshots = {}
UI.syncing = false

local function sameControlValue(left, right)
  if left == right then return true end
  if type(left) ~= "table" or type(right) ~= "table" then return false end
  for key, value in pairs(left) do
    if right[key] ~= value then return false end
  end
  for key, value in pairs(right) do
    if left[key] ~= value then return false end
  end
  return true
end

local function applyControlValue(control, value)
  local called, applied, message = pcall(control.SetValue, control, value)
  if not called then return false, applied end
  if applied == false then return false, message end
  return true
end

local function reportSyncFailure(kind, name, message)
  warn(string.format("[Katalyst] Could not sync %s %s: %s", kind, tostring(name), tostring(message)))
end

function UI.registerState(stateKey, control)
  UI.stateControls[stateKey] = control
  local value = S[stateKey]
  if value == nil then value = CFG[stateKey] end
  UI.stateSnapshots[stateKey] = value
end

function UI.registerValue(name, control, read)
  UI.valueControls[name] = {
    control = control,
    read = read,
  }
  if type(read) == "function" then
    local ok, value = pcall(read)
    if ok then UI.valueSnapshots[name] = value end
  end
end

function UI.clearControls()
  table.clear(UI.stateControls)
  table.clear(UI.valueControls)
  table.clear(UI.stateSnapshots)
  table.clear(UI.valueSnapshots)
end

function UI.syncState(stateKey)
  local control = UI.stateControls[stateKey]
  if not control then return end
  local value = S[stateKey]
  if value == nil then value = CFG[stateKey] end
  if value == nil then return end

  local wasSyncing = UI.syncing
  UI.syncing = true
  local ok, message = applyControlValue(control, value)
  UI.syncing = wasSyncing
  if ok then
    UI.stateSnapshots[stateKey] = value
  else
    reportSyncFailure("state", stateKey, message)
  end
end

function UI.syncValue(name)
  local entry = UI.valueControls[name]
  if not entry or type(entry.read) ~= "function" then return end

  local ok, value = pcall(entry.read)
  if not ok or value == nil then return end

  local wasSyncing = UI.syncing
  UI.syncing = true
  local applied, message = applyControlValue(entry.control, value)
  UI.syncing = wasSyncing
  if applied then
    UI.valueSnapshots[name] = value
  else
    reportSyncFailure("value", name, message)
  end
end

function UI.syncAll()
  local wasSyncing = UI.syncing
  UI.syncing = true

  for stateKey, control in pairs(UI.stateControls) do
    local value = S[stateKey]
    if value == nil then value = CFG[stateKey] end
    if value ~= nil then
      local applied, message = applyControlValue(control, value)
      if applied then
        UI.stateSnapshots[stateKey] = value
      else
        reportSyncFailure("state", stateKey, message)
      end
    end
  end

  for name, entry in pairs(UI.valueControls) do
    if type(entry.read) == "function" then
      local ok, value = pcall(entry.read)
      if ok and value ~= nil then
        local applied, message = applyControlValue(entry.control, value)
        if applied then
          UI.valueSnapshots[name] = value
        else
          reportSyncFailure("value", name, message)
        end
      end
    end
  end

  UI.syncing = wasSyncing
end

function UI.syncChanged(includeValues)
  for stateKey in pairs(UI.stateControls) do
    local value = S[stateKey]
    if value == nil then value = CFG[stateKey] end
    if value ~= nil and not sameControlValue(UI.stateSnapshots[stateKey], value) then
      UI.syncState(stateKey)
    end
  end

  if not includeValues then return end
  for name, entry in pairs(UI.valueControls) do
    if type(entry.read) == "function" then
      local ok, value = pcall(entry.read)
      if ok and value ~= nil and not sameControlValue(UI.valueSnapshots[name], value) then
        UI.syncValue(name)
      end
    end
  end
end

function UI.updDyn()
  UI.syncChanged(true)
end

function UI.updTog(skipSave)
  UI.syncChanged(false)
  if KEYBINDS_HUD and KEYBINDS_HUD.gui then
    pcall(KEYBINDS_HUD.update)
  end
  if not skipSave then
    pcall(G.saveConfig)
  end
end

UI.volatileStates = {
  apBreaker = true,
  animationBreaker = true,
  customApb = true,
  apNuker = true,
  fly = true,
}

local function restoreFeature(name, enabled, callback)
  if not enabled then return true end
  local ok, result, reason = pcall(callback)
  if not ok or result == false then
    local message = ok and reason or result
    warn("[Katalyst] Could not restore " .. name .. ": " .. tostring(message))
    return false, message
  end
  return true
end

