function UI.reconcileImportedState(previous)
  local desired = {}
  for stateKey, value in pairs(S) do
    if type(value) == "boolean" then
      desired[stateKey] = UI.volatileStates[stateKey] and false or value
    end
  end

  local lifecycleActions = UI.lifecycleActions or {}
  for stateKey, value in pairs(desired) do
    if not lifecycleActions[stateKey] then
      S[stateKey] = value
    end
  end

  local function transitionLifecycle(stateKey, target)
    local prior = S[stateKey]
    if prior == target then return true end
    local action = FLIP[lifecycleActions[stateKey]]
    if not action then
      warn("[Katalyst] Missing lifecycle action for " .. stateKey)
      return false
    end

    local ok, message = pcall(action)
    if not ok or S[stateKey] ~= target then
      S[stateKey] = prior
      warn("[Katalyst] Could not reconcile " .. stateKey .. ": " .. tostring(message or "state did not change"))
      return false
    end
    return true
  end

  local function reconcileLifecycle(stateKey)
    local value = desired[stateKey]
    local actionKey = lifecycleActions[stateKey]
    if value == nil or not actionKey then return end

    local prior = previous[stateKey]
    if prior == value then
      S[stateKey] = value
      return
    end

    S[stateKey] = prior
    transitionLifecycle(stateKey, value)
  end

  local orderedGraphics = {"opt", "noVis", "potatoGraphics", "focusSaver"}
  local reconciled = {}
  local firstGraphicsChange
  for index, stateKey in ipairs(orderedGraphics) do
    if previous[stateKey] ~= desired[stateKey] then
      firstGraphicsChange = index
      break
    end
  end

  if firstGraphicsChange then
    for _, stateKey in ipairs(orderedGraphics) do
      S[stateKey] = previous[stateKey]
    end
    for index = #orderedGraphics, firstGraphicsChange, -1 do
      local stateKey = orderedGraphics[index]
      transitionLifecycle(stateKey, false)
      reconciled[stateKey] = true
    end
    for index = firstGraphicsChange, #orderedGraphics do
      local stateKey = orderedGraphics[index]
      transitionLifecycle(stateKey, desired[stateKey] == true)
      reconciled[stateKey] = true
    end
  else
    for _, stateKey in ipairs(orderedGraphics) do
      reconciled[stateKey] = true
    end
  end
  for _, stateKey in ipairs(UI.lifecycleOrder or {}) do
    if stateKey ~= "panicHide" and not reconciled[stateKey] then
      reconcileLifecycle(stateKey)
    end
  end
  reconcileLifecycle("panicHide")

  AUTO_PARRY.sync()
  UI.syncAll()
  if KEYBINDS_HUD and KEYBINDS_HUD.gui then
    pcall(KEYBINDS_HUD.update)
  end
end
-- Guild/Name overrides (modifies existing in-game displays)
local lastUpdate = 0
local characterNames = {}
local GUILD_NAMES = {
  heartbeat = nil,
  clickConnections = {},
  originals = {},
}

local function rememberOriginal(label)
  if label and not GUILD_NAMES.originals[label] then
    GUILD_NAMES.originals[label] = label.Text
  end
end

-- Helper function to find the overhead BillboardGui for a character
local function getOverheadBillboard(char)
  for _, child in ipairs(char:GetChildren()) do
    if child:IsA("BillboardGui") then
      return child
    end
  end
  local head = char:FindFirstChild("Head")
  if head then
    for _, child in ipairs(head:GetChildren()) do
      if child:IsA("BillboardGui") then
        return child
      end
    end
  end
  local hrp = char:FindFirstChild("HumanoidRootPart")
  if hrp then
    for _, child in ipairs(hrp:GetChildren()) do
      if child:IsA("BillboardGui") then
        return child
      end
    end
  end
  for _, desc in ipairs(char:GetChildren()) do
    if desc:IsA("Model") or desc:IsA("Folder") then
      for _, child in ipairs(desc:GetChildren()) do
        if child:IsA("BillboardGui") then
          return child
        end
      end
    end
  end
  return nil
end

local function updateGuildNames()
  if not CFG.GuildOverrides then CFG.GuildOverrides = {} end
  if not CFG.NameOverrides then CFG.NameOverrides = {} end
  if not CFG.RobloxNameOverrides then CFG.RobloxNameOverrides = {} end

  for guiObject, connection in pairs(GUILD_NAMES.clickConnections) do
    if not guiObject.Parent then
      pcall(connection.Disconnect, connection)
      GUILD_NAMES.clickConnections[guiObject] = nil
    end
  end
  for label in pairs(GUILD_NAMES.originals) do
    if not label.Parent then GUILD_NAMES.originals[label] = nil end
  end

  for _, p in ipairs(G.Plrs:GetPlayers()) do
    local uid = tostring(p.UserId)
    local gOverride = CFG.GuildOverrides[uid]
    if not gOverride and CFG.GuildName and CFG.GuildName ~= "" then
      gOverride = CFG.GuildName
    end
    local nOverride = CFG.NameOverrides[uid]

    if p.Character then
      pcall(function()
        local bbg = getOverheadBillboard(p.Character)
        if bbg then
          local allLabels = {}
          for _, child in ipairs(bbg:GetChildren()) do
            if child:IsA("TextLabel") and child.Text and child.Text ~= "" then
              local t = child.Text
              if not string.match(t, "^%d+$")
                and not string.find(t, "^Lv")
                and not string.find(t, "HP")
                and not string.find(t, "%%")
                and #t < 60 then
                allLabels[#allLabels+1] = child
              end
            elseif child:IsA("Frame") or child:IsA("GuiObject") then
              for _, grandchild in ipairs(child:GetChildren()) do
                if grandchild:IsA("TextLabel") and grandchild.Text and grandchild.Text ~= "" then
                  local t = grandchild.Text
                  if not string.match(t, "^%d+$")
                    and not string.find(t, "^Lv")
                    and not string.find(t, "HP")
                    and not string.find(t, "%%")
                    and #t < 60 then
                    allLabels[#allLabels+1] = grandchild
                  end
                end
              end
            end
          end

          if #allLabels > 0 then
            -- Sort by TextSize descending: biggest font is the Character Name
            table.sort(allLabels, function(a, b)
              return a.TextSize > b.TextSize
            end)

            local originalText = allLabels[1].Text
            if originalText and originalText ~= "" and originalText ~= nOverride then
              characterNames[uid] = originalText
            end

            -- Override display name (largest label)
            if nOverride and allLabels[1] then
              rememberOriginal(allLabels[1])
              allLabels[1].Text = nOverride
            end

            -- Override guild name / title lines (all smaller labels)
            if gOverride then
              for i = 2, #allLabels do
                rememberOriginal(allLabels[i])
                allLabels[i].Text = gOverride
              end
            end
          end
        end
      end)
    end
  end

  local rOriginals = GUILD_NAMES.originals
  
  local containersToScan = {}
  local pg = G.LP and (G.LP:FindFirstChildOfClass("PlayerGui") or G.LP:FindFirstChild("PlayerGui"))
  if pg then
    for _, cName in ipairs({"Leaderboard", "PlayerList", "ServerList"}) do
      local found = pg:FindFirstChild(cName, true)
      if found then table.insert(containersToScan, found) end
    end
  end
  
  local okCG, coreGui = pcall(game.GetService, game, "CoreGui")
  if okCG and coreGui then
    local pList = coreGui:FindFirstChild("PlayerList") or coreGui:FindFirstChild("PlayerListMaster", true)
    if pList then table.insert(containersToScan, pList) end
  end

  pcall(function()
    for _, container in ipairs(containersToScan) do
      for _, lbl in ipairs(container:GetDescendants()) do
        if (lbl:IsA("TextLabel") or lbl:IsA("TextButton")) and lbl.Text and lbl.Text ~= "" then
          local t = rOriginals[lbl] or lbl.Text
          for _, p in ipairs(G.Plrs:GetPlayers()) do
            local uid = tostring(p.UserId)
            local charName = characterNames[uid]
            
            -- Match character name, username, or display name
            local isNameLabel = (charName and charName ~= "" and (t == charName or string.find(t, charName, 1, true)))
              or t == p.DisplayName or string.find(t, p.DisplayName, 1, true)
              or t == p.Name or string.find(t, p.Name, 1, true)
            
            if isNameLabel then
              if not rOriginals[lbl] then rOriginals[lbl] = t end
              
              -- Innate click to spectate (infinite range) / attach (CFG.AttachRange)
              local clickObj = (lbl:IsA("GuiButton") and lbl) or lbl.Parent
              if clickObj and clickObj:IsA("GuiObject") and not GUILD_NAMES.clickConnections[clickObj] then
                local lastClickTime = 0
                local function onPlayerListClick()
                  local now = os.clock()
                  if (now - lastClickTime) < 0.25 then return end -- Debounce multi-firing
                  lastClickTime = now
                  
                  if p == G.LP then
                    SPEC.stop()
                    if ATTACH_PLAYER and ATTACH_PLAYER.stop then ATTACH_PLAYER.stop() end
                    return
                  end
                  if G.UIS:IsKeyDown(Enum.KeyCode.LeftShift) or G.UIS:IsKeyDown(Enum.KeyCode.RightShift) then
                    if ATTACH_PLAYER then
                      if ATTACH_PLAYER.target == p then ATTACH_PLAYER.stop() else ATTACH_PLAYER.start(p) end
                    end
                  else
                    if SPEC.cur == p and S.spec then
                      SPEC.start(p)
                    else
                      SPEC.start(p)
                    end
                  end
                end

                GUILD_NAMES.clickConnections[clickObj] = clickObj.InputBegan:Connect(function(input)
                  if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                    -- Ensure click is on an active leaderboard container, not game world combat attacks
                    local isLeaderboardVisible = container and container.Visible
                    if container:IsA("GuiObject") then
                      local current = container
                      while current and current ~= pg and current ~= coreGui do
                        if not current.Visible then isLeaderboardVisible = false; break end
                        current = current.Parent
                      end
                    end
                    if isLeaderboardVisible then
                      onPlayerListClick()
                    end
                  end
                end)
              end

              -- Apply Roblox display name override
              local rOverride = CFG.RobloxNameOverrides and CFG.RobloxNameOverrides[uid]
              if rOverride then
                lbl.Text = rOverride
              end
              
              -- Apply guild override to sibling/cousin labels
              local gOverride = CFG.GuildOverrides and CFG.GuildOverrides[uid]
              if not gOverride and CFG.GuildName and CFG.GuildName ~= "" then
                gOverride = CFG.GuildName
              end
              if gOverride then
                local pContainer = lbl.Parent
                if pContainer then
                  for _, sibling in ipairs(pContainer:GetChildren()) do
                    if sibling:IsA("TextLabel") and sibling ~= lbl then
                      rememberOriginal(sibling)
                      sibling.Text = gOverride
                    end
                  end
                end
              end
              break
            end
          end
        end
      end
    end
  end)
end

function GUILD_NAMES.stop()
  if GUILD_NAMES.heartbeat then
    GUILD_NAMES.heartbeat:Disconnect()
    GUILD_NAMES.heartbeat = nil
  end
  for guiObject, connection in pairs(GUILD_NAMES.clickConnections) do
    if connection then pcall(connection.Disconnect, connection) end
    GUILD_NAMES.clickConnections[guiObject] = nil
  end
  for label, originalText in pairs(GUILD_NAMES.originals) do
    if label.Parent then
      pcall(function() label.Text = originalText end)
    end
    GUILD_NAMES.originals[label] = nil
  end
  table.clear(characterNames)
  lastUpdate = 0
end

function GUILD_NAMES.start()
  if GUILD_NAMES.heartbeat then return end
  GUILD_NAMES.heartbeat = G.RS.Heartbeat:Connect(function()
    local now = os.clock()
    if now - lastUpdate >= 2 then
      lastUpdate = now
      updateGuildNames()
    end
  end)
end

GUILD_NAMES.start()
PACKET_PLK = {on=false,stop=nil,cc=nil}
do
  local BREAKER_ANIMS = {
    "rbxassetid://18897116048", -- Subtle Mantra Focus
    "rbxassetid://18897118423", -- Subtle Aura Channel
    "rbxassetid://18897121015" -- Subtle Stance Adjustment
  }
  local function run(ch)
    if not ch then return function() end end
    local hum = ch:FindFirstChildOfClass("Humanoid")
    if not hum then return function() end end
    local ani = hum:FindFirstChildOfClass("Animator")
    if not ani then ani = G.new("Animator"); ani.Parent = hum end
    
    local trs = {}
    for _, id in ipairs(BREAKER_ANIMS) do
      pcall(function()
        local a = G.new("Animation"); a.AnimationId = id
        local tr = ani:LoadAnimation(a)
        tr.Priority = Enum.AnimationPriority.Action
        G.ti(trs, tr)
      end)
    end
    if #trs == 0 then return function() end end
    
    local go = true
    task.spawn(function()
      local actionPriorities = {
        Enum.AnimationPriority.Action,
        Enum.AnimationPriority.Action2,
        Enum.AnimationPriority.Action3,
      }
      local curIdx = 0
      while go do
        if not ch.Parent then break end
        
        local mode = CFG.PKTMode or "aggressive"
        local playWt = 0.5
        local playSpd = 1.0
        local playFade = 0.05
        local waitTime = 0.4
        local burstCount = 1
        
        if mode == "passive" then
          playWt = 0.30 + (math.random() * 0.25)
          playSpd = 1.0
          playFade = 0.015
          waitTime = 0.55 + math.random() * 0.25
          burstCount = 1
        elseif mode == "aggressive" then
          playWt = 0.88
          playSpd = 1.0
          waitTime = 0.25 + math.random() * 0.12
          burstCount = math.random(1, 2)
        else -- blatant
          playWt = 1.0
          playSpd = 1.2
          waitTime = 0.08 + math.random() * 0.04
          burstCount = math.random(4, 6)
        end
        
        pcall(function()
          for i = 1, burstCount do
            if not go or not ch.Parent then break end
            curIdx = (curIdx % #trs) + 1
            local tr = trs[curIdx]
            if tr then
              tr.Priority = actionPriorities[((i - 1) % #actionPriorities) + 1]
              tr:Play(playFade, playWt, playSpd)
              task.delay(0.45, function()
                pcall(function() tr:Stop(1.2) end)
              end)
            end
            if burstCount > 1 then task.wait(0.04) end
          end
        end)
        
        task.wait(waitTime)
      end
    end)
    
    return function()
      go = false
      for _, t in ipairs(trs) do pcall(function() t:Stop(0.3); t:Destroy() end) end
    end
  end
  
  local function att(ch)
    if PACKET_PLK.stop then PACKET_PLK.stop() end
    PACKET_PLK.stop = nil
    if not PACKET_PLK.on or not ch then return end
    PACKET_PLK.stop = run(ch)
  end
  
  function PACKET_PLK:start()
    if self.on then return end
    self.on = true
    if not self.cc then
      self.cc = G.LP.CharacterAdded:Connect(att)
    end
    task.spawn(function()
      att(G.LP.Character or G.LP.CharacterAdded:Wait())
    end)
  end
  
  function PACKET_PLK:stp()
    if not self.on then return end
    self.on = false
    if self.stop then self.stop(); self.stop = nil end
    if self.cc then self.cc:Disconnect(); self.cc = nil end
  end
end

