local function new(className, properties)
  local instance = Instance.new(className)
  local parent = properties.Parent

  for property, value in pairs(properties) do
    if property ~= "Parent" then
      instance[property] = value
    end
  end

  instance.Parent = parent
  return instance
end

local function corner(instance, radius)
  return new("UICorner", {
    CornerRadius = UDim.new(0, radius or Metrics.Radius),
    Parent = instance,
  })
end

local function padding(instance, left, right, top, bottom)
  return new("UIPadding", {
    PaddingLeft = UDim.new(0, left or 0),
    PaddingRight = UDim.new(0, right or left or 0),
    PaddingTop = UDim.new(0, top or left or 0),
    PaddingBottom = UDim.new(0, bottom or top or left or 0),
    Parent = instance,
  })
end

local function list(instance, gap, horizontal)
  return new("UIListLayout", {
    FillDirection = horizontal and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical,
    HorizontalAlignment = Enum.HorizontalAlignment.Left,
    SortOrder = Enum.SortOrder.LayoutOrder,
    Padding = UDim.new(0, gap or 0),
    Parent = instance,
  })
end

local function cloneArray(values)
  local result = table.create(#values)
  for index, value in ipairs(values) do
    result[index] = value
  end
  return result
end

local function arraysEqual(left, right)
  if #left ~= #right then
    return false
  end

  for index, value in ipairs(left) do
    if right[index] ~= value then
      return false
    end
  end

  return true
end

local function freezeArray(values)
  return cloneArray(values)
end

local function contains(values, wanted)
  for _, value in ipairs(values) do
    if value == wanted then
      return true
    end
  end
  return false
end

local function decimalPlaces(increment)
  local text = string.format("%.10f", increment):gsub("0+$", "")
  local point = string.find(text, ".", 1, true)
  return point and #text - point or 0
end

local function roundTo(value, increment)
  return math.floor(value / increment + 0.5) * increment
end

local function quantize(value, minimum, increment)
  return minimum + roundTo(value - minimum, increment)
end

local function colorHex(color)
  return string.format("#%02X%02X%02X", math.round(color.R * 255), math.round(color.G * 255), math.round(color.B * 255))
end

local function colorFromHex(text)
  local hex = string.gsub(text, "#", "")
  if not string.match(hex, "^%x%x%x%x%x%x$") then
    return nil
  end

  return Color3.fromRGB(
    tonumber(string.sub(hex, 1, 2), 16),
    tonumber(string.sub(hex, 3, 4), 16),
    tonumber(string.sub(hex, 5, 6), 16)
  )
end

local function safeCallback(callback, ...)
  if not callback then
    return
  end

  local ok, message = pcall(callback, ...)
  if not ok then
    warn("[KatalystUI] " .. tostring(message))
  end
end

local function inside(frame, point)
  if not frame or not frame.Parent then
    return false
  end

  local position = frame.AbsolutePosition
  local size = frame.AbsoluteSize
  return point.X >= position.X
    and point.X <= position.X + size.X
    and point.Y >= position.Y
    and point.Y <= position.Y + size.Y
end

local function guiParent()
  if type(gethui) == "function" then
    local ok, result = pcall(gethui)
    if ok and typeof(result) == "Instance" then
      return result
    end
  end

  return game:GetService("CoreGui")
end

local function protectGui(root)
  local protector = environment.protectgui
  if type(protector) ~= "function" then
    protector = environment.protect_gui
  end
  if type(protector) ~= "function" then
    local ok, synProtector = pcall(function()
      return environment.syn and environment.syn.protect_gui
    end)
    if ok then
      protector = synProtector
    end
  end

  if type(protector) == "function" then
    pcall(protector, root)
  end
end

function Library:_connect(signal, callback)
  local connection = signal:Connect(callback)
  self.Connections[#self.Connections + 1] = connection
  return connection
end

function Library:_pruneRegistries()
  for index = #self.Connections, 1, -1 do
    if not self.Connections[index].Connected then
      table.remove(self.Connections, index)
    end
  end

  for index = #self._accentBindings, 1, -1 do
    local instance = self._accentBindings[index].Instance
    if not instance or not instance.Parent then
      table.remove(self._accentBindings, index)
    end
  end
end

function Library:_bind(instance, property, token)
  instance[property] = self.Theme[token]
  if token == "Accent" then
    self._accentBindings[#self._accentBindings + 1] = {
      Instance = instance,
      Property = property,
    }
  end
end

function Library:_tween(instance, properties, onCompleted, tweenInfo)
  local tween = TweenService:Create(
    instance,
    tweenInfo or TweenInfo.new(Metrics.Motion, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
    properties
  )
  self._tweens[tween] = true
  tween.Completed:Once(function(playbackState)
    self._tweens[tween] = nil
    if onCompleted then
      onCompleted(playbackState)
    end
  end)
  tween:Play()
  return tween
end

function Library:_claimFlag(flag)
  if flag == nil or type(flag) ~= "string" or flag == "" then
    return nil
  end

  if self.Controls[flag] ~= nil then
    local base = flag
    local counter = 1
    while self.Controls[flag] ~= nil do
      counter = counter + 1
      flag = base .. "_" .. tostring(counter)
    end
  end
  return flag
end

function Library:_register(control, flag)
  control.Flag = flag
  if control._refreshAccent then
    self._accentControls[#self._accentControls + 1] = control
  end
  if flag then
    self.Controls[flag] = control
  end
end

Library.Flags = setmetatable({}, {
  __index = function(_, flag)
    local control = Library.Controls[flag]
    return control and control:GetValue() or nil
  end,
  __newindex = function()
    error("Library.Flags is read-only; use Library:SetFlag", 2)
  end,
  __metatable = "locked",
})

Library._accentBindings = {}
Library._tweens = {}
Library._keybinds = {}
Library._accentControls = {}
Library._notifications = {}
Library._tabs = {}
Library._searchEntries = {}
Library._visible = true
Library._scale = 1
Library._destroyed = false

local function themedStroke(instance, token, transparency)
  local stroke = new("UIStroke", {
    ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
    Thickness = 1,
    Transparency = transparency or 0,
    Parent = instance,
  })
  Library:_bind(stroke, "Color", token or "Border")
  return stroke
end

local function themedLabel(properties, token)
  local label = new("TextLabel", properties)
  Library:_bind(label, "TextColor3", token or "Text")
  return label
end

local function tooltipText(info)
  local text = info.Tooltip
  if type(text) ~= "string" or text == "" then
    text = info.Description
  end
  return type(text) == "string" and text ~= "" and text or nil
end

local function rowText(row, info, reservedWidth)
  local name = themedLabel({
    Active = true,
    BackgroundTransparency = 1,
    Position = UDim2.fromOffset(0, 7),
    Size = UDim2.new(1, -(reservedWidth or 0), 0, 18),
    Font = Enum.Font.GothamMedium,
    Text = info.Name or "Control",
    TextSize = 13,
    TextTruncate = Enum.TextTruncate.AtEnd,
    TextXAlignment = Enum.TextXAlignment.Left,
    ZIndex = 17,
    Parent = row,
  })
  local help = tooltipText(info)
  if help then
    Library:_attachTooltip(name, help, row)
  elseif type(info.Name) == "string" then
    local naturalWidth = TextService:GetTextSize(info.Name, 13, Enum.Font.GothamMedium, Vector2.new(1000, 18)).X
    if naturalWidth > math.max(1, 240 - (reservedWidth or 0)) then
      Library:_attachTooltip(name, info.Name, row, function()
        return naturalWidth > name.AbsoluteSize.X / Library._scale
      end)
    end
  end
  return name
end

function Library:_registerSearchEntry(section, frame, info)
  local label = info and info.Name
  if type(label) ~= "string" or label == "" then
    return
  end

  local path = string.format("%s · %s · %s", section.ParentTab.Name, section.Tab.Name, section.Name)
  self._searchEntries[#self._searchEntries + 1] = {
    Label = label,
    SearchText = string.lower(label .. " " .. path),
    Frame = frame,
    Tab = section.ParentTab,
    SubTab = section.Tab,
  }
end

local function makeRow(section, height, info)
  local row = new("Frame", {
    Active = true,
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    Size = UDim2.new(1, 0, 0, height),
    ZIndex = 16,
    Parent = section.Content,
  })
  Library:_registerSearchEntry(section, row, info)
  if section and section._updateSize then
    section:_updateSize()
  end
  return row
end

local function attachCommon(control)
  local function endInteraction()
    Library:_closePopup(control)
    if Library._capturing == control then
      Library:_cancelCapture()
    end
    if Library._sliderDrag and Library._sliderDrag.Control == control then
      Library._sliderDrag = nil
    end
    if Library._colorDrag and Library._colorDrag.Control == control then
      Library._colorDrag = nil
    end

    local focused = UserInputService:GetFocusedTextBox()
    if focused and focused:IsDescendantOf(control.Frame) then
      focused:ReleaseFocus()
    end
    Library:_hideTooltip(control.Frame)
  end

  function control:GetValue()
    return self.Value
  end

  function control:SetVisible(visible)
    visible = visible == true
    if not visible then
      endInteraction()
    end
    self.Frame.Visible = visible
    return true
  end

  function control:SetDisabled(disabled)
    self.Disabled = disabled == true
    if self.Disabled then
      endInteraction()
    end
    if self._render then
      self:_render()
    end
    return true
  end

  return control
end

local function createToggle(section, controlInfo, host, name)
  assert(type(controlInfo) == "table", "AddToggle requires an options table")
  Library:_claimFlag(controlInfo.Flag)

  local frame = host or makeRow(section, Metrics.Row, controlInfo)
  name = name or (not host and rowText(frame, controlInfo, 32) or nil)
  if host and not name then
    Library:_registerSearchEntry(section, section.Frame, controlInfo)
  end

  local checkbox = new("TextButton", {
    Name = "Checkbox",
    AutoButtonColor = false,
    BackgroundColor3 = Library.Theme.SurfaceHover,
    BorderSizePixel = 0,
    Position = host and UDim2.new(0.5, -11, 0.5, -11) or UDim2.new(1, -22, 0.5, -11),
    Size = UDim2.fromOffset(22, 22),
    Text = "",
    ZIndex = 17,
    Parent = frame,
  })
  corner(checkbox, 6)
  if host then
    Library:_attachTooltip(checkbox, tooltipText(controlInfo), frame)
  end

  local checkmark = new("ImageLabel", {
    Name = "Checkmark",
    AnchorPoint = Vector2.new(0.5, 0.5),
    BackgroundTransparency = 1,
    Image = CHECKMARK_IMAGE,
    ImageColor3 = Library.Theme.Text,
    Position = UDim2.fromScale(0.5, 0.5),
    Size = UDim2.fromOffset(16, 16),
    ZIndex = 18,
    Parent = checkbox,
  })

  local control = attachCommon({
    Type = "Toggle",
    Frame = frame,
    Value = controlInfo.Default == true,
    Disabled = false,
    Callback = controlInfo.Callback,
  })

  function control:_render()
    local disabled = self.Disabled
    checkbox.BackgroundColor3 = self.Value and Library.Theme.Accent or Library.Theme.SurfaceHover
    checkbox.BackgroundTransparency = disabled and 0.45 or 0
    checkmark.Visible = self.Value
    checkmark.ImageTransparency = disabled and 0.45 or 0
    if name then
      name.TextTransparency = disabled and 0.45 or 0
    end
  end

  function control:_refreshAccent()
    if self.Value then
      checkbox.BackgroundColor3 = Library.Theme.Accent
    end
  end

  function control:SetValue(value)
    if type(value) ~= "boolean" then
      return false, "toggle value must be a boolean"
    end
    if value == self.Value then
      return true
    end

    self.Value = value
    self:_render()
    safeCallback(self.Callback, value)
    return true
  end

  Library:_connect(checkbox.MouseButton1Click, function()
    if not control.Disabled then
      control:SetValue(not control.Value)
    end
  end)
  Library:_connect(checkbox.MouseEnter, function()
    if not control.Disabled and not control.Value then
      checkbox.BackgroundColor3 = Library.Theme.Border
    end
  end)
  Library:_connect(checkbox.MouseLeave, function()
    control:_render()
  end)

  Library:_register(control, controlInfo.Flag)
  control:_render()
  return control
end

local function createKeybind(section, controlInfo, host)
  if type(controlInfo) ~= "table" then controlInfo = {} end
  controlInfo.Flag = Library:_claimFlag(controlInfo.Flag)

  local allowedModes = {}
  local modeList = controlInfo.Modes or { "Toggle", "Hold", "Always" }
  if type(modeList) ~= "table" or #modeList == 0 then
    modeList = { "Toggle", "Hold", "Always" }
  end
  for _, availableMode in ipairs(modeList) do
    if modes[availableMode] then
      allowedModes[availableMode] = true
    end
  end
  if not next(allowedModes) then
    allowedModes["Toggle"] = true
    modeList = { "Toggle" }
  end

  local allowUnbound = controlInfo.AllowUnbound == true
  local passive = host ~= nil or controlInfo.Passive == true
  local key = controlInfo.Default
  if key == false or (key ~= nil and (typeof(key) ~= "EnumItem" or key.EnumType ~= Enum.KeyCode)) then
    key = nil
  end
  if key == nil and not allowUnbound then
    key = Enum.KeyCode.RightShift
  end
  local mode = controlInfo.Mode or "Toggle"
  if not allowedModes[mode] then
    mode = modeList[1] or "Toggle"
  end

  local frame = host or makeRow(section, Metrics.Row, controlInfo)
  local name = not host and rowText(frame, controlInfo, 52) or nil
  local trigger = new("TextButton", {
    AutoButtonColor = false,
    BackgroundColor3 = Library.Theme.SurfaceHover,
    BorderSizePixel = 0,
    Position = host and UDim2.new(0, 0, 0.5, -12) or UDim2.new(1, -44, 0.5, -12),
    Size = UDim2.fromOffset(host and 36 or 44, 24),
    Font = Enum.Font.GothamMedium,
    Text = key and key.Name or "None",
    TextColor3 = Library.Theme.TextMuted,
    TextSize = 10,
    TextTruncate = Enum.TextTruncate.AtEnd,
    ZIndex = 17,
    Parent = frame,
  })
  corner(trigger, 4)
  Library:_bind(trigger, "BackgroundColor3", "SurfaceHover")
  if host then
    Library:_attachTooltip(trigger, tooltipText(controlInfo), frame)
  end

  local control = attachCommon({
    Type = "Keybind",
    Frame = frame,
    Value = {
      Key = key,
      Mode = mode,
    },
    Modes = cloneArray(modeList),
    AllowedModes = allowedModes,
    AllowUnbound = allowUnbound,
    Passive = passive,
    Disabled = false,
    Callback = controlInfo.Callback,
    ChangedCallback = controlInfo.ChangedCallback,
    _active = false,
    _pressed = false,
  })

  function control:GetState()
    return self._active
  end

  function control:_setActive(active)
    active = active == true
    if self._active == active then
      return
    end
    self._active = active
    self:_render()
    if not self.Passive then
      safeCallback(self.Callback, active)
    end
  end

  function control:_render()
    local capturing = Library._capturing == self
    local popupOpen = Library._popup and Library._popup.Owner == self
    local keyName = self.Value.Key and self.Value.Key.Name or "None"
    trigger.Text = keyName
    trigger.TextColor3 = (self._active or capturing or popupOpen) and Library.Theme.Accent or Library.Theme.TextMuted
    trigger.BackgroundTransparency = self.Disabled and 0.45 or 0
    trigger.TextTransparency = self.Disabled and 0.45 or 0
    if name then
      name.TextTransparency = self.Disabled and 0.45 or 0
    end

    local captureButton = self._captureButton
    if captureButton then
      captureButton.Text = capturing and "Press a key..." or keyName
      captureButton.TextColor3 = capturing and Library.Theme.Accent or Library.Theme.Text
      self._captureStroke.Color = capturing and Library.Theme.Accent or Library.Theme.Border
    end
    if self._modeButtons then
      for availableMode, button in pairs(self._modeButtons) do
        local selected = availableMode == self.Value.Mode
        button.BackgroundColor3 = selected and Library.Theme.SurfaceHover or Library.Theme.Control
        button.TextColor3 = selected and Library.Theme.Accent or Library.Theme.TextMuted
      end
    end
  end

  function control:_refreshAccent()
    self:_render()
  end

  function control:SetValue(value)
    if type(value) ~= "table" then
      return false, "keybind value must contain Key and Mode"
    end

    local nextKey = value.Key
    local nextMode = value.Mode
    if nextKey == nil then
      if not self.AllowUnbound then
        return false, "keybind Key cannot be nil unless AllowUnbound is enabled"
      end
    elseif typeof(nextKey) ~= "EnumItem" or nextKey.EnumType ~= Enum.KeyCode then
      return false, "keybind Key must be an Enum.KeyCode or nil"
    end
    if not self.AllowedModes[nextMode] then
      return false, "keybind Mode is not allowed"
    end

    local old = self.Value
    local keyChanged = old.Key ~= nextKey
    local modeChanged = old.Mode ~= nextMode
    if not keyChanged and not modeChanged then
      return true
    end

    local oldActive = self._active
    local nextActive = oldActive
    if self.Passive then
      nextActive = false
    elseif modeChanged then
      nextActive = not self.Disabled and nextMode == "Always"
    elseif keyChanged and old.Mode == "Hold" then
      nextActive = false
    end

    self._pressed = false
    self.Value = {
      Key = nextKey,
      Mode = nextMode,
    }
    self._active = nextActive
    self:_render()
    safeCallback(self.ChangedCallback, nextKey, nextMode)
    if not self.Passive and nextActive ~= oldActive then
      safeCallback(self.Callback, nextActive)
    end
    return true
  end

  function control:SetKey(nextKey)
    return self:SetValue({
      Key = nextKey,
      Mode = self.Value.Mode,
    })
  end

  function control:SetMode(nextMode)
    return self:SetValue({
      Key = self.Value.Key,
      Mode = nextMode,
    })
  end

  function control:SetDisabled(disabled)
    disabled = disabled == true
    if disabled == self.Disabled then
      return true
    end

    self.Disabled = disabled
    if disabled then
      self._pressed = false
      Library:_hideTooltip(self.Frame)
      if Library._capturing == self then
        Library:_cancelCapture()
      end
      Library:_closePopup(self)
      self:_setActive(false)
    elseif not self.Passive and self.Value.Mode == "Always" then
      self:_setActive(true)
    else
      self:_render()
    end
    return true
  end

  function control:_inputBegan()
    if self.Passive or self._pressed then
      return
    end
    self._pressed = true

    local currentMode = self.Value.Mode
    if currentMode == "Toggle" then
      self:_setActive(not self._active)
    elseif currentMode == "Hold" then
      self:_setActive(true)
    end
  end

  function control:_inputEnded()
    if self.Passive or not self._pressed then
      return
    end
    self._pressed = false

    if self.Value.Mode == "Hold" then
      self:_setActive(false)
    end
  end

  function control:_popupClosed()
    if Library._capturing == self then
      Library:_cancelCapture()
    end
    self._captureButton = nil
    self._captureStroke = nil
    self._modeButtons = nil
    self:_render()
  end

  function control:_openEditor()
    local showModes = #self.Modes > 1
    local popup = new("Frame", {
      BackgroundColor3 = Library.Theme.Surface,
      BorderSizePixel = 0,
      Size = UDim2.fromOffset(176, showModes and 116 or 67),
      ZIndex = 101,
    })
    corner(popup, 6)
    themedStroke(popup, "Border", 0.35)
    Library:_bind(popup, "BackgroundColor3", "Surface")

    themedLabel({
      BackgroundTransparency = 1,
      Position = UDim2.fromOffset(10, 6),
      Size = UDim2.new(1, -20, 0, 18),
      Font = Enum.Font.GothamMedium,
      Text = controlInfo.PopupTitle or controlInfo.Name or "Keybind",
      TextSize = 12,
      TextTruncate = Enum.TextTruncate.AtEnd,
      TextXAlignment = Enum.TextXAlignment.Left,
      ZIndex = 102,
      Parent = popup,
    })

    local captureButton = new("TextButton", {
      AutoButtonColor = false,
      BackgroundColor3 = Library.Theme.Control,
      BorderSizePixel = 0,
      Position = UDim2.fromOffset(10, 29),
      Size = UDim2.new(1, -20, 0, 28),
      Font = Enum.Font.GothamMedium,
      Text = "",
      TextColor3 = Library.Theme.Text,
      TextSize = 11,
      TextTruncate = Enum.TextTruncate.AtEnd,
      ZIndex = 102,
      Parent = popup,
    })
    corner(captureButton, 4)
    local captureStroke = themedStroke(captureButton, "Border", 0.35)
    Library:_bind(captureButton, "BackgroundColor3", "Control")

    if showModes then
      themedLabel({
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(10, 63),
        Size = UDim2.new(1, -20, 0, 14),
        Font = Enum.Font.Gotham,
        Text = "Activation mode",
        TextSize = 10,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 102,
        Parent = popup,
      }, "TextMuted")

      local modeHolder = new("Frame", {
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(10, 82),
        Size = UDim2.new(1, -20, 0, 25),
        ZIndex = 102,
        Parent = popup,
      })
      local gap = 4
      local modeWidth = (156 - gap * (#self.Modes - 1)) / #self.Modes
      self._modeButtons = {}
      for index, availableMode in ipairs(self.Modes) do
        local option = new("TextButton", {
          AutoButtonColor = false,
          BackgroundColor3 = Library.Theme.Control,
          BorderSizePixel = 0,
          Position = UDim2.fromOffset((index - 1) * (modeWidth + gap), 0),
          Size = UDim2.fromOffset(modeWidth, 25),
          Font = Enum.Font.GothamMedium,
          Text = availableMode,
          TextColor3 = Library.Theme.TextMuted,
          TextSize = 10,
          TextTruncate = Enum.TextTruncate.AtEnd,
          ZIndex = 103,
          Parent = modeHolder,
        })
        corner(option, 4)
        self._modeButtons[availableMode] = option
        Library:_connect(option.Activated, function()
          if not self.Disabled then
            self:SetMode(availableMode)
          end
        end)
      end
    end

    self._captureButton = captureButton
    self._captureStroke = captureStroke
    Library:_connect(captureButton.Activated, function()
      if self.Disabled then
        return
      end
      if Library._capturing == self then
        Library:_cancelCapture()
      else
        Library:_beginCapture(self, true)
      end
    end)

    Library:_openPopup(self, popup, trigger)
    self:_render()
  end

  Library:_connect(trigger.Activated, function()
    if control.Disabled then
      return
    end
    if Library._popup and Library._popup.Owner == control then
      Library:_closePopup(control)
    else
      control:_openEditor()
    end
  end)

  if not passive then
    Library._keybinds[#Library._keybinds + 1] = control
  end
  Library:_register(control, controlInfo.Flag)
  control:_render()
  if not passive and mode == "Always" then
    control:_setActive(true)
  end
  return control
end

function Library:_closePopup(owner)
  local popup = self._popup
  if not popup or owner and popup.Owner ~= owner then
    return
  end

  self._popup = nil
  self._colorDrag = nil
  if popup.Owner and popup.Owner._popupClosed then
    popup.Owner:_popupClosed()
  end
  if popup.Frame then
    popup.Frame:Destroy()
  end
  self:_pruneRegistries()
end

function Library:_placePopup(frame, anchor)
  local overlayPosition = self._overlay.AbsolutePosition
  local overlaySize = self._overlay.AbsoluteSize
  local anchorPosition = anchor.AbsolutePosition
  local anchorSize = anchor.AbsoluteSize
  local popupSize = frame.AbsoluteSize
  if popupSize.X == 0 or popupSize.Y == 0 then
    popupSize = Vector2.new(frame.Size.X.Offset, frame.Size.Y.Offset)
  end

  local x = anchorPosition.X
  local y = anchorPosition.Y + anchorSize.Y + 5
  local right = overlayPosition.X + overlaySize.X - 8
  local bottom = overlayPosition.Y + overlaySize.Y - 8
  if y + popupSize.Y > bottom then
    y = anchorPosition.Y - popupSize.Y - 5
  end

  x = math.clamp(x, overlayPosition.X + 8, math.max(overlayPosition.X + 8, right - popupSize.X))
  y = math.clamp(y, overlayPosition.Y + 8, math.max(overlayPosition.Y + 8, bottom - popupSize.Y))
  frame.Position = UDim2.fromOffset(x - overlayPosition.X, y - overlayPosition.Y)
end

function Library:_ensureTooltip()
  if self._tooltipFrame then
    return
  end

  local frame = new("Frame", {
    Name = "Tooltip",
    BackgroundColor3 = self.Theme.SurfaceHover,
    BorderSizePixel = 0,
    Size = UDim2.fromOffset(0, 0),
    Visible = false,
    ZIndex = 160,
    Parent = self._overlay,
  })
  corner(frame, 4)
  themedStroke(frame, "Border", 0.25)
  self:_bind(frame, "BackgroundColor3", "SurfaceHover")
  self._tooltipScale = new("UIScale", {
    Scale = self._scale,
    Parent = frame,
  })

  local label = themedLabel({
    BackgroundTransparency = 1,
    Position = UDim2.fromOffset(8, 5),
    Size = UDim2.fromOffset(0, 0),
    Font = Enum.Font.Gotham,
    Text = "",
    TextSize = 13,
    TextWrapped = true,
    TextXAlignment = Enum.TextXAlignment.Left,
    TextYAlignment = Enum.TextYAlignment.Top,
    ZIndex = 161,
    Parent = frame,
  })

  self._tooltipFrame = frame
  self._tooltipLabel = label
end

function Library:_positionTooltip(point)
  local frame = self._tooltipFrame
  if not frame or not frame.Visible then
    return
  end

  local overlayPosition = self._overlay.AbsolutePosition
  local overlaySize = self._overlay.AbsoluteSize
  local size = frame.AbsoluteSize
  local x = point.X + 15
  local y = point.Y + 12
  local right = overlayPosition.X + overlaySize.X - 8
  local bottom = overlayPosition.Y + overlaySize.Y - 8

  if x + size.X > right then
    x = point.X - size.X - 12
  end
  if y + size.Y > bottom then
    y = point.Y - size.Y - 12
  end

  x = math.clamp(x, overlayPosition.X + 8, math.max(overlayPosition.X + 8, right - size.X))
  y = math.clamp(y, overlayPosition.Y + 8, math.max(overlayPosition.Y + 8, bottom - size.Y))
  frame.Position = UDim2.fromOffset(x - overlayPosition.X, y - overlayPosition.Y)
end

function Library:_showTooltip(owner, text)
  if not text or self._popup or self._capturing or self._dragging or not self._visible then
    return
  end

  self:_ensureTooltip()
  local bounds = TextService:GetTextSize(text, 13, Enum.Font.Gotham, Vector2.new(240, 1000))
  local width = math.min(240, math.max(1, bounds.X))
  self._tooltipLabel.Text = text
  self._tooltipLabel.Size = UDim2.fromOffset(width, bounds.Y)
  self._tooltipFrame.Size = UDim2.fromOffset(width + 16, bounds.Y + 10)
  self._tooltipOwner = owner
  self._tooltipFrame.Visible = true
  self:_positionTooltip(UserInputService:GetMouseLocation())
end

function Library:_hideTooltip(owner)
  if owner and self._tooltipOwner ~= owner then
    return
  end
  self._tooltipOwner = nil
  if self._tooltipFrame then
    self._tooltipFrame.Visible = false
  end
end

function Library:_attachTooltip(trigger, text, owner, shouldShow)
  if not text then
    return
  end
  owner = owner or trigger

  self:_connect(trigger.MouseEnter, function()
    if not shouldShow or shouldShow() then
      self:_showTooltip(owner, text)
    end
  end)
  self:_connect(trigger.MouseLeave, function()
    self:_hideTooltip(owner)
  end)
end

function Library:_querySearch(query)
  query = string.match(string.lower(query), "^%s*(.-)%s*$")
  if not string.find(query, "%S") then
    return {}
  end

  local results = {}
  for _, entry in ipairs(self._searchEntries) do
    if string.find(entry.SearchText, query, 1, true) then
      results[#results + 1] = entry
      if #results == 6 then
        break
      end
    end
  end
  return results
end

function Library:_styleSearchResults()
  local search = self._search
  if not search then
    return
  end

  for index, row in ipairs(search.Rows) do
    local selected = index == search.ActiveIndex
    row.BackgroundTransparency = selected and 0 or 1
    row.TextColor3 = selected and self.Theme.Text or self.Theme.TextMuted
  end
end

function Library:_clearSearchHighlight()
  local tween = self._searchHighlightTween
  local highlight = self._searchHighlightFrame
  self._searchHighlightTween = nil
  self._searchHighlightFrame = nil

  if tween then
    tween:Cancel()
  end
  if highlight and highlight.Parent then
    highlight:Destroy()
  end
end

function Library:_showSearchResults(query)
  local search = self._search
  if not search then
    return
  end
  if not string.find(query, "%S") then
    self:_closePopup(search)
    return
  end

  local results = self:_querySearch(query)
  self:_closePopup()

  local rowCount = math.max(1, #results)
  local width = math.max(190, search.Box.AbsoluteSize.X / self._scale)
  local popup = new("Frame", {
    BackgroundColor3 = self.Theme.Surface,
    BorderSizePixel = 0,
    Size = UDim2.fromOffset(width, rowCount * 30 + 10),
    ZIndex = 101,
  })
  corner(popup, 5)
  themedStroke(popup, "Border", 0.65)
  self:_bind(popup, "BackgroundColor3", "Surface")

  local holder = new("Frame", {
    BackgroundTransparency = 1,
    Position = UDim2.fromOffset(5, 5),
    Size = UDim2.new(1, -10, 1, -10),
    ZIndex = 102,
    Parent = popup,
  })
  list(holder, 0)

  search.Results = results
  search.Rows = {}
  search.ActiveIndex = #results > 0 and 1 or 0

  if #results == 0 then
    themedLabel({
      BackgroundTransparency = 1,
      Size = UDim2.new(1, 0, 0, 30),
      Font = Enum.Font.Gotham,
      Text = "No matches",
      TextSize = 11,
      ZIndex = 103,
      Parent = holder,
    }, "TextMuted")
  else
    for index, entry in ipairs(results) do
      local result = entry
      local row = new("TextButton", {
        AutoButtonColor = false,
        BackgroundColor3 = self.Theme.SurfaceHover,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, 30),
        Font = Enum.Font.Gotham,
        Text = result.Label,
        TextColor3 = self.Theme.TextMuted,
        TextSize = 11,
        TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 103,
        Parent = holder,
      })
      corner(row, 4)
      padding(row, 8, 8, 0, 0)
      search.Rows[index] = row

      self:_connect(row.MouseEnter, function()
        search.ActiveIndex = index
        self:_styleSearchResults()
      end)
      self:_connect(row.MouseButton1Click, function()
        self:_activateSearchEntry(result)
      end)
    end
  end

  self:_openPopup(search, popup, search.Box)
  self:_styleSearchResults()
end

function Library:_activateSearchEntry(entry)
  local search = self._search
  if not search then
    return
  end

  self:_closePopup(search)
  search.Box.Text = ""
  search.Box:ReleaseFocus()
  self:_selectTab(entry.Tab)
  entry.Tab:_selectSubTab(entry.SubTab)

  task.defer(function()
    if self._destroyed or not entry.Frame.Parent then
      return
    end

    local scroll = entry.SubTab.Scroll
    local y = scroll.CanvasPosition.Y + entry.Frame.AbsolutePosition.Y - scroll.AbsolutePosition.Y - 8
    scroll.CanvasPosition = Vector2.new(0, math.max(0, y))

    self:_clearSearchHighlight()

    local highlight = new("Frame", {
      Name = "SearchHighlight",
      Active = false,
      BackgroundColor3 = self.Theme.Accent,
      BackgroundTransparency = 0.84,
      BorderSizePixel = 0,
      Position = UDim2.fromOffset(-6, 0),
      Size = UDim2.new(1, 12, 1, 0),
      ZIndex = 19,
      Parent = entry.Frame,
    })
    corner(highlight, 4)
    self._searchHighlightFrame = highlight
    local tween
    tween = self:_tween(highlight, { BackgroundTransparency = 1 }, function()
      if self._searchHighlightTween == tween then
        self._searchHighlightTween = nil
        self._searchHighlightFrame = nil
        if highlight.Parent then
          highlight:Destroy()
        end
      end
    end, searchHighlightTweenInfo)
    self._searchHighlightTween = tween
  end)
end

function Library:_handleSearchInput(input)
  local search = self._search
  if not search or not search.Box:IsFocused() or input.UserInputType ~= Enum.UserInputType.Keyboard then
    return false
  end

  local key = input.KeyCode
  if key == Enum.KeyCode.Escape then
    self:_closePopup(search)
    search.Box.Text = ""
    search.Box:ReleaseFocus()
    return true
  end

  if not self._popup or self._popup.Owner ~= search then
    return false
  end

  local count = #search.Results
  if key == Enum.KeyCode.Down and count > 0 then
    search.ActiveIndex = search.ActiveIndex >= count and 1 or search.ActiveIndex + 1
  elseif key == Enum.KeyCode.Up and count > 0 then
    search.ActiveIndex = search.ActiveIndex <= 1 and count or search.ActiveIndex - 1
  elseif key == Enum.KeyCode.Return or key == Enum.KeyCode.KeypadEnter then
    local entry = search.Results[search.ActiveIndex]
    if entry then
      self:_activateSearchEntry(entry)
    end
    return true
  else
    return false
  end

  self:_styleSearchResults()
  return true
end

function Library:_openPopup(owner, frame, anchor)
  self:_closePopup()
  self:_cancelCapture()
  self:_hideTooltip()
  new("UIScale", {
    Scale = self._scale,
    Parent = frame,
  })
  frame.Parent = self._overlay
  self._popup = {
    Owner = owner,
    Frame = frame,
    Anchor = anchor,
  }
  self:_placePopup(frame, anchor)
end

function Library:_cancelCapture()
  local control = self._capturing
  if not control then
    return
  end

  self._capturing = nil
  control:_render()
end

function Library:_beginCapture(control, keepPopup)
  if not keepPopup or not self._popup or self._popup.Owner ~= control then
    self:_closePopup()
  end
  self:_cancelCapture()
  self:_hideTooltip()
  self._capturing = control
  control:_render()
end

function Library:IsCapturingKeybind()
  return not self._destroyed and (self._capturing ~= nil or self._capturedInput == true)
end

function Library:_dispatchBegan(input, processed)
  local pointerInput = input.UserInputType == Enum.UserInputType.MouseButton1
    or input.UserInputType == Enum.UserInputType.Touch
  if pointerInput and self._popup then
    local point = input.Position
    if not inside(self._popup.Frame, point) and not inside(self._popup.Anchor, point) then
      self:_closePopup()
    end
  end

  local capture = self._capturing
  if capture then
    if input.UserInputType ~= Enum.UserInputType.Keyboard then
      return
    end

    self._capturedInput = true
    task.defer(function()
      if not self._destroyed then
        self._capturedInput = false
      end
    end)

    if input.KeyCode == Enum.KeyCode.Escape then
      self:_cancelCapture()
      return
    end

    if capture.AllowUnbound and (input.KeyCode == Enum.KeyCode.Backspace or input.KeyCode == Enum.KeyCode.Delete) then
      self._capturing = nil
      capture:SetKey(nil)
      capture:_render()
    elseif input.KeyCode ~= Enum.KeyCode.Unknown then
      self._capturing = nil
      capture:SetKey(input.KeyCode)
      capture:_render()
    end
    return
  end

  if self._popup and input.KeyCode == Enum.KeyCode.Escape then
    self:_closePopup()
    return
  end

  if self:_handleSearchInput(input) then
    return
  end

  if processed or UserInputService:GetFocusedTextBox() then
    return
  end

  if input.UserInputType == Enum.UserInputType.Keyboard then
    for _, control in ipairs(self._keybinds) do
      if not control.Disabled and input.KeyCode == control.Value.Key then
        control:_inputBegan()
      end
    end
  end
end

function Library:_dispatchChanged(input)
  local inputType = input.UserInputType
  if inputType ~= Enum.UserInputType.MouseMovement and inputType ~= Enum.UserInputType.Touch then
    return
  end

  if self._tooltipFrame and self._tooltipFrame.Visible then
    self:_positionTooltip(input.Position)
  end

  local sliderDrag = self._sliderDrag
  if sliderDrag then
    local isMouseDrag = sliderDrag.Input.UserInputType == Enum.UserInputType.MouseButton1
      and inputType == Enum.UserInputType.MouseMovement
    if isMouseDrag or sliderDrag.Input == input then
      sliderDrag.Control:_setFromPosition(input.Position.X)
    end
  elseif self._colorDrag then
    self._colorDrag.Control:_setFromPicker(self._colorDrag.Mode, input.Position)
  elseif self._dragging then
    self:_dragWindow(input.Position)
  end
end

function Library:_dispatchEnded(input)
  if input.UserInputType == Enum.UserInputType.MouseButton1 then
    self._sliderDrag = nil
    self._colorDrag = nil
    self._dragging = nil
  end

  if self._sliderDrag and self._sliderDrag.Input == input then
    self._sliderDrag = nil
  end

  if input.UserInputType == Enum.UserInputType.Keyboard then
    for _, control in ipairs(self._keybinds) do
      if not control.Disabled and input.KeyCode == control.Value.Key then
        control:_inputEnded()
      end
    end
  end
end

function Library:_startDrag(input)
  self:_closePopup()
  self:_cancelCapture()
  self:_hideTooltip()
  self._dragging = {
    Pointer = input.Position,
    Position = self._main.Position,
  }
end

function Library:_dragWindow(pointer)
  local drag = self._dragging
  if not drag then
    return
  end

  local delta = pointer - drag.Pointer
  self._main.Position = UDim2.new(
    drag.Position.X.Scale,
    drag.Position.X.Offset + delta.X,
    drag.Position.Y.Scale,
    drag.Position.Y.Offset + delta.Y
  )
end

function Library:_selectTab(tab)
  self:_hideTooltip()
  for _, other in ipairs(self._tabs) do
    local selected = other == tab
    other.Page.Visible = selected
    other.Button.BackgroundColor3 = selected and self.Theme.Control or self.Theme.SurfaceHover
    other.Button.BackgroundTransparency = selected and 0 or 1
    other.Button.TextColor3 = selected and self.Theme.Text or self.Theme.TextSecondary
  end
  self._selectedTab = tab
  if tab then
    local targetSubTab = tab.SelectedSubTab or tab.DefaultSubTab or (tab.SubTabs and tab.SubTabs[1])
    if targetSubTab and tab._selectSubTab then
      tab:_selectSubTab(targetSubTab)
    elseif targetSubTab and targetSubTab._updateLayout then
      targetSubTab:_updateLayout()
    end
  end
end

function Library:CreateWindow(info)
  assert(not self._destroyed, "Library has been unloaded")
  assert(not self._root, "KatalystUI supports one window per library instance")
  info = info or {}

  local size = typeof(info.Size) == "UDim2" and info.Size or UDim2.fromOffset(Metrics.Window.X, Metrics.Window.Y)
  local root = new("ScreenGui", {
    Name = "KatalystUI",
    IgnoreGuiInset = true,
    ResetOnSpawn = false,
    DisplayOrder = 120,
    ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
  })

  protectGui(root)

  local parent = guiParent()
  local parented = pcall(function()
    root.Parent = parent
  end)
  if not parented then
    root.Parent = Players.LocalPlayer:WaitForChild("PlayerGui")
  end

  self._root = root
  self._overlay = new("Frame", {
    Name = "PopupLayer",
    BackgroundTransparency = 1,
    BorderSizePixel = 0,
    Size = UDim2.fromScale(1, 1),
    ZIndex = 100,
    Parent = root,
  })

  local main = new("Frame", {
    Name = "Window",
    AnchorPoint = Vector2.new(0.5, 0.5),
    BackgroundColor3 = self.Theme.Background,
    BorderSizePixel = 0,
    Position = UDim2.fromScale(0.5, 0.5),
    Size = size,
    Visible = false,
    ZIndex = 10,
    Parent = root,
  })
  corner(main, 7)
  self._mainStroke = themedStroke(main, "Border", WINDOW_STROKE_TRANSPARENCY)
  self._main = main
  self:_bind(main, "BackgroundColor3", "Background")

  self._uiScale = new("UIScale", {
    Scale = self._scale,
    Parent = main,
  })

  local function attachDragHandle(handle)
    self:_connect(handle.InputBegan, function(input)
      if input.UserInputType == Enum.UserInputType.MouseButton1 then
        self:_startDrag(input)
      end
    end)
  end

  local sidebar = new("Frame", {
    Name = "Sidebar",
    BackgroundColor3 = self.Theme.Sidebar,
    BorderSizePixel = 0,
    Size = UDim2.new(0, Metrics.Sidebar, 1, -Metrics.Footer),
    ZIndex = 11,
    Parent = main,
  })
  self:_bind(sidebar, "BackgroundColor3", "Sidebar")
  corner(sidebar, 7)

  new("Frame", {
    BackgroundColor3 = self.Theme.Sidebar,
