    ZIndex = 12,
    Parent = sidebar,
  })
  attachDragHandle(sidebarDragArea)

  local logo = info.Logo
  if type(logo) == "table" and type(logo.Image) == "string" and logo.Image ~= "" then
    new("ImageLabel", {
      Name = "Logo",
      Active = false,
      BackgroundTransparency = 1,
      Image = logo.Image,
      ImageColor3 = typeof(logo.Color) == "Color3" and logo.Color or Color3.new(1, 1, 1),
      ImageTransparency = 0,
      ImageRectOffset = typeof(logo.RectOffset) == "Vector2" and logo.RectOffset or Vector2.zero,
      ImageRectSize = typeof(logo.RectSize) == "Vector2" and logo.RectSize or Vector2.zero,
      Position = typeof(logo.Position) == "UDim2" and logo.Position or UDim2.fromOffset(32, 14),
      Size = typeof(logo.Size) == "UDim2" and logo.Size or UDim2.fromOffset(88, 30),
      ScaleType = Enum.ScaleType.Fit,
      ZIndex = 13,
      Parent = sidebarDragArea,
    })
  else
    themedLabel({
      BackgroundTransparency = 1,
      Position = UDim2.fromOffset(18, 17),
      Size = UDim2.new(1, -36, 0, 24),
      Font = Enum.Font.GothamBold,
      Text = string.upper(info.Title or "Katalyst"),
      TextSize = 17,
      TextXAlignment = Enum.TextXAlignment.Left,
      ZIndex = 13,
      Parent = sidebarDragArea,
    })
