  }, "TextSecondary")

  themedLabel({
    BackgroundTransparency = 1,
    Position = UDim2.new(0.6, 0, 0, 1),
    Size = UDim2.new(0.4, -12, 1, -1),
    Font = Enum.Font.GothamMedium,
    Text = tostring(info.FooterStatus or "Made by Adam & Juno"),
    TextSize = 10,
