    BackgroundTransparency = 1,
    Position = UDim2.new(1, -12, 0, 12),
    Size = UDim2.fromOffset(270, 360),
    ZIndex = 200,
    Parent = root,
  })
  self._notificationScale = new("UIScale", {
    Scale = self._scale,
    Parent = notificationHost,
  })
  local notificationLayout = list(notificationHost, 6)
  notificationLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
  self._notificationHost = notificationHost

  self:_connect(UserInputService.InputBegan, function(input, processed)
    self:_dispatchBegan(input, processed)
  end)
  self:_connect(UserInputService.InputChanged, function(input)
    self:_dispatchChanged(input)
  end)
  self:_connect(UserInputService.InputEnded, function(input)
    self:_dispatchEnded(input)
  end)

  local Window = {
    Library = self,
    Frame = main,
  }
  self.Window = Window

  function Window:AddCategory(name)
    name = tostring(name or "Category")
    if name == "" then name = "Category" end
    local label = themedLabel({
      BackgroundTransparency = 1,
      Size = UDim2.new(1, 0, 0, 22),
      Font = Enum.Font.GothamMedium,
      Text = name,
      TextSize = 11,
      TextXAlignment = Enum.TextXAlignment.Left,
      ZIndex = 13,
      Parent = Library._sidebarList,
    }, "TextMuted")
    padding(label, 8, 4, 7, 0)
    return label
  end

  function Window:AddTab(tabInfo)
    if type(tabInfo) == "string" then
      tabInfo = {
        Name = tabInfo,
      }
    elseif type(tabInfo) ~= "table" then
      tabInfo = {
        Name = "Tab",
      }
    end
    tabInfo.Name = tostring(tabInfo.Name or "Tab")
    if tabInfo.Name == "" then tabInfo.Name = "Tab" end

    local button = new("TextButton", {
      AutoButtonColor = false,
      BackgroundColor3 = Library.Theme.Control,
      BackgroundTransparency = 1,
      BorderSizePixel = 0,
      Size = UDim2.new(1, 0, 0, 32),
      Font = Enum.Font.GothamMedium,
      Text = tabInfo.Name,
      TextColor3 = Library.Theme.TextSecondary,
      TextSize = 13,
      TextXAlignment = Enum.TextXAlignment.Left,
      ZIndex = 13,
      Parent = Library._sidebarList,
    })
    corner(button, 5)
    padding(button, 8, 8, 0, 0)

    local page = new("Frame", {
      Name = tabInfo.Name,
      BackgroundTransparency = 1,
      Size = UDim2.fromScale(1, 1),
      Visible = false,
      ZIndex = 12,
      Parent = Library._pageHost,
