      Text = tabInfo.Name,
      TextSize = 22,
      TextXAlignment = Enum.TextXAlignment.Left,
      ZIndex = 13,
      Parent = page,
    })

    local subTabBar = new("ScrollingFrame", {
      Name = "SubTabBar",
      Active = true,
      BackgroundTransparency = 1,
      BorderSizePixel = 0,
      CanvasSize = UDim2.fromOffset(0, 0),
      Position = UDim2.fromOffset(Metrics.Padding, 50),
      ScrollBarThickness = 0,
      ScrollingDirection = Enum.ScrollingDirection.X,
      Size = UDim2.new(1, -Metrics.Padding * 2, 0, 30),
      ZIndex = 13,
      Parent = page,
    })
    local subTabLayout = list(subTabBar, 4, true)
    subTabLayout.VerticalAlignment = Enum.VerticalAlignment.Center

    local subPageHost = new("Frame", {
      Name = "SubPageHost",
      BackgroundTransparency = 1,
      Position = UDim2.fromOffset(Metrics.Padding, Metrics.ContentTop),
      Size = UDim2.new(1, -Metrics.Padding, 1, -Metrics.ContentTop - Metrics.Padding),
      ZIndex = 13,
      Parent = page,
    })
    local pageScrollbarGutter = Metrics.Padding + 6

    local Tab = {
      Name = tabInfo.Name,
      Button = button,
      Page = page,
      SubTabBar = subTabBar,
      SubTabLayout = subTabLayout,
      SubPageHost = subPageHost,
      SubTabs = {},
    }

    local function createSubPage(name)
      local scroll = new("ScrollingFrame", {
        Name = "PageScroll",
        Active = true,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        CanvasSize = UDim2.fromOffset(0, 0),
        ScrollBarImageColor3 = Library.Theme.Border,
        ScrollBarThickness = 3,
        Size = UDim2.fromScale(1, 1),
        Visible = false,
        ZIndex = 13,
        Parent = subPageHost,
      })
      Library:_bind(scroll, "ScrollBarImageColor3", "Border")

      local columns = new("Frame", {
        Name = "PageCanvas",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, -pageScrollbarGutter, 0, 0),
        ZIndex = 14,
        Parent = scroll,
      })

      local left = new("Frame", {
        Name = "LeftColumn",
        BackgroundTransparency = 1,
        Size = UDim2.new(0.5, -Metrics.Gap / 2, 0, 0),
        ZIndex = 14,
        Parent = columns,
      })
      local leftLayout = list(left, Metrics.Gap)

      local right = new("Frame", {
        Name = "RightColumn",
        BackgroundTransparency = 1,
        Position = UDim2.new(0.5, Metrics.Gap / 2, 0, 0),
        Size = UDim2.new(0.5, -Metrics.Gap / 2, 0, 0),
        ZIndex = 14,
        Parent = columns,
      })
      local rightLayout = list(right, Metrics.Gap)

      local full = new("Frame", {
        Name = "FullColumn",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 0),
        ZIndex = 14,
        Parent = columns,
      })
      local fullLayout = list(full, Metrics.Gap)

      local subTab = {
        Name = name,
        Scroll = scroll,
        Columns = columns,
        Left = left,
        Right = right,
        Full = full,
        LeftLayout = leftLayout,
        RightLayout = rightLayout,
        FullLayout = fullLayout,
      }

      function subTab:_updateLayout()
        local scale = Library._scale or 1
        local manualLeft = 0
        if self.Left then
          for _, child in ipairs(self.Left:GetChildren()) do
            if child:IsA("GuiObject") and child.Visible ~= false then
              manualLeft = manualLeft + child.Size.Y.Offset + Metrics.Gap
            end
          end
        end
        local manualRight = 0
        if self.Right then
          for _, child in ipairs(self.Right:GetChildren()) do
            if child:IsA("GuiObject") and child.Visible ~= false then
              manualRight = manualRight + child.Size.Y.Offset + Metrics.Gap
            end
          end
        end
        local manualFull = 0
        if self.Full then
          for _, child in ipairs(self.Full:GetChildren()) do
            if child:IsA("GuiObject") and child.Visible ~= false then
              manualFull = manualFull + child.Size.Y.Offset + Metrics.Gap
            end
          end
        end

        local layoutLeft = (self.LeftLayout and self.LeftLayout.AbsoluteContentSize and self.LeftLayout.AbsoluteContentSize.Y or 0) / scale
        local layoutRight = (self.RightLayout and self.RightLayout.AbsoluteContentSize and self.RightLayout.AbsoluteContentSize.Y or 0) / scale
        local layoutFull = (self.FullLayout and self.FullLayout.AbsoluteContentSize and self.FullLayout.AbsoluteContentSize.Y or 0) / scale

        local leftHeight = math.max(layoutLeft, manualLeft)
        local rightHeight = math.max(layoutRight, manualRight)
        local columnHeight = math.max(leftHeight, rightHeight)
        local fullHeight = math.max(layoutFull, manualFull)
        local columnGap = columnHeight > 0 and fullHeight > 0 and Metrics.Gap or 0

        self.Left.Size = UDim2.new(0.5, -Metrics.Gap / 2, 0, leftHeight)
        self.Right.Size = UDim2.new(0.5, -Metrics.Gap / 2, 0, rightHeight)
        self.Full.Position = UDim2.fromOffset(0, columnHeight + columnGap)
        self.Full.Size = UDim2.new(1, 0, 0, fullHeight)

        local height = math.max(columnHeight + columnGap + fullHeight, 100)
        self.Columns.Size = UDim2.new(1, -pageScrollbarGutter, 0, height)
        self.Scroll.CanvasSize = UDim2.fromOffset(0, height + 20)
      end

      if leftLayout then
        Library:_connect(leftLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
          subTab:_updateLayout()
        end)
      end
      if rightLayout then
        Library:_connect(rightLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
          subTab:_updateLayout()
        end)
      end
      if fullLayout then
        Library:_connect(fullLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
          subTab:_updateLayout()
        end)
      end
      Library:_connect(scroll:GetPropertyChangedSignal("CanvasPosition"), function()
        Library:_closePopup()
        Library:_hideTooltip()
      end)

      return subTab
    end

    Library:_connect(button.MouseButton1Click, function()
      Library:_closePopup()
      Library:_cancelCapture()
      Library:_selectTab(Tab)
    end)
    Library:_connect(button.MouseEnter, function()
      if Library._selectedTab ~= Tab then
        button.BackgroundTransparency = 0
        button.BackgroundColor3 = Library.Theme.SurfaceHover
      end
    end)
    Library:_connect(button.MouseLeave, function()
      if Library._selectedTab ~= Tab then
        button.BackgroundTransparency = 1
      end
    end)

    Library._tabs[#Library._tabs + 1] = Tab
    if not Library._selectedTab then
      Library:_selectTab(Tab)
    end

    local function addSection(self, sectionInfo)
      if type(sectionInfo) == "string" then
        sectionInfo = { Name = sectionInfo }
      elseif type(sectionInfo) ~= "table" then
        sectionInfo = { Name = "Section" }
      end
      sectionInfo.Name = tostring(sectionInfo.Name or "Section")
      local side = sectionInfo.Side or "Left"
      if side ~= "Left" and side ~= "Right" and side ~= "Full" then
        side = "Left"
      end

      local parentFrame = side == "Left" and self.Left or side == "Right" and self.Right or self.Full
      local frame = new("Frame", {
        BackgroundColor3 = Library.Theme.Surface,
        BorderSizePixel = 0,
        ClipsDescendants = false,
        Size = UDim2.new(1, 0, 0, 60),
        ZIndex = 15,
        Parent = parentFrame,
      })
      corner(frame, Metrics.Radius)
      themedStroke(frame, "Border", 0.78)
      Library:_bind(frame, "BackgroundColor3", "Surface")

      local headerSurface = new("Frame", {
        BackgroundColor3 = Library.Theme.Control,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(1, 1),
        Size = UDim2.new(1, -2, 0, 34),
        ZIndex = 15,
        Parent = frame,
      })
      Library:_bind(headerSurface, "BackgroundColor3", "Control")

      local sectionTitle = themedLabel({
        Active = true,
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(12, 9),
        Size = UDim2.new(1, -24, 0, 18),
        Font = Enum.Font.GothamSemibold,
        Text = sectionInfo.Name,
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        ZIndex = 16,
        Parent = frame,
      })
      Library:_attachTooltip(sectionTitle, tooltipText(sectionInfo))

      local headerDivider = new("Frame", {
        BackgroundColor3 = Library.Theme.Border,
        BackgroundTransparency = 0.8,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(1, 35),
        Size = UDim2.new(1, -2, 0, 1),
        ZIndex = 16,
        Parent = frame,
      })
      Library:_bind(headerDivider, "BackgroundColor3", "Border")

      local headerHeight = 42
      local contentFrame = new("Frame", {
        BackgroundTransparency = 1,
        Position = UDim2.fromOffset(12, headerHeight),
        Size = UDim2.new(1, -24, 0, 0),
        ZIndex = 16,
        Parent = frame,
      })
      local contentLayout = list(contentFrame, 2)

      local Section = {
        Name = sectionInfo.Name,
        ParentTab = Tab,
        Tab = self,
        Frame = frame,
        Title = sectionTitle,
        Content = contentFrame,
        Layout = contentLayout,
        HeaderHeight = headerHeight,
        HeaderActionWidth = 0,
      }

      function Section:_updateSize()
        local scale = Library._scale or 1
        local manualHeight = 0
        if self.Content then
          for _, child in ipairs(self.Content:GetChildren()) do
            if child:IsA("GuiObject") and child.Visible ~= false then
              manualHeight = manualHeight + child.Size.Y.Offset + 2
            end
          end
        end
        local layoutHeight = (self.Layout and self.Layout.AbsoluteContentSize and self.Layout.AbsoluteContentSize.Y or 0) / scale
        local contentHeight = math.max(layoutHeight, manualHeight)
        local hasContent = contentHeight > 0
        if self.Content then
          self.Content.Visible = true
          self.Content.Size = UDim2.new(1, -24, 0, math.max(0, contentHeight))
        end
        if headerDivider then
          headerDivider.Visible = hasContent
        end
        if self.Frame then
          self.Frame.Size = UDim2.new(1, 0, 0, hasContent and (self.HeaderHeight + contentHeight + 12) or 36)
        end
        if self.Tab and self.Tab._updateLayout then
          self.Tab:_updateLayout()
        end
      end

      if contentLayout then
        Library:_connect(contentLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
          Section:_updateSize()
        end)
      end

      function Section:_addHeaderAction(width)
        local offset = self.HeaderActionWidth
        local host = new("Frame", {
          Active = true,
          BackgroundTransparency = 1,
          BorderSizePixel = 0,
          Position = UDim2.new(1, -(12 + offset + width), 0, 1),
          Size = UDim2.fromOffset(width, 34),
          ZIndex = 16,
          Parent = self.Frame,
        })
        self.HeaderActionWidth = offset + width + 4
        self.Title.Size = UDim2.new(1, -(24 + self.HeaderActionWidth), 0, 18)
        return host
      end

      function Section:AddHeaderToggle(controlInfo)
        return createToggle(self, controlInfo, self:_addHeaderAction(24))
      end

      function Section:AddHeaderKeybind(controlInfo)
        return createKeybind(self, controlInfo, self:_addHeaderAction(36))
      end

      function Section:AddToggle(controlInfo)
        return createToggle(self, controlInfo)
      end

      function Section:AddBoundToggle(toggleInfo, keybindInfo)
        local row = makeRow(self, Metrics.Row, toggleInfo)
        local name = rowText(row, toggleInfo, 82)
        local keybindHost = new("Frame", {
          Active = true,
          BackgroundTransparency = 1,
          BorderSizePixel = 0,
          Position = UDim2.new(1, -64, 0, 0),
          Size = UDim2.fromOffset(36, Metrics.Row),
          ZIndex = 16,
          Parent = row,
        })
        local toggleHost = new("Frame", {
          Active = true,
          BackgroundTransparency = 1,
          BorderSizePixel = 0,
          Position = UDim2.new(1, -22, 0, 0),
          Size = UDim2.fromOffset(22, Metrics.Row),
          ZIndex = 16,
          Parent = row,
        })
        local toggle = createToggle(self, toggleInfo, toggleHost, name)
        local keybind = createKeybind(self, keybindInfo, keybindHost)
        return toggle, keybind
      end

      function Section:AddSlider(controlInfo)
        if type(controlInfo) ~= "table" then controlInfo = {} end
        local minVal = tonumber(controlInfo.Min) or 0
        local maxVal = tonumber(controlInfo.Max) or 100
        if maxVal < minVal then
          maxVal = minVal
        end
        controlInfo.Min = minVal
        controlInfo.Max = maxVal

        local increment = tonumber(controlInfo.Increment) or 1
        if increment <= 0 then increment = 1 end
        controlInfo.Increment = increment

        controlInfo.Flag = Library:_claimFlag(controlInfo.Flag)

        local row = makeRow(self, 41, controlInfo)
        local name = rowText(row, controlInfo, 68)
        local valueBox = new("TextBox", {
          BackgroundTransparency = 1,
          BorderSizePixel = 0,
          ClearTextOnFocus = false,
          Position = UDim2.new(1, -68, 0, 7),
          Size = UDim2.fromOffset(68, 18),
          Font = Enum.Font.GothamMedium,
          Text = "",
          TextColor3 = Library.Theme.TextMuted,
          TextSize = 12,
          TextXAlignment = Enum.TextXAlignment.Right,
          ZIndex = 17,
          Parent = row,
        })

        local track = new("TextButton", {
          AutoButtonColor = false,
          BackgroundColor3 = Library.Theme.Control,
          BorderSizePixel = 0,
          Position = UDim2.new(0, 0, 1, -8),
          Size = UDim2.new(1, 0, 0, 6),
          Text = "",
          ZIndex = 17,
          Parent = row,
        })
        corner(track, 3)

        local fill = new("Frame", {
          BackgroundColor3 = Library.Theme.Accent,
          BorderSizePixel = 0,
          Size = UDim2.fromScale(0, 1),
          ZIndex = 18,
          Parent = track,
        })
        corner(fill, 3)
        Library:_bind(fill, "BackgroundColor3", "Accent")

        local initial = type(controlInfo.Default) == "number" and controlInfo.Default or controlInfo.Min
        initial = math.clamp(quantize(initial, controlInfo.Min, increment), controlInfo.Min, controlInfo.Max)

        local control = attachCommon({
          Type = "Slider",
          Frame = row,
          Value = initial,
          Min = controlInfo.Min,
          Max = controlInfo.Max,
          Increment = increment,
          Fixed = controlInfo.Max == controlInfo.Min,
          Suffix = controlInfo.Suffix or "",
          Precision = decimalPlaces(increment),
          Disabled = false,
          Callback = controlInfo.Callback,
          _editing = false,
        })

        function control:_render()
          local ratio = self.Fixed and 1 or (self.Value - self.Min) / (self.Max - self.Min)
          fill.Size = UDim2.fromScale(ratio, 1)
          fill.BackgroundTransparency = (self.Disabled or self.Fixed) and 0.5 or 0
          track.BackgroundTransparency = (self.Disabled or self.Fixed) and 0.4 or 0
          local formatted = string.format("%." .. self.Precision .. "f", self.Value)
          valueBox.Text = self._editing and formatted or formatted .. self.Suffix
          valueBox.TextEditable = not self.Disabled and not self.Fixed
          valueBox.TextTransparency = self.Disabled and 0.45 or 0
          name.TextTransparency = self.Disabled and 0.45 or 0
        end

        function control:SetValue(value)
          if type(value) ~= "number" then
            return false, "slider value must be a number"
          end

          value = math.clamp(quantize(value, self.Min, self.Increment), self.Min, self.Max)
          if value == self.Value then
            return true
          end

          self.Value = value
          self:_render()
          safeCallback(self.Callback, value)
          return true
        end

        function control:_setFromPosition(x)
          if self.Disabled or self.Fixed then
            return
          end
          local width = track.AbsoluteSize.X
          if width <= 0 then
            return
          end
          local ratio = math.clamp((x - track.AbsolutePosition.X) / width, 0, 1)
          self:SetValue(self.Min + (self.Max - self.Min) * ratio)
        end

        Library:_connect(track.InputBegan, function(input)
          local inputType = input.UserInputType
          if
            (inputType == Enum.UserInputType.MouseButton1 or inputType == Enum.UserInputType.Touch)
            and not control.Disabled
            and not control.Fixed
          then
            Library._sliderDrag = {
              Control = control,
              Input = input,
            }
            control:_setFromPosition(input.Position.X)
          end
        end)
        Library:_connect(valueBox.Focused, function()
          if control.Disabled or control.Fixed then
            valueBox:ReleaseFocus()
            return
          end
          control._editing = true
          control:_render()
        end)
        Library:_connect(valueBox.FocusLost, function()
          control._editing = false
          if not control.Disabled then
            local value = tonumber(valueBox.Text)
            if value then
              control:SetValue(value)
            end
          end
          control:_render()
        end)

        Library:_register(control, controlInfo.Flag)
        control:_render()
        return control
      end

      function Section:AddDropdown(controlInfo)
        if type(controlInfo) ~= "table" then controlInfo = {} end
        controlInfo.Flag = Library:_claimFlag(controlInfo.Flag)

        local row = makeRow(self, Metrics.Row, controlInfo)
        local name = rowText(row, controlInfo, 130)
        local field = new("TextButton", {
          AutoButtonColor = false,
          BackgroundColor3 = Library.Theme.Control,
          BorderSizePixel = 0,
          Position = UDim2.new(1, -120, 0.5, -12),
          Size = UDim2.fromOffset(120, 24),
          Font = Enum.Font.Gotham,
          Text = "",
          TextColor3 = Library.Theme.Text,
          TextSize = 12,
          TextTruncate = Enum.TextTruncate.AtEnd,
          TextXAlignment = Enum.TextXAlignment.Left,
          ZIndex = 17,
          Parent = row,
        })
        corner(field, 4)
        padding(field, 8, 8, 0, 0)
        local fieldStroke = themedStroke(field, "Border")

        local optionSet = {}
        local options = {}
        local rawOptions = type(controlInfo.Options) == "table" and controlInfo.Options or {}
        if #rawOptions == 0 then
          rawOptions = {"None"}
        end
        for _, option in ipairs(rawOptions) do
          local optStr = tostring(option or "")
          if optStr ~= "" and not optionSet[optStr] then
            optionSet[optStr] = true
            options[#options + 1] = optStr
          end
        end
        if #options == 0 then
          options = {"None"}
          optionSet["None"] = true
        end

        local multi = controlInfo.Multi == true
        local initial
        if multi then
          initial = {}
          if type(controlInfo.Default) == "table" then
            for _, option in ipairs(options) do
              if contains(controlInfo.Default, option) then
                initial[#initial + 1] = option
              end
            end
          end
          initial = freezeArray(initial)
        else
          initial = optionSet[controlInfo.Default] and controlInfo.Default or options[1]
        end

        local control = attachCommon({
          Type = "Dropdown",
          Frame = row,
          Value = initial,
          Options = options,
          Multi = multi,
          Disabled = false,
          Callback = controlInfo.Callback,
        })

        function control:_render()
          if self.Multi then
            field.Text = #self.Value > 0 and table.concat(self.Value, ", ") or "None"
          else
            field.Text = self.Value
          end
          field.BackgroundTransparency = self.Disabled and 0.45 or 0
          field.TextTransparency = self.Disabled and 0.45 or 0
          name.TextTransparency = self.Disabled and 0.45 or 0
        end

        function control:SetValue(value)
          local normalized
          if self.Multi then
            if type(value) ~= "table" then
              return false, "multi-dropdown value must be an array"
            end
            normalized = {}
            for _, option in ipairs(self.Options) do
              if contains(value, option) then
                normalized[#normalized + 1] = option
              end
            end
            normalized = freezeArray(normalized)
            if arraysEqual(normalized, self.Value) then
              return true
            end
          else
            if type(value) ~= "string" or not contains(self.Options, value) then
              return false, "dropdown value is not an available option"
            end
            normalized = value
            if normalized == self.Value then
              return true
            end
          end

          self.Value = normalized
          self:_render()
          safeCallback(self.Callback, normalized)
          return true
        end

        function control:SetOptions(newOptions)
          if type(newOptions) ~= "table" or #newOptions == 0 then
            return false, "dropdown options must be a non-empty array"
          end

          local nextOptions = {}
          local seen = {}
          for _, option in ipairs(newOptions) do
            if type(option) ~= "string" or option == "" or seen[option] then
              return false, "dropdown options must be unique, non-empty strings"
            end
            seen[option] = true
            nextOptions[#nextOptions + 1] = option
          end

          Library:_closePopup(self)
          local old = self.Value
          self.Options = nextOptions
          if self.Multi then
            local kept = {}
            for _, option in ipairs(nextOptions) do
              if contains(old, option) then
                kept[#kept + 1] = option
              end
            end
            self.Value = freezeArray(kept)
            self:_render()
            if not arraysEqual(old, self.Value) then
              safeCallback(self.Callback, self.Value)
            end
          else
            self.Value = contains(nextOptions, old) and old or nextOptions[1]
            self:_render()
            if self.Value ~= old then
              safeCallback(self.Callback, self.Value)
            end
          end
          return true
        end

        function control:_popupClosed()
          fieldStroke.Color = Library.Theme.Border
          self._optionButtons = nil
        end

        function control:_renderOptions()
          if not self._optionButtons then
            return
          end
          for option, button in pairs(self._optionButtons) do
            local selected = self.Multi and contains(self.Value, option) or self.Value == option
            button.TextColor3 = selected and Library.Theme.Accent or Library.Theme.Text
            button.BackgroundColor3 = selected and Library.Theme.SurfaceHover or Library.Theme.Control
          end
        end

        function control:_refreshAccent()
          if Library._popup and Library._popup.Owner == self then
            fieldStroke.Color = Library.Theme.Accent
            self:_renderOptions()
          end
        end

        function control:_openOptions()
          local visibleCount = math.min(#self.Options, 6)
          local fieldWidth = field.AbsoluteSize.X / Library._scale
          if fieldWidth <= 0 then
            fieldWidth = field.Size.X.Offset
          end
          local popupWidth = math.max(148, fieldWidth)
          for _, option in ipairs(self.Options) do
            local optionWidth = TextService:GetTextSize(option, 12, Enum.Font.Gotham, Vector2.new(1000, 18)).X + 22
            popupWidth = math.max(popupWidth, optionWidth)
          end
          local viewportWidth = (Library._overlay.AbsoluteSize.X - 16) / Library._scale
          popupWidth = math.min(popupWidth, 320, viewportWidth)
          local popup = new("Frame", {
            BackgroundColor3 = Library.Theme.Surface,
            BorderSizePixel = 0,
            Size = UDim2.fromOffset(popupWidth, visibleCount * 27 + 8),
            ZIndex = 101,
          })
          corner(popup, 5)
          themedStroke(popup, "Border")
          Library:_bind(popup, "BackgroundColor3", "Surface")

          local optionScroll = new("ScrollingFrame", {
            Active = true,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            CanvasSize = UDim2.fromOffset(0, #self.Options * 27),
            Position = UDim2.fromOffset(4, 4),
            ScrollBarImageColor3 = Library.Theme.Border,
            ScrollBarThickness = #self.Options > 6 and 2 or 0,
            Size = UDim2.new(1, -8, 1, -8),
            ZIndex = 102,
            Parent = popup,
          })
          local optionLayout = list(optionScroll, 0)
          optionLayout.HorizontalAlignment = Enum.HorizontalAlignment.Center

          self._optionButtons = {}
          for _, option in ipairs(self.Options) do
            local optionButton = new("TextButton", {
              AutoButtonColor = false,
              BackgroundColor3 = Library.Theme.Control,
              BackgroundTransparency = 0,
              BorderSizePixel = 0,
              Size = UDim2.new(1, 0, 0, 27),
              Font = Enum.Font.Gotham,
              Text = option,
              TextColor3 = Library.Theme.Text,
              TextSize = 12,
              TextTruncate = Enum.TextTruncate.AtEnd,
              TextXAlignment = Enum.TextXAlignment.Left,
              ZIndex = 103,
              Parent = optionScroll,
            })
            padding(optionButton, 8, 8, 0, 0)
            self._optionButtons[option] = optionButton

            Library:_connect(optionButton.MouseButton1Click, function()
              if self.Multi then
                local selected = cloneArray(self.Value)
                local index = table.find(selected, option)
                if index then
                  table.remove(selected, index)
                else
                  selected[#selected + 1] = option
                end
                self:SetValue(selected)
                self:_renderOptions()
              else
                self:SetValue(option)
                Library:_closePopup(self)
              end
            end)
          end

          fieldStroke.Color = Library.Theme.Accent
          Library:_openPopup(self, popup, field)
          self:_renderOptions()
        end

        Library:_connect(field.MouseButton1Click, function()
          if control.Disabled then
            return
          end
          if Library._popup and Library._popup.Owner == control then
            Library:_closePopup(control)
          else
            control:_openOptions()
          end
        end)
        Library:_connect(field.MouseEnter, function()
          if not control.Disabled and not (Library._popup and Library._popup.Owner == control) then
            field.BackgroundColor3 = Library.Theme.SurfaceHover
          end
        end)
        Library:_connect(field.MouseLeave, function()
          field.BackgroundColor3 = Library.Theme.Control
        end)

        Library:_register(control, controlInfo.Flag)
        control:_render()
        return control
      end

      function Section:AddButton(controlInfo)
        if type(controlInfo) == "string" then
          controlInfo = { Name = controlInfo }
        elseif type(controlInfo) ~= "table" then
          controlInfo = { Name = "Button" }
        end
        controlInfo.Name = tostring(controlInfo.Name or "Button")
        local row = makeRow(self, Metrics.Row, controlInfo)
        local button = new("TextButton", {
          AutoButtonColor = false,
          BackgroundColor3 = Library.Theme.Control,
          BorderSizePixel = 0,
          Size = UDim2.new(1, 0, 0, 30),
          Font = Enum.Font.GothamMedium,
          Text = controlInfo.Name,
          TextColor3 = Library.Theme.Text,
          TextSize = 12,
          ZIndex = 17,
          Parent = row,
        })
        corner(button, 4)
        local buttonStroke = themedStroke(button, "Border", 0.5)
        Library:_attachTooltip(button, tooltipText(controlInfo))

        local control = {
          Type = "Button",
          Frame = row,
          Disabled = false,
          _hovered = false,
          Callback = controlInfo.Callback,
        }

        function control:SetVisible(visible)
          visible = visible == true
          if not visible then
            self._hovered = false
            Library:_hideTooltip(button)
            button.BackgroundColor3 = Library.Theme.Control
            buttonStroke.Color = Library.Theme.Border
          end
          self.Frame.Visible = visible
          return true
        end

        function control:SetDisabled(disabled)
          self.Disabled = disabled == true
          if self.Disabled then
            self._hovered = false
            Library:_hideTooltip(button)
            button.BackgroundColor3 = Library.Theme.Control
            buttonStroke.Color = Library.Theme.Border
          end
          button.BackgroundTransparency = self.Disabled and 0.45 or 0
          button.TextTransparency = self.Disabled and 0.45 or 0
          return true
        end

        function control:_refreshAccent()
          if self._hovered and not self.Disabled then
            buttonStroke.Color = Library.Theme.Accent
          end
        end
        Library._accentControls[#Library._accentControls + 1] = control

        Library:_connect(button.MouseButton1Click, function()
          if not control.Disabled then
            safeCallback(control.Callback)
          end
        end)
        Library:_connect(button.MouseEnter, function()
          if not control.Disabled then
            control._hovered = true
            button.BackgroundColor3 = Library.Theme.SurfaceHover
            buttonStroke.Color = Library.Theme.Accent
          end
        end)
        Library:_connect(button.MouseLeave, function()
          control._hovered = false
          button.BackgroundColor3 = Library.Theme.Control
          buttonStroke.Color = Library.Theme.Border
        end)

        return control
      end

      function Section:AddTextbox(controlInfo)
        if type(controlInfo) ~= "table" then controlInfo = {} end
        controlInfo.Flag = Library:_claimFlag(controlInfo.Flag)

        local multiLine = controlInfo.MultiLine == true
        local inputHeight = multiLine and 61 or 28
        local row = makeRow(self, multiLine and 90 or 57, controlInfo)
        rowText(row, controlInfo, 0)

        local box = new("TextBox", {
          BackgroundColor3 = Library.Theme.Control,
          BorderSizePixel = 0,
          ClearTextOnFocus = false,
          Position = UDim2.new(0, 0, 1, -inputHeight),
          Size = UDim2.new(1, 0, 0, inputHeight),
          Font = Enum.Font.Gotham,
          PlaceholderColor3 = Library.Theme.TextMuted,
          PlaceholderText = controlInfo.Placeholder or "Enter value...",
          Text = "",
          TextColor3 = Library.Theme.Text,
          TextSize = 12,
          TextWrapped = multiLine,
          TextXAlignment = Enum.TextXAlignment.Left,
          TextYAlignment = multiLine and Enum.TextYAlignment.Top or Enum.TextYAlignment.Center,
          MultiLine = multiLine,
          ZIndex = 17,
          Parent = row,
        })
        corner(box, 4)
        padding(box, 8, 8, 0, 0)
        local boxStroke = themedStroke(box, "Border")

        local numeric = controlInfo.Numeric == true
        local initial = controlInfo.Default
        if numeric then
          initial = type(initial) == "number" and initial or 0
        else
          initial = initial == nil and "" or tostring(initial)
        end

        local control = attachCommon({
          Type = "Textbox",
          Frame = row,
          Value = initial,
          Numeric = numeric,
          Disabled = false,
          Callback = controlInfo.Callback,
        })

        function control:_render()
          box.Text = tostring(self.Value)
          box.TextEditable = not self.Disabled
          box.BackgroundTransparency = self.Disabled and 0.45 or 0
          box.TextTransparency = self.Disabled and 0.45 or 0
        end

        function control:_refreshAccent()
          if UserInputService:GetFocusedTextBox() == box then
            boxStroke.Color = Library.Theme.Accent
          end
        end

        function control:SetValue(value)
          if self.Numeric then
            if type(value) ~= "number" then
              return false, "numeric textbox value must be a number"
            end
          elseif type(value) ~= "string" then
            return false, "textbox value must be a string"
          end

          if value == self.Value then
            self:_render()
            return true
          end
          self.Value = value
          self:_render()
          safeCallback(self.Callback, value)
          return true
        end

        Library:_connect(box.Focused, function()
          if not control.Disabled then
            boxStroke.Color = Library.Theme.Accent
          end
        end)
        Library:_connect(box.FocusLost, function()
          boxStroke.Color = Library.Theme.Border
          if control.Disabled then
            control:_render()
            return
          end

          if control.Numeric then
            local value = tonumber(box.Text)
            if value then
              control:SetValue(value)
            else
              control:_render()
            end
          else
            control:SetValue(box.Text)
          end
        end)

        Library:_register(control, controlInfo.Flag)
        control:_render()
        return control
      end

      function Section:AddKeybind(controlInfo)
        return createKeybind(self, controlInfo)
      end

      function Section:AddColorPicker(controlInfo)
        if type(controlInfo) ~= "table" then controlInfo = {} end
        controlInfo.Flag = Library:_claimFlag(controlInfo.Flag)

        local initial = controlInfo.Default
        if typeof(initial) ~= "Color3" then
          initial = Library.Theme.Accent or Color3.fromRGB(139, 92, 246)
        end

        local row = makeRow(self, Metrics.Row, controlInfo)
        local name = rowText(row, controlInfo, 36)
        local swatch = new("TextButton", {
          AutoButtonColor = false,
          BackgroundColor3 = initial,
          BorderSizePixel = 0,
          Position = UDim2.new(1, -24, 0.5, -9),
          Size = UDim2.fromOffset(24, 18),
          Text = "",
          ZIndex = 17,
          Parent = row,
        })
        corner(swatch, 4)
        local swatchStroke = themedStroke(swatch, "Border", 0.35)

        local control = attachCommon({
          Type = "ColorPicker",
          Frame = row,
          Value = initial,
          Disabled = false,
          Callback = controlInfo.Callback,
        })

        function control:_render()
          swatch.BackgroundColor3 = self.Value
          swatch.BackgroundTransparency = self.Disabled and 0.45 or 0
          swatchStroke.Color = Library._popup and Library._popup.Owner == self and Library.Theme.Accent
            or Library.Theme.Border
          name.TextTransparency = self.Disabled and 0.45 or 0
          if self._picker then
            self:_renderPicker()
          end
        end

        function control:_refreshAccent()
          if Library._popup and Library._popup.Owner == self then
            swatchStroke.Color = Library.Theme.Accent
          end
        end

        function control:SetValue(value)
          if typeof(value) ~= "Color3" then
            return false, "color picker value must be a Color3"
          end
          if value == self.Value then
            return true
          end

          self.Value = value
          if self._picker then
            local hue, saturation, brightness = value:ToHSV()
            if saturation > 0 and brightness > 0 then
              self._picker.Hue = hue
            end
            self._picker.Saturation = saturation
            self._picker.Brightness = brightness
          end
          self:_render()
          safeCallback(self.Callback, value)
          return true
        end

        function control:_renderPicker()
          local picker = self._picker
          if not picker then
            return
          end

          picker.SV.BackgroundColor3 = Color3.fromHSV(picker.Hue, 1, 1)
          picker.SVMarker.Position = UDim2.fromScale(picker.Saturation, 1 - picker.Brightness)
          picker.HueMarker.Position = UDim2.new(picker.Hue, -1, 0, -2)
          picker.Hex.Text = colorHex(self.Value)
        end

        function control:_setFromPicker(kind, point)
          local picker = self._picker
          if not picker then
            return
          end

          if kind == "SV" then
            local position = picker.SV.AbsolutePosition
            local size = picker.SV.AbsoluteSize
            picker.Saturation = math.clamp((point.X - position.X) / size.X, 0, 1)
            picker.Brightness = 1 - math.clamp((point.Y - position.Y) / size.Y, 0, 1)
          else
            local position = picker.HueBar.AbsolutePosition
            picker.Hue = math.clamp((point.X - position.X) / picker.HueBar.AbsoluteSize.X, 0, 1)
          end

          local value = Color3.fromHSV(picker.Hue, picker.Saturation, picker.Brightness)
          if value == self.Value then
            self:_renderPicker()
          else
            self:SetValue(value)
          end
        end

        function control:_popupClosed()
          self._picker = nil
          self:_render()
        end

        function control:_openPicker()
          local hue, saturation, brightness = self.Value:ToHSV()
          local popup = new("Frame", {
            BackgroundColor3 = Library.Theme.Surface,
            BorderSizePixel = 0,
            Size = UDim2.fromOffset(166, 179),
            ZIndex = 101,
          })
          corner(popup, 6)
          themedStroke(popup, "Border", 0.45)
          Library:_bind(popup, "BackgroundColor3", "Surface")

          local sv = new("Frame", {
            Active = true,
            BackgroundColor3 = Color3.fromHSV(hue, 1, 1),
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(8, 8),
            Size = UDim2.fromOffset(150, 115),
            ZIndex = 102,
            Parent = popup,
          })
          corner(sv, 4)

          local white = new("Frame", {
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
            Size = UDim2.fromScale(1, 1),
            ZIndex = 103,
            Parent = sv,
          })
          corner(white, 4)
          new("UIGradient", {
            Rotation = 0,
            Transparency = NumberSequence.new({
              NumberSequenceKeypoint.new(0, 0),
              NumberSequenceKeypoint.new(1, 1),
            }),
            Parent = white,
          })

          local black = new("Frame", {
            BackgroundColor3 = Color3.new(0, 0, 0),
            BorderSizePixel = 0,
            Size = UDim2.fromScale(1, 1),
            ZIndex = 104,
            Parent = sv,
          })
          corner(black, 4)
          new("UIGradient", {
            Rotation = 90,
            Transparency = NumberSequence.new({
              NumberSequenceKeypoint.new(0, 1),
              NumberSequenceKeypoint.new(1, 0),
            }),
            Parent = black,
          })

          local svMarker = new("Frame", {
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            Position = UDim2.fromScale(saturation, 1 - brightness),
            Size = UDim2.fromOffset(10, 10),
            ZIndex = 105,
            Parent = sv,
          })
          corner(svMarker, 5)
          new("UIStroke", {
            Color = Color3.new(1, 1, 1),
            Thickness = 1.5,
            Parent = svMarker,
          })

          local hueBar = new("Frame", {
            Active = true,
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
            Position = UDim2.fromOffset(11, 131),
            Size = UDim2.fromOffset(144, 8),
            ZIndex = 102,
            Parent = popup,
          })
          corner(hueBar, 4)
          new("UIGradient", {
            Color = ColorSequence.new({
              ColorSequenceKeypoint.new(0, Color3.fromHSV(0, 1, 1)),
              ColorSequenceKeypoint.new(0.17, Color3.fromHSV(0.17, 1, 1)),
              ColorSequenceKeypoint.new(0.33, Color3.fromHSV(0.33, 1, 1)),
              ColorSequenceKeypoint.new(0.5, Color3.fromHSV(0.5, 1, 1)),
              ColorSequenceKeypoint.new(0.67, Color3.fromHSV(0.67, 1, 1)),
              ColorSequenceKeypoint.new(0.83, Color3.fromHSV(0.83, 1, 1)),
              ColorSequenceKeypoint.new(1, Color3.fromHSV(1, 1, 1)),
            }),
            Parent = hueBar,
          })

          local hueMarker = new("Frame", {
            BackgroundColor3 = Color3.new(1, 1, 1),
            BorderSizePixel = 0,
            Position = UDim2.new(hue, -1, 0, -2),
            Size = UDim2.fromOffset(2, 14),
            ZIndex = 104,
            Parent = hueBar,
          })

          local hex = new("TextBox", {
            BackgroundColor3 = Library.Theme.Control,
            BorderSizePixel = 0,
            ClearTextOnFocus = false,
            Position = UDim2.fromOffset(8, 148),
            Size = UDim2.fromOffset(150, 22),
            Font = Enum.Font.GothamMedium,
            PlaceholderColor3 = Library.Theme.TextMuted,
            PlaceholderText = "#RRGGBB",
            Text = colorHex(self.Value),
            TextColor3 = Library.Theme.Text,
            TextSize = 11,
            ZIndex = 102,
            Parent = popup,
          })
          corner(hex, 4)
          padding(hex, 7, 7, 0, 0)
          Library:_bind(hex, "BackgroundColor3", "Control")
          Library:_bind(hex, "TextColor3", "Text")
          Library:_bind(hex, "PlaceholderColor3", "TextMuted")

          self._picker = {
            Hue = hue,
            Saturation = saturation,
            Brightness = brightness,
            SV = sv,
            SVMarker = svMarker,
            HueBar = hueBar,
            HueMarker = hueMarker,
            Hex = hex,
          }

          Library:_connect(sv.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
              Library._colorDrag = { Control = self, Mode = "SV" }
              self:_setFromPicker("SV", input.Position)
            end
          end)
          Library:_connect(hueBar.InputBegan, function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 then
              Library._colorDrag = { Control = self, Mode = "Hue" }
              self:_setFromPicker("Hue", input.Position)
            end
          end)
          Library:_connect(hex.FocusLost, function()
            local parsed = colorFromHex(hex.Text)
            if parsed then
              self:SetValue(parsed)
            else
              self:_renderPicker()
            end
          end)

          Library:_openPopup(self, popup, swatch)
          self:_render()
        end

        Library:_connect(swatch.MouseButton1Click, function()
          if control.Disabled then
            return
          end
          if Library._popup and Library._popup.Owner == control then
            Library:_closePopup(control)
          else
            control:_openPicker()
          end
        end)

        Library:_register(control, controlInfo.Flag)
        control:_render()
        return control
      end

      function Section:AddLabel(text)
        text = tostring(text or "")
        local row = makeRow(self, 24)
        local label = themedLabel({
          BackgroundTransparency = 1,
          Size = UDim2.fromScale(1, 1),
          Font = Enum.Font.Gotham,
          Text = text,
          TextSize = 12,
          TextWrapped = true,
          TextXAlignment = Enum.TextXAlignment.Left,
          TextYAlignment = Enum.TextYAlignment.Top,
          ZIndex = 17,
          Parent = row,
        }, "TextMuted")

        local function resize()
          local width = row.AbsoluteSize.X / (Library._scale or 1)
          if width <= 0 then
            return
          end
          local bounds = TextService:GetTextSize(label.Text, 12, Enum.Font.Gotham, Vector2.new(width, 1000))
          row.Size = UDim2.new(1, 0, 0, math.max(24, bounds.Y + 2))
        end
        Library:_connect(row:GetPropertyChangedSignal("AbsoluteSize"), resize)
        resize()

        local control = {
          Type = "Label",
          Frame = row,
        }

        function control:SetText(nextText)
          label.Text = tostring(nextText or "")
          resize()
          return true
        end

        function control:SetTextColor(color)
          if typeof(color) == "Color3" then
            label.TextColor3 = color
          end
          return true
        end

        function control:SetVisible(visible)
          row.Visible = visible == true
          return true
        end

        return control
      end

      function Section:AddDivider()
        local row = makeRow(self, 13)
        local line = new("Frame", {
          BackgroundColor3 = Library.Theme.Border,
          BorderSizePixel = 0,
          Position = UDim2.new(0, 0, 0.5, 0),
          Size = UDim2.new(1, 0, 0, 1),
          ZIndex = 17,
          Parent = row,
        })
        Library:_bind(line, "BackgroundColor3", "Border")

        local control = {
          Type = "Divider",
          Frame = row,
        }

        function control:SetVisible(visible)
          row.Visible = visible == true
          return true
        end

        return control
      end

      Section:_updateSize()
      return Section
    end

    function Tab:_selectSubTab(subTab)
      Library:_hideTooltip()
      for _, other in ipairs(self.SubTabs) do
        local selected = other == subTab
        other.Scroll.Visible = selected
        other.Indicator.Visible = selected
        other.Button.BackgroundColor3 = selected and Library.Theme.Control or Library.Theme.SurfaceHover
        other.Button.BackgroundTransparency = selected and 0 or 1
        other.Button.TextColor3 = selected and Library.Theme.Text or Library.Theme.TextSecondary
      end
      self.SelectedSubTab = subTab
      if subTab and subTab._updateLayout then
        subTab:_updateLayout()
      end
    end

    function Tab:AddSubTab(name)
      name = tostring(name or "SubTab")
      if name == "" then name = "SubTab" end
      local baseName = name
      local counter = 1
      local duplicate = true
      while duplicate do
        duplicate = false
        for _, existing in ipairs(self.SubTabs) do
          if existing.Name == name then
            counter = counter + 1
            name = baseName .. " " .. tostring(counter)
            duplicate = true
            break
          end
        end
      end

      local width = math.max(64, TextService:GetTextSize(name, 13, Enum.Font.GothamMedium, Vector2.new(320, 18)).X + 22)
      local subTab = createSubPage(name)
      local subButton = new("TextButton", {
        AutoButtonColor = false,
        BackgroundColor3 = Library.Theme.Control,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(width, 28),
        Font = Enum.Font.GothamMedium,
        Text = name,
        TextColor3 = Library.Theme.TextSecondary,
        TextSize = 13,
        ZIndex = 14,
        Parent = subTabBar,
      })
      corner(subButton, 5)

      local subIndicator = new("Frame", {
        BackgroundColor3 = Library.Theme.Accent,
        BorderSizePixel = 0,
        Position = UDim2.new(0.5, -9, 1, -2),
        Size = UDim2.fromOffset(18, 2),
        Visible = false,
        ZIndex = 15,
        Parent = subButton,
      })
      corner(subIndicator, 1)
      Library:_bind(subIndicator, "BackgroundColor3", "Accent")

      subTab.Button = subButton
      subTab.Indicator = subIndicator
      subTab.AddSection = addSection
      self.SubTabs[#self.SubTabs + 1] = subTab
      if not self.DefaultSubTab then
        self.DefaultSubTab = subTab
        self:_selectSubTab(subTab)
      end

      Library:_connect(subButton.MouseButton1Click, function()
        Library:_closePopup()
        Library:_cancelCapture()
        self:_selectSubTab(subTab)
      end)
      Library:_connect(subButton.MouseEnter, function()
        if self.SelectedSubTab ~= subTab then
          subButton.BackgroundTransparency = 0
          subButton.BackgroundColor3 = Library.Theme.Surface
        end
      end)
      Library:_connect(subButton.MouseLeave, function()
        if self.SelectedSubTab ~= subTab then
          subButton.BackgroundTransparency = 1
        end
      end)

      if not self.SelectedSubTab then
        self:_selectSubTab(subTab)
      end
      return subTab
    end

    function Tab:AddSection(sectionInfo)
      local subTab = self.DefaultSubTab or self:AddSubTab("Main")
      return subTab:AddSection(sectionInfo)
    end

    if subTabLayout and subTabBar then
      Library:_connect(subTabLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
        pcall(function()
          if subTabLayout and subTabBar and subTabLayout.AbsoluteContentSize then
            subTabBar.CanvasSize = UDim2.fromOffset(subTabLayout.AbsoluteContentSize.X / (Library._scale or 1), 0)
          end
        end)
      end)
    end

    return Tab
  end

  return Window
end

function Library:SetFlag(flag, value)
  if self._destroyed then
    return false, "library unloaded"
  end

  local control = self.Controls[flag]
  if not control then
    return false, "unknown flag: " .. tostring(flag)
  end
  if type(control.SetValue) ~= "function" then
    return false, "control does not have a value"
  end

  return control:SetValue(value)
end

function Library:SetAccent(color)
  if self._destroyed then
    return false, "library unloaded"
  end
  if typeof(color) ~= "Color3" then
    return false, "accent must be a Color3"
  end

  self.Theme.Accent = color
  for _, binding in ipairs(self._accentBindings) do
    local instance = binding.Instance
    if instance and instance.Parent then
      instance[binding.Property] = color
    end
  end

  for _, control in ipairs(self._accentControls) do
    control:_refreshAccent()
  end
  return true
end

function Library:SetScale(scale)
  if self._destroyed then
    return false, "library unloaded"
  end
  if type(scale) ~= "number" then
    return false, "scale must be a number"
  end

  scale = math.clamp(scale, 0.75, 1.25)
  self._scale = scale
  self:_closePopup()
  self:_hideTooltip()
  if self._uiScale then
    self._uiScale.Scale = scale
  end
  if self._tooltipScale then
    self._tooltipScale.Scale = scale
  end
  if self._notificationScale then
    self._notificationScale.Scale = scale
  end
  return true
end

function Library:SetVisible(visible)
  if self._destroyed then
    return false, "library unloaded"
  end
  if type(visible) ~= "boolean" then
    return false, "visibility must be a boolean"
  end
  if not self._main then
    return false, "window has not been created"
  end
  if visible == self._visible then
    return true
  end

  self._visible = visible
  self:_closePopup()
  self:_cancelCapture()
  self:_hideTooltip()
  if not visible and self._search then
    self._search.Box.Text = ""
    self._search.Box:ReleaseFocus()
  end

  if visible then
    pcall(function()
      UserInputService.MouseIconEnabled = true
      UserInputService.MouseBehavior = Enum.MouseBehavior.Default
    end)
    self._main.Visible = true
    if self._selectedTab then
      self:_selectTab(self._selectedTab)
    elseif self._tabs[1] then
      self:_selectTab(self._tabs[1])
    end
  else
    self._main.Visible = false
  end
  return true
end

function Library:Toggle()
  return self:SetVisible(not self._visible)
end

local function removeNotification(notification)
  notification.Alive = false
  if notification.DelayThread then
    task.cancel(notification.DelayThread)
    notification.DelayThread = nil
  end
  if notification.Frame then
    notification.Frame:Destroy()
    notification.Frame = nil
  end

  local index = table.find(Library._notifications, notification)
  if index then
    table.remove(Library._notifications, index)
  end
  Library:_pruneRegistries()
end

function Library:Notify(info)
  if self._destroyed or not self._notificationHost then
    return nil, "window has not been created"
  end
  info = info or {}

  local title = tostring(info.Title or "Katalyst")
  local description = tostring(info.Description or "")
  local message = description ~= "" and (title .. "  ·  " .. description) or title
  local frame = new("CanvasGroup", {
    BackgroundColor3 = self.Theme.Surface,
    BorderSizePixel = 0,
    GroupTransparency = 1,
    Size = UDim2.fromOffset(270, 34),
    ZIndex = 200,
    Parent = self._notificationHost,
  })
  corner(frame, 5)
  themedStroke(frame, "Border", 0.7)
  self:_bind(frame, "BackgroundColor3", "Surface")

  themedLabel({
    BackgroundTransparency = 1,
    Position = UDim2.fromOffset(10, 0),
    Size = UDim2.new(1, -20, 1, 0),
    Font = Enum.Font.Gotham,
    Text = message,
    TextSize = 11,
    TextTruncate = Enum.TextTruncate.AtEnd,
    TextXAlignment = Enum.TextXAlignment.Left,
    ZIndex = 201,
    Parent = frame,
  })

  local notification = {
    Alive = true,
    Closing = false,
    Frame = frame,
  }

  function notification:Close()
    if not self.Alive or self.Closing then
      return
    end

    self.Closing = true
    if self.DelayThread then
      task.cancel(self.DelayThread)
      self.DelayThread = nil
    end
    if self.EnterTween then
      self.EnterTween:Cancel()
      self.EnterTween = nil
    end

    local tween
    tween = Library:_tween(frame, { GroupTransparency = 1 }, function()
      if self.ExitTween == tween then
        self.ExitTween = nil
      end
      if self.Alive and not Library._destroyed then
        removeNotification(self)
      end
    end)
    self.ExitTween = tween
  end

  self._notifications[#self._notifications + 1] = notification
  local enterTween
  enterTween = self:_tween(frame, { GroupTransparency = 0 }, function()
    if notification.EnterTween == enterTween then
      notification.EnterTween = nil
    end
  end)
  notification.EnterTween = enterTween
  notification.DelayThread = task.delay(math.max(0.25, tonumber(info.Duration) or 4), function()
    notification.DelayThread = nil
    if notification.Alive and not Library._destroyed then
      notification:Close()
    end
  end)
  return notification
end

local configFolder = "KatalystUI/configs"

local function validConfigName(name)
  return type(name) == "string" and name:match("^[%w_-]+$") ~= nil
end

local function ensureConfigFolder()
  if type(makefolder) ~= "function" then
    return false, "executor filesystem is unavailable"
  end

  local ok, message = pcall(function()
    if type(isfolder) ~= "function" or not isfolder("KatalystUI") then
      makefolder("KatalystUI")
    end
    if type(isfolder) ~= "function" or not isfolder(configFolder) then
      makefolder(configFolder)
    end
  end)

  return ok, ok and nil or tostring(message)
end

local function serializeControl(control)
  local value = control:GetValue()
  if control.Type == "Toggle" then
    return { type = "Toggle", value = value }
  elseif control.Type == "Slider" then
    return { type = "Slider", value = value }
  elseif control.Type == "Dropdown" then
    return {
      type = "Dropdown",
      multi = control.Multi,
      value = value,
    }
  elseif control.Type == "Textbox" then
    return {
      type = "Textbox",
      numeric = control.Numeric,
      value = value,
    }
  elseif control.Type == "Keybind" then
    return {
      type = "Keybind",
      key = value.Key and value.Key.Name or false,
      mode = value.Mode,
    }
  elseif control.Type == "ColorPicker" then
    return {
      type = "ColorPicker",
      r = math.round(value.R * 255),
      g = math.round(value.G * 255),
      b = math.round(value.B * 255),
    }
  end
end

local function validSelectionArray(control, value)
  if type(value) ~= "table" then
    return false
  end

  local count = 0
  local seen = {}
  for index, option in pairs(value) do
    if type(index) ~= "number" or index < 1 or index % 1 ~= 0 then
      return false
    end
    if type(option) ~= "string" or seen[option] or not contains(control.Options, option) then
      return false
    end
    count = count + 1
    seen[option] = true
  end

  for index = 1, count do
    if value[index] == nil then
      return false
    end
  end
  return true
end

local function loadControl(control, entry)
  if type(entry) ~= "table" or entry.type ~= control.Type then
    return false
  end

  if control.Type == "Toggle" then
    return type(entry.value) == "boolean" and control:SetValue(entry.value)
  elseif control.Type == "Slider" then
    return type(entry.value) == "number"
      and entry.value >= control.Min
      and entry.value <= control.Max
      and control:SetValue(entry.value)
  elseif control.Type == "Dropdown" then
    if entry.multi ~= control.Multi then
      return false
    end
    if control.Multi and not validSelectionArray(control, entry.value) then
      return false
    end
    return control:SetValue(entry.value)
  elseif control.Type == "Textbox" then
    return entry.numeric == control.Numeric and control:SetValue(entry.value)
  elseif control.Type == "Keybind" then
    local key
    local validKey = false
    if entry.key == false or entry.key == nil then
      validKey = control.AllowUnbound
    elseif type(entry.key) == "string" then
      key = keyCodesByName[entry.key]
      validKey = key ~= nil
    end

    if not validKey or not control.AllowedModes[entry.mode] then
      return false
    end
    return control:SetValue({
      Key = key,
      Mode = entry.mode,
    })
  elseif control.Type == "ColorPicker" then
    if type(entry.r) ~= "number" or type(entry.g) ~= "number" or type(entry.b) ~= "number" then
      return false
    end
    if entry.r % 1 ~= 0 or entry.g % 1 ~= 0 or entry.b % 1 ~= 0 then
      return false
    end
    if entry.r < 0 or entry.r > 255 or entry.g < 0 or entry.g > 255 or entry.b < 0 or entry.b > 255 then
      return false
    end
    return control:SetValue(Color3.fromRGB(entry.r, entry.g, entry.b))
  end

  return false
end

function Library:SaveConfig(name)
  if self._destroyed then
    return false, "library unloaded"
  end
  if not validConfigName(name) then
    return false, "config name may only contain letters, numbers, underscores, and hyphens"
  end
  if type(writefile) ~= "function" then
    return false, "executor filesystem is unavailable"
  end

  local folderOk, folderError = ensureConfigFolder()
  if not folderOk then
    return false, folderError
  end

  local values = {}
  for flag, control in pairs(self.Controls) do
    local entry = serializeControl(control)
    if entry then
      values[flag] = entry
    end
  end

  local encoded
  local encodedOk, encodedError = pcall(function()
    encoded = HttpService:JSONEncode({
      version = 1,
      values = values,
    })
  end)
  if not encodedOk then
    return false, tostring(encodedError)
  end

  local path = configFolder .. "/" .. name .. ".json"
  local writeOk, writeError = pcall(writefile, path, encoded)
  if not writeOk then
    return false, tostring(writeError)
  end
  return true, "Saved config '" .. name .. "'."
end

function Library:LoadConfig(name)
  if self._destroyed then
    return false, "library unloaded"
  end
  if not validConfigName(name) then
    return false, "invalid config name"
  end
  if type(readfile) ~= "function" or type(isfile) ~= "function" then
    return false, "executor filesystem is unavailable"
  end

  local path = configFolder .. "/" .. name .. ".json"
  if not isfile(path) then
    return false, "config does not exist"
  end

  local document
  local readOk, readError = pcall(function()
    document = HttpService:JSONDecode(readfile(path))
  end)
  if not readOk then
    return false, tostring(readError)
  end
  if type(document) ~= "table" or document.version ~= 1 or type(document.values) ~= "table" then
    return false, "unsupported config format"
  end

  for flag, entry in pairs(document.values) do
    local control = self.Controls[flag]
    if control then
      loadControl(control, entry)
    end
  end
  return true, "Loaded config '" .. name .. "'."
end

function Library:DeleteConfig(name)
  if self._destroyed then
    return false, "library unloaded"
  end
  if not validConfigName(name) then
    return false, "invalid config name"
  end
  if type(delfile) ~= "function" or type(isfile) ~= "function" then
    return false, "executor filesystem is unavailable"
  end

  local path = configFolder .. "/" .. name .. ".json"
  if not isfile(path) then
    return false, "config does not exist"
  end

  local ok, message = pcall(delfile, path)
  if not ok then
    return false, tostring(message)
  end
  return true, "Deleted config '" .. name .. "'."
end

function Library:GetConfigs()
  if self._destroyed then
    return {}
  end
  if type(listfiles) ~= "function" then
    return {}
  end
  if type(isfolder) == "function" and not isfolder(configFolder) then
    return {}
  end

  local files
  local ok = pcall(function()
    files = listfiles(configFolder)
  end)
  if not ok or type(files) ~= "table" then
    return {}
  end

  local configs = {}
  for _, path in ipairs(files) do
    local filename = path:match("([^/\\]+)%.json$")
    if filename then
      configs[#configs + 1] = filename
    end
  end
  table.sort(configs)
  return configs
end

function Library:Unload()
  if self._destroyed then
    return true
  end
  self._destroyed = true

  self:_closePopup()
  self:_cancelCapture()
  self:_hideTooltip()
  self:_clearSearchHighlight()
  self._sliderDrag = nil
  self._colorDrag = nil
  self._dragging = nil
  self._capturedInput = nil

  for _, control in ipairs(self._keybinds) do
    control._pressed = false
    if control:GetState() then
      control:_setActive(false)
    end
  end

  for _, notification in ipairs(self._notifications) do
    notification.Alive = false
    if notification.DelayThread then
      task.cancel(notification.DelayThread)
      notification.DelayThread = nil
    end
  end

  local tweens = {}
  for tween in pairs(self._tweens) do
    tweens[#tweens + 1] = tween
  end
  table.clear(self._tweens)
  for _, tween in ipairs(tweens) do
    tween:Cancel()
  end

  for _, connection in ipairs(self.Connections) do
    if connection.Connected then
      connection:Disconnect()
    end
  end
  table.clear(self.Connections)

  table.clear(self._notifications)

  if self._root then
    self._root:Destroy()
  end
  if self.Window then
    self.Window.Frame = nil
    self.Window.Library = nil
  end
  self._root = nil
  self._main = nil
  self._mainStroke = nil
  self._overlay = nil
  self._pageHost = nil
  self._sidebarList = nil
  self._selectedTab = nil
  self._uiScale = nil
  self._visibilityTween = nil
  self._visibilityStrokeTween = nil
  self._visibilityVersion = nil
  self._tooltipFrame = nil
  self._tooltipLabel = nil
  self._tooltipOwner = nil
  self._tooltipScale = nil
  self._search = nil
  self._searchHighlightTween = nil
  self._searchHighlightFrame = nil
  self._notificationHost = nil
  self._notificationScale = nil
  self.Window = nil

  table.clear(self.Controls)
  table.clear(self._accentControls)
  table.clear(self._keybinds)
  table.clear(self._tabs)
  table.clear(self._searchEntries)
  table.clear(self._accentBindings)

  if self._environment.__KATALYST_UI_LIBRARY == self then
    self._environment.__KATALYST_UI_LIBRARY = nil
  end
  return true
end

return Library
end)()
return Library
end)()
local loadLogo = (function()
local data = [[]]

local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local values = {}
for i = 1, #chars do
  values[chars:byte(i)] = i - 1
end

local function decode(text)
  local bytes = {}
  for i = 1, #text, 4 do
    local cByte = text:byte(i + 2)
    local dByte = text:byte(i + 3)
    local a = values[text:byte(i)]
    local b = values[text:byte(i + 1)]
    local c = values[cByte] or 0
    local d = values[dByte] or 0
    local value = a * 262144 + b * 4096 + c * 64 + d

    bytes[#bytes + 1] = string.char(math.floor(value / 65536) % 256)
    if cByte ~= 61 then
      bytes[#bytes + 1] = string.char(math.floor(value / 256) % 256)
    end
    if dByte ~= 61 then
      bytes[#bytes + 1] = string.char(value % 256)
    end
  end
  return table.concat(bytes)
end

return function()
  local getAsset = getcustomasset
  if type(getAsset) ~= "function" then
    getAsset = getsynasset
  end
  if type(writefile) ~= "function" or type(getAsset) ~= "function" then
    return
  end

  local path = "katalyst_logo_white.png"
  local ok, logo = pcall(function()
    if type(isfile) ~= "function" or not isfile(path) then
      writefile(path, decode(data))
    end
    return getAsset(path)
  end)
  if ok then
    return logo
  end
end
end)()

