local function buildAutomationMenu(menu)
  local tab = menu.window:AddTab("Automation")
  local farmingPage = tab:AddSubTab("Farming")
  local mobsPage = tab:AddSubTab("Mobs")

  menu:addStateFeature(farmingPage, {
    Name = "Auto Ferryman",
    Side = "Left",
    StateKey = "ferrymanBoss",
    ActionKey = "ferrymanBoss",
    BindingKey = "ferrymanBoss",
  })
  menu:addStateFeature(farmingPage, {
    Name = "Echo Farm",
    Side = "Right",
    StateKey = "echo",
    ActionKey = "ef",
  })
  menu:addStateFeature(farmingPage, {
    Name = "Auto Loot",
    Side = "Left",
    StateKey = "autoLoot",
    ActionKey = "autoLoot",
  })

  local bringMobs = menu:addStateFeature(mobsPage, {
    Name = "Bring Mobs",
    Side = "Left",
    StateKey = "bringMob",
    ActionKey = "bringMob",
    BindingKey = "bringMob",
  })
  menu:addSlider(bringMobs, {
    Name = "Bring Range",
    Flag = "Runtime_BringMobRange",
    Min = 50,
    Max = 500,
    Default = BRING_MOBS.range,
    Increment = 1,
    Save = false,
    Suffix = " studs",
    Sync = function()
      return BRING_MOBS.range
    end,
    Callback = function(value)
      BRING_MOBS.range = value
    end,
  })

  local attachToMob = menu:addStateFeature(mobsPage, {
    Name = "Attach to Mob",
    Side = "Right",
    StateKey = "attachMob",
    ActionKey = "attachMob",
    BindingKey = "attachMob",
  })

  local emptyOption = "None available"
  local chooseMob = "Select a mob"
  local mobByLabel = {}
  local labelByMob = setmetatable({}, { __mode = "k" })
  local nextLabelByName = {}
  local attachMobDropdown

  local function collectMobs()
    local live = G.WS:FindFirstChild("Live") or G.WS
    local candidates = {}

    for index, model in ipairs(live:GetChildren()) do
      if model ~= G.LP.Character
        and model:IsA("Model")
        and model:FindFirstChildOfClass("Humanoid")
        and not G.Plrs:GetPlayerFromCharacter(model)
      then
        candidates[#candidates + 1] = { model = model, index = index }
      end
    end

    table.sort(candidates, function(left, right)
      local leftName = string.lower(left.model.Name)
      local rightName = string.lower(right.model.Name)
      if leftName == rightName then
        return left.index < right.index
      end
      return leftName < rightName
    end)

    local options = #candidates > 0 and { chooseMob } or {}
    table.clear(mobByLabel)
    for _, candidate in ipairs(candidates) do
      local model = candidate.model
      local label = labelByMob[model]
      if not label then
        local nextLabel = (nextLabelByName[model.Name] or 0) + 1
        nextLabelByName[model.Name] = nextLabel
        label = nextLabel == 1 and model.Name or (model.Name .. " #" .. nextLabel)
      end
      while mobByLabel[label] do
        local nextLabel = (nextLabelByName[model.Name] or 1) + 1
        nextLabelByName[model.Name] = nextLabel
        label = model.Name .. " #" .. nextLabel
      end
      labelByMob[model] = label
      options[#options + 1] = label
      mobByLabel[label] = model
    end

    if #candidates == 0 then
      options[1] = emptyOption
    end
    return options
  end

  local function selectedMobLabel()
    local target = ATTACH_MOB.target
    if target then
      for label, model in pairs(mobByLabel) do
        if model == target then
          return label
        end
      end
    end
    return next(mobByLabel) and chooseMob or emptyOption
  end

  local initialOptions = collectMobs()
  attachMobDropdown = menu:addDropdown(attachToMob, {
    Name = "Target Mob",
    SyncKey = "AttachMobTarget",
    Save = false,
    Options = initialOptions,
    Default = selectedMobLabel(),
    Sync = selectedMobLabel,
    Callback = function(label)
      local target = mobByLabel[label]
      if not target then
        return
      end
      ATTACH_MOB.target = target
      if S.attachMob then
        ATTACH_MOB.start(target)
      end
    end,
  })

  local function refreshMobs(removedMob)
    if removedMob and ATTACH_MOB.target == removedMob then
      ATTACH_MOB.stop()
    end
    attachMobDropdown:SetOptions(collectMobs())
    UI.syncValue("AttachMobTarget")
  end

  menu:addButton(attachToMob, {
    Name = "Refresh Mob List",
    Callback = refreshMobs,
  })

  local live = G.WS:FindFirstChild("Live") or G.WS
  menu:trackConnection(live.ChildAdded:Connect(refreshMobs))
  menu:trackConnection(live.ChildRemoved:Connect(function(mob)
    refreshMobs(mob)
  end))
end
