  local mobEsp = menu:addStateFeature(espPage, {
    Name = "Mob ESP",
    Side = "Right",
    StateKey = "mobEsp",
    ActionKey = "mobEsp",
    BindingKey = "mobEsp",
  })

  local filterStatus = mobEsp:AddLabel("Active filter: " .. (CFG.MobEspFilter or "ALL"))
  local mobFilterDropdown
  local collectMobFilters

  local function normalizeMobFilter(value)
    local trimmed = string.match(tostring(value or ""), "^%s*(.-)%s*$") or ""
    if trimmed == "" or string.lower(trimmed) == "all" then
      return "ALL"
    end
    return trimmed
  end

  local function setMobFilter(value)
    CFG.MobEspFilter = normalizeMobFilter(value)
    filterStatus:SetText("Active filter: " .. CFG.MobEspFilter)
    if mobFilterDropdown and collectMobFilters then
      mobFilterDropdown:SetOptions(collectMobFilters())
    end
    UI.syncValue("MobEspFilterText")
    UI.syncValue("MobEspFilterPreset")
  end

  menu:addTextbox(mobEsp, {
    Name = "Filter Mob Name",
    Flag = "CFG_MobEspFilterText",
    SyncKey = "MobEspFilterText",
    Placeholder = "Sharko, Duke, or ALL",
    Default = CFG.MobEspFilter ~= "ALL" and CFG.MobEspFilter or "",
    Sync = function()
      return CFG.MobEspFilter ~= "ALL" and CFG.MobEspFilter or ""
    end,
    Callback = setMobFilter,
    Reconcile = function()
      setMobFilter(CFG.MobEspFilter)
    end,
  })

  local presets = {
    "Sharko", "Megalodaunt", "Corrupted Sharko", "Thresher", "King Thresher",
    "Enforcer", "Ferryman", "Duke Erisia", "Chaser", "Scion of Ethiron",
    "Bounder", "Gryphon", "Lionfish", "Deep Widow", "Mudskipper", "Crab", "Squid",
  }

  collectMobFilters = function()
    local names = {}
    local seen = {}
    local live = G.WS:FindFirstChild("Live") or G.WS
    for _, model in ipairs(live:GetChildren()) do
      if model:IsA("Model")
        and model ~= G.LP.Character
        and not G.Plrs:GetPlayerFromCharacter(model)
      then
        local humanoid = model:FindFirstChildOfClass("Humanoid")
        if humanoid and humanoid.Health > 0 and not seen[model.Name] then
          seen[model.Name] = true
          names[#names + 1] = model.Name
        end
      end
    end
    table.sort(names, function(left, right)
      return string.lower(left) < string.lower(right)
    end)

    local options = { "All mobs" }
    for _, name in ipairs(names) do
      options[#options + 1] = name
    end
    for _, name in ipairs(presets) do
      if not seen[name] then
        seen[name] = true
        options[#options + 1] = name
      end
    end
    local currentFilter = CFG.MobEspFilter or "ALL"
    if currentFilter ~= "ALL" and not seen[currentFilter] then
      options[#options + 1] = currentFilter
    end
    return options
  end

  local function selectedMobFilter()
    return (CFG.MobEspFilter == nil or CFG.MobEspFilter == "ALL") and "All mobs" or CFG.MobEspFilter
  end

  mobFilterDropdown = menu:addDropdown(mobEsp, {
    Name = "Mob Filter Preset",
    SyncKey = "MobEspFilterPreset",
    Options = collectMobFilters(),
    Default = selectedMobFilter(),
    Sync = selectedMobFilter,
    Callback = function(value)
      setMobFilter(value == "All mobs" and "ALL" or value)
    end,
  })

  local function refreshMobFilters()
    mobFilterDropdown:SetOptions(collectMobFilters())
  end

  menu:addButton(mobEsp, {
    Name = "Show All Mobs",
