  local performancePage = tab:AddSubTab("Performance")

  local function addSection(page, name, side, tooltip)
    return page:AddSection({
      Name = name,
      Side = side,
      Tooltip = tooltip,
    })
  end

  local function setLabel(label, text)
    label:SetText(tostring(text or ""))
  end

  local function copyText(text)
    if type(setclipboard) == "function" then
      setclipboard(text)
      return true
    end
    print(text)
    return false
  end

  local rendering = addSection(
    performancePage,
    "Rendering",
    "Left",
    nil
  )
