      return CFG.FpsVal
    end,
    Callback = function(value)
      CFG.FpsVal = value
      if S.fps and type(setfpscap) == "function" then
        setfpscap(value)
      end
    end,
    Reconcile = function()
      if S.fps and type(setfpscap) == "function" then
        setfpscap(CFG.FpsVal)
      end
    end,
  })

  menu:addStateFeature(playerPage, {
    Name = "Fake Void",
    Side = "Left",
    StateKey = "nkb",
    ActionKey = "nkb",
    BindingKey = "nkb",
  })
  menu:addStateFeature(playerPage, {
    Name = "No Kill Bricks",
    Side = "Right",
    StateKey = "noKill",
    ActionKey = "noKill",
    BindingKey = "noKill",
  })
  menu:addStateFeature(playerPage, {
    Name = "Streamer Mode",
    Side = "Left",
    StateKey = "str",
    ActionKey = "st",
    BindingKey = "str",
  })

  local profileScanner = menu:addStateFeature(diagnosticsPage, {
    Name = "E-Girl Profile Scanner",
    Side = "Left",
    StateKey = "egirlDetector",
    ActionKey = "egirlDetector",
    BindingKey = "egirlDetector",
  })
  menu:addButton(profileScanner, {
    Name = "Scan All Server Profiles",
    Callback = function()
      EGIRL_DETECTOR.scanned = {}
      for _, player in ipairs(G.Plrs:GetPlayers()) do
        EGIRL_DETECTOR.scanPlayer(player)
      end
      G.noti("Profile Scanner", "Server profile scan started.", 2)
    end,
  })
  menu:addStateFeature(diagnosticsPage, {
    Name = "Animation ID Logger",
    Side = "Right",
    StateKey = "logAni",
