    BindingKey = "logAni",
  })
  local buffScanner = menu:addStateFeature(diagnosticsPage, {
    Name = "Buff Scanner",
    Side = "Right",
    StateKey = "buffLog",
    ActionKey = "buffLog",
    BindingKey = "buffLog",
  })
  menu:addButton(buffScanner, {
    Name = "Copy Last Buff Scan",
    Callback = function()
      if not BUFF_LOGGER.lastScan or BUFF_LOGGER.lastScan == "" then
        G.noti("Buff Scanner", "Wait for a scan before copying.", 2)
        return
      end
      if copyText(BUFF_LOGGER.lastScan) then
        G.noti("Buff Scanner", "Last scan copied to clipboard.", 2)
      else
        G.noti("Buff Scanner", "Clipboard unavailable; printed to console.", 2)
      end
    end,
  })
  menu:addStateFeature(diagnosticsPage, {
    Name = "Global Chat Spy",
    Side = "Left",
    StateKey = "gChat",
    ActionKey = "gc",
    BindingKey = "gChat",
  })

  local training = menu:addStateFeature(playerPage, {
    Name = "Auto Charisma / Intelligence",
    Side = "Right",
    StateKey = "autoChar",
    ActionKey = "autoChar",
    Tooltip = nil,
  })
  menu:addSlider(training, {
    Name = "Chat Interval",
    Flag = "Runtime_AutoCharismaInterval",
    Min = 2,
    Max = 15,
    Default = AUTO_CHARISMA.interval,
    Increment = 1,
    Save = false,
    Suffix = "s",
    Sync = function()
      return AUTO_CHARISMA.interval
    end,
    Callback = function(value)
      AUTO_CHARISMA.interval = value
    end,
  })

  for index = 1, 3 do
    local macroKey = "m" .. index
    local configKey = "M" .. index
    local macro = addSection(
      toolsPage,
      "Macro " .. index,
      index % 2 == 1 and "Left" or "Right",
      nil
    )
    menu:addBinding(macro, "Macro " .. index .. " Key", macroKey, {
      Header = true,
      Modes = {"Toggle"},
    })
    menu:addTextbox(macro, {
      Name = "Macro " .. index .. " Inputs",
      Flag = "CFG_" .. configKey,
      Placeholder = "e.g. Q, M2",
      Default = CFG[configKey],
      Sync = function()
        return CFG[configKey]
      end,
      Callback = function(value)
        CFG[configKey] = value
      end,
    })
  end

  local function resolvePlayer(query)
    local normalized = string.lower(string.gsub(tostring(query or ""), "%s+", ""))
    if normalized == "" or normalized == "me" or normalized == "self" then
      return G.LP
    end
    if normalized == "nearest" or normalized == "closest" then
      local root = G.myR()
      if not root then return nil end
      local closest
      local closestDistance = math.huge
      for _, player in ipairs(G.Plrs:GetPlayers()) do
        local playerRoot = player ~= G.LP and player.Character and player.Character:FindFirstChild("HumanoidRootPart")
        if playerRoot then
          local distance = (playerRoot.Position - root.Position).Magnitude
          if distance < closestDistance then
            closest = player
            closestDistance = distance
          end
        end
      end
      return closest or G.LP
    end
    for _, player in ipairs(G.Plrs:GetPlayers()) do
      if string.find(string.lower(player.Name), normalized, 1, true)
        or string.find(string.lower(player.DisplayName), normalized, 1, true)
      then
        return player
      end
    end
    return nil
  end

  local inspector = addSection(toolsPage, "Player Inspector", "Full", nil)
  local inspectTarget = inspector:AddTextbox({
    Name = "Target",
    Placeholder = "Player name, me, or nearest",
    Default = "",
  })
  local inspectStatus = inspector:AddLabel("Enter a player name to inspect.")

  local function formatPlayerStats(player)
    if not player then return nil end
    local live = G.WS:FindFirstChild("Live")
    local character = player.Character or (live and live:FindFirstChild(player.Name))
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local lines = { string.format("[%s (@%s)]", player.DisplayName or player.Name, player.Name) }
    if humanoid then
      lines[#lines + 1] = string.format(
        "Health: %.1f/%.1f (%d%%)",
        humanoid.Health,
        humanoid.MaxHealth,
        math.floor((humanoid.Health / math.max(1, humanoid.MaxHealth)) * 100)
      )
    end
    if character then
      lines[#lines + 1] = "Weapon: " .. tostring(character:GetAttribute("EquippedWeapon") or character:GetAttribute("Weapon") or "None")
      local attributes = {}
      for name, value in pairs(character:GetAttributes()) do
        if not tostring(name):find("Color") and not tostring(name):find("Pos") then
          attributes[#attributes + 1] = string.format("%s=%s", tostring(name), tostring(value))
        end
      end
      if #attributes > 0 then
        lines[#lines + 1] = "Attributes: " .. table.concat(attributes, ", ")
      end
    end
    return table.concat(lines, "\n")
  end

  menu:addButton(inspector, {
    Name = "Copy Target Stats",
    Callback = function()
      local player = resolvePlayer(inspectTarget:GetValue())
      if not player then
        setLabel(inspectStatus, "Player not found in this server.")
        return
      end
      local text = formatPlayerStats(player)
      setLabel(inspectStatus, text:sub(1, 350) .. (#text > 350 and "..." or ""))
      copyText(text)
      G.noti("Stats Copied", "Target stats copied or printed.", 2)
    end,
  })
  menu:addButton(inspector, {
    Name = "Copy All Server Players",
    Callback = function()
      local dumps = {}
      for _, player in ipairs(G.Plrs:GetPlayers()) do
        local text = formatPlayerStats(player)
        if text then dumps[#dumps + 1] = text end
      end
      copyText(table.concat(dumps, "\n\n"))
      setLabel(inspectStatus, string.format("Dumped %d players.", #dumps))
      G.noti("Server Dump", "All server player stats copied or printed.", 3)
    end,
  })

  local buildStealer = addSection(toolsPage, "Build Stealer", "Full", nil)
  local buildTarget = buildStealer:AddTextbox({
    Name = "Target",
    Placeholder = "Player name, me, or nearest",
    Default = "",
  })
  local buildStatus = buildStealer:AddLabel("Enter a player name to inspect their build.")

  local function readBuild(player)
    if not player then return nil, "No player specified" end
    local live = G.WS:FindFirstChild("Live")
    local character = player.Character or (live and live:FindFirstChild(player.Name)) or G.WS:FindFirstChild(player.Name)
    if not character then return nil, "Character does not exist in workspace" end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local backpack = player:FindFirstChild("Backpack")
    local passives = character:GetAttribute("Passives")
      or (player:FindFirstChild("Data") and player.Data:GetAttribute("Passives"))
      or ""

    local data = {
      version = 3,
      stats = {
        buildName = string.format("(%i) (%s) Stolen Build", os.time(), player.Name),
        buildDescription = "Build stolen using Katalyst Build Stealer.",
        buildAuthor = "Katalyst",
        power = character:GetAttribute("Level") or 20,
        pointsUntilNextPower = 67,
        points = 67,
        pointSpent = 67,
        traitPoints = 0,
        traits = {
          Vitality = character:GetAttribute("Trait_Health") or 0,
          Erudition = character:GetAttribute("Trait_Ether") or 0,
          Songchant = character:GetAttribute("Trait_MantraDamage") or 0,
          Proficiency = character:GetAttribute("Trait_WeaponDamage") or 0,
        },
        meta = {
          Race = "None",
          Oath = "None",
          Murmur = "None",
          Bell = "None",
          Origin = "Castaway",
          Outfit = "None",
        },
      },
      attributes = {
        weapon = {
          ["Heavy Wep."] = character:GetAttribute("Stat_WeaponHeavy") or character:GetAttribute("Heavy Weapon") or 0,
          ["Medium Wep."] = character:GetAttribute("Stat_WeaponMedium") or character:GetAttribute("Medium Weapon") or 0,
          ["Light Wep."] = character:GetAttribute("Stat_WeaponLight") or character:GetAttribute("Light Weapon") or 0,
        },
        base = {
          Strength = character:GetAttribute("Stat_Strength") or character:GetAttribute("Strength") or 0,
          Fortitude = character:GetAttribute("Stat_Fortitude") or character:GetAttribute("Fortitude") or 0,
          Agility = character:GetAttribute("Stat_Agility") or character:GetAttribute("Agility") or 0,
          Intelligence = character:GetAttribute("Stat_Intelligence") or character:GetAttribute("Intelligence") or 0,
          Willpower = character:GetAttribute("Stat_Willpower") or character:GetAttribute("Willpower") or 0,
          Charisma = character:GetAttribute("Stat_Charisma") or character:GetAttribute("Charisma") or 0,
        },
        attunement = {
          Flamecharm = character:GetAttribute("Stat_ElementFire") or character:GetAttribute("Flamecharm") or 0,
          Frostdraw = character:GetAttribute("Stat_ElementIce") or character:GetAttribute("Frostdraw") or 0,
          Thundercall = character:GetAttribute("Stat_ElementLightning") or character:GetAttribute("Thundercall") or 0,
          Galebreathe = character:GetAttribute("Stat_ElementWind") or character:GetAttribute("Galebreathe") or 0,
          Shadowcast = character:GetAttribute("Stat_ElementShadow") or character:GetAttribute("Shadowcast") or 0,
          Ironsing = character:GetAttribute("Stat_ElementMetal") or character:GetAttribute("Iron-Sing") or 0,
          Bloodrend = character:GetAttribute("Stat_ElementBlood") or character:GetAttribute("Blood") or 0,
        },
      },
      content = { mantraModifications = {}, notes = "" },
      meta = { tags = {}, isPrivate = true },
      talents = {},
      mantras = {},
      weapons = character:GetAttribute("EquippedWeapon") or character:GetAttribute("Weapon") or "",
      enchant = "",
      motif = "",
      preShrine = {
        base = { Strength = 100, Fortitude = 100, Agility = 100, Intelligence = 100, Willpower = 100, Charisma = 100 },
        weapon = { ["Heavy Wep."] = 100, ["Medium Wep."] = 100, ["Light Wep."] = 100 },
        attunement = { Flamecharm = 100, Frostdraw = 100, Thundercall = 100, Galebreathe = 100, Shadowcast = 100, Ironsing = 100, Bloodrend = 100 },
      },
      postShrine = nil,
      favoritedTalents = {},
    }
    data.postShrine = data.attributes

    local notes = {}
    if humanoid then
      notes[#notes + 1] = string.format("[HEALTH] %.2f / %.2f", humanoid.Health, humanoid.MaxHealth)
    end
    if backpack then
      for _, child in ipairs(backpack:GetChildren()) do
        if string.match(child.Name, "Resonance:") then
          data.stats.meta.Bell = string.gsub(child.Name, "Resonance:", "")
        end
        if string.match(child.Name, "Mantra") and child:GetAttribute("DisplayName") then
          local tag = string.match(child.Name, "RecalledMantra") and "[RECALLED MANTRA]" or "[USED MANTRA]"
          notes[#notes + 1] = tag .. " " .. (child:GetAttribute("RichStats") or child:GetAttribute("DisplayName") or "")
          if not string.match(child.Name, "RecalledMantra") then
            local displayName = child:GetAttribute("DisplayName")
            data.mantras[#data.mantras + 1] = displayName
            data.content.mantraModifications[displayName] = {}
          end
        end
        if child.Name == "Weapon" then
          notes[#notes + 1] = "[USED WEAPON] " .. tostring(child:GetAttribute("RichStats") or child.Name)
        end
      end
    end

    for _, passive in ipairs(string.split(tostring(passives), ";")) do
      if string.match(passive, "Murmur:") then
        data.stats.meta.Murmur = string.gsub(passive, "Murmur:%s*", "")
      elseif string.match(passive, "Oath:") then
        data.stats.meta.Oath = string.gsub(passive, "Oath:%s*", "")
      elseif #passive > 0 then
        data.talents[#data.talents + 1] = passive
      end
    end

    for _, instance in ipairs(character:GetChildren()) do
      if instance.Name == "Ring" then
        local ringName = instance:GetAttribute("DisplayName") or instance:GetAttribute("EquipmentRef") or instance.Name
        notes[#notes + 1] = string.format("[RING] %s: %s", tostring(ringName), tostring(instance:GetAttribute("RichStats") or ""))
      elseif string.match(instance.Name, "Equipment") and instance:GetAttribute("DisplayName") then
        notes[#notes + 1] = string.format(
          "[%s] %s %s",
          instance.Name,
          tostring(instance:GetAttribute("DisplayName")),
          tostring(instance:GetAttribute("RichStats") or "")
        )
      end
    end
    data.content.notes = table.concat(notes, "\n")
    return data
  end

  local function fallbackBuildLink(data, player)
    return string.format(
      "https://deepwoken.co/builder?str=%d&ftd=%d&agi=%d&int=%d&wlp=%d&chr=%d&med=%d&hvy=%d&lgt=%d&user=%s",
      data.attributes.base.Strength or 0,
      data.attributes.base.Fortitude or 0,
      data.attributes.base.Agility or 0,
      data.attributes.base.Intelligence or 0,
      data.attributes.base.Willpower or 0,
      data.attributes.base.Charisma or 0,
      data.attributes.weapon["Medium Wep."] or 0,
      data.attributes.weapon["Heavy Wep."] or 0,
      data.attributes.weapon["Light Wep."] or 0,
      tostring(player.UserId)
    )
  end

  local function currentBuild()
    local player = resolvePlayer(buildTarget:GetValue())
    if not player then
      setLabel(buildStatus, "Player not found in this server.")
      return nil
    end
    local data, err = readBuild(player)
    if not data then
      setLabel(buildStatus, "Failed to read build: " .. tostring(err))
      return nil
    end
    return player, data
  end

  menu:addButton(buildStealer, {
    Name = "Create Deepwoken.co Link",
    Callback = function()
      local player, data = currentBuild()
      if not player then return end
      local payload = G.HS:JSONEncode(data)
      local requestFunction = (type(request) == "function" and request)
        or (type(http_request) == "function" and http_request)
        or (type(syn) == "table" and type(syn.request) == "function" and syn.request)
        or (type(http) == "table" and type(http.request) == "function" and http.request)
        or (type(fluxus) == "table" and type(fluxus.request) == "function" and fluxus.request)
        or G.httpReq

      local function useFallback()
        local link = fallbackBuildLink(data, player)
        copyText(link)
        setLabel(buildStatus, string.format("COPIED BUILD URL:\n%s\n\nNotes:\n%s", link, tostring(data.content.notes)))
        G.noti("Build Stealer", "Copied builder link for " .. player.DisplayName .. "!", 3)
      end

      if not requestFunction then
        useFallback()
        return
      end

      setLabel(buildStatus, "Creating build link...")
      task.spawn(function()
        local ok, response = pcall(requestFunction, {
          Url = "https://deepwoken.co/api/proxy/builds/",
          Method = "POST",
          Headers = {
            ["Content-Type"] = "application/json",
            ["Accept"] = "application/json",
            ["Origin"] = "https://deepwoken.co",
            ["Referer"] = "https://deepwoken.co/builder",
            ["Sec-Fetch-Site"] = "same-origin",
            ["Sec-Fetch-Mode"] = "cors",
            ["Sec-Fetch-Dest"] = "empty",
          },
          Body = payload,
        })
        if ok and response and (response.Success or response.StatusCode == 200 or response.StatusCode == 201) and response.Body then
          local decodedOk, decoded = pcall(function()
            return G.HS:JSONDecode(response.Body)
          end)
          if decodedOk and decoded and decoded.id then
            local link = string.format("https://deepwoken.co/builder?id=%s", tostring(decoded.id))
            copyText(link)
            setLabel(buildStatus, string.format("COPIED BUILD LINK:\n%s\n\nNotes:\n%s", link, tostring(data.content.notes)))
            G.noti("Build Stealer", "Stole build from " .. player.DisplayName .. " and copied deepwoken.co link!", 4)
            return
          end
        end
        useFallback()
      end)
    end,
  })
