  local function refreshOverridePlayers(excludedPlayer)
    if selectedPlayer == excludedPlayer then selectedPlayer = nil end
    overrideDropdown:SetOptions(collectPlayers(excludedPlayer))
  end

  menu:addButton(overrides, {
    Name = "Refresh Player List",
    Callback = refreshOverridePlayers,
