  end))
end
local function buildMinigamesMenu(menu)
  local tab = menu.window:AddTab("Minigames")
  local trainingPage = tab:AddSubTab("Vault & Trainer")
  local roulettePage = tab:AddSubTab("Roulette")
  local casinoPage = tab:AddSubTab("Slots & Coin")

  local function isOpen(control)
    return not UI.tearingDown and control.Frame and control.Frame.Parent ~= nil
  end

  if CFG.KataCoins == nil then CFG.KataCoins = 1000 end
  if CFG.LastKataClaim == nil then CFG.LastKataClaim = 0 end

  local balanceListeners = {}

  local function onBalanceChanged(callback)
    balanceListeners[#balanceListeners + 1] = callback
  end

  local function setBalance(amount)
    CFG.KataCoins = math.max(0, math.floor(tonumber(amount) or 0))
    pcall(menu.save, menu)
    for _, callback in ipairs(balanceListeners) do
      pcall(callback, CFG.KataCoins)
    end
  end

  local function addCoins(amount)
    setBalance((CFG.KataCoins or 0) + amount)
  end

  local function spendCoins(amount)
    local balance = CFG.KataCoins or 0
    if balance < amount then
      return false
    end
    setBalance(balance - amount)
    return true
  end

  local endpoints = {
    "http://127.0.0.1:3000/leaderboard",
    "http://localhost:3000/leaderboard",
    "https://my-katalyst-sniper.loca.lt/leaderboard",
  }

  local function postCloudBalance()
    local httpRequest = G.httpReq
    local player = G.LP or (game.Players and game.Players.LocalPlayer)
    local username = (player and player.Name) or "Player"
    local displayName = (player and player.DisplayName) or username
    local userId = (player and player.UserId) or 0
    local coins = tonumber(CFG.KataCoins) or 1000
    local payload = G.HS:JSONEncode({
      userId = tostring(userId),
      username = tostring(username),
      displayName = tostring(displayName),
      coins = coins,
      balance = coins,
      bestReactionMs = tonumber(CFG.BestReactionMs) or 0,
      score = coins,
    })

    task.spawn(function()
      if not httpRequest then
        return
      end
      for _, url in ipairs(endpoints) do
        pcall(function()
          httpRequest({
            Url = url,
            Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = payload,
          })
        end)
      end
    end)
  end

