  local trainer = trainingPage:AddSection({
    Name = "Reflex & Parry Trainer",
    Side = "Right",
    Tooltip = nil,
  })
  local trainerStatus = trainer:AddLabel("Press Start Test to begin.")
  trainer:AddLabel("Under 160ms: +100 KC | under 200ms: +50 KC | under 250ms: +25 KC")
  local trainerScore = trainer:AddLabel("Best: -- ms | Attempts: 0")
  local trainerState = {
    active = false,
    waiting = false,
    flashTime = 0,
    bestScore = 999,
    attempts = 0,
  }

  local function handleReaction()
    if not trainerState.active then
      return
    end
    if trainerState.waiting then
      trainerState.active = false
      trainerState.waiting = false
      trainerStatus:SetText("TOO EARLY! (No Reward)")
      return
    end
    if trainerState.flashTime <= 0 then
      return
    end

    local reactionMs = math.floor((os.clock() - trainerState.flashTime) * 1000)
    trainerState.active = false
    trainerState.flashTime = 0
    trainerState.attempts = trainerState.attempts + 1
    trainerState.bestScore = math.min(trainerState.bestScore, reactionMs)

    local rating = "SLOW / VULNERABLE (+0 KC)"
    local earned = 0
    if reactionMs < 160 then
      rating = "GODLIKE REFLEXES (+100 KC)"
      earned = 100
    elseif reactionMs < 200 then
      rating = "EXCELLENT PARRY (+50 KC)"
      earned = 50
    elseif reactionMs < 250 then
      rating = "GOOD TIMING (+25 KC)"
      earned = 25
    end
    if earned > 0 then
      addCoins(earned)
    end

    trainerStatus:SetText(string.format("%d ms - %s", reactionMs, rating))
    trainerScore:SetText(string.format("Best: %d ms | Attempts: %d", trainerState.bestScore, trainerState.attempts))
  end

