      task.delay(math.random(15, 45) / 10, function()
        if trainerState.active and trainerState.waiting and isOpen(trainerStatus) then
          trainerState.waiting = false
          trainerState.flashTime = os.clock()
          trainerStatus:SetText("PARRY NOW!")
        end
      end)
