        local won = (selectedRouletteType == "RED" and isRed)
          or (selectedRouletteType == "BLACK" and isBlack)
          or (selectedRouletteType == "GREEN" and isGreen)
          or (selectedRouletteType == "EVEN" and isEven)
          or (selectedRouletteType == "ODD" and isOdd)

