local function copyInfo(info)
  local copy = {}
  for key, value in pairs(info) do
    if key ~= "Sync" and key ~= "SyncKey" and key ~= "Reconcile" and key ~= "Save" then
      copy[key] = value
    end
  end
  return copy
end

local function syncKey(info)
  if info.SyncKey then return info.SyncKey end
  if type(info.Flag) == "string" and string.sub(info.Flag, 1, 4) == "CFG_" then
    return string.sub(info.Flag, 5)
  end
  return info.Flag
end

local function accentColor()
  local stored = CFG.KatalystUIAccent
  if type(stored) ~= "table" then stored = DEFAULT_ACCENT end
  local red = tonumber(stored.r or stored[1]) or DEFAULT_ACCENT.r
  local green = tonumber(stored.g or stored[2]) or DEFAULT_ACCENT.g
  local blue = tonumber(stored.b or stored[3]) or DEFAULT_ACCENT.b
  return G.RGB(G.mc(G.mr(red), 0, 255), G.mc(G.mr(green), 0, 255), G.mc(G.mr(blue), 0, 255))
end

local function applyAccent(color)
  color = typeof(color) == "Color3" and color or accentColor()
  CFG.KatalystUIAccent = {
    r = G.mr(color.R * 255),
    g = G.mr(color.G * 255),
    b = G.mr(color.B * 255),
  }
  P.acc = color
  P.accB = color:Lerp(G.C3(1, 1, 1), 0.18)
  P.accD = color:Lerp(G.C3(0, 0, 0), 0.25)
  P.on = color
  UC.acGr = G.CS({G.CSK(0, P.accB), G.CSK(1, P.accD)})
  local ok, message = KatalystUI:SetAccent(color)
  if not ok then
    G.noti("Interface", message or "Could not update the accent color.", 3)
  end
end

local function createCoordinator(window)
  UI.lifecycleActions = {}
  UI.lifecycleOrder = {}
  local menu = {
    window = window,
    reconcilers = {},
    nextControlId = 0,
  }

  function menu:nextFlag(prefix)
    self.nextControlId = self.nextControlId + 1
    return prefix .. tostring(self.nextControlId)
  end

  function menu:save()
    if not UI.syncing and not UI.importing and not UI.suspendSave then
      G.saveConfig()
    end
  end

  function menu:runAndSave(callback, shouldSave)
    local wasSuspended = UI.suspendSave
    UI.suspendSave = true
    local ok, err = pcall(callback)
    UI.suspendSave = wasSuspended
    if not ok then
      warn("[Katalyst] Menu callback failed: " .. tostring(err))
      return false
    end
    if shouldSave ~= false then self:save() end
    return true
  end

  function menu:trackConnection(connection)
    return trk(connection)
  end

  function menu:trackState(stateKey, control)
    UI.registerState(stateKey, control)
    return control
  end

  function menu:trackValue(name, control, read)
    UI.registerValue(name, control, read)
    return control
  end

  function menu:trackReconciler(callback)
    self.reconcilers[#self.reconcilers + 1] = callback
  end

  function menu:reconcileConfig()
    for _, callback in ipairs(self.reconcilers) do
      local ok, err = pcall(callback)
      if not ok then
        warn("[Katalyst] Could not apply imported setting: " .. tostring(err))
      end
    end
  end

  local function bindingControlInfo(self, name, bindingKey, options)
    options = options or {}
    CFG.KeybindModes = type(CFG.KeybindModes) == "table" and CFG.KeybindModes or {}
    local modes = options.Modes or {"Toggle"}
    local allowedModes = {}
    for _, allowedMode in ipairs(modes) do allowedModes[allowedMode] = true end
    local function readMode()
      local mode = CFG.KeybindModes[bindingKey]
      if not allowedModes[mode] then mode = modes[1] end
      CFG.KeybindModes[bindingKey] = mode
      return mode
    end
    local mode = readMode()
    local rawKey = kb[bindingKey]
    local defaultKey = (typeof(rawKey) == "EnumItem" and rawKey.EnumType == Enum.KeyCode) and rawKey or nil
    return {
      Name = name,
      Flag = "Binding_" .. bindingKey,
      Default = defaultKey,
      Mode = mode,
      Modes = modes,
      AllowUnbound = bindingKey ~= "menuKey",
      Passive = true,
      ChangedCallback = function(key, nextMode)
        if UI.syncing then return end
        local storedKey = key or false
        nextMode = allowedModes[nextMode] and nextMode or modes[1]
        if kb[bindingKey] == storedKey and CFG.KeybindModes[bindingKey] == nextMode then return end
        kb[bindingKey] = storedKey
        CFG.KeybindModes[bindingKey] = nextMode
        if bindingKey == "apNuker" then kb.apBreaker = nil end
        if bindingKey == "menuKey" then
          CFG.MenuKey = key
        end
        self:save()
        if KEYBINDS_HUD and KEYBINDS_HUD.gui then
          pcall(KEYBINDS_HUD.update)
        end
      end,
    }, readMode
  end

  local function trackBinding(self, bindingKey, control, readMode)
    return self:trackValue(bindingKey, control, function()
      return {Key = kb[bindingKey] or nil, Mode = readMode()}
    end)
  end

  function menu:addBinding(section, name, bindingKey, options)
    options = options or {}
    local controlInfo, readMode = bindingControlInfo(self, name, bindingKey, options)
    local method = options.Header and "AddHeaderKeybind" or "AddKeybind"
    local control = section[method](section, controlInfo)
    return trackBinding(self, bindingKey, control, readMode)
  end

  local function stateControlInfo(self, name, stateKey, actionKey)
    return {
      Name = name,
      Flag = "State_" .. stateKey,
      Default = S[stateKey] == true,
      Callback = function(desired)
        if UI.syncing or S[stateKey] == desired then return end
        self:runAndSave(function()
          local action = actionKey and FLIP[actionKey]
          if action then
            action()
          else
            S[stateKey] = desired
          end
          UI.syncState(stateKey)
        end)
      end,
    }
  end

  local function trackStateControl(self, stateKey, actionKey, control)
    self:trackState(stateKey, control)
    if actionKey and IMPORT_LIFECYCLE_STATES[stateKey] and not UI.lifecycleActions[stateKey] then
      UI.lifecycleActions[stateKey] = actionKey
      UI.lifecycleOrder[#UI.lifecycleOrder + 1] = stateKey
    end
    return control
  end

  local function addStateControl(self, section, method, name, stateKey, actionKey)
    local control = section[method](section, stateControlInfo(self, name, stateKey, actionKey))
    return trackStateControl(self, stateKey, actionKey, control)
  end

  function menu:addStateToggle(section, name, stateKey, actionKey)
    return addStateControl(self, section, "AddToggle", name, stateKey, actionKey)
  end

  function menu:addBoundStateToggle(section, name, stateKey, actionKey, bindingKey, options)
    local bindingInfo, readMode = bindingControlInfo(self, name .. " Key", bindingKey, options or {})
    local toggle, binding = section:AddBoundToggle(
      stateControlInfo(self, name, stateKey, actionKey),
      bindingInfo
    )
    trackStateControl(self, stateKey, actionKey, toggle)
    trackBinding(self, bindingKey, binding, readMode)
    return toggle, binding
  end

  function menu:addStateFeature(page, info)
    local section = page:AddSection({
      Name = info.Name,
      Side = info.Side or "Left",
      Tooltip = info.Tooltip,
    })
    addStateControl(self, section, "AddHeaderToggle", info.Name, info.StateKey, info.ActionKey)
    if info.BindingKey then
      self:addBinding(section, info.Name .. " Key", info.BindingKey, {
        Header = true,
        Modes = info.Modes or {"Toggle", "Hold"},
      })
    end
    return section
  end

  function menu:addConfigToggle(section, name, configKey, changed)
    local control = section:AddToggle({
      Name = name,
      Flag = "CFG_" .. configKey,
      Default = CFG[configKey] == true,
      Callback = function(desired)
        if UI.syncing or CFG[configKey] == desired then return end
        self:runAndSave(function()
          CFG[configKey] = desired
          if changed then changed(desired) end
        end)
      end,
    })
    return self:trackValue(configKey, control, function() return CFG[configKey] == true end)
  end

  local function addValueControl(self, section, method, info)
    local options = copyInfo(info)
    local read = info.Sync
    local name = syncKey(info) or self:nextFlag("MenuValue_")
    options.Flag = options.Flag or self:nextFlag("MenuControl_")
    local changed = options.Callback
    options.Callback = function(value)
      if UI.syncing then return end
      if read then
        local ok, current = pcall(read)
        if ok and current == value then return end
      end
      self:runAndSave(function()
        if changed then changed(value) end
      end, info.Save)
      if read then UI.syncValue(name) end
    end
    local control = section[method](section, options)
    if read then self:trackValue(name, control, read) end
    if info.Reconcile then self:trackReconciler(info.Reconcile) end
    return control
  end

  function menu:addSlider(section, info)
    return addValueControl(self, section, "AddSlider", info)
  end

  function menu:addDropdown(section, info)
    local control = addValueControl(self, section, "AddDropdown", info)
    local setOptions = control.SetOptions
    function control:SetOptions(options)
      local wasSyncing = UI.syncing
      UI.syncing = true
      local ok, message = setOptions(self, options)
      UI.syncing = wasSyncing
      return ok, message
    end
    return control
  end

  function menu:addTextbox(section, info)
    return addValueControl(self, section, "AddTextbox", info)
  end

  function menu:addColorPicker(section, info)
    return addValueControl(self, section, "AddColorPicker", info)
  end

  function menu:addButton(section, info)
    return section:AddButton(info)
  end

  function menu:playerOptions(options)
    options = options or {}
    local noPlayers = "None available"
    local choosePlayer = "Select a player"
    local playerByLabel = {}
    local includeLocal = options.IncludeLocal == true

    local function playerLabel(player)
      if options.Label then return options.Label(player) end
      return (player.DisplayName or player.Name) .. " (@" .. player.Name .. ")"
    end

    local function collect(excludedPlayer)
      local players = {}
      for _, player in ipairs(G.Plrs:GetPlayers()) do
        if (includeLocal or player ~= G.LP) and player ~= excludedPlayer then
          players[#players + 1] = player
        end
      end
      table.sort(players, function(left, right)
        return string.lower(left.Name) < string.lower(right.Name)
      end)

      table.clear(playerByLabel)
      if #players == 0 then return {noPlayers} end

      local options = {choosePlayer}
      for _, player in ipairs(players) do
        local label = playerLabel(player)
        options[#options + 1] = label
        playerByLabel[label] = player
      end
      return options
    end

    local function resolve(label)
      return playerByLabel[label]
    end

    local function selected(target)
      if target then
        local label = playerLabel(target)
        if playerByLabel[label] == target then return label end
      end
      return next(playerByLabel) and choosePlayer or noPlayers
    end

    return collect, resolve, selected
  end

  return menu
end

local function buildSettingsMenu(menu)
  local tab = menu.window:AddTab("Settings")
  local interfacePage = tab:AddSubTab("Interface")
  local configPage = tab:AddSubTab("Config")
  local sessionPage = tab:AddSubTab("Session")

  local appearance = interfacePage:AddSection({Name = "Appearance", Side = "Left"})
  local accentSaveVersion = 0
  menu:addColorPicker(appearance, {
    Name = "Accent Color",
    Flag = "CFG_KatalystUIAccent",
    Default = accentColor(),
    Sync = accentColor,
    Save = false,
    Callback = function(color)
      applyAccent(color)
      accentSaveVersion = accentSaveVersion + 1
      local version = accentSaveVersion
      task.delay(0.25, function()
        if accentSaveVersion == version then menu:save() end
      end)
    end,
    Reconcile = function() applyAccent(accentColor()) end,
  })
  menu:addSlider(appearance, {
    Name = "Interface Scale",
    Flag = "CFG_KatalystUIScale",
    Min = 0.75,
    Max = 1.25,
    Default = CFG.KatalystUIScale or 1,
    Increment = 0.05,
    Suffix = "x",
    Sync = function() return CFG.KatalystUIScale or 1 end,
    Callback = function(value)
      CFG.KatalystUIScale = value
      KatalystUI:SetScale(value)
    end,
    Reconcile = function() KatalystUI:SetScale(CFG.KatalystUIScale or 1) end,
  })

  local input = interfacePage:AddSection({Name = "Input", Side = "Right"})
  menu:addBinding(input, "Menu Key", "menuKey")

  local transfer = configPage:AddSection({Name = "Import / Export", Side = "Full"})
  local importText = ""
  transfer:AddTextbox({
    Name = "Configuration",
    Flag = "Session_ConfigTransfer",
    Placeholder = "Paste KATALYST_CFG_ data or JSON",
    Default = "",
    Callback = function(value) importText = value end,
  })
  transfer:AddButton({
    Name = "Export to Clipboard",
    Callback = function()
      local exported = G.exportConfig()
      if type(setclipboard) == "function" then
        setclipboard(exported)
        G.noti("Configuration", "Copied the current configuration.", 3)
      else
        print(exported)
        G.noti("Configuration", "Clipboard unavailable; printed the configuration to console.", 4)
      end
    end,
  })
  transfer:AddButton({
    Name = "Import Configuration",
    Callback = function()
      local ok, message = G.importConfig(importText)
      G.noti("Configuration", ok and "Imported successfully." or tostring(message), 4)
    end,
  })
  transfer:AddButton({
    Name = "Save Now",
    Callback = function()
      G.saveConfig()
      G.saveTimings()
      G.noti("Configuration", "Saved.", 3)
    end,
  })

  local session = sessionPage:AddSection({Name = "Current Session", Side = "Full"})
  local serverName = "Unknown"
  pcall(function() serverName = SNIPE.getSrvN() end)
  session:AddLabel("User: " .. tostring(G.LP and G.LP.Name or "Unknown"))
  session:AddLabel("Server: " .. tostring(serverName))
  local unloadConfirmUntil = 0
  session:AddButton({
    Name = "Unload Katalyst",
    Callback = function()
      local now = os.clock()
      if now > unloadConfirmUntil then
        unloadConfirmUntil = now + 5
        G.noti("Unload Katalyst", "Click Unload Katalyst again within 5 seconds to confirm.", 5)
        return
      end
      unloadConfirmUntil = 0
      task.defer(unloadKatalyst)
    end,
  })
end

local function createMenu()
  pcall(G.loadConfig)
  pcall(G.loadTimings)
  if UI.clearControls then UI.clearControls() end
  UI.tearingDown = false
  UI.library = KatalystUI

  if applyAccent and accentColor then
    pcall(function() applyAccent(accentColor()) end)
  end

  local logo = nil
  if loadLogo then
    pcall(function() logo = loadLogo() end)
  end

  local window = KatalystUI:CreateWindow({
    Title = "KATALYST",
    Size = UDim2.fromOffset(736, 500),
    FooterText = "https://discord.gg/CcsVgwYtRb",
    FooterStatus = "Made by Adam & Juno",
    Logo = logo and {
      Image = logo,
      Color = G.C3(1, 1, 1),
      Position = UDim2.fromOffset(32, 14),
      Size = UDim2.fromOffset(88, 30),
    } or nil,
  })

  if KatalystUI._root then
    pcall(function() KatalystUI._root:SetAttribute("KI", true) end)
  end
  if KatalystUI.SetScale then
    pcall(function() KatalystUI:SetScale(CFG.KatalystUIScale or 1) end)
  end

  local menu = createCoordinator(window)
  UI.reconcileConfig = function()
    if menu and menu.reconcileConfig then
      pcall(function() menu:reconcileConfig() end)
    end
  end

  local function safeBuild(name, fn)
    local ok, err = pcall(fn, menu)
    if not ok then
      warn("[Katalyst] Error building " .. name .. ": " .. tostring(err))
    end
  end

  safeBuild("Combat", buildCombatMenu)
  safeBuild("Automation", buildAutomationMenu)
  safeBuild("Visuals", buildVisualsMenu)
  safeBuild("Movement", buildMovementMenu)
  safeBuild("Utility", buildUtilityMenu)
  safeBuild("Minigames", buildMinigamesMenu)
  safeBuild("Settings", buildSettingsMenu)

  local wasSuspended = UI.suspendSave
  UI.suspendSave = true
  pcall(UI.restoreConfiguredFeatures)
  if menu and menu.reconcileConfig then
    pcall(function() menu:reconcileConfig() end)
  end
  UI.hydrating = false
  UI.suspendSave = wasSuspended

  if UI.bindInp then pcall(UI.bindInp) end
  if UI.syncAll then pcall(UI.syncAll) end
  if UI.applyV then pcall(UI.applyV) end

  if KatalystUI._tabs and KatalystUI._tabs[1] then
    pcall(function() KatalystUI:_selectTab(KatalystUI._tabs[1]) end)
  end
end
return createMenu
end)()
local function runStartup()
  if isDeepwoken and G.BanRemoteHook and type(G.BanRemoteHook.init) == "function" then
    pcall(G.BanRemoteHook.init)
  end

  if HOPPER and type(HOPPER.checkAndHop) == "function" then
    pcall(HOPPER.checkAndHop)
  end

  local menuOk, menuErr = pcall(createMenu)
  if not menuOk then
    warn("[Katalyst] Failed to initialize UI: " .. tostring(menuErr))
    pcall(unloadKatalyst)
    return
  end

  if PC and type(PC.init) == "function" then
    pcall(PC.init)
  end

  shared.KatalystLoaded = true
  pcall(function()
    G.noti("Katalyst", "Full Release by adamXIV  Press P")
  end)
  print("[Katalyst] Full Release by adamXIV  press P")
end

runStartup()
